/****** Object:  View dbo.ACTIVE_TABLE_VARIABLES    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW ACTIVE_TABLE_VARIABLES AS
	SELECT TOP 100 PERCENT
		Logical_Name	= S_Idx.Name,
		Table_Name		= S_Obj.Name,
		ID				= S_Obj.ID
	FROM 
				TempDB..Sysobjects		S_Obj	WITH (NOLOCK)	
		JOIN	TempDB..SysIndexes		S_Idx	WITH (NOLOCK)	ON S_Idx.ID		= S_Obj.ID --
	WHERE
		S_Obj.xtype				= 'U'		AND 
		S_Obj.base_schema_ver	= 0
	GROUP BY
		S_Idx.Name,
		S_Obj.Name,
		S_Obj.ID
/*	ORDER BY
		S_Idx.Name*/


GO

SET QUOTED_IDENTIFIER OFF 
GO
SET ANSI_NULLS ON 
GO

SET QUOTED_IDENTIFIER ON 
GO
SET ANSI_NULLS ON 
GO

/****** Object:  View dbo.DBObjects    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW DBObjects AS
	SELECT TOP 100 PERCENT
		Type	= CASE T.Table_Type WHEN 'BASE TABLE' THEN 'Table' WHEN 'VIEW' THEN 'View' ELSE T.Table_Type END,
		Name	= T.Table_Name,
		Fields	= COUNT(C.Column_Name),
		IsTable	= CONVERT(BIT, CASE T.Table_Type WHEN 'BASE TABLE' THEN 1 ELSE 0 END),
		IsView	= CONVERT(BIT, CASE T.Table_Type WHEN 'VIEW' THEN 1 ELSE 0 END),
		IsProc	= CONVERT(BIT, 0),
		IsUDF	= CONVERT(BIT, 0)
	FROM 
				Information_Schema.Tables	T	WITH (NOLOCK) 
		JOIN	Information_Schema.Columns	C	WITH (NOLOCK) ON C.Table_Name	= T.Table_Name
	GROUP BY
		T.Table_Type,
		T.Table_Name

	UNION ALL

	SELECT TOP 100 PERCENT
		Type	= CASE R.Routine_Type WHEN 'FUNCTION' THEN 'UDF' WHEN 'PROCEDURE' THEN 'SP' ELSE R.Routine_Name END,
		Name	= R.Routine_Name,
		Fields	= NULL,
		IsTable	= CONVERT(BIT, 0),
		IsView	= CONVERT(BIT, 0),
		IsProc	= CONVERT(BIT, CASE R.Routine_Type WHEN 'PROCEDURE' THEN 1 ELSE 0 END),
		IsUDF	= CONVERT(BIT, CASE R.Routine_Type WHEN 'FUNCTION'	THEN 1 ELSE 0 END)
	FROM
			Information_Schema.Routines		R	WITH (NOLOCK)
	ORDER BY
		IsTable		DESC,
		IsView		DESC,
		IsProc		DESC,
		IsUDF		DESC,
		Name


GO

SET QUOTED_IDENTIFIER OFF 
GO
SET ANSI_NULLS ON 
GO

SET QUOTED_IDENTIFIER ON 
GO
SET ANSI_NULLS ON 
GO

/****** Object:  View dbo.SCHEMA_UDF_LIST    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW SCHEMA_UDF_LIST AS
	SELECT DISTINCT TOP 100 PERCENT FUNCTION_NAME = name, DATE_CREATED = crdate FROM sysObjects WITH (NOLOCK) WHERE (type='FN' or xtype='FN') ORDER BY name




