/****** Object:  View dbo.SYSTEM_DB_OBJECTS    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW SYSTEM_DB_OBJECTS AS
	SELECT TOP 100 PERCENT
		Type		= CASE SO.Type	WHEN 'P' THEN 'PROCEDURE' WHEN 'U' THEN 'TABLE' WHEN 'S' THEN 'SYSTEM TABLE' WHEN 'V' THEN 'VIEW' ELSE '[UNKNOWN]' END,
		Name		= SO.Name,
		ID			= SO.ID,
		Segments	= COUNT(SC.ID),
		Length		= SUM(DATALENGTH(SC.TEXT))
	FROM 
				SYSOBJECTS 		SO	WITH (NOLOCK) 
		JOIN	SYSCOMMENTS		SC	WITH (NOLOCK)  ON SC.ID = SO.ID
	WHERE 
		SO.TYPE IN('V','P')
	GROUP BY
		SO.TYPE,
		SO.NAME,
		SO.ID
	ORDER BY
		SO.TYPE,
		SO.NAME,
		SO.ID




