/****** Object:  View dbo.SYSTEM_TEMPORARY_TABLES    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW SYSTEM_TEMPORARY_TABLES AS	
	SELECT
		TABLE_NAME	= CASE
			WHEN TABLE_NAME LIKE '#%______________________%[0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F]' THEN LEFT(TABLE_NAME, CHARINDEX('_____________________________________', TABLE_NAME) - 1)
			ELSE TABLE_NAME END
	FROM
		tempdb.INFORMATION_SCHEMA.TABLES WITH (NOLOCK)
	WHERE 
		TABLE_NAME LIKE '#%' + REPLICATE('_', 116 - CHARINDEX('_____________________________________', TABLE_NAME)) + '%[0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F]'
	--ORDER BY TABLE_NAME






