/****** Object:  View dbo.Schema_Objects    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW [Schema_Objects] AS
	SELECT TOP 100 PERCENT
		*
	FROM
		(	SELECT [Type]	= 'table',		[Name]	= [Schema].[Table_Name]			FROM [Information_Schema].[Tables]		[Schema]	WITH (NOLOCK)	WHERE [Schema].[Table_Type]	= 'Base Table'
			UNION ALL
			SELECT [Type]	= 'view',		[Name]	= [Schema].[Table_Name]			FROM [Information_Schema].[Tables]		[Schema]	WITH (NOLOCK)	WHERE [Schema].[Table_Type]	= 'View'
			UNION ALL
			SELECT [Type]	= 'procedure',	[Name]	= [Schema].[Routine_Name]		FROM [Information_Schema].[Routines]	[Schema]	WITH (NOLOCK)	WHERE (NOT [Schema].[Routine_Name] LIKE 'dt_%')
		) [Objects]
	ORDER BY
		[Type], [Name]


