CREATE VIEW TEMP_TableLoaders AS
SELECT TOP 100 PERCENT
	TableName = KCU.TABLE_NAME, 
	Loader = ROUTINE_NAME, 
	PKey = KCU.COLUMN_NAME	
FROM 
	INFORMATION_SCHEMA.ROUTINES R WITH (NOLOCK)
	INNER JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE KCU WITH (NOLOCK) ON (KCU.TABLE_NAME = SUBSTRING(R.ROUTINE_NAME, 9, 999) AND KCU.ORDINAL_POSITION = 1 AND KCU.CONSTRAINT_NAME LIKE 'PK%')
WHERE 
	ROUTINE_NAME LIKE 'sp_load_%'
ORDER BY
	KCU.TABLE_NAME



