/****** Object:  View dbo.viewBid_ActiveWorksheet    Script Date: 7/31/2024 12:57:20 PM ******/

-- BACKUP

CREATE  VIEW viewBid_ActiveWorksheet AS
	SELECT
		LoanAppID					= Bid.LoanAppID,
		LoanApp_BidID				= Bid.LoanApp_BidID,
		LendersBranchID				= Branch.LendersBranchID,
		LenderID					= Branch.LenderID,
		LoanApp_WorksheetID			= MAX(Worksheet.LoanApp_WorksheetID)
	FROM
					tblLoanApp_Bids				Bid			WITH (NOLOCK)
		LEFT JOIN	tblLendersBranches			Branch		WITH (NOLOCK) ON	Branch.LendersBranchID		= Bid.LendersBranchID
		LEFT JOIN	tblLoanApp_Worksheet 		Worksheet	WITH (NOLOCK) ON	Worksheet.LoanApp_BidID		= Bid.LoanApp_BidID			AND
																				Worksheet.Active			= 1
	/*
	WHERE
		Bid.LoanApp_BidID		= @_LoanApp_BidID
	*/
	GROUP BY
		Bid.LoanAppID,
		Bid.LoanApp_BidID,
		Branch.LendersBranchID,
		Branch.LenderID



