/****** Object:  View [dbo].[view_LoanApps_Bids]    Script Date: 8/1/2024 9:38:13 AM ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



-- BACKUP

CREATE   VIEW view_LoanApps_Bids AS
SELECT TOP 100 PERCENT
  AUTO_LOAN_APP.LoanAppID,
  BID.LoanApp_BidID,
  AUTO_LOAN_APP.DealerID,
  AUTO_LOAN_APP.APPLICANT_NAMES,
  AUTO_LOAN_APP.CREDIT_GUID,
  BID.YIELD_TYPE,
  BID.COMMENTS,
  BID.TERM,
  BID.PAYMENT,
  BID.MESSAGING_STATUS,
  BID.REBATE_PERCT,
  ADVANCE = ISNULL(BID.ADVANCE,       0),
  LENDER_BRANCH.LenderID,
	BID.FINANCING_AMOUNT,

  ANTICIPATED_RATE        = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.ANTICIPATED_RATE,       '')     ELSE  ISNULL(AUTO_LOAN_APP.ANTICIPATED_RATE       , '')		END,
  LOAN_DOWN_PAYMENT       = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_DOWN_PAYMENT,       0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_DOWN_PAYMENT      ,  0)		END,
  LOAN_ESTIMATED_PAYMENT  = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_ESTIMATED_PAYMENT,  0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_ESTIMATED_PAYMENT ,  0)		END,
  LOAN_LICENSE            = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_LICENSE,            0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_LICENSE           ,  0)		END,
  LOAN_MISC               = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_MISC,               0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_MISC              ,  0)		END,
  LOAN_PURCHASE_PRICE     = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_PURCHASE_PRICE,     0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_PURCHASE_PRICE    ,  0)		END,
  LOAN_TAX                = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_TAX,                0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_TAX               ,  0)		END,
  LOAN_TERM_REQUESTED     = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_TERM_REQUESTED,     0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_TERM_REQUESTED    ,  0)		END,
  LOAN_TOTAL_LOAN_AMOUNT  = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT,  0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT ,  0)		END,
  LOAN_WARRANTY           = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.LOAN_WARRANTY,           0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_WARRANTY          ,  0)		END,
  VEHICLE_DESCRIPTION     = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.VEHICLE_DESCRIPTION,    '')     ELSE  ISNULL(AUTO_LOAN_APP.VEHICLE_DESCRIPTION    , '')		END,
  VEHICLE_MAKE            = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.VEHICLE_MAKE,           '')     ELSE  ISNULL(AUTO_LOAN_APP.VEHICLE_MAKE           , '')		END,
  VEHICLE_MILEAGE         = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.VEHICLE_MILEAGE,         0)     ELSE  ISNULL(AUTO_LOAN_APP.VEHICLE_MILEAGE        ,  0)		END,
  VEHICLE_MODEL           = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.VEHICLE_MODEL,          '')     ELSE  ISNULL(AUTO_LOAN_APP.VEHICLE_MODEL          , '')		END,
  VEHICLE_VIN             = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.VEHICLE_VIN,            '')     ELSE  ISNULL(AUTO_LOAN_APP.VEHICLE_VIN            , '')		END,
  VEHICLE_YEAR            = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.VEHICLE_YEAR,           '')     ELSE  ISNULL(AUTO_LOAN_APP.VEHICLE_YEAR           , '')		END,
  VEHICLE_TYPE            = CASE WHEN WS.LoanApp_WorksheetID  IS  NOT NULL  THEN  ISNULL(WS.VEHICLE_TYPE,           '')     ELSE  ISNULL(AUTO_LOAN_APP.VEHICLE_TYPE           , '')		END,

  LOAN_SALES_TAX_RATE     = CASE WHEN WS.LOAN_SALES_TAX_RATE  IS  NOT NULL  THEN  ISNULL(WS.LOAN_SALES_TAX_RATE,    '')     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_SALES_TAX_RATE    , '')		END,
  LOAN_TRADE_IN_NET       = CASE WHEN WS.LOAN_TRADE_IN_NET    IS  NOT NULL  THEN  ISNULL(WS.LOAN_TRADE_IN_NET,    0)     ELSE  ISNULL(AUTO_LOAN_APP.LOAN_TRADE_IN_NET    , 0)		END,


	VEHICLE									= CASE
		WHEN WS.LoanApp_WorksheetID	IS	NOT NULL	THEN
			CONVERT(CHAR(4),			WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL
		ELSE
			CONVERT(CHAR(4), AUTO_LOAN_APP.VEHICLE_YEAR) + ' ' + AUTO_LOAN_APP.VEHICLE_MAKE + ' ' + AUTO_LOAN_APP.VEHICLE_MODEL
		END,
	WorksheetID							= WS.LoanApp_WorksheetID,

  AUTO_LOAN_APP.COMMENTS AS LoanAppCOMMENTS,
  AUTO_LOAN_APP.LOAN_LICENSE_TAXABLE,
  AUTO_LOAN_APP.LOAN_DOCSMOG_TAXABLE,
  AUTO_LOAN_APP.SMOG_CERTIFY_FEE,
  AUTO_LOAN_APP.SMOG_CERTIFY_FEE_TAXABLE,
  AUTO_LOAN_APP.SMOG_SELLER_FEE,
  AUTO_LOAN_APP.SMOG_SELLER_FEE_TAXABLE,

  AUTO_LOAN_APP.LOAN_GAP,
  AUTO_LOAN_APP.LOAN_GAP_TAXABLE,
  AUTO_LOAN_APP.LOAN_WARRANTY_TAXABLE,
  AUTO_LOAN_APP.LOAN_MISC2,
  AUTO_LOAN_APP.LOAN_MISC_TAXABLE,
  AUTO_LOAN_APP.NEW_USED,

  STATUS = ISNULL(BID.STATUS, ''),
  BID.ARCHIVED,
  DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State AS Dealer,
  DEALER.EMail AS DealerEMail,
  AUTO_LOAN_APP.rowVersion,
  AUTO_LOAN_APP.UpdateUser,
  AUTO_LOAN_APP.CreateUser,
  AUTO_LOAN_APP.UpdateDateTime,
  AUTO_LOAN_APP.CreateDateTime,
  BID.RATE, BID.LendersBranchID,
  LENDER_BRANCH.LenderName + N' - ' + LENDER_BRANCH.BranchName + N' (' + LENDER_BRANCH.CITY + N', ' + LENDER_BRANCH.STATE + N')' AS Lender,
  LENDER_BRANCH.CITY as LenderBranch_City,
  LENDER_BRANCH.STATE as LenderBranch_State,
  LENDER_BRANCH.ZIP as LenderBranch_Zip,
  LENDER_BRANCH.STREET_1 as LenderBranch_Street1,
  LENDER_BRANCH.STREET_2 as LenderBranch_Street2,
  LENDER_BRANCH.Phone as LenderBranch_Phone,
  LENDER_BRANCH.Fax as LenderBranch_Fax,
  LENDER_BRANCH.BranchName, LENDER_BRANCH.notification_email AS lenderEmail,
  BID.CreateDateTime AS BidCreateDateTime,
  BID.UpdateDateTime AS BidUpdateDateTime,
  ISNULL(BID.SUBMIT_DATE, BID.CreateDateTime) AS BidSubmitDateTime,
  LENDER.Address AS LenderAddress,
  LENDER.City AS LenderCity,
  LENDER.State AS LenderState, LENDER.ZIP AS LenderZip,
  BID.LENDER_ARCHIVED, DEALER.DealerName, BID.FUNDED, BID.Stips, BID.Reason,
  BID.LENDER_CREDIT_GUID, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EX, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EQ,
  AUTO_LOAN_APP.DEALER_CREDIT_WANTS_TU, AUTO_LOAN_APP.DEALER_CREDIT_EX, AUTO_LOAN_APP.DEALER_CREDIT_EQ,
  AUTO_LOAN_APP.DEALER_CREDIT_TU, BID.LENDER_CREDIT_WANTS_EX, BID.LENDER_CREDIT_WANTS_TU, BID.LENDER_CREDIT_EQ,
  BID.LENDER_CREDIT_TU, BID.LENDER_CREDIT_EX, BID.LENDER_CREDIT_WANTS_EQ, BID.Reasons, BID.DISCOUNT_FEE, BID.AUTOMATED,
  BID.CANCELED_DATE, BID.OFFER_DATE, BID.FUNDED_DATE, BID.OFFERED_BY, BID.ACCEPT_DATE, BID.SUBMIT_DATE, BID.SUBMIT_BY,
  BID.PRIMARY_SCORE, BID.SECONDARY_SCORE, BID.ACCEPT_BY, BID.PTI, BID.DTI, AUTO_LOAN_APP.REMINDER_DATE,
  LENDER.LenderName, LENDER_BRANCH.Phone AS BranchPhone, LENDER_BRANCH.Fax AS BranchFax,
  LENDER_BRANCH.STREET_1 AS BranchStreet1,
  LENDER_BRANCH.STREET_2 AS BranchStreet2,
  LENDER_BRANCH.STATE AS BranchState,
  LENDER_BRANCH.ZIP AS BranchZip,
  LENDER_BRANCH.CITY AS BranchCity,
  AUTO_LOAN_APP.LenderID AS LenderDealerID,
  tblLoanApp_Bids_Fax.STATUS AS Fax_Status,
  tblLoanApp_Bids_Fax.UpdateDateTime AS Fax_LastUpdate,
  LENDER_BRANCH.FAX_TYPE AS BranchFaxType,
  LENDER_BRANCH.FAX_ONLY AS BranchFaxOnly,
  DEALER.City DealerCity,
  DEALER.State DealerState,
  BID.Counter,
  RESUBMIT_POLICY=ISNULL(LENDER.RESUBMIT_POLICY, 'NOT_ALLOWED'),
  t.ShortName AS PartnerName,
  ISNULL(ll.FullName, ISNULL(lbl.FullName,'')) As LenderAgentName,
  ISNULL(dl.UserName, '') as DealerSalesPerson,
  bfs.BidFundingStatus	,
  bfs.StatusUpdateDateTime as FundingStatusUpdateDateTime	,
  bfs.StatusUpdateUser as FundingStatusUpdateUser	,
  WorksheetActive = WS.Active,
  ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL) AS VEHICLE_RETAIL,
  ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED) AS VEHICLE_RETAIL_ADJUSTED,
  ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE) AS VEHICLE_WHOLESALE,
  ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED) AS VEHICLE_WHOLESALE_ADJUSTED
FROM
  tblLoanApps AUTO_LOAN_APP WITH (NOLOCK)
    INNER JOIN			tblLoanApp_Bids BID WITH (NOLOCK)                  ON   AUTO_LOAN_APP.LoanAppID = BID.LoanAppID
    INNER JOIN			viewLenderBranches LENDER_BRANCH WITH (NOLOCK)     ON   BID.LendersBranchID = LENDER_BRANCH.LendersBranchID
    INNER JOIN			tblLenders LENDER WITH (NOLOCK)                    ON   LENDER_BRANCH.LenderID = LENDER.LenderID
	INNER JOIN			viewBid_ActiveWorksheet Active_WS WITH (NOLOCK)		ON Active_WS.LoanApp_BidID = Bid.LoanApp_BidID

    LEFT OUTER JOIN   tblLoanApp_Bids_Fax WITH (NOLOCK)                  ON   BID.LoanApp_BidID = tblLoanApp_Bids_Fax.LoanApp_BidID
    LEFT OUTER JOIN   tblDealers DEALER WITH (NOLOCK)                    ON   AUTO_LOAN_APP.DealerID = DEALER.DealerID
    LEFT OUTER JOIN   tblLoanApp_Worksheet WS WITH (NOLOCK)              ON	WS.LoanApp_WorksheetID		= Active_WS.LoanApp_WorksheetID
--(BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)

	LEFT OUTER JOIN		viewLoanPartner			t		WITH (NOLOCK) ON AUTO_LOAN_APP.LoanAppID = t.LoanAppID

	LEFT OUTER JOIN tblLenderDealerRelation		r	      WITH (NOLOCK) ON r.DealerID = DEALER.DealerID AND LENDER_BRANCH.LenderID = r.LenderID
	LEFT OUTER JOIN tblLendersLogins		    ll		  WITH (NOLOCK) ON ll.LendersLoginID = r.LenderAgentID
	LEFT OUTER JOIN tblLendersBranchLogins		lbl		  WITH (NOLOCK) ON lbl.LendersBranchLoginID = r.LenderBranchAgentID
	LEFT OUTER JOIN tblLoanAppAssignedDealers	ad		  WITH (NOLOCK) ON ad.LoanAppID = AUTO_LOAN_APP.LoanAppID
    LEFT OUTER JOIN tblDealersLogins			dl		  WITH (NOLOCK) ON dl.DealersLoginID = ad.DealersLoginID
	LEFT OUTER JOIN tblLoanApp_BidFundingStatus	bfs		  WITH (NOLOCK) ON bfs.LoanApp_BidID = BID.LoanApp_BidID


--WHERE Bid.LoanApp_BidID = 1590562

