CREATE VIEW TEMP_viewLenderPending AS
SELECT --top 10
  BID.LoanAppID,
  BID.LoanApp_BidID,
  OfferDate = BID.Offer_Date,
  BidStatus = BID.Status,
  DaysSinceOffer = DATEDIFF(d, Offer_Date, GETDATE()),

  AcceptDate = case
    WHEN NOT Accept_Date is NULL THEN Accept_Date
    WHEN BID.Status IN ('accepted', 'Funded') THEN bidupdatedatetime
  end,

  FundingStartDate = Funded_Date,
  DaysSinceFundingStart = DATEDIFF(d, Funded_Date, GETDATE()),
  D.DealerName,
  Dealer =
    DBO.ProperCase(D.DealerName) + ' (' + DBO.ProperCase(D.City) + ', ' + Upper(D.State) + ')',
  applicant_Names = dbo.ProperCase(applicant_names),
  D.DealerID,
  BID.LenderID,
  LendersBranchID,
  vehicle = dbo.ProperCase(vehicle),
  TitleStatus = ISNULL(TI.Status, 'N/A'),
  TitleStatusDate = CASE
    WHEN TI.Status_Date IS NULL THEN NULL
    ELSE TI.Status_Date
  End,
  DaysSinceTitleStatus =  CASE
    WHEN TI.Status_Date IS NULL THEN ''
    WHEN datediff(d, TI.Status_Date, GETDATE()) < 2 THEN 'Today'
    ELSE CONVERT(VARCHAR(4), DATEDIFF(d, TI.Status_Date, GETDATE() )) + ' Days Ago'
