/****** Object:  View dbo.viewDealerRevenueDaily    Script Date: 7/31/2024 12:57:21 PM ******/


CREATE VIEW dbo.viewDealerRevenueDaily
AS
SELECT     TOP 100 PERCENT DATENAME([month], dbo.tblPayFlowTransactions.ts_added) AS [AP Month], DATEPART(mm, dbo.tblPayFlowTransactions.ts_added)
                      AS [Billing Month], DATEPART(dd, dbo.tblPayFlowTransactions.ts_added) AS [Day], DATEPART(yyyy, dbo.tblPayFlowTransactions.ts_added)
                      AS [AP Year], SUM(CONVERT(money, dbo.tblPayFlowTransactions.amt)) AS [Gross Revenue], SUM(CONVERT(money, dbo.tblPayFlowTransactions.amt)
                      * (dbo.tblAffiliatePayouts.payout_pct_external / 100)) AS [Payout Amt], SUM(CONVERT(money, dbo.tblPayFlowTransactions.amt)
                      * (dbo.tblAffiliatePayouts.payout_pct_internal / 100)) AS [Net Revenue]
FROM         dbo.tblDealersBilling INNER JOIN
                      dbo.tblDealers ON dbo.tblDealersBilling.dealerid = dbo.tblDealers.DealerID INNER JOIN
                      dbo.tblPayFlowTransactions ON dbo.tblDealersBilling.dealer_service_id = dbo.tblPayFlowTransactions.dealer_service_id INNER JOIN
                      dbo.tblAffiliatePayouts INNER JOIN
                      dbo.tblAffiliates ON dbo.tblAffiliatePayouts.payout_id = dbo.tblAffiliates.payout_id ON dbo.tblDealers.AffiliateID = dbo.tblAffiliates.AffiliateID
WHERE     (dbo.tblPayFlowTransactions.result = 0)
GROUP BY DATENAME([month], dbo.tblPayFlowTransactions.ts_added), DATEPART(dd, dbo.tblPayFlowTransactions.ts_added), DATEPART(mm,
                      dbo.tblPayFlowTransactions.ts_added), DATEPART(yyyy, dbo.tblPayFlowTransactions.ts_added)
ORDER BY DATEPART(yyyy, dbo.tblPayFlowTransactions.ts_added) DESC, DATEPART(dd, dbo.tblPayFlowTransactions.ts_added), DATEPART(mm,
                      dbo.tblPayFlowTransactions.ts_added)





