FROM
  INFORMATION_SCHEMA.ROUTINES R WITH (NOLOCK)
  JOIN sysObjects SO WITH (NOLOCK) ON (R.[ROUTINE_NAME]=SO.[NAME])
  JOIN sysComments SC WITH (NOLOCK) ON (SO.id = SC.id)
WHERE
  ROUTINE_CATALOG='CreditSmarts'





