/****** Object:  View dbo.ViewSchema_PrimaryKeyCount    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW [ViewSchema_PrimaryKeyCount] AS
	SELECT 
		[TABLES].[TABLE_NAME], [KEYS] = COUNT(*)
	FROM
					[INFORMATION_SCHEMA].[TABLES]								[TABLES]			WITH (NOLOCK)
		JOIN	[INFORMATION_SCHEMA].[TABLE_CONSTRAINTS]		[CONSTRAINTS]	WITH (NOLOCK) ON [CONSTRAINTS].[TABLE_NAME]			= [TABLES].[TABLE_NAME]
		JOIN	[INFORMATION_SCHEMA].[KEY_COLUMN_USAGE]			[KEY_COLUMN]	WITH (NOLOCK) ON [KEY_COLUMN].[CONSTRAINT_NAME]	= [CONSTRAINTS].[CONSTRAINT_NAME]
	WHERE
				[TABLES].[TABLE_TYPE]							= 'BASE TABLE'
		AND	[CONSTRAINTS].[CONSTRAINT_TYPE]		= 'PRIMARY KEY'
	GROUP BY
			[TABLES].[TABLE_NAME]
	
