/****** Object:  View dbo.__viewProcesses    Script Date: 7/31/2024 12:57:15 PM ******/
create view __viewProcesses as 


select top 1000
    P.spid
,P.last_batch
,datediff(n, P.last_batch, getdate()) as 'duration_minutes'
,  
right(
convert(varchar, 
            dateadd(n, datediff(n, P.last_batch, getdate()), '1900-01-01')
            ,121)
, 12) as 'batch_duration'
,  P.program_name
,   P.hostname
,   P.loginame
from master.dbo.sysprocesses P
where --P.spid > 50 and
      P.status not in ('background', 'sleeping')
and      P.cmd not in ('AWAITING COMMAND'
                    ,'MIRROR HANDLER'
                    ,'LAZY WRITER'
                    ,'CHECKPOINT SLEEP'
                    ,'RA MANAGER')
order by batch_duration desc

