/****** Object:  View dbo.BACKUP_viewB2B_DecisionsOutstandingToSend    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW BACKUP_viewB2B_DecisionsOutstandingToSend AS
	SELECT TOP 100 PERCENT --00 PERCENT
		PartnerToolID		= TOOL.PartnerToolID,
		PartnerCode			= TOOL.ShortName ,
		LoanApp_BidID		= BIDS.LoanApp_BidID,
		Field				= ELEMENT.Field,
		DataValue			= ELEMENT.DataValue,
		PartnerActive		= TOOL.Active,
		LendersBranchID		= BRANCH.LendersBranchID,
		LenderID			= BRANCH.LenderID,
		URL 				= CASE
			WHEN LEN(ISNULL(SEND.URL, '')) > 0 THEN SEND.URL
			WHEN TOOL.ShortName = 'LENDINGTREE' THEN 'https://lenderweb.lendingtree.com/LenderDecisions/AutoOfferPost.aspx'
			ELSE '' END,
		UserName = CASE
			WHEN LEN(RTRIM(LTRIM(ISNULL(SEND.Username, '')))) = 0 THEN	LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthUser, '')))
			ELSE	LTRIM(RTRIM(ISNULL(SEND.UserName, '')))	END,
		Password = CASE
			WHEN LEN(RTRIM(LTRIM(ISNULL(SEND.Password, '')))) = 0 THEN	LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthPassword, '')))
			ELSE	LTRIM(RTRIM(ISNULL(SEND.Password, '')))	END,
		XML					= SEND.XML,
		LastSentDateTime 	= DBO.StripToDate((SELECT MAX(DataValue) FROM tblPartnerDataElement	WITH (NOLOCK)	WHERE LoanApp_BidID=BIDS.LoanApp_BidID AND Field='LastSentDateTime')),
		LastUpdateDateTime	= DBO.StripToDate(BIDS.UpdateDateTime),
		BidStatus			= BIDS.Status

	FROM
						tblLoanApp_Bids				BIDS			WITH (NOLOCK)
			INNER JOIN	tblPartnerDataElement		ELEMENT			WITH (NOLOCK)	ON BIDS.LoanApp_BidID		= ELEMENT.LoanApp_BidID
			INNER JOIN	tblPartnerToolsTriggers		SEND			WITH (NOLOCK)	ON SEND.PartnerToolID		= ELEMENT.PartnerToolID		AND SEND.TYPE='SEND_DECISION'
			INNER JOIN	tblPartnerTools				TOOL			WITH (NOLOCK)	ON ELEMENT.PartnerToolID	= TOOL.PartnerToolID
		INNER JOIN	tblLendersBranches				BRANCH			WITH (NOLOCK)	ON BRANCH.LendersBranchID	= BIDS.LendersBranchID
		INNER JOIN	tblLenders						LENDER			WITH (NOLOCK)	ON LENDER.LenderID			= Branch.LenderID
		INNER JOIN	viewB2B_PartnerAuthentication	AUTHENTICATION	WITH (NOLOCK)	ON AUTHENTICATION.LenderID	= BRANCH.LenderID			AND AUTHENTICATION.PartnerToolID = ELEMENT.PartnerToolID

	WHERE
			TOOL.Active										 = 1
		AND	BIDS.Status										IN ('PENDING_DEALER', 'DECLINE_LENDER')
			AND	LENDER.LenderID								IN (SELECT LenderID FROM tblPartnerDataElement WITH (NOLOCK))
		AND	BRANCH.LENDERID								NOT	IN(1050)
		AND	Element.PartnerToolID 							IN (2, 8)
			AND	ELEMENT.Field								 =			(SELECT TOP 1 Field FROM tblPartnerElementDefinition DEFINITION	WITH (NOLOCK)	WHERE (DEFINITION.PartnerToolID=ELEMENT.PartnerToolID AND DEFINITION.ValueType='PARTNER_LOAN_ID'))
		AND	DATEDIFF(dd, BIDS.UpdateDateTime, GETDATE())	<=	14
		AND DBO.StripToDate(ISNULL((SELECT TOP 1 DataValue FROM tblPartnerDataElement	WITH (NOLOCK)	WHERE (LoanApp_BidID=BIDS.LoanApp_BidID ) AND Field='LastSentDateTime'), '1/1/2009')) 									<	DBO.StripToDate(BIDS.UpdateDateTime)
	ORDER BY
		BIDS.LoanAppID DESC,
		BIDS.LoanApp_BidID DESC



GO

