/****** Object:  View dbo.viewB2B_Lenders_UsingBeta_V3    Script Date: 7/31/2024 12:57:16 PM ******/

/*
	SET NOCOUNT ON;
	SET LOCK_TIMEOUT 60000;
	DECLARE	@_Now DATETIME; SET @_Now = GETDATE();
*/

CREATE VIEW [dbo].[viewB2B_Lenders_UsingBeta_V3] AS
	SELECT
		[PDE].[PartnerToolID], [Branch].[LenderID], [Branch].[LendersBranchID], [PDE].[UpdateDateTime] as ActivatedWhen
	FROM
					[tblLendersBranches]			[Branch]			WITH (NOLOCK)
		JOIN	[tblPartnerDataElement]		[PDE]					WITH (NOLOCK) 
		ON [PDE].[LenderID] = [Branch].[LenderID] 
		AND [PDE].[Field] = 'USE_V3' 
		AND [PDE].[DataValue] = 'TRUE' 
		AND [PDE].[Active] = 1 
		AND [PDE].[DealerID] = 0 
		AND [PDE].[LendersBranchID] = 0 
		AND [PDE].[LoanAppID] = 0 
		AND [PDE].[LoanApp_BidID] = 0
	WHERE
		EXISTS(SELECT * FROM [tblLenders] [Lender] WITH (NOLOCK) WHERE [Lender].[LenderID] = [Branch].[LenderID])

