/****** Object:  View dbo.viewB2B_PartnerFields    Script Date: 7/31/2024 12:57:16 PM ******/




CREATE VIEW [dbo].[viewB2B_PartnerFields] AS
SELECT TOP 100 PERCENT
  PartnerCode = PARTNER_TOOLS.ShortName,
  PartnerName = ISNULL(NULLIF(PARTNER_TOOLS.DisplayName, ''), PARTNER_TOOLS.ShortName),
  PartnerToolID                         =  FIELD_DEFINITION.PartnerToolID,
  PartnerElementDefinitionID            =  PartnerElementDefinitionID,
  Active                                =  FIELD_DEFINITION.Active,
  Field                                 =  Field,
  Description                           =  Description,
  KeyedFrom = SUBSTRING(
    ISNULL(NULLIF(ISNULL(NULLIF(ISNULL(CONVERT(VARCHAR(255), KeyedFromLoanAppID),        0), 1), ', Application'), '0'), '') +
    ISNULL(NULLIF(ISNULL(NULLIF(ISNULL(CONVERT(VARCHAR(255), KeyedFromLoanApp_BidID),    0), 1), ', Bid'), '0'), '') +
    ISNULL(NULLIF(ISNULL(NULLIF(ISNULL(CONVERT(VARCHAR(255), KeyedFromLenderID),         0), 1), ', Lender'), '0'), '') +
    ISNULL(NULLIF(ISNULL(NULLIF(ISNULL(CONVERT(VARCHAR(255), KeyedFromLendersBranchID),  0), 1), ', Branch'), '0'), '') +
    ISNULL(NULLIF(ISNULL(NULLIF(ISNULL(CONVERT(VARCHAR(255), KeyedFromDealerID),         0), 1), ', Dealer'), '0'), '') +
    ISNULL(NULLIF(ISNULL(NULLIF(ISNULL(CONVERT(VARCHAR(255), KeyedFromAffiliateID),      0), 1), ', Affiliate'), '0'), ''),
      3, 999),
  Type = CASE
        WHEN ValueType = 'ENABLED'                THEN 'CreditSmarts - Enabled'
        WHEN ValueType = 'LoanAppID'              THEN 'CreditSmarts - Internal Loan Number'
        WHEN ValueType = 'LoanApp_BidID'          THEN 'CreditSmarts - Internal Offer Number'
        WHEN ValueType = 'ApplicationID'          THEN 'CreditSmarts - Internal Application Number'
        WHEN ValueType = 'DealerID'               THEN 'CreditSmarts - Internal Dealership Number'
        WHEN ValueType = 'LenderID'               THEN 'CreditSmarts - Internal Lender Number'
        WHEN ValueType = 'LendersBranchID'        THEN 'CreditSmarts - Internal Branch Number'
        WHEN ValueType = 'AffiliateID'            THEN 'CreditSmarts - Internal Affilate Number'
        WHEN ValueType = 'PARTNER_LOAN_ID'        THEN 'Partner (Loan Data) - Loan Number'
        WHEN ValueType = 'PARTNER_OFFER_ID'       THEN 'Partner (Loan Data) - Offer Number'
        WHEN ValueType = 'PARTNER_DEALER_ID'      THEN 'Partner (Loan Data) - Dealership Number'
        WHEN ValueType = 'PARTNER_LENDER_ID'      THEN 'Partner (Loan Data) - Lender Number'
        WHEN ValueType = 'PARTNER_BRANCH_ID'      THEN 'Partner (Loan Data) - Branch Number'
        WHEN ValueType = 'PARTNER_AFFILATE_ID'    THEN 'Partner (Loan Data) - Affilate Number'
        WHEN ValueType = 'LENDER_LOAN_ID'         THEN 'Lender - Internal Loan Number'
        WHEN ValueType = 'LENDER_OFFER_ID'        THEN 'Lender - Internal Offer Number'
        WHEN ValueType = 'LENDER_DEALER_ID'       THEN 'Lender - Internal Dealership Number'
        WHEN ValueType = 'LENDER_BRANCH_ID'       THEN 'Lender - Internal Branch Number'
        WHEN ValueType = 'BRANCH_LOAN_ID'         THEN 'Branch - Internal Loan Number'
        WHEN ValueType = 'BRANCH_OFFER_ID'        THEN 'Branch - Internal Offer Number'
        WHEN ValueType = 'BRANCH_DEALER_ID'       THEN 'Branch - Internal Dealership Number'
        WHEN ValueType = 'BRANCH_AFFILATE_ID'     THEN 'Branch - Internal Affilate Number'
        WHEN ValueType = 'PARTNER_AUTH_LOGIN'     THEN 'Partner (Communications) - Post Login'
        WHEN ValueType = 'PARTNER_AUTH_PASSWORD'  THEN 'Partner (Communications) - Post Password'
        WHEN ValueType = 'PARTNER_POST_URL'       THEN 'Partner (Communications) - Post URL'
        WHEN ValueType = 'PARTNER_REMOTE_FOLDER'  THEN 'Partner (Communications) - Remote Folder'
        WHEN ValueType = 'PARTNER_CODE'       THEN 'Partner (Carleton) - Partner Code'
        WHEN ValueType = 'LENDER_CODE'       THEN 'Partner (Carleton) - Lender Code'
        ELSE '(Other/Unknown)'
    END,
  ValueType                             =  ValueType,
  ShowOnDealerAdmin                     =  ISNULL(ShowOnDealerAdmin, 0),
  ShowOnLenderAdmin                     =  ISNULL(ShowOnLenderAdmin, 0),
  ShowOnLendersBranchAdmin              =  ISNULL(ShowOnLendersBranchAdmin, 0),
  ShowOnAffiliateAdmin                  =  ISNULL(ShowOnAffiliateAdmin, 0),
  ShowOnLenderDealerConsoleAdmin        =  ISNULL(ShowOnLenderDealerConsoleAdmin, 0),
  Caption = CASE
        WHEN LEN(ISNULL(Caption, '')) > 0          THEN Caption
        WHEN ValueType = 'ENABLED'                 THEN 'CreditSmarts - Enabled'
        WHEN ValueType = 'LoanAppID'               THEN 'CreditSmarts - Internal Loan Number'
        WHEN ValueType = 'LoanApp_BidID'           THEN 'CreditSmarts - Internal Offer Number'
        WHEN ValueType = 'ApplicationID'           THEN 'CreditSmarts - Internal Application Number'
        WHEN ValueType = 'DealerID'                THEN 'CreditSmarts - Internal Dealership Number'
        WHEN ValueType = 'LenderID'                THEN 'CreditSmarts - Internal Lender Number'
        WHEN ValueType = 'LendersBranchID'         THEN 'CreditSmarts - Internal Branch Number'
        WHEN ValueType = 'AffiliateID'             THEN 'CreditSmarts - Internal Affilate Number'
        WHEN ValueType = 'PARTNER_LOAN_ID'         THEN 'Partner - Loan Number'
        WHEN ValueType = 'PARTNER_OFFER_ID'        THEN 'Partner - Offer Number'
        WHEN ValueType = 'PARTNER_DEALER_ID'       THEN 'Partner - Dealership Number'
        WHEN ValueType = 'PARTNER_LENDER_ID'       THEN 'Partner - Lender Number'
        WHEN ValueType = 'PARTNER_BRANCH_ID'       THEN 'Partner - Branch Number'
        WHEN ValueType = 'PARTNER_AFFILATE_ID'     THEN 'Partner - Affilate Number'
        WHEN ValueType = 'LENDER_LOAN_ID'          THEN 'Lender - Internal Loan Number'
        WHEN ValueType = 'LENDER_OFFER_ID'         THEN 'Lender - Internal Offer Number'
        WHEN ValueType = 'LENDER_DEALER_ID'        THEN 'Lender - Internal Dealership Number'
        WHEN ValueType = 'LENDER_BRANCH_ID'        THEN 'Lender - Internal Branch Number'
        WHEN ValueType = 'BRANCH_LOAN_ID'          THEN 'Branch - Internal Loan Number'
        WHEN ValueType = 'BRANCH_OFFER_ID'         THEN 'Branch - Internal Offer Number'
        WHEN ValueType = 'BRANCH_DEALER_ID'        THEN 'Branch - Internal Dealership Number'
        WHEN ValueType = 'BRANCH_AFFILATE_ID'      THEN 'Branch - Internal Affilate Number'
        WHEN ValueType = 'PARTNER_AUTH_LOGIN'      THEN 'Outbound Posting Login'
        WHEN ValueType = 'PARTNER_AUTH_PASSWORD'   THEN 'Outbound Posting Password'
        WHEN ValueType = 'PARTNER_POST_URL'        THEN 'Outbound Posting URL'
        WHEN ValueType = 'PARTNER_CODE'		THEN 'Partner (Carleton) - Partner Code'
        WHEN ValueType = 'LENDER_CODE'      THEN 'Partner (Carleton) - Lender Code'
        ELSE '(Other/Unknown)'
    END,
  KeyedFromLoanAppID                    =  KeyedFromLoanAppID,
  KeyedFromLoanApp_BidID                =  KeyedFromLoanApp_BidID,
  KeyedFromLenderID                     =  KeyedFromLenderID,
  KeyedFromLendersBranchID              =  KeyedFromLendersBranchID,
  KeyedFromDealerID                     =  KeyedFromDealerID,
  KeyedFromAffiliateID                  =  KeyedFromAffiliateID,
  SortSequence                          =  SortSequence,
  Value                                 =  Value,
  Notes                                 =  FIELD_DEFINITION.Notes,
  CreateDateTime                        =  FIELD_DEFINITION.CreateDateTime,
  UpdateDateTime                        =  FIELD_DEFINITION.UpdateDateTime,
  CreateUser                            =  FIELD_DEFINITION.CreateUser,
  UpdateUser                            =  FIELD_DEFINITION.UpdateUser,
  rowVersion                            =  FIELD_DEFINITION.rowVersion
FROM
  tblPartnerElementDefinition FIELD_DEFINITION WITH (NOLOCK)
    JOIN tblPartnerTools PARTNER_TOOLS WITH (NOLOCK) ON (PARTNER_TOOLS.PartnerToolID = FIELD_DEFINITION.PartnerToolID)
ORDER BY
  PartnerToolID, CONVERT(INT, ISNULL(NULLIF(SortSequence, 0), 9999)), Field






