/****** Object:  View dbo.viewLenderDisplayCaptions    Script Date: 7/31/2024 12:57:22 PM ******/


CREATE VIEW viewLenderDisplayCaptions AS
SELECT DISTINCT TOP 100 PERCENT
  LENDER.LenderID,
  BRANCH.LendersBranchID,
  BranchDisplayCaption = CASE
    WHEN LENDER.LenderName = BRANCH.BranchName THEN UPPER(REPLACE(REPLACE(REPLACE(LENDER.LenderName, ')', ''), '(', ''), '.', '') + ' - ' + BRANCH.City + ', ' + BranchState.State)
    WHEN LEFT(BRANCH.BranchName, LEN(LENDER.LenderName)) = LENDER.LenderName then REPLACE(REPLACE(REPLACE(UPPER(LENDER.LenderName + ' - ' + SUBSTRING(BRANCH.BranchName, LEN(LENDER.LenderName) + 2, 999)), ')', ''), '(', ''), '.', '')
    WHEN BRANCH.BranchName = BRANCH.City then UPPER(REPLACE(REPLACE(REPLACE(LENDER.LenderName, ')', ''), '(', ''), '.', '') + ' - ' + BRANCH.City + ', ' + BranchState.State)
    ELSE REPLACE(REPLACE(REPLACE(UPPER(LENDER.LenderName + ' - ' + BRANCH.BranchName), ')', ''), '(', ''), '.', '')
  END,
  LENDER.LenderName,
  BRANCH.BranchName,
  BranchCity = BRANCH.City,
  BranchState = BRANCH.State,
  BranchZip = BRANCH.Zip,
  BranchPhone = CASE
    WHEN LEN(ISNULL(BRANCH.Phone, '')) > 0 THEN dbo.scrubPhoneNumber(BRANCH.Phone)
    ELSE dbo.scrubPhoneNumber(LENDER.Phone)
  END,
  BranchFax = CASE
    WHEN LEN(ISNULL(BRANCH.Fax, '')) > 0 THEN dbo.scrubPhoneNumber(BRANCH.Fax)
    ELSE dbo.scrubPhoneNumber(LENDER.Fax)
  END,
  LenderPhone = dbo.scrubPhoneNumber(LENDER.Phone),
  LenderFax = dbo.scrubPhoneNumber(LENDER.Fax),
  LenderPrefix = UPPER(ISNULL(LENDER.LoginPrefix, '')),
  BranchPrefix = UPPER(ISNULL(BRANCH.LoginPrefix, ''))
FROM
  tblLenders LENDER WITH (NOLOCK)
  JOIN tblLendersBranches BRANCH WITH (NOLOCK) ON (LENDER.LenderID=BRANCH.LenderID)
  JOIN tblStates BranchState WITH (NOLOCK) ON (BranchState.StateAbbrev = BRANCH.State)
ORDER BY
  LENDER.LenderName,
  BRANCH.BranchName,
  BRANCH.City,
  BRANCH.State






