/****** Object:  View dbo.viewB2B_PartnerFields_RelationshipData    Script Date: 7/31/2024 12:57:23 PM ******/




--ALTER   VIEW viewB2B_PartnerFields_Dealer AS

CREATE VIEW [dbo].[viewB2B_PartnerFields_RelationshipData] AS

SELECT TOP 100 PERCENT
  PartnerDataElementID=ISNULL(DATA_VALUE.PartnerDataElementID, -1),
  FIELD_DEFINITION.PartnerElementDefinitionID,
  FIELD_DEFINITION.PartnerToolID,
  FIELD_DEFINITION.PartnerCode,
  FIELD_DEFINITION.PartnerName,
  DEALER.DealerID,
  Dealer = CASE
    WHEN LEN(ISNULL(DEALER.CITY, '')) > 0 AND LEN(ISNULL(DEALER.STATE, '')) > 0
      THEN UPPER(DEALER.DealerName + ' (' + DEALER.CITY + ', ' + DEALER.STATE + ')')
    WHEN LEN(ISNULL(DEALER.CITY, '')) > 0
      THEN UPPER(DEALER.DealerName + ' (' + DEALER.CITY + ')')
    WHEN LEN(ISNULL(DEALER.STATE, '')) > 0
      THEN UPPER(DEALER.DealerName + ' (' + DEALER.STATE + ')')
    ELSE
      UPPER(DEALER.DealerName)
    END,

  DATA_VALUE.LenderID,

  Lender = CASE
    WHEN LENDER.LenderID IS NULL THEN 'N/A'
    ELSE UPPER(LENDER.LenderName)
  END,

  DATA_VALUE.LendersBranchID,

  LenderBranch = CASE
    WHEN BRANCH.LendersBranchID IS NULL THEN 'N/A'
    ELSE BranchDisplayCaption
  END,

  FIELD_DEFINITION.Caption,
  FIELD_DEFINITION.Field,
  HasValue = CASE
    WHEN LEN(ISNULL(DATA_VALUE.DataValue, '')) > 0
      THEN CONVERT(BIT, 1)
    ELSE CONVERT(BIT, 0)
    END,
  DataValue       = ISNULL(NULLIF(DATA_VALUE.DataValue, ''), '(Not Entered)'),
  FIELD_DEFINITION.SortSequence,
  CreateDateTime  = ISNULL(DATA_VALUE.CreateDateTime, FIELD_DEFINITION.CreateDateTime),
  UpdateDateTime  = ISNULL(DATA_VALUE.UpdateDateTime, FIELD_DEFINITION.UpdateDateTime),
  CreateUser      = ISNULL(DATA_VALUE.CreateUser, FIELD_DEFINITION.CreateUser),
  UpdateUser      = ISNULL(DATA_VALUE.UpdateUser, FIELD_DEFINITION.UpdateUser),
  DATA_VALUE.Active,
  rowVersion      = ISNULL(DATA_VALUE.rowVersion, FIELD_DEFINITION.rowVersion)
FROM
  tblPartnerDataElement DATA_VALUE WITH (NOLOCK)
  JOIN viewB2B_PartnerFields FIELD_DEFINITION WITH (NOLOCK) ON (DATA_VALUE.Field = FIELD_DEFINITION.Field AND DATA_VALUE.PartnerToolID = FIELD_DEFINITION.PartnerToolID)

  LEFT OUTER JOIN tblDealers DEALER WITH (NOLOCK) ON (DATA_VALUE.DealerID = DEALER.DealerID)
  LEFT OUTER JOIN tblLenders LENDER WITH (NOLOCK) ON (DATA_VALUE.LenderID = LENDER.LenderID)
  LEFT OUTER JOIN viewLenderDisplayCaptions BRANCH WITH (NOLOCK) ON (DATA_VALUE.LendersBranchID = BRANCH.LendersBranchID)
WHERE
  (DEALER.DealerID IS NOT NULL OR LENDER.LenderID IS NOT NULL OR BRANCH.LendersBranchID IS NOT NULL)
ORDER BY
  FIELD_DEFINITION.SortSequence








