/****** Object:  View dbo.viewB2B_PartnerFields_Dealer    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW viewB2B_PartnerFields_Dealer AS

SELECT TOP 100 Percent
  RelationshipWith = CASE
    WHEN ISNULL(LendersBranchID, 0) > 0 THEN LenderBranch
    WHEN ISNULL(LenderID, 0) > 0 THEN Lender
    ELSE '(All On This Tool)'
  END,

  PartnerDataElementID,
  PartnerToolID,
  PartnerCode,
  PartnerName,
  DealerID,
  Dealer,
  Caption = CASE
    WHEN Field = 'Dealer Enabled (CreditSmarts)'
      THEN 'Activation by CreditSmarts Administration'

    WHEN Field = 'Dealer Enabled (Lender)' AND ISNULL(LendersBranchID, 0) > 0
      THEN 'Use Activated by ' + LenderBranch

    WHEN Field = 'Dealer Enabled (Lender)' AND ISNULL(LenderID, 0) > 0
      THEN 'Use Activated by ' + Lender

    WHEN Field = 'Dealer Enabled (Lender)'
      THEN 'Use Activated by Lender'

    WHEN ISNULL(LendersBranchID, 0) > 0
      THEN Caption + ' - ' + LenderBranch

    WHEN ISNULL(LenderID, 0) > 0
      THEN Caption + ' - ' + Lender

    ELSE Caption + ' (All Partners)'
  End,

  Field,
  HasValue,
  DataValue,
  CreateDateTime,
  UpdateDateTime,
  CreateUser,
  UpdateUser,
  rowVersion
FROM
  viewB2B_PartnerFields_RelationshipData
WHERE
  DealerID IN (SELECT DealerID FROM tblDealers)
ORDER BY
  PartnerCode, Lender, LenderBranch, SortSequence






