/****** Object:  View dbo.viewB2B_PartnerFields_Lender    Script Date: 7/31/2024 12:57:15 PM ******/



CREATE VIEW viewB2B_PartnerFields_Lender AS

SELECT TOP 100 Percent


  RelationshipWith = CASE
    WHEN ISNULL(DealerID, 0) > 0 Then Dealer
    ELSE '(All On This Tool)'
  END,

  PartnerDataElementID,
  PartnerToolID,
  PartnerCode,
  PartnerName,
  DealerID,
  LenderID,
  LendersBranchID,
  Dealer,
  Caption = CASE
    WHEN Field = 'Dealer Enabled (CreditSmarts)'
      THEN 'Activation by CreditSmarts Administration for ' + Dealer

    WHEN Field = 'Dealer Enabled (Lender)'
      THEN 'Activated by Lender for ' + Dealer

    ELSE Caption + ' (This Tool)'
  End,

  Field,
  HasValue,
  DataValue,
  CreateDateTime,
  UpdateDateTime,
  CreateUser,
  UpdateUser,
  rowVersion
FROM
  viewB2B_PartnerFields_RelationshipData
WHERE
  (NOT (ISNULL(DataValue, '') = '' OR ((Field = 'Dealer Enabled (Lender)' OR Field = 'Dealer Enabled (CreditSmarts)') AND DataValue='FALSE')))
ORDER BY
  PartnerCode, ISNULL(NULLIF(Dealer, ''), 'AAAAAAAAAAA'), SortSequence






