CREATE VIEW viewBids_Debug AS
	SELECT
		LoanAppID,
		LoanApp_BidID,
		Automated = CASE
			WHEN AUTOMATED='1' THEN 'Yes'
			ELSE 'No'
			END,
		Status = STATUS,
		LenderID,
		BranchID = LendersBranchID,
		Lender = LenderName,
		DealerID,
		Dealer,
		Applicant = APPLICANT_NAMES,
		Vehicle = VEHICLE,
		DEAL = CASE
			WHEN LEN(ISNULL(TERM, '')) > 0 AND ISNULL(PAYMENT, 0) > 0 AND ISNULL(FINANCING_AMOUNT, 0) > 0 THEN
				LTRIM(STR(FINANCING_AMOUNT)) + ' @ ' + LTRIM(STR(RATE)) + ' (' + LTRIM(STR(PAYMENT)) + '/Mo)'
			ELSE ''
			END,
		WorksheetID,
		Created = BidCreateDateTime,
		Updated = BidUpdateDateTime,
		Submitted = BidSubmitDateTime,
		[By] = CASE
			WHEN OFFER_DATE IS NULL OR OFFERED_BY IS NULL THEN ''
			WHEN LEN(ISNULL(OFFERED_BY, '')) = 0 THEN ''
			ELSE OFFERED_BY + ' On ' + CONVERT(VARCHAR(64), OFFER_DATE)
		END,
		Bureau_Lender = CASE
			WHEN LEN(ISNULL(LENDER_CREDIT_EX, '')) > 0 THEN 'EX'
			WHEN LEN(ISNULL(LENDER_CREDIT_TU, '')) > 0 THEN 'TU'
			WHEN LEN(ISNULL(LENDER_CREDIT_EQ, '')) > 0 THEN 'EQ'
			ELSE ''
			END,
		GUID_Lender = CASE
			WHEN LEN(ISNULL(LENDER_CREDIT_EX, '')) > 0 THEN LENDER_CREDIT_EX
			WHEN LEN(ISNULL(LENDER_CREDIT_TU, '')) > 0 THEN LENDER_CREDIT_TU
			WHEN LEN(ISNULL(LENDER_CREDIT_EQ, '')) > 0 THEN LENDER_CREDIT_EQ
			ELSE ''
			END,
		Bureau_Dealer = CASE
			WHEN LEN(ISNULL(DEALER_CREDIT_EX, '')) > 0 THEN 'EX'
			WHEN LEN(ISNULL(DEALER_CREDIT_TU, '')) > 0 THEN 'TU'
			WHEN LEN(ISNULL(DEALER_CREDIT_EQ, '')) > 0 THEN 'EQ'
			ELSE ''
			END,
		GUID_Dealer = CASE
			WHEN LEN(ISNULL(DEALER_CREDIT_EX, '')) > 0 THEN DEALER_CREDIT_EX
			WHEN LEN(ISNULL(DEALER_CREDIT_TU, '')) > 0 THEN DEALER_CREDIT_TU
			WHEN LEN(ISNULL(DEALER_CREDIT_EQ, '')) > 0 THEN DEALER_CREDIT_EQ
			ELSE ''
			END,
		Score_Primary = PRIMARY_SCORE,
		Score_Secondary = SECONDARY_SCORE,
		Filename = LTRIM(RTRIM(STR(LoanAppID))) + '-' + LTRIM(RTRIM(STR(LoanApp_BidID))) + '.XML',
