/****** Object:  View dbo.viewColumns    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW viewColumns AS
	SELECT TOP 100 PERCENT
		[DB]			= T.TABLE_CATALOG,
		[Owner]			= T.TABLE_SCHEMA,
		[Name]			= T.TABLE_NAME,
		IsTable			= CONVERT(BIT, CASE T.TABLE_TYPE WHEN 'BASE TABLE' THEN 1 ELSE 0 END),
		IsView			= CONVERT(BIT, CASE T.TABLE_TYPE WHEN 'VIEW' THEN 1 ELSE 0 END),
		--[Type]			= T.TABLE_TYPE,
		--[ ]				= '||',
		Position		= C.ORDINAL_POSITION,
		Field			= C.COLUMN_NAME,
		DataType		= UPPER(CASE WHEN DATA_TYPE = 'int' THEN 'INTEGER' WHEN DATA_TYPE IN ('VARCHAR', 'CHAR') THEN DATA_TYPE + '(' + CONVERT(VARCHAR(16), CHARACTER_MAXIMUM_LENGTH) + ')' ELSE C.DATA_TYPE END),
		Nullable		= CONVERT(BIT, CASE C.IS_NULLABLE WHEN 'YES' THEN 1 ELSE 0 END),
		DefaultValue	= C.COLUMN_DEFAULT
		--C.NUMERIC_PRECISION,
		--C.NUMERIC_PRECISION_RADIX,
		--C.NUMERIC_SCALE,
		--C.DATETIME_PRECISION,
		--C.DATA_TYPE,
		--C.CHARACTER_MAXIMUM_LENGTH,

	FROM
				INFORMATION_SCHEMA.TABLES		T	WITH (NOLOCK)
		JOIN	INFORMATION_SCHEMA.COLUMNS		C	WITH (NOLOCK)	ON T.TABLE_NAME = C.TABLE_NAME
	ORDER BY
		T.TABLE_TYPE,
		T.TABLE_NAME,
		C.ORDINAL_POSITION



