/****** Object:  View dbo.viewDealerZipCodes    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW viewDealerZipCodes AS
	SELECT --top 5
		DealerID = DEALER.DealerID,
		
		ZIP = CASE
			WHEN DEALER.ZIP IS NULL THEN NULL
			WHEN LEN(DEALER.ZIP) = 0 THEN NULL
			WHEN DEALER.ZIP = '0' THEN NULL
			WHEN ISNUMERIC( LEFT(DEALER.ZIP, 5) ) = 1 THEN LEFT(DEALER.ZIP, 5)
			WHEN CHARINDEX('-', DEALER.ZIP) > 0 AND ISNUMERIC(LEFT(DEALER.ZIP, CHARINDEX('-', DEALER.ZIP) - 1)) = 1 THEN LEFT(DEALER.ZIP, 5)
			ELSE
				NULL
		END,
		ZIP_AS_ENTERED = DEALER.ZIP,
		State = DEALER.STATE
	FROM
		tblDealers		DEALER	WITH (NOLOCK)





