/****** Object:  View dbo.viewFilterGen_ProgramFilters_Inner    Script Date: 7/31/2024 12:57:24 PM ******/

CREATE VIEW viewFilterGen_ProgramFilters_Inner AS
	SELECT TOP 100 PERCENT
		LenderID			= Program.LenderID,
		LenderName			= Lender.LenderName,
		City				= Lender.City,
		State				= Lender.State,
		ZIP					= Lender.Zip,
		RESUBMIT_POLICY		= ISNULL(RESUBMIT_POLICY, ''),
		S_R_A				= ISNULL(Lender.MIN_HOUSING_SINGLE_RENT_AMT,			0),
		S_M_A				= ISNULL(NULLIF(Lender.MIN_HOUSING_SINGLE_MORTGAGE_AMT,	0),	ISNULL(Lender.MIN_HOUSING_SINGLE_RENT_AMT, 0)),
		J_R_A				= ISNULL(NULLIF(Lender.MIN_HOUSING_JOINT_RENT_AMT,		0),	ISNULL(Lender.MIN_HOUSING_SINGLE_RENT_AMT, 0)),
		J_M_A				= ISNULL(NULLIF(Lender.MIN_HOUSING_JOINT_MORTGAGE_AMT,	0),	ISNULL(Lender.MIN_HOUSING_SINGLE_MORTGAGE_AMT, ISNULL(Lender.MIN_HOUSING_SINGLE_RENT_AMT, 0))),
		S_R_P				= ISNULL(Lender.MIN_HOUSING_SINGLE_RENT_PCT,			0),
		S_M_P				= ISNULL(NULLIF(Lender.MIN_HOUSING_SINGLE_MORTGAGE_PCT,	0),	ISNULL(Lender.MIN_HOUSING_SINGLE_RENT_PCT, 0)),
		J_R_P				= ISNULL(NULLIF(Lender.MIN_HOUSING_JOINT_RENT_PCT,		0),	ISNULL(Lender.MIN_HOUSING_SINGLE_RENT_PCT, 0)),
		J_M_P				= ISNULL(NULLIF(Lender.MIN_HOUSING_JOINT_MORTGAGE_PCT,	0),	ISNULL(NULLIF(Lender.MIN_HOUSING_SINGLE_MORTGAGE_PCT, 0), ISNULL(Lender.MIN_HOUSING_SINGLE_RENT_PCT, 0))),	
		ProgramID			= Program.ProgramID,
		ProgramName			= CASE ISNULL(Program.ProgramName, '')
				WHEN  ''  THEN 'Loan Program'
				ELSE      DBO.ProperCase(Program.ProgramName)
			END,
		CreditTier			= Program.CreditTier,
		Automated			= Program.Automated,
		Underwriting		= Program.Underwriting,
		AutoSelect			= Program.AutoSelect,
		NoCredit			= Program.NoCredit,
		Submit				= CASE WHEN Automated=0 AND Underwriting=0 THEN 1 ELSE 0 END,	
		Description			= CASE ISNULL(ProgramFilter.Description, '')
			WHEN ''             THEN 'Filter'
			WHEN 'FILTER SET'   THEN 'Filter'
			WHEN 'FILTER ONE'   THEN 'Filter #1'
			WHEN 'PRIMARY'      THEN 'Filter #1'
			WHEN 'FILTER TWO'   THEN 'Filter #2'
			WHEN 'FILTER THREE' THEN 'Filter #3'
			WHEN 'FILTER FOUR'  THEN 'Filter #4'
			WHEN 'FILTER FIVE'  THEN 'Filter #5'
			WHEN 'FILTER SIX'   THEN 'Filter #6'
			WHEN 'FILTER SEVEN' THEN 'Filter #7'
			WHEN 'FILTER EIGHT' THEN 'Filter #8'
			WHEN 'FILTER NINE'  THEN 'Filter #9'
			WHEN 'FILTER'       THEN 'Filter #1'
			WHEN 'FILTER1'      THEN 'Filter #1'
			WHEN 'FILTER2'      THEN 'Filter #2'
			WHEN 'FILTER3'      THEN 'Filter #3'
			WHEN 'FILTER4'      THEN 'Filter #4'
			WHEN 'FILTER5'      THEN 'Filter #5'
			WHEN 'FILTER6'      THEN 'Filter #6'
			WHEN 'FILTER7'      THEN 'Filter #7'
			WHEN 'FILTER8'      THEN 'Filter #8'
			WHEN 'FILTER9'      THEN 'Filter #9'
			WHEN 'FILTER 1'     THEN 'Filter #1'
			WHEN 'FILTER 2'     THEN 'Filter #2'
			WHEN 'FILTER 3'     THEN 'Filter #3'
			WHEN 'FILTER 4'     THEN 'Filter #4'
			WHEN 'FILTER 5'     THEN 'Filter #5'
			WHEN 'FILTER 6'     THEN 'Filter #6'
			WHEN 'FILTER 7'     THEN 'Filter #7'
			WHEN 'FILTER 8'     THEN 'Filter #8'
			WHEN 'FILTER 9'     THEN 'Filter #9'
			WHEN 'CR'           THEN 'Filter'
			WHEN 'CR1'          THEN 'Filter #1'
			WHEN 'CR2'          THEN 'Filter #2'
			WHEN 'CR3'          THEN 'Filter #3'
			WHEN 'CR4'          THEN 'Filter #4'
			WHEN 'CR5'          THEN 'Filter #5'
			WHEN 'CR6'          THEN 'Filter #6'
			WHEN 'CR7'          THEN 'Filter #7'
			WHEN 'CR8'          THEN 'Filter #8'
			WHEN 'CR9'          THEN 'Filter #9'
			WHEN 'CR 1'         THEN 'Filter #1'
			WHEN 'CR 2'         THEN 'Filter #2'
			WHEN 'CR 3'         THEN 'Filter #3'
			WHEN 'CR 4'         THEN 'Filter #4'
			WHEN 'CR 5'         THEN 'Filter #5'
			WHEN 'CR 6'         THEN 'Filter #6'
			WHEN 'CR 7'         THEN 'Filter #7'
			WHEN 'CR 8'         THEN 'Filter #8'
			WHEN 'CR 9'         THEN 'Filter #9'
			WHEN 'PR1'          THEN 'Filter #1'
			WHEN 'PR2'          THEN 'Filter #2'
			WHEN 'PR3'          THEN 'Filter #3'
			WHEN 'PR4'          THEN 'Filter #4'
			WHEN 'PR5'          THEN 'Filter #5'
			WHEN 'PR6'          THEN 'Filter #6'
			WHEN 'PR7'          THEN 'Filter #7'
			WHEN 'PR8'          THEN 'Filter #8'
			WHEN 'PR9'          THEN 'Filter #9'
			WHEN 'PR 1'         THEN 'Filter #1'
			WHEN 'PR 2'         THEN 'Filter #2'
			WHEN 'PR 3'         THEN 'Filter #3'
			WHEN 'PR 4'         THEN 'Filter #4'
			WHEN 'PR 5'         THEN 'Filter #5'
			WHEN 'PR 6'         THEN 'Filter #6'
			WHEN 'PR 7'         THEN 'Filter #7'
			WHEN 'PR 8'         THEN 'Filter #8'
			WHEN 'PR 9'         THEN 'Filter #9'
			ELSE                   DBO.ProperCase(ProgramFilter.Description)
		END,
	
		ProgramFilterID				= ISNULL(ProgramFilter.ProgramFilterID, 0),
		(SELECT COUNT(*) FROM tblValues V                       WITH (NOLOCK)  WHERE Len(Value) > 0 AND ProgramFilterID = ProgramFilter.ProgramFilterID) ParameterValueCount,
		(SELECT COUNT(*) FROM tblProgramFilterBranches          WITH (NOLOCK)  WHERE ProgramFilterID = ProgramFilter.ProgramFilterID) BranchFilterCount,
		(SELECT COUNT(*) FROM tblProgramFilterStates_App        WITH (NOLOCK)  WHERE ProgramFilterID = ProgramFilter.ProgramFilterID) ApplicantStateFilterCount,
		(SELECT COUNT(*) FROM tblProgramFilterCounties_App      WITH (NOLOCK)  WHERE ProgramFilterID = ProgramFilter.ProgramFilterID) ApplicantCountyFilterCount,
		(SELECT COUNT(*) FROM tblProgramFilterStates            WITH (NOLOCK)  WHERE ProgramFilterID = ProgramFilter.ProgramFilterID) DealerStateFilterCount,
		(SELECT COUNT(*) FROM tblProgramFilterCounties          WITH (NOLOCK)  WHERE ProgramFilterID = ProgramFilter.ProgramFilterID) DealerCountyFilterCount,
		(SELECT COUNT(*) FROM tblProgramFilterDealers           WITH (NOLOCK)  WHERE ProgramFilterID = ProgramFilter.ProgramFilterID) DealerFilterCount,
		(SELECT COUNT(*) FROM tblProgramFilterDealersExclude    WITH (NOLOCK)  WHERE ProgramFilterID = ProgramFilter.ProgramFilterID) DealerExcludeFilterCount,
		(SELECT COUNT(*) FROM tblProgramFilterStipulations      WITH (NOLOCK)  WHERE ProgramFilterID = ProgramFilter.ProgramFilterID) StipulationsCount,
		LastUpdate				= ISNULL(ProgramFilter.UpdateDateTime, Program.UpdateDateTime)	
	FROM
					tblPrograms			Program        		WITH (NOLOCK)
		LEFT JOIN	tblProgramFilter	ProgramFilter  		WITH (NOLOCK) ON ProgramFilter.ProgramID	= Program.ProgramID
		LEFT JOIN	tblLenders			Lender         		WITH (NOLOCK) ON Lender.LenderID		= Program.LenderID	
	ORDER BY
		Program.LenderID, ISNULL(Program.CreditTier, 'Z') DESC, Program.ProgramName, Program.ProgramID, ProgramFilter.Description, ProgramFilter.programFilterID




