		Underwriting					= ISNULL(PFI.Underwriting,					0),
		AutoSelect						= ISNULL(PFI.AutoSelect,					0),
		NoCredit						= CONVERT(BIT,	0),									--ISNULL(PFI.NoCredit,						0),
		Submit							= ISNULL(PFI.Submit,						0),
		Description						= ISNULL(PFI.Description,					''),
		ProgramFilterID					= ISNULL(PFI.ProgramFilterID,				0),
		ParameterValueCount				= ISNULL(PFI.ParameterValueCount,			0),
