		LenderName						= ISNULL(PFI.LenderName,					''),
		City							= ISNULL(PFI.City,							''),
		State							= ISNULL(PFI.State,							''),
		ZIP								= ISNULL(PFI.ZIP,							''),
		RESUBMIT_POLICY					= ISNULL(PFI.RESUBMIT_POLICY,				''),
		S_R_A							= ISNULL(PFI.S_R_A,							0),
		S_M_A							= ISNULL(PFI.S_M_A,							0),
		J_R_A							= ISNULL(PFI.J_R_A,							0),
		J_M_A							= ISNULL(PFI.J_M_A,							0),
		S_R_P							= ISNULL(PFI.S_R_P,							0),
		S_M_P							= ISNULL(PFI.S_M_P,							0),
		J_R_P							= ISNULL(PFI.J_R_P,							0),
		J_M_P							= ISNULL(PFI.J_M_P,							0),
		ProgramID						= ISNULL(PFI.ProgramID,						0),
		ProgramName						= ISNULL(PFI.ProgramName,					''),
		CreditTier						= ISNULL(PFI.CreditTier,					''),
		Automated						= ISNULL(PFI.Automated,						0),
		Underwriting					= ISNULL(PFI.Underwriting,					0),
		AutoSelect						= ISNULL(PFI.AutoSelect,					0),
		NoCredit						= ISNULL(PFI.NoCredit,						0),
		Submit							= ISNULL(PFI.Submit,						0),
		Description						= ISNULL(PFI.Description,					''),
		ProgramFilterID					= ISNULL(PFI.ProgramFilterID,				0),
		ParameterValueCount				= ISNULL(PFI.ParameterValueCount,			0),
		BranchFilterCount				= ISNULL(PFI.BranchFilterCount,				0),
		ApplicantStateFilterCount		= ISNULL(PFI.ApplicantStateFilterCount,		0),
		ApplicantCountyFilterCount		= ISNULL(PFI.ApplicantCountyFilterCount,    0),
		DealerStateFilterCount			= ISNULL(PFI.DealerStateFilterCount,		0),
		DealerCountyFilterCount			= ISNULL(PFI.DealerCountyFilterCount,		0),
		DealerFilterCount				= ISNULL(PFI.DealerFilterCount,				0),
		DealerExcludeFilterCount		= ISNULL(PFI.DealerExcludeFilterCount,		0),
		StipulationsCount				= ISNULL(PFI.StipulationsCount,				0),
		LastUpdate						= ISNULL(PFI.LastUpdate,					GETDATE())
	FROM
