CREATE VIEW viewBid_PartnerInformation AS
	SELECT
		[LoanAppID]				= MIN([Bid].[LoanAppID]), [Bid].[LoanApp_BidID], [LenderID] = MIN([Branch].[LenderID]), [LendersBranchID] = MIN([Branch].[LendersBranchID]),
		[PartnerCount]			= COUNT([ID].[PartnerToolID]),
		[PartnerToolID]			= ISNULL(MIN([ID].[PartnerToolID]), 0),
		[Partner]				= ISNULL(MIN([Partner].[ShortName]), ''),
		[PartnerName]			= ISNULL(MIN([Partner].[DisplayName]), ''),
		[PartnerLoanID_Name]	= ISNULL(MIN([ID].[Field]), ''),
		[PartnerLoanID]			= ISNULL(MIN([ID].[Value]), '')
	FROM
					[tblLoanApp_Bids]			[Bid]		WITH (NOLOCK)
		JOIN		[tblLendersBranches]		[Branch]	WITH (NOLOCK) ON [Branch].[LendersBranchID]		= [Bid].[LendersBranchID]
		LEFT JOIN	[tblPartnerLoanIdentifier]	[ID]		WITH (NOLOCK) ON [ID].[LoanApp_BidID]			= [Bid].[LoanApp_BidID]
		LEFT JOIN	[tblPartnerTools]			[Partner]	WITH (NOLOCK) ON [Partner].[PartnerToolID]		= [ID].[PartnerToolID]
--	WHERE
--		[Bid].[LoanApp_BidID] IN (SELECT [LoanApp_BidID] FROM @_Bids)
	GROUP BY
		[Bid].[LoanApp_BidID]
	

--SELECT * FROM viewBid_PartnerInformation WITH (NOLOCK) WHERE [LoanApp_BidID] IN (SELECT [LoanApp_BidID] FROM @_Bids);
