/****** Object:  View dbo.viewLoanAppPhoneNumbers    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW [dbo].[viewLoanAppPhoneNumbers]

AS

SELECT
	INFO.LoanAppID,
	
	NULLIF(
		DBO.fmt_phone_simple(
			PrimaryBorrower.Home_Phone_Area_Code,
			PrimaryBorrower.Home_Phone_Prefix,
			PrimaryBorrower.Home_Phone_Number),
		'000-000-0000')
			Primary_Home_Phone
,

	NULLIF(
		DBO.fmt_phone_simple(
			PrimaryBorrower.Mobile_Phone_Area_Code,
			PrimaryBorrower.Mobile_Phone_Prefix,
			PrimaryBorrower.Mobile_Phone_Number),
		'000-000-0000')
			Primary_Mobile_Phone,

	Secondary_Home_Phone = CASE Cast(Applicants AS VARCHAR(64))
		WHEN '1' THEN NULL
		WHEN '2' THEN
			NULLIF(
				DBO.fmt_phone_simple(
					SecondaryBorrower.Home_Phone_Area_Code,
					SecondaryBorrower.Home_Phone_Prefix,
					SecondaryBorrower.Home_Phone_Number),
				'000-000-0000')
	END,

	Secondary_Mobile_Phone = CASE Cast(Applicants AS VARCHAR(64))
		WHEN '1' THEN NULL
		WHEN '2' THEN
			NULLIF(
				DBO.fmt_phone_simple(
					SecondaryBorrower.Mobile_Phone_Area_Code,
					SecondaryBorrower.Mobile_Phone_Prefix,
					SecondaryBorrower.Mobile_Phone_Number),
				'000-000-0000')
	END,

	dbo.scrubPhoneNumber_simple(Dealer.Telephone)
		DealerPhone

FROM
	viewLoanAppPrimarySecondaryApplicant		INFO,
	tblLoanApp_Applicant										PrimaryBorrower,
	tblLoanApp_Applicant										SecondaryBorrower,
	tblLoanApps															LoanApp,
	tblDealers															Dealer

WHERE
				PrimaryBorrower.LoanApp_ApplicantID			= INFO.PrimaryApplicantID
	AND		SecondaryBorrower.LoanApp_ApplicantID		= INFO.PrimaryApplicantID
	AND		LoanApp.LoanAppID												= INFO.LoanAppID
	AND		LoanApp.DealerID												= Dealer.DealerID
	





