CREATE VIEW [dbo].[viewApplicantsIncome] AS

select distinct
	a.LoanApp_ApplicantID,
	a.LoanAppID,
	isnull(a.GROSS_MONTHLY,0) as bIncome,
	isnull(a.OTHER_MONTHLY,0) as bAddIncome,
	isnull(coa.GROSS_MONTHLY,0) as cobIncome,
	isnull(coa.OTHER_MONTHLY,0) as cobAddIncome
from dbo.tblLoanApp_Applicant a WITH (NOLOCK)
	left join tblLoanApp_Applicant coa WITH (NOLOCK) on
		a.LoanAppID = coa.LoanAppID and
		a.LoanApp_ApplicantID < coa.LoanApp_ApplicantID
