/****** Object:  View dbo.viewBidFundingStatus_History_Inner    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE view [dbo].[viewBidFundingStatus_History_Inner] AS 
SELECT
	bids.loanapp_bidid,
	bids.LenderID,
	case 
		when isnull(max(hist_rej.statusupdatedatetime),0) > isnull(max(hist_fund.statusupdatedatetime),0) then 
			datediff(mi, isnull(min(hist_rec.statusupdatedatetime), max(hist_rej.statusupdatedatetime)), max(hist_rej.statusupdatedatetime))+1
		else 
			datediff(mi, isnull(min(hist_rec.statusupdatedatetime), max(hist_fund.statusupdatedatetime)), max(hist_fund.statusupdatedatetime))+1
	end as [DateDiff]
	--,case 
	--	when isnull(max(hist_rej.statusupdatedatetime), 0) > isnull(max(hist_fund.statusupdatedatetime), 0) then '1'
	--	else '2'
	--end 
	--,min(offer_date) as offer_date
	,min(hist_rec.statusupdatedatetime) as received,
	 max(hist_rej.statusupdatedatetime)as rejected,
	 max(hist_fund.statusupdatedatetime) as funded
from 
	view_loanapps_bids bids WITH (NOLOCK)
	left join tblLoanApp_BidFundingStatus_History hist_rec  WITH (NOLOCK)  on (hist_rec.loanapp_bidid=bids.loanapp_bidid and hist_rec.bidfundingstatus='RECEIVED')
	left join tblLoanApp_BidFundingStatus_History hist_rej  WITH (NOLOCK)  on (hist_rej.loanapp_bidid=bids.loanapp_bidid and hist_rej.bidfundingstatus='REJECTED')
	left join tblLoanApp_BidFundingStatus_History hist_fund  WITH (NOLOCK)  on (hist_fund.loanapp_bidid=bids.loanapp_bidid and hist_fund.bidfundingstatus='FUNDED')
--WHERE lenderid = 1224
group by 
	bids.loanapp_bidid,bids.createdatetime, bids.lenderid


