--Can you please group the amount approved, rate, term, payment approved together?

--LOAN_TOTAL_LOAN_AMOUNT
--LOAN_ESTIMATED_PAYMENT
--LOAN_TERM_REQUESTED

--FINANCING_AMOUNT
--RATE
--TERM
--PAYMENT

CREATE                VIEW [dbo].[view_CSV_Export_Extended] AS
	SELECT --TOP 100 PERCENT 
		AUTO_LOAN_APP.LoanAppID, BID.LoanApp_BidID, AUTO_LOAN_APP.CREDIT_GUID, BID.YIELD_TYPE, BID.COMMENTS,
                      BID.MESSAGING_STATUS, BID.REBATE_PERCT, BID.ADVANCE,
                      LENDER_BRANCH.LenderID, 
					  
					  BID.FINANCING_AMOUNT, 
					  CONVERT(float,REPLACE(REPLACE(BID.RATE, '%', ''),'$', '')) AS RATE, 
					  CONVERT(int, LEFT(NULLIF(BID.TERM, 'NaN'), 2)) AS TERM,
					  BID.PAYMENT,  
					  
					  ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT) as LOAN_TOTAL_LOAN_AMOUNT, 
					  ISNULL(WS.LOAN_ESTIMATED_PAYMENT, AUTO_LOAN_APP.LOAN_ESTIMATED_PAYMENT) as LOAN_ESTIMATED_PAYMENT,
					  ISNULL(CONVERT(int,LEFT(NULLIF(WS.LOAN_TERM_REQUESTED, 'NaN'),2)), CONVERT(int,LEFT(NULLIF(AUTO_LOAN_APP.LOAN_TERM_REQUESTED, 'NaN'), 2))) AS LOAN_TERM_REQUESTED, 
					  
					  ISNULL(WS.LOAN_PURCHASE_PRICE, AUTO_LOAN_APP.LOAN_PURCHASE_PRICE) as LOAN_PURCHASE_PRICE,
                      ISNULL(WS.LOAN_DOWN_PAYMENT, AUTO_LOAN_APP.LOAN_DOWN_PAYMENT) as LOAN_DOWN_PAYMENT, AUTO_LOAN_APP.DealerID,
                      ISNULL(WS.VEHICLE_MODEL, AUTO_LOAN_APP.VEHICLE_MODEL) as VEHICLE_MODEL, ISNULL(WS.VEHICLE_MAKE, AUTO_LOAN_APP.VEHICLE_MAKE) as VEHICLE_MAKE, AUTO_LOAN_APP.APPLICANT_NAMES, ISNULL(WS.LOAN_MISC, AUTO_LOAN_APP.LOAN_MISC) as LOAN_MISC,
                      ISNULL(WS.LOAN_TAX, AUTO_LOAN_APP.LOAN_TAX) as LOAN_TAX, ISNULL(WS.LOAN_WARRANTY, AUTO_LOAN_APP.LOAN_WARRANTY) as LOAN_WARRANTY, ISNULL(WS.LOAN_GAP, AUTO_LOAN_APP.LOAN_GAP) as LOAN_GAP, ISNULL(WS.LOAN_LICENSE, AUTO_LOAN_APP.LOAN_LICENSE) as LOAN_LICENSE, 
					  CASE  WHEN BID.CANCELED_DATE IS NOT NULL THEN 'Cancelled as of ' + convert(varchar, BID.CANCELED_DATE, 101) ELSE BID.STATUS END as STATUS, 
					  --BID.STATUS,
					  BID.ARCHIVED,
                      DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State AS Dealer, ISNULL(WS.VEHICLE_MILEAGE, AUTO_LOAN_APP.VEHICLE_MILEAGE) as VEHICLE_MILEAGE, ISNULL(WS.VEHICLE_YEAR, AUTO_LOAN_APP.VEHICLE_YEAR) as VEHICLE_YEAR,
                      AUTO_LOAN_APP.COMMENTS AS LoanAppCOMMENTS, ISNULL(WS.VEHICLE_DESCRIPTION, AUTO_LOAN_APP.VEHICLE_DESCRIPTION) as VEHICLE_DESCRIPTION, DEALER.EMail AS DealerEMail, AUTO_LOAN_APP.rowVersion,
                      AUTO_LOAN_APP.UpdateUser, AUTO_LOAN_APP.CreateUser, AUTO_LOAN_APP.UpdateDateTime, AUTO_LOAN_APP.CreateDateTime,
                      BID.LendersBranchID,
                      LENDER_BRANCH.LenderName + N' - ' + LENDER_BRANCH.BranchName + N' (' + LENDER_BRANCH.CITY + N', ' + LENDER_BRANCH.STATE + N')' AS Lender,
                       LENDER_BRANCH.BranchName, LENDER_BRANCH.notification_email AS lenderEmail, BID.CreateDateTime AS BidCreateDateTime,
                      BID.UpdateDateTime AS BidUpdateDateTime,
                      ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), AUTO_LOAN_APP.VEHICLE_YEAR) + ' ' + AUTO_LOAN_APP.VEHICLE_MAKE + ' ' + AUTO_LOAN_APP.VEHICLE_MODEL) AS Vehicle,
                      dbo.tblLenders.Address AS LenderAddress, dbo.tblLenders.City AS LenderCity, dbo.tblLenders.State AS LenderState, dbo.tblLenders.ZIP AS LenderZip,
                      BID.LENDER_ARCHIVED, DEALER.DealerName, BID.FUNDED, BID.Stips, ISNULL(WS.ANTICIPATED_RATE,       AUTO_LOAN_APP.ANTICIPATED_RATE) as ANTICIPATED_RATE, BID.Reason,
                      BID.LENDER_CREDIT_GUID, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EX, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EQ,
