	LEFT OUTER JOIN		tblLendersLogins		    		  WITH (NOLOCK) ON tblLendersLogins.LendersLoginID = tblLenderDealerRelation.LenderAgentID
	LEFT OUTER JOIN		tblLendersBranchLogins				  WITH (NOLOCK) ON tblLendersBranchLogins.LendersBranchLoginID = tblLenderDealerRelation.LenderBranchAgentID








