/****** Object:  View dbo.viewSystemWaitingBlocking    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW [viewSystemWaitingBlocking] AS
	SELECT
		[Waiting] = ISNULL([X].[Waiting], 0),
		[Blocking] = ISNULL([X].[Blocking], 0),
		[WaitTime] = ISNULL([X].[WaitTime], 0)
	FROM
		(SELECT
			[Waiting] = COUNT([Proc].[spid]),
			[Blocking] = (SELECT COUNT([Proc_Inner].[SPID]) FROM [Master].[DBO].[SYSPROCESSES] [Proc_Inner] WITH (NOLOCK) WHERE NULLIF([Proc_Inner].[Blocked], 0) IS NOT NULL),
			[WaitTime] = SUM([Proc].[waittime])
		FROM
			[Master].[DBO].[SYSPROCESSES]											[Proc]		WITH (NOLOCK)
		WHERE
			[Proc].[cmd] NOT IN ('LAZY WRITER', 'LOG WRITER', 'LOCK MONITOR', 'CHECKPOINT SLEEP', 'TASK MANAGER', 'SIGNAL HANDLER') AND [Proc].[Program_Name] NOT IN ('SQL Query Analyzer - Trace') AND [Proc].[waitType] <> 0x020b AND NULLIF([Proc].[waittime], 0) IS NOT NULL
		) [X]
	WHERE
		NULLIF([X].[Waiting], 0) IS NOT NULL OR NULLIF([X].[Blocking], 0) IS NOT NULL OR NULLIF([X].[WaitTime], 0) IS NOT NULL


