CREATE VIEW viewUserLiabilityTypeDropdown AS
SELECT TOP 100 PERCENT
  UserLiabilityTypeID,
  display = CASE
    WHEN Category = 'AUTO' THEN 'Auto: ' + displayValue
    WHEN Category = 'EDUCATION' THEN 'Education: ' + displayValue
    WHEN Category = 'HOUSING' THEN 'Housing: ' + displayValue
    WHEN Category = 'OTHER' THEN 'Other: ' + displayValue
    WHEN Category = 'REVOLVING' THEN 'Revolving: ' + displayValue
    WHEN Category = 'INSTALLMENT' THEN 'Installment: ' + displayValue
    ELSE Category + ': ' + displayValue
  END
FROM
  viewUserLiabilityTypes
order by
  category, sortValue, displayValue





