/****** Object:  View dbo.viewLenderAutomationDealsToTag    Script Date: 7/31/2024 12:57:24 PM ******/



CREATE VIEW viewLenderAutomationDealsToTag AS
--ALTER VIEW BACKUP_2012_08_09_viewLenderAutomationDealsToTag AS
	SELECT TOP 100 PERCENT
		LoanAppID			= BID.LoanAppID,
		LoanApp_BidID		= BID.LoanApp_BidID,
		LenderID			= AUTOMATED_LENDERS.LenderID,
		LenderName			= AUTOMATED_LENDERS.LenderName,
		ProgramID			= AUTOMATED_LENDERS.ProgramID,
		ProgramName			= AUTOMATED_LENDERS.ProgramName,
		CreditTier			= AUTOMATED_LENDERS.CreditTier,
		LendersBranchID		= BRANCH.LendersBranchID,
		BranchName			= UPPER(BRANCH.BranchName),
		DealerID			= DEALER.DealerID,
		DealerName			= UPPER(DEALER.DealerName),
		DealerLocation		= UPPER(DEALER.CITY + ', ' + DEALER.STATE),
		Applicant			= UPPER(APP.Applicant_Names)
	
	FROM
							tblLoanApp_Bids						BID						WITH (NOLOCK)
			INNER JOIN		tblLendersBranches					BRANCH					WITH (NOLOCK)   ON  BRANCH.LendersBranchID = BID.LendersBranchID
			INNER JOIN		viewLenderAutomatedPrograms			AUTOMATED_LENDERS		WITH (NOLOCK)   ON  AUTOMATED_LENDERS.LenderID = BRANCH.LenderID
			INNER JOIN		tblLoanApps							APP						WITH (NOLOCK)   ON  APP.LoanAppID = BID.LoanAppID
			INNER JOIN		tblDealers							DEALER					WITH (NOLOCK)   ON  APP.DealerID = DEALER.DealerID
	WHERE
				(NOT ISNULL(APP.LenderID, 0) = BRANCH.LenderID)
