/****** Object:  View dbo.BACKUP_2013_06_12_viewB2B_CommentsOutstandingToSend    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW BACKUP_2013_06_12_viewB2B_CommentsOutstandingToSend AS
SELECT TOP 100 PERCENT
	PartnerToolID					=	ELEMENT.PartnerToolID,
	PartnerCode						= PARTNER_TOOL.ShortName,
	LoanApp_BidID					= ELEMENT.LoanApp_BidID,
	ELEMENT.Field,
	ELEMENT.DataValue,
	LendersBranchID 			= BIDS.LendersBranchID,
	TRIGGER_SEND.URL,
	TRIGGER_SEND.Username,
	TRIGGER_SEND.Password,
	TRIGGER_SEND.XML

FROM
				tblLoanApp_Bids 							BIDS 						WITH (NOLOCK)
	JOIN	tblPartnerDataElement 				ELEMENT 				WITH (NOLOCK)		ON BIDS.LoanApp_BidID = ELEMENT.LoanApp_BidID --AND ELEMENT.Field = DEFINITION.Field
	JOIN	tblPartnerElementDefinition 	DEFINITION 			WITH (NOLOCK)		ON DEFINITION.PartnerToolID = ELEMENT.PartnerToolID AND DEFINITION.Field = ELEMENT.Field AND DEFINITION.ValueType = 'PARTNER_LOAN_ID'
	JOIN	tblPartnerTools								PARTNER_TOOL		WITH (NOLOCK)		ON ELEMENT.PartnerToolID = PARTNER_TOOL.PartnerToolID
	JOIN	tblPartnerToolsTriggers				TRIGGER_SEND 		WITH (NOLOCK)		ON TRIGGER_SEND.PartnerToolID = ELEMENT.PartnerToolID AND TRIGGER_SEND.TYPE = 'SEND_MESSAGING'

WHERE
	BIDS.LoanApp_BiDID IN (SELECT LoanApp_BidID FROM tblLoanApp_Bids_CommentLog CL WITH (NOLOCK) WHERE [From] = 'LENDER' AND [DateTime] > '2010-08-01')
	AND
		(
		BIDS.LoanApp_BidID NOT IN (SELECT LoanApp_BidID FROM tblPartnerDataElement DE WITH (NOLOCK) WHERE Field='LastSentDateTime')
		OR
		dbo.StripToDate((SELECT MAX([DateTime]) FROM tblLoanApp_Bids_CommentLog CL WITH (NOLOCK) WHERE CL.LoanApp_BidID = BIDS.LoanApp_BidID AND CL.[FROM] = 'LENDER'))
		>
		dbo.StripToDate(CONVERT(DateTime, (SELECT MAX(DataValue) FROM tblPartnerDataElement	WITH (NOLOCK)	WHERE PartnerToolID = PARTNER_TOOL.PartnerToolID AND LoanApp_BidID = BIDS.LoanApp_BidID AND Field = 'LastSentDateTime')
		)))

	AND Element.PartnerToolID IN(2, 8)




