	    DealerID                    = DEALER.DealerID,

	    LoanApp_BidID               = BID.LoanApp_BidID,
			Status											= BID.Status,
	    LoanAppID                   = BID.LoanAppID,

			Customer = APP.Applicant_Names,

			CreditReportAccount = CASE
				WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN CONVERT(BIT, 1)
				WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN CONVERT(BIT, 1)
				ELSE CONVERT(BIT, 0)
			END,

			CreditReportAccountSource = CASE
				WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN 'LENDER_BRANCH'
				WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN 'LENDER_MASTER'
				ELSE 'NONE'
			END,

			CreditReportUserName = CASE
				WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(BRANCH.MicroBilt_Login))
				WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(LENDER.MicroBilt_Login))
				ELSE ''
			END,

			CreditReportPassword = CASE
				WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(BRANCH.MicroBilt_Password))
				WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(LENDER.MicroBilt_Password))
				ELSE ''
			END,

			Automation_Bureau = LENDER.AUTOMATION_CREDIT_PROVIDER,

			Existing_Bureau = CASE
				WHEN (ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'EX' AND LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) = 38) THEN BID.LENDER_CREDIT_EX
				WHEN (ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'TU' AND LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) = 38) THEN BID.LENDER_CREDIT_TU
				WHEN (ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'EQ' AND LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) = 38) THEN BID.LENDER_CREDIT_EQ
				WHEN (LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) = 38) THEN BID.LENDER_CREDIT_EX
				WHEN (LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) = 38) THEN BID.LENDER_CREDIT_TU
				WHEN (LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) = 38) THEN BID.LENDER_CREDIT_EQ
				ELSE ''
			END,
			Age													= DATEDIFF(s, BID.UpdateDateTime, GETDATE())
	FROM
	          tblLoanApp_Bids       BID     WITH (NOLOCK)
	    JOIN  tblLoanApps           APP     WITH (NOLOCK) ON  ( BID.LoanAppID           = APP.LoanAppID       )
	    JOIN  tblDealers            DEALER  WITH (NOLOCK) ON  ( DEALER.DealerID         = APP.DealerID        )
	    JOIN  tblLendersBranches    BRANCH  WITH (NOLOCK) ON  ( BRANCH.LendersBranchID  = BID.LendersBranchID )
	    JOIN  tblLenders            LENDER  WITH (NOLOCK) ON  ( BRANCH.LenderID         = LENDER.LenderID     )
	WHERE
		(NOT ISNULL(APP.LenderID, 0) = LENDER.LenderID)

		AND

			DATEDIFF(d, BID.UpdateDateTime, GETDATE()) <= 2

			AND
	    	(
				(BID.Status IN ('PENDING_AUTOMATION')) OR (BID.Status = 'PROCESSING_AUTOMATION' AND DATEDIFF(ss, BID.UpdateDateTime, GETDATE()) > 3000)
				OR
				(BID.LoanApp_BidID IN (SELECT DISTINCT LoanApp_BidID FROM viewLenderAutomationDealsToTag))
			)

	ORDER BY
	    BRANCH.LenderID DESC,
	    BRANCH.LendersBranchID,
	    BID.LoanApp_BidID DESC






