/****** Object:  View dbo.BACKUP_viewFF_MessagingUnread    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW BACKUP_viewFF_MessagingUnread AS

SELECT
	F.FreeformID,
	ISNULL(CONVERT(varchar(10), F.DealerID), 'undefined') DealerID,
	ISNULL('''' + D.DealerName + '''', 'undefined') DealerName,

	ISNULL(CONVERT(varchar(10), F.LenderID), 'undefined') LenderID,
	ISNULL('''' + L.LenderName + '''', 'undefined') LenderName,

	F.LendersBranchID,
	F.Admin,
	F.DealerLastRead,
	F.LenderLastRead,
	F.LendersBranchLastRead,
	F.AdminLastRead,
	MAX(FV.CreateDateTime) MostRecent

FROM
	tblFreeForm F WITH (NOLOCK)
	INNER JOIN tblFreeFormValues FV WITH (NOLOCK) ON F.FreeFormID = FV.FreeFormID
	--tblFreeFormValues FV
	--tblDealers D,
	--tblLenders L,
	--tblLendersBranches LB
	LEFT OUTER JOIN tblDealers D WITH (NOLOCK) ON F.DealerID = D.DealerID
	LEFT OUTER JOIN tblLenders L WITH (NOLOCK) ON F.LenderID = L.LenderID
	LEFT OUTER JOIN tblLendersBranches LB WITH (NOLOCK) ON F.LendersBranchID = LB.LendersBranchID

WHERE
	F.FreeFormID = FV.FreeFormID
	AND	Object = 'MESSAGING'
	AND	Property='CONVERSATION'

	--AND F.DealerID *= D.DealerID
	--AND F.LenderID *= L.LenderID
	--AND F.LendersBranchID *= LB.LendersBranchID

	AND	ID = 0
	

GROUP BY
	F.FreeformID,
	F.DealerID,
	D.DealerName,
	F.LenderID,
	L.LenderName,
	F.LendersBranchID,
	F.Admin,
	F.DealerLastRead,
	F.LenderLastRead,
	F.LendersBranchLastRead,
	F.AdminLastRead






