AS

SELECT
	FF.*,
	ISNULL((SELECT MAX(FV.UpdateDateTime) FROM tblFreeFormValues FV WHERE FF.FreeFormID = FV.FreeFormID), FF.CreateDateTime) UpdateDateTime,
	(SELECT COUNT(*) FROM tblFreeFormValues FV WHERE FF.FreeFormID = FV.FreeFormID) Entries,
	FV.FreeFormValueID,
	FV.mime_type,
	FV.length,
	FV.ShortValue,
	FV.EntryValue

FROM
	tblFreeForm FF WITH (NOLOCK)
	LEFT OUTER JOIN tblFreeFormValues FV WITH (NOLOCK) ON FF.FreeFormID = FV.FreeFormID
	--tblFreeFormValues FV

