CREATE VIEW BACKUP_view_LoanApp_FIPS AS

SELECT
	A.LoanAppID								LoanAppID,
	D.ZIP 										DealerZIP,
	D.State 									DealerState,
	Z1.CountyFIPS 						DealerFIPS,
	C.ZIP											CustomerZIP,
	C.State										CustomerState,
	Z2.CountyFIPS							CustomerFIPS

FROM
	tblLoanApps 						A,
	tblDealers 							D,
	tblZips 								Z1,
	tblZips									Z2,
	tblLoanApp_Applicant		AA,
	tblLoanApp_CurrAddress 	C

WHERE
	D.ZIP 		=		Z1.ZIPCode 			AND
	C.ZIP			=		Z2.ZIPCode 			AND

	C.LoanApp_ApplicantID 	= AA.LoanApp_ApplicantID	AND
	AA.LoanAppID 						= A.LoanAppID							AND
	A.DealerID							=	D.DealerID 							







