/****** Object:  View dbo.ERIK_TEMP_B2B_MULTIPLE_BIDS    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW ERIK_TEMP_B2B_MULTIPLE_BIDS AS
SELECT
--PDE.*,
LoanAppID					= BID_ORIGINAL.LoanAppID,
l = bid_other.loanappid,
LenderID					= BRANCH_ORIGINAL.LenderID,
LoanApp_BidID_Original		= BID_ORIGINAL.LoanApp_BidID,
LoanApp_BidID_Other			= BID_OTHER.LoanApp_BidID,
LendersBranchID_Original	= BRANCH_ORIGINAL.LendersBranchID,
LendersBranchID_Other		= BRANCH_OTHER.LendersBranchID,
Status_Original				= BID_ORIGINAL.Status,
Status_Other				= BID_OTHER.Status,

Same = CASE
	WHEN NOT ISNULL(BID_ORIGINAL.Financing_Amount, 0)		= ISNULL(BID_OTHER.Financing_Amount, 0) 	THEN CONVERT(BIT, 0)
	WHEN NOT ISNULL(NULLIF(BID_ORIGINAL.Term, '0'), '')		= ISNULL(NULLIF(BID_OTHER.Term, '0'), '')	THEN CONVERT(BIT, 0)
	WHEN NOT ISNULL(BID_ORIGINAL.Discount_Fee, 0)			= ISNULL(BID_OTHER.Discount_Fee, 0)			THEN CONVERT(BIT, 0)
	WHEN NOT ISNULL(NULLIF(BID_ORIGINAL.Rate, '0'), '')		= ISNULL(NULLIF(BID_OTHER.Rate, '0'), '')	THEN CONVERT(BIT, 0)
	WHEN NOT ISNULL(BID_ORIGINAL.Advance, 0)				= ISNULL(BID_OTHER.Advance, 0)				THEN CONVERT(BIT, 0)
	WHEN NOT ISNULL(BID_ORIGINAL.Payment, 0)				= ISNULL(BID_OTHER.Payment, 0)				THEN CONVERT(BIT, 0)
	WHEN NOT ISNULL(BID_ORIGINAL.Status, '')				= ISNULL(BID_OTHER.Status, '')				THEN CONVERT(BIT, 0)
	WHEN NOT ISNULL(BID_ORIGINAL.ARCHIVED, 0)				= ISNULL(BID_OTHER.ARCHIVED, 0)				THEN CONVERT(BIT, 0)
	ELSE CONVERT(BIT, 1)
END


FROM
			tblLoanApp_Bids 		BID_ORIGINAL		WITH (NOLOCK)
	JOIN	tblLendersBranches		BRANCH_ORIGINAL		WITH (NOLOCK)	ON BID_ORIGINAL.LendersBranchID = BRANCH_ORIGINAL.LendersBranchID

	JOIN	tblLoanApp_Bids 		BID_OTHER			WITH (NOLOCK) 	ON 				BID_ORIGINAL.LoanAppID 		=	BID_OTHER.LoanAppID
																			AND (NOT	BID_ORIGINAL.LoanApp_BidID	=	BID_OTHER.LoanApp_BidID)
																			AND			BID_OTHER.STATUS			IN	('PENDING_DEALER', 'DECLINE_LENDER')

	JOIN	tblLendersBranches		BRANCH_OTHER		WITH (NOLOCK)	ON		BID_OTHER.LendersBranchID		= BRANCH_OTHER.LendersBranchID
																			AND	BRANCH_OTHER.LenderID			= BRANCH_ORIGINAL.LenderID

	JOIN	tblPartnerDataElement	PDE					WITH (NOLOCK)	ON				PDE.LoanApp_BidID = BID_Original.LoanApp_BidID

WHERE
	BID_ORIGINAL.LoanApp_BidID IN (SELECT LoanApp_BidID FROM tblPartnerDataElement WITH (NOLOCK) WHERE PartnerToolID = 12)

	AND (NOT BID_OTHER.LoanApp_BidID IN (SELECT LoanApp_BidID FROM tblPartnerDataElement WITH (NOLOCK)))
	AND (NOT ISNULL(BID_OTHER.ARCHIVED, 0) = 1)
	AND (BID_OTHER.Canceled_Date IS NULL)






