/****** Object:  View dbo.TEMP_view_LoanApps_Bids_20111102    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW TEMP_view_LoanApps_Bids_20111102 AS
SELECT TOP 100 PERCENT
	APPLICATION.LoanAppID,
	BID.LoanApp_BidID,
	APPLICATION.DealerID,

	APPLICATION.APPLICANT_NAMES,

	BidAge = DATEDIFF(day, BID.UpdateDateTime, GetDate()),
	
	LENDER_ARCHIVED = ISNULL(BID.LENDER_ARCHIVED, 0),
	
	Canceled = CASE
		WHEN Canceled_Date IS NULL THEN CONVERT(BIT, 0)
		ELSE CONVERT(BIT, 1)
	End,
	
	Canceled_Date,
	
	Funded = CASE
		WHEN FUNDED_DATE IS NOT NULL THEN CONVERT(BIT, 1)
		WHEN Funded IS NULL THEN CONVERT(BIT, 0)
		ELSE CONVERT(BIT, Funded)
	End,

	DEALER_CREDIT_WANTS_EX = CASE
		WHEN LEN(ISNULL(APPLICATION.DEALER_CREDIT_EX, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(APPLICATION.DEALER_CREDIT_WANTS_EX, 0)
	END,

	DEALER_CREDIT_WANTS_EQ = CASE
		WHEN LEN(ISNULL(APPLICATION.DEALER_CREDIT_EQ, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(APPLICATION.DEALER_CREDIT_WANTS_EQ, 0)
	END,

	DEALER_CREDIT_WANTS_TU = CASE
		WHEN LEN(ISNULL(APPLICATION.DEALER_CREDIT_TU, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(APPLICATION.DEALER_CREDIT_WANTS_TU, 0)
	END,

	DEALER_CREDIT_EX		= ISNULL(APPLICATION.DEALER_CREDIT_EX, ''),
	DEALER_CREDIT_EQ		= ISNULL(APPLICATION.DEALER_CREDIT_EQ, ''),
	DEALER_CREDIT_TU		= ISNULL(APPLICATION.DEALER_CREDIT_TU, ''),

	LENDER_CREDIT_WANTS_EX = CASE
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(BID.LENDER_CREDIT_WANTS_EX, 0)
	END,

	LENDER_CREDIT_WANTS_EQ = CASE
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(BID.LENDER_CREDIT_WANTS_EQ, 0)
	END,

	LENDER_CREDIT_WANTS_TU = CASE
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(BID.LENDER_CREDIT_WANTS_TU, 0)
	END,

	LENDER_CREDIT_EX		= ISNULL(BID.LENDER_CREDIT_EX, ''),
	LENDER_CREDIT_EQ		= ISNULL(BID.LENDER_CREDIT_EQ, ''),
	LENDER_CREDIT_TU		= ISNULL(BID.LENDER_CREDIT_TU, ''),


	LenderID          = LENDER.LenderID,
	Lender            = LENDER_BRANCH.LenderName + N' - ' + LENDER_BRANCH.BranchName + N' (' + LENDER_BRANCH.CITY + N', ' + LENDER_BRANCH.STATE + N')',
	LenderName        = ISNULL(LENDER.LenderName, ''),
	LenderAddress     = ISNULL(LENDER.Address, ''),
	LenderCity        = ISNULL(LENDER.City, ''),
	LenderState       = ISNULL(LENDER.State, ''),
	LenderZip         = ISNULL(LENDER.ZIP, ''),
	LenderEMail       = ISNULL(LENDER_BRANCH.notification_email, ISNULL(LENDER.Notification_EMail, '')),

	LendersBranchID   = BID.LendersBranchID,
	BranchName        = ISNULL(LENDER_BRANCH.BranchName, ''),
	BranchStreet1     = ISNULL(LENDER_BRANCH.STREET_1, ''),
	BranchStreet2     = ISNULL(LENDER_BRANCH.STREET_2, ''),
	BranchCity        = ISNULL(LENDER_BRANCH.CITY, ''),
	BranchState       = ISNULL(LENDER_BRANCH.STATE, ''),
	BranchZip         = ISNULL(LENDER_BRANCH.ZIP, ''),
	BranchPhone       = ISNULL(LENDER_BRANCH.Phone, ''),
	BranchFax         = ISNULL(LENDER_BRANCH.Fax, ''),

	LENDER_BRANCH.FAX_TYPE AS BranchFaxType,
	LENDER_BRANCH.FAX_ONLY AS BranchFaxOnly,

	DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State AS Dealer,
	DEALER.EMail AS DealerEMail,
	DEALER.DealerName,
	DEALER.City DealerCity,
	DEALER.State DealerState,

	BID.YIELD_TYPE,
	BID.COMMENTS,
	TERM = CONVERT(INT, NULLIF(BID.TERM, '')),
	BID.PAYMENT,
	BID.MESSAGING_STATUS,
	BID.REBATE_PERCT,
	ADVANCE = ISNULL(BID.ADVANCE,       0),
	BID.FINANCING_AMOUNT,
	BID.STATUS,
	BID.ARCHIVED,
	BID.CreateDateTime AS BidCreateDateTime,
	BID.UpdateDateTime AS BidUpdateDateTime,
	BID.RATE,
	BID.Stips,
	BID.Reason,
	BID.Reasons,
	BID.DISCOUNT_FEE,
	BID.AUTOMATED,
	BID.OFFER_DATE,
	BID.FUNDED_DATE,
	BID.OFFERED_BY,
	BID.ACCEPT_DATE,
	BID.SUBMIT_DATE,
	BID.SUBMIT_BY,
	BID.PRIMARY_SCORE,
	BID.SECONDARY_SCORE,
	BID.ACCEPT_BY,
	BID.PTI,
	BID.DTI,
	BID.Counter,
	ISNULL(BID.SUBMIT_DATE, BID.CreateDateTime) AS BidSubmitDateTime,

	ANTICIPATED_RATE=          ISNULL(WS.ANTICIPATED_RATE,   APPLICATION.ANTICIPATED_RATE),
	LOAN_DOWN_PAYMENT=         ISNULL(WS.LOAN_DOWN_PAYMENT,  APPLICATION.LOAN_DOWN_PAYMENT),
	LOAN_ESTIMATED_PAYMENT=    ISNULL(WS.LOAN_ESTIMATED_PAYMENT, APPLICATION.LOAN_ESTIMATED_PAYMENT),
	LOAN_LICENSE=              ISNULL(WS.LOAN_LICENSE,       APPLICATION.LOAN_LICENSE),
	LOAN_MISC=                 ISNULL(WS.LOAN_MISC,          APPLICATION.LOAN_MISC),
	LOAN_PURCHASE_PRICE=       ISNULL(WS.LOAN_PURCHASE_PRICE,APPLICATION.LOAN_PURCHASE_PRICE),
	LOAN_TAX=                  ISNULL(WS.LOAN_TAX,           APPLICATION.LOAN_TAX),
	LOAN_TERM_REQUESTED=       ISNULL(WS.LOAN_TERM_REQUESTED,APPLICATION.LOAN_TERM_REQUESTED),
	LOAN_TOTAL_LOAN_AMOUNT=    ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, APPLICATION.LOAN_TOTAL_LOAN_AMOUNT),
	LOAN_WARRANTY=             ISNULL(WS.LOAN_WARRANTY,      APPLICATION.LOAN_WARRANTY),
	VEHICLE_DESCRIPTION=       ISNULL(WS.VEHICLE_DESCRIPTION,APPLICATION.VEHICLE_DESCRIPTION),
	VEHICLE_MAKE=              ISNULL(WS.VEHICLE_MAKE,       APPLICATION.VEHICLE_MAKE),
	VEHICLE_MILEAGE=           ISNULL(WS.VEHICLE_MILEAGE,    APPLICATION.VEHICLE_MILEAGE),
	VEHICLE_MODEL=             ISNULL(WS.VEHICLE_MODEL,      APPLICATION.VEHICLE_MODEL),
	VEHICLE_VIN=               ISNULL(WS.VEHICLE_VIN,        APPLICATION.VEHICLE_VIN),
	VEHICLE_YEAR=              ISNULL(WS.VEHICLE_YEAR,       APPLICATION.VEHICLE_YEAR),
	VEHICLE_TYPE = ISNULL(WS.VEHICLE_TYPE,       APPLICATION.VEHICLE_TYPE),
	VEHICLE=                   ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), APPLICATION.VEHICLE_YEAR) + ' ' + APPLICATION.VEHICLE_MAKE + ' ' + APPLICATION.VEHICLE_MODEL),

	WorksheetID = WS.LoanApp_WorksheetID,
	LoanAppComments = APPLICATION.COMMENTS,
	APPLICATION.LOAN_TRADE_IN_NET,
	APPLICATION.LOAN_LICENSE_TAXABLE,
	APPLICATION.LOAN_DOCSMOG_TAXABLE,
	APPLICATION.SMOG_CERTIFY_FEE,
	APPLICATION.SMOG_CERTIFY_FEE_TAXABLE,
	APPLICATION.SMOG_SELLER_FEE,
	APPLICATION.SMOG_SELLER_FEE_TAXABLE,
	APPLICATION.LOAN_GAP,
	APPLICATION.LOAN_GAP_TAXABLE,
	APPLICATION.LOAN_WARRANTY_TAXABLE,
	APPLICATION.LOAN_MISC2,
	APPLICATION.LOAN_MISC_TAXABLE,
	APPLICATION.NEW_USED,
	APPLICATION.REMINDER_DATE,
	APPLICATION.LenderID AS LenderDealerID,
	APPLICATION.rowVersion,
	APPLICATION.UpdateUser,
	APPLICATION.CreateUser,
	APPLICATION.UpdateDateTime,
	APPLICATION.CreateDateTime,

	FAX.Fax_Status,
	FAX.Fax_LastUpdate,

	RESUBMIT_POLICY=ISNULL(LENDER.RESUBMIT_POLICY, 'NOT_ALLOWED'),

	PARTNER.PartnerName,

	BidFundingStatus	= ISNULL(FUNDING.BidFundingStatus, ''),
	FUNDING.StatusUpdateDateTime,

	LenderAgentName = CASE
		WHEN ASSIGNMENT.LendersLoginID IS NULL		THEN ''
		WHEN LEN(ISNULL(ASSIGNMENT.LenderFullName, '')) > 0		THEN ASSIGNMENT.LenderFullName
		WHEN LEN(ISNULL(ASSIGNMENT.LenderUserName, '')) > 0		THEN ASSIGNMENT.LenderUserName
		ELSE 'Agent of ' + LENDER.LenderName
	End,

	BranchAgentName = CASE
		WHEN ASSIGNMENT.LendersBranchLoginID IS NULL		THEN ''
		WHEN LEN(ISNULL(ASSIGNMENT.BranchFullName, '')) > 0		THEN ASSIGNMENT.BranchFullName
		WHEN LEN(ISNULL(ASSIGNMENT.BranchUserName, '')) > 0		THEN ASSIGNMENT.BranchUserName
		ELSE 'Agent of ' + LENDER_BRANCH.BranchName
	End,

	DealerSalesPerson = CASE
		WHEN ASSIGNMENT.DealersLoginID IS NULL					THEN ''
		WHEN LEN(ISNULL(ASSIGNMENT.DealerFullName, '')) > 0		THEN ASSIGNMENT.DealerFullName
		WHEN LEN(ISNULL(ASSIGNMENT.DealerUserName, '')) > 0		THEN ASSIGNMENT.DealerUserName
		ELSE 'Sales Person at ' + DEALER.DealerName
	End

FROM
  						tblLoanApps					APPLICATION		WITH (NOLOCK)
    		INNER JOIN	tblLoanApp_Bids				BID				WITH (NOLOCK) ON APPLICATION.LoanAppID		= BID.LoanAppID
    		INNER JOIN	viewLenderBranches			LENDER_BRANCH	WITH (NOLOCK) ON BID.LendersBranchID		= LENDER_BRANCH.LendersBranchID
    		INNER JOIN	tblLenders 					LENDER			WITH (NOLOCK) ON LENDER_BRANCH.LenderID		= LENDER.LenderID
			INNER JOIN	viewBidsPartnerTool			PARTNER 		WITH (NOLOCK) ON BID.LoanApp_BidID			= PARTNER.LoanApp_BidID
			INNER JOIN	viewBidsFaxStatus			FAX 			WITH (NOLOCK) ON FAX.LoanApp_BidID			= BID.LoanApp_BidID
			INNER JOIN	viewBidsLoanAppAssignment	ASSIGNMENT		WITH (NOLOCK) ON ASSIGNMENT.LoanApp_BidID	= BID.LoanApp_BidID
			INNER JOIN	viewBidsFundingStatus		FUNDING 		WITH (NOLOCK) ON FUNDING.LoanApp_BidID		= BID.LoanApp_BidID
	LEFT	OUTER JOIN	tblDealers					DEALER			WITH (NOLOCK) ON APPLICATION.DealerID		= DEALER.DealerID
    LEFT	OUTER JOIN	tblLoanApp_Worksheet		WS 				WITH (NOLOCK) ON (BID.LoanApp_BidID			= WS.LoanApp_BidID AND WS.ACTIVE=1)

ORDER BY
	BID.LoanApp_BidID DESC,
	APPLICATION.LoanAppID DESC






GO

SET QUOTED_IDENTIFIER OFF 
