/****** Object:  View dbo.TEMP_2011_12_07_viewBidsInterfaceDisplay    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW TEMP_2011_12_07_viewBidsInterfaceDisplay AS
	SELECT
		LoanAppID,
		LoanApp_BidID,
		DealerID,
		APPLICANT_NAMES,
		YIELD_TYPE,
		COMMENTS = '',

	TERM = CASE
		WHEN TERM IS NULL 				THEN NULL
		WHEN ISNUMERIC(TERM) = 1		THEN TERM
		WHEN TERM = ''					THEN NULL
		WHEN CHARINDEX('M', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('M', TERM) - 1))
		WHEN CHARINDEX('/', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('/', TERM) - 1))
		WHEN CHARINDEX(' ', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX(' ', TERM) - 1))
		ELSE -1
	END,
		PAYMENT,
		MESSAGING_STATUS,
		REBATE_PERCT,
		ADVANCE,
		LenderID,

		BidAge = DBO.DAYSAGO(BidUpdateDateTime, GETDATE()),

		LENDER_ARCHIVED = ISNULL(LENDER_ARCHIVED, 0),

		Canceled = CASE
			WHEN Canceled_Date IS NULL THEN CONVERT(BIT, 0)
			ELSE CONVERT(BIT, 1)
		End,

		Canceled_Date,

		Funded = CASE
			WHEN FUNDED_DATE IS NOT NULL THEN CONVERT(BIT, 1)
			WHEN Funded IS NULL THEN CONVERT(BIT, 0)
			ELSE CONVERT(BIT, Funded)
		End,

		ShowInLenderNewDeals = CASE
			WHEN NOT Canceled_Date	IS NULL									THEN CONVERT(BIT, 0)
			WHEN LENDER_ARCHIVED	=  1 									THEN CONVERT(BIT, 0)
			WHEN DBO.DAYSAGO(BidUpdateDateTime, GETDATE()) > 30				THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus IN ('RECEIVED', 'REJECTED')				THEN CONVERT(BIT, 0)
			WHEN STATUS IN ('PENDING_LENDER', 'REFERRED', 'PENDING_B2B') 	THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
		END,

		ShowInLenderPendingFunding = CASE
			WHEN StatusUpdateDateTime	IS	NULL						THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus		IS	NULL						THEN CONVERT(BIT, 0)
			WHEN LEN(BidFundingStatus)	=	0							THEN CONVERT(BIT, 0)
			WHEN DBO.DAYSAGO(StatusUpdateDateTime, GETDATE()) > 45		THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'RECEIVED'							THEN CONVERT(BIT, 1)
			WHEN DBO.DAYSAGO(StatusUpdateDateTime, GETDATE()) > 30		THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'REJECTED'							THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
			--ELSE CONVERT(BIT, 1)
		END,

		ShowInLenderMessaging = CASE
			WHEN NOT Canceled_Date	IS NULL									THEN CONVERT(BIT, 0)
			WHEN LENDER_ARCHIVED	=  1 									THEN CONVERT(BIT, 0)
			WHEN DBO.DAYSAGO(BidUpdateDateTime, GETDATE()) > 14			THEN CONVERT(BIT, 0)
			WHEN Messaging_Status = 'COMMENT_FOR_LENDER'					THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
		END,

		Message_Age_Dealer = CASE
			WHEN
				MESSAGING_STATUS IN ('COMMENT_FOR_DEALER')
					THEN (SELECT MAX(DateTime) FROM tblLoanapp_Bids_CommentLog WITH (NOLOCK) WHERE tblLoanapp_Bids_CommentLog.LoanApp_BidID = LoanApp_BidID AND [FROM]='LENDER')
			ELSE NULL
		END,

		Message_Age_Lender = CASE
			WHEN
				MESSAGING_STATUS IN ('COMMENT_FOR_LENDER')
					THEN (SELECT MAX(DateTime) FROM tblLoanapp_Bids_CommentLog WITH (NOLOCK) WHERE tblLoanapp_Bids_CommentLog.LoanApp_BidID = LoanApp_BidID AND [FROM]='DEALER')
			ELSE NULL
		END,

		ShowInDealerNewDeals = CASE
--			WHEN
--					MESSAGING_STATUS	= 'COMMENT_FOR_DEALER'
--				AND DBO.DAYSAGO(BidUpdateDateTime, GETDATE()) <= 30
--																								THEN CONVERT(BIT, 1)
			WHEN					
					BidFundingStatus IN ('REJECTED')
				AND	DBO.DAYSAGO(StatusUpdateDateTime, GETDATE()) <= 30							THEN CONVERT(BIT, 1)

			WHEN				
					ISNULL(StatusUpdateDateTime, FUNDED_DATE) IS NOT NULL
				AND	DBO.DAYSAGO(ISNULL(StatusUpdateDateTime, FUNDED_DATE), GETDATE()) <= 14		THEN CONVERT(BIT, 1)

			WHEN
					DBO.DAYSAGO(OFFER_DATE, GETDATE()) <= 14				
				AND STATUS NOT IN ('ACCEPTED')													THEN CONVERT(BIT, 1)

			WHEN
				DBO.DAYSAGO(BidUpdateDateTime, GETDATE()) <= 7				
				AND STATUS IN ('REFERRED', 'DECLINE_LENDER', 'PENDING_LENDER', 'PENDING_AUTOMATION', 'PROCESSING_AUTOMATION', 'B2B_ERROR', 'PENDING_B2B', 'DUPLICATE')																								THEN CONVERT(BIT, 1)

			WHEN
				DBO.DAYSAGO(BidUpdateDateTime, GETDATE()) <= 14				
				AND STATUS IN ('PENDING_DEALER')
																								THEN CONVERT(BIT, 1)


			ELSE CONVERT(BIT, 0)
		END,

		ShowInDealerMessaging = CASE
			WHEN NOT Canceled_Date	IS NULL									THEN CONVERT(BIT, 0)
			WHEN LENDER_ARCHIVED	=  1 									THEN CONVERT(BIT, 0)
			WHEN DBO.DAYSAGO(BidUpdateDateTime, GETDATE()) > 14			THEN CONVERT(BIT, 0)
			WHEN Messaging_Status = 'COMMENT_FOR_DEALER'					THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
		END,

		ShowInDealerFunding = CASE
			WHEN StatusUpdateDateTime	IS	NULL						THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus		IS	NULL						THEN CONVERT(BIT, 0)
			WHEN LEN(BidFundingStatus)	=	0							THEN CONVERT(BIT, 0)
			WHEN DBO.DAYSAGO(StatusUpdateDateTime, GETDATE()) > 45	THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'RECEIVED'							THEN CONVERT(BIT, 1)
			WHEN DBO.DAYSAGO(StatusUpdateDateTime, GETDATE()) > 30	THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'REJECTED'							THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
			--ELSE CONVERT(BIT, 1)
		END,

		FUNDED_DATE,
		FINANCING_AMOUNT,
		ANTICIPATED_RATE,
		LOAN_DOWN_PAYMENT,
		LOAN_ESTIMATED_PAYMENT,
		LOAN_LICENSE,
		LOAN_MISC,
		LOAN_PURCHASE_PRICE,
		LOAN_TAX,
		LOAN_TERM_REQUESTED,
		LOAN_TOTAL_LOAN_AMOUNT,
		LOAN_WARRANTY,
		VEHICLE_DESCRIPTION,
		VEHICLE_MAKE,
		VEHICLE_MILEAGE,
		VEHICLE_MODEL,
		VEHICLE_VIN,
		VEHICLE_YEAR,
		VEHICLE_TYPE,
		VEHICLE,
		WorksheetID,
		NEW_USED,
		STATUS,
		ARCHIVED = ISNULL(ARCHIVED, 0),
		Dealer,
		DealerEMail,
		UpdateUser,
		CreateUser,
		UpdateDateTime,
		CreateDateTime,
		RATE,
		LendersBranchID,
		Lender,
		BranchName,
		BidCreateDateTime,
		BidUpdateDateTime,
		BidSubmitDateTime,
		LenderCity,
		LenderState,
		DealerName,
		Stips,
		Reason,
		DEALER_CREDIT_EX,
		DEALER_CREDIT_EQ,
		DEALER_CREDIT_TU,
		LENDER_CREDIT_EQ,
		LENDER_CREDIT_TU,
		LENDER_CREDIT_EX,
		Reasons,
		DISCOUNT_FEE,
		AUTOMATED,
		OFFER_DATE,

		OFFERED_BY,
		ACCEPT_DATE,
		SUBMIT_DATE,
		SUBMIT_BY,
		PRIMARY_SCORE,
		SECONDARY_SCORE,
		ACCEPT_BY,
		PTI,
		DTI,
		REMINDER_DATE,
		LenderName,

		BranchStreet1,		
		BranchPhone,
		BranchFax,
		BranchCity,
		BranchState,
		BranchZip,

		BranchFaxOnly = ISNULL(BranchFaxOnly, 0),



		LenderDealerID,
		Fax_Status,
		Fax_LastUpdate,
		DealerCity,
		DealerState,
		Counter,
		RESUBMIT_POLICY,
		PartnerName,
		BidFundingStatus,
		StatusUpdateDateTime,
		LenderAgentName,
		BranchAgentName,
		DealerSalesPerson

FROM
	TEMP_view_LoanApps_Bids_20111102

WHERE
	DBO.DAYSAGO(BidUpdateDateTime, GETDATE()) < 30


--WHERE DBO.DAYSAGO(BidUpdateDateTime, GETDATE()) < 30 AND STATUS IN ('PENDING_LENDER') AND LenderID = 278







GO

SET QUOTED_IDENTIFIER OFF 
GO
SET ANSI_NULLS ON 
GO

