/****** Object:  View dbo.TEMP_2013_03_25_PARTNER_FIELDS    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW TEMP_2013_03_25_PARTNER_FIELDS AS
	SELECT TOP 100 PERCENT		
		Comments				= '1 AutoGen.  Partner: "' + UPPER(ISNULL(PARTNER.ShortName, '')) + '", Lender: "' + UPPER(ISNULL(LENDER.LenderName, '')) + '", Field: "' + REPLACE(DEFINITION.Field, 'Lender Enabled (CreditSmarts)',  'Enabled-L-CS') + '"',
		PartnerToolID			= PARTNER.PartnerToolID,
		LenderID				= LENDER.LenderID,
		LendersBranchID			= 0,
		Field					= DEFINITION.Field,
		DataValue				= '',
		Active					= 1, 
		LoanAppID				= 0, 
		LoanApp_BidID			= 0,
		DealerID				= 0, 
		CreateDateTime			= GETDATE(),
		UpdateDateTime			= GETDATE(),
		CreateUser				= 'system', 
		UpdateUser				= 'system', 
		rowVersion				= 1,
		SortValue				= RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), PARTNER.PartnerToolID), 8) + '_' + RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), LENDER.LenderID), 8) + '_' + RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), 0), 8) + '_' + LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(DEFINITION.FIELD), 'LENDER ENABLED (CREDITSMARTS)',  'ENABLED_LM__CS'), ' ', ''), '(', ''), ')', ''), '-', ''), 24)
	
	FROM 
							tblPartnerElementDefinition 	DEFINITION		WITH (NOLOCK) 
					JOIN	tblPartnerTools					PARTNER			WITH (NOLOCK) ON PARTNER.PartnerToolID = DEFINITION.PartnerToolID
		LEFT OUTER	JOIN	tblLenders						LENDER			WITH (NOLOCK) ON LenderStatus IN ('ACTIVE', 'TRIAL_30')
	WHERE 
			DEFINITION.ValueType		= 'ENABLED'		
		AND	DEFINITION.Active			= 1
		AND	PARTNER.Active				= 1
		AND	KeyedFromDealerID			= 0
		AND	KeyedFromLoanApp_BidID		= 0
		AND	KeyedFromLoanAppID			= 0
		AND	KeyedFromLenderID			= 1
		AND	KeyedFromLendersBranchID	= 0
		AND
			NOT EXISTS (SELECT * FROM tblPartnerDataElement DV WHERE DV.LenderID = LENDER.LenderID AND ISNULL(DV.LendersBranchID, 0) = 0)

	
	UNION ALL
	
	SELECT TOP 100 PERCENT
		Comments				= '2 AutoGen.  Partner: "' + UPPER(ISNULL(PARTNER.ShortName, '')) + '", Lender: "' + UPPER(ISNULL(LENDER.LenderName, '')) + '", Branch: "' + UPPER(ISNULL(BRANCH.BranchName, '')) + '", Field: "' + REPLACE(DEFINITION.Field, 'Lender Enabled (CreditSmarts)',  'Enabled-L-CS') + '"',
		PartnerToolID			= PARTNER.PartnerToolID,
		LenderID				= LENDER.LenderID,
		LendersBranchID			= BRANCH.LendersBranchID,
		Field					= DEFINITION.Field,
		DataValue				= '',
		Active					= 1, 
		LoanAppID				= 0, 
		LoanApp_BidID			= 0,
		DealerID				= 0, 
		CreateDateTime			= GETDATE(),
		UpdateDateTime			= GETDATE(),
		CreateUser				= 'system', 
		UpdateUser				= 'system', 
		rowVersion				= 1,
		SortValue				= RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), PARTNER.PartnerToolID), 8) + '_' + RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), LENDER.LenderID), 8) + '_' + RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), BRANCH.LendersBranchID), 8) + '_' + LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(DEFINITION.FIELD), 'LENDER ENABLED (CREDITSMARTS)',  'ENABLED_LMB_CS'), ' ', ''), '(', ''), ')', ''), '-', ''), 24)
	
	FROM 
							tblPartnerElementDefinition 	DEFINITION		WITH (NOLOCK) 
					JOIN	tblPartnerTools					PARTNER			WITH (NOLOCK) ON PARTNER.PartnerToolID = DEFINITION.PartnerToolID
		LEFT OUTER	JOIN	tblLenders						LENDER			WITH (NOLOCK) ON LenderStatus IN ('ACTIVE', 'TRIAL_30')
		LEFT OUTER	JOIN	tblLendersBranches				BRANCH			WITH (NOLOCK) ON BRANCH.LenderID = LENDER.LenderID
	WHERE 
			ValueType='ENABLED'		
		AND	DEFINITION.Active			= 1
		AND	PARTNER.Active				= 1
		AND	KeyedFromDealerID			= 0
		AND	KeyedFromLoanApp_BidID		= 0
		AND	KeyedFromLoanAppID			= 0
		AND	KeyedFromLenderID			= 1
		AND	KeyedFromLendersBranchID	= 1
		AND
			NOT EXISTS (SELECT * FROM tblPartnerDataElement DV WHERE DV.LenderID = LENDER.LenderID AND DV.LendersBranchID = BRANCH.LendersBranchID)
	
	UNION ALL
	
	SELECT TOP 100 PERCENT
		Comments				= '3 AutoGen.  Partner: "' + UPPER(ISNULL(PARTNER.ShortName, '')) + '", Lender: "' + UPPER(ISNULL(LENDER.LenderName, '')) + '", Branch: "' + UPPER(ISNULL(BRANCH.BranchName, '')) + '", Field: "' + REPLACE(DEFINITION.Field, 'Lender Enabled (CreditSmarts)',  'Enabled-L-CS') + '"',
		PartnerToolID			= PARTNER.PartnerToolID,
		LenderID				= LENDER.LenderID,
		LendersBranchID			= BRANCH.LendersBranchID,
		Field					= DEFINITION.Field,
		DataValue				= '',
		Active					= 1, 
		LoanAppID				= 0, 
		LoanApp_BidID			= 0,
		DealerID				= 0, 
		CreateDateTime			= GETDATE(),
		UpdateDateTime			= GETDATE(),
		CreateUser				= 'system', 
		UpdateUser				= 'system', 
		rowVersion				= 1,
		SortValue				= RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), PARTNER.PartnerToolID), 8) + '_' + RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), LENDER.LenderID), 8) + '_' + RIGHT(REPLICATE('0', 8) + CONVERT(VARCHAR(8), BRANCH.LendersBranchID), 8) + '_' + LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(DEFINITION.FIELD), 'LENDER ENABLED (CREDITSMARTS)',  'ENABLED_L_B_CS'), ' ', ''), '(', ''), ')', ''), '-', ''), 24)
	
	FROM 
							tblPartnerElementDefinition 	DEFINITION		WITH (NOLOCK) 
					JOIN	tblPartnerTools					PARTNER			WITH (NOLOCK) ON PARTNER.PartnerToolID = DEFINITION.PartnerToolID
		LEFT OUTER	JOIN	tblLenders						LENDER			WITH (NOLOCK) ON LenderStatus IN ('ACTIVE', 'TRIAL_30')
		LEFT OUTER	JOIN	tblLendersBranches				BRANCH			WITH (NOLOCK) ON BRANCH.LenderID = LENDER.LenderID
	WHERE 
			ValueType					= 'ENABLED'		
		AND	DEFINITION.Active			= 1
		AND	PARTNER.Active				= 1
		AND	KeyedFromDealerID			= 0
		AND	KeyedFromLoanApp_BidID		= 0
		AND	KeyedFromLoanAppID			= 0
		AND	KeyedFromLenderID			= 0
		AND	KeyedFromLendersBranchID	= 1
		AND
			NOT EXISTS (SELECT * FROM tblPartnerDataElement DV WHERE ISNULL(DV.LenderID, 0) IN (0, LENDER.LenderID) AND DV.LendersBranchID = BRANCH.LendersBranchID)
	
	ORDER BY
		SortValue




