/****** Object:  View dbo.TEMP_2016_07_20_SAL_FAX_POST    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW TEMP_2016_07_20_SAL_FAX_POST AS
SELECT
	Bids.LoanAppID, 
	LoanApp_BidID = MAX(Bids.LoanApp_BidID),
	App.Applicant_Names, 
	Dealer.DealerName, 
	DealerFax = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(Dealer.Fax, ' ',''), '-', ''), '(', ''), ')', ''), '.', ''),
	FromAddress	= 'fax@creditsmarts.com',
	ToAddress = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(Dealer.Fax, ' ',''), '-', ''), '(', ''), ')', ''), '.', '') + '@emailfaxservice.com',
	URL = 'http://www.creditsmarts.com/creditsmarts/fax/approval_notice.asp?BidID=' + CONVERT(VARCHAR(32), MAX(Bids.LoanApp_BidID))

FROM
			tblLoanApp_Bids		Bids	WITH (NOLOCK)
	JOIN	tblLendersBranches	Branch	WITH (NOLOCK) ON Branch.LendersBranchID		= Bids.LendersBranchID
	JOIN	tblLenders			Lender	WITH (NOLOCK) ON Lender.LenderID			= Branch.LenderID
	JOIN	tblLoanApps			App		WITH (NOLOCK) ON App.LoanAppID				= Bids.LoanAppID
	JOIN	tblDealers			Dealer	WITH (NOLOCK) ON Dealer.DealerID			= App.DealerID
WHERE
		Bids.UpdateDateTime >= '2016-07-20' AND 
		Bids.Status IN('PENDING_DEALER', 'DECLINE_LENDER')	AND
		Lender.LenderID = 366
GROUP BY
	Bids.LoanAppID,
	App.Applicant_Names,
	Dealer.DealerName,
	Dealer.Fax


