/****** Object:  View dbo.TEMP_BIDS_DECLINE_NO_OFFERDATE    Script Date: 7/31/2024 12:57:15 PM ******/
--DECLARE @LID INT; DECLARE @BIDS TABLE(LoanApp_BidID INT NOT NULL PRIMARY KEY); SET @LID = 1482214;
--INSERT INTO @BIDS SELECT LoanApp_BidID FROM tblLoanApp_Bids WITH (NOLOCK) WHERE Status = 'DECLINE_LENDER' AND DATEDIFF(d, UpdateDateTime, GETDATE()) < 2 AND Offer_Date IS NULL
-- LoanAppID = @LID;
CREATE VIEW TEMP_BIDS_DECLINE_NO_OFFERDATE AS
	SELECT TOP 100 PERCENT
		PartnerToolID		= Partner.PartnerToolID,
		Partner				= UPPER(LTRIM(RTRIM(Partner.ShortName))),
		PartnerLoanID_Name	= DE_LoanID.Field,
		LoanAppID			= Bids.LoanAppID,
		LoanApp_BidID		= Bids.LoanApp_BidID,
		PartnerLoanID		= DE_LoanID.DataValue,
		BidTime				= Bids.UpdateDateTime,
		OfferTime			= Bids.Offer_Date,
		SentTime			= CONVERT(DATETIME, CASE WHEN ISDATE(DE_Sent.DataValue)=1 THEN DE_Sent.DataValue ELSE NULL END),
		SentTimeID			= DE_Sent.PartnerDataElementID,
		MsgTime				= MAX(Msg.[DateTime])

	FROM
					tblLoanApp_Bids					Bids			WITH (NOLOCK)			
			 JOIN	tblPartnerDataElement			DE_LoanID		WITH (NOLOCK)	ON DE_LoanID.LoanApp_BidID		= Bids.LoanApp_BidID
			 JOIN	tblPartnerElementDefinition		DF_LoanID		WITH (NOLOCK)	ON DF_LoanID.PartnerToolID		= DE_LoanID.PartnerToolID		AND	DF_LoanID.Field	= DE_LoanID.Field		AND DF_LoanID.ValueType = 'PARTNER_LOAN_ID'
			 JOIN	tblPartnerTools					Partner			WITH (NOLOCK)	ON Partner.PartnerToolID		= DE_LoanID.PartnerToolID
		LEFT JOIN	tblLoanApp_Bids_CommentLog		Msg				WITH (NOLOCK)	ON Msg.LoanApp_BidID			= Bids.LoanApp_BidID			AND Msg.[From] = 'LENDER'
		LEFT JOIN	tblPartnerDataElement			DE_Sent			WITH (NOLOCK)	ON DE_Sent.PartnerToolID		= DE_LoanID.PartnerToolID		AND DE_Sent.LoanApp_BidID		= Bids.LoanApp_BidID			AND	DE_Sent.Field		= 'LastSentDateTime'

	WHERE 
		--Bids.LoanApp_BidID IN (SELECT LoanApp_BidID FROM @BIDS)
		
			Bids.Status = 'DECLINE_LENDER' 
		AND	DATEDIFF(d, Bids.UpdateDateTime, GETDATE()) < 2 
		AND	Bids.Offer_Date IS NULL
	GROUP BY
		Partner.PartnerToolID,
		Partner.ShortName,
		DE_LoanID.Field,
		Bids.LoanAppID,
		Bids.LoanApp_BidID,
		DE_LoanID.DataValue,
		Bids.UpdateDateTime,
		Bids.OFFER_DATE,
		DE_Sent.PartnerDataElementID,
		DE_Sent.DataValue,
		DE_Sent.DataValue


