/****** Object:  View dbo.TEMP_ERIK_EQUIFAX    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW TEMP_ERIK_EQUIFAX AS
	SELECT TOP 100 PERCENT
		BID.LoanAppID,
		LoanApp_BidID	= BID.LoanApp_BidID,
		LenderID		= LENDER.LenderID,
		DealerID		= DEALER.DealerID,
		CreditPullID	= CREDIT.CreditPullID,
		GUID			= BID.Lender_Credit_EQ,
		Lender 			= UPPER(LENDER.LenderName),
		Branch			= UPPER(BRANCH.BranchName),
		Dealer			= UPPER(DEALER.DealerName),
		Applicants		= UPPER(APP.Applicant_Names),
		CreditDate 		= CREDIT.CreateDateTime,
		URL 			= 'http://cheetah:81/CreditSmarts/Credit/Show_Credit.ASP?ID=%7B' + REPLACE(CONVERT(VARCHAR(64), GUID), '-', '%2D') + '%7D&Sudo_LenderID=' + LTRIM(RTRIM(STR(LENDER.LenderID)))
	
	FROM
	
						tblLoanApp_Bids		BID 		WITH (NOLOCK)
	
		INNER JOIN		tblLendersBranches	BRANCH		WITH (NOLOCK)
			ON BRANCH.LendersBranchID = BID.LendersBranchID
	
		INNER JOIN		tblLoanApps			APP			WITH (NOLOCK)
			ON APP.LoanAppID = BID.LoanAppID
	
		INNER JOIN		tblLenders			LENDER		WITH (NOLOCK)
			ON BRANCH.LenderID = LENDER.LenderID
	
		INNER JOIN		tblDealers			DEALER		WITH (NOLOCK)
			ON DEALER.DealerID = APP.DealerID
	
		INNER JOIN		tblCreditPulls		CREDIT		WITH (NOLOCK)
			ON CONVERT(UNIQUEIDENTIFIER, BID.Lender_Credit_EQ) = CREDIT.GUID
	
	WHERE
				LEN(ISNULL(BID.Lender_Credit_EQ, '')) > 0
		AND		BID.CreateDateTime > '2011-06-01'




