/****** Object:  View dbo.TEMP_ERIK_PDE_SCORE_Inner    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW TEMP_ERIK_PDE_SCORE_Inner AS
	SELECT
		[PartnerDataElementID]	= [PDE].[PartnerDataElementID],
		[PartnerToolID]					= ISNULL( [PDE].[PartnerToolID],		0),
		[LoanAppID]							= ISNULL( [App].[LoanAppID],				0),
		[LoanApp_BidID]					= ISNULL( [Bid].[LoanApp_BidID],		0),
		[LenderID]							= ISNULL( ISNULL([Lender].[LenderID], [Branch].[LenderID]),					0),
		[LendersBranchID]				= ISNULL( [Branch].[LendersBranchID],																0),
		[DealerID]							= ISNULL( ISNULL(NULLIF([PDE].[DealerID], 0), [App].[DealerID]), 		0),
		[Field]									= [PDE].[Field],
		[Value]									= [PDE].[DataValue],
		[Score]									= CASE WHEN [PDE].[LoanApp_BidID] <> 0 THEN 90 WHEN [PDE].[LoanAppID] <> 0 THEN 30 ELSE 0 END + CASE WHEN [PDE].[LendersBranchID] <> 0 THEN 50 WHEN [PDE].[LenderID] <> 0 THEN 20 ELSE 0 END + CASE WHEN [PDE].[DealerID] <> 0 THEN 10 ELSE 0 END + CASE WHEN [PDE].[PartnerToolID] <> 0 THEN 5 ELSE 0 END,
		[Created]								= [PDE].[CreateDateTime],
		[Updated]								= [PDE].[UpdateDateTime],
		[rowVersion]						= [PDE].[rowVersion]
	FROM
							[tblPartnerDataElement]		[PDE]			WITH (NOLOCK)
		LEFT JOIN	[tblLoanApp_Bids]					[Bid]			WITH (NOLOCK) ON [Bid].[LoanApp_BidID]				= NULLIF([PDE].[LoanApp_BidID],						0)
		LEFT JOIN	[tblLoanApps]							[App]			WITH (NOLOCK) ON [App].[LoanAppID]						= ISNULL(NULLIF([PDE].[LoanAppID],				0), [Bid].[LoanAppID]				)
		LEFT JOIN	[tblLendersBranches]			[Branch]	WITH (NOLOCK) ON [Branch].[LendersBranchID]		= ISNULL(NULLIF([PDE].[LendersBranchID],	0), [Bid].[LendersBranchID]	)
		LEFT JOIN	[tblLenders]							[Lender]	WITH (NOLOCK) ON [Lender].[LenderID]					= ISNULL(NULLIF([PDE].[LenderID],					0), [Branch].[LenderID]			)


GO

