/****** Object:  View dbo.TEMP_ERIK_PDE_SCORE_Outer    Script Date: 7/31/2024 12:57:15 PM ******/
--SET ROWCOUNT 200;

CREATE VIEW TEMP_ERIK_PDE_SCORE_Outer AS
	SELECT
		[PartnerDataElementID]	= MAX([PartnerDataElementID]),
		[PartnerToolID],
		[LoanApp_BidID],
		[LoanAppID]				= MIN([LoanAppID]),
		[LendersBranchID]	= MIN([LendersBranchID]),
		[LenderID]				= MIN([LenderID]),
		[DealerID]				= MIN([DealerID]),
		[Field],
		[Score],
		[C] = (SELECT COUNT(*) FROM TEMP_ERIK_PDE_SCORE_Inner [B2] WITH (NOLOCK) WHERE
						[B2].[PartnerToolID]		= [B].[PartnerToolID]
				AND	[B2].[LoanApp_BidID]		= [B].[LoanApp_BidID]),
		[S] = (SELECT MAX([Score]) FROM TEMP_ERIK_PDE_SCORE_Inner [B2] WITH (NOLOCK) WHERE
						[B2].[PartnerToolID]		= [B].[PartnerToolID]
				AND	[B2].[LoanApp_BidID]		= [B].[LoanApp_BidID])

/*
		[HiScore] = (SELECT MAX([Score]) FROM TEMP_ERIK_PDE_SCORE_Inner [B2] WITH (NOLOCK) WHERE
						[B2].[PartnerToolID]		= [B].[PartnerToolID]
				AND	[B2].[LoanApp_BidID]		= [B].[LoanApp_BidID]
				AND	[B2].[Field]						= [B].[Field])
*/

/*				AND	[B2].[LoanAppID]				= [B].[LoanAppID]
				AND	[B2].[LendersBranchID]	= [B].[LendersBranchID]
				AND	[B2].[LenderID]					= [B].[LenderID]
				AND	[B2].[DealerID]					= [B].[DealerID]
				)*/
	FROM
		TEMP_ERIK_PDE_SCORE_Inner [B] WITH (NOLOCK)
	GROUP BY
		[PartnerToolID],
		[LoanApp_BidID],
		-- [LoanAppID], [LenderID], [LendersBranchID], [DealerID],
		[Field],
		[Score]

