/****** Object:  View dbo.TEMP_ERIK_viewR1_MultipleBids_Inner    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW TEMP_ERIK_viewR1_MultipleBids_Inner AS
SELECT TOP 100 PERCENT
	ApplicationDate	= APP.UpdateDateTime,
	LoanAppID		= PDE.LoanAppID,
	Applicants		= APP.APPLICANT_NAMES,
	DealerID		= Dealer.DealerID,
	Dealer			= UPPER(DEALER.DEALERNAME),
	DealerLocation	= UPPER(DEALER.CITY) + ', ' + UPPER(DEALER.STATE),	
	Vehicle			= LTRIM(RTRIM(STR(APP.VEHICLE_YEAR))) + ' ' + APP.VEHICLE_MAKE + ' ' + APP.VEHICLE_MODEL,
	Bids			= COUNT(BID.LoanApp_BidID)
FROM
			tblpartnerdataelement 	PDE		WITH (NOLOCK)
	JOIN	tblLoanApp_Bids			BID		WITH (NOLOCK) ON PDE.LoanAppID = BID.LoanAppID
	JOIN	tblLoanApps				APP		WITH (NOLOCK) ON APP.LoanAppID = BID.LoanAppID	
	JOIN	tblDealers				DEALER	WITH (NOLOCK)		ON DEALER.DealerID = APP.DealerID
WHERE
	PDE.PartnerToolID = 12 and PDE.LoanAppID > 0
	AND (NOT DEALER.DealerID IN(7312, 1))
	AND (NOT BID.STATUS IN ('PENDING_LENDER'))
GROUP BY
	APP.UpdateDateTime,
	PDE.LoanAppID,
	APP.APPLICANT_NAMES,
	DEALER.DealerID,
	DEALER.DealerName,
	DEALER.City,
	DEALER.State,
	APP.VEHICLE_YEAR,
	APP.VEHICLE_MAKE,
	APP.VEHICLE_MODEL
HAVING 	
	COUNT(BID.LoanApp_BidID) > 1
ORDER BY
	APP.UpdateDateTime DESC





