/****** Object:  View dbo.TEMP_LCPW    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW TEMP_LCPW AS
SELECT TOP 100 PERCENT * FROM
(SELECT
  LENDER.LenderID,
  BRANCH.LendersBranchID,
  Microbilt_Login = CASE
    WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN BRANCH.Microbilt_Login
    ELSE LENDER.MicroBilt_Login
  END,
  Microbilt_Password = CASE
    WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN BRANCH.Microbilt_Password
    ELSE LENDER.MicroBilt_Password
  END
FROM
  tblLenders LENDER
    JOIN tblLendersBranches BRANCH ON (LENDER.LenderID=BRANCH.LenderID)
) X
WHERE
  LEN(ISNULL(Microbilt_Login, '')) > 0
ORDER BY
  LenderID, LendersBranchID





