/****** Object:  View dbo.TEMP_PDE_TRIM    Script Date: 7/31/2024 12:57:15 PM ******/
--BEGIN
 /* horiz vert bcp csv html meta pretty none */

CREATE VIEW TEMP_PDE_TRIM AS
	SELECT
		/* TOP 100 PERCENT */
			[PDE].[PartnerDataElementID],
			[PDE].[PartnerToolID],
			[PDE].[Field],
			[PDE].[DataValue],
			[PDE].[UpdateDateTime],

/*
	[PDE].[LoanAppID]				= 0	AND
	[PDE].[LoanApp_BidID]		= 0	AND
	[PDE].[LenderID]				= 0	AND
	[PDE].[LendersBranchID]	= 0	AND
	[PDE].[DealerID]				= 0	AND
*/

			[Keep_Reason]	= CASE
				WHEN [PDE].[CreateDateTime]		>=	DATEADD(m, -36, GETDATE())	THEN 'Created <36mo'
				WHEN [PDE].[UpdateDateTime]		>=	DATEADD(m, -36, GETDATE())	THEN 'Updated <36mo'
				WHEN  [PDE].[LoanAppID]  =  0  AND  [PDE].[LoanApp_BidID]  =  0  AND  [PDE].[LenderID]  =  0  AND  [PDE].[LendersBranchID]  =  0  AND  [PDE].[DealerID]  =  0 THEN 'Global'
				ELSE NULL END,
			[Purge_Reason] = CASE
				WHEN [PDE].[PartnerToolID]		>	0	AND	NOT	EXISTS	(SELECT * FROM [tblPartnerTools]		[Target]	WITH (NOLOCK)	WHERE	[Target].[PartnerToolID]		= [PDE].[PartnerToolID]			) THEN	'Bad PartnerToolID'
				WHEN [PDE].[LoanAppID]				> 0	AND	NOT	EXISTS	(SELECT * FROM [tblLoanApps]				[Target]	WITH (NOLOCK)	WHERE	[Target].[LoanAppID]				= [PDE].[LoanAppID]					) THEN 'Bad LoanApp'
				WHEN [PDE].[LoanApp_BidID]		> 0	AND	NOT	EXISTS	(SELECT * FROM [tblLoanApp_Bids]		[Target]	WITH (NOLOCK)	WHERE	[Target].[LoanApp_BidID]		= [PDE].[LoanApp_BidID]			)	THEN 'Bad LoanApp_BidID'
				WHEN [PDE].[LenderID]					> 0	AND	NOT	EXISTS	(SELECT * FROM [tblLenders]					[Target]	WITH (NOLOCK)	WHERE	[Target].[LenderID]					= [PDE].[LenderID]					)	THEN 'Bad Lender'
				WHEN [PDE].[LendersBranchID]	> 0	AND	NOT	EXISTS	(SELECT * FROM [tblLendersBranches]	[Target]	WITH (NOLOCK)	WHERE	[Target].[LendersBranchID]	= [PDE].[LendersBranchID]		)	THEN 'Bad LendersBranchID'
				WHEN [PDE].[DealerID]					> 0	AND	NOT	EXISTS	(SELECT * FROM [tblDealers]					[Target]	WITH (NOLOCK)	WHERE	[Target].[DealerID]					= [PDE].[DealerID]					)	THEN 'Bad DealerID'
				ELSE NULL END
	FROM
		[tblPartnerDataElement]	[PDE]		WITH (NOLOCK)
	WHERE
		[PDE].[CreateDateTime]	< DATEADD(m, -12, GETDATE())
/* 	ORDER BY
		[PDE].[PartnerDataElementID]
 */

 /* horiz vert bcp csv html meta pretty none */

--END


