/****** Object:  View dbo.TEMP_SAL_FAX    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW TEMP_SAL_FAX AS

SELECT TOP 100 PERCENT
	APP.LoanAppID,
	BID.LoanApp_BidID,
	BID.LendersBranchID,
	BID.LenderID,
	DEALER.DealerID,
	FAX = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(DEALER.Fax, '(', ''), ')', ''), '-', ''), '.', ''), ' ', ''),
	BID.Status

FROM
	tblloanapp_bids BID WITH (nolock)
	JOIN tblLendersBranches BRANCH ON (BID.LendersBranchID = BRANCH.LendersBranchID AND BRANCH.LenderID=366)
	JOIN tblLoanAppS APP WITH (NOLOCK) ON (BID.LoanAppID = APP.LoanAppID)
	JOIN tblDealers DEALER WITH (NOLOCK) ON (DEALER.DealerID = APP.DealerID)
WHERE
	NOT BID.Status IN ('PENDING_LENDER')
ORDER BY
	BID.LoanApp_BidID DESC




