/****** Object:  View dbo.TEMP_viewB2B_DataElementsToFill    Script Date: 7/31/2024 12:57:15 PM ******/


/*
DECLARE @_PARTNER_ID INT; SET @_PARTNER_ID = 12;
DECLARE @_HOURS_TO_CHECK INT; SET @_HOURS_TO_CHECK = 96;
*/

/*
SELECT * FROM
	tblPartnerDataElement VALUE WHERE VALUE.LoanApp_BidID IN
		(SELECT LoanApp_BidID FROM tblLoanApp_Bids B WHERE B.LoanAppID = VALUE.LoanAppID)
*/

/*
SELECT * FROM tblLoanApp_Bids WHERE LoanAppID IN(859044) OR LoanApp_BidID IN(648671, 648671, 648618)
SELECT * FROM tblPartnerDataElement WHERE LoanAppID IN(859044) OR LoanApp_BidID IN(648671, 648671, 648618)
*/


--SET NOCOUNT ON;


--LoanAppID   LoanApp_BidID Status                         Elements    OuterElements MinElement  MinElementElements MaxElement  MaxElementElements 




CREATE VIEW TEMP_viewB2B_DataElementsToFill AS
	SELECT TOP 100 PERCENT
		BID.LoanAppID,
		BID.LoanApp_BidID,
		BID.Status,
		PartnerToolID = (SELECT TOP 1 PartnerToolID FROM tblPartnerDataElement Value WITH (NOLOCK) WHERE Value.LoanApp_BidID = BID.LoanApp_BidID),

		Elements = (SELECT COUNT(*) FROM tblPartnerDataElement Value With (NOLOCK) WHERE Value.LoanApp_BidID = BID.LoanApp_BidID),
	
		OuterElements = (
			SELECT COUNT(*) FROM tblPartnerDataElement Value With (NOLOCK) WHERE Value.LoanApp_BidID IN		
				(SELECT LoanApp_BidID FROM tblLoanApp_Bids BidsInner WITH (NOLOCK) WHERE BidsInner.LoanAppID = BID.LoanAppID)
			),
	
		MinElement = (
			SELECT Min(Value.LoanApp_BidID) FROM tblPartnerDataElement Value With (NOLOCK) WHERE Value.LoanApp_BidID IN		
				(SELECT LoanApp_BidID FROM tblLoanApp_Bids BidsInner WITH (NOLOCK) WHERE BidsInner.LoanAppID = BID.LoanAppID)
			),
	
		MinElementElements = (
			SELECT COUNT(*) FROM tblPartnerDataElement Value With (NOLOCK) WHERE Value.LoanApp_BidID IN	(
				SELECT Min(Value.LoanApp_BidID) FROM tblPartnerDataElement Value With (NOLOCK) WHERE Value.LoanApp_BidID IN		
					(SELECT LoanApp_BidID FROM tblLoanApp_Bids BidsInner WITH (NOLOCK) WHERE BidsInner.LoanAppID = BID.LoanAppID)
			)
		),
	
	
		MaxElement = (
			SELECT Max(Value.LoanApp_BidID) FROM tblPartnerDataElement Value With (NOLOCK) WHERE Value.LoanApp_BidID IN		
				(SELECT LoanApp_BidID FROM tblLoanApp_Bids BidsInner WITH (NOLOCK) WHERE BidsInner.LoanAppID = BID.LoanAppID)
			),
	
	
		MaxElementElements = (
			SELECT COUNT(*) FROM tblPartnerDataElement Value With (NOLOCK) WHERE Value.LoanApp_BidID IN	(
				SELECT Max(Value.LoanApp_BidID) FROM tblPartnerDataElement Value With (NOLOCK) WHERE Value.LoanApp_BidID IN		
					(SELECT LoanApp_BidID FROM tblLoanApp_Bids BidsInner WITH (NOLOCK) WHERE BidsInner.LoanAppID = BID.LoanAppID)
			)
		)
	FROM
		tblLoanApp_Bids BID
	WHERE
		BID.STATUS IN ('DECLINE_LENDER', 'PENDING_DEALER', 'DECLINE_DEALER')
		AND LoanAppID IN(
			SELECT 
				DISTINCT InnerBid.LoanAppID		
			FROM 
						tblPartnerDataElement	InnerValue		WITH (NOLOCK)
				JOIN	tblLoanApp_Bids			InnerBid		WITH (NOLOCK)	ON InnerBid.LoanApp_BidID = InnerValue.LoanApp_BidID
			WHERE
					InnerBid.CreateDateTime		> DATEADD(hh, -24, GETDATE())
				--AND	InnerValue.PartnerToolID	= @_PARTNER_ID
		)
		AND LoanApp_BidID NOT IN(SELECT LoanApp_BidID FROM tblPartnerDataElement WITH (NOLOCK))
	
	ORDER BY
		BID.LoanAppID,
		BID.LoanApp_BidID





