/****** Object:  View dbo.TEMP_viewCreditTesting_2020_04_27    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW TEMP_viewCreditTesting_2020_04_27 AS
	SELECT TOP 100 PERCENT
		LoanAppID				= App.LoanAppID, 
		LoanApp_BidID			= MIN(Bid.LoanApp_BidID),
		LendersBranchID			= MIN(Branch.LendersBranchID),
		LenderID				= Lender.LenderID, 
		CreditReportAccount		= MIN(UPPER(CASE
			WHEN LEN(ISNULL(Branch.Microbilt_Login, '')) > 0 AND LEN(ISNULL(Branch.Microbilt_Password, '')) > 0 THEN CONVERT(BIT, 1)
			WHEN LEN(ISNULL(Lender.Microbilt_Login, '')) > 0 AND LEN(ISNULL(Lender.Microbilt_Password, '')) > 0 THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0) END)),
		CreditReportAccountSource = MIN(UPPER(CASE
			WHEN LEN(ISNULL(Branch.Microbilt_Login, '')) > 0 AND LEN(ISNULL(Branch.Microbilt_Password, '')) > 0 THEN 'Lender_Branch'
			WHEN LEN(ISNULL(Lender.Microbilt_Login, '')) > 0 AND LEN(ISNULL(Lender.Microbilt_Password, '')) > 0 THEN 'Lender_MASTER'
			ELSE 'NONE' END)),
		CreditReportUserName = MIN(UPPER(CASE
			WHEN LEN(ISNULL(Branch.Microbilt_Login, '')) > 0 AND LEN(ISNULL(Branch.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(Branch.MicroBilt_Login))
			WHEN LEN(ISNULL(Lender.Microbilt_Login, '')) > 0 AND LEN(ISNULL(Lender.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(Lender.MicroBilt_Login))
			ELSE '' END)),
		CreditReportPassword = MIN(UPPER(CASE
			WHEN LEN(ISNULL(Branch.Microbilt_Login, '')) > 0 AND LEN(ISNULL(Branch.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(Branch.MicroBilt_Password))
			WHEN LEN(ISNULL(Lender.Microbilt_Login, '')) > 0 AND LEN(ISNULL(Lender.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(Lender.MicroBilt_Password))
			ELSE '' END)),
		Automation_Bureau = MIN(CASE
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_EX, '')) = 38 THEN 'EX'
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_TU, '')) = 38 THEN 'TU'
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_EQ, '')) = 38 THEN 'EQ' END),
		Existing_Bureau = MIN(CASE
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_EX, '')) = 38 THEN Bid.Lender_CREDIT_EX
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_TU, '')) = 38 THEN Bid.Lender_CREDIT_TU
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_EQ, '')) = 38 THEN Bid.Lender_CREDIT_EQ ELSE '' END),
		Has_Existing_Bureau = CONVERT(BIT, CASE
			WHEN NULlif(Lender.AUTOMATION_CREDIT_PROVIDER, '') IS NULL THEN 0
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_EX, ''))	= 38 THEN 1
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_TU, ''))	= 38 THEN 1
			WHEN LEN(ISNULL(Bid.Lender_CREDIT_EQ, ''))	= 38 THEN 1
			ELSE 0 END),
		CreditPullID_EQ		= MAX(ISNULL(credit_eq.CreditPullID, 0)),
		CreditPullID_EX		= MAX(ISNULL(Credit_EX.CreditPullID, 0)),
		CreditPullID_TU		= MAX(ISNULL(Credit_TU.CreditPullID, 0)),
		Age					= DATEDIFF(s, Bid.UpdateDateTime,	GETDATE()),
		BidSubmit			= DATEDIFF(d, Bid.Submit_Date,		GETDATE()),
		BidOffer			= DATEDIFF(d, Bid.Offer_Date,		GETDATE())
	FROM
						tblLoanApp_Bids			Bid			WITH (NOLOCK)
				JOIN tblLoanApps				App			WITH (NOLOCK) ON Bid.LoanAppID				= App.LoanAppID
				JOIN tblDealers					Dealer		WITH (NOLOCK) ON Dealer.DealerID			= App.DealerID
				JOIN tblLendersBranches			Branch		WITH (NOLOCK) ON Branch.LendersBranchID		= Bid.LendersBranchID
				JOIN tblLenders					Lender		WITH (NOLOCK) ON Branch.LenderID			= Lender.LenderID
		LEFT	JOIN tblCreditPulls				CREDIT_EX	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(Bid.Lender_Credit_EX, '')) = 1	/*AND	ISNULL(Credit_EX.Bureau, '') IN('EX', '')	AND	*/ ANd Credit_EX.GUID				= NULLIF(Bid.Lender_Credit_EX, '')
		LEFT	JOIN tblCreditPulls				CREDIT_TU	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(Bid.Lender_Credit_TU, '')) = 1	/*AND	ISNULL(Credit_TU.Bureau, '') IN('TU', '')	AND	*/ aND Credit_TU.GUID				= NULLIF(Bid.Lender_Credit_TU, '')
		LEFT	JOIN tblCreditPulls				CREDIT_EQ	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(Bid.Lender_Credit_EQ, '')) = 1	/*AND	ISNULL(Credit_EQ.Bureau, '') IN('EQ', '')	AND	*/ AnD Credit_EQ.GUID				= NULLIF(Bid.Lender_Credit_EQ, '')
	WHERE
		Bid.CreateDateTime >= CONVERT(DATETIME, CONVERT(VARCHAR(60), GETDATE(), 102)) 
		--AND DATEADD(mi, -120, GETDATE())
		--AND Bid.UpdateDateTime < DATEADD(mi, -120, GETDATE())
		AND (Credit_EX.CreditPullID IS NOT NULL OR Credit_EQ.CreditPullID IS NOT NULL OR Credit_TU.CreditPullID IS NOT NULL)
		AND Lender.LenderID <> 1224
	GROUP BY 
		App.LoanAppID,
		Lender.LenderID,
		Bid.UpdateDateTime,
		Bid.Submit_Date,
		Bid.Offer_Date,
		Bid.Offered_By,
		Lender.Automation_Credit_Provider,
		Bid.Lender_Credit_EX,
		Bid.Lender_Credit_EQ,
		Bid.Lender_Credit_TU,
		Credit_EX.Bureau,
		Credit_TU.Bureau,
		Credit_EQ.Bureau
	ORDER BY
		App.LoanAppID,
		Lender.LenderID

GO

