/****** Object:  View dbo.TEMP_viewSocials    Script Date: 7/31/2024 12:57:15 PM ******/


-- MILLARD

--SELECT applicant_names, * FROM tblLoanApps where applicant_names like '%millard%';



--SELECT TOP 5 * FROM tblLoanApp_Applicant;

CREATE VIEW TEMP_viewSocials as

SELECT TOP 100 PERCENT

APPLICATION.LoanAppID,

Date = APPLICATION.CreateDateTime,

HasBureau = CASE WHEN
	LEN(
LTRIM(RTRIM(ISNULL(DEALER_CREDIT_EX, ''))) +
LTRIM(RTRIM(ISNULL(DEALER_CREDIT_TU, ''))) +
LTRIM(RTRIM(ISNULL(DEALER_CREDIT_EQ, '')))) > 0 THEN 'Yes'
ELSE 'No'
END,

Name =
LTRIM(RTRIM(REPLACE(REPLACE( UPPER(LEFT(LAST_NAME, 1)) + LOWER(SUBSTRING(LAST_NAME, 2, 999)) + ', ' + UPPER(LEFT(FIRST_NAME, 1)) + LOWER(SUBSTRING(FIRST_NAME, 2, 999))
, ' de ', ' De '), ' la ', ' La '))),


SSN =
	RIGHT('000' + LTRIM(STR(SSN_1 ) ), 3) + '-'  +
	RIGHT('00' + LTRIM(STR(SSN_2 ) ), 2) + '-'  +
	RIGHT('0000' + LTRIM(STR(SSN_3 ) ), 4),

Dealer = RTRIM(LTRIM(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(LEFT(DealerName, 1)) + LOWER(SUBSTRING(DealerName, 2, 999)), '™', ''),
' - consumer direct vehicle refinance', ''), 'Lendingtree', 'LendingTree'), '  ', ' '))),

DealerLocation = UPPER(LEFT(DEALER.City, 1)) + LOWER(SUBSTRING(DEALER.City, 2, 999)) + ', ' + UPPER(Dealer.State),

DealerPhone = '(' + LEFT(REPLACE(REPLACE(REPLACE(REPLACE(DEALER.TelePhone, '-', ''), '(', ''), ')', ''), ' ', ''), 3) + ') ' + SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(DEALER.TelePhone, '-', ''), '(', ''), ')', ''), ' ', ''), 4, 3) + '-' + SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(DEALER.TelePhone, '-', ''), '(', ''), ')', ''), ' ', ''), 7, 4),


SSN_P1 = RIGHT('000' + LTRIM(STR(SSN_1 ) ), 3),
SSN_P2 =	RIGHT('00' + LTRIM(STR(SSN_2 ) ), 2),
SSN_P3 = RIGHT('0000' + LTRIM(STR(SSN_3 ) ), 4)


FROM
			tblLoanApp_Applicant	APPLICANT		WITH (NOLOCK)
	JOIN	tblLoanApps				APPLICATION		WITH (NOLOCK)	ON (APPLICANT.LoanAppID = APPLICATION.DealerID)
	JOIN	tblDealers				DEALER			WITH (NOLOCK)	ON (APPLICATION.DealerID = DEALER.DealerID)

WHERE
	APPLICATION.CreateDateTime > '2012-06-01'
ORDER BY APPLICATION.LoanAppID DESC





