/****** Object:  View dbo.Temp_View_PeakSubmits    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW Temp_View_PeakSubmits AS
SELECT DISTINCT TOP 100 PERCENT
    APP.DealerID,
    APP.LoanAppID,
    Credit_GUID = CASE
      WHEN LEN(ISNULL(Dealer_Credit_EX, '')) > 0 THEN  Dealer_Credit_EX
      WHEN LEN(ISNULL(Dealer_Credit_TU, '')) > 0 THEN  Dealer_Credit_TU
      WHEN LEN(ISNULL(Dealer_Credit_EQ, '')) > 0 THEN  Dealer_Credit_EQ
    END
FROM
  tblLoanApp_Bids BID
  JOIN tblLoanApps APP ON(BID.LoanAppID=APP.LoanAppID)
    WHERE
      LendersBranchID IN (SELECT LendersBranchID FROM tblLendersBranches WHERE LenderID IN (SELECT LenderID FROM tblLenders WHERE LenderName LIKE 'PEAK%'))
      AND
      (LEN(ISNULL(Dealer_Credit_EX, '')) > 0 OR LEN(ISNULL(Dealer_Credit_TU, '')) > 0 OR LEN(ISNULL(Dealer_Credit_EQ, '')) > 0)
ORDER BY
  APP.LoanAppID





