/****** Object:  View dbo.__TEMP_ERIK_2019_09_12    Script Date: 7/31/2024 12:57:15 PM ******/
--DECLARE @_BidID INTEGER; SET @_BidID = 1496186;

/*
	SELECT 
		DATEDIFF(dd, Bid.CreateDateTime, GETDATE()),
		* 
	FROM
				tblLoanApp_Bids		Bid		WITH (NOLOCK)
		JOIN	tblLendersBranches	Branch	WITH (NOLOCK) ON	Branch.LendersBranchID		= Bid.LendersBranchID
		JOIN	tblLenders			Lender	WITH (NOLOCK) ON	Lender.LenderID				= Branch.LenderID
	WHERE 
		Bid.LoanApp_BidID = @_BidID;
*/

CREATE  VIEW __TEMP_ERIK_2019_09_12 AS
	SELECT TOP 100 PERCENT
		ApplicationID	= CONVERT(VARCHAR(32), Bid.LoanAppID) + '-' + CONVERT(VARCHAR(32), Bid.LoanApp_BidID),
		LoanAppID		= Bid.LoanAppID,
		LoanApp_BidID	= Bid.LoanApp_BidID,
		Created			= Bid.CreateDateTime,
		LenderID		= Lender.LenderID,
		LendersBranchID	= Branch.LendersBranchID,
		LenderCode		= ISNULL(NULLIF(Lender.LoginPrefix, ''), 'Test'),
		BranchCode		= ISNULL(NULLIF(Branch.LoginPrefix, ''), 'TestBranch'),
		Lender			= Lender.LenderName,
		EX				= CONVERT(UNIQUEIDENTIFIER, NULLIF(Bid.Lender_Credit_EX, '')),
		EQ				= CONVERT(UNIQUEIDENTIFIER, NULLIF(Bid.Lender_Credit_EQ, '')),
		TU				= CONVERT(UNIQUEIDENTIFIER, NULLIF(Bid.Lender_Credit_TU, '')),
		HasEX			= CONVERT(BIT, CASE WHEN NULLIF(Bid.Lender_Credit_EX, '') IS NOT NULL THEN 1 ELSE 0 END),
		HasEQ			= CONVERT(BIT, CASE WHEN NULLIF(Bid.Lender_Credit_EQ, '') IS NOT NULL THEN 1 ELSE 0 END),
		HasTU			= CONVERT(BIT, CASE WHEN NULLIF(Bid.Lender_Credit_TU, '') IS NOT NULL THEN 1 ELSE 0 END)
	FROM
				tblLoanApp_Bids		Bid		WITH (NOLOCK)
		JOIN	tblLendersBranches	Branch	WITH (NOLOCK) ON	Branch.LendersBranchID		= Bid.LendersBranchID
		JOIN	tblLenders			Lender	WITH (NOLOCK) ON	Lender.LenderID				= Branch.LenderID
	WHERE
		DATEDIFF(dd, Bid.CreateDateTime, GETDATE())		<= 360		AND
		(		NULLIF(Bid.Lender_Credit_EX, '')	IS NOT NULL
			OR	NULLIF(Bid.Lender_Credit_EQ, '')	IS NOT NULL
			OR	NULLIF(Bid.Lender_Credit_TU, '')	IS NOT NULL	)

	--AND Bid.LoanApp_BidID = @_BidID

	ORDER BY
		Bid.LoanAppID DESC,
		Bid.LoanApp_BidID
--	OPTION (MAXDOP 1)


