/****** Object:  View dbo._temp_vins_    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW _temp_vins_ as
	SELECT TOP 1000
		VIN			= CONVERT(VARCHAR(17),	UPPER(REPLACE(ISNULL(Apps.Vehicle_Vin, ''), ' ', ''))),
		[Year]		= Vehicle_Year,
		Make		= CONVERT(VARCHAR(30),	DBO.ProperCase(IsNull(Apps.Vehicle_Make,		''))),
		Model		= CONVERT(VARCHAR(30),	DBO.ProperCase(IsNull(Apps.Vehicle_Model,		'')))

/*
		Vehicle		= CONVERT(VARCHAR(4), VEHICLE_YEAR) + ' ' + DBO.ProperCase(VEHICLE_MAKE + ' ' + VEHICLE_MODEL),
		Mileage		= Apps.Vehicle_Mileage,
		Type		= CONVERT(VARCHAR(20),	DBO.ProperCase(IsNull(Apps.Vehicle_Type,		''))),
		New_Used	= CASE ISNULL(Apps.New_Used, '') WHEN 'NEW' THEN 'New' ELSE 'Used' END,
		Created		= CreateDateTime
*/
	FROM 
		tblLoanApps apps WITH (NOLOCK)
	WHERE 
			Vehicle_VIN				IS			NOT NULL
		AND	Vehicle_Make			IS			NOT NULL
		AND Vehicle_Model			IS			NOT NULL
		AND Vehicle_Year			IS			NOT NULL
		AND	LEN(Vehicle_VIN)		=			17
		AND	LEN(Vehicle_Make)		>			 1
		AND LEN(Vehicle_Model)		>			 1
		AND Vehicle_Year			BETWEEN		1900 AND 2050	
	ORDER BY 		LoanAppID DESC









