/****** Object:  View dbo.activeNonFaxLenderBranches    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW activeNonFaxLenderBranches AS
	SELECT TOP 100 PERCENT
		Lender.LenderID,
		Branch.LendersBranchID,
		LenderStatus		= MIN(Lender.LenderStatus),
		LenderName			= MIN(Lender.LenderName),
		BranchName			= MIN(Branch.BranchName)
	FROM
					tblLenders				Lender			WITH (NOLOCK)
		INNER JOIN	tblLendersBranches		Branch			WITH (NOLOCK)	ON	Branch.LenderID		= Lender.LenderID
	WHERE
		Lender.LenderStatus NOT IN ('INACTIVE', 'FAX')

	GROUP BY
		Lender.LenderID,
		Branch.LendersBranchID
	ORDER BY
		Lender.LenderID,
		Branch.LendersBranchID


