-- ---------------------------------------------------------------------------


-- * 4 of 64    sync_phpbb_user_lenderBranch   ID: 16055143

-- *******************************************************************

CREATE VIEW sync_phpbb_user_lenderBranch
  AS

  SELECT TOP 100 PERCENT
    NULL                                    DealerID              ,
    D.LenderID                              LenderID              ,
    D.LendersBranchID                       LendersBranchID       ,
    NULL                                    AdminLoginID          ,
    D.LendersBranchID + 2000000             user_id               ,
    1                                       user_active           ,
    1                                       user_viewemail        ,
    0                                       user_regdate          ,

    '<B>' + D.LenderName + '</B><BR>' +
    D.BranchName + '<BR>' +
    D.City + ', ' + D.State + '<BR>' +
    D.Telephone                             user_sig              ,

    1                                       user_attachsig        ,
    1                                       user_popup_pm         ,
    D.LenderName + ' - ' + D.BranchName     username              ,
    UPPER(D.Password)                       user_password         ,
    UPPER(D.CITY + ', ' + D.STATE)          user_from             ,
    LOWER(D.EMail)                          user_email            ,
    ''                                      user_website          ,
    Z.TZ                                    user_timezone         ,
    0                                       user_level            ,
    4                                       user_rank

FROM
  viewLenderBranchLogins D LEFT OUTER JOIN
    tblUniqueZips Z ON D.ZIP = Z.ZipCode

WHERE
  (D.LendersBranchLoginID IN
    (SELECT     MIN(LendersBranchLoginID)
     FROM       tblLendersBranchLogins
     WHERE      LendersBranchID = D.LendersBranchID))

ORDER BY
  D.LendersBranchID









