/****** Object:  View dbo.temp_erik_dealerActivity    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW temp_erik_dealerActivity AS

SELECT TOP 100 PERCENT
	Dealer = UPPER(DealerName),
	City = UPPER(City),
	State = Dealer.State,
	Applications = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID),
	Applications_Last_30 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30),
	Applications_Last_60 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=60),
	Applications_Last_90 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=90),
	Applications_Last_Year = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=365),
	RealApps = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND VALIDATION_STATUS='VALID'),
	RealApps_Last_30 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND VALIDATION_STATUS='VALID' AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30),
	RealApps_Last_60 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND VALIDATION_STATUS='VALID' AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30),
	RealApps_Last_90 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND VALIDATION_STATUS='VALID' AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30),
	RealApps_Last_Year = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND VALIDATION_STATUS='VALID' AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30),
	CreditOnly = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND STATUS='CREDIT'),
	CreditOnly_Last_30 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND STATUS='CREDIT' AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30),
	CreditOnly_Last_60 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND STATUS='CREDIT' AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30),
	CreditOnly_Last_90 = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND STATUS='CREDIT' AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30),
	CreditOnly_Last_Year = (SELECT COUNT(*) FROM tblLoanApps APPS WITH (NOLOCK) WHERE APPS.DealerID = DEALER.DealerID AND STATUS='CREDIT' AND DATEDIFF(dd, APPS.CreateDateTime, GETDATE()) <=30)
FROM
	tblDealers DEALER WITH (NOLOCK)
WHERE
	DealerID IN (SELECT DealerID FROM tblLoanApps WITH (NOLOCK))
ORDER BY
  DEALER.State,
  Dealer.City,
  Dealer.DealerName





