/****** Object:  View dbo.temp_view_PartnerDealersAllowed    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE	VIEW [dbo].[temp_view_PartnerDealersAllowed] AS
SELECT --DISTINCT --TOP 100 PERCENT
--	TOP 5
		LenderID			= L.LenderID,
		DealerID			= D.DealerID,
		PartnerToolID		= PT.PartnerToolID,
		Lender				= UPPER(L.LenderName),
		Dealer				= UPPER(D.DealerName),
		Dealer_Location		= UPPER(D.City + ', ' + D.State),
		DealerType			= ISNULL(NULLIF(D.DealerType, ''), 'Independent'),
		NeedsCS				= CONVERT(BIT, CASE
								WHEN	ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'FRANCHISE' AND CAST(PDE_Activation.DataValue AS INT) > 1 THEN 1
								WHEN	ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'FRANCHISE' AND CAST(PDE_Activation.DataValue AS INT) <= 1 THEN 0
								WHEN	CAST(PDE_Activation.DataValue AS INT) = 1 OR CAST(PDE_Activation.DataValue AS INT) = 3 THEN 1
								ELSE 0 END),
		AllowedByLender			= CONVERT(BIT, CASE WHEN	EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE Field	= 'Dealer Enabled (Lender)'			AND DataValue	= 'TRUE' AND DealerID	= D.DealerID	AND LenderID = L.LenderID	AND PartnerToolID = PT.PartnerToolID	/*AND LoanAppID = 0	AND LoanApp_BidID = 0	AND LendersBranchID = 0*/) THEN 1 ELSE 0 END),
		AllowedByCreditSmarts	= CONVERT(BIT, CASE WHEN	EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE Field	= 'Dealer Enabled (CreditSmarts)'	AND DataValue	= 'TRUE' AND DealerID	= D.DealerID	AND LenderID = L.LenderID	AND PartnerToolID = PT.PartnerToolID	/*AND LoanAppID = 0	AND LoanApp_BidID = 0	AND LendersBranchID = 0*/) THEN 1 ELSE 0 END),
		Disposition				= CASE
		WHEN	ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'Franchise' AND
		((CAST(PDE_Activation.DataValue AS INT) < 2 AND
			EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
					Field				= 'Dealer Enabled (Lender)'			AND
					DataValue			= 'TRUE'							AND
					DealerID			= D.DealerID						AND
					LenderID			= L.LenderID						AND
					PartnerToolID		= PT.PartnerToolID					AND
					LoanAppID			= 0									AND
					LoanApp_BidID		= 0									AND
					LendersBranchID		= 0
			)) OR (CAST(PDE_Activation.DataValue AS INT) >= 2				AND
				EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
					Field				= 'Dealer Enabled (Lender)'			AND
					DataValue			= 'TRUE'							AND
					DealerID			= D.DealerID						AND
					LenderID			= L.LenderID						AND
					PartnerToolID		= PT.PartnerToolID					AND
					LoanAppID			= 0									AND
					LoanApp_BidID		= 0									AND
					LendersBranchID		= 0) 	AND

				EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
					Field				= 'Dealer Enabled (CreditSmarts)' 	AND
					DataValue			= 'TRUE'							AND
					DealerID			= D.DealerID						AND
					LenderID			= L.LenderID						AND
					PartnerToolID		= PT.PartnerToolID					AND
					LoanAppID			= 0									AND
					LoanApp_BidID		= 0									AND
					LendersBranchID		= 0))) THEN 'ACTIVE'
		WHEN ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'Independent'	AND
			 (((CAST(PDE_Activation.DataValue AS INT) = 0 OR CAST(PDE_Activation.DataValue AS INT) = 2) AND
			 EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (Lender)'			AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0))
			OR ((CAST(PDE_Activation.DataValue AS INT) = 1 OR CAST(PDE_Activation.DataValue AS INT) = 3) AND
			EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (Lender)'			AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0)								AND
			EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (CreditSmarts)'	AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0
			)
		)) THEN 'ACTIVE'
	WHEN (NOT EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (Lender)'			AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0))
			AND (NOT EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (CreditSmarts)'	AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0)) THEN 'NONACTIVE'
	WHEN EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (Lender)'			AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0) AND (
			(ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'Franchise' AND CAST(PDE_Activation.DataValue AS INT) >= 2 AND NOT EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (CreditSmarts)'	AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0)) OR
			(ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'Independent' AND (CAST(PDE_Activation.DataValue AS INT) = 1 OR CAST(PDE_Activation.DataValue AS INT) = 3) AND NOT EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (CreditSmarts)'	AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0))) THEN 'PENDING_CS'
	WHEN EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE
				Field				= 'Dealer Enabled (CreditSmarts)'	AND
				DataValue			= 'TRUE'							AND
				DealerID			= D.DealerID						AND
				LenderID			= L.LenderID						AND
				PartnerToolID		= PT.PartnerToolID					AND
				LoanAppID			= 0									AND
				LoanApp_BidID		= 0									AND
				LendersBranchID		= 0) THEN 'PENDING_LENDER' END,

		[Activation Type]	= CAST(PDE_Activation.DataValue AS INT)
	FROM
				tblPartnerTools				PT				WITH (NOLOCK)
		JOIN	tblPartnerDataElement		PDE				WITH (NOLOCK) ON 
					PDE.PartnerToolID 				=	PT.PartnerToolID 			AND 
					PDE.Field						<> 'Activation Policy'			AND
					PDE.LenderID					<>	0							AND
					PDE.DealerID					<>	0							AND
					PDE.LoanAppID					=	0							AND
					PDE.LoanApp_BidID				=	0

		JOIN	tblLenders					L				WITH (NOLOCK) ON PDE.LenderID = L.LenderID
		JOIN	tblDealers					D				WITH (NOLOCK) ON PDE.DealerID = D.DealerID
		JOIN	tblPartnerDataElement		PDE_Activation	WITH (NOLOCK) ON
					PDE_Activation.PartnerToolID	= PT.PartnerToolID 			AND
					PDE_Activation.Field			= 'Activation Policy'		AND
					PDE_Activation.LenderID			= L.LenderID				AND
					PDE_Activation.	LoanAppID		= 0							AND
					PDE_Activation.LoanApp_BidID	= 0							AND
					PDE_Activation.LendersBranchID	= 0

--WHERE
--	L.LenderID = 1186 AND PT.PartnerToolID = 12

GROUP BY
	L.LenderID,
	D.DealerID,
	PT.PartnerToolID,
	L.LenderName,
	D.DealerName,
	D.City,
	D.State,
	D.DealerType,
	PDE_Activation.DataValue

-- AND D.DealerID	IN (SELECT DealerID FROM tblPartnerDataElement WITH (NOLOCK)) -- WHERE NOT ISNULL(DataValue, 'FALSE') = 'FALSE')

/*
ORDER BY
	UPPER(D.DealerName)
*/




--OPTION (MAXDOP 1)



