CREATE VIEW temp_view_PartnerDealersAllowed_2012_12_04 AS
SELECT DISTINCT TOP 100 PERCENT
  L.LenderID,
  D.DealerID,
  PT.PartnerToolID,
  Lender = UPPER(L.LenderName),
  Dealer = UPPER(D.DealerName),
  Dealer_Location = UPPER(D.City + ', ' + D.State),
  DealerType = ISNULL(NULLIF(D.DealerType, ''), 'Independent'),

  NeedsCS = CASE
    WHEN ISNULL(D.DealerType, '') = 'FRANCHISE' AND PT.FranDealerNeedsCS = 1 THEN 1
    WHEN ISNULL(D.DealerType, '') = 'FRANCHISE' AND PT.FranDealerNeedsCS = 0 THEN 0
    WHEN PT.IndDealerNeedsCS = 1 THEN 1
    ELSE 0
  END,

  AllowedByLender = CASE
    WHEN EXISTS(SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (Lender)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN 1
    ELSE 0
    END,
  AllowedByCreditSmarts = CASE
    WHEN EXISTS(SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (CreditSmarts)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN 1
    ELSE 0
    END,
  Disposition = CASE
    WHEN ISNULL(D.DealerType, '') = 'FRANCHISE' AND PT.FranDealerNeedsCS = 0 AND EXISTS(SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (Lender)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN
      'ACTIVE'

    WHEN EXISTS(SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (Lender)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID)
          AND EXISTS (SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (CreditSmarts)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN
      'ACTIVE'

    WHEN (NOT EXISTS(SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (Lender)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID))
          AND (NOT EXISTS(SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (CreditSmarts)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID)) THEN
      'NONACTIVE'

    WHEN EXISTS(SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (Lender)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN
      'PENDING_CS'

    WHEN EXISTS(SELECT * FROM tblPartnerDataElement WHERE Field='Dealer Enabled (CreditSmarts)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN
      'PENDING_LENDER'
  END

 FROM
  tblPartnerTools PT WITH (NOLOCK)
  JOIN tblPartnerDataElement PDE WITH (NOLOCK) ON (PDE.PartnerToolID = PT.PartnerToolID)
  JOIN tblLenders L WITH (NOLOCK) ON (PDE.LenderID = L.LenderID)
  JOIN tblDealers D WITH (NOLOCK) ON (PDE.DealerID = D.DealerID AND PDE.DealerID=D.DealerID)
WHERE
  D.DealerID
    IN (SELECT DealerID FROM tblPartnerDataElement) -- WHERE NOT ISNULL(DataValue, 'FALSE') = 'FALSE')
ORDER BY
  UPPER(D.DealerName)









