/****** Object:  View dbo.temp_view_PartnerDealersAllowed_2013_05_12    Script Date: 7/31/2024 12:57:15 PM ******/

/*
	DECLARE @_LenderID		INTEGER,
			@_DealerID		INTEGER,
			@_PartnerID		INTEGER;

	SET 	@_LenderID		 = 60;
	SET		@_DealerID		= 3763;
	SET 	@_PartnerID		 = 2;
*/
--	SELECT * FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LenderID = @_LenderID AND PDE.PartnerToolID = @_PartnerID AND PDE.DealerID = 3763;	RETURN;

CREATE  VIEW temp_view_PartnerDealersAllowed_2013_05_12 AS

-- 0	No Dealerships Need CS Approval
-- 0	
-- 1	Ind Need CS,	Franchise Do Not
-- 2	NOT USED
-- 3	ALL Dealerships Need CS

--ALTER  VIEW ERIK_2016_04_26_allowed AS
		SELECT --TOP 500 --PERCENT
			--PDE.Field,
			--PDE_DEFINITION.*,

			LenderID			= Lender.LenderID,
			DealerID			= Dealer.DealerID,
			PartnerToolID		= Partner.PartnerToolID,
			Lender				= UPPER(Lender.LenderName),
			Dealer				= UPPER(Dealer.DealerName),
			Dealer_Location		= UPPER(Dealer.City + ', ' + Dealer.State),
			ActivationPolicy	= CONVERT(INTEGER,	CASE WHEN ISNUMERIC(PDE_Activation.DataValue) = 1 THEN PDE_Activation.DataValue ELSE NULL END),

			DealerType			= ISNULL(NULLIF(Dealer.DealerType, ''), 'Independent'),

			NeedsCS				= CONVERT(INTEGER, CASE WHEN ISNUMERIC(PDE_Activation.DataValue) = '0'	THEN 1
														WHEN PDE_Activation.DataValue			 = '0'	THEN 0
														WHEN PDE_Activation.DataValue			 = '2'	THEN 1
														WHEN PDE_Activation.DataValue			 = '3'	THEN 1
														WHEN PDE_Activation.DataValue			 = '1'	AND LEFT(ISNULL(Dealer.DealerType, 'I'), 1) = 'F' THEN 0
														WHEN PDE_Activation.DataValue			 = '1'	AND LEFT(ISNULL(Dealer.DealerType, 'I'), 1) = 'I' THEN 1
														ELSE 666 END),

			AllowedByLender			= ISNULL(CONVERT(BIT,	CASE Dealer_Enabled_Lender.DataValue		WHEN 'TRUE'		THEN 1	ELSE 0 END),	0),
			AllowedByCreditSmarts	= ISNULL(CONVERT(BIT,	CASE Dealer_Enabled_CS.DataValue			WHEN 'TRUE'		THEN 1	ELSE 0 END),	0),
			Disposition				= CONVERT(VARCHAR(30),	CASE
				-- IF THIS Partner-Lender-Dealer TRIAD IS EXPLICITLY MARKED ENABLED BY CREDITSMARTS, ACTIVATION POLICY AND DEALER TYPE DO NOT NEED TO BE CHECKED
				WHEN ISNULL(Dealer_Enabled_CS.DataValue,		'' )	= 'TRUE'	AND ISNULL(Dealer_Enabled_Lender.DataValue, '') = 'TRUE'		THEN 'ACTIVE'
				WHEN ISNULL(Dealer_Enabled_CS.DataValue,		'' )	= 'TRUE'																	THEN 'PENDING_LENDER'

				WHEN ISNULL(PDE_Activation.DataValue,	'0')	= '0'		AND ISNULL(Dealer_Enabled_Lender.DataValue,	'' )	= 'TRUE'	THEN 'ACTIVE'
				WHEN ISNULL(PDE_Activation.DataValue,	'0')	= '0'		AND ISNULL(Dealer_Enabled_CS.DataValue,		'' )	= 'TRUE'	THEN 'PENDING_LENDER'

				WHEN ISNULL(PDE_Activation.DataValue,	'0')	= '1'		AND ISNULL(Dealer_Enabled_Lender.DataValue,	'' )	= 'TRUE'	AND ISNULL(NULLIF(LEFT(Dealer.DealerType, 1), ''), 'I') = 'I'	THEN 'PENDING_CS'
				WHEN ISNULL(PDE_Activation.DataValue,	'0')	= '1'		AND ISNULL(Dealer_Enabled_Lender.DataValue,	'' )	= 'TRUE'	AND ISNULL(NULLIF(LEFT(Dealer.DealerType, 1), ''), 'I') = 'F'	THEN 'ACTIVE'
				WHEN ISNULL(PDE_Activation.DataValue,	'0')	= '1'		AND ISNULL(Dealer_Enabled_CS.DataValue,		'' )	= 'TRUE'																	THEN 'PENDING_LENDER'

				--WHEN ISNULL(PDE_Activation.DataValue,	'0')	= '0'		AND ISNULL(Dealer_Enabled_Lender.DataValue,		'' )	= 'TRUE'	THEN 'PENDING_LENDER'
				WHEN ISNULL(PDE_Activation.DataValue,	'0')	= '3'		AND ISNULL(Dealer_Enabled_Lender.DataValue,	'' )	= 'TRUE'	THEN 'PENDING_CS'
				WHEN ISNULL(PDE_Activation.DataValue,	'0')	= '3'		AND ISNULL(Dealer_Enabled_CS.DataValue,		'' )	= 'TRUE'	THEN 'PENDING_LENDER'
				ELSE 'NONACTIVE' END)

		 FROM
					tblPartnerTools				Partner					WITH (NOLOCK)
			JOIN	tblPartnerDataElement		PDE						WITH (NOLOCK) ON PDE.PartnerToolID						=	Partner.PartnerToolID

			JOIN	tblPartnerElementDefinition	PDE_Definition			WITH (NOLOCK) ON PDE_Definition.PartnerToolID			=	PDE.PartnerToolID		AND
																						 PDE_Definition.Field					=	PDE.Field				

		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			JOIN	tblLenders					Lender					WITH (NOLOCK) ON Lender.LenderID						=	PDE.LenderID

		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			JOIN	tblDealers					Dealer					WITH (NOLOCK) ON Dealer.DealerID						=	PDE.DealerID

		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			JOIN	tblPartnerDataElement		PDE_Activation			WITH (NOLOCK) ON PDE_Activation.PartnerToolID			=	Partner.PartnerToolID				AND
																						 PDE_Activation.Field					=	'Activation Policy'					AND
																						 PDE_Activation.LenderID				=	Lender.LenderID						AND
																						 PDE_Activation.DealerID				=	0

		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		LEFT JOIN	tblPartnerDataElement		Dealer_Enabled_CS		WITH (NOLOCK) ON Dealer_Enabled_CS.PartnerToolID		=	Partner.PartnerToolID				AND
																						 Dealer_Enabled_CS.Field				=	'Dealer Enabled (CreditSmarts)'		AND
																						 Dealer_Enabled_CS.DealerID				=	Dealer.DealerID						AND
																						 Dealer_Enabled_CS.LenderID				=	Lender.LenderID

		LEFT JOIN	tblPartnerDataElement		Dealer_Enabled_Lender	WITH (NOLOCK) ON Dealer_Enabled_Lender.PartnerToolID	=	Partner.PartnerToolID				AND
																						 Dealer_Enabled_Lender.Field			=	'Dealer Enabled (Lender)'			AND
																						 Dealer_Enabled_Lender.DealerID			=	Dealer.DealerID						AND
																						 Dealer_Enabled_Lender.LenderID			=	Lender.LenderID

		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------




--		WHERE
--			Dealer.DealerID				IN (SELECT DealerID FROM tblPartnerDataElement WITH (NOLOCK)) -- WHERE NOT ISNULL(DataValue, 'FALSE') = 'FALSE')

			--AND Lender.LenderID			 = @_LenderID
			--AND Partner.PartnerToolID	 = @_PartnerID

			--AND Dealer.DealerID = @_DealerID


		--ORDER BY   UPPER(Dealer.DealerName)

--WHERE 
--Lender.LenderID = 60 AND 
--Partner.PartnerToolID = 2
--AND NOT Disposition IN('NONACTIVE', 'PENDING_LENDER') 
--ORDER BY Disposition, Dealer


		GROUP BY
			Lender.LenderID,
			Lender.LenderName,
			Dealer.DealerID,
			Dealer.DealerName,
			Dealer.City,
			Dealer.State,
			Partner.PartnerToolID,
			PDE_Activation.DataValue,
