/****** Object:  View dbo.temp_view_PartnerDealersAllowed_scratch    Script Date: 7/31/2024 12:57:15 PM ******/

--CREATE VIEW temp_view_PartnerDealersAllowed_2013_05_12 AS
CREATE VIEW temp_view_PartnerDealersAllowed_scratch AS
SELECT --DISTINCT TOP 100 PERCENT
--	SELECT TOP 1
  L.LenderID,
  D.DealerID,
  PT.PartnerToolID,
  Lender = UPPER(L.LenderName),
  Dealer = UPPER(D.DealerName),
  Dealer_Location = UPPER(D.City + ', ' + D.State),
  DealerType =  ISNULL(NULLIF(D.DealerType, ''), 'Independent'),

  NeedsCS = CASE
    WHEN ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'FRANCHISE' AND CAST(PDE_Activation.DataValue AS INT) > 1 THEN 1
    WHEN ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'FRANCHISE' AND CAST(PDE_Activation.DataValue AS INT) <= 1 THEN 0
    WHEN CAST(PDE_Activation.DataValue AS INT) = 1 OR CAST(PDE_Activation.DataValue AS INT) = 3 THEN 1
    ELSE 0
  END,

  AllowedByLender = CASE
    WHEN EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK) WHERE Field='Dealer Enabled (Lender)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN 1
    ELSE 0
    END,
  AllowedByCreditSmarts = CASE
    WHEN EXISTS(SELECT * FROM tblPartnerDataElement WITH (NOLOCK)  WHERE Field='Dealer Enabled (CreditSmarts)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN 1
    ELSE 0
    END,
  Disposition = CASE
    WHEN 
		ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'Franchise' AND 
		((
			CAST(PDE_Activation.DataValue AS INT) < 2 AND 
			EXISTS(
				SELECT * 
				FROM tblPartnerDataElement  WITH (NOLOCK) 
				WHERE Field='Dealer Enabled (Lender)' AND 
					DataValue='TRUE' AND 
					DealerID=D.DealerID AND 
					LenderID=L.LenderID AND 
					PartnerToolID=PT.PartnerToolID
			)
		) OR (
			CAST(PDE_Activation.DataValue AS INT) >= 2 AND 
			EXISTS(
				SELECT * 
				FROM tblPartnerDataElement  WITH (NOLOCK) 
				WHERE Field='Dealer Enabled (Lender)' AND 
					DataValue='TRUE' AND 
					DealerID=D.DealerID AND 
					LenderID=L.LenderID AND 
					PartnerToolID=PT.PartnerToolID
			) AND
			EXISTS(
				SELECT * 
				FROM tblPartnerDataElement  WITH (NOLOCK) 
				WHERE Field='Dealer Enabled (CreditSmarts)' AND 
					DataValue='TRUE' AND 
					DealerID=D.DealerID AND 
					LenderID=L.LenderID AND 
					PartnerToolID=PT.PartnerToolID
			)
		)) THEN 'ACTIVE'
	WHEN 
		ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'Independent' AND 
		((
			(CAST(PDE_Activation.DataValue AS INT) = 0 OR CAST(PDE_Activation.DataValue AS INT) = 2) AND 
			EXISTS(
				SELECT * 
				FROM tblPartnerDataElement  WITH (NOLOCK) 
				WHERE Field='Dealer Enabled (Lender)' AND 
					DataValue='TRUE' AND 
					DealerID=D.DealerID AND 
					LenderID=L.LenderID AND 
					PartnerToolID=PT.PartnerToolID
			)
		) OR (
			(CAST(PDE_Activation.DataValue AS INT) = 1 OR CAST(PDE_Activation.DataValue AS INT) = 3) AND 
			EXISTS(
				SELECT * 
				FROM tblPartnerDataElement  WITH (NOLOCK) 
				WHERE Field='Dealer Enabled (Lender)' AND 
					DataValue='TRUE' AND 
					DealerID=D.DealerID AND 
					LenderID=L.LenderID AND 
					PartnerToolID=PT.PartnerToolID
			) AND 
			EXISTS(
				SELECT * 
				FROM tblPartnerDataElement  WITH (NOLOCK) 
				WHERE Field='Dealer Enabled (CreditSmarts)' AND 
					DataValue='TRUE' AND 
					DealerID=D.DealerID AND 
					LenderID=L.LenderID AND 
					PartnerToolID=PT.PartnerToolID
			)
		)) THEN 'ACTIVE'
    WHEN (NOT EXISTS(SELECT * FROM tblPartnerDataElement  WITH (NOLOCK) WHERE Field='Dealer Enabled (Lender)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID))
          AND (NOT EXISTS(SELECT * FROM tblPartnerDataElement  WITH (NOLOCK) WHERE Field='Dealer Enabled (CreditSmarts)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID)) THEN
      'NONACTIVE'

    WHEN 
		EXISTS(
			SELECT * 
			FROM tblPartnerDataElement  WITH (NOLOCK) 
			WHERE Field='Dealer Enabled (Lender)' AND 
				DataValue='TRUE' AND 
				DealerID=D.DealerID AND 
				LenderID=L.LenderID AND 
				PartnerToolID=PT.PartnerToolID
		) AND (
			(
				ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'Franchise' AND 
				CAST(PDE_Activation.DataValue AS INT) >= 2 AND 
				NOT EXISTS(
					SELECT * 
					FROM 
					tblPartnerDataElement  WITH (NOLOCK) 
					WHERE 
						Field='Dealer Enabled (CreditSmarts)' AND 
						DataValue='TRUE' AND 
						DealerID=D.DealerID AND 
						LenderID=L.LenderID AND 
						PartnerToolID=PT.PartnerToolID)
			) OR (
				ISNULL(NULLIF(D.DealerType, ''), 'Independent') = 'Independent' AND 
				(CAST(PDE_Activation.DataValue AS INT) = 1 OR CAST(PDE_Activation.DataValue AS INT) = 3) AND 
				NOT EXISTS(
					SELECT * 
					FROM 
					tblPartnerDataElement  WITH (NOLOCK) 
					WHERE 
						Field='Dealer Enabled (CreditSmarts)' AND 
						DataValue='TRUE' AND 
						DealerID=D.DealerID AND 
						LenderID=L.LenderID AND 
						PartnerToolID=PT.PartnerToolID)
			)) THEN
      'PENDING_CS'

    WHEN EXISTS(SELECT * FROM tblPartnerDataElement  WITH (NOLOCK) WHERE Field='Dealer Enabled (CreditSmarts)' AND DataValue='TRUE' AND DealerID=D.DealerID AND LenderID=L.LenderID AND PartnerToolID=PT.PartnerToolID) THEN
      'PENDING_LENDER'
  END
,CAST(PDE_Activation.DataValue AS INT) as [activation type]

 FROM
  tblPartnerTools PT WITH (NOLOCK)
  JOIN tblPartnerDataElement PDE WITH (NOLOCK) ON (PDE.PartnerToolID = PT.PartnerToolID) AND PDE.Field <> 'Activation Policy'

  JOIN tblLenders L WITH (NOLOCK) ON (PDE.LenderID = L.LenderID)
  JOIN tblDealers D WITH (NOLOCK) ON (PDE.DealerID = D.DealerID AND PDE.DealerID=D.DealerID)
  JOIN tblPartnerDataElement PDE_Activation WITH (NOLOCK) ON (PDE_Activation.PartnerToolID = PT.PartnerToolID) AND PDE_Activation.Field = 'Activation Policy' AND PDE_Activation.LenderID = L.LenderID
WHERE
  		D.DealerID	IN	(SELECT DealerID FROM viewDealers_PossibleActives WITH (NOLOCK))
  AND	D.DealerID	IN	(SELECT DealerID FROM tblPartnerDataElement WITH (NOLOCK) ) -- WHERE NOT ISNULL(DataValue, 'FALSE') = 'FALSE')
--ORDER BY
--  UPPER(D.DealerName)






