/****** Object:  View dbo.viewAffiliate30DayAppCount    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW dbo.viewAffiliate30DayAppCount
AS
SELECT     TOP 100 PERCENT dbo.tblDealers.AffiliateID, COUNT(dbo.tblLoanApps.LoanAppID) AS [30DayAppCount]
FROM         dbo.tblLoanApps INNER JOIN
                      dbo.tblDealers ON dbo.tblLoanApps.DealerID = dbo.tblDealers.DealerID
WHERE     (dbo.tblLoanApps.CreateDateTime BETWEEN DATEADD([day], - 30, GETDATE()) AND GETDATE())
GROUP BY dbo.tblDealers.AffiliateID
ORDER BY COUNT(dbo.tblLoanApps.LoanAppID) DESC





