/****** Object:  View dbo.viewAffiliateDealerAppCount    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW [dbo].[viewAffiliateDealerAppCount]
AS
SELECT     TOP 100 PERCENT dbo.tblAffiliateLogins.AffiliateLoginID, dbo.tblAffiliates.AffiliateID, dbo.tblDealers.DealerID, dbo.tblDealers.DealerName,
                      dbo.tblDealers.Contact, dbo.tblDealers.Address, dbo.tblDealers.City, dbo.tblDealers.State, dbo.tblDealers.ZIP, dbo.tblDealers.Telephone,
                      dbo.tblDealers.Fax, dbo.tblDealers.EMail, dbo.tblDealers.DealerType,
                      dbo.tblDealers.activated AS DealerActive,
                      dbo.tblDealers.DealerStatus AS DealerStatus,
                      dbo.tblDealers.DealerStatusUpdateDateTime,
                      dbo.tblAffiliateLogins.Active,
                      COUNT(dbo.tblLoanApps.LoanAppID) AS LoanAppCount
FROM         dbo.tblDealers WITH (NOLOCK)
	INNER JOIN dbo.tblAffiliateLogins WITH (NOLOCK)
	INNER JOIN dbo.tblAffiliates WITH (NOLOCK) ON dbo.tblAffiliateLogins.AffiliateID = dbo.tblAffiliates.AffiliateID ON
                      dbo.tblDealers.AffiliateID = dbo.tblAffiliates.AffiliateID
    LEFT OUTER JOIN dbo.tblLoanApps WITH (NOLOCK) ON dbo.tblDealers.DealerID = dbo.tblLoanApps.DealerID
GROUP BY dbo.tblAffiliateLogins.AffiliateLoginID, dbo.tblAffiliates.AffiliateID, dbo.tblDealers.DealerID, dbo.tblDealers.DealerName, dbo.tblDealers.Contact,
                      dbo.tblDealers.Address, dbo.tblDealers.City, dbo.tblDealers.State, dbo.tblDealers.ZIP, dbo.tblDealers.Telephone, dbo.tblDealers.Fax,
                      dbo.tblDealers.EMail, dbo.tblDealers.DealerType, dbo.tblAffiliateLogins.Active, dbo.tblDealers.activated, dbo.tblDealers.DealerStatus,dbo.tblDealers.DealerStatusUpdateDateTime
ORDER BY COUNT(dbo.tblLoanApps.LoanAppID) DESC





