/****** Object:  View dbo.viewApplication_CreditDemographic    Script Date: 7/31/2024 12:57:15 PM ******/

--DECLARE @_AppID INTEGER; SET @_AppID = 1295215;

CREATE VIEW viewApplication_CreditDemographic AS
	SELECT 
		LoanAppID			= Applicant.LoanAppID,
		LoanApp_ApplicantID	= Applicant.LoanApp_ApplicantID,
		First_Name			= DBO.ProperCase(Applicant.First_Name),
		Last_Name			= DBO.ProperCase(Applicant.Last_Name),
		First_Name_SoundEx	= SOUNDEX(Applicant.First_Name),
		Last_Name_SoundEx	= SOUNDEX(Applicant.Last_Name),
		SSN					= RIGHT('000' + CONVERT(VARCHAR(3), Applicant.SSN_1), 3) + '-' + RIGHT('00' + CONVERT(VARCHAR(2), Applicant.SSN_2), 2) + '-' + RIGHT('0000' + CONVERT(VARCHAR(4), Applicant.SSN_3), 4),
		DealerID			= Dealer.DealerID,
		DealerName			= DBO.ProperCase(Dealer.DealerName),
		DealerLocation		= DBO.ProperCase(Dealer.City) + ', ' + UPPER(Dealer.State),
		LenderID			= Branch.LenderID,
		ReferenceID			= Context.CreditPullContextID,
		Reference_DealerID	= Context.DealerID,
		Reference_LenderID	= Context.LenderID
	FROM 
					tblLoanApp_Applicant	Applicant		WITH (NOLOCK) 
		JOIN		tblLoanApps				CreditApp		WITH (NOLOCK)	ON CreditApp.LoanAppID		= Applicant.LoanAppID
		LEFT JOIN	tblDealers				Dealer			WITH (NOLOCK)	ON Dealer.DealerID			= CreditApp.DealerID
		LEFT JOIN	tblLoanApp_Bids			Bids			WITH (NOLOCK)	ON Bids.LoanAppID			= CreditApp.LoanAppID
		LEFT JOIN	tblLendersBranches		Branch			WITH (NOLOCK)	ON Branch.LendersBranchID	= Bids.LendersBranchID
		LEFT JOIN	tblLenders				Lender			WITH (NOLOCK)	ON Lender.LenderID			= Branch.LenderID

		LEFT JOIN	tblCreditPullContext	Context			WITH (NOLOCK)	ON Context.LoanAppID		= Bids.LoanAppID
																				AND(	(Context.LenderID	= Branch.LenderID)
																				OR		(Context.DealerID	= Dealer.DealerID)
																				)
--	WHERE 		Applicant.LoanAppID = @_AppID






