/****** Object:  View dbo.viewAutomationServiceConnections    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE VIEW viewAutomationServiceConnections AS
	SELECT
		[SessionID]		= [Proc].[Spid],
		[Machine]			= RTRIM([Proc].[HostName]),
		[App]					= RTRIM(CASE WHEN [Proc].[Program_Name] IN ('CSMarts_Queue_AutoCredit', 'CSmarts_Queue_AutoDecline') THEN [Proc].[Program_Name] WHEN [Proc].[Program_Name] LIKE 'Filter%Queue,%prjFilterQueue%' THEN 'CSMarts_Queue_AutoOffer' ELSE [Proc].[Program_Name] END),
		[PID]					= [Proc].[HostProcess],
		[Login]				= [Proc].[Login_Time],
		[Activity]		= [Proc].[Last_Batch],
		[LoginAgo]		= DATEDIFF(ss, [Proc].[Login_Time], GETDATE()),
		[ActivityAgo]	= DATEDIFF(ss, [Proc].[Last_Batch], GETDATE()),
		-- [Status]			= RTRIM([Proc].[Status]),
		[OpenTrans]		= [Proc].[Open_Tran],
		[Blocked]			= [Proc].[Blocked],
		[CPU]					= [Proc].[CPU],
		[IO]					= [Proc].[Physical_IO],
		[Memory]			= [Proc].[MemUsage],
		[Locks] 			= (SELECT COUNT(*) FROM [SYSTEM_LOGICAL_LOCKS] [Lock] WITH (NOLOCK) WHERE [Lock].[Object] = 'tblLoanApp_Underwriting'
			AND [Lock].[Scope] = 'Single' AND [Lock].[LockExpireDateTime] > GETDATE()
			AND [Lock].[LockedBy_SessionID] = [Proc].[SPID]
			AND [Lock].[LockedBy_Machine] = [Proc].[HostName])
			--AND [Lock].[PrimaryKeyValue] = [Underwriting].[UnderwritingID]
			-- AND [Lock].[LockedBy] = @_User
FROM
	[MASTER].[DBO].[SYSPROCESSES] [Proc] WITH (NOLOCK)
WHERE
	[Proc].[Program_Name] IN ('CSMarts_Queue_AutoCredit', 'CSmarts_Queue_AutoDecline') OR [Proc].[Program_Name] LIKE 'Filter%Queue,%prjFilterQueue%'


