/****** Object:  View dbo.viewAverageDealerRating    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE view [dbo].[viewAverageDealerRating] as 
select 
--rating.lenderid,
rating.dealerid,

Round(avg(Cast(rating.rating as Float)), 2) as average, 

count(rating1.lenderdealerratingid) as '1', 
count(rating2.lenderdealerratingid) as '2', 
count(rating3.lenderdealerratingid) as '3', 
count(rating4.lenderdealerratingid) as '4', 
count(rating5.lenderdealerratingid) as '5'

from tblLenderDealerRating as rating  WITH (NOLOCK)
left join tblLenderDealerRating as rating1 WITH (NOLOCK) on rating1.lenderid=rating.lenderid and rating1.dealerid=rating.dealerid and rating1.rating=1
left join tblLenderDealerRating as rating2 WITH (NOLOCK) on rating2.lenderid=rating.lenderid and rating2.dealerid=rating.dealerid and rating2.rating=2
left join tblLenderDealerRating as rating3 WITH (NOLOCK) on rating3.lenderid=rating.lenderid and rating3.dealerid=rating.dealerid and rating3.rating=3
left join tblLenderDealerRating as rating4 WITH (NOLOCK) on rating4.lenderid=rating.lenderid and rating4.dealerid=rating.dealerid and rating4.rating=4
left join tblLenderDealerRating as rating5 WITH (NOLOCK) on rating5.lenderid=rating.lenderid and rating5.dealerid=rating.dealerid and rating5.rating=5
--where rating.lenderid=45 and rating.dealerid=35756
Group by rating.dealerid


