/****** Object:  View dbo.viewB2BReport_RouteOne    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW viewB2BReport_RouteOne AS
SELECT TOP 100 PERCENT
	Status = CASE BID.Status
		WHEN 'PENDING_DEALER' THEN 'Offer'
		WHEN 'DECLINE_LENDER' THEN 'Decline'
	END,
	
	BID.UpdateDateTime,
	BID.LoanAppID,
	BID.LoanApp_BidID,
	Dealer.DealerID,
	Dealer			= UPPER(DEALER.DEALERNAME),
	DealerLocation	= UPPER(DEALER.CITY) + ', ' + UPPER(DEALER.STATE),	
	Applicants		= APP.APPLICANT_NAMES,
	Vehicle			= LTRIM(RTRIM(STR(APP.VEHICLE_YEAR))) + ' ' + APP.VEHICLE_MAKE + ' ' + APP.VEHICLE_MODEL,
	Payment			= ISNULL(NULLIF(dbo.FormatCurrency(BID.Payment, 1, 1), '$0.00'), ''),
	Term			= ISNULL(NULLIF(BID.Term, '0'), ''),
	Amount 			= ISNULL(NULLIF(dbo.FormatCurrency(BID.Financing_Amount, 1, 1), '$0.00'), ''),
	Discount		= ISNULL(NULLIF(dbo.FormatCurrency(BID.Discount_Fee, 1, 1), '$0.00'), ''),
	Fees			= ISNULL(NULLIF(dbo.FormatCurrency(BID.Advance, 1, 1), '$0.00'), ''),
	OfferComments	= BID.Comments


FROM
	tblLoanApp_Bids				BID		WITH (NOLOCK)
	JOIN tblLoanApps			APP		WITH (NOLOCK)		ON APP.LoanAppID = BID.LoanAppID
	JOIN tblLendersBranches		BRANCH	WITH (NOLOCK)		ON BRANCH.LendersBranchID = BID.LendersBranchID
	JOIN tblDealers				DEALER	WITH (NOLOCK)		ON DEALER.DealerID = APP.DealerID
WHERE
	LoanApp_BidID IN (SELECT LoanApp_BidID FROM tblPartnerDataElement WITH (NOLOCK) WHERE PartnerToolID = 12)
	AND BID.STATUS IN ('DECLINE_LENDER', 'PENDING_DEALER')
	AND DEALER.DealerID NOT IN (1)
ORDER BY
	BID.UpdateDateTime DESC





GO

