/****** Object:  View dbo.viewB2BXSLtFieldNames    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW viewB2BXSLtFieldNames AS	
	SELECT TOP 100 PERCENT
		VariableName		= 'var' + CASE 
			WHEN PED.Field = 'PARTNER_POST_URL'			THEN	'PostURL'
			WHEN PED.Field = 'transactionId'			THEN	'TransactionID'
			ELSE Replace(Replace(Replace(UPPER(LEFT(PED.Field, 1)) + SUBSTRING(PED.FIELD, 2, 999), ' ', ''), '(', ''), ')', '')
		END,	
	
		PartnerToolID		= PARTNER.PartnerToolID,
		PartnerElementDefinitionID	= PED.PartnerElementDefinitionID,
		Partner				= UPPER(LTRIM(RTRIM(PARTNER.Shortname))),
	
		Name				= CASE WHEN LEN(LTRIM(RTRIM(ISNULL(DisplayName, '')))) > 0 THEN PARTNER.DisplayName ELSE CreditSmarts.dbo.properCase(Replace(Partner.ShortName, '_', ' ')) END,
		UsedBy 				= REPLACE(LTRIM(RTRIM(REPLACE(
								ISNULL(REPLACE(CONVERT(CHAR(1), NULLIF(Partner.Dealer, 0)), '1', 'Dealer '), '') +
								ISNULL(REPLACE(CONVERT(CHAR(1), NULLIF(Partner.Lender, 0)), '1', 'Lender '), '') +
								ISNULL(REPLACE(CONVERT(CHAR(1), NULLIF(Partner.LenderBranch, 0)), '1', 'Branch '),
							 ''), '  ', ' '))), ' ', ', '),
	
		Field						= PED.Field, 
	--	Description					= CASE LEN(ISNULL(PED.Description, '')) WHEN 0 THEN DBO.ProperCase(REPLACE(PED.Field, '_', ' ')) END,
		ValueType					= PED.ValueType, 
		Caption						= PED.Caption
	FROM
				tblPartnerTools					PARTNER		WITH (NOLOCK)
		JOIN	tblPartnerElementDefinition		PED			WITH (NOLOCK) ON PED.PartnerToolID = PARTNER.PartnerToolID
	WHERE
			PARTNER.Active = 1
		AND	PED.Active = 1
	--	AND ISNULL(PED.KeyedFromLoanAppID, 0) = 0
	--	AND ISNULL(PED.KeyedFromLoanApp_BidID, 0) = 0 
	---	AND ValueType NOT IN('', 'ENABLED')
	--	AND 1 IN (KeyedFromLenderID, KeyedFromLendersBranchID, KeyedFromDealerID, KeyedFromAffiliateID)
--		AND PARTNER.PartnerToolID = 20
		
	ORDER BY
		PARTNER.ShortName,
		ISNULL(PED.SortSequence, '00000'),
		PED.Field




