/****** Object:  View dbo.viewB2B_ACS_OutstandingStatus    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW viewB2B_ACS_OutstandingStatus AS

  SELECT TOP 100 PERCENT
    ACS.*
  FROM
    viewB2B_ACS_Status ACS WITH (NOLOCK)
      JOIN tblLoanApp_Bids BID  WITH (NOLOCK) ON (ACS.LoanApp_BidID=BID.LoanApp_BidID)
  WHERE
    BID.Canceled_Date IS NULL
    AND ACS.Status NOT IN ('CANCELLED', 'DECLINE_LENDER', 'DECLINED', 'FILTER_DECLINE', 'NOQUOTES', 'APPLICATION WITHDRAWN', 'SERVICE COMPLETED', 'PREQUALIFIED - CANCELLED BY CUSTOMER')
    AND (ISNULL(ApplicationID, 0) > 0 AND ISNULL(QuoteID, 0) > 0)

    AND ((BID.Status NOT IN('DECLINE_LENDER', 'PENDING_DEALER', 'ACCEPTED')
      OR ACS.STATUS LIKE '%PENDING%'))
    AND (      (DATEPART(hour, GETDATE()) BETWEEN 6 AND 19 AND StatusSecondsAgo >= 120)
      OR      (DATEPART(hour, GETDATE()) NOT BETWEEN 6 AND 19 AND StatusSecondsAgo >= 600)    )
  ORDER BY
    StatusSecondsAgo DESC








