/****** Object:  View dbo.viewB2B_ACS_OutstandingToSend    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW viewB2B_ACS_OutstandingToSend AS
SELECT TOP 100 PERCENT
  LoanAppID = BIDS.LoanAppID,
  LoanApp_BidID = BIDS.LoanApp_BidID,
  CS_STATUS = BIDS.STATUS,
  ACS_STATUS = ISNULL(ACS.STATUS, 'NONE'),
  Score = ISNULL(SCORE.Highest_Score, 0),
  QuoteID = ISNULL(ACS.QuoteID, 0),
  SessionID = ISNULL(ACS.SessionID, 0),
  ApplicationID = ISNULL(ACS.ApplicationID, 0)
FROM 	
  tblLoanApp_Bids BIDS WITH (NOLOCK)
    LEFT OUTER JOIN tblB2B_ACS_Status ACS WITH (NOLOCK) ON(ACS.LoanApp_BidID=BIDS.LoanApp_BidID)
    LEFT OUTER JOIN tblLoanApp_DealerCreditScore SCORE WITH (NOLOCK) ON (SCORE.LoanAppID=BIDS.LoanAppID)
WHERE
  BIDS.LendersBranchID = 534
  AND CANCELED_DATE IS NULL
  AND ACS.AppPostText IS NULL
  AND ISNULL(ACS.ApplicationID, 0) = 0
  AND (NOT BIDS.STATUS IN('DECLINE_LENDER', 'CANCELLED', 'PENDING_DEALER', 'REFERRED'))

  AND (NOT (BIDS.STATUS='B2B_ERROR' AND DATEDIFF(ss, ACS.LastStatusDateTime, GETDATE()) < 300))
  AND (NOT (BIDS.STATUS='B2B_ERROR' AND ISNULL(SCORE.Highest_Score, 0) <= 0 AND ACS.LastMessageDateTime IS NOT NULL))
ORDER BY
  LoanApp_BidID






