CREATE VIEW viewB2B_ACS_Status AS

SELECT TOP 100 PERCENT
  BID.LoanAppID,
  ACS.LoanApp_BidID,
  BID.LendersBranchID,
  BRANCH.LenderID,
  DealerID = CONVERT(int, APP.DealerID),
  ACS.ApplicationID,
  ACS.SessionID,
  ACS.QuoteID,
  ACS.Status,
  CS_STATUS = BID.STATUS,
  ACS.LastStatusDateTime,
  StatusSecondsAgo = DATEDIFF(ss, ACS.LastStatusDateTime, GETDATE()),
  ACS.SentDateTime,
  SentSecondsAgo = DATEDIFF(ss, ACS.SentDateTime, GETDATE())
FROM
  tblB2B_ACS_Status             ACS       WITH (NOLOCK)
    JOIN tblLoanApp_Bids        BID       WITH (NOLOCK) ON(BID.LoanApp_BidID = ACS.LoanApp_BidID)
    JOIN tblLendersBranches     BRANCH    WITH (NOLOCK) ON(BID.LendersBranchID = BRANCH.LendersBranchID)
    JOIN tblLoanApps            APP       WITH (NOLOCK) ON(BID.LoanAppID = APP.LoanAppID)
ORDER BY
  ACS.LastStatusDateTime








