/****** Object:  View dbo.viewB2B_ActiveLenderTools    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW viewB2B_ActiveLenderTools AS

SELECT TOP 100 PERCENT
  PartnerToolID = TOOLS.PartnerToolID,
  PartnerCode = TOOLS.ShortName,
  PartnerName = TOOLS.DisplayName,
  LenderID = LENDER.LenderID,
  LendersBranchID = 0,
  LenderName = LENDER.LenderName,
  BranchName = NULL,
  FranDealerAvailable = ISNULL(TOOLS.FranchiseDealer, 0),
  FranDealerLenderActivation = ISNULL(TOOLS.FranDealerLenderActivation, 'LENDER'),
  FranDealerNeedsCS = ISNULL(TOOLS.FranDealerNeedsCS, 1),
  IndDealerAvailable = ISNULL(TOOLS.Dealer, 0),
  IndDealerLenderActivation = ISNULL(TOOLS.IndDealerLenderActivation, 'LENDER'),
  IndDealerNeedsCS = ISNULL(TOOLS.IndDealerNeedsCS, 1)
FROM
  tblLenders LENDER WITH (NOLOCK)
  JOIN tblPartnerDataElement VALUE WITH (NOLOCK) ON (VALUE.PartnerToolID = VALUE.PartnerToolID AND VALUE.LenderID = LENDER.LenderID)
  JOIN tblPartnerTools TOOLS WITH (NOLOCK) ON (TOOLS.PartnerToolID = VALUE.PartnerToolID)
WHERE
  TOOLS.Active = 1 AND
  VALUE.Field = 'Lender Enabled (CreditSmarts)' AND
  VALUE.DataValue = 'TRUE'

UNION

SELECT TOP 100 PERCENT
  PartnerToolID = TOOLS.PartnerToolID,
  PartnerCode = TOOLS.ShortName,
  PartnerName = TOOLS.DisplayName,
  LenderID = 0,
  LendersBranchID = BRANCH.LendersBranchID,
  LenderName = LENDER.LenderName,
  BranchName = BRANCH.BranchName,
  FranDealerAvailable = ISNULL(TOOLS.FranchiseDealer, 0),
  FranDealerLenderActivation = ISNULL(TOOLS.FranDealerLenderActivation, 'LENDER'),
  FranDealerNeedsCS = ISNULL(TOOLS.FranDealerNeedsCS, 1),
  IndDealerAvailable = ISNULL(TOOLS.Dealer, 0),
  IndDealerLenderActivation = ISNULL(TOOLS.IndDealerLenderActivation, 'LENDER'),
  IndDealerNeedsCS = ISNULL(TOOLS.IndDealerNeedsCS, 1)

FROM
  tblLenders LENDER WITH (NOLOCK)
  JOIN tblLendersBranches BRANCH WITH (NOLOCK) ON (BRANCH.LenderID = LENDER.LenderID)
  JOIN tblPartnerDataElement VALUE WITH (NOLOCK) ON (VALUE.PartnerToolID = VALUE.PartnerToolID AND VALUE.LendersBranchID = BRANCH.LendersBranchID)
  JOIN tblPartnerTools TOOLS WITH (NOLOCK) ON (TOOLS.PartnerToolID = VALUE.PartnerToolID)
WHERE
  TOOLS.Active = 1 AND
  VALUE.Field = 'Lender Enabled (CreditSmarts)' AND
  VALUE.DataValue = 'TRUE'
ORDER BY
  LenderID,
  LendersBranchID






