*/
	--DECLARE @BIDS TABLE(LoanAppID INT NOT NULL, LoanApp_BidID INT NOT NULL PRIMARY KEY); 
	--INSERT INTO @BIDS 
		--SELECT TOP 200 Bids.LoanAppID, Bids.LoanApp_BidID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblLoanApp_Bids Bids WITH (NOLOCK) ON Bids.LoanApp_BidID = PDE.LoanApp_BidID	WHERE PDE.Field='LastSentDateTime' AND PDE.PartnerToolID IN(2,8) GROUP BY Bids.LoanAppID, Bids.LoanApp_BidID, PDE.PartnerDataElementID ORDER BY PDE.PartnerDataElementID DESC
		--SELECT TOP 200 Bids.LoanAppID, Bids.LoanApp_BidID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblLoanApp_Bids Bids WITH (NOLOCK) ON Bids.LoanApp_BidID = PDE.LoanApp_BidID 					WHERE PDE.Field='LastSentDateTime' AND PDE.PartnerToolID IN(2,8) GROUP BY Bids.LoanAppID, Bids.LoanApp_BidID, PDE.PartnerDataElementID ORDER BY PDE.PartnerDataElementID DESC
		--SELECT TOP 200 Bids.LoanAppID, Bids.LoanApp_BidID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblLoanApp_Bids Bids WITH (NOLOCK) ON Bids.LoanApp_BidID = PDE.LoanApp_BidID 					WHERE Bids.LoanApp_BidID IS NOT NULL AND PDE.Field='dt_app_id' AND Bids.Status IN('PENDING_LENDER') AND PDE.PartnerToolID IN(2,8) AND NOT EXISTS(SELECT * FROM tblLoanApp_Bids_CommentLog CL WITH (NOLOCK) WHERE CL.LoanApp_BidID = Bids.LoanApp_BidID)		GROUP BY Bids.LoanAppID, Bids.LoanApp_BidID, PDE.PartnerDataElementID 		ORDER BY PDE.PartnerDataElementID DESC

--	RETURN;

	SELECT
		PartnerToolID		= Partner.PartnerToolID,
		PartnerCode			= Partner.ShortName,

		LoanAppID			= Bid.LoanAppID,
		LoanApp_BidID		= Bid.LoanApp_BidID,
		BidStatus			= Bid.Status,
		Decisioned			= CONVERT(BIT, CASE WHEN Bid.Status IN('PENDING_DEALER', 'ACCEPTED_DEALER', 'DECLINE_DEALER', 'DECLINE_LENDER') THEN 1 ELSE 0 END),

		Partner_LoanID		= NULLIF(LTRIM(RTRIM(Value_LoanID.DataValue)), ''),
		Partner_LoanID_Name	= NULLIF(LTRIM(RTRIM(Value_LoanID.Field)), ''),


		Message_Count		= COUNT(Messaging.[DateTime]),
		Message_First		= MIN(Messaging.[DateTime]),
		Message_Last		= MAX(Messaging.[DateTime]),

		LastBidUpdate		= DBO.Greater(Bid.UpdateDateTime, Bid.Offer_Date),

		Decision_Date		= CASE WHEN Bid.Status IN('PENDING_LENDER', 'REFERRED') THEN NULL WHEN BID.Status IN('ACCEPTED', 'DECLINE_DEALER', 'DECLINE_LENDER', 'PENDING_DEALER') THEN DBO.Greater(Bid.Offer_Date, Bid.UpdateDateTime) ELSE NULL END,

		LastSent			= CONVERT(DATETIME, Value_LastSent.DataValue)

	FROM
					tblLoanApp_Bids						Bid							WITH (NOLOCK)

             JOIN	tblPartnerDataElement				Value_LoanID				WITH (NOLOCK) ON		Value_LoanID.LoanApp_BidID			= Bid.LoanApp_BidID
																										AND	Value_LoanID.LoanAppID				= 0
																										AND	Value_LoanID.LenderID				= 0
																										AND	Value_LoanID.DealerID				= 0

			JOIN	tblPartnerElementDefinition			Definition_LoanID			WITH (NOLOCK) ON		Definition_LoanID.PartnerToolID		= Value_LoanID.PartnerToolID
																										AND	Definition_LoanID.ValueType			= 'PARTNER_LOAN_ID'
																										AND	Definition_LoanID.Field				= Value_LoanID.Field

			 JOIN	tblPartnerTools						Partner						WITH (NOLOCK) ON		Partner.PartnerToolID				= Value_LoanID.PartnerToolID

		LEFT JOIN	tblLoanApp_Bids_CommentLog			Messaging					WITH (NOLOCK) ON		Messaging.LoanApp_BidID				= Bid.LoanApp_BidID		and Messaging.[From] = 'LENDER'
																										/*AND	(	ISNULL(Messaging.[From],	'')	= 'LENDER' 
																											 OR	ISNULL(Messaging.[To],		'') = 'DEALER')*/

		LEFT JOIN	tblPartnerDataElement				Value_LastSent				WITH (NOLOCK) ON		Value_LastSent.PartnerToolID		= Partner.PartnerToolID
																										AND	Value_LastSent.LoanApp_BidID		= Bid.LoanApp_BiDID
																										AND	Value_LastSent.Field				= 'LastSentDateTime'
																										AND	Value_LastSent.LoanAppID			= 0
																										AND	Value_LastSent.LenderID				= 0
																										AND	Value_LastSent.DealerID				= 0
																										AND ISDATE(Value_LastSent.DataValue)	= 1
	--WHERE Bid.LoanApp_BidID IN (SELECT LoanApp_BidID FROM @BIDS)

	GROUP BY
		Partner.PartnerToolID,
		Partner.ShortName,
		Bid.LoanAppID,
		Bid.LoanApp_BidID,
		Value_LoanID.DataValue,
		Value_LoanID.Field,
		Value_LastSent.DataValue,
		Bid.UpdateDateTime,
		Bid.Offer_Date,
		Bid.STATUS


