		LenderID				= BRANCH.LenderID,
		LoanApp_BidID_Count		= COUNT(BID.LoanApp_BidID),
		LoanApp_BidID_Low		= MIN(BID.LoanApp_BidID),
		LoanApp_BidID_High		= MAX(BID.LoanApp_BidID)
