/****** Object:  View dbo.viewB2B_Bids_Dates    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW viewB2B_Bids_Dates AS
	SELECT
		LoanAppID			= Bids.LoanAppID,
		LoanApp_BidID		= Bids.LoanApp_BidID,
		BidStatus			= Bids.Status,

		Submit_Date			= DBO.SimpleDateTime(	CASE	WHEN Bids.Submit_Date				IS NOT NULL		THEN Bids.Submit_Date
															WHEN Bids.CreateDateTime			IS NOT NULL		THEN Bids.CreateDateTime
															WHEN Bids.UpdateDateTime			IS NOT NULL		THEN Bids.UpdateDateTime
															WHEN Application.UpdateDateTime		IS NOT NULL		THEN Application.UpdateDateTime
															WHEN Application.CreateDateTime		IS NOT NULL		THEN Application.CreateDateTime			END),

		Decision_Date		= DBO.SimpleDateTime(	CASE	WHEN Bids.Offer_Date				IS NOT NULL		THEN Bids.Offer_Date
															WHEN Bids.UpdateDateTime			IS NOT NULL		THEN Bids.UpdateDateTime
															WHEN Bids.Submit_Date				IS NOT NULL		THEN Bids.Submit_Date
															WHEN Bids.CreateDateTime			IS NOT NULL		THEN Bids.CreateDateTime				END),

		Funded_Date			= DBO.SimpleDateTime(	Bids.Funded_Date	)
	FROM
				  tblLoanApp_Bids 			Bids 						WITH (NOLOCK)
			 JOIN tblLoanApps				Application					WITH (NOLOCK) ON Application.LoanAppID		= Bids.LoanApp_BidID

 	



