/****** Object:  View dbo.viewB2B_Bids_LastSent    Script Date: 7/31/2024 12:57:15 PM ******/

CREATE VIEW viewB2B_Bids_LastSent AS
	SELECT
		LAST_SENT.PartnerDataElementID,
		LAST_SENT.PartnerToolID,
		APPLICATION.LoanAppID,
		BIDS.LoanApp_BidID,
		LENDER.LenderID,
		BRANCH.LendersBranchID,
		DEALER.DealerID,
	
		Date_LastSent			= CONVERT(DATETIME, CASE
			WHEN LAST_SENT.DataValue			IS NULL		THEN NULL
			WHEN LEN(LAST_SENT.DataValue)		= 0			THEN NULL
			WHEN ISDATE(LAST_SENT.DataValue)	= 0			THEN NULL
			ELSE LAST_SENT.DataValue END),
	
		Date_BidUpdate	= BIDS.UpdateDateTime,
		Date_Funded		= BIDS.Funded_Date,
		Date_Offer		= BIDS.OFFER_DATE,
		Date_Submit		= BIDS.SUBMIT_DATE
	
		FROM
							tblPartnerDataElement		LAST_SENT		WITH (NOLOCK)
			INNER JOIN		tblLoanApp_Bids				BIDS			WITH (NOLOCK) ON LAST_SENT.LoanApp_BidID	= BIDS.LoanApp_BidID
			INNER JOIN		tblLoanApps					APPLICATION		WITH (NOLOCK) ON BIDS.LoanAppID				= APPLICATION.LoanAppID			
			INNER JOIN		tblDealers					DEALER			WITH (NOLOCK) ON APPLICATION.DealerID		= DEALER.DealerID
			INNER JOIN		tblLendersBranches			BRANCH			WITH (NOLOCK) ON BIDS.LendersBranchID		= BRANCH.LendersBranchID
			INNER JOIN		tblLenders					LENDER			WITH (NOLOCK) ON BRANCH.LenderID			= LENDER.LenderID
			INNER JOIN		tblPartnerTools				PARTNER			WITH (NOLOCK) ON PARTNER.PartnerToolID		= LAST_SENT.PartnerToolID
		WHERE
			LAST_SENT.Field		= 'LastSentDateTime'




