/****** Object:  View dbo.viewB2B_Branch_GlobalToolStatus    Script Date: 7/31/2024 12:57:15 PM ******/








create  VIEW [dbo].[viewB2B_Branch_GlobalToolStatus] AS
	SELECT TOP 100 PERCENT
		B.LenderID,
		B.LendersBranchID,
		L.LenderName,
		PT.PartnerToolID,
		ShortName = CASE
			WHEN PT.ShortName IN (NULL, '') THEN
				'PARTNER_' + LTRIM(RTRIM(STR(PT.PartnerToolID)))
			ELSE
				PT.ShortName
		END,

		DisplayName = CASE
			WHEN PT.DisplayName IN (NULL, '') AND PT.ShortName IN (NULL, '') THEN
				'Partner # ' + LTRIM(RTRIM(STR(PT.PartnerToolID)))
			WHEN PT.DisplayName IN (NULL, '') THEN
				PT.ShortName
			ELSE
				PT.DisplayName
			END,				

		Enabled = CASE
			WHEN
				EXISTS(SELECT * FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.PartnerToolID = PT.PartnerToolID  AND  PDE.LendersBranchID = B.LendersBranchID AND Field='Lender Enabled (CreditSmarts)' AND DataValue='TRUE')
					THEN	CONVERT(BIT, 1)
					ELSE	CONVERT(BIT, 0)
			END
	
	FROM
					tblLendersBranches		B		WITH (NOLOCK)
		JOIN		tblLenders				L		WITH (NOLOCK)	ON (B.LenderID = L.LenderID)

		CROSS JOIN	tblPartnerTools			PT		WITH (NOLOCK)		
	
	WHERE
		EXISTS (
			SELECT
				*
			FROM
				tblPartnerElementDefinition		PED		WITH (NOLOCK)
			WHERE
				(PED.PartnerToolID = PT.PartnerToolID)
				AND 	Field = 'Lender Enabled (CreditSmarts)'
				AND		ShowOnLendersBranchAdmin = 1
				AND		KeyedFromLendersBranchID = 1
--				and ped.partnertoolid=2
--				and ped.partnertoolid=8
			)

--			AND ((NOT PartnerToolID IN (18,21)) OR (LenderID in (1037,227,60) ))
			AND ((NOT PartnerToolID IN (18, 44)) OR (B.LenderID in (1037,227,60) 
		
			OR (B.LenderID IN (45) AND PartnerToolID IN (44)) --enable r1 new interface only for test lender for now
			))

	
	ORDER BY
		PT.ShortName
--		L.LenderID,		PT.PartnerToolID














