/****** Object:  View dbo.viewB2B_CommentLog_Comments_2013_02_06    Script Date: 7/31/2024 12:57:15 PM ******/



CREATE VIEW viewB2B_CommentLog_Comments_2013_02_06 AS
SELECT TOP 100 PERCENT
	LoanAppID		= BID.LoanAppID,
	LoanApp_BidID	= BID.LoanApp_BidID,
	DealerID		= CONVERT(INT, APP.DealerID),
	LenderID		= BRANCH.LenderID,
	LendersBranchID	= BID.LendersBranchID,

	Date = CASE
		WHEN NOT CL.DateTime IS NULL 		THEN CL.DateTime
		WHEN NOT CL.UpdateDateTime IS NULL	THEN CL.UpdateDateTime
		WHEN NOT CL.CreateDateTime IS NULL	THEN CL.CreateDateTime
		ELSE GETDATE()
	END,

	[From] = CASE
		WHEN NOT [FROM] IS NULL				THEN [FROM]
		WHEN [To] = 'DEALER'				THEN 'LENDER'
		WHEN [To] = 'LENDER'				THEN 'DEALER'
	END,

	[To] = CASE
		WHEN NOT [To] IS NULL				THEN [To]
		WHEN [From] = 'DEALER'				THEN 'LENDER'
		WHEN [From] = 'LENDER'				THEN 'DEALER'
	END,

	Comment = CL.Comment
FROM
				tblLoanApp_Bids_CommentLog	CL		WITH (NOLOCK)
	INNER JOIN	tblLoanApp_Bids				BID		WITH (NOLOCK)	ON	CL.LoanApp_BidID		=	BID.LoanApp_BidID
	INNER JOIN	tblLoanApps					APP		WITH (NOLOCK)	ON	BID.LoanAppID			=	APP.LoanAppID
	INNER JOIN	tblLendersBranches			BRANCH	WITH (NOLOCK)	ON	BRANCH.LendersBranchID	=	BID.LendersBranchID

WHERE
		COMMENT IS NOT NULL
	AND	LEN(COMMENT) > 0

ORDER BY
	[DateTime] DESC






