/****** Object:  View dbo.viewB2B_CommentsOutstandingToSend    Script Date: 7/31/2024 12:57:15 PM ******/
CREATE    VIEW viewB2B_CommentsOutstandingToSend AS
	SELECT TOP 0 --PERCENT
		PartnerToolID				= Partner.PartnerToolID,
		PartnerCode					= Partner.ShortName,
		LoanAppID					= Bid.LoanAppID,
		LoanApp_BidID				= Value_LoanID.LoanApp_BidID,
		Field						= Value_LoanID.Field,
		LastSent					= Value_LastSent.DataValue,
		Message_Date				= Messaging.[DateTime],
		DataValue					= Value_LoanID.DataValue,
		LendersBranchID				= Bid.LendersBranchID,
		LenderID					= Branch.LenderID,
		URL							= Messaging_Trigger.URL,
		UserName					= Messaging_Trigger.Username,
		Password					= Messaging_Trigger.Password,
		XML							= Messaging_Trigger.XML
	FROM
					tblLoanApp_Bids						Bid							WITH (NOLOCK)

			 JOIN	tblLendersBranches					Branch						WITH (NOLOCK) ON		Branch.LendersBranchID				= Bid.LendersBranchID

			 JOIN	tblPartnerTools						Partner						WITH (NOLOCK) ON		Partner.PartnerToolID				= 2

             JOIN	tblPartnerDataElement				Value_LoanID				WITH (NOLOCK) ON		Value_LoanID.PartnerToolID			= Partner.PartnerToolID
																										AND	Value_LoanID.LoanApp_BidID			= Bid.LoanApp_BidID
																										AND	Value_LoanID.LoanAppID				= 0
																										AND	Value_LoanID.LenderID				= 0
																										AND	Value_LoanID.DealerID				= 0

			JOIN	tblPartnerElementDefinition			Definition_LoanID			WITH (NOLOCK) ON		Definition_LoanID.PartnerToolID		= Partner.PartnerToolID
																										AND	Definition_LoanID.ValueType			= 'PARTNER_LOAN_ID'
																										AND	Definition_LoanID.Field				= Value_LoanID.Field

			JOIN	tblPartnerToolsTriggers				Messaging_Trigger			WITH (NOLOCK) ON		Messaging_Trigger.PartnerToolID		= Partner.PartnerToolID
																										AND	Messaging_Trigger.Type				= 'SEND_MESSAGING'
			JOIN	tblLoanApp_Bids_CommentLog			Messaging					WITH (NOLOCK) ON		Messaging.LoanApp_BidID				= Bid.LoanApp_BidID
																										AND	[From]								= 'LENDER'
																										AND DATALENGTH(Messaging.Comment)		> 0

		LEFT JOIN	tblPartnerDataElement				Value_LastSent				WITH (NOLOCK) ON		Value_LastSent.LoanApp_BidID		= Bid.LoanApp_BiDID
																										AND	Value_LastSent.PartnerToolID		= Partner.PartnerToolID
																										AND	Value_LastSent.Field				= 'LastSentDateTime'
																										AND	Value_LastSent.LoanAppID			= 0
																										AND	Value_LastSent.LenderID				= 0
																										AND	Value_LastSent.DealerID				= 0
	WHERE
			Bid.CreateDateTime								>=	DATEADD(d, -60, GETDATE())
		AND	Messaging.[DateTime]							>=	DATEADD(d, -15, GETDATE())
		AND	ISNULL(Value_LastSent.DataValue, '2000-01-01')	<	Messaging.[DateTime]

--		AND Bid.LoanAppID = @LID

		--AND	Bid.LoanApp_BidID NOT IN (SELECT LoanApp_BidID FROM viewB2B_DecisionsOutstandingToSend	WITH (NOLOCK))
		--AND	DateDiff(ss, Value_LastSent.DataValue, GETDATE()) <	250

	ORDER BY
		Messaging.LoanApp_Bids_CommentLogID DESC	

/*
		Bid.LoanAppID DESC,
		Bid.LoanApp_BidID DESC,
		Messaging.LoanApp_Bids_CommentLogID DESC
		Messaging.[DateTime] DESC
	
	OPTION (MAXDOP 1)
*/


GO

