/****** Object:  View dbo.viewB2B_Dates    Script Date: 7/31/2024 12:57:15 PM ******/


CREATE VIEW viewB2B_Dates AS
	SELECT TOP 100 PERCENT
		BID.LoanAppID,
		BID.LoanApp_BidID,
		SentTime		= DE.DataValue,
		BidTime			= BID.UpdateDateTime,
		CommentTime		= MAX(CL.DateTime)
	FROM
		tblLoanApp_Bids_CommentLog 				CL		WITH (NOLOCK)
		INNER JOIN tblLoanApp_Bids 				BID		WITH (NOLOCK)		ON (BID.LoanApp_BidID = CL.LoanApp_BidID)
		INNER JOIN tblPartnerDataElement		DE		WITH (NOLOCK)		ON (CL.Loanapp_BidID = DE.LoanApp_BidID)
	WHERE
		DE.Field = 'LastSentDateTime'
		AND DE.DataValue IS NOT NULL
		AND BID.UpdateDateTime > '2012-01-01'
	GROUP BY
		BID.LoanAppID,
		BID.LoanApp_BidID,
		DE.DataValue,
		BID.UpdateDateTime
	ORDER BY
		BID.LoanApp_BidID DESC




