/****** Object:  View dbo.viewB2B_DealerCreditScoresToBackFill_Inner    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_DealerCreditScoresToBackFill_Inner AS
  SELECT DISTINCT TOP 100 PERCENT
    LoanAppID,

    GUID = CASE
      WHEN LEN(ISNULL(DEALER_CREDIT_EX, '')) > 0  THEN  DEALER_CREDIT_EX
      WHEN LEN(ISNULL(DEALER_CREDIT_TU, '')) > 0  THEN  DEALER_CREDIT_TU
      WHEN LEN(ISNULL(DEALER_CREDIT_EQ, '')) > 0  THEN  DEALER_CREDIT_EQ
    END,

    BUREAU = CASE
      WHEN LEN(ISNULL(DEALER_CREDIT_EX, '')) > 0  THEN  'EX'
      WHEN LEN(ISNULL(DEALER_CREDIT_TU, '')) > 0  THEN  'TU'
      WHEN LEN(ISNULL(DEALER_CREDIT_EQ, '')) > 0  THEN  'EQ'
    END

  FROM
    tblLoanApps WITH (NOLOCK)

  WHERE
    LoanAppID IN(SELECT LoanAppID FROM tblLoanApp_Bids WITH (NOLOCK) WHERE LendersBranchID=534)
    AND (LoanAppID NOT IN(SELECT LoanAppID FROM tblLoanApp_DealerCreditScore WITH (NOLOCK)))
    AND (LEN(ISNULL(DEALER_CREDIT_EX, '')) > 0 OR LEN(ISNULL(DEALER_CREDIT_TU, '')) > 0 OR LEN(ISNULL(DEALER_CREDIT_EQ, '')) > 0)

  ORDER BY
    LoanAppID DESC





