/****** Object:  View dbo.viewB2B_DealerTrackBidInfo    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewB2B_DealerTrackBidInfo AS
	SELECT --TOP 500
		LoanAppID			= DateStats.LoanAppID,
		LoanApp_BidID		= DateStats.LoanApp_BidID,
		Status				= DateStats.Status,
		LendersBranchID		= DateStats.LendersBranchID,
		LenderID			= DateStats.LenderID,
		Lender				= DateStats.Lender,
		DealerID			= DateStats.DealerID,
		Dealer				= DateStats.Dealer,
		ActivityDate		= DateStats.ActivityDate,
		DecisionDate		= DateStats.DecisionDate,
		MessageDate			= DateStats.MessageDate,
		DT_ApplicationID	= PDE_AppID.DataValue,
		DT_LenderID			= PDE_LenderID.DataValue,
		Funded				= CONVERT(BIT, CASE WHEN Funded.LoanApp_BidID IS NOT NULL THEN 1 ELSE 0 END),
		Funded_Date			= CASE WHEN Funded.Funded_Date IS NOT NULL THEN DBO.SimpleDateTime(Funded.Funded_Date)  END,
		Sent				= DBO.SimpleDateTime(PDE_Sent.DataValue),
		/*FundingSent			= DBO.SimpleDateTime(PDE_Funding_Sent.DataValue),*/
		SendDecision		= CONVERT(BIT, CASE 
			WHEN Funded.LoanApp_BidID 													IS																		NOT NULL	THEN 0
			/*WHEN ISDATE(PDE_Funding_Sent.DataValue)										=		1																			THEN 0*/
			WHEN ISDATE(PDE_Sent.DataValue)												=		0 																			THEN 1


			--WHEN CONVERT(DATETIME, (CONVERT(VARCHAR(16), PDE_Sent.DataValue, 120)))		<	CONVERT(DATETIME, (CONVERT(VARCHAR(16), DateStats.DecisionDate, 120)))				THEN 1
			ELSE 0 END),

		SendMessages		= CONVERT(BIT, CASE 
			WHEN Funded.LoanApp_BidID IS NOT NULL THEN 0
			WHEN ISDATE(DateStats.MessageDate) = 0 THEN 0
			WHEN CONVERT(DATETIME, (CONVERT(VARCHAR(16), PDE_Sent.DataValue, 120)))		<	CONVERT(DATETIME, (CONVERT(VARCHAR(16), DateStats.MessageDate, 120)))				THEN 1
			--WHEN ISDATE(DateStats.MessageDate) = 1 AND (ISDATE(PDE_Sent.DataValue) = 0 OR DBO.SimpleDateTime(PDE_Sent.DataValue) < DateStats.MessageDate) THEN 1 
			ELSE 0 END)/*,
		SendFunding			= CONVERT(BIT, CASE
			WHEN Funded.LoanApp_BidID IS NULL THEN 0
			ELSE 0
		END)*/
	FROM
					tblLoanApp_Bids				Bids	
			 JOIN	viewBidsDateStats			DateStats			WITH (NOLOCK)	ON Bids.LoanApp_BidID						= DateStats.LoanApp_BidID
		LEFT JOIN	tblLoanApp_Bids				Funded				WITH (NOLOCK)	ON Funded.LoanAppID							= Bids.LoanAppID					AND Funded.Funded_Date			IS NOT NULL
		LEFT JOIN	tblLendersBranches			Funded_Branch		WITH (NOLOCK)	ON Funded_Branch.LendersBranchID			= Funded.LendersBranchID			AND Funded_Branch.LenderID			= DateStats.LenderID
		LEFT JOIN	tblPartnerDataElement		PDE_AppID			WITH (NOLOCK)	ON PDE_AppID.PartnerDataElementID			> 3409602							AND Bids.LoanApp_BidID				= PDE_AppID.LoanApp_BidID			AND	PDE_AppID.PartnerToolID			= 2									AND		PDE_AppID.Field			IN(	'dt_app_id'			)
		LEFT JOIN	tblPartnerDataElement		PDE_LenderID		WITH (NOLOCK)	ON PDE_LenderID.PartnerDataElementID		> 3409602							AND Bids.LoanApp_BidID				= PDE_LenderID.LoanApp_BidID		AND	PDE_LenderID.PartnerToolID		= 2									AND		PDE_LenderID.Field		IN(	'dt_lender_id'		)
		LEFT JOIN	tblPartnerDataElement		PDE_Sent			WITH (NOLOCK)	ON PDE_Sent.PartnerDataElementID			> 3409602							AND Bids.LoanApp_BidID				= PDE_Sent.LoanApp_BidID			AND	PDE_Sent.PartnerToolID			= 2									AND 	PDE_Sent.Field			IN(	'LastSentDateTime'	)
		--LEFT JOIN	tblPartnerDataElement		PDE_Funding_Sent	WITH (NOLOCK)	ON PDE_Funding_Sent.PartnerDataElementID	> 3409602							AND Funded.LoanAppID					= PDE_Funding_Sent.LoanAppID		AND PDE_Funding_Sent.PartnerToolID	= 2									AND		PDE_Funding_Sent.Field	IN(	'LastSentDateTime_Funding ')	AND	ISDATE(PDE_Funding_Sent.DataValue) = 1
	WHERE
			Bids.LoanApp_BidID			>	785600
		AND	Bids.CreateDateTime			>	CONVERT(DATETIME, (CONVERT(VARCHAR(10), DATEADD(dd, -90, GETDATE()), 120)))
		AND Bids.LoanApp_BidID			IN	(SELECT LoanApp_BidID FROM tblPartnerDataElement WITH (NOLOCK) WHERE PartnerDataElementID			> 3409602 AND PartnerToolID = 2)
		AND Bids.Status					IN	('PENDING_DEALER', 'DECLINE_LENDER')


--ORDER BY Bids.LoanApp_BidID DESC;



