/****** Object:  View dbo.viewB2B_DealerTrack_Ack_New    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE    VIEW [dbo].[viewB2B_DealerTrack_Ack_New] AS
	SELECT TOP 100 PERCENT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		LenderID				= Branch.LenderID,
		LendersBranchID			= Branch.LendersBranchID,
		Lender					= UPPER(Lender.LenderName + ' (' + Lender.City + ', ' + Lender.State + ')'),
		LenderLocation			= UPPER(Lender.City + ' ' + Lender.State) + ' ' + ISNULL(NULLIF(RIGHT('00000' + Lender.ZIP, 5), '00000'), ''),
		DealerID				= Dealer.DealerID,
		Dealer					= UPPER(Dealer.DealerName + ' (' + Dealer.City + ', ' + Dealer.State + ')'),
		DealerLocation			= UPPER(Dealer.City + ' ' + Dealer.State) + ' ' + ISNULL(NULLIF(RIGHT('00000' + Dealer.ZIP, 5), '00000'), ''),

		PartnerToolID			= Partner.PartnerToolID,
		Partner					= Partner.ShortName,
		PartnerDataElementID	= PDE_LoanID.PartnerDataElementID,
		AppCreated				= App.CreateDateTime,

		--LoanApp_BidID			= MIN(Bid.LoanApp_BidID),
		Post_User				= PDE_Login.DataValue,
		Post_PW					= PDE_Password.DataValue,
		--Post_URL				= PDE_URL.DataValue,

		Post_URL			= CASE			
			WHEN /*Lender.LenderID = 1234 AND*/ NULLIF(PDE_Ack_URL.DataValue, '')	IS NOT NULL		THEN PDE_Ack_URL.DataValue	
			ELSE PDE_URL.DataValue END,

		DT_Ack					= '<dt_ack type="ack">'		+
									'<dt_lender_id>'		+ 	PDE_LenderID.DataValue		+ '</dt_lender_id>'        +
									'<dt_dealer_id>'		+ 	PDE_DealerID.DataValue		+ '</dt_dealer_id>'        +
									'<dt_app_id>'			+ 	PDE_LoanID.DataValue		+ '</dt_app_id>'           +
									'<lender_dealer_id>'	+ 	CONVERT(VARCHAR(16), Dealer.DealerID)		+ '</lender_dealer_id>'    										+
									'<lender_app_id>'		+ 	CONVERT(VARCHAR(16), Bid.LoanAppID) + '-' + CONVERT(VARCHAR(16), Bid.LoanApp_BidID)	+ '</lender_app_id>'	+
									'<err_description>'		+ 	''							+ '</err_description>'     +
								'</dt_ack>',

		Partner_LoanID_Name		= PDE_LoanID.Field,
		Partner_LoanID			= PDE_LoanID.DataValue,
		Partner_LenderID_Name	= PDE_LenderID.Field,
		Partner_LenderID		= PDE_LenderID.DataValue,
		Partner_DealerID_Name	= PDE_DealerID.Field,
		Partner_DealerID		= PDE_DealerID.DataValue
	FROM
			 tblLoanApp_Bids				Bid					WITH (NOLOCK)
		JOIN tblLendersBranches				Branch				WITH (NOLOCK) ON Branch.LendersBranchID			= Bid.LendersBranchID
		JOIN tblLenders						Lender				WITH (NOLOCK) ON Lender.LenderID				= Branch.LenderID
		JOIN tblPartnerElementDefinition	PED_LoanID			WITH (NOLOCK) ON PED_LoanID.ValueType	= 'PARTNER_LOAN_ID'				AND	PED_LoanID.Active	= 1
		JOIN tblPartnerTools				Partner				WITH (NOLOCK) ON Partner.PartnerToolID			= PED_LoanID.PartnerToolID	AND Partner.Active			= 1
		JOIN tblLoanApps					App					WITH (NOLOCK) ON App.LoanAppID					= Bid.LoanAppID
		JOIN tblDealers						Dealer				WITH (NOLOCK) ON Dealer.DealerID				= App.DealerID
		JOIN tblPartnerElementDefinition	PED_Login			WITH (NOLOCK) ON PED_Login.PartnerToolID		= Partner.PartnerToolID		AND PED_Login.ValueType		= 'PARTNER_AUTH_LOGIN'			AND	PED_Login.Active	= 1
		JOIN tblPartnerElementDefinition	PED_Password		WITH (NOLOCK) ON PED_Password.PartnerToolID		= Partner.PartnerToolID		AND PED_Password.ValueType	= 'PARTNER_AUTH_PASSWORD'		AND	PED_Password.Active	= 1
		JOIN tblPartnerElementDefinition	PED_DealerID		WITH (NOLOCK) ON PED_DealerID.PartnerToolID		= Partner.PartnerToolID		AND PED_DealerID.ValueType	= 'PARTNER_DEALER_ID'			AND	PED_DealerID.Active	= 1	
		JOIN tblPartnerElementDefinition	PED_LenderID		WITH (NOLOCK) ON PED_LenderID.PartnerToolID		= Partner.PartnerToolID		AND PED_LenderID.ValueType	= 'PARTNER_LENDER_ID'			AND	PED_LenderID.Active	= 1
		JOIN tblPartnerElementDefinition	PED_URL				WITH (NOLOCK) ON PED_URL.PartnerToolID			= Partner.PartnerToolID		AND PED_URL.ValueType		= 'PARTNER_POST_URL'			AND	PED_URL.Active		= 1

		JOIN tblPartnerElementDefinition	PED_Ack_URL			WITH (NOLOCK) ON PED_Ack_URL.PartnerToolID		= Partner.PartnerToolID		AND PED_Ack_URL.Field		= 'URL_ACK_APP'

		JOIN tblPartnerDataElement			PDE_Ack_URL			WITH (NOLOCK) ON PDE_Ack_URL.PartnerDataElementID > 500000 And PDE_Ack_URL.PartnerToolID		= Partner.PartnerToolID		AND PDE_Ack_URL.Field		= PED_Ack_URL.Field				AND PDE_Ack_URL.LenderID		= Branch.LenderID		AND PDE_Ack_URL.LoanAppID	= 0		AND PDE_Ack_URL.LoanApp_BidID	= 0		AND PDE_Ack_URL.LendersBranchID		= 0		AND PDE_Ack_URL.DealerID	= 0

		JOIN tblPartnerDataElement			PDE_Login			WITH (NOLOCK) ON PDE_Login.PartnerDataElementID > 500000 And PDE_Login.PartnerToolID		= Partner.PartnerToolID		AND PDE_Login.Field			= PED_Login.Field				AND PDE_Login.LenderID			= Branch.LenderID		AND PDE_Login.LoanAppID		= 0		AND PDE_Login.LoanApp_BidID		= 0		AND PDE_Login.LendersBranchID		= 0		AND PDE_Login.DealerID		= 0
		JOIN tblPartnerDataElement			PDE_Password		WITH (NOLOCK) ON PDE_Password.PartnerDataElementID > 500000 And  PDE_Password.PartnerToolID		= Partner.PartnerToolID		AND PDE_Password.Field		= PED_Password.Field			AND PDE_Password.LenderID		= Branch.LenderID		AND PDE_Password.LoanAppID	= 0		AND PDE_Password.LoanApp_BidID	= 0		AND PDE_Password.LendersBranchID	= 0		AND PDE_Password.DealerID	= 0
		JOIN tblPartnerDataElement			PDE_DealerID		WITH (NOLOCK) ON PDE_DealerID.PartnerDataElementID > 500000 And  PDE_DealerID.PartnerToolID		= Partner.PartnerToolID		AND PDE_DealerID.Field		= PED_DealerID.Field			AND PDE_DealerID.LoanApp_BidID	= Bid.LoanApp_BidID		AND PDE_DealerID.LoanAppID	= 0		AND PDE_DealerID.DealerID		= 0		AND PDE_DealerID.LendersBranchID	= 0		AND PDE_DealerID.LenderID	= 0
		JOIN tblPartnerDataElement			PDE_LenderID		WITH (NOLOCK) ON PDE_LenderID.PartnerDataElementID > 500000 And  PDE_LenderID.PartnerToolID		= Partner.PartnerToolID		AND PDE_LenderID.Field		= PED_LenderID.Field			AND PDE_LenderID.LoanApp_BidID	= Bid.LoanApp_BidID		AND PDE_LenderID.LoanAppID	= 0		AND PDE_LenderID.DealerID		= 0		AND PDE_LenderID.LendersBranchID	= 0		AND PDE_LenderID.LenderID	= 0
		JOIN tblPartnerDataElement			PDE_LoanID			WITH (NOLOCK) ON PDE_LoanID.PartnerDataElementID > 1000000 And  PDE_LoanID.PartnerToolID		= Partner.PartnerToolID		AND PDE_LoanID.Field		= PED_LoanID.Field				AND PDE_LoanID.LoanApp_BidID	= Bid.LoanApp_BidID		AND PDE_LoanID.LoanAppID	= 0		AND PDE_LoanID.DealerID			= 0		AND PDE_LoanID.LendersBranchID		= 0		AND PDE_LoanID.LenderID		= 0
		JOIN tblPartnerDataElement			PDE_URL				WITH (NOLOCK) ON PDE_URL.PartnerDataElementID > 500000 And  PDE_URL.PartnerToolID			= Partner.PartnerToolID		AND PDE_URL.Field			= PED_URL.Field					AND PDE_URL.LenderID			= Branch.LenderID		AND PDE_URL.LoanAppID		= 0		AND PDE_URL.DealerID			= 0		AND PDE_URL.LendersBranchID			= 0		AND PDE_URL.LoanApp_BidID	= 0
	WHERE
		Bid.CreateDateTime				>	DATEADD(dd, -2, GETDATE())	AND

/*
		(	Bid.UpdateDateTime			>	DATEADD(dd, -7, GETDATE())	OR
			Bid.CreateDateTime			>	DATEADD(dd, -7, GETDATE())
			--App.UpdateDateTime			>	DATEADD(dd, -7, GETDATE())
			--App.CreateDateTime			>	DATEADD(dd, -7, GETDATE())	
			--PDE_LoanID.UpdateDateTime	>	DATEADD(dd, -7, GETDATE())	
			--PDE_LoanID.CreateDateTime	>	DATEADD(dd, -7, GETDATE())	
		)	AND
		--PDE_LoanID.PartnerDataElementID	>	(SELECT MIN(PartnerDataElementID) FROM tblPartnerDataElement WITH (NOLOCK) WHERE CreateDateTime >= DATEADD(dd, -1, GETDATE())) AND
		--PDE_LoanID.CreateDateTime		>=	DATEADD(dd, -1, GETDATE())	AND

		PDE_LoanID.Field				=	'dt_app_id' AND
		PDE_LoanID.LoanAppID			= 0	AND
		PDE_LoanID.LenderID				= 0 AND
		PDE_LoanID.LendersBranchID		= 0	AND
		PDE_LoanID.DealerID				= 0	AND
		PDE_LoanID.PartnerToolID		= 2 AND
		Partner.PartnerToolID			= 2	AND
*/

		Bid.LoanApp_BidID =
			(SELECT 
				MIN(LoanApp_BidID) 
			FROM 
					 tblLoanApp_Bids		Bids_Inner		WITH (NOLOCK)
				JOIN tblLendersBranches		Branch_Inner	WITH (NOLOCK) ON Branch_Inner.LendersBranchID = Bids_Inner.LendersBranchID
			WHERE
				Bids_Inner.LoanAppID		= Bid.LoanAppID		AND
				Branch_Inner.LenderID		= Branch.LenderID
		)
--	ORDER BY
--		PDE_LoanID.PartnerDataElementID DESC
/*
	GROUP BY
		Bid.LoanAppID,
		Branch.LenderID,
		App.CreateDateTime,
		Dealer.DealerID,
		Bid.LoanApp_BidID,
		PDE_LoanID.PartnerDataElementID,
		--Branch.LendersBranchID,
		Partner.PartnerToolID,
		Partner.ShortName,
		PDE_LoanID.Field,
		PDE_LoanID.DataValue,
		PDE_Login.DataValue,
		PDE_Password.DataValue,
		PDE_URL.DataValue,
		PDE_LenderID.Field,
		PDE_LenderID.DataValue,
		PDE_DealerID.Field,
		PDE_DealerID.DataValue
*/		
/*
	ORDER BY
		Bid.LoanAppID,
		Branch.LenderID,
		Bid.LoanApp_BidID
--		Bid.LoanAppID
*/

--		





