/****** Object:  View dbo.viewB2B_DealerTrack_NewestApp    Script Date: 7/31/2024 12:57:16 PM ******/
--CREATE 
CREATE VIEW viewB2B_DealerTrack_NewestApp AS
	SELECT TOP 1
		PartnerDataElementID		= DT_APP_ID.PartnerDataElementID,
		PartnerToolID				= DT_APP_ID.PartnerToolID,
		Partner						= Partner.ShortName,
		AppID						= CONVERT(VARCHAR(14), Bid.LoanAppID) + '-' + CONVERT(VARCHAR(15), Bid.LoanApp_BidID),
		LoanAppID					= Bid.LoanAppID,
		LoanApp_BidID				= Bid.LoanApp_BidID,
		LenderID					= Lender.LenderID,
		LendersBranchID				= Branch.LendersBranchID,
		DealerID					= Dealer.DealerID,
		Dealer						= UPPER(Dealer.DealerName),
		DealerLocation				= UPPER(Dealer.City + ', ' + Dealer.State),
		Lender						= UPPER(Lender.LenderName),
		LenderLocation				= UPPER(Lender.City + ', ' + Lender.State),
		DT_App_ID					= CONVERT(VARCHAR(30), DT_APP_ID.DataValue),
		AppCreated					= App.CreateDateTime,
		DateTime_Now				= GETDATE()
	FROM 
			 tblPartnerDataElement		DT_APP_ID	WITH (NOLOCK)
		JOIN tblPartnerTools			Partner		WITH (NOLOCK) ON Partner.PartnerToolID		= DT_APP_ID.PartnerToolID
		JOIN tblLoanApp_Bids			Bid			WITH (NOLOCK) ON Bid.LoanApp_BidID			= DT_APP_ID.LoanApp_BidID
		JOIN tblLoanApps				App			WITH (NOLOCK) ON App.LoanAppID				= Bid.LoanAppID
		JOIN tblLendersBranches			Branch		WITH (NOLOCK) ON Branch.LendersBranchID		= Bid.LendersBranchID 
		JOIN tblLenders					Lender		WITH (NOLOCK) ON Lender.LenderID			= Branch.LenderID
		JOIN tblDealers					Dealer		WITH (NOLOCK) ON Dealer.DealerID			= App.DealerID

	WHERE 
		DT_APP_ID.PartnerDataElementID IN(SELECT MAX(PartnerDataElementID) FROM tblPartnerDataElement WITH (NOLOCK) WHERE 
			PartnerToolID = 2 AND Field = 'dt_app_id' AND LenderID = 0 AND LoanAppID = 0 AND DealerID = 0 AND LendersBranchID = 0)


