/****** Object:  View dbo.viewB2B_Dealer_GlobalToolStatus    Script Date: 7/31/2024 12:57:16 PM ******/









CREATE    VIEW viewB2B_Dealer_GlobalToolStatus AS
	SELECT TOP 100 PERCENT
		D.DealerID,
		D.DealerName,
		PT.PartnerToolID,
		ShortName = CASE
			WHEN PT.ShortName IN (NULL, '') THEN
				'PARTNER_' + LTRIM(RTRIM(STR(PT.PartnerToolID)))
			ELSE
				PT.ShortName
		END,

		DisplayName = CASE
			WHEN PT.DisplayName IN (NULL, '') AND PT.ShortName IN (NULL, '') THEN
				'Partner # ' + LTRIM(RTRIM(STR(PT.PartnerToolID)))
			WHEN PT.DisplayName IN (NULL, '') THEN
				PT.ShortName
			ELSE
				PT.DisplayName
			END,				

		Enabled = CASE
			WHEN
				EXISTS(SELECT * FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.PartnerToolID = PT.PartnerToolID  AND  PDE.DealerID = D.DealerID AND Field='Dealer Activation' AND DataValue='TRUE')
					THEN	CONVERT(BIT, 1)
					ELSE	CONVERT(BIT, 0)
			END
	
	FROM
					tblDealers				D		WITH (NOLOCK)				
		CROSS JOIN	tblPartnerTools			PT		WITH (NOLOCK)		
	
	WHERE
		EXISTS (
			SELECT
				*
			FROM
				tblPartnerElementDefinition		PED		WITH (NOLOCK)
			WHERE
				(PED.PartnerToolID = PT.PartnerToolID)
				AND 	Field = 'Dealer Activation'
				AND		ShowOnDealerAdmin = 1
				AND		KeyedFromDealerID = 1
--				and ped.partnertoolid=2
--				and ped.partnertoolid=8
			)

--			AND ((NOT PartnerToolID IN (18,21)) OR (LenderID in (1037,227,60) ))
			--AND ((NOT PartnerToolID IN (18, 44)) OR (LenderID in (1037,227,60) 
		
			--OR (LenderID IN (45) AND PartnerToolID IN (44)) --enable r1 new interface only for test lender for now
			--))

	
	ORDER BY
		PT.ShortName
--		L.LenderID,		PT.PartnerToolID















