/****** Object:  View dbo.viewB2B_Dealers_UsingBeta_V3    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE  VIEW [dbo].viewB2B_Dealers_UsingBeta_V3 AS
	SELECT TOP 100 PERCENT
		PartnerToolID		= PDE_USE_V3.PartnerToolID,
		DealerID			= Dealer.DealerID
	FROM 			
				tblPartnerDataElement		PDE_USE_V3		WITH (NOLOCK)
		JOIN	tblDealers					Dealer			WITH (NOLOCK) ON Dealer.DealerID				= PDE_USE_V3.DealerID
	WHERE
		PDE_USE_V3.Field			= 'USE_V3'					AND
		PDE_USE_V3.DataValue		= 'TRUE'					AND
		PDE_USE_V3.Active			= 1							AND
		PDE_USE_V3.LenderID			= 0							AND
		PDE_USE_V3.LendersBranchID	= 0							AND
		PDE_USE_V3.LoanAppID		= 0							AND
		PDE_USE_V3.LoanApp_BidID	= 0
	GROUP BY
		PDE_USE_V3.PartnerToolID,
		Dealer.DealerID
	ORDER BY
		PDE_USE_V3.PartnerToolID,
		Dealer.DealerID



