/****** Object:  View dbo.viewB2B_Dealers_UsingR1OneWayPost    Script Date: 7/31/2024 12:57:16 PM ******/


--select * from tblPartnerDataElement where Field = 'USE_V3' and partnertoolid= (select partnertoolid from tblpartnertools where shortname='R1_ONE_WAY') 
-- select * from [viewB2B_Dealers_UsingR1OneWayPost] 
-- select * from tblPartnerDataElement where field = 'Dealer Enabled (CreditSmarts)' and partnertoolid=44
--SELECT * FROM view_B2B_DealersActiveForPartnerTool  WITH (NOLOCK) WHERE PartnerToolID = 44
--delete from tblPartnerDataElement where partnerdataelementid=10598425

CREATE  VIEW [dbo].[viewB2B_Dealers_UsingR1OneWayPost] AS
	SELECT TOP 100 PERCENT
		PartnerToolID		= PDE.PartnerToolID,
		Field				= PDE.Field,
		DataValue			= PDE.DataValue,
		DealerID			= Dealer.DealerID
	FROM 			
				tblPartnerDataElement		PDE		WITH (NOLOCK)
		JOIN	tblDealers					Dealer			WITH (NOLOCK) ON Dealer.DealerID				= PDE.DealerID
	WHERE
		PDE.PartnerToolID	= (SELECT PartnerToolID FROM tblPartnerTools WHERE ShortName = 'R1_ONE_WAY')	AND
		PDE.Field			= 'Dealer Activation' /*correct field name */
		--PDE.Field			= 'Dealer Enabled (CreditSmarts)' /* incorrect field name */	
		AND PDE.Active			= 1									AND 
		PDE.DataValue		= 'TRUE'							AND 
		PDE.LenderID		= 0							AND
		PDE.LendersBranchID	= 0							AND
		PDE.LoanAppID		= 0							AND
		PDE.LoanApp_BidID	= 0
	GROUP BY
		PDE.PartnerToolID,
		PDE.Field,
		PDE.DataValue,
		Dealer.DealerID
	ORDER BY
		PDE.PartnerToolID,
		PDE.Field,
		PDE.DataValue,
		Dealer.DealerID



