CREATE VIEW viewB2B_DecisionsOutstandingToSend_2013_04_29_1 AS

SELECT TOP 100 PERCENT
	PARTNER_TOOL.PartnerToolID,
	PARTNER_TOOL.ShortName PartnerCode,
	BIDS.LoanApp_BidID,
	ELEMENT.Field,
	ELEMENT.DataValue,
	BRANCH.LendersBranchID,
	BRANCH.LenderID,

	URL = CASE
		WHEN LEN(ISNULL(TRIGGER_SEND.URL, '')) > 0 THEN TRIGGER_SEND.URL
		WHEN PARTNER_TOOL.ShortName = 'LENDINGTREE' THEN 'https://lenderweb.lendingtree.com/LenderDecisions/AutoOfferPost.aspx'
		ELSE ''
	END,

	UserName = CASE
		WHEN LEN(RTRIM(LTRIM(ISNULL(TRIGGER_SEND.Username, '')))) = 0 THEN	LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthUser, '')))
		ELSE	LTRIM(RTRIM(ISNULL(TRIGGER_SEND.UserName, '')))
	END,

	Password = CASE
		WHEN LEN(RTRIM(LTRIM(ISNULL(TRIGGER_SEND.Password, '')))) = 0 THEN	LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthPassword, '')))
		ELSE	LTRIM(RTRIM(ISNULL(TRIGGER_SEND.Password, '')))
	END,


	TRIGGER_SEND.XML,
	LastUpdateDateTime = DBO.StripToDate(BIDS.UpdateDateTime),
	BidStatus = BIDS.Status

FROM
				tblLoanApp_Bids					BIDS			WITH (NOLOCK)
	INNER JOIN	tblPartnerDataElement	 		ELEMENT			WITH (NOLOCK) ON BIDS.LoanApp_BidID			= ELEMENT.LoanApp_BidID AND Field='LastSentDateTime'
	INNER JOIN	tblPartnerToolsTriggers 		TRIGGER_SEND 	WITH (NOLOCK) ON TRIGGER_SEND.PartnerToolID	= ELEMENT.PartnerToolID AND TRIGGER_SEND.TYPE='SEND_DECISION'
	INNER JOIN	tblPartnerTools					PARTNER_TOOL 	WITH (NOLOCK) ON ELEMENT.PartnerToolID		= PARTNER_TOOL.PartnerToolID
	INNER JOIN	tblLendersBranches 				BRANCH			WITH (NOLOCK) ON BRANCH.LendersBranchID		= BIDS.LendersBranchID
	INNER JOIN	tblLenders 	 					LENDER			WITH (NOLOCK) ON LENDER.LenderID			= Branch.LenderID
	LEFT OUTER JOIN	viewB2B_PartnerAuthentication	AUTHENTICATION 	WITH (NOLOCK) ON AUTHENTICATION.LenderID	= BRANCH.LenderID AND AUTHENTICATION.PartnerToolID = ELEMENT.PartnerToolID
WHERE
		DATEDIFF(dd, BIDS.UpdateDateTime, GETDATE())			<=	90
	AND 
BIDS.Status		IN	('PENDING_DEALER', 'DECLINE_LENDER')
	AND	ELEMENT.Field											 =	(SELECT TOP 1 Field FROM tblPartnerElementDefinition DEFINITION	WITH (NOLOCK)	WHERE (DEFINITION.PartnerToolID=ELEMENT.PartnerToolID AND DEFINITION.ValueType='PARTNER_LOAN_ID'))
	AND DBO.StripToDate(ISNULL((SELECT TOP 1 DataValue FROM tblPartnerDataElement	WITH (NOLOCK)	WHERE (LoanApp_BidID=BIDS.LoanApp_BidID ) AND Field='LastSentDateTime'), '1/1/2009')) < DBO.StripToDate(BIDS.UpdateDateTime)
	AND LENDER.LenderID											IN	(SELECT LenderID FROM tblPartnerDataElement WITH (NOLOCK))
	AND Element.PartnerToolID									IN	(2, 8, 20)
	AND BRANCH.LENDERID										NOT	IN	(1050)
	AND	PARTNER_TOOL.Active										 =	ISNULL(PARTNER_TOOL.Active, 0)

	AND LEN(ISNULL(ELEMENT.DataValue, '')) > 0

	and not bids.lendersbranchid in(select LendersBranchID from tblLendersBranches WITH (NOLOCK) WHERE LenderID IN (select LenderID from tblLenders WITH (NOLOCK) where lendername like 'first inv%'))

--	AND BIDS.LoanApp_BidID=582705


--851334
ORDER BY
	BIDS.LoanApp_BidID			DESC,
	BIDS.LoanAppID 				DESC,
	PARTNER_TOOL.PartnerToolID








