/****** Object:  View dbo.viewB2B_DecisionsOutstandingToSend_Old    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_DecisionsOutstandingToSend_Old AS

SELECT TOP 100 PERCENT
  DATA_ELEMENT.PartnerToolID,
  PARTNER_TOOL.ShortName PartnerCode,
  DATA_ELEMENT.LoanApp_BidID,
  DATA_ELEMENT.Field,
  DATA_ELEMENT.DataValue,
  CONVERT(datetime, SENT_ELEMENT.DataValue) LastSentDateTime,
--  CONVERT(datetime, SENT_ELEMENT.DataValue) LastSentDateTime,
  TRIGGER_SEND.URL,
  TRIGGER_SEND.Username,
  TRIGGER_SEND.Password,
  TRIGGER_SEND.XML

FROM
  tblPartnerDataElement DATA_ELEMENT  WITH (NOLOCK)
    LEFT OUTER JOIN tblPartnerDataElement SENT_ELEMENT  WITH (NOLOCK) ON (DATA_ELEMENT.PartnerToolID = SENT_ELEMENT.PartnerToolID AND DATA_ELEMENT.LoanApp_BidID = SENT_ELEMENT.LoanApp_BidID AND SENT_ELEMENT.Field='LastSentDateTime')
  JOIN tblPartnerTools PARTNER_TOOL WITH (NOLOCK) ON (DATA_ELEMENT.PartnerToolID = PARTNER_TOOL.PartnerToolID)
    JOIN tblPartnerToolsTriggers TRIGGER_SEND WITH (NOLOCK) ON (TRIGGER_SEND.PartnerToolID=DATA_ELEMENT.PartnerToolID AND TRIGGER_SEND.TYPE='SEND_DECISION')
  JOIN tblLoanApp_Bids BIDS  WITH (NOLOCK) ON (DATA_ELEMENT.LoanApp_BidID = BIDS.LoanApp_BidID)
WHERE
  DATA_ELEMENT.LoanApp_BidID > 0
  AND (SENT_ELEMENT.DataValue IS NULL OR CONVERT(datetime, SENT_ELEMENT.DataValue) < BIDS.UpdateDateTime)



ORDER BY
  DATA_ELEMENT.LoanApp_BidID






