	PARTNER_TOOL.PartnerToolID,
	PARTNER_TOOL.ShortName PartnerCode,
	BIDS.LoanApp_BidID,
	ELEMENT.Field,
	ELEMENT.DataValue,
	BRANCH.LendersBranchID,
	BRANCH.LenderID,

	URL = CASE
		WHEN LEN(ISNULL(TRIGGER_SEND.URL, '')) > 0 THEN TRIGGER_SEND.URL
		WHEN PARTNER_TOOL.ShortName = 'LENDINGTREE' THEN 'https://lenderweb.lendingtree.com/LenderDecisions/AutoOfferPost.aspx'
		ELSE ''
	END,

	UserName = CASE
		WHEN LEN(RTRIM(LTRIM(ISNULL(TRIGGER_SEND.Username, '')))) = 0 THEN	LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthUser, '')))
		ELSE	LTRIM(RTRIM(ISNULL(TRIGGER_SEND.UserName, '')))
	END,

	Password = CASE
		WHEN LEN(RTRIM(LTRIM(ISNULL(TRIGGER_SEND.Password, '')))) = 0 THEN	LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthPassword, '')))
		ELSE	LTRIM(RTRIM(ISNULL(TRIGGER_SEND.Password, '')))
	END,


	TRIGGER_SEND.XML,
	LastUpdateDateTime = DBO.StripToDate(BIDS.UpdateDateTime),
	BidStatus = BIDS.Status

FROM
				tblLoanApp_Bids					BIDS			WITH (NOLOCK)
	inner JOIN tblPartnerDataElement ELEMENT WITH (NOLOCK) ON ELEMENT.LoanApp_BidID in (select loanapp_bidid from tblloanapp_bids with (nolock) where loanappid=bids.loanappid)
	INNER JOIN	tblPartnerToolsTriggers 		TRIGGER_SEND 	WITH (NOLOCK) ON TRIGGER_SEND.PartnerToolID	= ELEMENT.PartnerToolID AND TRIGGER_SEND.TYPE='SEND_DECISION'
	INNER JOIN	tblPartnerTools					PARTNER_TOOL 	WITH (NOLOCK) ON ELEMENT.PartnerToolID		= PARTNER_TOOL.PartnerToolID
