/****** Object:  View dbo.viewB2B_DecisionsOutstandingToSend_test    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_DecisionsOutstandingToSend_test AS

SELECT TOP 100 PERCENT
	PartnerToolID                           = PARTNER_TOOL.PartnerToolID,

	LoanApp_BidID                           = BIDS.LoanApp_BidID,
	LoanAppID								= BIDS.LoanAppID,
	LendersBranchID                         = BRANCH.LendersBranchID,
	LenderID								= BRANCH.LenderID,
	LenderName								= LENDER.LenderName,
	ShortName                               = PARTNER_TOOL.ShortName,
	PartnerCode                             = PARTNER_TOOL.ShortName,
	Field                                   = ELEMENT.Field,
	DataValue                               = ELEMENT.DataValue,
	URL                                     = CASE
		WHEN LEN(ISNULL(TRIGGER_SEND.URL, '')) > 0 THEN TRIGGER_SEND.URL
		ELSE 'https://gateway.lendingtree.com:8022/LenderResponse/MLenderResponse'
	END,

	Username                                = CASE
		WHEN LEN(ISNULL(TRIGGER_SEND.Username, '')) > 0 THEN TRIGGER_SEND.Username
		WHEN LEN(ISNULL(TRIGGER_SEND.Username, '')) = 0 AND (LENDER.LenderID = 45 OR LENDER.LenderID=227) THEN 'matadorsresponse'
		ELSE ''
	END,

	Password                                = CASE
		WHEN LEN(ISNULL(TRIGGER_SEND.Password, '')) > 0 THEN TRIGGER_SEND.Password
		WHEN LEN(ISNULL(TRIGGER_SEND.Password, '')) = 0 AND (LENDER.LenderID = 45 OR LENDER.LenderID=227) THEN 'Matadors02'
		ELSE ''
	END,

	XML                                     = TRIGGER_SEND.XML,
	LastSentDateTime                        = DBO.StripToDate((SELECT MAX(DataValue) FROM tblPartnerDataElement WITH (NOLOCK) WHERE LoanApp_BidID = BIDS.LoanApp_BidID AND Field = 'LastSentDateTime')),
	LastUpdateDateTime                      = DBO.StripToDate(BIDS.UpdateDateTime),
	BidStatus                               = BIDS.Status

FROM
			tblLoanApp_Bids				BIDS			WITH (NOLOCK)
	JOIN	tblPartnerDataElement		ELEMENT			WITH (NOLOCK)		ON BIDS.LoanApp_BidID = ELEMENT.LoanApp_BidID
	JOIN	tblPartnerToolsTriggers 	TRIGGER_SEND	WITH (NOLOCK)		ON TRIGGER_SEND.PartnerToolID = ELEMENT.PartnerToolID AND TRIGGER_SEND.TYPE = 'SEND_DECISION'
	JOIN	tblPartnerTools				PARTNER_TOOL	WITH (NOLOCK)		ON ELEMENT.PartnerToolID = PARTNER_TOOL.PartnerToolID
	JOIN	tblLendersBranches			BRANCH 			WITH (NOLOCK)		ON BRANCH.LendersBranchID = BIDS.LendersBranchID
	JOIN	tblLenders					LENDER 			WITH (NOLOCK)		ON LENDER.LenderID = Branch.LenderID
WHERE
			ELEMENT.Field = (SELECT TOP 1 Field FROM tblPartnerElementDefinition DEFINITION WITH (NOLOCK) WHERE (DEFINITION.PartnerToolID = ELEMENT.PartnerToolID AND DEFINITION.ValueType = 'PARTNER_LOAN_ID'))
	AND DBO.StripToDate(ISNULL((SELECT TOP 1 DataValue FROM tblPartnerDataElement WITH (NOLOCK) WHERE (LoanApp_BidID = BIDS.LoanApp_BidID ) AND Field = 'LastSentDateTime'), '1/1/2009')) < DBO.StripToDate(BIDS.UpdateDateTime)
	AND BIDS.Status IN ('PENDING_DEALER', 'DECLINE_LENDER')
	AND DATEDIFF(dd, BIDS.UpdateDateTime, GETDATE()) < = 14
	AND LENDER.LenderID IN (SELECT LenderID FROM tblPartnerDataElement WITH (NOLOCK))
	AND ELEMENT.PartnerToolID = 8

ORDER BY
	BIDS.LoanApp_BidID DESC





