/****** Object:  View dbo.viewB2B_DriveItCRM_Loans    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE view viewB2B_DriveItCRM_Loans														AS 
SELECT --top 10 
	Bid.LoanAppID,
	Bid.LoanApp_BidID,
	Bid.LenderID,
	Bid.LendersBranchID,
	Financing_Amount = ISNULL(Bid.Financing_Amount, 0) ,
	Vehicle_Wholesale_Adjusted = ISNULL(Bid.Vehicle_Wholesale_Adjusted, 0),
	LTV = (Bid.Financing_Amount/NULLIF(Bid.Vehicle_Wholesale_Adjusted, 0) ) * 100,


	BureauName		= CASE CreditPull.Bureau
		WHEN 'TU'		THEN	'Transunion'
		WHEN 'EX'		THEN	'Experian'
		WHEN 'EQ'		THEN	'Equifax'
		ELSE CreditPull.Bureau
	END,

	CreditPull.[CreditPullID]												AS CreditPullID,
	CreditPull.[GUID]														AS GUID,
	CreditPull.[Bureau]														AS Bureau,
	S.[Primary_Score]														AS Primary_Score,
	S.[Primary_CardID]														AS Primary_CardID,
	S.[Primary_Card]														AS Primary_Card,
	S.[Primary_Code_1]														AS Primary_Code_1,
	S.[Primary_Description_1]												AS Primary_Description_1,
	S.[Primary_Code_2]														AS Primary_Code_2,
	S.[Primary_Description_2]												AS Primary_Description_2,
	S.[Primary_Code_3]														AS Primary_Code_3,
	S.[Primary_Description_3]												AS Primary_Description_3,
	S.[Primary_Code_4]														AS Primary_Code_4,
	S.[Primary_Description_4]												AS Primary_Description_4,
	S.[Secondary_Score]														AS Secondary_Score,
	S.[Secondary_CardID]													AS Secondary_CardID,
	S.[Secondary_Card]														AS Secondary_Card,
	S.[Secondary_Code_1]													AS Secondary_Code_1,
	S.[Secondary_Description_1]												AS Secondary_Description_1,
	S.[Secondary_Code_2]													AS Secondary_Code_2,
	S.[Secondary_Description_2]												AS Secondary_Description_2,
	S.[Secondary_Code_3]													AS Secondary_Code_3,
	S.[Secondary_Description_3]												AS Secondary_Description_3,
	S.[Secondary_Code_4]													AS Secondary_Code_4,
	S.[Secondary_Description_4]												AS Secondary_Description_4,

	Primary_Inquiry_Code					= S.Primary_Inquiry_Code,
	Primary_Inquiry_Description			= S.Primary_Inquiry_Description,
	Primary_Reject_Code					= S.Primary_Reject_Code,
	Primary_Reject_Description			= S.Primary_Reject_Description,
	Secondary_Inquiry_Code					= S.Secondary_Inquiry_Code,
	Secondary_Inquiry_Description			= S.Secondary_Inquiry_Description,
	Secondary_Reject_Code					= S.Secondary_Reject_Code,
	Secondary_Reject_Description			= S.Secondary_Reject_Description,


	ScoreDateTime = CreditPull.CreateDateTime,
	PullUrl = 'https://www.Creditsmarts.com/Creditsmarts/underwriting/ajax/ajax-driveit-crm-send.asp?LoanAppID=' + CAST(Bid.LoanAppID AS VARCHAR(10)) + '&BidID=' + CAST(Bid.LoanApp_BidID AS VARCHAR(10)) + '&LenderID=' + CAST(Bid.LenderID AS VARCHAR(10)),
	PartnerToolID = -5000
--Bid.*
	--ISNULL(CreditPull.CreateDateTime, CreditPending.UpdateDateTime)														AS ScoreDateTime,

	FROM [view_LoanApps_Bids] Bid with (nolock)

	LEFT JOIN tblCreditPulls			CreditPull			WITH (NOLOCK) ON CreditPull.GUID					IN (dbo.fn_getGUID(Bid.Lender_Credit_EX), dbo.fn_getGUID(Bid.Lender_Credit_EQ), dbo.fn_getGUID(Bid.Lender_Credit_TU))
	LEFT JOIN tblCreditPulls_Scores		S					WITH (NOLOCK) ON S.GUID								=  CreditPull.GUID
	--LEFT JOIN tblCreditPullsPending	CreditPending		WITH (NOLOCK) ON CreditPull.GUID					=  CreditPending.GUID
	LEFT JOIN tblPartnerDataElement		LastSent			WITH (NOLOCK) ON LastSent.PartnerDataElementID		>  4000000					AND
																		 LastSent.LoanApp_BidID				=  Bid.LoanApp_BidID		AND
																		 LastSent.LenderID 					=  Bid.LenderID				AND 
																		 LastSent.PartnerToolID 			= -5000 					AND
																		 LastSent.Field 					 = 'LastSentDateTime'		AND
																		 LEN(ISNULL(LastSent.DataValue, '')) > 0
	WHERE  
		Bid.CreateDateTime								> '2017-03-01'															AND
		DateDiff(d, Bid.CreateDateTime, GETDATE())		<= 1																	AND 
		LastSent.UpdateDateTime							IS NULL																	AND
		(LEN(Lender_Credit_EX) > 0 OR LEN(Lender_Credit_TU) > 0 OR LEN(Lender_Credit_EQ) > 0)									AND
		(S.[Primary_Score] <= 600 AND S.[Primary_Score] >= 0 AND S.[Secondary_Score] <= 600 AND S.[Secondary_Score] >= 0)		AND
		ISNULL(Bid.Vehicle_Wholesale_Adjusted, 0)		<  110000																AND
		Bid.Financing_Amount							>  0																	AND 
		((Bid.Financing_Amount/NULLIF(Bid.Vehicle_Wholesale_Adjusted, 0) ) * 100) <= 90											/*AND

		Bid.LenderID=1140
	ORDER BY
		Bid.LoanApp_BidID DESC
	OPTION (MAXDOP 1)

--having LTV > 90
--order by Bid.LoanAppID desc
*/

