/****** Object:  View dbo.viewB2B_Exchange_LastSent    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewB2B_Exchange_LastSent AS
	SELECT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		LenderID				= Lender.LenderID,
		LendersBranchID			= Branch.LendersBranchID,
		DealerID				= Dealer.DealerID,
		PartnerToolID			= PTT.PartnerToolID,
		LastSentDateTime		= CONVERT(DATETIME, CASE
			WHEN PDE_Sent.DataValue							IS	NULL		THEN NULL
			WHEN LEN(PDE_Sent.DataValue)					=	0			THEN NULL
			WHEN LEN(LTRIM(PDE_Sent.DataValue))				= 	0			THEN NULL
			WHEN ISDATE(PDE_Sent.DataValue)					=	1			THEN PDE_Sent.DataValue
			ELSE NULL END)

/*
		Status					= PTS.Status,
		Sent					= PTS.Sent,
		PostError				= PTS.PostError,
		PostErrorDescription	= PTS.PostErrorDescription,
		UpdateDateTime			= PTS.UpdateDateTime
*/

	FROM
						tblLoanApp_Bids					Bid			WITH (NOLOCK)
				JOIN	tblLoanApps						App			WITH (NOLOCK)	ON	App.LoanAppID				=	Bid.LoanAppID
				JOIN	tblDealers						Dealer		WITH (NOLOCK)	ON	Dealer.DealerID				=	App.DealerID
				JOIN	tblLendersBranches				Branch		WITH (NOLOCK)	ON	Branch.LendersBranchID		=	Bid.LendersBranchID
				JOIN	tblLenders						Lender		WITH (NOLOCK)	ON	Lender.LenderID				=	Branch.LenderID
		LEFT	JOIN	tblPartnerDataElement			PDE_SENT	WITH (NOLOCK) 	ON	PDE_SENT.Field				=	'LastSentDateTime'
																					AND	PDE_SENT.Active				=	1
																					AND	PDE_SENT.LoanApp_BidID		IN 	(SELECT LoanApp_BidID FROM tblLoanApp_Bids Bid_Inner WITH (NOLOCK) WHERE Bid_Inner.LoanAppID = Bid.LoanAppID AND Bid_Inner.LendersBranchID IN (SELECT LendersBranchID FROM tblLendersBranches Branch_Inner WITH (NOLOCK) WHERE Branch_Inner.LenderID = Branch.LenderID))
		LEFT	JOIN	tblPartnerTools					PTT			WITH (NOLOCK)	ON	PTT.PartnerToolID			=	PDE_Sent.PartnerToolID

	--WHERE Bid.LoanAppID = 986389 OR Bid.LoanApp_BidID = 774221




GO

