/****** Object:  View dbo.viewB2B_FieldLookup_PartnerDealerID    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW viewB2B_FieldLookup_PartnerDealerID AS
	SELECT
		PartnerToolID			= Partner.PartnerToolID,
		Partner					= UPPER(Partner.ShortName),
		PartnerName				= ISNULL(NULLIF(Partner.DisplayName, ''), Partner.ShortName),
		DealerID				= Dealer.DealerID,
		Partner_DealerID_Name	= ISNULL(PDE_DealerID.Field,		''),
		Partner_DealerID		= ISNULL(PDE_DealerID.DataValue,	''),
		PartnerField_Name		= ISNULL(PDE_DealerID.Field,		''),
		PartnerField_Value		= ISNULL(PDE_DealerID.DataValue,	''),
		CreateUser				= ISNULL(ISNULL(NULLIF(PDE_DealerID.CreateUser, ''), NULLIF(PDE_DealerID.UpdateUser, '')), ''),
		UpdateUser				= ISNULL(ISNULL(NULLIF(PDE_DealerID.UpdateUser, ''), NULLIF(PDE_DealerID.CreateUser, '')), ''),
		CreateDateTime			= ISNULL(PDE_DealerID.CreateDateTime,	PDE_DealerID.UpdateDateTime),
		UpdateDateTime			= ISNULL(PDE_DealerID.UpdateDateTime,	PDE_DealerID.CreateDateTime),
		RowVersion				= ISNULL(NULLIF(PDE_DealerID.RowVersion, 0), 1)
	FROM
				tblDealers						Dealer			
		JOIN	tblPartnerDataElement			PDE_DealerID	WITH (NOLOCK) ON PDE_DealerID.DealerID		= Dealer.DealerID
		JOIN	tblPartnerElementDefinition		PED_DealerID	WITH (NOLOCK) ON PED_DealerID.PartnerToolID = PDE_DealerID.PartnerToolID 		AND PED_DealerID.Field = PDE_DealerID.Field	AND PED_DealerID.ValueType	= 'PARTNER_DEALER_ID'
		JOIN	tblPartnerTools					Partner			WITH (NOLOCK) ON Partner.PartnerToolID		= PDE_DealerID.PartnerToolID	
	WHERE
			ISNULL(Partner.Active,					0)	=	1
		AND NULLIF(PDE_DealerID.LoanApp_BidID,		0)	IS	NULL
		AND NULLIF(PDE_DealerID.LendersBranchID,	0)	IS	NULL
		AND NULLIF(PDE_DealerID.LoanAppID,			0)	IS	NULL
		AND NULLIF(PDE_DealerID.LenderID,			0)	IS	NULL
		AND NULLIF(PDE_DealerID.DealerID,			0)	IS	NOT NULL
	/*
	ORDER BY
		Partner.PartnerToolID,
		Dealer.DealerID
	*/

