/****** Object:  View dbo.viewB2B_FieldLookup_PartnerLenderID    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW viewB2B_FieldLookup_PartnerLenderID AS
	SELECT
		PartnerToolID			= Partner.PartnerToolID,
		Partner					= UPPER(Partner.ShortName),
		PartnerName				= ISNULL(NULLIF(Partner.DisplayName, ''), Partner.ShortName),
		LenderID				= Lender.LenderID,
		Partner_LenderID_Name	= ISNULL(PDE_LenderID.Field,		''),
		Partner_LenderID		= ISNULL(PDE_LenderID.DataValue,	''),
		PartnerField_Name		= ISNULL(PDE_LenderID.Field,		''),
		PartnerField_Value		= ISNULL(PDE_LenderID.DataValue,	''),
		CreateUser				= ISNULL(ISNULL(NULLIF(PDE_LenderID.CreateUser, ''), NULLIF(PDE_LenderID.UpdateUser, '')), ''),
		UpdateUser				= ISNULL(ISNULL(NULLIF(PDE_LenderID.UpdateUser, ''), NULLIF(PDE_LenderID.CreateUser, '')), ''),
		CreateDateTime			= ISNULL(PDE_LenderID.CreateDateTime,	PDE_LenderID.UpdateDateTime),
		UpdateDateTime			= ISNULL(PDE_LenderID.UpdateDateTime,	PDE_LenderID.CreateDateTime),
		RowVersion				= ISNULL(NULLIF(PDE_LenderID.RowVersion, 0), 1)
	FROM
				tblLenders						Lender			
		JOIN	tblPartnerDataElement			PDE_LenderID	WITH (NOLOCK) ON PDE_LenderID.LenderID		= Lender.LenderID
		JOIN	tblPartnerElementDefinition		PED_LenderID	WITH (NOLOCK) ON PED_LenderID.PartnerToolID = PDE_LenderID.PartnerToolID 		AND PED_LenderID.Field = PDE_LenderID.Field	AND PED_LenderID.ValueType	= 'PARTNER_LENDER_ID'
		JOIN	tblPartnerTools					Partner			WITH (NOLOCK) ON Partner.PartnerToolID		= PDE_LenderID.PartnerToolID	
	WHERE
			ISNULL(Partner.Active,					0)	=	1
		AND NULLIF(PDE_LenderID.LoanApp_BidID,		0)	IS	NULL
		AND NULLIF(PDE_LenderID.LendersBranchID,	0)	IS	NULL
		AND NULLIF(PDE_LenderID.LoanAppID,			0)	IS	NULL
		AND NULLIF(PDE_LenderID.DealerID,			0)	IS	NULL
		AND NULLIF(PDE_LenderID.LenderID,			0)	IS	NOT NULL
	/*
	ORDER BY
		Partner.PartnerToolID,
		Lender.LenderID
	*/

