/****** Object:  View dbo.viewB2B_FixBlueYieldApps    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewB2B_FixBlueYieldApps AS
	SELECT TOP 100 PERCENT
		LoanAppID		= BID.LoanAppID,
		LoanApp_BidID	= BID.LoanApp_BidID,
		Status			= BID.STATUS,
		Rate			= CONVERT(FLOAT, ISNULL(NULLIF(NULLIF(REPLACE(REPLACE(BID.Rate, '%', ''), ' ', ''), ''), '0'), '10')),
		Term			= CONVERT(INT, ISNULL(NULLIF(APP.LOAN_TERM_REQUESTED, ''), 60)),
		Who 			= CONVERT(VARCHAR(32), Applicant_Names), 
		Amount			= NULLIF(LOAN_TOTAL_LOAN_AMOUNT, 0),
		--Payment			= DBO.Payment(Loan_Total_Loan_Amount, Loan_Term_Requested, 10)
		Payment			= NULLIF(LOAN_ESTIMATED_PAYMENT, 0)
	FROM 
				tblLoanApps			APP		WITH (NOLOCK) 
		JOIN	tblLoanApp_Bids		BID		WITH (NOLOCK) ON 	BID.LoanAppID			= APP.LoanAppID
		JOIN	tblLendersBranches	BRANCH	WITH (NOLOCK) ON	BRANCH.LendersBranchID	= BID.LendersBranchID
		JOIN	tblLenders			LENDER	WITH (NOLOCK) ON	LENDER.LenderID			= BRANCH.LenderID
		JOIN	tblDealers			DEALER	WITH (NOLOCK) ON 	DEALER.DealerID			= APP.DealerID
	WHERE 
			LENDER.LenderName									=		'Matadors Community Credit Union'		
		AND	DEALER.DealerName									=		'Blue Yield'
		AND NULLIF(APP.LOAN_TOTAL_LOAN_AMOUNT,	0)				IS		NOT NULL
		AND NULLIF(APP.LOAN_TERM_REQUESTED,		0)				IS		NOT NULL
		AND NULLIF(APP.LOAN_ESTIMATED_PAYMENT,	0)				IS		NULL
		AND	DATEDIFF(hh, BID.CreateDateTime, 	GETDATE())		<=		72
		AND BID.STATUS											NOT IN	('PENDING_DEALER', 'DECLINE_DEALER', 'ACCEPTED')
	ORDER BY
		LoanAppID





