				/*(	(	E_LastSent.LoanAppID	= Bids.LoanAppID		AND		E_LastSent.LoanApp_BidID	= Bids.LoanApp_BidID	)
				OR	(	E_LastSent.LoanAppID	= 0						AND		E_LastSent.LoanApp_BidID	= Bids.LoanApp_BidID	)
				OR	(	E_LastSent.LoanAppID	= Bids.LoanAppID		AND		E_LastSent.LoanApp_BidID	= 0						)	)*/

			 JOIN tblPartnerTools					Partner			WITH (NOLOCK) ON Partner.PartnerToolID		= E_LastSent.PartnerToolID
	WHERE
