/****** Object:  View dbo.viewB2B_LenderBranchForPost    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_LenderBranchForPost AS

SELECT TOP 100 PERCENT
	tblLendersInterfaces.LendersInterfaceID,
	tblLendersInterfaces.LenderID,
	tblLendersBranches.LendersBranchID,
	tblLenders.LoginPrefix LenderCompanyCode,
	NULL BranchCompanyCode,
	ISNULL(PostCustom, 0) PostCustom,
	ISNULL(PostTest, 0) PostTest,
	ISNULL(NoResubmitSameDealerDays, 0) NoResubmitSameDealerDays,
	ISNULL(NoResubmitDifferentDealerDays, 0) NoResubmitDifferentDealerDays


FROM
	tblLendersInterfaces WITH (NOLOCK)
		INNER JOIN tblLenders WITH (NOLOCK)  ON tblLendersInterfaces.LenderID = tblLenders.LenderID
		INNER JOIN tblLendersBranches WITH (NOLOCK) ON tblLenders.LenderID = tblLendersBranches.LenderID

WHERE
	PostActive=1

UNION ALL

SELECT TOP 100 PERCENT
	tblLendersInterfaces.LendersInterfaceID,
	tblLendersInterfaces.LenderID,
	tblLendersInterfaces.LendersBranchID,
	tblLenders.LoginPrefix LenderCompanyCode,
	tblLendersBranches.LoginPrefix  BranchCompanyCode,
	ISNULL(PostCustom, 0) PostCustom,
	ISNULL(PostTest, 0) PostTest,
	ISNULL(NoResubmitSameDealerDays, 0) NoResubmitSameDealerDays,
	ISNULL(NoResubmitDifferentDealerDays, 0) NoResubmitDifferentDealerDays

FROM
	tblLendersBranches WITH (NOLOCK)
	INNER JOIN tblLenders  WITH (NOLOCK) ON tblLendersBranches.LenderID = tblLenders.LenderID
	INNER JOIN tblLendersInterfaces WITH (NOLOCK) ON tblLendersBranches.LendersBranchID = tblLendersInterfaces.LendersBranchID

WHERE
  PostActive=1







