/****** Object:  View dbo.viewB2B_LenderBranchInterfaces    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_LenderBranchInterfaces AS

SELECT
  LendersInterfaceID    = I.LendersInterfaceID,
  Name                  = I.Name,
  InterfaceAge          = DATEDIFF(s, I.UpdateDateTime, GETDATE()),
  PartnerCode           = I.PartnerCode,
  PostActive            = I.PostActive,
	PostText							= I.PostTest,
  ReceiveActive         = I.ReceiveActive,
	ReceiveTest						= I.ReceiveTest,
            MustHaveCustomerNumber            = ISNULL(I.MustHaveCustomerNumber, 0),
            SendNotificationMessageToLender   = ISNULL(I.SendNotificationMessageToLender, 0),
  LenderID              = I.LenderID,
  LenderName            = L.LenderName,
	LenderCompanyCode			=	L.LoginPrefix,
	LenderAge							= DATEDIFF(s, L.UpdateDateTime, GETDATE()),	

  LendersBranchID       = LB.LendersBranchID,
  BranchName            = LB.BranchName,
	BranchCompanyCode			= LB.LoginPrefix,
	BranchAge							= DATEDIFF(s, LB.UpdateDateTime, GETDATE()),

  Notification_Email    =
    CASE
      WHEN (NULLIF(L.notification_email, '') IS NULL AND NULLIF(LB.notification_email, '') IS NULL)  THEN  ''
      WHEN (NULLIF(LB.notification_email, '') IS NULL) THEN L.notification_email
      WHEN (NULLIF(L.notification_email, '') IS NULL) THEN LB.notification_email
      ELSE L.notification_email + CHAR(10) + LB.notification_email
    END
FROM
	tblLendersInterfaces I  WITH (NOLOCK) INNER JOIN
		tblLenders L  WITH (NOLOCK) ON
			I.LenderID = L.LenderID INNER JOIN
				tblLendersBranches LB  WITH (NOLOCK) ON L.LenderID = LB.LenderID

UNION ALL

SELECT TOP 100 PERCENT
	LendersInterfaceID    = I.LendersInterfaceID,
	Name                  = I.Name,
  InterfaceAge          = DATEDIFF(s, I.UpdateDateTime, GETDATE()),
	PartnerCode           = I.PartnerCode,
  PostActive            = I.PostActive,
	PostText							= I.PostTest,
  ReceiveActive         = I.ReceiveActive,
	ReceiveTest						= I.ReceiveTest,
            MustHaveCustomerNumber            = ISNULL(I.MustHaveCustomerNumber, 0),
            SendNotificationMessageToLender   = ISNULL(I.SendNotificationMessageToLender, 0),
	LenderID              = I.LenderID,
	LenderName            = L.LenderName,
	LenderCompanyCode			=	L.LoginPrefix,
	LenderAge							= DATEDIFF(s, L.UpdateDateTime, GETDATE()),	
	LendersBranchID       = I.LendersBranchID,

	BranchName            = LB.BranchName,
	BranchCompanyCode			= LB.LoginPrefix,
	BranchAge							= DATEDIFF(s, LB.UpdateDateTime, GETDATE()),
  notification_email    = L.notification_email
FROM
	tblLendersBranches LB  WITH (NOLOCK) INNER JOIN
		tblLenders L  WITH (NOLOCK) ON LB.LenderID = L.LenderID INNER JOIN
			tblLendersInterfaces I  WITH (NOLOCK) ON LB.LendersBranchID = I.LendersBranchID







GO

