  LoginURL,
  Logo,
  PartnerDataElementID,
  PartnerElementDefinitionID,
  PDF.PartnerToolID,
  ShortName,
  ShowOnAffiliateAdmin,
  ShowOnDealerAdmin,
  ShowOnLenderAdmin,
  ShowOnLenderDealerConsoleAdmin,
  ShowOnLendersBranchAdmin,
  SignUpURL,
  SortSequence,
  Tooltip,
  Value,
  ValueType

  FROM
    tblPartnerTools PF WITH (NOLOCK)
    JOIN tblPartnerElementDefinition PDF WITH (NOLOCK) ON (PF.PartnerToolID=PDF.partnerToolID)
    LEFT OUTER JOIN tblPartnerDataElement PDE WITH (NOLOCK) ON (PF.PartnerToolID=PDE.PartnerToolID)
WHERE
  (KeyedFromLenderID=1 OR KeyedFromLendersBranchID=1) AND (KeyedFromDealerID = 1) AND (ValueType='ENABLED')
ORDER BY
  SortSequence






