/****** Object:  View dbo.viewB2B_LenderPartnerActivity    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewB2B_LenderPartnerActivity AS
	SELECT	TOP 100 PERCENT 
		PartnerToolID	= PT.PartnerToolID,
		LenderID		= Lender.LenderID
	FROM 
				tblPartnerTools			PT		WITH (NOLOCK)	
		JOIN	tblPartnerDataElement	PDE		WITH (NOLOCK) 	ON PDE.PartnerToolID	= PT.PartnerToolID		AND PDE.Field	NOT IN('Activation Policy', 'Lender Enabled (CreditSmarts)', 'Dealer Enabled (Lender)', 'Dealer Enabled (CreditSmarts)', 'LastSentDateTime_Funding') 		AND LEN(PDE.DataValue) > 0
		JOIN	tblLenders				Lender	WITH (NOLOCK)	ON Lender.LenderID		= PDE.LenderID
	WHERE 
			PDE.Field	NOT IN('Activation Policy', 'Lender Enabled (CreditSmarts)', 'Dealer Enabled (Lender)', 'Dealer Enabled (CreditSmarts)', 'LastSentDateTime_Funding') 
		AND LEN(PDE.DataValue) > 0
	GROUP BY
		PT.PartnerToolID, 
		Lender.LenderID
	--ORDER BY PT.PartnerToolID,Lender.LenderID

--	OPTION (MAXDOP 1)

--WHERE PDE.PartnerToolID = PT.PartnerToolID AND PDE.LenderID = LENDER.LenderID AND PDE.DealerID = 0 AND Field NOT IN('Lender Enabled (CreditSmarts)', 'Activation Policy')




