/****** Object:  View dbo.viewB2B_LenderPartnerParameters    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_LenderPartnerParameters AS

SELECT DISTINCT TOP 100 PERCENT
	LenderID				= BRANCH.LenderID,
	LenderName				= BRANCH.LenderName,
	LendersBranchID			= BRANCH.LendersBranchID,
	BranchName				= BRANCH.BranchName,
	PartnerToolID			= TOOL.PartnerToolID,
	Partner					= TOOL.ShortName,
	PartnerName				= ISNULL(NULLIF(TOOL.DisplayName,''), TOOL.ShortName),
	PartnerIsChannel		= ISNULL(TOOL.IsChannel, 0),
	PartnerLenderIDField	= ISNULL(DEFINITION_LENDER_ID.Field, ''),

	PartnerLenderID =
		(SELECT TOP 1 DataValue FROM tblPartnerDataElement PDE_LENDER_ID WITH (NOLOCK) WHERE
		TOOL.PartnerToolID = PDE_LENDER_ID.PartnerToolID AND PDE_LENDER_ID.Field = DEFINITION_LENDER_ID.Field AND
		(PDE_LENDER_ID.LendersBranchID = BRANCH.LendersBranchID OR (PDE_LENDER_ID.LenderID = BRANCH.LenderID
		AND PDE_LENDER_ID.LendersBranchID = 0))),

	LenderActivated = CASE
		WHEN ELEMENT_ENABLED.DataValue IN('TRUE', 'T', '1', 'YES', 'Y') THEN CONVERT(BIT, 1)
		ELSE CONVERT(BIT, 0)
	END,

	PostURL					= ISNULL(ELEMENT_URL.DataValue, ''),
	PostUser				= ISNULL(ELEMENT_USER.DataValue, ''),
	PostPassword			= ISNULL(ELEMENT_PASSWORD.DataValue, '')

FROM
	viewLenderBranches 						BRANCH			WITH (NOLOCK)

	CROSS JOIN tblPartnerTools 				TOOL 			WITH (NOLOCK)

	LEFT OUTER JOIN tblPartnerElementDefinition	DEFINITION_LENDER_ID	WITH (NOLOCK)
		ON	DEFINITION_LENDER_ID.PartnerToolID = TOOL.PartnerToolID AND DEFINITION_LENDER_ID.ValueType = 'PARTNER_LENDER_ID'

	LEFT OUTER JOIN tblPartnerDataElement		ELEMENT_LENDER_ID		WITH (NOLOCK)
		ON	TOOL.PartnerToolID = ELEMENT_LENDER_ID.PartnerToolID AND ELEMENT_LENDER_ID.Field = DEFINITION_LENDER_ID.Field AND (( ELEMENT_LENDER_ID.LenderID = 0 AND ELEMENT_LENDER_ID.LendersBranchID = 0) OR (ELEMENT_LENDER_ID.LendersBranchID = BRANCH.LendersBranchID OR (ELEMENT_LENDER_ID.LenderID = BRANCH.LenderID AND ELEMENT_LENDER_ID.LendersBranchID = 0)))

	LEFT OUTER JOIN tblPartnerDataElement		ELEMENT_URL		WITH (NOLOCK)
		ON	TOOL.PartnerToolID = ELEMENT_URL.PartnerToolID AND ELEMENT_URL.Field = 'POST_URL' AND (( ELEMENT_URL.LenderID = 0 AND ELEMENT_URL.LendersBranchID = 0) OR (ELEMENT_URL.LendersBranchID = BRANCH.LendersBranchID OR (ELEMENT_URL.LenderID = BRANCH.LenderID AND ELEMENT_URL.LendersBranchID = 0)))

	LEFT OUTER JOIN tblPartnerDataElement		ELEMENT_USER		WITH (NOLOCK)
		ON	TOOL.PartnerToolID = ELEMENT_USER.PartnerToolID AND ELEMENT_USER.Field = 'POST_AUTH_USER' AND ((ELEMENT_USER.LenderID = 0 AND ELEMENT_USER.LendersBranchID = 0) OR   (ELEMENT_USER.LendersBranchID = BRANCH.LendersBranchID OR (ELEMENT_USER.LenderID = BRANCH.LenderID AND ELEMENT_USER.LendersBranchID = 0)))

	LEFT OUTER JOIN tblPartnerDataElement		ELEMENT_PASSWORD		WITH (NOLOCK)
		ON	TOOL.PartnerToolID = ELEMENT_PASSWORD.PartnerToolID AND ELEMENT_PASSWORD.Field = 'POST_PASSWORD' AND ((ELEMENT_PASSWORD.LenderID = 0 AND ELEMENT_PASSWORD.LendersBranchID = 0) OR ( ELEMENT_PASSWORD.LendersBranchID = BRANCH.LendersBranchID OR (ELEMENT_PASSWORD.LenderID = BRANCH.LenderID AND ELEMENT_PASSWORD.LendersBranchID = 0)))

	LEFT OUTER JOIN tblPartnerDataElement		ELEMENT_ENABLED		WITH (NOLOCK)
		ON	TOOL.PartnerToolID = ELEMENT_ENABLED.PartnerToolID AND ELEMENT_ENABLED.Field = 'Lender Enabled (CreditSmarts)' AND ((ELEMENT_ENABLED.LenderID = 0 AND ELEMENT_ENABLED.LendersBranchID = 0) OR  (ELEMENT_ENABLED.LendersBranchID = BRANCH.LendersBranchID OR (ELEMENT_ENABLED.LenderID = BRANCH.LenderID AND ELEMENT_ENABLED.LendersBranchID = 0)))

WHERE
			ISNULL(TOOL.IsCreditSmarts, 0) = 0
		AND	ISNULL(TOOL.IsInternal, 0) = 0

ORDER BY
	TOOL.PartnerToolID,
	BRANCH.LenderID,
	BRANCH.LendersBranchID




GO

