/****** Object:  View dbo.viewB2B_LenderPartnerParametersEx    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW viewB2B_LenderPartnerParametersEx AS
	SELECT TOP 100 PERCENT
		PartnerToolID			= Tool.PartnerToolID,
		Partner					= MIN(Tool.ShortName),
		LenderID				= Lender.LenderID,
		LendersBranchID			= Branch.LendersBranchID,
		Lender					= MIN(Lender.LenderName),
		Branch					= MIN(Branch.BranchName),
		PartnerLenderIDField	= MIN( ISNULL(Definition_Lender_ID.Field,		'')),
		PartnerLenderID			= MIN(ISNULL(E_Lender_ID.DataValue,					'')),
		LenderActivated			= CONVERT(BIT, MIN(CASE WHEN E_Decisions_Enabled.DataValue IN('TRUE', 'T', '1', 'YES', 'Y') THEN 1 ELSE 0 END)),
		PostURL					= MIN(ISNULL(NULLIF(E_Decisions_URL.DataValue,	''	),		ISNULL(E_URL_Generic.DataValue,			''	))),
		PostUser				= MIN(ISNULL(E_Decisions_User.DataValue,			''	)),
		PostPassword			= MIN(ISNULL(E_Decisions_Password.DataValue,		''	)),
		FundingURL				= MIN(ISNULL(NULLIF(E_Funding_URL.DataValue,		''	),		ISNULL(E_Decisions_URL.DataValue,		''))),
		FundingUser				= MIN(ISNULL(NULLIF(E_Funding_User.DataValue,		''	),		ISNULL(E_Decisions_User.DataValue,		''))),
		FundingPassword			= MIN(ISNULL(NULLIF(E_Funding_Password.DataValue,	''	),		ISNULL(E_Decisions_Password.DataValue,	'')))

	FROM
				  tblLenders					Lender					WITH (NOLOCK)
			 JOIN tblLendersBranches			Branch					WITH (NOLOCK) ON	Branch.LenderID						= Lender.LenderID
			 JOIN tblPartnerTools				Tool					WITH (NOLOCK) ON	Tool.Active							= 1
			 JOIN tblPartnerElementDefinition	Definition_Lender_ID	WITH (NOLOCK) ON	Definition_Lender_ID.ValueType		= 'PARTNER_LENDER_ID'			AND
																							Definition_Lender_ID.PartnerToolID	= Tool.PartnerToolID
		LEFT JOIN tblPartnerDataElement			E_Lender_ID				WITH (NOLOCK) ON	Tool.PartnerToolID	= E_Lender_ID.PartnerToolID				AND E_Lender_ID.Field			= Definition_Lender_ID.Field		AND E_Lender_ID.LenderID			= Branch.LenderID	AND E_Lender_ID.LendersBranchID				= 0		AND E_Lender_ID.LoanAppID			= 0		AND E_Lender_ID.LoanApp_BidID			= 0		AND E_Lender_ID.DealerID			= 0    AND E_Lender_ID.DataValue           <> ''
		LEFT JOIN tblPartnerDataElement			E_Decisions_URL			WITH (NOLOCK) ON	Tool.PartnerToolID	= E_Decisions_URL.PartnerToolID			AND E_Decisions_URL.Field		= 'POST_URL'						AND E_Decisions_URL.LenderID		= Branch.LenderID	AND E_Decisions_URL.LendersBranchID			= 0		AND E_Decisions_URL.LoanAppID		= 0		AND E_Decisions_URL.LoanApp_BidID		= 0		AND E_Decisions_URL.DealerID		= 0    AND E_Decisions_URL.DataValue       <> ''
		LEFT JOIN tblPartnerDataElement			E_Decisions_User		WITH (NOLOCK) ON	Tool.PartnerToolID	= E_Decisions_User.PartnerToolID		AND E_Decisions_User.Field		= 'POST_AUTH_USER'					AND E_Decisions_User.LenderID		= Branch.LenderID	AND E_Decisions_User.LendersBranchID		= 0		AND E_Decisions_User.LoanAppID		= 0		AND E_Decisions_User.LoanApp_BidID		= 0		AND E_Decisions_User.DealerID		= 0    AND E_Decisions_User.DataValue      <> ''
		LEFT JOIN tblPartnerDataElement			E_Decisions_Password	WITH (NOLOCK) ON	Tool.PartnerToolID	= E_Decisions_Password.PartnerToolID	AND E_Decisions_Password.Field	= 'POST_PASSWORD'					AND E_Decisions_Password.LenderID	= Branch.LenderID	AND E_Decisions_Password.LendersBranchID	= 0		AND E_Decisions_Password.LoanAppID	= 0		AND E_Decisions_Password.LoanApp_BidID	= 0		AND E_Decisions_Password.DealerID	= 0    AND E_Decisions_Password.DataValue  <> ''
		LEFT JOIN tblPartnerDataElement			E_Funding_URL			WITH (NOLOCK) ON	Tool.PartnerToolID	= E_Funding_URL.PartnerToolID			AND E_Funding_URL.Field			= 'POST_URL_FOR_FUNDING'			AND E_Funding_URL.LenderID			= Branch.LenderID	AND E_Funding_URL.LendersBranchID			= 0		AND E_Funding_URL.LoanAppID			= 0		AND E_Funding_URL.LoanApp_BidID			= 0		AND E_Funding_URL.DealerID			= 0    AND E_Funding_URL.DataValue         <> ''
		LEFT JOIN tblPartnerDataElement			E_Funding_User			WITH (NOLOCK) ON	Tool.PartnerToolID	= E_Funding_User.PartnerToolID			AND E_Funding_User.Field		= 'POST_USER_FOR_FUNDING'			AND E_Funding_User.LenderID			= Branch.LenderID	AND E_Funding_User.LendersBranchID			= 0		AND E_Funding_User.LoanAppID		= 0		AND E_Funding_User.LoanApp_BidID		= 0		AND E_Funding_User.DealerID			= 0    AND E_Funding_User.DataValue        <> ''
		LEFT JOIN tblPartnerDataElement			E_Funding_Password		WITH (NOLOCK) ON	Tool.PartnerToolID	= E_Funding_Password.PartnerToolID		AND E_Funding_Password.Field	= 'POST_PASSWORD_FOR_FUNDING'		AND E_Funding_Password.LenderID		= Branch.LenderID	AND E_Funding_Password.LendersBranchID		= 0		AND E_Funding_Password.LoanAppID	= 0		AND E_Funding_Password.LoanApp_BidID	= 0		AND E_Funding_Password.DealerID		= 0    AND E_Funding_Password.DataValue    <> ''
		LEFT JOIN tblPartnerDataElement			E_Decisions_Enabled		WITH (NOLOCK) ON	Tool.PartnerToolID	= E_Decisions_Enabled.PartnerToolID		AND E_Decisions_Enabled.Field	= 'LENDER ENABLED (CREDITSMARTS)'	AND E_Decisions_Enabled.LenderID	= Branch.LenderID	AND E_Decisions_Enabled.LendersBranchID		= 0		AND E_Decisions_Enabled.LoanAppID	= 0		AND E_Decisions_Enabled.LoanApp_BidID	= 0		AND E_Decisions_Enabled.DealerID	= 0    AND E_Decisions_Enabled.DataValue   <> ''
		LEFT JOIN tblPartnerDataElement			E_URL_Generic			WITH (NOLOCK) ON	Tool.PartnerToolID	= E_URL_Generic.PartnerToolID			AND	E_URL_Generic.Field			= 'POST_URL'						AND	E_URL_Generic.LenderID			= 0					AND E_URL_Generic.LendersBranchID			= 0		AND E_URL_Generic.LoanAppID			= 0		AND E_URL_Generic.LoanApp_BidID			= 0		AND E_URL_Generic.DealerID			= 0    AND E_URL_Generic.DataValue         <> ''
	WHERE
		Tool.IsCreditSmarts				<> 1								AND
		Tool.IsInternal					<> 1								AND
		Tool.Active						<> 0								AND
		Lender.LenderStatus				<> 'INACTIVE'						AND
		E_Decisions_Enabled.DataValue	IN ('TRUE', 'T', '1', 'YES', 'Y')
	GROUP BY
		Tool.PartnerToolID,
		Lender.LenderID,
		Branch.LendersBranchID
	ORDER BY
		Tool.PartnerToolID,
		Lender.LenderID,
		Branch.LendersBranchID


GO

