/****** Object:  View dbo.viewB2B_Lender_GlobalToolStatus_test    Script Date: 7/31/2024 12:57:16 PM ******/






CREATE VIEW viewB2B_Lender_GlobalToolStatus_test AS
	SELECT TOP 100 PERCENT
		L.LenderID,
		L.LenderName,
		PT.PartnerToolID,
		ShortName = CASE
			WHEN PT.ShortName IN (NULL, '') THEN
				'PARTNER_' + LTRIM(RTRIM(STR(PT.PartnerToolID)))
			ELSE
				PT.ShortName
		END,

		DisplayName = CASE
			WHEN PT.DisplayName IN (NULL, '') AND PT.ShortName IN (NULL, '') THEN
				'Partner # ' + LTRIM(RTRIM(STR(PT.PartnerToolID)))
			WHEN PT.DisplayName IN (NULL, '') THEN
				PT.ShortName
			ELSE
				PT.DisplayName
			END,				

		Enabled = CASE
			WHEN
				EXISTS(SELECT * FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.PartnerToolID = PT.PartnerToolID  AND  PDE.LenderID = L.LenderID AND Field='Lender Enabled (CreditSmarts)' AND DataValue='TRUE')
					THEN	CONVERT(BIT, 1)
					ELSE	CONVERT(BIT, 0)
			END
	
	FROM
					tblLenders				L		WITH (NOLOCK)				
		CROSS JOIN	tblPartnerTools			PT		WITH (NOLOCK)		
	
	WHERE
		EXISTS (
			SELECT
				*
			FROM
				tblPartnerElementDefinition		PED		WITH (NOLOCK)
			WHERE
				(PED.PartnerToolID = PT.PartnerToolID)
				AND 	Field = 'Lender Enabled (CreditSmarts)'
				AND		ShowOnLenderAdmin = 1
				AND		KeyedFromLenderID = 1
--				and ped.partnertoolid=2
--				and ped.partnertoolid=8
			)

--			AND ((NOT PartnerToolID IN (18,21)) OR (LenderID in (1037,227,60) ))
			AND ((NOT PartnerToolID IN (18)) OR (LenderID in (1037,227,60) ))

	
	ORDER BY
		PT.ShortName
--		L.LenderID,		PT.PartnerToolID












