/****** Object:  View dbo.viewB2B_LendersActiveForPartner    Script Date: 7/31/2024 12:57:16 PM ******/


--ALTER  VIEW view_B2B_LendersActiveForPartnerTool AS
CREATE VIEW viewB2B_LendersActiveForPartner AS
  SELECT TOP 100 PERCENT * FROM
    (SELECT DISTINCT TOP 100 PERCENT
      PT.PartnerToolID,
      PartnerCode = PT.ShortName,
      Partner = PT.DisplayName,
      LENDER.LenderID,
      LenderName = UPPER(LENDER.LenderName),
      AuthorizedByCS = CASE
        WHEN EXISTS(SELECT * FROM  tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.PartnerToolID = PT.PartnerToolID AND PDE.LenderID = LENDER.LenderID AND Field='Lender Enabled (CreditSmarts)' AND DataValue='TRUE')
          THEN CONVERT(BIT, 1)
        ELSE CONVERT(BIT, 0)
      END,

		PartnerActive			= ISNULL(PT.Active, 0),
		PartnerLogo				= ISNULL(PT.Logo, ''),
		PartnerInformationURL	= ISNULL(PT.InformationURL, ''),
		PartnerSignUpURL		= ISNULL(PT.SignUpURL, ''),
		PartnerLoginURL                        = ISNULL(PT.LoginURL, ''),
		IndDealerNeedsCS                = ISNULL(PT.IndDealerNeedsCS, 0),
		IndDealerLenderActivation       = ISNULL(PT.IndDealerLenderActivation, 0),
		FranchiseDealer                 = ISNULL(PT.FranchiseDealer, 0),
		FranDealerNeedsCS               = ISNULL(PT.FranDealerNeedsCS, 0),
		FranDealerLenderActivation      = ISNULL(PT.FranDealerLenderActivation, ''),
		IsChannel                       = ISNULL(PT.IsChannel, 0),
		IsInternal                      = ISNULL(PT.IsInternal, 0),
		IsCreditSmarts                  = ISNULL(PT.IsCreditSmarts, 0),
		Type                            = ISNULL(PT.TYPE, 0)

    FROM
      tblLenders LENDER WITH (NOLOCK),
      tblPartnerTools PT WITH (NOLOCK)
    ) TABLE_X

--	WHERE PartnerToolID = 12

  ORDER BY
    AuthorizedByCS DESC,
	Partner,
    LenderName





