/****** Object:  View dbo.viewB2B_LendersInterfacesForReceive    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewB2B_LendersInterfacesForReceive AS

	SELECT TOP 100 PERCENT
		LendersInterfaceID	= Interface.LendersInterfaceID,
		LenderID			= Interface.LenderID,
		LenderCompanyCode	= Lender.LoginPrefix,
		BranchCompanyCode	= Branch.LoginPrefix,
		LendersBranchID		= ISNUlL(Interface.LendersBranchID, BraNCh.LendersBranchID),
		PartnerCode			= Interface.PartnerCode,
		ReceiveActive		= ISNULL(Interface.ReceiveActive,	0),
		ReceiveTest			= ISNULL(Interface.ReceiveTest,		0),
		ReceiveCustom		= ISNULl(Interface.ReceiveCustom,	0)		
	FROM
				tblLendersInterfaces 		Interface		WITH (NOLOCK)
		JOIN	tblLenders					Lender			WITH (NOLOCK) ON Lender.LenderID	= Interface.LenderID
		JOIN	tblLendersBranches 			Branch			With (NOLOCK) ON Branch.LenderID	= Lender.LenderID
	WHERE
		Interface.ReceiveActive	= 1
		AND Lender.LoginPrefix NOT IN ('turned off')
		AND Lender.LenderID <> 1091
	ORDER BY
		InterfaCe.PartnerCOde
		




