/****** Object:  View dbo.viewB2B_LoanChannelPartners    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewB2B_LoanChannelPartners AS
	SELECT TOP 100 PERCENT
		PartnerToolID		= ISNULL(TOOLS.PartnerToolID,	0),
		PartnerTool			= ISNULL(TOOLS.ShortName,		0),
		PartnerName			= ISNULL(TOOLS.DisplayName,		0),
		Dealer				= ISNULL(TOOLS.Dealer,			0),
		FranchiseDealer		= ISNULL(TOOLS.FranchiseDealer,	0),
		Lender				= ISNULL(TOOLS.Lender,			0),
		LenderBranch		= ISNULL(TOOLS.LenderBranch,	0)
	FROM 
		tblPartnerTools		TOOLS		WITH (NOLOCK)
	
	WHERE
			ISNULL(TOOLS.IsChannel,			1)	=	1 
		AND	ISNULL(TOOLS.IsInternal,		0)	=	0
		AND	ISNULL(TOOLS.IsCreditSmarts,	0)	=	0
		AND ISNULL(TOOLS.Active,			0)	=	1
		AND ISNULL(DisplayName,				'') <>	'Internal'
		AND ISNULL(DisplayName,				'') <>	'Internal'
		AND ISNULL(ShortName, 				'')	<>	'CreditSmarts'
		AND ISNULL(ShortName, 				'')	<>	'CreditSmarts'
	ORDER BY
		TOOLS.PartnerToolID




