/****** Object:  View dbo.viewB2B_MissingPartnerDataElement    Script Date: 7/31/2024 12:57:16 PM ******/

--DROP VIEW viewB2B_PossiblyMissingPartnerDataElement;

CREATE VIEW viewB2B_MissingPartnerDataElement AS
	SELECT TOP 100 PERCENT
		PDE.PartnerToolID,
		PDE.DealerID,
		PDE.LenderID,
		PDE.LendersBranchID,
		PDE.LoanAppID,
		BID_2.LoanApp_BidID,
		PDE.Active,
		PDE.Field,
		PDE.DataValue,	
		PDE.COMMENTS,
		PDE.CreateDateTime,
		PDE.UpdateDateTime,
		PDE.CreateUser,
		PDE.UpdateUser,
		PDE.rowVersion
	
	FROM
						tblPartnerDataElement		PDE		WITH (NOLOCK)
		INNER JOIN		tblLoanApp_Bids				BID		WITH (NOLOCK)	ON BID.LoanApp_BidID = PDE.LoanApp_BidID
		LEFT OUTER JOIN	tblLoanApp_Bids				BID_2	WITH (NOLOCK)	ON BID_2.LoanAppID = BID.LoanAppID AND BID_2.LendersBranchID = BID.LendersBranchID
	WHERE
			PDE.CreateDateTime > '2012-12-20'
		AND	ISNULL(PDE.LoanApp_BidID, 0) > 0
		AND	NOT EXISTS(
			SELECT
				* 
			FROM
				tblPartnerDataElement	PDE_INNER
			WHERE
					PDE_INNER.LoanApp_BidID = BID_2.LoanApp_BidID
				AND PDE_INNER.Field = PDE.Field)
	ORDER BY
		PDE.CreateDateTime DESC





