CREATE VIEW viewB2B_OutboundInitialStats_2013_04_25 AS
	--DECLARE @_BID_ID INT; SET @_BID_ID = 465516;

	SELECT
		LoanAppID					= BID.LoanAppID,
		AppAge 						= DATEDIFF(s, APP.UPDATEDATETIME, GETDATE()),
	
		LoanApp_BidID				= LoanApp_BidID,
		BidAge 						= DATEDIFF(s, BID.UpdateDateTime, GETDATE()),
	
		LenderID 					= LENDER.LenderID,
		LenderCompanyCode			= LENDER.LoginPrefix,
		LenderAge					= DATEDIFF(s, LENDER.UpdateDateTime, GETDATE()),
	
		LendersBranchID				= BID.LendersBranchID,
		BranchCompanyCode 			= BRANCH.LoginPrefix,
		BranchAge					= DATEDIFF(s, BRANCH.UpdateDateTime, GETDATE()),
	
		DealerID					= DEALER.DealerID,
		DealerCompanyCode			= DEALER.LoginPrefix,
		DealerAge					= DATEDIFF(s, DEALER.UpdateDateTime, GETDATE()),
	
		UnderwritingID				= (SELECT UnderwritingID FROM tblLoanApp_Underwriting U WHERE U.LoanAppID = APP.LoanAppID AND U.LenderID = LENDER.LenderID),
		UnderwritingAge				= (SELECT DATEDIFF(s, U.UpdateDateTime, GETDATE()) FROM tblLoanApp_Underwriting U WHERE U.LoanAppID = APP.LoanAppID AND U.LenderID = LENDER.LenderID)
	
	FROM
					tblLoanApp_Bids			BID		WITH (NOLOCK)
		INNER JOIN	tblLoanApps				APP		WITH (NOLOCK) ON APP.LoanAppID				= BID.LoanAppID
		INNER JOIN	tblLendersBranches 		BRANCH	WITH (NOLOCK) ON BRANCH.LendersBranchID		= BID.LendersBranchID
		INNER JOIN	tblLenders 				LENDER	WITH (NOLOCK) ON LENDER.LenderID			= BRANCH.LenderID
		INNER JOIN	tblDealers 				DEALER	WITH (NOLOCK) ON DEALER.DealerID			= APP.DealerID
	--WHERE	BID.LoanApp_BidID = @_BID_ID






