/****** Object:  View dbo.viewB2B_PartnerAuthentication_2013_04_25    Script Date: 7/31/2024 12:57:16 PM ******/

--ALTER VIEW viewB2B_PartnerAuthentication 

CREATE VIEW viewB2B_PartnerAuthentication_2013_04_25 AS
SELECT TOP 100 PERCENT
	PDE_USER.PartnerToolID,
	PartnerCode = PARTNER_TOOL.ShortName,
	PartnerName = PARTNER_TOOL.DisplayName,
	PDE_USER.LenderID,
	PDE_USER.LendersBranchID,
	PDE_USER.DealerID,
	AuthUser = PDE_USER.DataValue,
	AuthPassword = PDE_PASSWORD.DataValue


FROM
				tblPartnerTools						PARTNER_TOOL	WITH (NOLOCK)
		JOIN	tblPartnerDataElement				PDE_USER		WITH (NOLOCK)	ON	PARTNER_TOOL.PartnerToolID = PDE_USER.PartnerToolID
		JOIN	tblPartnerDataElement				PDE_PASSWORD 	 WITH (NOLOCK)	ON  PDE_PASSWORD.PartnerToolID =  PARTNER_TOOL.PartnerToolID
WHERE
			PDE_USER.FIELD 			IN 	('POST_AUTH_USER', 'POST_USER')
	AND 	PDE_PASSWORD.FIELD		IN	('POST_AUTH_PASSWORD', 'POST_PASSWORD')
	AND		ISNULL(PDE_USER.DealerID, 0)		= ISNULL(PDE_PASSWORD.DealerID, 0)
	AND		ISNULL(PDE_USER.LenderID, 0)		= ISNULL(PDE_PASSWORD.LenderID, 0)
	AND		ISNULL(PDE_USER.LendersBranchID, 0)	= ISNULL(PDE_PASSWORD.LendersBranchID, 0)
ORDER BY
	PARTNER_TOOL.PartnerToolID,
	PDE_USER.LenderID,
	PDE_USER.LendersBranchID,
	PDE_USER.DealerID





