/****** Object:  View dbo.viewB2B_PartnerCSV_DEALERTRACK    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW [dbo].[viewB2B_PartnerCSV_DEALERTRACK] AS
SELECT TOP 100 PERCENT
  "Lender ID" = '@DealerTrackLenderID',
  "Lender Dealer ID" = DealerID,

  LegalName = CASE
    WHEN CHARINDEX('DBA', DealerName) > 0 THEN
      UPPER(SUBSTRING(DealerName, CHARINDEX('DBA', DealerName) + 4, 99))
    ELSE
      UPPER(DealerName)
    END,

  DBAName = CASE
    WHEN CHARINDEX('DBA', DealerName) > 3 THEN
      UPPER(SUBSTRING(DealerName, 1, CHARINDEX('DBA', DealerName)-2))
    ELSE
      UPPER(DealerName)
    END,

  Street = UPPER(ADDRESS),
  City = UPPER(CITY),
  State = UPPER(STATE),
  --PostalCode = REPLICATE('0', LEN(ZIP) - 5) + ZIP,
  PostalCode = REPLICATE('0', 5 - LEN(ZIP)) + CONVERT(VARCHAR(5), ZIP), 
  Phone = CONVERT(CHAR(10), DBO.stripToNumbers(TELEPHONE)),
  Fax = CONVERT(CHAR(10), DBO.stripToNumbers(FAX))
--  EftFax = '',
--  RelationMgrID = '',
--  LoanAppID = '',
--  LeaseAppID = '',
--  LoanSvcID = '',
--  LeaseSvcId = '',
--  Dept = '',
--  Street2 = '',
--  CostCenter = '',
--  "Independent Preference" = '',
--  PrimeID = '',
--  SubprimeID = '',
--  SubventedID = '',
--  VehicleType = ''
FROM
  tblDealers WITH (NOLOCK)
ORDER BY
  DealerName,
  DealerID

--WHERE
--  DealerID IN (5150, 5659, 5858, 6362, 6407, 6408, 6504, 6549, 9209, 9503, 9504, 9505, 9506, 9507, 9508, 9510, 9511, 9512, 9513, 9514, 9515, 9516, 9517, 9518, 9519, 9520, 9522, 9523, 9524, 9525, 9526, 9527, 9528, 9529, 9532, 9536, 9537, 9538, 9539, 9540, 9541, 9543, 9544, 9546, 9547, 9549, 9550, 9551, 9552, 9554, 9555, 9556, 9590, 9676, 9742, 9748, 9752, 9759, 9779, 9795, 9803, 9804, 9805, 9806, 9807, 9808, 9815, 9816, 9817, 9818, 9819, 9820);









