		Partner					= FIELDS.Partner,

		Loan_ID					= CONVERT(VARCHAR(30), ISNULL(PED_LENDER_ID.Field,			'')),
        Lender_ID               = CONVERT(VARCHAR(30), ISNULL(PED_DEALER_ID.Field,			'')),
        Dealer_ID               = CONVERT(VARCHAR(30), ISNULL(PED_LOAN_ID.Field,			'')),
        Post_Login              = CONVERT(VARCHAR(30), ISNULL(PED_AUTH_LOGIN.Field,			'')),
        Post_Password           = CONVERT(VARCHAR(30), ISNULL(PED_AUTH_PASSWORD.Field,		'')),
        Post_URL                = CONVERT(VARCHAR(30), ISNULL(PED_POST_URL.Field,			'')),
        Funding_Login           = CONVERT(VARCHAR(30), ISNULL(PED_FUNDING_LOGIN.Field,		'')),
        Funding_Password        = CONVERT(VARCHAR(30), ISNULL(PED_FUNDING_PASSWORD.Field,	'')),
        Funding_URL             = CONVERT(VARCHAR(30), ISNULL(PED_FUNDING_URL.Field,		''))
	FROM
							viewB2B_PartnerFieldNameCrossJoin_INNER		FIELDS					WITH (NOLOCK)
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_LENDER_ID			WITH (NOLOCK) ON	 					PED_LENDER_ID.PartnerElementDefinitionID			= FIELDS.Loan_ID
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_DEALER_ID			WITH (NOLOCK) ON	 					PED_DEALER_ID.PartnerElementDefinitionID			= FIELDS.Lender_ID
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_LOAN_ID				WITH (NOLOCK) ON						PED_LOAN_ID.PartnerElementDefinitionID				= FIELDS.Dealer_ID
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_AUTH_LOGIN			WITH (NOLOCK) ON	 					PED_AUTH_LOGIN.PartnerElementDefinitionID			= FIELDS.Post_Login
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_AUTH_PASSWORD		WITH (NOLOCK) ON						PED_AUTH_PASSWORD.PartnerElementDefinitionID		= FIELDS.Post_Password
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_POST_URL			WITH (NOLOCK) ON						PED_POST_URL.PartnerElementDefinitionID				= FIELDS.Post_URL
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_FUNDING_LOGIN		WITH (NOLOCK) ON	 					PED_FUNDING_LOGIN.PartnerElementDefinitionID		= FIELDS.Funding_Login
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_FUNDING_PASSWORD	WITH (NOLOCK) ON						PED_FUNDING_PASSWORD.PartnerElementDefinitionID		= FIELDS.Funding_Password
		LEFT OUTER JOIN		tblPartnerElementDefinition					PED_FUNDING_URL			WITH (NOLOCK) ON						PED_FUNDING_URL.PartnerElementDefinitionID			= FIELDS.Funding_URL




