/****** Object:  View dbo.viewB2B_PartnerFieldNameCrossJoin_INNER    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_PartnerFieldNameCrossJoin_INNER AS
	SELECT TOP 100 PERCENT
		PartnerToolID			= PARTNER_TOOLS.PartnerToolID,
		Partner					= CONVERT(VARCHAR(15), PARTNER_TOOLS.ShortName),

		Loan_ID					= MIN(PED_LOAN_ID.PartnerElementDefinitionID),
		Lender_ID				= MIN(PED_LENDER_ID.PartnerElementDefinitionID),
		Dealer_ID				= MIN(PED_DEALER_ID.PartnerElementDefinitionID),

		Post_Login				= MIN(PED_AUTH_LOGIN.PartnerElementDefinitionID),
		Post_Password			= MIN(PED_AUTH_PASSWORD.PartnerElementDefinitionID),
		Post_URL				= MIN(PED_POST_URL.PartnerElementDefinitionID),

		Funding_Login			= MIN(PED_FUNDING_LOGIN.PartnerElementDefinitionID),
		Funding_Password		= MIN(PED_FUNDING_PASSWORD.PartnerElementDefinitionID),
		Funding_URL				= MIN(PED_FUNDING_URL.PartnerElementDefinitionID)

	FROM
							tblPartnerTools					PARTNER_TOOLS			WITH (NOLOCK)
		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_LENDER_ID			WITH (NOLOCK) ON	 		PED_LENDER_ID.ValueType				= 'PARTNER_LENDER_ID'			AND PARTNER_TOOLS.PartnerToolID = PED_LENDER_ID.PartnerToolID
		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_DEALER_ID			WITH (NOLOCK) ON	 		PED_DEALER_ID.ValueType				= 'PARTNER_DEALER_ID'			AND PARTNER_TOOLS.PartnerToolID = PED_DEALER_ID.PartnerToolID

		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_LOAN_ID				WITH (NOLOCK) ON	 			PED_LOAN_ID.ValueType				IN	('PARTNER_LOAN_ID')			AND PARTNER_TOOLS.PartnerToolID = PED_LOAN_ID.PartnerToolID

		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_AUTH_LOGIN			WITH (NOLOCK) ON	 		PED_AUTH_LOGIN.ValueType			= 'PARTNER_AUTH_LOGIN'			AND PARTNER_TOOLS.PartnerToolID = PED_AUTH_LOGIN.PartnerToolID
		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_AUTH_PASSWORD		WITH (NOLOCK) ON			PED_AUTH_PASSWORD.ValueType			= 'PARTNER_AUTH_PASSWORD'		AND PARTNER_TOOLS.PartnerToolID = PED_AUTH_PASSWORD.PartnerToolID
		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_POST_URL			WITH (NOLOCK) ON			PED_POST_URL.ValueType				= 'PARTNER_POST_URL'			AND PARTNER_TOOLS.PartnerToolID = PED_POST_URL.PartnerToolID

		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_FUNDING_LOGIN		WITH (NOLOCK) ON	 		PED_FUNDING_LOGIN.ValueType			= 'PARTNER_FUNDING_LOGIN'		AND PARTNER_TOOLS.PartnerToolID = PED_FUNDING_LOGIN.PartnerToolID
		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_FUNDING_PASSWORD	WITH (NOLOCK) ON			PED_FUNDING_PASSWORD.ValueType		= 'PARTNER_FUNDING_PASSWORD'	AND PARTNER_TOOLS.PartnerToolID = PED_FUNDING_PASSWORD.PartnerToolID
		LEFT OUTER JOIN		tblPartnerElementDefinition		PED_FUNDING_URL			WITH (NOLOCK) ON			PED_FUNDING_URL.ValueType			= 'PARTNER_FUNDING_URL'			AND PARTNER_TOOLS.PartnerToolID = PED_FUNDING_URL.PartnerToolID

	WHERE
		EXISTS(	SELECT *
				FROM
					tblPartnerElementDefinition PED WITH (NOLOCK)
				WHERE
						PED.PartnerToolID = PARTNER_TOOLS.PartnerToolID
					AND ValueType IN('PARTNER_LENDER_ID', 'PARTNER_DEALER_ID', 'PARTNER_LOAN_ID', 'PARTNER_AUTH_LOGIN', 'PARTNER_AUTH_PASSWORD', 'PARTNER_POST_URL', 'PARTNER_FUNDING_LOGIN', 'PARTNER_FUNDING_PASSWORD', 'PARTNER_FUNDING_URL')
		)
	GROUP BY
		PARTNER_TOOLS.PartnerToolID,
		PARTNER_TOOLS.ShortName
	ORDER BY
		PARTNER_TOOLS.ShortName,
		PARTNER_TOOLS.PartnerToolID




GO

