/****** Object:  View dbo.viewB2B_PartnerFieldNames    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_PartnerFieldNames AS
	SELECT TOP 100 PERCENT
		PartnerToolID			= PT.PartnerToolID,				
		PartnerCode				= PT.ShortName,
		PARTNER_LENDER_ID		= ISNULL((SELECT TOP 1 Field FROM tblPartnerElementDefinition PED WITH (NOLOCK) WHERE PED.PartnerToolID = PT.PartnerToolID  AND PED.ValueType IN('LENDER_CODE','PARTNER_LENDER_ID')), '(NULL)'),
		PARTNER_AUTH_LOGIN		= ISNULL((SELECT TOP 1 Field FROM tblPartnerElementDefinition PED WITH (NOLOCK) WHERE PED.PartnerToolID = PT.PartnerToolID  AND PED.ValueType IN('PARTNER_AUTH_LOGIN')), '(NULL)'),
		PARTNER_AUTH_PASSWORD	= ISNULL((SELECT TOP 1 Field FROM tblPartnerElementDefinition PED WITH (NOLOCK) WHERE PED.PartnerToolID = PT.PartnerToolID  AND PED.ValueType IN('PARTNER_AUTH_PASSWORD')), '(NULL)'),
		PARTNER_DEALER_ID		= ISNULL((SELECT TOP 1 Field FROM tblPartnerElementDefinition PED WITH (NOLOCK) WHERE PED.PartnerToolID = PT.PartnerToolID  AND PED.ValueType IN('PARTNER_DEALER_ID')), '(NULL)'),
		PARTNER_LOAN_ID			= ISNULL((SELECT TOP 1 Field FROM tblPartnerElementDefinition PED WITH (NOLOCK) WHERE PED.PartnerToolID = PT.PartnerToolID  AND PED.ValueType IN('PARTNER_LOAN_ID')), '(NULL)'),
		PARTNER_POST_URL		= ISNULL((SELECT TOP 1 Field FROM tblPartnerElementDefinition PED WITH (NOLOCK) WHERE PED.PartnerToolID = PT.PartnerToolID  AND PED.ValueType IN('PARTNER_POST_URL')), '(NULL)')
	FROM
	  tblPartnerTools PT WITH (NOLOCK)
	




