/****** Object:  View dbo.viewB2B_PartnerFields_LenderMaster    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_PartnerFields_LenderMaster AS
SELECT TOP 100 PERCENT
  DATA_VALUE.PartnerDataElementID,
  FIELD_DEFINITION.PartnerElementDefinitionID,
  TOOLS.PartnerToolID,
  PartnerCode = TOOLS.ShortName,
  PartnerName = TOOLS.DisplayName,
  LENDER.LenderID,
  Lender = CASE
    WHEN LEN(ISNULL(LENDER.CITY, '')) > 0 AND LEN(ISNULL(LENDER.STATE, '')) > 0
      THEN UPPER(LENDER.LenderName + ' (' + LENDER.CITY + ', ' + LENDER.STATE + ')')
    WHEN LEN(ISNULL(LENDER.CITY, '')) > 0
      THEN UPPER(LENDER.LenderName + ' (' + LENDER.CITY + ')')
    WHEN LEN(ISNULL(LENDER.STATE, '')) > 0
      THEN UPPER(LENDER.LenderName + ' (' + LENDER.STATE + ')')
    ELSE
      UPPER(LENDER.LenderName)
    END,
  FIELD_DEFINITION.Caption,
  FIELD_DEFINITION.Field,
  HasValue = CASE
    WHEN LEN(ISNULL(DATA_VALUE.DataValue, '')) > 0
      THEN CONVERT(BIT, 1)
    ELSE CONVERT(BIT, 0)
    END,
  DataValue       = ISNULL(NULLIF(DATA_VALUE.DataValue, ''), '(Not Entered)'),
  CreateDateTime  = ISNULL(DATA_VALUE.CreateDateTime, FIELD_DEFINITION.CreateDateTime),
  UpdateDateTime  = ISNULL(DATA_VALUE.UpdateDateTime, FIELD_DEFINITION.UpdateDateTime),
  CreateUser      = ISNULL(DATA_VALUE.CreateUser, FIELD_DEFINITION.CreateUser),
  UpdateUser      = ISNULL(DATA_VALUE.UpdateUser, FIELD_DEFINITION.UpdateUser),
  rowVersion      = ISNULL(DATA_VALUE.rowVersion, FIELD_DEFINITION.rowVersion),
  FIELD_DEFINITION.sortSequence
FROM
  tblPartnerDataElement DATA_VALUE  WITH (NOLOCK)
  JOIN tblPartnerElementDefinition FIELD_DEFINITION  WITH (NOLOCK)ON (FIELD_DEFINITION.PartnerToolID=FIELD_DEFINITION.PartnerToolID AND FIELD_DEFINITION.ShowOnLenderAdmin = 1 AND DATA_VALUE.Field = FIELD_DEFINITION.Field)
  JOIN tblPartnerTools TOOLS WITH (NOLOCK) ON (DATA_VALUE.PartnerToolID = TOOLS.PartnerToolID)
  JOIN tblLenders LENDER  WITH (NOLOCK)ON (DATA_VALUE.LenderID = LENDER.LenderID)
WHERE
 TOOLS.Active = 1

ORDER BY
  LENDER.LenderID,
  FIELD_DEFINITION.sortSequence,
  FIELD_DEFINITION.caption






