/****** Object:  View dbo.viewB2B_PartnerIDFieldNames    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW viewB2B_PartnerIDFieldNames AS
	SELECT TOP 100 PERCENT
		PartnerToolID			= Partner.PartnerToolID,
		Field_Has_All			= ISNULL(CONVERT(BIT, CASE WHEN PED_Loan_ID.Field IS NULL OR PED_Lender_ID.Field IS NULL OR PED_Loan_ID.Field IS NULL THEN 0 WHEN LEN(PED_Loan_ID.Field) = 0 OR LEN(PED_Lender_ID.Field) = 0 OR LEN(PED_Loan_ID.Field) = 0 THEN 0 ELSE 1 END), 0),

		Field_Has_LoanID		= ISNULL(CONVERT(BIT, CASE WHEN PED_Loan_ID.Field	IS NULL THEN 0 WHEN LEN(PED_Loan_ID.Field)		= 0 THEN 0	ELSE 1 END),	0),
		Field_Has_LenderID		= ISNULL(CONVERT(BIT, CASE WHEN PED_Lender_ID.Field	IS NULL THEN 0 WHEN LEN(PED_Lender_ID.Field)	= 0 THEN 0	ELSE 1 END),	0),
		Field_Has_DealerID		= ISNULL(CONVERT(BIT, CASE WHEN PED_Dealer_ID.Field	IS NULL THEN 0 WHEN LEN(PED_Dealer_ID.Field)	= 0 THEN 0	ELSE 1 END),	0),

		Field_LoanID			= ISNULL(PED_Loan_ID.Field,		''),
		Field_LenderID			= ISNULL(PED_Lender_ID.Field,	''),
		Field_DealerID			= ISNULL(PED_Dealer_ID.Field,	'')
	FROM
					tblPartnerTools					Partner			WITH (NOLOCK)
		LEFT JOIN	tblPartnerElementDefinition		PED_Loan_ID		WITH (NOLOCK) ON PED_Loan_ID.PartnerToolID		= Partner.PartnerToolID	AND PED_Loan_ID.ValueType	= 'PARTNER_LOAN_ID'
		LEFT JOIN	tblPartnerElementDefinition		PED_Lender_ID	WITH (NOLOCK) ON PED_Lender_ID.PartnerToolID	= Partner.PartnerToolID	AND PED_Lender_ID.ValueType	= 'PARTNER_LENDER_ID'
		LEFT JOIN	tblPartnerElementDefinition		PED_Dealer_ID	WITH (NOLOCK) ON PED_Dealer_ID.PartnerToolID	= Partner.PartnerToolID	AND PED_Dealer_ID.ValueType	= 'PARTNER_DEALER_ID'
	WHERE		
		ISNULL(Partner.Active, 0)				= 1
		AND ISNULL(Partner.IsCreditSmarts, 0)	= 0
	ORDER BY
		Partner.PartnerToolID

