/****** Object:  View dbo.viewB2B_PartnerLenderElementStats    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_PartnerLenderElementStats AS
	SELECT TOP 100 PERCENT
		Partner = PT.DisplayName,
		PartnerCode = PT.ShortName,
		PDE.PartnerToolID,
		Lender = LENDER.LenderName,
		LenderCode = LENDER.LoginPrefix,
		PDE.LenderID,
		Records = Count(*),
		First = REPLACE(CONVERT(CHAR(10), MIN(PDE.CreateDateTime), 102), '.', '-'),
		Oldest = DATEDIFF(d, MIN(PDE.CreateDateTime), GETDATE()),
		Last = REPLACE(CONVERT(CHAR(10), MAX(PDE.UpdateDateTime), 102), '.', '-'),
		Newest = DATEDIFF(d, MAX(PDE.UpdateDateTime), GETDATE())
	
	FROM
					tblPartnerDataElement		PDE		WITH (NOLOCK)
		INNER JOIN	tblPartnerTools				PT		WITH (NOLOCK) ON PDE.PartnerToolID = PT.PartnerToolID
		INNER JOIN	tblLenders					LENDER	WITH (NOLOCK) ON PDE.LenderID = LENDER.LenderID
	WHERE
			(Field NOT IN('Lender Enabled (CreditSmarts)'))
		AND (NOT PDE.LenderID IN(45))
	GROUP BY
		PDE.PartnerToolID,
		PT.ShortName,
		PT.DisplayName,
		PDE.LenderID,
		LENDER.LenderName,
		LENDER.LoginPrefix
	ORDER BY
		PT.ShortName,
		LENDER.LenderName




