/****** Object:  View dbo.viewB2B_PartnerLenderID    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_PartnerLenderID AS
SELECT
ED.PartnerToolID,
PartnerCode = PT.ShortName,
ED.Field,
DE.DataValue,
LenderID = CASE
  WHEN ISNULL(DE.LenderID, 0) > 0 THEN
    DE.LenderID
  WHEN ISNULL(DE.LendersBranchID, 0) > 0 THEN
    (SELECT ISNULL(LenderID, 0) FROM tblLendersBranches LB WITH (NOLOCK) WHERE LB.LendersBranchID=DE.LendersBranchID)
  END,
DE.LendersBranchID

FROM
tblPartnerElementDefinition ED WITH (NOLOCK)
INNER JOIN tblPartnerDataElement DE WITH (NOLOCK) ON (ED.PartnerToolID = DE.PartnerToolID AND ED.ValueType = 'PARTNER_LENDER_ID')
