CREATE VIEW viewB2B_PartnerLoanIdentifier AS
SELECT
	BID.LoanApp_BidID,
	BID.LoanAppID,
	BID.LendersBranchID,
	BRANCH.LenderID,
	LID.PartnerToolID,
	LID.PartnerCode,
	LID.Field,
	PDE.DataValue

FROM
	tblLoanApp_Bids								BID		WITH (NOLOCK)
	JOIN	tblLendersBranches					BRANCH	WITH (NOLOCK)		ON BRANCH.LendersBranchID = BID.LendersBranchID
	JOIN	tblLoanApps							APP		WITH (NOLOCK)		ON BID.LoanAppID = APP.LoanAppID
	JOIN	tblDealers							DEALER	WITH (NOLOCK)		ON APP.DealerID = DEALER.DealerID
	JOIN	tblPartnerDataElement				PDE		WITH (NOLOCK)		ON PDE.LoanApp_BidID = BID.LoanApp_BidID
	JOIN	viewB2B_PartnerLoanIdentifierField	LID		WITH (NOLOCK)		ON PDE.Field = LID.Field





