/****** Object:  View dbo.viewB2B_PartnerLoanIdentifierField    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_PartnerLoanIdentifierField AS
SELECT TOP 100 PERCENT
	PT.PartnerToolID,
	PartnerCode = UPPER(PT.ShortName),
	ValueType		= 'PARTNER_LOAN_ID',
	Field	= CASE
		WHEN ShortName = 'CreditSmarts'	THEN	'LoanApp_BidID'
		WHEN LEN(PED.Field) > 0 THEN	LTRIM(RTRIM(PED.Field))
		ELSE 'ApplicationID'
	END,
	DefinedByPartner = CASE
		WHEN ShortName = 'CreditSmarts' THEN CONVERT(BIT, 0)
		WHEN LEN(PED.Field) > 0 THEN CONVERT(BIT, 0)
		ELSE CONVERT(BIT, 1)
	END
FROM
				tblPartnerTools					PT		WITH (NOLOCK)
	LEFT JOIN	tblPartnerElementDefinition		PED		WITH (NOLOCK) ON (PT.PartnerToolID=PED.PartnerToolID AND PED.ValueType='PARTNER_LOAN_ID')
ORDER BY
	PT.PartnerToolID,
	PT.ShortName




