/****** Object:  View dbo.viewB2B_PartnerLoanIdentifiers    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewB2B_PartnerLoanIdentifiers AS

SELECT
	ELEMENT.PartnerToolID,
	LoanAppID	=	CASE
		WHEN BIDS.LoanAppID IS NOT NULL			THEN BIDS.LoanAppID
		WHEN BIDS_OUTER.LoanAppID IS NOT NULL	THEN BIDS_OUTER.LoanAppID
		WHEN ELEMENT.LoanAppID <= 0				THEN NULL
		ELSE ELEMENT.LoanAppID END,

	LoanApp_BidID	= CASE
		WHEN BIDS.LoanApp_BidID	IS NOT NULL	THEN BIDS.LoanApp_BidID
		WHEN BIDS_OUTER.LoanApp_BidID	IS NOT NULL	THEN BIDS_OUTER.LoanApp_BidID
		WHEN ELEMENT.LoanApp_BidID > 0		THEN ELEMENT.LoanApp_BidID
		ELSE NULL
	END,

	ELEMENT.PartnerDataElementID,
	Identifier	= ELEMENT.FIELD,
	ID			= ELEMENT.DataValue

	FROM
						tblPartnerElementDefinition		DEFINITION_APP_ID	WITH (NOLOCK)
		INNER JOIN		tblPartnerDataElement	 		ELEMENT				WITH (NOLOCK) ON 
				ELEMENT.Field			= DEFINITION_APP_ID.Field 
			AND ELEMENT.PartnerToolID	= DEFINITION_APP_ID.PartnerToolID
			AND	ELEMENT.DataValue 		IS NOT NULL 
			AND LEN(ELEMENT.DataValue) 	> 0
			
		LEFT OUTER JOIN	tblLoanApp_Bids					BIDS				WITH (NOLOCK)
			ON (ELEMENT.LoanApp_BidID > 0 AND BIDS.LoanApp_BidID = ELEMENT.LoanApp_BidID)
--			OR (ELEMENT.LoanApp_BidID <= 0 AND ELEMENT.LoanAppID > 0 AND BIDS.LoanAppID = ELEMENT.LoanAppID)

		LEFT OUTER JOIN	tblLoanApp_Bids					BIDS_OUTER			WITH (NOLOCK)
			ON (ELEMENT.LoanApp_BidID <= 0 AND ELEMENT.LoanAppID > 0 AND BIDS_OUTER.LoanAppID = ELEMENT.LoanAppID)
			--ON (ELEMENT.LoanApp_BidID > 0 AND BIDS_OUTER.LoanApp_BidID = ELEMENT.LoanApp_BidID)
			--OR 

--		INNER JOIN		 ON DEFINITION_APP_ID.PartnerToolID = ELEMENT.PartnerToolID AND DEFINITION_APP_ID.ValueType='PARTNER_LOAN_ID' --AND 		

	WHERE
				DEFINITION_APP_ID.ValueType = 'PARTNER_LOAN_ID'
--			AND ELEMENT.Field				= DEFINITION_APP_ID.Field 
--			AND ELEMENT.PartnerToolID		= DEFINITION_APP_ID.PartnerToolID
--			AND	ELEMENT.DataValue 			IS NOT NULL 
--			AND LEN(ELEMENT.DataValue) 		> 0

--		AND	ELEMENT.F
--		DEFINITION_APP_ID.Field = ELEMENT.Field
--AND	
AND (BIDS.LoanApp_BidID IS NOT NULL OR BIDS_OUTER.LoanApp_BidID IS NOT NULL)
AND
	(
			(DEFINITION_APP_ID.KeyedFromLoanApp_BidID = 1 AND DEFINITION_APP_ID.KeyedFromLoanAppID = 1 AND (ELEMENT.LoanApp_BidID <= 0 OR ELEMENT.LoanAppID <= 0))
		OR	(DEFINITION_APP_ID.KeyedFromLoanApp_BidID = 1 AND (BIDS.LoanApp_BidID IS NULL OR ELEMENT.LoanApp_BidID <= 0))
		OR	(DEFINITION_APP_ID.KeyedFromLoanAppID = 1 AND (ELEMENT.LoanAppID <= 0))
	)





GO

