/****** Object:  View dbo.viewB2B_PartnerSequenceLock    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW viewB2B_PartnerSequenceLock AS
	SELECT 
		[PartnerToolID]					= [PDE].[PartnerToolID], 
		[LoanAppID]						= MIN([Bid].[LoanAppID]),
		[LoanApp_BidID]					= [Bid_Inner].[LoanApp_BidID]
	FROM 
				[tblLoanApp_Bids]					[Bid]			WITH (NOLOCK)
		JOIN	[tblLoanApps]						[App]			WITH (NOLOCK) ON [App].[LoanAppID]				= [Bid].[LoanAppID]
		JOIN	[tblLoanApp_Bids]					[Bid_Inner]		WITH (NOLOCK) ON [Bid_Inner].[LoanAppID]		= [Bid].[LoanAppID]
		JOIN	[tblPartnerDataElement]				[PDE]			WITH (NOLOCK) ON [PDE].[LoanApp_BidID]			= [Bid_Inner].[LoanApp_BidID]
	WHERE 
			[PDE].[PartnerToolID]			IN	(SELECT [PartnerToolID]		FROM [tblPartnerTools]				[Tool]	WITH (NOLOCK) WHERE [Tool].[ShortName]		LIKE 'ROUTEONE%')
		AND EXISTS								(SELECT	*					FROM [tblPartnerElementDefinition]	[PED]	WITH (NOLOCK) WHERE [PED].[PartnerToolID] = [PDE].[PartnerToolID] AND [PED].[Field] = [PDE].[Field])
		AND	[PDE].[DealerID]				=	0
		AND	[PDE].[LenderID]				=	0
		AND	[PDE].[LendersBranchID]			=	0
		AND	[PDE].[LoanAppID]				=	0
		AND	[PDE].[LoanApp_BidID]			>	0
		AND	[PDE].[Field]					=	'SEQUENCE'
		AND [PDE].[UpdateDateTime]			>=	DATEADD(s, -30, GETDATE())
	GROUP BY
		[PDE].[PartnerToolID], 
		[Bid_Inner].[LoanApp_BidID]

GO

