/****** Object:  View dbo.viewB2B_PartnerStatInit    Script Date: 12/14/2015 1:35:16 PM ******/

CREATE  VIEW [dbo].[viewB2B_PartnerStatInit] AS

	SELECT TOP 100 PERCENT
	  D.*,
	  TRIGGER_SEND.XML
	FROM
		(SELECT DISTINCT
			P.Active,
			B.LenderID,
			B.LenderName,
			B.LendersBranchID,
			B.BranchName,
			D.PartnerToolID,
			PartnerCode,
			URL,
			Username,
			Password,
			ISNULL(NULLIF(P.DisplayName, ''), D.PartnerCode) Name
		FROM
			viewB2B_DecisionsOutstandingToSend D WITH (NOLOCK)
		    INNER JOIN tblPartnerTools P WITH (NOLOCK) ON (D.PartnerToolID=P.PartnerToolID)
		    INNER JOIN viewLenderBranches B WITH (NOLOCK) ON (B.LendersBranchID=D.LendersBranchID)
		WHERE
			ISNULL(P.ACTIVE, 0) = 1) D

	INNER JOIN	tblPartnerToolsTriggers TRIGGER_SEND	WITH (NOLOCK)	ON	TRIGGER_SEND.PartnerToolID=D.PartnerToolID AND TRIGGER_SEND.TYPE='SEND_DECISION'

ORDER BY
  D.PartnerCode





