/****** Object:  View dbo.viewB2B_PartnerToolPostStats    Script Date: 7/31/2024 12:57:16 PM ******/

--SET NOCOUNT ON; DECLARE @_DATE_LOW DATETIME, @_DATE_HIGH DATETIME; SET @_DATE_LOW = '2013-05-08'; SET @_DATE_HIGH = GETDATE();

CREATE VIEW viewB2B_PartnerToolPostStats AS

SELECT DISTINCT
	LoanAppID				= BidsOuter.LoanAppID,
	LoanApp_CreateDateTime	= AppsOuter.CreateDateTime,
	LoanApp_UpdateDateTime	= AppsOuter.UpdateDateTime,
	LoanApp_CreateAge		= DATEDIFF(s, AppsOuter.CreateDateTime, GETDATE()),
	LoanApp_UpdateAge		= DATEDIFF(s, AppsOuter.UpdateDateTime, GETDATE()),
	LoanApp_BidID			= BidsOuter.LoanApp_BidID,
--	OriginalBidID			= (SELECT MIN(LoanApp_BidID) FROM tblLoanApp_Bids BidsInner WITH (NOLOCK) WHERE BidsInner.LoanAppID = BidsOuter.LoanAppID),
	Bid_CreateDateTime		= BidsOuter.CreateDateTime,
	Bid_UpdateDateTime		= BidsOuter.UpdateDateTime,
	Bid_CreateAge			= DATEDIFF(s, BidsOuter.CreateDateTime, GETDATE()),
	Bid_UpdateAge			= DATEDIFF(s, BidsOuter.UpdateDateTime, GETDATE()),	
	Elements_Bid			= (SELECT COUNT(*) FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LoanApp_BidID = BidsOuter.LoanApp_BidID),
	Elements_App			= (SELECT COUNT(*) FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LoanAppID = BidsOuter.LoanAppID),
	Elements_OtherBids		= (SELECT COUNT(*) FROM tblPartnerDataElement PDE WITH (NOLOCK) 
		WHERE PDE.LoanApp_BidID IN (
			SELECT LoanApp_BidID FROM tblLoanApp_Bids WHERE LoanAppID IN (
				SELECT LoanAppID FROM tblLoanApp_Bids B2 WHERE B2.LoanApp_BidID = BidsOuter.LoanApp_BidID
			)
		)
	)

FROM
			tblLoanApp_Bids		BidsOuter		WITH (NOLOCK)
	JOIN	tblLoanApps			AppsOuter		WITH (NOLOCK)		ON AppsOuter.LoanAppID = BidsOuter.LoanAppID

WHERE
		ABS(DATEDIFF(hh, GETDATE(), BidsOuter.CreateDateTime))	< 48
	OR	ABS(DATEDIFF(hh, GETDATE(), AppsOuter.CreateDateTime))	< 48
	OR	ABS(DATEDIFF(hh, GETDATE(), BidsOuter.UpdateDateTime))	< 48
	OR	ABS(DATEDIFF(hh, GETDATE(), AppsOuter.UpdateDateTime))	< 48




GO

