CREATE VIEW [dbo].[viewB2B_PartnersToUploadDealerFile] AS
	SELECT --TOP 100 PERCENT
		PartnerCode				= Partner.ShortName,
		Partner					= Partner.DisplayName,
		Lender					= DBO.ProperCase(ISNULL(Lender.LenderName, '')),
		Upload.*,
		PartnerLenderID			= ISNULL(Element_LenderID.DataValue,	''),
		PartnerLoginField		= ISNULL(Definition_LOGIN.Field,			''),
		PartnerLogin			= ISNULL(Element_Login.DataValue,		''),
		PartnerPasswordField 	= ISNULL(Element_Password.Field,		''),
		PartnerPassword 		= ISNULL(Element_Password.DataValue,	''),
		PartnerPostURL			= ISNULL(Element_URL.DataValue,			''),
	
		PartnerPostURL_DealerList		= CASE
--From: Lisa Kincade <lkincade@routeone.com>
--Sent: Monday, September 19, 2022 7:13 AM
--To: 'Sean CreditSmarts CEO' <sryan@creditsmarts.com>
--Subject: Decommission of HTTPS Dropzone - ACTION REQUIRED

--Good morning,
--You are receiving this communication because there is an
--upcoming change that may affect your RouteOne Integration.
--RouteOne will be decommissioning the HTTPS protocol for
--DLM (Dealer Lender Matching) file post to the Dropzone server
--on December 1st, 2022.  If your current procedure utilizes SFTP,
--there is no further action required. If you use either the
--HTTPS or manual methods below, you will need to switch to SFTP.
--Please see below for host and username/password details.
      WHEN Partner.PartnerToolID		= 12 THEN 'sftp://dropzone.routeone.net:3022'
	--	WHEN Partner.PartnerToolID		= 12 THEN 'https://dropzone.routeone.net/SimpleFilePost/DlmUpload'
	--	WHEN Partner.PartnerToolID		= 12 THEN 'https://12.173.222.107/cgi-bin/upload.cgi'
	--	WHEN Partner.PartnerToolID		= 2 THEN


--From: sryan@creditsmarts.com 
--Sent: Friday, January 10, 2020 12:11 AM
--To: 'Ruzzet Anafiev' 
--Subject: RE: Dealer File Upload

--Ruzzet, 
--For dealertrack the new dealer file upload url is 
--https://dtlpi.dealertrack.com/DealerFeed/DealerFileUpload.asp

		ELSE 'https://dtlpi.dealertrack.com/DealerFeed/DealerFileUpload.asp'
--		ELSE 'https://www.dealertrack.com/DealerFeed/DealerFileUpload.asp'
--		ELSE 'https://dtlpi.dealertrack.com/DealerFeed/DealerFileUpload.asp'
	
		END,
	
	  NeedsDealerFileUpload		= CASE
	    WHEN Upload.LastRequested > Upload.LastPerformed THEN 1
	    WHEN Upload.LastPerformed IS NULL AND Upload.LastRequested IS NOT NULL THEN 1
	    WHEN Upload.LastRequested IS NOT NULL AND Upload.Results IN('Processing', 'Pending') AND DATEDIFF(mi, Upload.LastRequested, GETDATE()) <= 90 THEN 1
	    ELSE 0
	  END
	FROM
					tblPartnerUpload				Upload					WITH (NOLOCK)
			 JOIN	tblPartnerTools					Partner					WITH (NOLOCK) ON	Partner.PartnerToolID					= Upload.PartnerToolID
			 JOIN	tblLenders						Lender					WITH (NOLOCK) ON	Lender.LenderID							= Upload.LenderID				AND Lender.LenderStatus					NOT IN ('INACTIVE', 'FAX')
			 JOIN	tblPartnerElementDefinition		Definition_Lender_ID	WITH (NOLOCK) ON	Definition_Lender_ID.PartnerToolID		= Partner.PartnerToolID			AND	Definition_Lender_ID.ValueType		= 'PARTNER_Lender_ID'
			 JOIN	tblPartnerDataElement			Element_LenderID		WITH (NOLOCK) ON	Element_LenderID.PartnerToolID			= Partner.PartnerToolID			AND
																								Element_LenderID.Field					= Definition_Lender_ID.Field	AND	
																								Element_LenderID.LenderID				= Lender.LenderID				AND
																								Element_LenderID.DealerID				= 0								AND
																								Element_LenderID.LoanAppID				= 0								AND
																								Element_LenderID.LoanApp_BidID			= 0								--AND


		LEFT JOIN	tblPartnerElementDefinition		Definition_Password 	WITH (NOLOCK) ON	Definition_Password.PartnerToolID		= Partner.PartnerToolID			AND	Definition_Password.ValueType		= 'PARTNER_AUTH_Password'
		LEFT JOIN	tblPartnerElementDefinition		Definition_LOGIN		WITH (NOLOCK) ON	Definition_LOGIN.PartnerToolID			= Partner.PartnerToolID			AND Definition_LOGIN.ValueType			= 'PARTNER_AUTH_LOGIN'
		LEFT JOIN	tblPartnerElementDefinition		Definition_URL			WITH (NOLOCK) ON	Definition_URL.PartnerToolID			= Partner.PartnerToolID			AND Definition_URL.ValueType			= 'PARTNER_POST_URL'

		LEFT JOIN	tblPartnerDataElement			Element_Password		WITH (NOLOCK) ON	Element_Password.PartnerToolID			= Partner.PartnerToolID			AND	Element_Password.Field				= Definition_Password.Field			AND Element_Password.LenderID		= Lender.LenderID


		LEFT JOIN	tblPartnerDataElement			Element_Login			WITH (NOLOCK) ON	Element_Login.PartnerToolID				= Partner.PartnerToolID			AND 
																								Element_Login.Field						= Definition_LOGIN.Field		AND 
																								Element_Login.LenderID					= Lender.LenderID				AND
																								Element_Login.DealerID					= 0								AND
																								Element_Login.LoanAppID					= 0								AND
																								Element_Login.LoanApp_BidID				= 0								--AND
																								
		LEFT JOIN	tblPartnerDataElement			Element_URL				WITH (NOLOCK) ON	Element_URL.PartnerToolID				= Partner.PartnerToolID			AND 
																								Element_URL.Field						= Definition_URL.Field			AND 
																								Element_URL.LenderID					= Lender.LenderID				AND
																								Element_URL.DealerID					= 0								AND
																								Element_URL.LoanAppID					= 0								AND
																								Element_URL.LoanApp_BidID				= 0								--AND



	--	JOIN viewB2B_LenderPartnerActivity LPA WITH (NOLOCK)			ON	LPA.PartnerToolID		= Upload.PartnerToolID AND LPA.LenderID		= Lender.LenderID
	WHERE
		Partner.Active			=		1				--AND
