		Partner.ShortName,
		Partner.DisplayName,
		Lender.LenderName,
		Upload.PartnerToolID,
		Upload.LenderID,
		Upload.LastPerformed,
		Upload.LastRequested,
		Upload.Results,
		Element_LenderID.DataValue,
		Definition_LOGIN.Field,
		Element_Password.Field,
		Element_Password.DataValue,
		Partner.PartnerToolID/,		
		Upload.LastRequested,
