/****** Object:  View dbo.viewB2B_Partners_Using_V3    Script Date: 7/31/2024 12:57:16 PM ******/

create  VIEW [dbo].[viewB2B_Partners_Using_V3] AS
	SELECT 
		[Partner].*
	FROM
		tblPartnerTools [Partner] WITH (NOLOCK)
		JOIN tblPartnerElementDefinition [ELEMENT] WITH (NOLOCK) ON [ELEMENT].PartnerToolID=[Partner].PartnerToolID 
