/****** Object:  View dbo.viewB2B_RightsizeLenderConfig    Script Date: 7/31/2024 12:57:16 PM ******/








CREATE VIEW [dbo].[viewB2B_RightsizeLenderConfig] AS
SELECT TOP 1 PERCENT 
--		LoanApp_BidID		= BID.LoanApp_BidID,
		LenderID		= Branch.LenderID,
		LendersBranchID		= Branch.LendersBranchID,
		PartnerToolID		= PartnerTool.PartnerToolID
		,PostURL		= ELEMENT_FUNDING_URL.DataValue,
		PostUser		= ELEMENT_FUNDING_USER.DataValue,
		PostPassword		= ELEMENT_FUNDING_PASSWORD.DataValue
		,ServerName		= PDE_FUNDING_SERVERNAME.DataValue,
		DatabaseName		= PDE_FUNDING_DATABASENAME.DataValue
	FROM
--		tblLoanApp_Bids					BID			WITH (NOLOCK)
--		INNER JOIN	tblLendersBranches				Branch		WITH (NOLOCK) ON Branch.LendersBranchID		= BID.LendersBranchID
	tblLendersBranches				Branch		WITH (NOLOCK)-- ON Branch.LendersBranchID		= BID.LendersBranchID
	INNER JOIN	tblPartnerTools				PartnerTool			WITH (NOLOCK)		ON PartnerTool.Shortname			= 'RIGHTSIZE'
		
--		INNER	JOIN	viewB2B_LenderPartnerParametersEx 	ToolParameters		WITH (NOLOCK)		ON PartnerTool.PartnerToolID		= ToolParameters.PartnerToolID		AND	ToolParameters.LendersBranchID = branch.LendersBranchID

	LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_URL				WITH (NOLOCK)	ON	PartnerTool.PartnerToolID	= ELEMENT_FUNDING_URL.PartnerToolID				AND ELEMENT_FUNDING_URL.Field			= 'POST_URL_FOR_FUNDING'						AND ELEMENT_FUNDING_URL.LenderID		= BRANCH.LenderID
	LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_USER			WITH (NOLOCK)   ON	PartnerTool.PartnerToolID	= ELEMENT_FUNDING_USER.PartnerToolID			AND ELEMENT_FUNDING_USER.Field			= 'POST_USER_FOR_FUNDING'			AND ELEMENT_FUNDING_USER.LenderID		= BRANCH.LenderID
	LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_PASSWORD		WITH (NOLOCK)   ON	PartnerTool.PartnerToolID	= ELEMENT_FUNDING_PASSWORD.PartnerToolID		AND ELEMENT_FUNDING_PASSWORD.Field		= 'POST_PASSWORD_FOR_FUNDING'		AND ELEMENT_FUNDING_PASSWORD.LenderID	= BRANCH.LenderID
	LEFT JOIN tblPartnerDataElement		ELEMENT_DECISIONS_ENABLED		WITH (NOLOCK)	ON	PartnerTool.PartnerToolID	= ELEMENT_DECISIONS_ENABLED.PartnerToolID		AND ELEMENT_DECISIONS_ENABLED.Field		= 'Lender Enabled (CreditSmarts)' 	AND ELEMENT_DECISIONS_ENABLED.LenderID	= BRANCH.LenderID

	LEFT JOIN tblPartnerDataElement				PDE_FUNDING_SERVERNAME			WITH (NOLOCK)
		ON  PDE_FUNDING_SERVERNAME.PartnerToolID = PartnerTool.PartnerToolID
		AND PDE_FUNDING_SERVERNAME.LenderID = Branch.LenderID
		AND PDE_FUNDING_SERVERNAME.Field='POST_SERVERNAME_FOR_FUNDING'
		AND PDE_FUNDING_SERVERNAME.Active = 1

	LEFT JOIN tblPartnerDataElement				PDE_FUNDING_DATABASENAME			WITH (NOLOCK)
		ON PDE_FUNDING_DATABASENAME.PartnerToolID = PartnerTool.PartnerToolID
		AND PDE_FUNDING_DATABASENAME.LenderID = Branch.LenderID
		AND PDE_FUNDING_DATABASENAME.Field='POST_DATABASENAME_FOR_FUNDING'
		AND PDE_FUNDING_DATABASENAME.Active = 1



		
	WHERE		--pp_bidid=931628	
			ISNULL(PartnerTool.IsCreditSmarts, 	0	) 	=	0
		AND	ISNULL(PartnerTool.IsInternal,		0	)	=	0
		AND	ISNULL(PartnerTool.Active,		1	)	=	1
		AND	ISNULL(ELEMENT_DECISIONS_ENABLED.DataValue, 'N'	)	IN	('TRUE', 'T', '1', 'YES', 'Y')

		AND (NOT	(		
						NULLIF(ELEMENT_FUNDING_URL.DataValue,			'')		IS NULL
						AND	NULLIF(ELEMENT_FUNDING_USER.DataValue,			'')		IS NULL
						AND	NULLIF(ELEMENT_FUNDING_PASSWORD.DataValue,		'')		IS NULL
					)
			)			
--branch.lenderid=45




















