/****** Object:  View dbo.viewB2B_TitleInsuranceStatus_Backfill    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewB2B_TitleInsuranceStatus_Backfill AS

SELECT TOP 100 PERCENT
  FundingCheckListID = FCTI.FundingCheckListID,
  LenderID = FC.LenderID,
  LoanAppID = FC.LoanAppID,
  LoanApp_BidID = CONVERT(int, REPLACE(ApplicationNumber, CONVERT(VARCHAR(64), FC.LoanAppID) + '-', '')),
  Status = STATUS,
  LastStatusChangeHoursAgo = DATEDIFF(hh, DATEADD(hh, -2, STATUS_DATE), GETDATE()),
  LastStatusChangeMinutesAgo = DATEDIFF(mi, DATEADD(hh, -2, STATUS_DATE), GETDATE()),
  STATUS_DATE = STATUS_DATE,
  LAST_CHECK_DATE = ISNULL(FCTI.UpdateDateTime, STATUS_DATE),
  LastCheckHoursAgo = DATEDIFF(hh, ISNULL(FCTI.UpdateDateTime, STATUS_DATE), GETDATE()),
	LastCheckMinutesAgo = DATEDIFF(mi, ISNULL(FCTI.UpdateDateTime, STATUS_DATE), GETDATE()),
  ApplicationNumber
FROM
  tblLoanApp_FundingChecklist_TitleInsurance FCTI WITH (NOLOCK)
  JOIN tblLoanApp_FundingCheckList FC WITH (NOLOCK) ON (FC.FundingCheckListID = FCTI.FundingCheckListID)
WHERE
	Status NOT IN ('Deal Cancelled By Borrower', 'Delete and Remove from View', 'Registration Validated', 'DEV_KILL')
	AND DATEDIFF(mi, DATEADD(hh, -2, STATUS_DATE), GETDATE()) > 90
	AND DATEDIFF(hh, DATEADD(hh, -2, STATUS_DATE), GETDATE()) < 1000
	AND DATEDIFF(mi, ISNULL(FCTI.UpdateDateTime, STATUS_DATE), GETDATE()) > 30

	AND	(NOT STATUS='NONE' AND DATEDIFF(mi, ISNULL(FCTI.UpdateDateTime, STATUS_DATE), GETDATE()) < 30)




ORDER BY   FCTI.UpdateDateTime DESC






