/****** Object:  View dbo.viewB2B_TrafficDateTime    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewB2B_TrafficDateTime AS
	SELECT
		LoanAppID		= Bids.LoanAppID,
		LoanApp_BidID	= Bids.LoanApp_BidID,
		PartnerToolID	= Partner_Tool.PartnerToolID,
		Partner			= UPPER(Partner_Tool.ShortName),
		Offer_Date		= DBO.StripToSeconds(ISNULL(Bids.Offer_Date, Bids.UpdateDateTime)),
		LastMessage		= DBO.StripToSeconds((SELECT MAX(DateTime) FROM tblLoanApp_Bids_CommentLog CL WITH (NOLOCK) WHERE CL.LoanApp_BidID = Bids.LoanApp_BidID AND [From] = 'LENDER')),
		LastSent		= DBO.StripToSeconds(CONVERT(DATETIME, CASE WHEN ISDATE(PDE_LAST_Sent.DataValue) = 1 THEN PDE_LAST_Sent.DataValue END)),
		BidStatus		= Bids.Status,
		LenderID		= Branch.LenderID,
		LenderName		= DBO.ProperCase(Lender.LenderName),
		LendersBranchID	= Branch.LendersBranchID,
		DealerID		= Dealer.DealerID,
		Dealer			= DBO.ProperCase(Dealer.DealerName),
		DealerLocation	= DBO.ProperCase(Dealer.City) + ', ' + UPPER(Dealer.State)
	FROM
					 tblLoanApp_Bids					Bids			WITH (NOLOCK)
				JOIN tblLoanApps						Application		WITH (NOLOCK) ON		Application.LoanAppID			= Bids.LoanAppID
				JOIN tblDealers							Dealer			WITH (NOLOCK) ON		Dealer.DealerID					= Application.DealerID
				JOIN tblLendersBranches					Branch			WITH (NOLOCK) ON 		Branch.LendersBranchID			= Bids.LendersBranchID
				JOIN tblLenders							Lender			WITH (NOLOCK) ON		Lender.LenderID					= Bids.LenderID
				JOIN tblPartnerDataElement				PDE				WITH (NOLOCK) ON		PDE.LoanApp_BidID				= Bids.LoanApp_BidID		AND PDE.CreateDateTime > '2014-01-01'
				JOIN tblPartnerTools					Partner_Tool	WITH (NOLOCK) ON 		Partner_Tool.PartnerToolID		= PDE.PartnerToolID
				JOIN tblPartnerElementDefinition		PED				WITH (NOLOCK) ON		PED.PartnerToolID				= PDE.PartnerToolID
																							AND	PED.ValueType					= 'PARTNER_LOAN_ID'
																							AND	PED.Field						= PDE.Field

		LEFT	JOIN tblPartnerDataElement				PDE_LAST_SENT	WITH (NOLOCK) ON 		PDE_LAST_SENT.LoanApp_BidID 	= Bids.LoanApp_BidID
																							AND	PDE_LAST_Sent.PartnerToolID		= PDE.PartnerToolID
																							AND	PDE_LAST_SENT.Field				= 'LastSentDateTime'
																							AND PDE_LAST_SENT.CreateDateTime	> '2014-01-01'
	WHERE
		Bids.Offer_Date	>	'2014-01-01'	--DATEADD(dd, -90, GETDATE())







GO

