/****** Object:  View dbo.viewBidDecisionStatus_Outer    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW [viewBidDecisionStatus_Outer] AS
	SELECT --TOP 500
		[LoanAppID]					= [Bid].[LoanAppID],
		[LoanApp_BidID]			= [Bid].[LoanApp_BidID],
		[LenderID]					= [Branch].[LenderID],
		[LendersBranchID]		= [Branch].[LendersBranchID],
		[Lender]						= UPPER(LEFT([Lender].[LenderName], 30)),
		[DealerID]					= [Dealer].[DealerID],
		[Dealer]						= ISNULL(UPPER(LEFT([Dealer].[DealerName], 30)), ''),
		[status]						= [Bid].[Status],
		[Offer_Date]				= [Bid].[Offer_Date],
		[isDecision]				= CONVERT(BIT, CASE WHEN [Bid].[Status] IN ('PENDING_DEALER', 'DECLINE_DEALER', 'DECLINE_LENDER', 'ACCEPTED')	THEN 1	ELSE 0 END),
		[isPending]					= CONVERT(BIT, CASE WHEN [Bid].[Status] IN ('REFERRED', 'PENDING_LENDER')																			THEN 1	ELSE 0 END),
		[Bids]							= (SELECT	COUNT(*)											FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK) JOIN [tblLendersBranches] [Branches] WITH (NOLOCK) ON [Branches].[LendersBranchID] = [Bids].[LendersBranchID] WHERE		[Bids].[LoanAppID] = [Bid].[LoanAppID] AND [Branches].[LenderID] = [Branch].[LenderID] AND [Bids].[Canceled_Date] IS NULL),
		--[Decisions]					= (	SELECT	COUNT(*) FROM		[tblLoanApp_Bids] [Bids] WITH (NOLOCK) JOIN [tblLendersBranches] [Branches] WITH (NOLOCK) ON [Branches].[LendersBranchID] = [Bids].[LendersBranchID] WHERE		[Bids].[LoanAppID] = [Bid].[LoanAppID] AND [Branches].[LenderID] = [Branch].[LenderID] AND [Bids].[Status] IN ('PENDING_DEALER', 'DECLINE_DEALER', 'DECLINE_LENDER', 'ACCEPTED') AND [Bids].[Canceled_Date] IS NULL AND [Bids].[Offer_Date] IS NOT NULL),
		--[Pendings]					= (	SELECT	COUNT(*) FROM		[tblLoanApp_Bids] [Bids] WITH (NOLOCK) JOIN [tblLendersBranches] [Branches] WITH (NOLOCK) ON [Branches].[LendersBranchID] = [Bids].[LendersBranchID] WHERE		[Bids].[LoanAppID] = [Bid].[LoanAppID] AND [Branches].[LenderID] = [Branch].[LenderID] AND [Bids].[Status] IN ('REFERRED', 'PENDING_LENDER') AND [Bids].[Canceled_Date] IS NULL),
--		[LatestDecision]		= (SELECT TOP 1 [Bids].[LoanApp_BidID]	FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK) JOIN [tblLendersBranches] [Branches] WITH (NOLOCK) ON [Branches].[LendersBranchID] = [Bids].[LendersBranchID] WHERE	[Bids].[LoanAppID] = [Bid].[LoanAppID] AND [Branches].[LenderID] = [Branch].[LenderID] AND [Bids].[Status] IN ('PENDING_DEALER', 'DECLINE_DEALER', 'DECLINE_LENDER', 'ACCEPTED') AND [Bids].[Canceled_Date] IS NULL AND [Bids].[Offer_Date] IS NOT NULL ORDER BY 	[Bids].[Offer_Date] DESC),
--		[LatestPending]			= (SELECT MAX([Bids].[LoanApp_BidID])		FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK) JOIN [tblLendersBranches] [Branches] WITH (NOLOCK) ON [Branches].[LendersBranchID] = [Bids].[LendersBranchID]	WHERE	[Bids].[LoanAppID] = [Bid].[LoanAppID] AND [Branches].[LenderID] = [Branch].[LenderID] AND [Bids].[Status] IN ('REFERRED', 'PENDING_LENDER') AND [Bids].[Canceled_Date] IS NULL),
		[CreateUser]				= [Bid].[CreateUser],
		[UpdateUser]				= [Bid].[UpdateUser],
		[CreateDateTime]		= [Bid].[CreateDateTime],
		[UpdateDateTime]		= [Bid].[UpdateDateTime],
		[RowVersion]				= [Bid].[RowVersion]
	FROM
								[tblLoanApp_Bids]								[Bid]				WITH (NOLOCK)
					JOIN	[tblLoanApps]										[App]				WITH (NOLOCK) ON	[App].[LoanAppID]							 = [Bid].[LoanAppID]
					JOIN	[tblLendersBranches]						[Branch]		WITH (NOLOCK) ON	[Branch].[LendersBranchID]		 = [Bid].[LendersBranchID]
					JOIN	[tblLenders]										[Lender]		WITH (NOLOCK) ON	[Lender].[LenderID]						 = [Branch].[LenderID]
		LEFT	JOIN	[tblDealers]										[Dealer]		WITH (NOLOCK) ON	[Dealer].[DealerID]						 = [App].[DealerID]
	WHERE
		[Bid].[Canceled_Date] IS NULL
		-- AND [Bid].[LoanAppID] = 2646461
/*
	GROUP BY
			[Partner].[PartnerToolID],
			[Bid].[LoanApp_BidID],
			[Bid].[LoanAppID],
			[Branch].[LenderID],
			[Bid].[Status],
			[Bid].[Offer_Date],
			[Bid].[Canceled_Date]
*/


