/****** Object:  View dbo.viewBid_PartnerInformation_Inner    Script Date: 7/31/2024 12:57:16 PM ******/
-- NEW
CREATE  VIEW viewBid_PartnerInformation_Inner AS
	SELECT
		LoanAppID					= Bid.LoanAppID,
		LoanApp_BidID				= Bid.LoanApp_BidID,
		PartnerCount				= COUNT(DISTINCT PDE.PartnerToolID),
		PartnerToolID				= MIN(PDE.PartnerToolID),
		PDE_ID_Application_ID		= MIN(PDE.PartnerDataElementID),
		Partner_Application_Field	= ISNULL(MIN(PDE.Field),			''),
		Partner_Application_Value	= ISNULL(MIN(PDE.DataValue), 		''),
		PartnerToolID_Other			= NULLIF(MAX(PDE.PartnerToolID),	MIN(PDE.PartnerToolID))
	FROM
					tblLoanApp_Bids					Bid			WITH (NOLOCK)
			 JOIN	tblLoanApps						App			WITH (NOLOCK) ON Bid.LoanAppID		= App.LoanAppID
   		LEFT JOIN	tblPartnerDataElement			PDE		  	WITH (NOLOCK) ON 
						PDE.PartnerDataElementID > 	9146844											

					AND PDE.LoanApp_BidID = Bid.LoanApp_BidID AND PDE.Field IN	(SELECT Field FROM tblPartnerElementDefinition PED_Inner WITH (NOLOCK) WHERE PED_Inner.PartnerToolID = PDE.PartnerToolID AND PED_Inner.ValueType = 'PARTNER_LOAN_ID')

		--LEFT JOIN	tblPartnerElementDefinition		PED			WITH (NOLOCK) ON PED.PartnerToolID		= PDE.PartnerToolID	AND PED.Field = PDE.Field AND PED.ValueType = 'PARTNER_LOAN_ID'
		--JOIN	tblPartnerTools					PARTNER		WITH (NOLOCK) ON Partner.PartnerToolID	= PDE.PartnerToolID

	/*
