		Bid.LoanApp_BidID IN(SELECT TOP 500 LoanApp_BidID FROM tblLoanApp_Bids Bid_Inner WITH (NOLOCK) ORDER BY Bid_Inner.LoanApp_BidID DESC)
	*/

