/****** Object:  View dbo.viewBids    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewBids AS
	SELECT TOP 100 PERCENT
		BIDS.LoanAppID,
		BIDS.LoanApp_BidID,
		LENDER.LenderID,	
		BRANCH.LendersBranchID,
		DEALER.DealerID,	
	
		Lender					= ISNULL(LTRIM(RTRIM(CASE
			WHEN NOT ASCII(LEFT(LENDER.LenderName, 1)) = ASCII(UPPER(LEFT(LENDER.LenderName, 1)))
				THEN UPPER(LENDER.LenderName)
			ELSE LENDER.LenderName END)), ''),

		LenderLocation			= LENDER.City + ', ' + UPPER(LENDER.State),

		Branch					= ISNULL(LTRIM(RTRIM(CASE
			WHEN NOT ASCII(LEFT(Branch.BranchName, 1)) = ASCII(UPPER(LEFT(Branch.BranchName, 1)))
				THEN UPPER(Branch.BranchName)
			ELSE Branch.BranchName END)), ''),
	
		BranchLocation			=  Branch.City + ', ' + UPPER(BRANCH.STATE),
	
		Dealer					= DEALER.DealerName,
	
		DealerLocation			= Dealer.City + ', ' + UPPER(Dealer.STATE),
	
		Applicant				= APP.APPLICANT_NAMES,
	
		App_Created				= ISNULL(APP.CreateDateTime, ISNULL(BIDS.SUBMIT_DATE, BIDS.CreateDateTime)),
		App_Created_Days_Ago	= DATEDIFF(dd, ISNULL(APP.CreateDateTime, ISNULL(BIDS.SUBMIT_DATE, BIDS.CreateDateTime)), GETDATE()),
	
		Submit_Date				= ISNULL(BIDS.SUBMIT_DATE, BIDS.CreateDateTime),
		Submit_Days_Ago			= DATEDIFF(dd, BIDS.SUBMIT_DATE, GETDATE()),
	
		Offer_Date				= BIDS.OFFER_DATE,
		Offer_Days_Ago			= DATEDIFF(dd, BIDS.OFFER_DATE, GETDATE()),
	
		Bid_Status				= BIDS.Status,
	
		Lender_Has_Credit = CONVERT(BIT, CASE
			WHEN LENDER_EX.GUID IS NOT NULL	THEN 1
			WHEN LENDER_EQ.GUID IS NOT NULL	THEN 1
			WHEN LENDER_TU.GUID IS NOT NULL	THEN 1
			ELSE 0 END),
	
		Dealer_Has_Credit = CONVERT(BIT, CASE
			WHEN DEALER_EX.GUID IS NOT NULL	THEN 1
			WHEN DEALER_EQ.GUID IS NOT NULL	THEN 1
			WHEN DEALER_TU.GUID IS NOT NULL	THEN 1
			ELSE 0 END),
	
		Lender_Bureaus				= REPLACE(LTRIM(RTRIM(
			CASE WHEN LENDER_EX.GUID IS NOT NULL	THEN 'Experian ' 	ELSE ''	END +
			CASE WHEN LENDER_EQ.GUID IS NOT NULL	THEN 'Equifax '		ELSE ''	END	+
			CASE WHEN LENDER_TU.GUID IS NOT NULL	THEN 'Trans-Union ' ELSE ''	END	)), ' ', ', '),
	
		Dealer_Bureaus = REPLACE(LTRIM(RTRIM(
			CASE WHEN DEALER_EX.GUID IS NOT NULL	THEN 'Experian ' 	ELSE '' END	+
			CASE WHEN DEALER_EQ.GUID IS NOT NULL	THEN 'Equifax '		ELSE ''	END	+
			CASE WHEN DEALER_TU.GUID IS NOT NULL	THEN 'Trans-Union ' ELSE ''	END)), ' ', ', '),

		URL_UWC = 
			'https://www.CreditSmarts.com/CreditSmarts/Underwriting/Default.ASP?SUDO_LenderID=' + LTRIM(RTRIM(STR(LENDER.LenderID))) + '&BidID='+ LTRIM(RTRIM(STR(BIDS.LoanApp_BidID))),

		URL_UWC_Local = 
			'http://127.0.0.1:81/CreditSmarts/Underwriting/Default.ASP?SUDO_LenderID=' + LTRIM(RTRIM(STR(LENDER.LenderID))) + '&BidID='+ LTRIM(RTRIM(STR(BIDS.LoanApp_BidID))),

		Primary_Score = NULLIF(BIDS.Primary_Score, -1),
		Secondary_Score = NULLIF(BIDS.Secondary_Score, -1)	
	FROM 
					tblLoanApp_Bids			BIDS		WITH (NOLOCK)
		INNER JOIN	tblLoanApps 			APP 		WITH (NOLOCK) ON APP.LoanAppID				= BIDS.LoanAppID
		INNER JOIN	tblLendersBranches		BRANCH 		WITH (NOLOCK) ON BRANCH.LendersBranchID		= BIDS.LendersBranchID 
		INNER JOIN	tblLenders				LENDER 		WITH (NOLOCK) ON LENDER.LenderID			= BRANCH.LenderID 
		
		LEFT OUTER JOIN	tblDealers			DEALER		WITH (NOLOCK) ON APP.DealerID = DEALER.DealerID
		
--		LEFT OUTER JOIN tblUniqueZipCities	LENDER_ZIP	WITH (NOLOCK) ON NULLIF(LENDER.ZIP, '') IS NOT NULL AND ISNUMERIC(LENDER.ZIP) = 1 AND LENDER.ZIP = LENDER_ZIP.ZIPCODE
--		LEFT OUTER JOIN tblUniqueZipCities	BRANCH_ZIP	WITH (NOLOCK) ON NULLIF(LENDER.ZIP, '') IS NOT NULL AND ISNUMERIC(LENDER.ZIP) = 1 AND BRANCH.ZIP = BRANCH_ZIP.ZIPCODE
--		LEFT OUTER JOIN tblUniqueZipCities	DEALER_ZIP	WITH (NOLOCK) ON NULLIF(LENDER.ZIP, '') IS NOT NULL AND ISNUMERIC(LENDER.ZIP) = 1 AND DEALER.ZIP = DEALER_ZIP.ZIPCODE
	
		LEFT OUTER JOIN	tblCreditPulls		LENDER_EX	WITH (NOLOCK) ON NULLIF(BIDS.LENDER_CREDIT_EX, '') IS NOT NULL AND NULLIF(BIDS.LENDER_CREDIT_EX, '') = LENDER_EX.GUID AND LENDER_EX.Data_Raw IS NOT NULL AND LENDER_EX.Data_XML IS NOT NULL AND DATALENGTH(LENDER_EX.Data_Raw) >= 256 AND DATALENGTH(LENDER_EX.Data_XML) >= 1024
		LEFT OUTER JOIN	tblCreditPulls		LENDER_EQ	WITH (NOLOCK) ON NULLIF(BIDS.LENDER_CREDIT_EQ, '') IS NOT NULL AND NULLIF(BIDS.LENDER_CREDIT_EQ, '') = LENDER_EQ.GUID AND LENDER_EQ.Data_Raw IS NOT NULL AND LENDER_EQ.Data_XML IS NOT NULL AND DATALENGTH(LENDER_EQ.Data_Raw) >= 256 AND DATALENGTH(LENDER_EQ.Data_XML) >= 1024
		LEFT OUTER JOIN	tblCreditPulls		LENDER_TU	WITH (NOLOCK) ON NULLIF(BIDS.LENDER_CREDIT_TU, '') IS NOT NULL AND NULLIF(BIDS.LENDER_CREDIT_EQ, '') = LENDER_TU.GUID AND LENDER_TU.Data_Raw IS NOT NULL AND LENDER_TU.Data_XML IS NOT NULL AND DATALENGTH(LENDER_TU.Data_Raw) >= 256 AND DATALENGTH(LENDER_TU.Data_XML) >= 1024
	
		LEFT OUTER JOIN	tblCreditPulls		DEALER_EX	WITH (NOLOCK) ON NULLIF(APP.DEALER_CREDIT_EX, '') IS NOT NULL AND NULLIF(APP.DEALER_CREDIT_EX, '') = DEALER_EX.GUID AND DEALER_EX.Data_Raw IS NOT NULL AND DEALER_EX.Data_XML IS NOT NULL AND DATALENGTH(DEALER_EX.Data_Raw) >= 256 AND DATALENGTH(DEALER_EX.Data_XML) >= 1024
		LEFT OUTER JOIN	tblCreditPulls		DEALER_EQ	WITH (NOLOCK) ON NULLIF(APP.DEALER_CREDIT_EQ, '') IS NOT NULL AND NULLIF(APP.DEALER_CREDIT_EQ, '') = DEALER_EQ.GUID AND DEALER_EQ.Data_Raw IS NOT NULL AND DEALER_EQ.Data_XML IS NOT NULL AND DATALENGTH(DEALER_EQ.Data_Raw) >= 256 AND DATALENGTH(DEALER_EQ.Data_XML) >= 1024
		LEFT OUTER JOIN	tblCreditPulls		DEALER_TU	WITH (NOLOCK) ON NULLIF(APP.DEALER_CREDIT_TU, '') IS NOT NULL AND NULLIF(APP.DEALER_CREDIT_TU, '') = DEALER_TU.GUID AND DEALER_TU.Data_Raw IS NOT NULL AND DEALER_TU.Data_XML IS NOT NULL AND DATALENGTH(DEALER_TU.Data_Raw) >= 256 AND DATALENGTH(DEALER_TU.Data_XML) >= 1024

	WHERE
			DATEDIFF(dd, BIDS.CreateDateTime,	GETDATE()) < 365
		OR	DATEDIFF(dd, BIDS.CreateDateTime,	GETDATE()) < 365
		OR	DATEDIFF(dd, APP.CreateDateTime,	GETDATE()) < 365
		OR	DATEDIFF(dd, APP.CreateDateTime,	GETDATE()) < 365
		OR	LENDER.LenderID = 45
		OR	DEALER.DealerID	= 1

--	ORDER BY 		BIDS.LoanApp_BidID DESC




