/****** Object:  View dbo.viewBidsAutomationPending    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE  VIEW [dbo].[viewBidsAutomationPending] AS
	SELECT
		[Bid].*
		--[CreditStatus]	= [Queue].[CreditStatus]
	FROM
				[viewBidsAutomationPending_Outer]	[Bid]			WITH (NOLOCK)
		JOIN	[tblLoanApp_Bids]					[B]				WITH (NOLOCK) ON [B].[LoanApp_BidID] = [Bid].[LoanApp_BidID]
		--LEFT JOIN	[tblLoanApp_Bids_AutomationQueue]		[Queue]		WITH (NOLOCK) ON [Queue].[LoanApp_BidID]		= [Bid].[LoanApp_BidID]
	WHERE
				[Bid].[LenderID] <> 45 AND -- while testing new service
				[Bid].[Has_Existing_Bureau]		= 1
		AND		[Bid].[NeedsPull] 						= 0
		AND	[Bid].[NeedsAutoDecline]			= 0
		AND		[Bid].[NeedsAutoOffer]				= 1
		AND (
			( 
				[Bid].[Status] IN ('PENDING_LENDER', 'PENDING_AUTOMATION') AND [Bid].[Age] >  5) --AND NOT [B].[Offered_By] LIKE 'automation@%'	)
			OR	( 
				[Bid].[Status] IN ('PROCESSING_AUTOMATION') 								AND [Bid].[Age] > 180	)
		)



