CREATE VIEW [dbo].[viewBidsAutomationPendingCreditPull] AS
	SELECT
		[Bid].*,
		[CreditStatus]	= [Queue].[CreditStatus],
		[LockedBy] 			= NULLIF([Lock].[LockedBy], '')
	FROM
							[viewBidsAutomationPending_Outer]		[Bid]			WITH (NOLOCK)
		LEFT JOIN	[tblLoanApp_Bids_AutomationQueue]		[QUEUE]		WITH (NOLOCK) ON 		[QUEUE].[LoanApp_BidID]		= [Bid].[LoanApp_BidID]
		LEFT JOIN	[SYSTEM_LOGICAL_LOCKS]							[Lock]		WITH (NOLOCK) ON 		[Lock].[Object]				= 'tblLoanApp_Bids' AND [Lock].[PrimaryKeyValue] = [Bid].[LoanApp_BidID] AND [Lock].[Scope] = 'Automation_Credit' AND [Lock].[LockExpireDateTime] > GETDATE()
