CREATE VIEW [dbo].[viewBidsAutomationPendingCreditPull_NEW] AS
	SELECT
		Bid.*,
		CreditStatus	= Queue.CreditStatus,
		Locked			= CONVERT(BIT, CASE WHEN Lock.LockID IS NOT NULL THEN 1 ELSE 0 END),
		LockedBy		= Lock.LockedBy,
		LockedByYou		= CONVERT(BIT, CASE WHEN Lock.LockID IS NULL THEN 0 WHEN Lock.LockedBy = HOST_NAME() THEN 1 ELSE 0 END)
	FROM
					viewBidsAutomationPending_Outer		Bid			WITH (NOLOCK)
		LEFT JOIN	tblLoanApp_Bids_AutomationQueue		QUEUE		WITH (NOLOCK) ON 		QUEUE.LoanApp_BidID		= Bid.LoanApp_BidID
		LEFT JOIN	SYSTEM_LOGICAL_LOCKS				Lock		WITH (NOLOCK) ON 		Lock.Object				= 'tblLoanApp_Bids'
																						AND	Lock.PrimaryKeyValue	= Bid.LoanApp_BidID
																						AND Lock.Scope				= 'Automation_Credit'
																						AND Lock.LockExpireDateTime	> GETDATE()
	WHERE
--Bid.LoanApp_BidID = 1878725


			Has_Existing_Bureau = 0
		OR	Bid.Status IN ('PENDING_AUTOMATION_3', 'PENDING_LENDER', 'PENDING_AUTOMATION', 'PROCESSING_AUTOMATION')
/*
