		Bid.LoanAppID,
		Lender.LenderID,
		Bid.LoanApp_BidID,
		Branch.LendersBranchID,
		Bid.Status,
		Canceled = CONVERT(BIT, CASE WHEN Bid.Canceled_Date IS NULL THEN 0 ELSE 1 END)
--		BidCount_Branch = (SELECT COUNT(*) FROM tblLoanApp_Bids Bid_Inner_1 WITH (NOLOCK) WHERE Bid_Inner_1.LoanAppID = Bid.LoanAppID AND Bid_Inner_1.LendersBranchID = Bid.LendersBranchID),
