/****** Object:  View dbo.viewBidsLatestDecision    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW [viewBidsLatestDecision] AS
	SELECT
		[Bid].[LoanAppID],
		[Branch].[LenderID],
		CONVERT(INTEGER, [App].[DealerID]) [DealerID],
		[BidActive].[LoanApp_BidID],
		[BidActive].[LendersBranchID],
		[BidActive].[Status],
		[BidActive].[Offer_Date]
	FROM
				[tblLoanApp_Bids]			[Bid]				WITH (NOLOCK)
		JOIN	[tblLoanApps]				[App]				WITH (NOLOCK) ON [App].[LoanAppID]				= [Bid].[LoanAppID]
		JOIN	[tblLendersBranches]		[Branch]			WITH (NOLOCK) ON [Branch].[LendersBranchID]		= [Bid].[LendersBranchID]
		JOIN	[tblLoanApp_Bids]			[BidActive]			WITH (NOLOCK) ON [BidActive].[LoanApp_BidID]	= (
			SELECT TOP 1
				[Bid_Active].[LoanApp_BidID]
			FROM
				[tblLoanApp_Bids]	[Bid_Active] WITH (NOLOCK)
			WHERE
					[Bid_Active].[LoanAppID]		 = [Bid].[LoanAppID]
				AND [Bid_Active].[CreateDateTime]	>= [App].[CreateDateTime]
				AND [Bid_Active].[Canceled_Date]	IS NULL
				AND [Bid_Active].[Offer_Date]		IS NOT NULL
				AND [Bid_Active].[Status]			IN ('PENDING_DEALER', 'DECLINE_LENDER', 'ACCEPTED')
				AND (
						[Bid_Active].[LendersBranchID]	 = [Branch].[LendersBranchID]
					OR	EXISTS(SELECT * FROM [tblLendersBranches] [Branch_Outer] WITH (NOLOCK) WHERE [Branch_Outer].[LendersBranchID] = [Bid_Active].[LendersBranchID] AND [Branch_Outer].[LenderID] = [Branch].[LenderID])
					-- [Branch_Outer].[LenderID] = [Branch].[LenderID]
					--[Bid_Active].[LendersBranchID]	IN (SELECT [Branch_Outer].[LendersBranchID] FROM [tblLendersBranches] [Branch_Outer] WITH (NOLOCK) WHERE [Branch_Outer].[LenderID] = [Branch].[LenderID])
				)
			ORDER BY
				[Bid_Active].[Offer_Date] DESC)
	WHERE
			[Bid].[CreateDateTime] >= [App].[CreateDateTime]
		AND [Bid].[Canceled_Date]	IS NULL
		AND [Bid].[Offer_Date]		IS NOT NULL
		AND [Bid].[Status]			IN ('PENDING_DEALER', 'DECLINE_LENDER', 'ACCEPTED')
		-- AND [Bid].[LoanAppID]		 = 2616887
	GROUP BY
		[Bid].[LoanAppID],
		[Branch].[LenderID],
		[App].[DealerID],
		[BidActive].[LoanApp_BidID],
		[BidActive].[LendersBranchID],
		[BidActive].[Status],
		[BidActive].[Offer_Date]


GO

