/****** Object:  View dbo.viewBidsMessaging_Combined    Script Date: 7/31/2024 12:57:16 PM ******/
--DECLARE @BidID INTEGER, @LoanAppID INTEGER; SET @BidID = 1858339; SET @LoanAppID = 2046252;
CREATE VIEW viewBidsMessaging_Combined AS
	SELECT --TOP 500
		LoanAppID					= Bid_Inner.LoanAppID,
		LenderID					= Branch_Outer.LenderID,
		LendersBranchID				= Branch_Outer.LendersBranchID,
		DealerID					= CONVERT(INTEGER, CASE WHEN ISNUMERIC(Credit_App.DealerID) = 1 THEN CONVERT(INTEGER, Credit_App.DealerID) ELSE NULL END),
		LoanApp_BidID				= Bid_Inner.LoanApp_BidID,
		LoanApp_BidID_Target		= Bid_Outer.LoanApp_BidID,
		LoanApp_Bids_CommentLogID	= Comments.LoanApp_Bids_CommentLogID,
		[From]						= CASE	WHEN NULLIF(Comments.[From],	'') IS NOT NULL		THEN Comments.[From]
											WHEN ISNULL(Comments.[To],		'') = 'LENDER'		THEN 'DEALER'
											WHEN ISNULL(Comments.[To],		'') = 'DEALER'		THEN 'LENDER'
																								ELSE 'UNKNOWN' END,
		[To]						= CASE	WHEN NULLIF(Comments.[To],		'') IS NOT NULL		THEN Comments.[To]
											WHEN ISNULL(Comments.[From],	'') = 'LENDER'		THEN 'DEALER'
											WHEN ISNULL(Comments.[From],	'') = 'DEALER'		THEN 'LENDER'
																								ELSE 'UNKNOWN' END,
		DateTime					= Comments.DateTime,
		[Read]						= CONVERT(BIT, CASE	WHEN Comments.[READ] IS NOT NULL														THEN Comments.[READ]
														WHEN Comments.[From] = 'LENDER' AND Bid_Outer.Messaging_Status = 'COMMENT_FOR_DEALER'	THEN 0
														WHEN Comments.[From] = 'DEALER' AND Bid_Outer.Messaging_Status = 'COMMENT_FOR_LENDER'	THEN 0

																																				ELSE 1 END),
		Comment						= Comments.Comment,
		CommentLength				= DATALENGTH(Comments.Comment			),
		CreateDateTime				= Comments.CreateDateTime,
		UpdateDateTime				= Comments.UpdateDateTime,
		CreateUser					= ISNULL(Comments.CreateUser,		''	),
		UpdateUser					= ISNULL(Comments.UpdateUser,		''	),
		rowVersion					= ISNULL(Comments.rowVersion, 		1	)
	FROM 
				tblLoanApp_Bids 			Bid_Inner 		WITH (NOLOCK) 
		JOIN	tblLoanApps					Credit_App		WITH (NOLOCK) ON Credit_App.LoanAppID			= Bid_Inner.LoanAppID
		JOIN	tblLendersBranches			Branch_Inner	WITH (NOLOCK) ON Branch_Inner.LendersBranchID	= Bid_Inner.LendersBranchID
		JOIN 	tblLoanApp_Bids				Bid_Outer		WITH (NOLOCK) ON Bid_Outer.LoanAppID 			= Bid_Inner.LoanAppID
		JOIN	tblLendersBranches			Branch_Outer	WITH (NOLOCK) ON Branch_Outer.LendersBranchID	= Bid_Outer.LendersBranchID		AND		Branch_Outer.LenderID	= Branch_Inner.LenderID
		JOIN	tblLoanApp_Bids_CommentLog	Comments		WITH (NOLOCK) ON Comments.LoanApp_BidID			= Bid_Outer.LoanApp_BidID
	WHERE 
			Comments.LoanApp_Bids_CommentLogID 		IS NOT		NULL
		AND Comments.Comment						IS NOT		NULL
		AND	DATALENGTH(Comments.Comment)			>			0

		--AND Bid_Inner.LoanApp_BidID IN (SELECT LoanApp_BidID FROM tblLoanApp_Bids WITH (NOLOCK) WHERE LoanAppID = @LoanAppID)
		--AND	Bid_Inner.LoanApp_BidID IN (@BidID)
		--Bid_Inner.LoanAppID IN (@LoanAppID)


