/****** Object:  View dbo.viewBidsMostRecentDecision    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewBidsMostRecentDecision AS
		SELECT
			LoanAppID					= Bid.LoanAppID,
			LoanApp_BidID				= Bid.LoanApp_BidID,
			LendersBranchID				= Bid.LendersBranchID,
			LenderID					= Bid.LenderID,
			LoanApp_BidID_New			= (
				SELECT TOP 1
					Bid_Inner.LoanApp_BidID
				FROM
							tblLoanApp_Bids			Bid_Inner		WITH (NOLOCK)
					JOIN	tblLendersBranches		Branch_Inner	WITH (NOLOCK)	ON Bid_Inner.LendersBranchID = Branch_Inner.LendersBranchID
				WHERE
									Bid_Inner.LoanAppID		=	(SELECT LoanAppID FROM tblLoanApp_Bids WITH (NOLOCK) WHERE LoanApp_BidID = Bid.LoanApp_BidID)
						AND			Branch_Inner.LenderID	=	Branch.LenderID
						AND			Bid_Inner.Canceled_Date	IS	NULL
						AND	(		(	Bid_Inner.Status	=	'PENDING_DEALER'	AND		ISNULL(Bid_Inner.PAYMENT, -1) >= 0	)
								OR		Bid_Inner.Status	=	'DECLINE_LENDER'	)
						
				ORDER BY
					Bid_Inner.LoanApp_BidID DESC
			)
		FROM 
					tblLoanApp_Bids			Bid			WITH (NOLOCK)
			JOIN	tblLendersBranches		Branch		WITH (NOLOCK) ON Branch.LendersBranchID = Bid.LendersBranchID
		WHERE
			Bid.LoanApp_BidID IN(
				SELECT
					LoanApp_BidID
				FROM
							tblLoanApp_Bids		Bid_Inner		WITH (NOLOCK)
					JOIN	tblLendersBranches	Branch_Inner	WITH (NOLOCK)	ON Branch_Inner.LendersBranchID = Bid_Inner.LendersBranchID
				WHERE
						Bid_Inner.LoanAppID		= Bid.LoanAppID 
					AND	Branch_Inner.LenderID	= Branch.LenderID
			)
		



