/****** Object:  View dbo.viewBidsSimple    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW dbo.viewBidsSimple
AS
SELECT     TOP 100 PERCENT AUTO_LOAN_APP.LoanAppID, BID.LoanApp_BidID, BID.STATUS, AUTO_LOAN_APP.APPLICANT_NAMES,
                      AUTO_LOAN_APP.VEHICLE_YEAR + ' ' + AUTO_LOAN_APP.VEHICLE_MAKE + ' ' + AUTO_LOAN_APP.VEHICLE_MODEL AS Vehicle,
                      AUTO_LOAN_APP.DealerID, DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State AS Dealer, BID.ARCHIVED AS ArchivedByDealer,
                      BID.SUBMIT_DATE AS SubmitDt, BID.SUBMIT_BY AS SubmitBy, LENDER_BRANCH.LenderID, BID.LendersBranchID,
                      LENDER_BRANCH.LenderName + N' - ' + LENDER_BRANCH.BranchName + N' (' + LENDER_BRANCH.CITY + N', ' + LENDER_BRANCH.STATE + N')' AS Lender,
                       BID.LENDER_ARCHIVED AS ArchivedByLender, BID.YIELD_TYPE AS FinType, BID.TERM AS Term, BID.PAYMENT AS Payment, BID.REBATE_PERCT,
                      BID.ADVANCE, BID.FINANCING_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT AS AppLoanAmount,
                      AUTO_LOAN_APP.UpdateDateTime AS AppChangeDt, AUTO_LOAN_APP.CreateDateTime AS AppCreateDt, BID.RATE, BID.FUNDED,
                      BID.CreateDateTime AS BidCreateDt, BID.UpdateDateTime AS BidChangeDt, BID.Stips, BID.Reasons, BID.DISCOUNT_FEE, BID.AUTOMATED,
                      BID.CANCELED_DATE, BID.OFFER_DATE, BID.OFFERED_BY, BID.FUNDED_DATE, BID.ACCEPT_DATE, BID.ACCEPT_BY, BID.COUNTER,
                      AUTO_LOAN_APP.DEALER_CREDIT_EX, AUTO_LOAN_APP.DEALER_CREDIT_TU, AUTO_LOAN_APP.DEALER_CREDIT_EQ, BID.LENDER_CREDIT_EX,
                      BID.LENDER_CREDIT_TU, BID.LENDER_CREDIT_EQ
FROM         dbo.tblLoanApps AUTO_LOAN_APP INNER JOIN
                      dbo.tblLoanApp_Bids BID ON AUTO_LOAN_APP.LoanAppID = BID.LoanAppID INNER JOIN
                      dbo.viewLenderBranches LENDER_BRANCH ON BID.LendersBranchID = LENDER_BRANCH.LendersBranchID LEFT OUTER JOIN
                      dbo.tblDealers DEALER ON AUTO_LOAN_APP.DealerID = DEALER.DealerID
ORDER BY BID.LoanApp_BidID DESC, AUTO_LOAN_APP.LoanAppID DESC





