		DealerID				= Dealer.DealerID,
		Lender					= Lender.LenderName,
		Branch					= Branch.BranchName,
		Dealer					= Dealer.DealerName,
		Customer				= Apps.Applicant_Names,
*/
		MessageCount			= ISNULL(CL.MessageCount, 0),
		FirstMessage			= CL.FirstMessage,
		LastMessage				= CL.LastMessage,
		Dealer_MessageCount		= ISNULL(CL_Dealer.MessageCount, 0),
		Dealer_FirstMessage		= CL_Dealer.FirstMessage,
		Dealer_LastMessage		= CL_Dealer.LastMessage,	
		Lender_MessageCount		= ISNULL(CL_Lender.MessageCount, 0),
		Lender_FirstMessage		= CL_Lender.FirstMessage,
		Lender_LastMessage		= CL_Lender.LastMessage
	FROM
					tblLoanApp_Bids					BIDS		WITH (NOLOCK)
/*			 JOIN	tblLoanApps						Apps		WITH (NOLOCK)	ON Apps.LoanAppID			= BIDS.LoanAppID
		LEFT JOIN	tblLendersBranches				Branch		WITH (NOLOCK)	ON Branch.LendersBranchID	= BIDS.LendersBranchID
		LEFT JOIN	tblLenders						Lender		WITH (NOLOCK)	ON Lender.LenderID			= Branch.LenderID
		LEFT JOIN	tblDealers						Dealer		WITH (NOLOCK)	ON Dealer.DealerID			= Apps.DealerID
*/
		LEFT JOIN	viewBids_CommentStats_Inner		CL 			WITH (NOLOCK)	ON CL.LoanApp_BidID			= BIDS.LoanApp_BidID	
		LEFT JOIN	viewBids_CommentStats_Inner		CL_Lender 	WITH (NOLOCK)	ON CL_Lender.LoanApp_BidID	= BIDS.LoanApp_BidID	AND CL_Lender.[From] = 'LENDER'
		LEFT JOIN	viewBids_CommentStats_Inner		CL_Dealer 	WITH (NOLOCK)	ON CL_Dealer.LoanApp_BidID	= BIDS.LoanApp_BidID	AND CL_Dealer.[From] = 'DEALER'





