/****** Object:  View dbo.viewBids_Funded    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewBids_Funded AS
	SELECT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		LenderID				= Lender.LenderID,
		DealerID				= Dealer.DealerID,
		Funded_Date				= MAX(Bid.Funded_Date)
	FROM
				tblLoanApp_Bids								BID					WITH (NOLOCK)
		JOIN	tblLoanApps									App					WITH (NOLOCK) ON	App.LoanAppID					= Bid.LoanAppID
		JOIN	tblDealers									Dealer				WITH (NOLOCK) ON	Dealer.DealerID					= App.DealerID
		JOIN	tblLendersBranches							Branch				WITH (NOLOCK) ON	Branch.LendersBranchID			= Bid.LendersBranchID
		JOIN	tblLenders									Lender				WITH (NOLOCK) ON	Lender.LenderID					= Branch.LenderID
		JOIN	tblLoanApp_Underwriting						Underwriting		WITH (NOLOCK) ON	Underwriting.LoanAppID			= Bid.LoanAppID				AND Underwriting.LenderID	= Lender.LenderID
--		JOIN	view_B2B_LendersActiveForPartnerTool		R					WITH (NOLOCK) ON	Branch.LenderID					= R.LenderID				AND R.AuthorizedByCS		= 1
--		JOIN	tblPartnerToolsTriggers						PTT					WITH (NOLOCK) ON	PTT.PartnerToolID				= R.PartnerToolID			AND PTT.TYPE				= 'EXCHANGE'
--		JOIN	tblPartnerTools								PartnerTool			WITH (NOLOCK) ON	PartnerTool.PartnerToolID		= PTT.PartnerToolID
--		JOIN	
	WHERE
			BID.FUNDED_DATE							IS NOT NULL
		--AND BID.Funded_Date						>=	DATEADD(dd, -30, GETDATE())

		AND Bid.LoanApp_BidID IN (	SELECT TOP 1
										LoanApp_BidID
									FROM
												tblLoanApp_Bids			Bid_Inner		WITH (NOLOCK)
									WHERE
											Bid_Inner.LoanAppID		= Bid.LoanAppID
										AND	Bid_Inner.Funded_Date	= Bid.Funded_Date
										AND	Bid_Inner.LendersBranchID IN (	SELECT
																				LendersBranchID
																			FROM
																						tblLendersBranches		Branch_Inner		WITH (NOLOCK)
																			WHERE
																					Branch_Inner.LenderID = Lender.LenderID		)	)

	GROUP BY
		Bid.LoanAppID,
		Bid.LoanApp_BidID,
		Lender.LenderID,
		Dealer.DealerID


/*	Having
		COUNT(*) > 1
*/
	

/*
		AND EXISTS(SELECT * FROM tblPartnerDataElement PDE_INNER WITH (NOLOCK) WHERE 
				PDE_Inner.PartnerToolID	= PTT.PartnerToolID
			AND	PDE_Inner.LoanApp_BidID	IN
				(SELECT LoanApp_BidID FROM tblLoanApp_Bids Bid_Inner WITH (NOLOCK) WHERE Bid_Inner.LoanAppID = Bid.LoanAppID 
)
*/



