/****** Object:  View dbo.viewBids_OfferIsValid    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW viewBids_OfferIsValid AS
	SELECT
		LoanAppID		= Bids.LoanAppID,
		LoanApp_BidID	= Bids.LoanApp_BidID,
		Status			= Bids.Status,
		Pending_Lender	= CONVERT(BIT,		CASE WHEN Bids.Status IN('PENDING_LENDER', 'REFERRED')			THEN 1						ELSE 0		END),
		Pending_Dealer	= CONVERT(BIT, 		CASE WHEN Bids.Status IN('PENDING_DEALER', 'DECLINE_LENDER')	THEN 1						ELSE 0		END),
		Term			= NULLIF(CONVERT(TINYINT,	CASE WHEN ISNUMERIC(Bids.Term) = 1						THEN Bids.Term				ELSE NULL	END),	0),
		Amount			= NULLIF(CONVERT(MONEY,	CASE WHEN ISNULL(Bids.Financing_Amount, 0) > 0				THEN Bids.Financing_Amount	ELSE NULL	END),	0),
		Payment			= NULLIF(CONVERT(MONEY,	CASE WHEN ISNULL(Bids.Financing_Amount, 0) > 0				THEN Bids.Financing_Amount	ELSE NULL	END),	0),
		Rate			= Bids.Rate --NULLIF(Bids.Rate, 0)
	FROM
		tblLoanApp_Bids		Bids	WITH (NOLOCK)

