/****** Object:  View dbo.viewBids_PendingLenderFunded    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewBids_PendingLenderFunded AS
	SELECT TOP 100 PERCENT
		LoanAppID		= Bids.LoanAppID,
		LoanApp_BidID	= Bids.LoanApp_BidID,
		LenderID		= Lender.LenderID,
		DealerID		= Dealer.DealerID,
		LendersBranchID	= Branch.LendersBranchID,
		Funded_Date		= Bids.Funded_Date,
		Lender			= DBO.ProperCase(Lender.LenderName),
		Dealer			= DBO.ProperCase(Dealer.DealerName) + ' (' + DBO.ProperCase(Dealer.City) + ', ' + UPPER(Dealer.State) + ')'
	FROM
				tblLoanApp_Bids				Bids		WITH (NOLOCK)
		JOIN	tblLoanApps					Apps		WITH (NOLOCK) ON Apps.LoanAppID				= Bids.LoanAppID
		JOIN	tblLendersBranches			Branch		WITH (NOLOCK) ON Branch.LendersBranchID 	= Bids.LendersBranchID
		JOIN	tblLenders					Lender		WITH (NOLOCK) ON Lender.LenderID			= Branch.LenderID
		JOIN	tblDealers					Dealer		WITH (NOLOCK) ON Dealer.DealerID			= Apps.DealerID

	WHERE 
			Bids.STATUS									IN			('PENDING_LENDER', 'REFERRED') 
		AND Bids.Funded_Date							IS			NOT NULL
		AND DATEDIFF(d, Bids.Funded_Date, GETDATE())	<=			120
		--AND Bids.Funded_Date							>=			@pLowDate
		--AND Bids.Funded_Date							<=			@pHighDate
		AND ((SELECT COUNT(*) FROM tblLoanApp_Bids B2 WITH (NOLOCK) WHERE LoanAppID = Bids.LoanAppID AND FUNDED_DATE IS NOT NULL) = 1)
	ORDER BY
		Bids.Funded_Date




