/****** Object:  View dbo.viewCityCountyState    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewCityCountyState AS
	SELECT
		City		= CITY.City,
		County		= COUNTY.County,
		State		= STATE.StateCode,
		StateName	= STATE.State,
		StateFIPS	= STATE.StateFIPS,
		CountyFIPS	= COUNTY.CountyFIPS,
		MSA			= NULLIF(CITY.MSA,	0)
	FROM
				tblCities		CITY	WITH (NOLOCK)
		JOIN	tblCounties		COUNTY	WITH (NOLOCK) ON		CITY.StateFips		= COUNTY.StateFIPS 
															AND CITY.CountyFIPS 	= COUNTY.CountyFIPS
	
		JOIN	tblStates		STATE	WITH (NOLOCK) ON		STATE.StateFips		= CITY.StateFips
															AND	STATE.IsState		= 1
	WHERE
			NULLIF(CITY.StateFIPS,		0)	IS NOT NULL
		AND	NULLIF(CITY.CountyFips, 	0)	IS NOT NULL
		AND	NULLIF(COUNTY.StateFIPS,	0)	IS NOT NULL
		AND	NULLIF(COUNTY.CountyFips, 	0)	IS NOT NULL
		AND NULLIF(CITY.City,			'')	IS NOT NULL
		AND NULLIF(COUNTY.County,		'')	IS NOT NULL
	/*ORDER BY
		STATE.StateCode,
		CITY.City,
		COUNTY.County		
	*/	
	




