/****** Object:  View dbo.viewCommentLogMetaData    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewCommentLogMetaData AS
	SELECT
		LoanAppID							= ISNULL(CLI_DEALER.LoanAppID,                    CLI_LENDER.LoanAppID),
		LoanApp_BidID						= ISNULL(CLI_DEALER.LoanApp_BidID,                CLI_LENDER.LoanApp_BidID),
		LenderID							= ISNULL(CLI_DEALER.LenderID,                     CLI_LENDER.LenderID),
		DealerID							= ISNULL(CLI_DEALER.DealerID,                     CLI_LENDER.DealerID),

		MessageCount_Dealer					= ISNULL(CLI_DEALER.MessageCount,	0),
		MessageCount_Lender                 = ISNULL(CLI_LENDER.MessageCount,	0),
		Oldest_Dealer						= DBO.SimpleDateTime(CLI_DEALER.Oldest),
		Oldest_Lender						= DBO.SimpleDateTime(CLI_LENDER.Oldest),
		Newest_Dealer						= DBO.SimpleDateTime(CLI_DEALER.Newest),
		Newest_Lender						= DBO.SimpleDateTime(CLI_LENDER.Newest),

		MessageCount						= ISNULL(CLI_DEALER.MessageCount, 0)	+	ISNULL(CLI_LENDER.MessageCount, 0),

		Oldest								= DBO.SimpleDateTime(	CASE	WHEN CLI_DEALER.Oldest		IS NULL					THEN CLI_LENDER.Oldest
																			WHEN CLI_LENDER.Oldest		IS NULL					THEN CLI_DEALER.Oldest
																			WHEN CLI_DEALER.Oldest		<=	CLI_LENDER.Oldest	THEN CLI_DEALER.Oldest
																																ELSE CLI_LENDER.Oldest END),

		Oldest_Source						= CASE	WHEN CLI_DEALER.Oldest		IS NULL					THEN 'LENDER'
													WHEN CLI_LENDER.Oldest		IS NULL					THEN 'DEALER'
													WHEN CLI_DEALER.Oldest		<=	CLI_LENDER.Oldest	THEN 'DEALER'
																										ELSE 'LENDER' END,

		Newest								= DBO.SimpleDateTime(	CASE	WHEN CLI_DEALER.Newest		IS NULL					THEN CLI_LENDER.Newest
																			WHEN CLI_LENDER.Newest		IS NULL					THEN CLI_DEALER.Newest
																			WHEN CLI_DEALER.Newest		>=	CLI_LENDER.Newest	THEN CLI_DEALER.Newest
																																ELSE CLI_LENDER.Newest END),
					
		Newest_Source						= CASE	WHEN CLI_DEALER.Newest		IS NULL					THEN 'LENDER'
													WHEN CLI_LENDER.Newest		IS NULL					THEN 'DEALER'
													WHEN CLI_DEALER.Newest		>=	CLI_LENDER.Newest	THEN 'DEALER'
																										ELSE 'LENDER' END

	FROM
					viewCommentLogMetaData_Inner		CLI_DEALER		WITH (NOLOCK)
		RIGHT JOIN	viewCommentLogMetaData_Inner		CLI_LENDER		WITH (NOLOCK) ON CLI_LENDER.LoanApp_BidID = CLI_Dealer.LoanApp_BidID AND CLI_Lender.MessageFrom = 'LENDER'
	WHERE
		CLI_DEALER.MessageFrom = 'DEALER'



