/****** Object:  View dbo.viewCommentLogMetaData_Inner    Script Date: 7/31/2024 12:57:16 PM ******/

/*BEGIN
	SET LOCK_TIMEOUT 600000;
*/

CREATE VIEW viewCommentLogMetaData_Inner AS
		SELECT
			--LoanApp_Bids_CommentLogID	= CL.LoanApp_Bids_CommentLogID,
			LoanAppID					= Bids.LoanAppID,
			LoanApp_BidID				= Bids.LoanApp_BidID,
			LenderID					= Branch.LenderID,
			DealerID					= Dealer.DealerID,
			MessageFrom					= CL.[From],
			MessageCount				= COUNT(*),
			Oldest						= MIN(CL.[DateTime]),
			Newest						= MAX(CL.[DateTime])
		FROM
					tblLoanApp_Bids_CommentLog		CL		WITH (NOLOCK)
			JOIN	tblLoanApp_Bids					Bids	WITH (NOLOCK) ON Bids.LoanApp_BidID			= CL.LoanApp_BidID
			JOIN	tblLoanApps						Apps	WITH (NOLOCK) ON Apps.LoanAppID				= Bids.LoanAppID
			JOIN	tblDealers						Dealer	WITH (NOLOCK) ON Dealer.DealerID			= Apps.DealerID
			JOIN	tblLendersBranches				Branch	WITH (NOLOCK) ON Branch.LendersBranchID		= Bids.LendersBranchID
		GROUP BY
			--CL.LoanApp_Bids_CommentLogID,
			Bids.LoanAppID,
			Bids.LoanApp_BidID,
			Branch.LenderID,
			Dealer.DealerID,
			CL.[From]
--END



