/****** Object:  View dbo.viewCreditMetaInfo    Script Date: 7/31/2024 12:57:16 PM ******/

CREATE VIEW viewCreditMetaInfo AS
	SELECT
		CreditPullID,
		GUID,
		Valid		= CONVERT(BIT, CASE
			WHEN CreateDateTime < DATEADD(d, -90, GETDATE())				THEN 0
			WHEN Data_Raw										IS NULL		THEN 0			
			WHEN Data_XML										IS NULL		THEN 0			
			WHEN LEN(ISNULL(ErrorDescription, ''))				> 0			THEN 0
			WHEN DATALENGTH(Data_XML)							< 768		THEN 0
			ELSE 1
		END),
	
		ErrorDescription
	FROM
		tblCreditPulls		WITH (NOLOCK)
	



