/****** Object:  View dbo.viewCreditPending    Script Date: 7/31/2024 12:57:16 PM ******/

--SET NOCOUNT ON;
--SET LOCK_TIMEOUT 120000;


CREATE VIEW viewCreditPending AS
	SELECT
		ID							= pendingCreditRequestID,
		GUID						= GUID,
		Server						= CASE
			WHEN CHARINDEX('\', QueuePath) > 0 THEN	'\\' + UPPER(LEFT(QueuePath, CHARINDEX('\', QueuePath) - 1))
			ELSE '' END,
		Queue						= CASE
			WHEN CHARINDEX('\', QueuePath) > 0 THEN	REPLACE(SUBSTRING(QueuePath, CHARINDEX('\', QueuePath), 999), '\PRIVATE$\', '')
			ELSE '' END,
		Bureau						= bureau,
		Member_ID					= memberid,
		--Password_Hash				= pwhash,
		SSN_Primary					= CASE
			WHEN LEN(SSN1) = 9 THEN
				SUBSTRING(SSN1, 1, 3) + '-' + SUBSTRING(SSN1, 4, 2) + '-' + SUBSTRING(SSN1, 6, 4)
			ELSE '' END,
	
		SSN_Secondary				= CASE
			WHEN LEN(SSN2) = 9 THEN
				SUBSTRING(SSN2, 1, 3) + '-' + SUBSTRING(SSN2, 4, 2) + '-' + SUBSTRING(SSN2, 6, 4)
			ELSE ''
		END,
				
		CreateDateTime				= createDateTime,
		Status						= Status
	FROM 
		tblCreditPullsPending WITH (NOLOCK)
	WHERE
		(NOT GUID IS NULL)
--ORDER BY 	PendingCreditRequestID DESC;



