/****** Object:  View dbo.viewCreditPullStatus    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewCreditPullStatus AS
SELECT -- TOP 5
	PENDING.PendingCreditRequestID,
	PULLS.CreditPullID,	
	Requested = PENDING.CreateDateTime,
	Returned = PULLS.UpdateDateTime,
--	SecondsAgo = DATEDIFF(ss, PENDING.updateDateTime, GETDATE()),
	Latency = DATEDIFF(ss, PENDING.updateDateTime, PULLS.updateDateTime),
	GUID = PENDING.GUID,
	Vendor = PENDING.Vendor,
	Status = CASE
		WHEN ISNULL(PULLS.ErrorCode, 0) = 0 AND NOT PULLS.Data_XML IS NULL THEN 'SUCCESS'
		WHEN ISNULL(PULLS.ErrorCode, 0) > 0 THEN 'ERROR_BUREAU'
		WHEN PULLS.Data_XML IS NULL AND NOT PULLS.Data_Raw IS NULL THEN 'ERROR_DECODING'
		WHEN PULLS.DATA_XML IS NULL AND PULLS.DATA_RAW IS NULL AND DATEDIFF(ss, PENDING.updateDateTime, GETDATE()) > 90 THEN 'ERROR_TIMEOUT'
		WHEN PULLS.DATA_RAW IS NULL THEN 'PENDING'
		ELSE 'ERROR_UNKNOWN'
	END,

	PULLS.ErrorCode

	FROM
					tblCreditPullsPending 	PENDING		WITH (NOLOCK)
		LEFT JOIN	tblCreditPulls			PULLS		WITH (NOLOCK)	ON	PENDING.GUID = PULLS.GUID
	WHERE
		LEN(ISNULL(memberid, '')) > 0 AND LEN(ISNULL(pwhash, '')) > 0





