--DECLARE @T CHAR(1), @T2 CHAR(2), @T3 CHAR(3), @T4 CHAR(4);
--SELECT @T = CHAR(9); SELECT @T2 = REPLACE(SPACE(16), ' ', @T), @T3 = REPLACE(SPACE(16), ' ', @T), @T4 = REPLACE(SPACE(16), ' ', @T);
--SELECT @T2 + COLUMN_NAME + @T2 + '= ISNULL(Credit.' + COLUMN_NAME + ',' + @T4 + '),' FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='tblCreditPulls' ORDER BY ORDINAL_POSITION;
--SELECT @T2 + COLUMN_NAME + @T2 + '= Credit.' + COLUMN_NAME + ',' FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='tblCreditPulls' ORDER BY ORDINAL_POSITION;

CREATE VIEW viewCreditValid AS
	SELECT
		CreditPullID			= Credit.CreditPullID,
		GUID					= Credit.GUID,
		Bureau					= Credit.Bureau,
		ErrorCode				= ISNULL(Credit.ErrorCode,			0						),
		ErrorDescription		= ISNULL(Credit.ErrorDescription,	''						),
		RawLength				= ISNULL(DATALENGTH(DATA_RAW),		0						),
		XmlLength				= ISNULL(DATALENGTH(DATA_XML),		0						),
		CreateDateTime			= ISNULL(Credit.CreateDateTime,		Credit.UpdateDateTime	),
		CreateUser				= ISNULL(Credit.CreateUser,			''						),
		UpdateDateTime			= ISNULL(Credit.UpdateDateTime,		Credit.CreateDateTime	),
		UpdateUser				= ISNULL(ISNULL(Credit.UpdateUser, Credit.CreateUser), ''	),
		rowVersion				= ISNULL(Credit.rowVersion,			1						)	
	FROM
		tblCreditPulls	CREDIT	WITH (NOLOCK)
	WHERE
			NULLIF(ErrorCode,			 0)	IS NULL
		AND	NULLIF(ErrorDescription,	'')	IS NULL
		AND NULLIF(Bureau,				'')	IS NOT NULL
		AND DATA_RAW						IS NOT NULL
		AND DATA_XML						IS NOT NULL
		AND DATALENGTH(Data_XML)			> 1000
		AND DATALENGTH(Data_Raw)			> 500




