/****** Object:  View dbo.viewCredit_OutstandingVerify    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE VIEW viewCredit_OutstandingVerify AS	
	SELECT TOP 100
		Bid.LoanApp_BidID,
		Bid.LoanAppID,
		Credit.CreditPullID,
		Credit.GUID,
		Credit.rowVersion,
		Credit.CreateDateTime,
		Credit.UpdateDateTime
	FROM
				tblLoanApp_Bids		Bid		WITH (NOLOCK)
		JOIN	tblCreditPulls		Credit	WITH (NOLOCK) ON Credit.GUID = Bid.Lender_Credit_TU
	WHERE
		NULLIF(Bid.Lender_Credit_TU, '') 	IS 	NOT NULL						AND
		DATALENGTH(Credit.Data_XML)			>=	500								AND
		Credit.rowVersion					<=	1								AND
		Credit.CreateDateTime				>=	DATEADD(dd, -30, GETDATE())
	GROUP BY
		Bid.LoanApp_BidID,
		Bid.LoanAppID,
		Credit.CreditPullID,
		Credit.GUID,
		Credit.rowVersion,
		Credit.CreateDateTime,
		Credit.UpdateDateTime
	ORDER BY
		Bid.LoanApp_BidID	DESC
		--Credit.CreditPullID DESC
	--OPTION (MAXDOP 1)


