/****** Object:  View dbo.viewCredit_ScoreReasonLookup    Script Date: 7/31/2024 12:57:16 PM ******/


CREATE VIEW viewCredit_ScoreReasonLookup AS

SELECT DISTINCT TOP 100 PERCENT
	Bureau = LTRIM(RTRIM(Bureau)),
	CardID = LTRIM(RTRIM(CardID)),
	Code = LTRIM(RTRIM(Code)),
	Description = LTRIM(RTRIM(Description)),

	Key1 = UPPER('/' + LTRIM(RTRIM(Bureau)) + '#' + LTRIM(RTRIM(CardID)) + '#' + LTRIM(RTRIM(Code)) + '\'),
	Key2 = CASE
		WHEN ISNUMERIC(Code) = 1 AND ISNUMERIC(CardID) = 1 THEN
			UPPER('/' + LTRIM(RTRIM(Bureau)) + '#' + LTRIM(STR(CONVERT(int, CardID))) + '#' + LTRIM(STR(CONVERT(int, Code))) + '\')

		WHEN ISNUMERIC(Code) = 1 THEN
			UPPER('/' + LTRIM(RTRIM(Bureau)) + '#' + LTRIM(RTRIM(CardID)) + '#' + LTRIM(STR(CONVERT(int, Code))) + '\')

		WHEN ISNUMERIC(CardID) = 1 THEN
			UPPER('/' + LTRIM(RTRIM(Bureau)) + '#' + LTRIM(STR(CONVERT(int, CardID))) + '#' + LTRIM(RTRIM(Code)) + '\')

		ELSE '/' + LTRIM(RTRIM(Bureau)) + '#' + LTRIM(RTRIM(CardID)) + '#' + Code + '\'
	END
FROM
	tblCreditPulls_ScoreReasons WITH (NOLOCK)
WHERE
	NOT	(Bureau IS NULL OR CardID IS NULL OR Description IS NULL)

ORDER BY
	Bureau,
	CardID,
	Code




