/****** Object:  View dbo.viewCredit_ScoresToBackFill    Script Date: 7/31/2024 12:57:16 PM ******/
CREATE  VIEW viewCredit_ScoresToBackFill AS
	SELECT TOP 100
		CreditPullID		= CreditPulls.CreditPullID,
		GUID				= CreditPulls.GUID,
		Credit_DateTime		= CreditPulls.CreateDateTime
	FROM
		tblCreditPulls		CreditPulls		WITH (NOLOCK)
	WHERE
		CreditPulls.CreditPullID >= (SELECT MIN(CreditPullID) FROM tblCreditPulls CP WITH (NOLOCK) WHERE CP.CreateDateTime > DATEADD(d, -14, GETDATE()))		and
		(NOT EXISTS(SELECT GUID FROM tblCredit_ScoreCardDone SCD WITH (NOLOCK) WHERE SCD.GUID = CreditPulls.GUID))											AND	
		DATALENGTH(CreditPulls.Data_Raw)		>=	500																										AND
		DATALENGTH(CreditPulls.Data_XML)		>=	512																										AND
		1 = 1
	ORDER BY
		CreditPulls.CreditPullID DESC


