/****** Object:  View dbo.viewCurrentlyLoggedIn    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewCurrentlyLoggedIn
AS

SELECT     'Dealer' TYPE, C.SessionID, C.LoginDateTime, C.REMOTE_HOST HOST, C.REMOTE_IP IP, C.SERVER, C.USER_AGENT, L.LoginPrefix + '/' + L.UserName Username, L.DealerName Company, D .City City, D .State State,
                      L.DealerID DealerID, NULL LenderID
FROM         tblCurrentlyLoggedIn C, viewDealersLogins L, tblDealers D
WHERE     C.DealersLoginID = L.DealersLoginID AND L.DealerID = D .DealerID AND DateDiff(hh, LoginDateTime, GetDate() ) <= 24

UNION

SELECT     'Lender' AS TYPE, C.SessionID, C.LoginDateTime, C.REMOTE_HOST HOST, C.REMOTE_IP IP, C.SERVER, C.USER_AGENT, L.LoginPrefix + '/' + L.UserName AS Username, L.LenderName AS Company, LBIZ.City,
                      LBIZ.State, NULL DealerID, L.LenderID
FROM         dbo.tblCurrentlyLoggedIn C INNER JOIN
                      dbo.viewLendersLogins L ON C.LendersLoginID = L.LendersLoginID INNER JOIN
                      dbo.tblLenders LBIZ ON L.LenderID = LBIZ.LenderID
WHERE DateDiff(hh, LoginDateTime, GetDate() ) <= 24

UNION

SELECT     'Lender Branch' AS TYPE, C.SessionID, C.LoginDateTime, C.REMOTE_HOST HOST, C.REMOTE_IP IP, C.SERVER, C.USER_AGENT, L.LoginPrefix + '/' + L.UserName AS Username, L.LenderName AS Company, B.CITY,
                      B.STATE, NULL AS DealerID, L.LenderID
FROM         dbo.tblCurrentlyLoggedIn C INNER JOIN
                      dbo.viewLenderBranchLogins L ON C.LendersBranchLoginID = L.LendersBranchLoginID INNER JOIN
                      dbo.tblLendersBranches B ON L.LendersBranchID = B.LendersBranchID

WHERE DateDiff(hh, LoginDateTime, GetDate() ) <= 24

UNION

SELECT     'Admin' TYPE, C.SessionID, C.LoginDateTime, C.REMOTE_HOST HOST, C.REMOTE_IP IP, C.SERVER, C.USER_AGENT, L.UserName Username, '' Company, NULL City, NULL State, NULL DealerID, NULL LenderID
FROM         tblCurrentlyLoggedIn C, viewAdminLogins L
WHERE     C.AdminLoginID = L.AdminLoginID AND DateDiff(hh, LoginDateTime, GetDate() ) <= 24

UNION

SELECT     'Affiliate' TYPE, C.SessionID, C.LoginDateTime, C.REMOTE_HOST HOST, C.REMOTE_IP IP, C.SERVER, C.USER_AGENT, L.UserName Username, Name Company, NULL City, NULL State, NULL DealerID, NULL LenderID
FROM         tblCurrentlyLoggedIn C, viewAffiliateLogins L
WHERE     C.AffiliateLoginID = L.AffiliateLoginID AND DateDiff(hh, LoginDateTime, GetDate() ) <= 24






