/****** Object:  View dbo.viewDealersAppStats    Script Date: 7/31/2024 12:57:17 PM ******/

CREATE VIEW viewDealersAppStats AS
	SELECT
		DEALER.DealerID,
		Apps				= COUNT(APP.LoanAppID),
		FirstApp			= MIN(APP.UpdateDateTime),
		LastApp				= MAX(APP.UpdateDateTime),
	
		FirstApp_DaysAgo	= DATEDIFF(dd,		MIN(APP.UpdateDateTime), GETDATE()),
		FirstApp_WeeksAgo	= DATEDIFF(ww,		MIN(APP.UpdateDateTime), GETDATE()),
		FirstApp_MonthsAgo	= DATEDIFF(month,	MIN(APP.UpdateDateTime), GETDATE()),
		
		LastApp_SecondsAgo	= DATEDIFF(ss,		MAX(APP.UpdateDateTime), GETDATE()),
		LastApp_DaysAgo		= DATEDIFF(dd,		MAX(APP.UpdateDateTime), GETDATE()),
		LastApp_WeeksAgo	= DATEDIFF(ww,		MAX(APP.UpdateDateTime), GETDATE()),
		LastApp_MonthsAgo	= DATEDIFF(month,	MAX(APP.UpdateDateTime), GETDATE())
	
	
	
	FROM
	
							tblDealers			DEALER			WITH (NOLOCK)
		LEFT OUTER JOIN 	tblLoanApps			APP				WITH (NOLOCK) 	ON	APP.DealerID = DEALER.DealerID
	
	GROUP BY
		DEALER.DealerID




