/****** Object:  View dbo.viewDriveItCRM_Loans    Script Date: 7/31/2024 12:57:17 PM ******/
create view viewDriveItCRM_Loans as 
SELECT --top 10 
	bid.loanappid,
	bid.loanapp_bidid,
	financing_amount = ISNULL(bid.financing_amount, 0) ,
	VEHICLE_WHOLESALE_ADJUSTED = ISNULL(bid.VEHICLE_WHOLESALE_ADJUSTED, 0),
	LTV = (ISNULL(bid.financing_amount, 0)/ISNULL(bid.VEHICLE_WHOLESALE_ADJUSTED, 0) ) * 100,


	BureauName		= CASE S_CreditPull.Bureau
		WHEN 'TU'		THEN	'Transunion'
		WHEN 'EX'		THEN	'Experian'
		WHEN 'EQ'		THEN	'Equifax'
		ELSE S_CreditPull.Bureau
	END,

	S_CreditPull.[CreditPullID] as CreditPullID,
	S_CreditPull.[GUID] as GUID,
	S_CreditPull.[Bureau] as Bureau,
	S.[Primary_Score] as Primary_Score,
	S.[Primary_CardID] as Primary_CardID,
	S.[Primary_Card] as Primary_Card,
	S.[Primary_Code_1] as Primary_Code_1,
	S.[Primary_Description_1] as Primary_Description_1,
	S.[Primary_Code_2] as Primary_Code_2,
	S.[Primary_Description_2] as Primary_Description_2,
	S.[Primary_Code_3] as Primary_Code_3,
	S.[Primary_Description_3] as Primary_Description_3,
	S.[Primary_Code_4] as Primary_Code_4,
	S.[Primary_Description_4] as Primary_Description_4,
	S.[Secondary_Score] as Secondary_Score,
	S.[Secondary_CardID] as Secondary_CardID,
	S.[Secondary_Card] as Secondary_Card,
	S.[Secondary_Code_1] as Secondary_Code_1,
	S.[Secondary_Description_1] as Secondary_Description_1,
	S.[Secondary_Code_2] as Secondary_Code_2,
	S.[Secondary_Description_2] as Secondary_Description_2,
	S.[Secondary_Code_3] as Secondary_Code_3,
	S.[Secondary_Description_3] as Secondary_Description_3,
	S.[Secondary_Code_4] as Secondary_Code_4,
	S.[Secondary_Description_4] as Secondary_Description_4,

	Primary_Inquiry_Code					= S.Primary_Inquiry_Code,
	Primary_Inquiry_Description			= S.Primary_Inquiry_Description,
	Primary_Reject_Code					= S.Primary_Reject_Code,
	Primary_Reject_Description			= S.Primary_Reject_Description,
	Secondary_Inquiry_Code					= S.Secondary_Inquiry_Code,
	Secondary_Inquiry_Description			= S.Secondary_Inquiry_Description,
	Secondary_Reject_Code					= S.Secondary_Reject_Code,
	Secondary_Reject_Description			= S.Secondary_Reject_Description,

	ISNULL(S_CreditPull.CreateDateTime, S_PendingCredit.UpdateDateTime) as ScoreDateTime

--bid.*

FROM [view_LoanApps_Bids] bid with (nolock)

	LEFT JOIN tblCreditPulls		S_CreditPull	WITH (NOLOCK)	
		ON S_CreditPull.GUID IN (dbo.fn_getGUID(BID.Lender_Credit_EX), dbo.fn_getGUID(BID.Lender_Credit_EQ), dbo.fn_getGUID(BID.Lender_Credit_TU))
	LEFT JOIN tblCreditPulls_Scores S WITH (NOLOCK) ON 	S.GUID = S_CreditPull.GUID
	LEFT JOIN tblCreditPullsPending	S_PendingCredit		WITH (NOLOCK)	ON S_CreditPull.GUID = S_PendingCredit.GUID

WHERE bid.[LenderID] = 1140 AND 
(LEN(LENDER_CREDIT_EX) > 0 OR LEN(LENDER_CREDIT_TU) > 0 OR LEN(LENDER_CREDIT_EQ) > 0) and 
ISNULL(S.[Primary_Score], 0) > 600 AND 
ISNULL(bid.VEHICLE_WHOLESALE_ADJUSTED, 0) > 0 and 
((ISNULL(bid.financing_amount, 0)/ISNULL(bid.VEHICLE_WHOLESALE_ADJUSTED, 0) ) * 100) > 90
--having LTV > 90
--order by bid.loanappid desc



GO

