	--AND F.DealerID *= D.DealerID
	--AND F.LenderID *= L.LenderID
	--AND F.LendersBranchID *= LB.LendersBranchID

	AND	ID = 0
	

GROUP BY
	F.FreeformID,
	F.DealerID,
	D.DealerName,
	F.LenderID,
	L.LenderName,
	F.LendersBranchID,
	F.Admin,
