/****** Object:  View dbo.viewFaxPending    Script Date: 7/31/2024 12:57:17 PM ******/

CREATE  VIEW viewFaxPending AS
	SELECT TOP 100 PERCENT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		ApplicationID			= CONVERT(VARCHAR(30), CONVERT(VARCHAR(8), Bid.LoanAppID) + '-' + CONVERT(VARCHAR(8), Bid.LoanApp_BidID)),
		LoanApp_Bids_FaxID		= Fax.LoanApp_Bids_FaxID,
		LenderID				= Branch.LenderID,
		LendersBranchID			= Branch.LendersBranchID,
		LenderName				= DBO.ProperCase(LENDER.LenderName),
		DealerID				= CONVERT(INT, App.DealerID),
		DealerName				= DBO.ProperCase(DEALER.DealerName),
		DealerLocation			= CASE
			WHEN NULLIF(Dealer.City, '') IS NULL AND NULLIF(Dealer.State, '') IS NULL 		THEN ''
			WHEN NOT (NULLIF(Dealer.City, '') IS NULL OR NULLIF(Dealer.State, '') IS NULL)	THEN DBO.ProperCase(DEALER.City) + ', ' + UPPER(DEALER.State)
			WHEN NOT (NULLIF(Dealer.City, '') IS NULL )										THEN DBO.ProperCase(DEALER.City)
			ELSE 'Unknown City, ' + UPPER(DEALER.State) END,

		Fax						= Branch.Fax,
		Status					= ISNULL(Fax.Status,	''),
	
		BranchFaxType			= ISNULL(BRANCH.Fax_Type, ''),
		BranchFaxOnly			= ISNULL(BRANCH.Fax_Only, 0),
	
		BranchFax				= REPLACE(REPLACE(REPLACE(BRANCH.Fax, ' ', ''), '-', ''), '.', ''),
		BranchFaxEMail			= DBO.GetFaxEmailDestination(ISNULL(BRANCH.Fax, '')),
	
	
	
		CreateDateTime			= CASE	WHEN Fax.CreateDateTime		IS NOT NULL 	THEN	Fax.CreateDateTime
										WHEN Fax.UpdateDateTime		IS NOT NULL 	THEN	Fax.UpdateDateTime
										WHEN Bid.CreateDateTime		IS NOT NULL 	THEN	Bid.CreateDateTime
										WHEN Bid.UpdateDateTime		IS NOT NULL 	THEN	Bid.UpdateDateTime
										WHEN App.CreateDateTime		IS NOT NULL 	THEN	App.CreateDateTime
										WHEN App.UpdateDateTime		IS NOT NULL 	THEN	App.UpdateDateTime
										ELSE 						GETDATE()				END,
	
		UpdateDateTime			= CASE	WHEN Fax.UpdateDateTime		IS NOT NULL 	THEN	Fax.UpdateDateTime
										WHEN Fax.CreateDateTime		IS NOT NULL 	THEN	Fax.CreateDateTime
										WHEN Bid.UpdateDateTime		IS NOT NULL 	THEN	Bid.UpdateDateTime
										WHEN Bid.CreateDateTime		IS NOT NULL 	THEN	Bid.CreateDateTime
										WHEN App.UpdateDateTime		IS NOT NULL 	THEN	App.UpdateDateTime
										WHEN App.CreateDateTime		IS NOT NULL 	THEN	App.CreateDateTime
										ELSE 						GETDATE() 				END,
	
		CreateUser				= CASE	WHEN NULLIF(Fax.CreateUser,		'')	IS NOT NULL		THEN	Fax.CreateUser
										WHEN NULLIF(Fax.UpdateUser,		'')	IS NOT NULL		THEN	Fax.UpdateUser
										WHEN NULLIF(Bid.CreateUser,		'')	IS NOT NULL		THEN	Bid.CreateUser
										WHEN NULLIF(Bid.UpdateUser,		'')	IS NOT NULL		THEN	Bid.UpdateUser
										ELSE						''						END,
	
		UpdateUser				= CASE
										WHEN NULLIF(Fax.UpdateUser,		'')	IS NOT NULL		THEN	Fax.UpdateUser
										WHEN NULLIF(Fax.CreateUser,		'')	IS NOT NULL		THEN	Fax.CreateUser
										WHEN NULLIF(Bid.UpdateUser,		'')	IS NOT NULL		THEN	Bid.UpdateUser
										WHEN NULLIF(Bid.CreateUser,		'')	IS NOT NULL		THEN	Bid.CreateUser
										ELSE						''						END,
	
		rowVersion				= ISNULL(Fax.rowVersion, 1)
	
	FROM
				tblLoanApp_Bids			BID 	WITH (NOLOCK)
		JOIN	tblLoanApps				APP 	WITH (NOLOCK) ON BID.LoanAppID			= APP.LoanAppID
		JOIN	tblLendersBranches		BRANCH	WITH (NOLOCK) ON BRANCH.LendersBranchID	= BID.LendersBranchID
		JOIN	tblLenders				LENDER	WITH (NOLOCK) ON LENDER.LenderID		= BRANCH.LenderID
		JOIN	tblDealers				DEALER	WITH (NOLOCK) ON DEALER.DealerID		= APP.DealerID
		JOIN	tblLoanApp_Bids_Fax		FAX 	WITH (NOLOCK) ON BID.LoanApp_BidID		= FAX.LoanApp_BidID
	
	WHERE
			BID.CANCELED_DATE	IS	NULL
		AND FAX.STATUS			IN	('PENDING')
		AND BID.CreateDateTime 	>	CONVERT(DATETIME, CONVERT(VARCHAR(10), DATEADD(d, -30, GETDATE()), 121))
	
	ORDER BY
		Bid.LoanApp_BidID
/*
	ORDER BY
		BID.OFFER_DATE		DESC,
		BID.UpdateDateTime	DESC,
		BID.LoanApp_BidID	DESC
*/

GO

