/****** Object:  View dbo.viewFilterGen_ProgramFilter_ApplicantCounties    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewFilterGen_ProgramFilter_ApplicantCounties AS
	SELECT TOP 100 PERCENT
	  PFC.ProgramFilterID,
	  C.StateFIPS,
	  FS.StateAbbrev,
	  PFC.CountyFIPS,
	  C.County
	
	FROM
	  tblProgramFilterCounties_App PFC WITH (NOLOCK),
	  tblProgramFilterStates_App FS WITH (NOLOCK),
	  tblStates S WITH (NOLOCK),
	  tblCounties C  WITH (NOLOCK)
	
	WHERE
	      FS.StateAbbrev = S.StateAbbrev
	  AND PFC.ProgramFilterID = FS.ProgramFilterID
	  AND C.StateFIPS = S.StateFIPS
	  AND PFC.CountyFIPS = C.CountyFIPS
	
	ORDER BY
	  PFC.ProgramFilterID,
	  FS.StateAbbrev,
	  PFC.CountyFIPS





