CREATE VIEW viewFilterGen_ProgramFilter_ApplicantStates AS
	SELECT TOP 100 PERCENT
	  ProgramFilterID,
	  FS.StateAbbrev,
	  State,
	
	  CountyFilterCount =
	    (SELECT COUNT(*) FROM tblProgramFilterCounties_App PFC WHERE PFC.ProgramFilterID = FS.ProgramFilterID AND PFC.CountyFIPS IN (SELECT CountyFIPS FROM tblCounties C WHERE C.StateFIPS = S.StateFIPS))
	
	FROM
	  tblProgramFilterStates_App FS WITH (NOLOCK), tblStates S WITH (NOLOCK)
	
	WHERE
	  FS.StateAbbrev = S.StateAbbrev
	
	ORDER BY
	  ProgramFilterID,
	  FS.StateAbbrev





