/****** Object:  View dbo.viewFilterGen_Programs    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewFilterGen_Programs AS
	SELECT TOP 100 PERCENT
		P.LenderID,
	  L.LenderName,
	  L.City,
	  L.State,
	  L.Zip,
		ProgramID,
		ProgramName,
		CreditTier,
		Active,
		Automated,
		Underwriting,
		AutoSelect,
		NoCredit,
	  Submit = CASE
	    WHEN Automated=0 AND Underwriting=0 THEN
	      1
	    ELSE
	      0
	  END,
		ProgramFilterCount,
		ParameterValueCount,
		ApplicantStateFilterCount,
		ApplicantCountyFilterCount,
		DealerStateFilterCount,
		DealerCountyFilterCount,
		DealerFilterCount,
		DealerExcludeFilterCount,
	  Empty = CASE
	    WHEN ProgramFilterCount + pARAMETERValueCount + ApplicantStateFilterCount + ApplicantCountyFilterCount + DealerStateFilterCount + DealerCountyFilterCount + DealerFilterCount + DealerExcludeFilterCount = 0 THEN
	      1
	    ELSE
	      0
	  END,
		Date = CASE
	    WHEN LastBranchUpdate >= LastUpdate AND LastBranchUpdate >= LastLenderUpdate THEN
				LastBranchUpdate
	    WHEN LastLenderUpdate >= LastUpdate AND LastLenderUpdate >= LastBranchUpdate THEN
				LastLenderUpdate
	    ELSE
				LastUpdate
	  END
	
	FROM
		viewFilterGen_Programs_Inner P WITH (NOLOCK),
	  tblLenders L WITH (NOLOCK)
	
	WHERE
	  L.LenderID = P.LenderID
	
	ORDER BY
	  L.LenderID, P.ProgramID





GO

