/****** Object:  View dbo.viewFilterProgramCounties    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewFilterProgramCounties AS
	SELECT TOP 100 PERCENT
		ProgramFilterID, StateAbbrev State, StateName, C.CountyFIPS FIPS, County CountyName
	FROM
		tblProgramFilterCounties P WITH (NOLOCK), tblCounties C WITH (NOLOCK), tblStates S WITH (NOLOCK)
	WHERE
