/****** Object:  View dbo.viewFilterTest    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE  VIEW viewFilterTest AS
	SELECT TOP 100 PERCENT
		Lender						= UPPER(LENDER.LenderName),
		LenderID					= BRANCH.LenderID,
		LenderPrefix				= LENDER.LoginPrefix,
		Branch						= UPPER(BRANCH.BranchName),
		LendersBranchID				= BRANCH.LendersBranchID,
		BranchPrefix				= CASE WHEN LEN(RTRIM(LTRIM(ISNULL(BRANCH.LoginPrefix, '')))) = 0 THEN LENDER.LoginPrefix ELSE BRANCH.LoginPrefix END,
		Dealer						= UPPER(DEALER.DealerName),
		DealerID					= DEALER.DealerID,
		LoanApp_BidID				= BID.LoanApp_BidID,
		Status						= BID.Status,
		LoanAppID					= BID.LoanAppID,
		Customer					= APP.Applicant_Names,

		CreditReportAccount = CASE
			WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN CONVERT(BIT, 1)
			WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0) END,

		CreditReportAccountSource = CASE
			WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN 'LENDER_BRANCH'
			WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN 'LENDER_MASTER'
			ELSE 'NONE' END,

		CreditReportUserName = CASE
			WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(BRANCH.MicroBilt_Login))
			WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(LENDER.MicroBilt_Login))
			ELSE '' END,

		CreditReportPassword = CASE
			WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(BRANCH.MicroBilt_Password))
			WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(LENDER.MicroBilt_Password))
			ELSE '' END,

		Automation_Bureau = LENDER.AUTOMATION_CREDIT_PROVIDER,

		Existing_Bureau = CASE
			WHEN ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'EX' AND LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) = 38 AND CREDIT_EX.BUREAU = 'EX'	THEN BID.LENDER_CREDIT_EX
			WHEN ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'TU' AND LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) = 38 AND CREDIT_TU.BUREAU = 'TU'	THEN BID.LENDER_CREDIT_TU
			WHEN ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'EQ' AND LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) = 38 AND CREDIT_EQ.BUREAU = 'EQ'	THEN BID.LENDER_CREDIT_EQ

			WHEN ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'EX' AND LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) <> 38	THEN ''
			WHEN ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'TU' AND LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) <> 38	THEN ''
			WHEN ISNULL(LENDER.AUTOMATION_CREDIT_PROVIDER, '') = 'EQ' AND LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) <> 38	THEN ''
			WHEN 														  LEN(ISNULL(BID.LENDER_CREDIT_EX, ''))  = 38	THEN BID.LENDER_CREDIT_EX
			WHEN														  LEN(ISNULL(BID.LENDER_CREDIT_TU, ''))  = 38	THEN BID.LENDER_CREDIT_TU
			WHEN														  LEN(ISNULL(BID.LENDER_CREDIT_EQ, ''))  = 38	THEN BID.LENDER_CREDIT_EQ
			ELSE '' END,
		Age					= DATEDIFF(s, BID.UpdateDateTime, GETDATE())/*,

		EX		= NULLIF(BID.Lender_Credit_EX, ''),
		EXb		= ISNULL(Credit_EX.Bureau,	''),
		TU		= NULLIF(BID.Lender_Credit_TU, ''),
		TUb		= ISNULL(Credit_TU.Bureau,	''),
		EQ		= NULLIF(BID.Lender_Credit_EQ, ''),
		EQb		= ISNULL(Credit_EQ.Bureau,	'')*/

	FROM
					 tblLoanApp_Bids			BID			WITH (NOLOCK)
				JOIN tblLoanApps				APP			WITH (NOLOCK) ON BID.LoanAppID				= APP.LoanAppID
				JOIN tblDealers					DEALER		WITH (NOLOCK) ON DEALER.DealerID			= APP.DealerID
				JOIN tblLendersBranches			BRANCH		WITH (NOLOCK) ON BRANCH.LendersBranchID		= BID.LendersBranchID
				JOIN tblLenders					LENDER		WITH (NOLOCK) ON BRANCH.LenderID			= LENDER.LenderID

		LEFT	JOIN tblCreditPulls				CREDIT_EX	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(BID.Lender_Credit_EX, '')) = 1	AND	ISNULL(Credit_EX.Bureau, '') IN('EX', '')	AND	Credit_EX.GUID				= NULLIF(BID.Lender_Credit_EX, '')
		LEFT	JOIN tblCreditPulls				CREDIT_TU	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(BID.Lender_Credit_TU, '')) = 1	AND	ISNULL(Credit_TU.Bureau, '') IN('TU', '')	AND	Credit_TU.GUID				= NULLIF(BID.Lender_Credit_TU, '')
		LEFT	JOIN tblCreditPulls				CREDIT_EQ	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(BID.Lender_Credit_EQ, '')) = 1	AND	ISNULL(Credit_EQ.Bureau, '') IN('EQ', '')	AND	Credit_EQ.GUID				= NULLIF(BID.Lender_Credit_EQ, '')


	WHERE
--(					
		--ISNULL(APP.LenderID, 0) <> LENDER.LenderID) 		AND	
--		(		--DATEDIFF(d, BID.UpdateDateTime,	GETDATE())	<= 2 OR	
		--		DATEDIFF(d, BID.Submit_Date,	GETDATE())	<= 2 	OR	
		--		DATEDIFF(d, BID.Offer_Date,		GETDATE())	<= 2
--		)
--		AND	(		(BID.Status IN ('PENDING_AUTOMATION')) OR (BID.Status = 'PROCESSING_AUTOMATION' AND DATEDIFF(ss, BID.UpdateDateTime, GETDATE()) > 3000)
--				OR	(BID.LoanApp_BidID IN (SELECT DISTINCT LoanApp_BidID FROM viewLenderAutomationDealsToTag)))
--)
--And 
BID.LoanApp_BidID = 1226701
--OR (LEN(ISNULL(Lender.Automation_Credit_Provider, '')) > 0 AND Lender.LenderID IN(1094, 227, 1037) AND Bid.Status IN ('REFERRED', 'PENDING_LENDER', 'PENDING_DEALER', 'DECLINE_LENDER') AND Bid.CreateDateTime >= '2014-03-01')

	ORDER BY
		--BRANCH.LenderID DESC,
		BRANCH.LendersBranchID,
		BID.LoanApp_BidID DESC







