/****** Object:  View dbo.viewFreeForm    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewFreeForm AS
	SELECT TOP 100 PERCENT
		FF.FreeformID,
		FF.Object,
		FF.Property,
		FF.ID,

		PlainText = CASE
			WHEN FFV.EntryValue IS NULL THEN ''
			WHEN CHARINDEX('>', EntryValue, 1) > 0 AND CHARINDEX('</', EntryValue) > 0
				THEN SUBSTRING(EntryValue, CHARINDEX('>', EntryValue, 1) + 1, CHARINDEX('</', EntryValue) - CHARINDEX('>', EntryValue) - 1)
			ELSE
				''
		END,	

		FFV.EntryValue,
		FF.DealerID,
		FF.LenderID,
		FF.LendersBranchID,
		FF.AffiliateID,
		FFV.CreateUser,
		FFV.CreateDateTime,
		FFV.UpdateUser,
		FFV.UpdateDateTime
	FROM
					tblFreeForm 				FF		WITH (NOLOCK)
		JOIN	tblFreeFormValues		FFV		WITH (NOLOCK) ON (FF.FreeFormID = FFV.FreeFormID)
	ORDER BY
		FFV.UpdateDateTime DESC	





