CREATE VIEW [dbo].[viewFundingCheckList_Applicants] AS

SELECT
	FCL_A.*,
	LEGAL_NAME 				= ISNULL(LA_A.LAST_NAME , '') + ', ' + ISNULL(LA_A.FIRST_NAME, '') + ' ' + ISNULL(LA_A.MIDDLE_INITIAL, ''),
	SSN								=	dbo.fmt_ssn(LA_A.SSN_1,LA_A.SSN_2,SSN_3),
	HOME_ADDRESS  		= LA_CA.STREET_1 + ';' + LA_CA.CITY + ', ' + LA_CA.STATE + ' ' +  REPLACE(CONVERT(CHAR(5), LA_CA.ZIP), ' ', '0'),
	HOME_PHONE    		= dbo.fmt_phone_simple(LA_A.HOME_PHONE_AREA_CODE, LA_A.HOME_PHONE_PREFIX, LA_A.HOME_PHONE_NUMBER),
	EMPLOYER_NAME			= LA_CE.COMPANY,
	EMPLOYER_PHONE		= dbo.fmt_phone_simple(LA_CE.PHONE_AREA_CODE, LA_CE.PHONE_PREFIX, LA_CE.PHONE_NUMBER),

--	EMPLOER_ADDRESS 	= CASE
--		WHEN ISNULL(LA_CE.ADDRESS_STREET_1, 'NOT SUPPLIED') = 'NOT SUPPLIED' AND ISNULL(LA_CE.ADDRESS_CITY, 'NOT SUPPLIED') = 'NOT SUPPLIED' AND ISNULL(LA_CE.ADDRESS_STATE, 'XX') = 'XX' AND ISNULL(LA_CE.ADDRESS_ZIP, '0')='0' THEN
--			'N / A'
--		ELSE
--			ISNULL(LA_CE.ADDRESS_STREET_1, '') + ';' + 	ISNULL(LA_CE.ADDRESS_CITY, '') + ', ' + ISNULL(LA_CE.ADDRESS_STATE, '') + ' ' +	REPLACE(CONVERT(CHAR(5), ISNULL(LA_CE.ADDRESS_ZIP, '')), ' ', '0')
--		END,

	EMPLOYER_ADDRESS = ISNULL(LA_CE.ADDRESS_STREET_1, '') + ';' + 	ISNULL(LA_CE.ADDRESS_CITY, '') + ', ' + ISNULL(LA_CE.ADDRESS_STATE, '') + ' ' +	REPLACE(CONVERT(CHAR(5), ISNULL(LA_CE.ADDRESS_ZIP, '')), ' ', '0'),


	BASE_INCOME       = ISNULL(GROSS_MONTHLY, 0),
	OTHER_INCOME      = ISNULL(OTHER_MONTHLY, 0),

	EMAIL_ADDRESS		= LA_A.EMAIL_ADDRESS

FROM
	tblLoanApp_FundingChecklist_Applicant		FCL_A WITH (NOLOCK)
	INNER JOIN tblLoanApp_Applicant				LA_A WITH (NOLOCK) ON (FCL_A.LoanApp_ApplicantID = LA_A.LoanApp_ApplicantID)

	LEFT JOIN tblLoanApp_CurrAddress			LA_CA WITH (NOLOCK) ON (FCL_A.LoanApp_ApplicantID = LA_CA.LoanApp_ApplicantID)
	LEFT JOIN tblLoanApp_CurrEmployer			LA_CE WITH (NOLOCK) ON (FCL_A.LoanApp_ApplicantID = LA_CE.LoanApp_ApplicantID)
--	tblLoanApp_Applicant						LA_A WITH (NOLOCK)
--	tblLoanApp_CurrAddress						LA_CA WITH (NOLOCK),
--	tblLoanApp_CurrEmployer						LA_CE WITH (NOLOCK)


WHERE
			FCL_A.LoanApp_ApplicantID = LA_A.LoanApp_ApplicantID
	--AND	FCL_A.LoanApp_ApplicantID *= LA_CA.LoanApp_ApplicantID
	--AND	FCL_A.LoanApp_ApplicantID *= LA_CE.LoanApp_ApplicantID	
--AND FCL_A.FundingCheckListID=1164





