/****** Object:  View dbo.viewFundingCheckList_References    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewFundingCheckList_References AS

SELECT
	FLR.FundingChecklist_ReferenceID,
	FLR.FundingChecklistID,
	FLR.LoanApp_ReferenceID,
	FLR.LoanApp_RelativeID,
	FLR.REFERENCE_MATCH,
	FLR.COMMENTS,
	'REFERENCE'							TYPE,
	LAR.NAME								NAME,
	LAR.ADDRESS_STREET_1		ADDRESS,
	dbo.fmt_Phone_Simple(LAR.PHONE_AREA_CODE, LAR.PHONE_PREFIX, LAR.PHONE_NUMBER) PHONE,
	FLR.CreateDateTime,
	FLR.UpdateDateTime,
	FLR.CreateUser,
	FLR.UpdateUser,
	FLR.rowVersion

FROM
	tblLoanApp_FundingChecklist_Reference FLR,
	tblLoanApp_References LAR

WHERE
	FLR.LoanApp_ReferenceID = LAR.LoanApp_ReferenceID
	AND LEN(LAR.NAME) > 0

UNION ALL

SELECT
	FLR.FundingChecklist_ReferenceID,
	FLR.FundingChecklistID,
	FLR.LoanApp_ReferenceID,
	FLR.LoanApp_RelativeID,
	FLR.REFERENCE_MATCH,
	FLR.COMMENTS,
	'RELATIVE'							TYPE,
	LAR.NAME								NAME,
	LAR.ADDRESS_STREET_1		ADDRESS,
	dbo.fmt_Phone_Simple(LAR.PHONE_AREA_CODE, LAR.PHONE_PREFIX, LAR.PHONE_NUMBER) PHONE,
	FLR.CreateDateTime,
	FLR.UpdateDateTime,
	FLR.CreateUser,
	FLR.UpdateUser,
	FLR.rowVersion

FROM
	tblLoanApp_FundingChecklist_Reference FLR,
	tblLoanApp_Relatives LAR

WHERE
	FLR.LoanApp_RelativeID = LAR.LoanApp_RelativeID
	AND LEN(FLR.NAME) > 0

UNION ALL

SELECT
	FLR.FundingChecklist_ReferenceID,
	FLR.FundingChecklistID,
	FLR.LoanApp_ReferenceID,
	FLR.LoanApp_RelativeID,
	FLR.REFERENCE_MATCH,
	FLR.COMMENTS,
	FLR.TYPE,
	FLR.NAME,
	FLR.ADDRESS,
	FLR.PHONE,
	FLR.CreateDateTime,
	FLR.UpdateDateTime,
	FLR.CreateUser,
	FLR.UpdateUser,
	FLR.rowVersion

FROM
	tblLoanApp_FundingChecklist_Reference FLR

WHERE
	FLR.LoanApp_ReferenceID IS NULL
	AND FLR.LoanApp_RelativeID IS NULL








