CREATE view viewFundingDeals AS

SELECT --WorksheetActive,vehicle,
active = case
 WHEN activedeal.LoanApp_PreFundedActiveDealID is null and bids.FUNDED_DATE is not null  THEN 1
 WHEN activedeal.LoanApp_PreFundedActiveDealID is not null THEN 1
 else 0
end,
activedeal.LoanApp_PreFundedActiveDealID,
activedeal.StatusUpdateDateTime,
activedeal.StatusUpdateUser,
--bids.loanapp_bidid ,
--bids.FUNDED_DATE ,
--bids.FINANCING_AMOUNT ,
--bids.TERM ,
--bids.RATE 


bids.LoanApp_BidID,
bids.FINANCING_AMOUNT,
bids.TERM,
bids.RATE,
bids.DISCOUNT_FEE,
bids.REBATE_PERCT,
bids.ADVANCE,
--                   ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), AUTO_LOAN_APP.VEHICLE_YEAR) + ' ' + AUTO_LOAN_APP.VEHICLE_MAKE + ' ' + AUTO_LOAN_APP.VEHICLE_MODEL),
branch.lenderid
FROM tblLoanApp_Bids bids WITH (NOLOCK) 
join tbllendersbranches branch with (nolock) on branch.lendersbranchid=bids.lendersbranchid
left outer join tblLoanApp_PreFundedActiveDeal activedeal WITH (NOLOCK) on bids.loanapp_bidid =activedeal.loanapp_bidid and activedeal.lenderid=branch.lenderid
