/****** Object:  View dbo.viewHttpPostParameterSummary    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW dbo.viewHttpPostParameterSummary
AS
SELECT     t1.LenderID, t1.LenderName, dbo.tblYesNo.yes_no_desc AS CanPost, tblYesNo_1.yes_no_desc AS SendAsHTTPForm, t1.PostURL, t1.PostType,
                      t2.post_action_param_id, t2.post_action_code, t2.required, t2.parameter, t2.parameter_desc, t2.entity_name, t2.element_name, t2.use_default,
                      t2.use_where_clause, t2.where_clause, t2.document_number, t2.post_parameter_rule_id
FROM         dbo.tblLenders t1 INNER JOIN
                      dbo.tblYesNo tblYesNo_1 ON t1.SendAsHTTPForm = tblYesNo_1.yes_no_bitwise INNER JOIN
                      dbo.tblHttpPostParameters t2 ON t1.LenderID = t2.LenderID LEFT OUTER JOIN
                      dbo.tblYesNo ON t1.CanPost = dbo.tblYesNo.yes_no_bitwise





