CREATE VIEW viewInventory_AvailForSaleMini AS
	SELECT TOP 100 PERCENT
		DealersInventoryID	ID,
		DealerID,
		YEAR					VEHICLE_YEAR,
		MAKE					VEHICLE_MAKE,
		MODEL					VEHICLE_MODEL,
		ODOMETER			VEHICLE_MILEAGE,
		SERIAL_NO			VEHICLE_VIN,
		PRICE					SALE_PRICE,
		NEW=CASE ISNULL(STATUS, '')
			WHEN 'NEW' THEN CONVERT(bit, 1)
			ELSE CONVERT(bit,0)
		END,
		BOOK_RETAIL,
		BOOK_RETAIL_ADJUSTED,
		BOOK_WHOLESALE,
		BOOK_WHOLESALE_ADJUSTED
	FROM
		tblDealersInventory
	WHERE
		SALE_STATUS = 'AVAILABLE'
	ORDER BY
		YEAR DESC,
		MAKE,
		MODEL,
		PRICE DESC






