/****** Object:  View dbo.viewLenderBranchBureaus    Script Date: 7/31/2024 12:57:17 PM ******/

CREATE VIEW viewLenderBranchBureaus AS
	SELECT TOP 100 PERCENT
		I.LenderID,
		I.LendersBranchID,
		I.LenderName,
		I.BranchName,
		HasCredit	= 			CONVERT(BIT,	CASE	WHEN I.Lender_HasBureauAuthentication = 1 OR I.Branch_HasBureauAuthentication = 1 THEN 1 ELSE 0 END),
																
		CREDIT_EX			=	CONVERT(BIT,	CASE	WHEN I.Lender_HasBureauAuthentication = 1 AND ISNULL(L.CREDIT_EX, 0) = 1 THEN 1 
														WHEN I.Lender_HasBureauAuthentication = 1 AND ISNULL(L.CREDIT_EX, 0) = 1 THEN 1 ELSE 0 END),
																
		CREDIT_EQ			=	CONVERT(BIT,	CASE	WHEN I.Lender_HasBureauAuthentication = 1 AND ISNULL(L.CREDIT_EQ, 0) = 1 THEN 1 
														WHEN I.Lender_HasBureauAuthentication = 1 AND ISNULL(L.CREDIT_EQ, 0) = 1 THEN 1 ELSE 0 END),
																
		CREDIT_TU			=	CONVERT(BIT,	CASE	WHEN I.Lender_HasBureauAuthentication = 1 AND ISNULL(L.CREDIT_TU, 0) = 1 THEN 1 
														WHEN I.Lender_HasBureauAuthentication = 1 AND ISNULL(L.CREDIT_TU, 0) = 1 THEN 1 ELSE 0 END),
	
		BureauSource		=	CASE	WHEN I.Lender_HasBureauAuthentication = 1 	THEN 'LENDER'
										WHEN I.Branch_HasBureauAuthentication = 1 	THEN 'BRANCH'
										ELSE 'NONE' END,
	
		MicroBilt_Login		= 	CASE	WHEN I.Lender_HasBureauAuthentication = 1	THEN L.Microbilt_Login
										WHEN I.Branch_HasBureauAuthentication = 1	THEN B.Microbilt_Login
										ELSE '' END,
	
		MicroBilt_Password	= 	CASE	WHEN I.Lender_HasBureauAuthentication = 1	THEN L.Microbilt_Password
										WHEN I.Branch_HasBureauAuthentication = 1	THEN B.Microbilt_Password
										ELSE '' END
		FROM 
					viewLenderBranchBureaus_Inner	I	WITH (NOLOCK)
			JOIN	tblLenders						L	WITH (NOLOCK)	ON L.LenderID = I.LenderID
			JOIN	tblLendersBranches				B	WITH (NOLOCK)	ON B.LendersBranchID = I.LendersBranchID
		ORDER BY
			L.LenderID,
			B.LendersBranchID




GO

