/****** Object:  View dbo.viewLenderBranchBureaus_Inner    Script Date: 7/31/2024 12:57:17 PM ******/



CREATE VIEW viewLenderBranchBureaus_Inner AS
	SELECT
		L.LenderID,
		L.LenderName,
		Lender_HasBureauAuthentication	= CONVERT(BIT, CASE WHEN 		LEN(RTRIM(LTRIM(ISNULL(L.Microbilt_Login, 		'')))) > 0	AND LEN(LTRIM(RTRIM(ISNULL(L.Microbilt_Password,	'')))) > 0	THEN 1 ELSE 0 END),
		B.LendersBranchID,
		B.BranchName,
		Branch_HasBureauAuthentication	= CONVERT(BIT, CASE WHEN 		LEN(RTRIM(LTRIM(ISNULL(B.Microbilt_Login, 		'')))) > 0	AND LEN(LTRIM(RTRIM(ISNULL(B.Microbilt_Password,	'')))) > 0	THEN 1 ELSE 0 END)
	FROM
				tblLenders				L	WITH (NOLOCK)
		JOIN	tblLendersBranches		B	WITH (NOLOCK)	ON B.LenderID	= L.LenderID
	WHERE
		(		(L.LenderStatus = 'ACTIVE')
			OR	(L.LenderStatus = 'TRIAL_30' AND	DATEDIFF(d, L.LenderStatusUpdateDateTime, GETDATE()) >= 0))




