/****** Object:  View dbo.viewLenderBranchCompanyCodes    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewLenderBranchCompanyCodes AS
SELECT TOP 100 PERCENT
  LenderID = LENDER.LenderID,
  LendersBranchID = BRANCH.LendersBranchID,
  Lender = CONVERT(VARCHAR(32), UPPER(LENDER.LenderName)),
  Branch = CONVERT(VARCHAR(32), UPPER(BRANCH.BranchName)),
  LenderCompanyCode = CONVERT(VARCHAR(32), UPPER(ISNULL(LENDER.LoginPrefix, ''))),
  BranchCompanyCode = CONVERT(VARCHAR(32), UPPER(ISNULL(BRANCH.LoginPrefix, ''))),
  LenderScripts = CASE
    WHEN LEN(ISNULL(LENDER.LoginPrefix, '')) > 0 THEN
      '\\APP2\CreditSmarts\bin\lender_scripts\' + UPPER(ISNULL(LENDER.LoginPrefix, '')) + '\'
    ELSE
      ''
  END,
  BranchScripts = CASE
    WHEN LEN(ISNULL(LENDER.LoginPrefix, '')) > 0  AND LEN(ISNULL(BRANCH.LoginPrefix, '')) > 0 THEN
      '\\APP2\CreditSmarts\bin\lender_scripts\' + UPPER(ISNULL(LENDER.LoginPrefix, '')) + '\' + UPPER(ISNULL(BRANCH.LoginPrefix, '')) + '\'
    ELSE
      ''
  END
FROM
  tblLenders LENDER
    JOIN tblLendersBranches BRANCH ON(LENDER.LenderID=BRANCH.LenderID)
ORDER BY
  LENDER.LenderName,
  BRANCH.BranchName





