/****** Object:  View dbo.viewLenderBranches_Simple    Script Date: 7/31/2024 12:57:17 PM ******/

CREATE VIEW viewLenderBranches_Simple AS
SELECT
	LENDER.LenderID,
	BRANCH.LendersBranchID,
	DisplayName = CASE
		WHEN	LENDER.LenderName = BRANCH.BranchName			
			THEN LENDER.LenderName

		WHEN	LEFT(BRANCH.BranchName, LEN(LENDER.LenderName)) = LENDER.LenderName
			THEN RTRIM(LEFT(LENDER.LenderName, LEN(BRANCH.BranchName))) + ' - ' + LTRIM(SUBSTRING(BRANCH.BranchName, LEN(LENDER.LenderName) + 1, 999))

		ELSE
			LENDER.LenderName + ' - ' + BRANCH.BranchName
	END + ' (' + BRANCH.City + ', ' + BRANCH.State + ')',

	LENDER.LenderName,
	LenderCompanyCode	= ISNULL(LENDER.LoginPrefix, ''),

	LenderCity		= ISNULL(LENDER.City, ''),
	LenderState		= ISNULL(LENDER.State, ''),
	LenderZip		= LENDER.Zip,

	BranchCompanyCode	= ISNULL(BRANCH.LoginPrefix, ''),
	BRANCH.BranchName,

	BranchCity		= ISNULL(Branch.City, ''),
	BranchState		= ISNULL(Branch.State, ''),
	BranchZip		= CONVERT(VARCHAR(5), LEFT(CASE
		WHEN BRANCH.Zip	IS NULL		THEN	''
		WHEN BRANCH.ZIP >= 10000	THEN 	CONVERT(VARCHAR(16), BRANCH.ZIP)
		ELSE 								RIGHT('00000' + CONVERT(VARCHAR(32), Branch.Zip), 5)
	END, 5))

FROM
					tblLenders			LENDER		WITH (NOLOCK)
	INNER JOIN		tblLendersBranches	BRANCH		WITH (NOLOCK) ON BRANCH.LenderID = LENDER.LenderID




