/****** Object:  View dbo.viewLenderCreditReports    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewLenderCreditReports AS

SELECT TOP 100 PERCENT
	tblLendersBranches.LenderID										LenderID					,
	tblLoanApp_Bids.LoanAppID											LoanAppID					,
	'EX' 																					BureauCode				,
	'Experian' 																		BureauName				,
	tblLoanApp_Bids.LENDER_CREDIT_EX 							GUID

FROM
	tblLoanApp_Bids INNER JOIN
  	tblLendersBranches ON
  		tblLoanApp_Bids.LendersBranchID = tblLendersBranches.LendersBranchID

WHERE
			tblLoanApp_Bids.LENDER_CREDIT_EX IS NOT NULL
	AND LEN(tblLoanApp_Bids.LENDER_CREDIT_EX) > 0

ORDER BY
	tblLoanApp_Bids.LoanAppID DESC,
	tblLoanApp_Bids.LenderID


UNION ALL


SELECT TOP 100 PERCENT
	tblLendersBranches.LenderID										LenderID					,
	tblLoanApp_Bids.LoanAppID											LoanAppID					,
	'TU' 																					BureauCode				,
	'Trans-Union' 																BureauName				,
	tblLoanApp_Bids.LENDER_CREDIT_TU 							GUID

FROM
	tblLoanApp_Bids INNER JOIN
  	tblLendersBranches ON
  		tblLoanApp_Bids.LendersBranchID = tblLendersBranches.LendersBranchID

WHERE
			tblLoanApp_Bids.LENDER_CREDIT_TU IS NOT NULL
	AND LEN(tblLoanApp_Bids.LENDER_CREDIT_TU) > 0

ORDER BY
	tblLoanApp_Bids.LoanAppID DESC,
	tblLoanApp_Bids.LenderID


UNION ALL


SELECT TOP 100 PERCENT
	tblLendersBranches.LenderID										LenderID					,
	tblLoanApp_Bids.LoanAppID											LoanAppID					,
	'EQ' 																					BureauCode				,
	'Equifax' 																		BureauName				,
	tblLoanApp_Bids.LENDER_CREDIT_EQ 							GUID

FROM
	tblLoanApp_Bids INNER JOIN
  	tblLendersBranches ON
  		tblLoanApp_Bids.LendersBranchID = tblLendersBranches.LendersBranchID

WHERE
			tblLoanApp_Bids.LENDER_CREDIT_EQ IS NOT NULL
	AND LEN(tblLoanApp_Bids.LENDER_CREDIT_EQ) > 0

ORDER BY
	tblLoanApp_Bids.LoanAppID DESC,
	tblLoanApp_Bids.LenderID







