--ALTER  VIEW viewLenderCreditReports AS
CREATE VIEW viewLenderCreditReports_Test AS
	-- DECLARE @_LoanAppID INTEGER, @_LenderID INTEGER; SET @_LoanAppID = 1142195; SET @_LenderID = 1092;
	--------------------
	--    EXPERIAN
	--------------------

	SELECT
		LenderID		= Branch.LenderID,
		LoanAppID		= Bids.LoanAppID,
		BureauCode		= 'EX',
		BureauName		= 'Experian',
    	GUID			= Bids.LENDER_CREDIT_EX
	FROM
				tblLoanApp_Bids			Bids	WITH (NOLOCK)
		JOIN	tblLendersBranches 		Branch	WITH (NOLOCK) ON Bids.LendersBranchID = Branch.LendersBranchID
	WHERE
			NULLIF(Bids.Lender_Credit_EX, '') IS NOT NULL
		-- AND Bids.LoanAppID = @_LoanAppID AND Branch.LenderID = @_LenderID
		
	UNION ALL

	--------------------
	--    EQUIFAX
	--------------------

	SELECT
		LenderID		= Branch.LenderID,
		LoanAppID		= Bids.LoanAppID,
		BureauCode		= 'EQ',
		BureauName		= 'Equifax',
    	GUID			= Bids.LENDER_CREDIT_EQ
	FROM
				tblLoanApp_Bids			Bids	WITH (NOLOCK)
		JOIN	tblLendersBranches 		Branch	WITH (NOLOCK) ON Bids.LendersBranchID = Branch.LendersBranchID
	WHERE
			NULLIF(Bids.Lender_Credit_EQ, '') IS NOT NULL
		-- AND Bids.LoanAppID = @_LoanAppID AND Branch.LenderID = @_LenderID

	UNION ALL

	--------------------
	--    TRANS-UNION
	--------------------

	SELECT
		LenderID		= Branch.LenderID,
		LoanAppID		= Bids.LoanAppID,
		BureauCode		= 'TU',
		BureauName		= 'Trans-Union',
    	GUID			= Bids.LENDER_CREDIT_TU
	FROM
				tblLoanApp_Bids			Bids	WITH (NOLOCK)
		JOIN	tblLendersBranches 		Branch	WITH (NOLOCK) ON Bids.LendersBranchID = Branch.LendersBranchID
	WHERE
			NULLIF(Bids.Lender_Credit_TU, '') IS NOT NULL
		-- AND Bids.LoanAppID = @_LoanAppID AND Branch.LenderID = @_LenderID




