/****** Object:  View dbo.viewLenderEmailRef    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW [dbo].[viewLenderEmailRef] AS
SELECT
		b.LoanAppID,
		lb.LenderID,
		REPLACE(REPLACE(ISNULL(d.EMail, ISNULL(e.DealerEmail,'')), CHAR(10) ,';'),CHAR(13) ,';')  as DealerEmail,
		CASE WHEN a.EMAIL_ADDRESS IS NOT NULL AND LEN(a.EMAIL_ADDRESS) > 0 THEN REPLACE(REPLACE(a.EMAIL_ADDRESS, CHAR(10) ,';'),CHAR(13) ,';')
			ELSE REPLACE(REPLACE(ISNULL(e.CustomerEmail,''), CHAR(10) ,';'),CHAR(13) ,';') END AS CustomerEmail,
		a.LoanApp_ApplicantID
	FROM tblLoanApp_Bids b WITH (NOLOCK)
		LEFT JOIN tblLoanApps l WITH (NOLOCK) ON b.LoanAppID = l.LoanAppID
		LEFT JOIN tblLendersBranches lb WITH (NOLOCK) ON lb.LendersBranchID = b.LendersBranchID
		LEFT JOIN tblLenderEmailRef e WITH (NOLOCK) ON l.LoanAppID = e.LoanAppID AND e.LenderID = lb.LenderID
		LEFT JOIN tblDealers d WITH (NOLOCK) ON l.DealerID = d.DealerID
		LEFT JOIN tblLoanApp_Applicant a WITH (NOLOCK) ON l.LoanAppID = a.LoanAppID





GO

