CREATE VIEW viewLenderInvoicing AS
	SELECT --TOP 10
		LoanAppID					= Bids.LoanAppID,
		LoanApp_BidID				= Bids.LoanApp_BidID,
		BidCreateDateTime			= Bids.CreateDateTime,
		BidUpdateDateTime			= Bids.UpdateDateTime,
		BidSubmitDateTime			= Bids.Submit_Date,
		Status						= Bids.Status,
		Financing_Amount			= Bids.Financing_Amount,
		Funded						= CONVERT(Bit, CASE WHEN Bids.Funded = 1 THEN 1 WHEN Bids.Funded_Date IS NOT NULL THEN 1 ELSE 0 END),

		BillableDate				= CASE WHEN Lender.Fee_Method = 'PER_FUNDED' THEN Bids.Funded_Date ELSE ISNULL(Bids.Submit_Date, Bids.CreateDateTime) END,

		LenderID					= Lender.LenderID,
		LenderName					= DBO.ProperCase(Lender.LenderName),
		LenderStatus				= ISNULL(Lender.LenderStatus, ''),
		LenderAddress				= Lender.Address,
		LenderCity					= DBO.ProperCase(Lender.City),
        LenderState					= UPPER(Lender.State),
		LenderZIP					= Lender.ZIP,
		Fee_Method					= Lender.Fee_Method,
		Fee_Per_Unit				= Lender.Fee_Per_Unit,

		DealerID					= Dealer.DealerID,
		DealerName					= DBO.ProperCase(Dealer.DealerName),
		Applicant_Names				= DBO.ProperCase(Apps.Applicant_Names)


	FROM
				tblLoanApp_Bids			Bids		WITH (NOLOCK)
		JOIN	tblLoanApps				Apps		WITH (NOLOCK)	ON Apps.LoanAppID			= Bids.LoanAppID
		JOIN	tblLendersBranches		Branch		WITH (NOLOCK)	ON Branch.LendersBranchID	= Bids.LendersBranchID
		JOIN	tblLenders				Lender		WITH (NOLOCK)	ON Lender.LenderID			= Branch.LenderID
		JOIN	tblDealers				Dealer		WITH (NOLOCK)	ON Dealer.DealerID			= Apps.DealerID
	WHERE
				Lender.LenderStatus		IN	('ACTIVE', 'TRIAL_30')
		AND	(	Lender.Fee_Method		=	'PER_SUBMITTED'
				OR
				(Lender.Fee_Method = 'PER_FUNDED' AND (Bids.Funded = 1 OR Bids.Funded_Date IS NOT NULL))
			)




GO

