/****** Object:  View dbo.viewLenderLoanAppCombinedStatus    Script Date: 7/31/2024 12:57:17 PM ******/

CREATE VIEW viewLenderLoanAppCombinedStatus AS
	SELECT
		LoanAppID	= Bids.LoanAppID,
		LenderID	= Branch.LenderID,
		Status		= CASE WHEN Bids.Canceled_Date IS NOT NULL THEN 'CANCELED' ELSE Bids.Status END,
		Pending_Lender	= CONVERT(BIT, CASE WHEN Bids.Status IN('PENDING_LENDER', 'REFERRED') THEN 1 ELSE 0 END),
		Decisioned		= CONVERT(BIT, CASE WHEN Bids.Status IN('PENDING_DEALER', 'DECLINE_LENDER')	THEN 1 ELSE 0 END),
		Quantity	= COUNT(*)
		

	FROM
				tblLoanApp_Bids		Bids		WITH (NOLOCK)
		--JOIN	tblLoanApps			Apps		WITH (NOLOCK)	ON Apps.LoanAppID			= Bids.LoanAppID
		JOIN	tblLendersBranches	Branch		WITH (NOLOCK)	ON Branch.LendersBranchID	= Bids.LendersBranchID
		--JOIN	tblLenders			Lender		WITH (NOLOCK)	ON Lender.LenderID			= Branch.LenderID

	/*
	WHERE
			Branch.LenderID = 1037
		AND Bids.CreateDateTime > '2015-06-01'
	*/

	GROUP BY
		Bids.LoanAppID,
		Branch.LenderID,
		CASE WHEN Bids.Canceled_Date IS NOT NULL THEN 'CANCELED' ELSE Bids.Status END,
		CONVERT(BIT, CASE WHEN Bids.Status IN('PENDING_LENDER', 'REFERRED') THEN 1 ELSE 0 END),
		CONVERT(BIT, CASE WHEN Bids.Status IN('PENDING_DEALER', 'DECLINE_LENDER')	THEN 1 ELSE 0 END)






