/****** Object:  View dbo.viewLenderPartnerFields    Script Date: 7/31/2024 12:57:17 PM ******/
CREATE VIEW [viewLenderPartnerFields] AS
	SELECT 
		[PartnerToolID]				= [Partner].[PartnerToolID],
		[Partner]							= MIN([Partner].[ShortName]),
		[LenderID]						= [Branch].[LenderID],
		[LendersBranchID]			= [Branch].[LendersBranchID],
		[Field]								= [PDE].[Field], 
		--[BoundTo] = CASE WHEN MAX([PDE].[LendersBranchID]) = 0 THEN 'Lender' WHEN MAX([PDE].[LenderID]) = 0 THEN 'Branch' ELSE 'Both' END,
		[Value]								= NULLIF(ISNULL(NULLIF([PDE].[DataValue], ''), [PED].[Value]), '')
	FROM
					[tblPartnerTools]								[Partner] WITH (NOLOCK)
		JOIN	[tblPartnerElementDefinition]		[PED]			WITH (NOLOCK) ON [PED].[PartnerToolID] = [Partner].[PartnerToolID] AND [PED].[Active] = 1 AND [PED].[ValueType] <> 'ENABLED' AND [PED].[KeyedFromLoanAppID] = 0 AND [PED].[KeyedFromLoanApp_BidID] = 0 AND [PED].[KeyedFromDealerID] = 0 AND ([PED].[KeyedFromLenderID] = 1 OR [PED].[KeyedFromLendersBranchID] = 1)
		JOIN 	[tblPartnerDataElement]					[PDE]			WITH (NOLOCK) ON [PDE].[PartnerToolID] = [Partner].[PartnerToolID] AND [PDE].[Field] = [PED].[Field] AND [PDE].[Active] = 1 AND [PDE].[LoanAppID] = 0 AND [PDE].[LoanApp_BidID] = 0 AND [PDE].[DealerID] = 0 AND ([PDE].[LenderID] > 0 OR [PDE].[LendersBranchID] > 0) AND ([PDE].[DataValue] <> '' OR [PED].[Value] <> '')
		JOIN	[tblLendersBranches]						[Branch]	WITH (NOLOCK) ON [Branch].[LendersBranchID] = [PDE].[LendersBranchID] OR ([PDE].[LenderID] = [Branch].[LenderID] AND [PDE].[LendersBranchID] = 0)
	--WHERE 
		--[PDE].[DataValue] <> '' OR [PED].[Value] <> ''
	GROUP BY
		[Partner].[PartnerToolID],
		[Branch].[LenderID],
		[Branch].[LendersBranchID],
		[PDE].[Field],
		[PDE].[DataValue], [PED].[Value]


