/****** Object:  View dbo.viewLenderPartnersActivatedForBid    Script Date: 7/31/2024 12:57:17 PM ******/

CREATE VIEW [viewLenderPartnersActivatedForBid] AS
SELECT
	[LoanAppID]						= [Bid].[LoanAppID],
	[LoanApp_BidID]					= [Bid].[LoanApp_BidID],
	[LenderID]						= [Partner].[LenderID],
	[LendersBranchID]				= [Bid].[LendersBranchID],
	[PartnerToolID]					= [Partner].[PartnerToolID],
	[Active]						= CONVERT(BIT, 1),
	[Pending]						= CONVERT(BIT, CASE WHEN [Bid].[Canceled_Date] IS NULL AND [Bid].[Status] IN ('PENDING_LENDER', 'REFERRED') THEN 1 ELSE 0 END),
	[Decisioned]					= CONVERT(BIT, CASE WHEN [Bid].[Canceled_Date] IS NULL AND [Bid].[Offer_Date] IS NOT NULL AND [Bid].[Status] IN ('PENDING_DEALER', 'DECLINE_DEALER', 'DECLINE_LENDER', 'ACCEPTED')	THEN 1	ELSE 0 END)
	/*
	[ActivatedByLenderID]			= [Partner].[ActivatedByLenderID],
	[ActivatedByLendersBranchID]	= [Partner].[ActivatedByLendersBranchID],
	[PartnerToolsTriggerID]			= [Partner].[PartnerToolsTriggerID],
	[TriggerType]					= [Partner].[TriggerType],
	[Trigger]						= [Partner].[Trigger]*/
FROM
			[tblLoanApp_Bids]					[Bid]		WITH (NOLOCK)
	JOIN	[viewPartnersActivatedForBranch]	[Partner]	WITH (NOLOCK) ON [Partner].[LendersBranchID] = [Bid].[LendersBranchID]
--WHERE [Bid].[LoanApp_BidID] = @B
GROUP BY
	[Bid].[LoanAppID],
	[Bid].[LoanApp_BidID],
	[Partner].[LenderID],
	[Bid].[LendersBranchID],
	[Bid].[Canceled_Date],
	[Bid].[Offer_Date],
	[Bid].[Status],
	[Partner].[PartnerToolID]/*,
	[Partner].[ActivatedByLenderID],
	[Partner].[ActivatedByLendersBranchID],
	[Partner].[PartnerToolsTriggerID],
	[Partner].[TriggerType],
	[Partner].[Trigger]*/


