/****** Object:  View dbo.viewLendersFileAttach    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewLendersFileAttach AS

SELECT TOP 100 PERCENT
	F.LendersFileID,
  F.LenderID,
	CONVERT(VARCHAR(255), F.[File]) + '.' + ISNULL(NULLIF(A.Extension,''),'PDF') [File],
  F.SortValue SEQ,
  ISNULL(F.FileType, '') FileType,
  F.CreateDateTime,
  F.UpdateDateTime,
  F.CreateUser,
  F.UpdateUser,
  F.RowVersion,
  ISNULL(F.Caption, '') Caption,
  LoginPrefix CompanyCode
FROM
  tblLendersFileAttach F
    JOIN tblAttachments A ON(F.[File] = A.AttachmentID)
    JOIN tblLenders L ON (F.LenderID = L.LenderID)
ORDER BY
  F.LenderID,
  F.SortValue,
  F.Caption






