/****** Object:  View dbo.viewLendersTrialStatus    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW viewLendersTrialStatus AS
	SELECT
		LenderID,
		LenderName,
		Status = UPPER(ISNULL(LenderStatus, 'ACTIVE')),
		LenderStatusUpdateDateTime = ISNULL(LenderStatusUpdateDateTime, GETDATE()),
	
		StatusAge = DATEDIFF(Day, ISNULL(LenderStatusUpdateDateTime, GETDATE()), GETDATE()),
	
		Trial = CONVERT(BIT, CASE WHEN LenderStatus = 'TRIAL_30' THEN 1 ELSE 0 END),
		Expired = CONVERT(BIT, CASE
			WHEN		LenderStatus = 'TRIAL_30'
					AND	DATEDIFF(Day, ISNULL(LenderStatusUpdateDateTime, GETDATE()), GETDATE()) > 30 THEN 1
			ELSE 0 END),
	
		Active = CONVERT(BIT, CASE
				WHEN LenderStatus IN ('ACTIVE', NULL) THEN 1
				WHEN LenderStatus IN ('INACTIVE', 'FAX') THEN 0
	
				WHEN		LenderStatus = 'TRIAL_30'
						AND	DATEDIFF(Day, ISNULL(LenderStatusUpdateDateTime, GETDATE()), GETDATE()) > 30 THEN 0
	
				ELSE 1
			END)
	FROM
		tblLenders WITH (NOLOCK)





GO

