/****** Object:  View dbo.viewLoanApp_ApplicantDemographics    Script Date: 7/31/2024 12:57:17 PM ******/


CREATE VIEW [dbo].[viewLoanApp_ApplicantDemographics] AS

SELECT --TOP 100 PERCENT
	APP.LoanAppID,

	Applicants				= CASE 
		WHEN CO_APPLICANT.LoanApp_ApplicantID IS NULL		THEN 1
		WHEN NULLIF(CO_APPLICANT.FIRST_NAME, '') IS NULL	THEN 1
		ELSE 2
	END,

	Applicant_Names			= CASE
		WHEN NULLIF(CO_APPLICANT.FIRST_NAME, '') IS NULL	THEN CreditSmarts.DBO.Capitalize(APPLICANT.First_Name + ' ' + APPLICANT.Last_Name)

		WHEN APPLICANT.LAST_NAME = CO_APPLICANT.LAST_NAME AND LEN(ISNULL(CO_APPLICANT.RELATIONSHIP_TO_PRIMARY, '')) > 0 THEN
			CreditSmarts.DBO.Capitalize(
				APPLICANT.First_Name + ' & ' + CO_APPLICANT.First_Name + ' (' + CO_APPLICANT.RELATIONSHIP_TO_PRIMARY + ') ' + APPLICANT.Last_Name) 

		ELSE 
			CreditSmarts.DBO.Capitalize(
				APPLICANT.First_Name + ' ' + APPLICANT.Last_Name + ', ' + 
				CO_APPLICANT.First_Name + ' ' + CO_APPLICANT.Last_Name + 

				CASE WHEN LEN(ISNULL(CO_APPLICANT.RELATIONSHIP_TO_PRIMARY, '')) > 0 THEN ' (' + CO_APPLICANT.RELATIONSHIP_TO_PRIMARY + ')' ELSE '' END
			)

		END,

	Applicant_Last_Name				= CreditSmarts.DBO.Capitalize(APPLICANT.Last_Name),
	Applicant_First_Name			= CreditSmarts.DBO.Capitalize(APPLICANT.First_Name),
	Applicant_Name					= CreditSmarts.DBO.Capitalize(APPLICANT.First_Name + ' ' + APPLICANT.Last_Name),
	Applicant_Phone					= CreditSmarts.DBO.PhoneNumberFormat(APPLICANT.HOME_PHONE_AREA_CODE,	APPLICANT.HOME_PHONE_PREFIX,	APPLICANT.HOME_PHONE_NUMBER, 	NULL),
	Applicant_MobilePhone			= CreditSmarts.DBO.PhoneNumberFormat(APPLICANT.MOBILE_PHONE_AREA_CODE,	APPLICANT.MOBILE_PHONE_PREFIX,	APPLICANT.MOBILE_PHONE_NUMBER,	NULL),
	Applicant_SSN					= CreditSmarts.DBO.FormatSSN(APPLICANT.SSN_1, APPLICANT.SSN_2, APPLICANT.SSN_3),

	Applicant_Employment_Status		= CreditSmarts.DBO.FormatEmploymentStatus(APPLICANT_EMPLOYER.CLASSIFICATION),
	Applicant_Employer				= CreditSmarts.DBO.Capitalize(APPLICANT_EMPLOYER.COMPANY),
	Applicant_Position				= CreditSmarts.DBO.Capitalize(APPLICANT_EMPLOYER.POSITION),
	Applicant_Work_Phone			= CreditSmarts.DBO.PhoneNumberFormat(APPLICANT_EMPLOYER.PHONE_AREA_CODE,	APPLICANT_EMPLOYER.PHONE_PREFIX,	APPLICANT_EMPLOYER.PHONE_NUMBER,	APPLICANT_EMPLOYER.PHONE_EXTENSION),

	Applicant_Base_Income			= ISNULL(Applicant.Gross_Monthly, 0),

	Applicant_Other_Income			= ISNULL(APPLICANT.OTHER_MONTHLY, 0),
	Applicant_Other_Income_Type		= CreditSmarts.DBO.FormatOtherIncomeSource(APPLICANT.OTHER_TYPE),
	Applicant_Other_Income_Source	= CreditSmarts.DBO.Capitalize(APPLICANT.Other_Source),
	Applicant_Total_Income			= ISNULL(Applicant.Gross_Monthly, 0) + ISNULL(APPLICANT.OTHER_MONTHLY, 0),



	CoApplicant_Last_Name			= CreditSmarts.DBO.Capitalize(CO_APPLICANT.Last_Name),
	CoApplicant_First_Name			= CreditSmarts.DBO.Capitalize(CO_APPLICANT.First_Name),
	CoApplicant_Name				= CreditSmarts.DBO.Capitalize(CO_APPLICANT.First_Name + ' ' + CO_APPLICANT.Last_Name),
	CoApplicant_Phone				= CreditSmarts.DBO.PhoneNumberFormat(CO_APPLICANT.HOME_PHONE_AREA_CODE,	CO_APPLICANT.HOME_PHONE_PREFIX,	CO_APPLICANT.HOME_PHONE_NUMBER, 	NULL),
	CoApplicant_MobilePhone			= CreditSmarts.DBO.PhoneNumberFormat(CO_APPLICANT.MOBILE_PHONE_AREA_CODE,	CO_APPLICANT.MOBILE_PHONE_PREFIX,	CO_APPLICANT.MOBILE_PHONE_NUMBER,	NULL),
	CoApplicant_SSN					= CreditSmarts.DBO.FormatSSN(CO_APPLICANT.SSN_1, CO_APPLICANT.SSN_2, CO_APPLICANT.SSN_3),

	CoApplicant_Employment_Status	= CreditSmarts.DBO.FormatEmploymentStatus(CO_APPLICANT_EMPLOYER.CLASSIFICATION),
	CoApplicant_Employer			= CreditSmarts.DBO.Capitalize(CO_APPLICANT_EMPLOYER.COMPANY),
	CoApplicant_Position			= CreditSmarts.DBO.Capitalize(CO_APPLICANT_EMPLOYER.POSITION),
	CoApplicant_Work_Phone			= CreditSmarts.DBO.PhoneNumberFormat(CO_APPLICANT_EMPLOYER.PHONE_AREA_CODE,	APPLICANT_EMPLOYER.PHONE_PREFIX,	APPLICANT_EMPLOYER.PHONE_NUMBER,	APPLICANT_EMPLOYER.PHONE_EXTENSION),

	CoApplicant_Base_Income			= ISNULL(CO_APPLICANT.Gross_Monthly, 0),

	CoApplicant_Other_Income		= ISNULL(CO_APPLICANT.OTHER_MONTHLY, 0),
	CoApplicant_Other_Income_Type	= CreditSmarts.DBO.FormatOtherIncomeSource(CO_APPLICANT.OTHER_TYPE),
	CoApplicant_Other_Income_Source	= CreditSmarts.DBO.Capitalize(CO_APPLICANT.Other_Source),
	CoApplicant_Total_Income		= ISNULL(CO_APPLICANT.Gross_Monthly, 0) + ISNULL(CO_APPLICANT.OTHER_MONTHLY, 0)

	,Applicant_EMail					= APPLICANT.EMAIL_ADDRESS,
	CoApplicant_EMail				= CO_APPLICANT.EMAIL_ADDRESS


FROM
	tblLoanApps			APP		WITH (NOLOCK)

	INNER JOIN		tblLoanApp_Applicant	APPLICANT				WITH (NOLOCK)	ON APPLICANT.LoanAppID = APP.LoanAppID
	LEFT OUTER JOIN	tblLoanApp_Applicant	CO_APPLICANT			WITH (NOLOCK)	ON CO_APPLICANT.LoanAppID = APP.LoanAppID AND CO_APPLICANT.LoanApp_ApplicantID > APPLICANT.LoanApp_ApplicantID
	LEFT OUTER JOIN	tblLoanApp_CurrEmployer	APPLICANT_EMPLOYER		WITH (NOLOCK)	ON APPLICANT_EMPLOYER.LoanApp_ApplicantID = APPLICANT.LoanApp_ApplicantID
	LEFT OUTER JOIN	tblLoanApp_CurrEmployer	CO_APPLICANT_EMPLOYER	WITH (NOLOCK)	ON CO_APPLICANT_EMPLOYER.LoanApp_ApplicantID = CO_APPLICANT.LoanApp_ApplicantID

--WHERE  LEN(ISNULL(APPLICANT.HOME_PHONE_AREA_CODE, '')) = 3 AND LEN(ISNULL(CO_APPLICANT.RELATIONSHIP_TO_PRIMARY, '')) > 0

--WHERE 	CO_APPLICANT.LoanApp_ApplicantID IS NOT NULL


--ORDER BY	APP.LoanAppID DESC




