/****** Object:  View dbo.viewLoanApp_ApplicantInfo    Script Date: 7/31/2024 12:57:17 PM ******/
CREATE VIEW viewLoanApp_ApplicantInfo AS
	SELECT
		LoanAppID					= CreditApp.LoanAppID,
		DealerID					= CONVERT(INTEGER, CreditApp.DealerID),
		Applicants					= CASE WHEN Applicant_2.LoanApp_ApplicantID IS NULL THEN 1 ELSE 2 END,

		Primary_ApplicantID			= Applicant_1.LoanApp_ApplicantID,
		Primary_Name				= CONVERT(VARCHAR(40), ISNULL(DBO.ProperCase(Applicant_1.First_Name	+ ' ' + Applicant_1.Last_Name), '')),
		Primary_AddressID			= Address_1.LoanApp_CurrAddresID,
		Primary_Address1			= DBO.ProperCase(Address_1.Street_1),
		Primary_Address2			= DBO.ProperCase(Address_1.City) + ' ' + UPPER(Address_1.State) + ' ' + CONVERT(VARCHAR(5), Address_1.ZIP),

		Secondary_ApplicantID		= Applicant_2.LoanApp_ApplicantID,
		Secondary_Name				= CONVERT(VARCHAR(40), ISNULL(DBO.ProperCase(Applicant_2.First_Name	+ ' ' + Applicant_2.Last_Name), '')),
		Secondary_AddressID			= Address_2.LoanApp_CurrAddresID,
		Secondary_Address1			= DBO.ProperCase(Address_2.Street_2),
		Secondary_Address2			= DBO.ProperCase(Address_2.City) + ' ' + UPPER(Address_2.State) + ' ' + CONVERT(VARCHAR(5), Address_2.ZIP)
	FROM
					tblLoanApps					CreditApp			WITH (NOLOCK) --ON CreditApp.LoanAppID	NP		= Batch.LoanAppID
			 JOIN	tblLoanApp_Applicant		Applicant_1			WITH (NOLOCK) ON Applicant_1.LoanAppID			= CreditApp.LoanAppID	--AND Applicant_1.Last_Name IS NOT NULL	AND LEN(Applicant_1.Last_Name) > 0
			 JOIN	tblLoanApp_CurrAddress		Address_1			WITH (NOLOCK) ON Address_1.LoanApp_ApplicantID	= Applicant_1.LoanApp_ApplicantID
		LEFT JOIN	tblLoanApp_Applicant		Applicant_2			WITH (NOLOCK) ON Applicant_2.LoanAppID			= CreditApp.LoanAppID AND Applicant_2.LoanApp_ApplicantID > Applicant_1.LoanApp_ApplicantID
		LEFT JOIN	tblLoanApp_CurrAddress		Address_2			WITH (NOLOCK) ON Address_2.LoanApp_ApplicantID IS NOT NULL AND Address_2.LoanApp_ApplicantID	= Applicant_2.LoanApp_ApplicantID
	WHERE
		Applicant_1.LoanApp_ApplicantID	IN (SELECT MIN(LoanApp_ApplicantID) FROM tblLoanApp_Applicant A1 WITH (NOLOCK) WHERE A1.LoanAppID = CreditApp.LoanAppID)


