/****** Object:  View dbo.viewLoanApp_Bids_CommentLogStats    Script Date: 7/31/2024 12:57:18 PM ******/


CREATE VIEW viewLoanApp_Bids_CommentLogStats AS

SELECT top 50
	LoanApp_BidID		= BID.LoanApp_BidID,
	LoanAppID,
	MESSAGING_STATUS	= ISNULL(BID.MESSAGING_STATUS, ''),
	TotalComments = ISNULL(TO_LENDER.CommentsToLender, 0) + ISNULL(TO_Dealer.CommentsToDealer, 0),	

	NewestComment = CASE
		WHEN TO_DEALER.LoanApp_BidID			IS NULL AND TO_LENDER.LoanApp_BidID IS NULL		THEN NULL
		WHEN TO_DEALER.LoanApp_BidID			IS NULL											THEN TO_LENDER.NewestCommentToLender
		WHEN TO_LENDER.LoanApp_BidID			IS NULL											THEN TO_DEALER.NewestCommentToDealer
		WHEN TO_DEALER.NewestCommentToDealer > TO_LENDER.NewestCommentToLender					THEN TO_DEALER.NewestCommentToDealer
		WHEN TO_LENDER.NewestCommentToLender > TO_DEALER.NewestCommentToDealer					THEN TO_LENDER.NewestCommentToLender
	END,

	NewestCommentAge = CASE
		WHEN TO_DEALER.LoanApp_BidID			IS NULL AND TO_LENDER.LoanApp_BidID IS NULL		THEN NULL

		WHEN TO_DEALER.LoanApp_BidID			IS NULL											THEN DATEDIFF(day, NewestCommentToLender, GETDATE())
		WHEN TO_LENDER.LoanApp_BidID			IS NULL											THEN DATEDIFF(day, NewestCommentToDealer, GETDATE())

		WHEN TO_DEALER.NewestCommentToDealer > TO_LENDER.NewestCommentToLender					THEN DATEDIFF(day, NewestCommentToDealer, GETDATE())
		WHEN TO_LENDER.NewestCommentToLender > TO_DEALER.NewestCommentToDealer					THEN DATEDIFF(day, NewestCommentToLender, GETDATE())
	END,

	CommentsToLender = ISNULL(TO_LENDER.CommentsToLender, 0),
	NewestCommentToLenderAge = DATEDIFF(day, NewestCommentToLender, GETDATE()),
	TO_LENDER.NewestCommentToLender,

	CommentsToDealer = ISNULL(TO_Dealer.CommentsToDealer, 0),
	NewestCommentToDealerAge = DATEDIFF(day, NewestCommentToDealer, GETDATE()),
	TO_DEALER.NewestCommentToDealer

FROM
					tblLoanApp_Bids									BID			WITH (NOLOCK)
	LEFT OUTER JOIN	viewLoanApp_Bids_CommentLogStats_ToDealer 		TO_DEALER	WITH (NOLOCK)	ON BID.LoanApp_BidID = TO_DEALER.LoanApp_BidID
	LEFT OUTER JOIN	viewLoanApp_Bids_CommentLogStats_ToLender 		TO_LENDER	WITH (NOLOCK)	ON BID.LoanApp_BidID = TO_LENDER.LoanApp_BidID




