/****** Object:  View dbo.viewLoanApp_RedirectQueue    Script Date: 7/31/2024 12:57:18 PM ******/

CREATE VIEW viewLoanApp_RedirectQueue AS
	SELECT TOP 100 PERCENT
		LoanAppID		= Bid.LoanAppID,
		LoanApp_BidID	= Bid.LoanApp_BidID,
		DealerID		= CONVERT(INTEGER, App.DealerID),
		Dealer			= CASE Dealer.DealerID
			WHEN 27659	THEN 'LendingTree (Purchase)'
			WHEN 27662	THEN 'LendingTree (Refinance)'
			ELSE DBO.ProperCase(Dealer.DealerName)
		END,
		LendersBranchID	= Branch.LendersBranchID,
		Branch			= DBO.ProperCase(Branch.BranchName),
		LenderID		= Branch.LenderID,
		Lender			= DBO.ProperCase(Lender.LenderName),
		PartnerToolID	= CASE

			WHEN EXISTS(SELECT PDE.PartnerToolID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblPartnerTools PT WITH (NOLOCK) ON PT.PartnerToolID = PDE.PartnerToolID WHERE PDE.LoanApp_BidID = Bid.LoanApp_BidID AND LEN(ISNULL(PDE.DataValue, '')) > 0) THEN
				(SELECT TOP 1 PDE.PartnerToolID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblPartnerTools PT WITH (NOLOCK) ON PT.PartnerToolID = PDE.PartnerToolID WHERE PDE.LoanApp_BidID = Bid.LoanApp_BidID AND LEN(ISNULL(PDE.DataValue, '')) > 0 ORDER BY PartnerDataElementID DESC)
-- ORDER BY PDE.UpdateDateTime DESC)


			WHEN EXISTS(SELECT PDE.PartnerToolID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblPartnerTools PT WITH (NOLOCK) ON PT.PartnerToolID = PDE.PartnerToolID WHERE PDE.LoanAppID = Bid.LoanAppID AND LEN(ISNULL(PDE.DataValue, '')) > 0) THEN
				(SELECT TOP 1 PDE.PartnerToolID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblPartnerTools PT WITH (NOLOCK) ON PT.PartnerToolID = PDE.PartnerToolID WHERE PDE.LoanAppID = Bid.LoanAppID AND LEN(ISNULL(PDE.DataValue, '')) > 0 ORDER BY PartnerDataElementID DESC)


/*
			WHEN EXISTS(SELECT PDE.PartnerToolID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblPartnerTools PT WITH (NOLOCK) ON PT.PartnerToolID = PDE.PartnerToolID WHERE PDE.LoanApp_BidID = Bid.LoanApp_BidID) THEN
				(SELECT TOP 1 PDE.PartnerToolID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblPartnerTools PT WITH (NOLOCK) ON PT.PartnerToolID = PDE.PartnerToolID WHERE PDE.LoanApp_BidID = Bid.LoanApp_BidID ORDER BY PDE.UpdateDateTime DESC)

			WHEN EXISTS(SELECT PDE.PartnerToolID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblPartnerTools PT WITH (NOLOCK) ON PT.PartnerToolID = PDE.PartnerToolID WHERE PDE.LoanAppID = Bid.LoanAppID) THEN
				(SELECT TOP 1 PDE.PartnerToolID FROM tblPartnerDataElement PDE WITH (NOLOCK) JOIN tblPartnerTools PT WITH (NOLOCK) ON PT.PartnerToolID = PDE.PartnerToolID WHERE PDE.LoanAppID = Bid.LoanAppID ORDER BY PDE.UpdateDateTime DESC)
*/

			ELSE NULL
		END,

		Status			= UPPER(REPLACE(Bid.Status, ' ', '_')),

		IsPendingLender		= CONVERT(BIT, CASE
			WHEN Bid.Status IN('PENDING_LENDER', 'REFERRED')	THEN 1
			ELSE 0
		END),

		IsPendingDealer		= CONVERT(BIT, CASE
			WHEN Bid.Status IN('PENDING_DEALER', 'DECLINE_LENDER', 'DECLINE_DEALER', 'ACCEPTED', 'Canceled By Lender')	THEN 1
			ELSE 0
		END),
	
		SubmitDate		= CASE
			WHEN Bid.Submit_Date		IS NOT NULL		THEN	Bid.Submit_Date
			WHEN Bid.CreateDateTime		IS NOT NULL		THEN	Bid.CreateDateTime
			WHEN Bid.UpdateDateTime		IS NOT NULL		THEN	Bid.UpdateDateTime
			WHEN App.UpdateDateTime		IS NOT NULL		THEN	App.UpdateDateTime
			WHEN App.CreateDateTime		IS NOT NULL		THEN	App.CreateDateTime
			ELSE '2001-01-01'		END,
	
		BidDate	= Bid.CreateDateTime,
		AppDate	= CASE
			WHEN App.UpdateDateTime IS NOT NULL AND App.CreateDateTime IS NOT NULL AND App.UpdateDateTime >= App.CreateDateTime		THEN	App.UpdateDateTime
			WHEN App.UpdateDateTime IS NOT NULL AND App.CreateDateTime IS NOT NULL AND App.UpdateDateTime <= App.CreateDateTime		THEN	App.CreateDateTime
			WHEN App.UpdateDateTime IS NOT NULL THEN	App.UpdateDateTime
			ELSE App.CreateDateTime
		END,
	
		SubmitAge				= DATEDIFF(hh, CASE
			WHEN Bid.Submit_Date		IS NOT NULL		THEN	Bid.Submit_Date
			WHEN Bid.CreateDateTime		IS NOT NULL		THEN	Bid.CreateDateTime
			WHEN Bid.UpdateDateTime		IS NOT NULL		THEN	Bid.UpdateDateTime
			WHEN App.UpdateDateTime		IS NOT NULL		THEN	App.UpdateDateTime
			WHEN App.CreateDateTime		IS NOT NULL		THEN	App.CreateDateTime
			ELSE '2001-01-01'		END, GETDATE()),

		BidAge			= DATEDIFF(hh, Bid.CreateDateTime, GETDATE()),
		AppAge			= DATEDIFF(hh, App.CreateDateTime, GETDATE())
	FROM
				tblLoanApp_Bids 	Bid		WITH (NOLOCK)
		JOIN	tblLoanApps			App		WITH (NOLOCK) ON App.LoanAppID			= Bid.LoanAppID
		JOIN	tblLendersBranches	Branch	WITH (NOLOCK) ON Branch.LendersBranchID	= Bid.LendersBranchID
		JOIN	tblLenders			Lender	WITH (NOLOCK) ON Lender.LenderID		= Branch.LenderID
		JOIN	tblDealers			Dealer	WITH (NOLOCK) ON Dealer.DealerID		= App.DealerID

--	WHERE
--		DATEDIFF(dd, Bid.CreateDateTime, GETDATE()) <= 10

	ORDER BY
		Bid.LoanApp_BidID	DESC,
		Bid.LoanAppID		DESC




