/****** Object:  View dbo.viewLoanApps_Income    Script Date: 7/31/2024 12:57:18 PM ******/


CREATE VIEW viewLoanApps_Income AS
	SELECT
		LoanAppID										=	PRIMARY_BORROWER.LoanAppID,
		TotalIncome									= ISNULL(PRIMARY_BORROWER.GROSS_MONTHLY, 0) + ISNULL(PRIMARY_BORROWER.OTHER_MONTHLY, 0) + ISNULL(SECONDARY_BORROWER.GROSS_MONTHLY, 0) + ISNULL(SECONDARY_BORROWER.OTHER_MONTHLY, 0),

		Primary_ApplicantID 				=	PRIMARY_BORROWER.LoanApp_ApplicantID,
		Primary_Name								= PRIMARY_BORROWER.FIRST_NAME + ' ' + PRIMARY_BORROWER.LAST_NAME,
		Primary_BaseIncome					= ISNULL(PRIMARY_BORROWER.GROSS_MONTHLY, 0),
		Primary_OtherIncome					= ISNULL(PRIMARY_BORROWER.OTHER_MONTHLY, 0),
		Primary_OtherSource					= ISNULL(PRIMARY_BORROWER.OTHER_SOURCE, ''),
		Primary_TotalIncome					=	ISNULL(PRIMARY_BORROWER.GROSS_MONTHLY, 0) + ISNULL(PRIMARY_BORROWER.OTHER_MONTHLY, 0),

		Secondary_ApplicantID 				=	SECONDARY_BORROWER.LoanApp_ApplicantID,
		Secondary_Name								= SECONDARY_BORROWER.FIRST_NAME + ' ' + SECONDARY_BORROWER.LAST_NAME,
		Secondary_BaseIncome					= ISNULL(SECONDARY_BORROWER.GROSS_MONTHLY, 0),
		Secondary_OtherIncome					= ISNULL(SECONDARY_BORROWER.OTHER_MONTHLY, 0),
		Secondary_OtherSource					= ISNULL(SECONDARY_BORROWER.OTHER_SOURCE, ''),
		Secondary_TotalIncome					=	ISNULL(SECONDARY_BORROWER.GROSS_MONTHLY, 0) + ISNULL(SECONDARY_BORROWER.OTHER_MONTHLY, 0)

	FROM
											tblLoanApp_Applicant PRIMARY_BORROWER 		WITH (NOLOCK)
		LEFT OUTER JOIN 	tblLoanApp_Applicant SECONDARY_BORROWER		WITH (NOLOCK) ON SECONDARY_BORROWER.LoanAppID = PRIMARY_BORROWER.LoanAppID AND SECONDARY_BORROWER.LoanApp_ApplicantID > PRIMARY_BORROWER.LoanApp_ApplicantID
WHERE
	PRIMARY_BORROWER.LoanApp_ApplicantID = (SELECT MIN(LoanApp_ApplicantID) FROM tblLoanApp_Applicant A WITH (NOLOCK) WHERE A.LoanAppID = PRIMARY_BORROWER.LoanAppID)





