/****** Object:  View dbo.viewLoanApps_OutstandingReportBackFill    Script Date: 7/31/2024 12:57:18 PM ******/


CREATE VIEW viewLoanApps_OutstandingReportBackFill AS

SELECT TOP 100 PERCENT
	BIDS_OUTER.LoanAppID,
	BIDS_OUTER.LoanApp_BidID,
	BRANCH.LenderID,
	BIDS_OUTER.LendersBranchID,
  Lender_Credit = CASE
		WHEN LEN(ISNULL(BIDS_CREDIT.LENDER_CREDIT_EX, '')) > 0  THEN BIDS_CREDIT.LENDER_CREDIT_EX
		WHEN LEN(ISNULL(BIDS_CREDIT.LENDER_CREDIT_TU, '')) > 0  THEN BIDS_CREDIT.LENDER_CREDIT_TU
		WHEN LEN(ISNULL(BIDS_CREDIT.LENDER_CREDIT_EQ, '')) > 0  THEN BIDS_CREDIT.LENDER_CREDIT_EQ
	END,
	BidCreate = BIDS_OUTER.CreateDateTime,
	BidUpdate = BIDS_OUTER.UpdateDateTime


 FROM
	tblLoanApp_Bids BIDS_OUTER WITH (NOLOCK)
		JOIN tblLendersBranches BRANCH WITH (NOLOCK) ON BIDS_OUTER.LendersBranchID=BRANCH.LendersBranchID
		JOIN tblLoanApp_Bids BIDS_CREDIT  WITH (NOLOCK) ON (BIDS_CREDIT.LoanAppID=BIDS_OUTER.LoanAppID AND BIDS_CREDIT.LendersBranchID IN
            (SELECT L.LendersBranchID FROM tblLendersBranches L WITH (NOLOCK) WHERE L.LenderID=BRANCH.LenderID) AND LEN(ISNULL(BIDS_CREDIT.LENDER_CREDIT_EX, '') + ISNULL(BIDS_CREDIT.LENDER_CREDIT_TU, '') + ISNULL(BIDS_CREDIT.LENDER_CREDIT_EQ, '')) > 0)

	WHERE BIDS_OUTER.CreateDateTime >= DATEADD(dd, -60, GETDATE())
    --AND BIDS_OUTER.CreateDateTime > '2010-09-16'
	AND (ISNULL(BIDS_OUTER.PTI,0)=0 OR ISNULL(BIDS_OUTER.DTI,0)=0 OR ISNULL(BIDS_OUTER.PRIMARY_SCORE,0)=0)

    AND(
        CONVERT(uniqueidentifier, NULLIF(BIDS_CREDIT.LENDER_CREDIT_EX, '')) IN (SELECT GUID FROM tblCreditPulls WITH (NOLOCK))
        OR
        CONVERT(uniqueidentifier, NULLIF(BIDS_CREDIT.LENDER_CREDIT_TU, ''))  IN (SELECT GUID FROM tblCreditPulls WITH (NOLOCK))
        OR
        CONVERT(uniqueidentifier, NULLIF(BIDS_CREDIT.LENDER_CREDIT_EQ, ''))  IN (SELECT GUID FROM tblCreditPulls WITH (NOLOCK))
)

GROUP BY
	BIDS_OUTER.LoanAppID,
	BIDS_OUTER.LoanApp_BidID,
	BRANCH.LenderID,
	BIDS_OUTER.LendersBranchID,
  CASE
		WHEN LEN(ISNULL(BIDS_CREDIT.LENDER_CREDIT_EX, '')) > 0  THEN BIDS_CREDIT.LENDER_CREDIT_EX
		WHEN LEN(ISNULL(BIDS_CREDIT.LENDER_CREDIT_TU, '')) > 0  THEN BIDS_CREDIT.LENDER_CREDIT_TU
		WHEN LEN(ISNULL(BIDS_CREDIT.LENDER_CREDIT_EQ, '')) > 0  THEN BIDS_CREDIT.LENDER_CREDIT_EQ
	END,
	BIDS_OUTER.CreateDateTime,
	BIDS_OUTER.UpdateDateTime

ORDER BY
	BIDS_OUTER.LoanAppID DESC,
	BIDS_OUTER.LoanApp_BidID DESC





GO

