	SELECT
		[LoanAppID]													= [Bid].[LoanAppID],
		[ShortName]													= MIN([Partner].[ShortName]),
		[DisplayName]												= MIN([Partner].[DisplayName]),
		[PartnerToolID]											= [Partner].[PartnerToolID],
