		JOIN	[tblPartnerDataElement]					[PDE]				WITH (NOLOCK) ON [PDE].[LenderID] = 0 AND [PDE].[LendersBranchID] = 0 AND [PDE].[DealerID] = 0 AND ([PDE].[LoanAppID] > 0 OR [PDE].[LoanApp_BidID] > 0) AND [PDE].[LoanAppID] IN (0, [Bid].[LoanAppID]) AND [PDE].[LoanApp_BidID] IN (0, [Bid].[LoanApp_BidID]) AND ([PDE].[LoanAppID] = [Bid].[LoanAppID] OR [PDE].[LoanApp_BidID] = [Bid].[LoanApp_BidID]) AND [PDE].[DataValue] <> ''
		JOIN	[tblPartnerTools]								[Partner]		WITH (NOLOCK) ON [Partner].[PartnerToolID] = [PDE].[PartnerToolID]
		JOIN	[tblPartnerElementDefinition]		[PED]				WITH (NOLOCK)	ON [PED].[PartnerToolID] = [Partner].[PartnerToolID] AND [PED].ValueType = 'PARTNER_LOAN_ID' AND [PED].[Field] = [PDE].[Field] 		
