/****** Object:  View dbo.viewMessaging_BidMessagingStatus    Script Date: 7/31/2024 12:57:18 PM ******/
CREATE VIEW viewMessaging_BidMessagingStatus AS
	SELECT --TOP 100
		[LoanAppID]						= [Bids].[LoanAppID],
		[LoanApp_BidID]					= [Bids].[LoanApp_BidID],
		[LenderID]						= [Branch].[LenderID],
		[LendersBranchID]				= [Branch].[LendersBranchID],
		--[DealerID]						= [Dealer].[DealerID],

		[Messaging_Count]				= COUNT([Messaging_Bid].[LoanApp_Bids_CommentLogID]),
		[Messaging_LowID]				= MIN([Messaging_Bid].[LoanApp_Bids_CommentLogID]),
		[Messaging_HighID]				= MAX([Messaging_Bid].[LoanApp_Bids_CommentLogID]),
		[Messaging_LowDate]				= MIN([Messaging_Bid].[DateTime]),
		[Messaging_HighDate]			= MAX([Messaging_Bid].[DateTime]),

		[Lender_Count]					= COUNT([Messaging_Lender].[LoanApp_Bids_CommentLogID]),
		[Lender_LowID]					= MIN([Messaging_Lender].[LoanApp_Bids_CommentLogID]),
		[Lender_HighID]					= MAX([Messaging_Lender].[LoanApp_Bids_CommentLogID]),
		[Lender_LowDate]				= MIN([Messaging_Lender].[DateTime]),
		[Lender_HighDate]				= MAX([Messaging_Lender].[DateTime]),

		[Dealer_Count]					= COUNT([Messaging_Dealer].[LoanApp_Bids_CommentLogID]),
		[Dealer_LowID]					= MIN([Messaging_Dealer].[LoanApp_Bids_CommentLogID]),
		[Dealer_HighID]					= MAX([Messaging_Dealer].[LoanApp_Bids_CommentLogID]),
		[Dealer_LowDate]				= MIN([Messaging_Dealer].[DateTime]),
		[Dealer_HighDate]				= MAX([Messaging_Dealer].[DateTime])
	FROM
					tblLoanApp_Bids 					[Bids] 				WITH (NOLOCK)
			 JOIN	tblLendersBranches					[Branch]			WITH (NOLOCK) ON [Branch].[LendersBranchID]				= [Bids].[LendersBranchID]
		LEFT JOIN	tblLoanApp_Bids_CommentLog			[Messaging_Bid]		WITH (NOLOCK) ON [Messaging_Bid].[LoanApp_BidID]		= [Bids].[LoanApp_BidID]		--AND [Messaging_Lender].[From] = 'LENDER'
		LEFT JOIN	tblLoanApp_Bids_CommentLog			[Messaging_Lender]	WITH (NOLOCK) ON [Messaging_Bid].[LoanApp_BidID]	IS NOT NULL		AND (  [Messaging_Lender].[LoanApp_BidID]		= [Bids].[LoanApp_BidID]		AND [Messaging_Lender].[From] = 'LENDER' 	)
		LEFT JOIN	tblLoanApp_Bids_CommentLog			[Messaging_Dealer]	WITH (NOLOCK) ON  [Messaging_Bid].[LoanApp_BidID]	IS NOT NULL		AND (  [Messaging_Dealer].[LoanApp_BidID]		= [Bids].[LoanApp_BidID]		AND [Messaging_Dealer].[From] = 'DEALER'	)
	--WHERE
	--		[Bids].[CreateDateTime] >= '2015-12-05'
	GROUP BY
		[Bids].[LoanAppID],
		[Bids].[LoanApp_BidID],
		[Branch].[LenderID],
		[Branch].[LendersBranchID]
--,		[Dealer].[DealerID]


