/****** Object:  View dbo.viewOutstandingOfferMessage    Script Date: 7/31/2024 12:57:18 PM ******/

CREATE VIEW viewOutstandingOfferMessage AS
	SELECT TOP 100 PERCENT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		LenderID				= Branch.LenderID,
		LendersBranchID			= Branch.LendersBranchID,
		PartnerToolID			= PDE.PartnerToolID,
		PartnerDataElementID	= PDE.PartnerDataElementID,
		--DealerID				= CONVERT(INTEGER, CreditApp.DealerID),
		BidStatus				= Bid.Status,
		When_Sent				= CONVERT(DATETIME, PDE.DataValue),
		When_Offer				= Bid.Offer_Date,
		When_Message			= Message.[DateTime]

		/*,
		DataValue				= CONVERT(DATETIME, PDE.DataValue),
		Offer_Date				= ISNULL(Bid.Offer_Date, Bid.UpdateDateTime),
		Field					= PDE.Field,
		Diff_Sent_Offer			= DATEDIFF(mi, Bid.Offer_Date, PDE.DataValue),
		Diff_Sent_Message		= DATEDIFF(mi, Message.[DateTime], PDE.DataValue)
		*/
	FROM 
				tblLoanApp_Bids					Bid					WITH (NOLOCK)
		JOIN	tblPartnerDataElement			PDE					WITH (NOLOCK)	ON PDE.LoanApp_BidID			= Bid.LoanApp_BidID			AND		PDE.[Field]		= 'LastSentDateTime'	AND ISDATE(PDE.[DataValue])		= 1
		JOIN	tblloanapp_bids_CommentLog		Message				WITH (NOLOCK)	ON Bid.LoanApp_BidID			= Message.LoanApp_BidID		AND		Message.[From]	= 'Lender'				AND	Message.[DateTime]	IS NOT NULL

		JOIN	tblLendersBranches				Branch				WITH (NOLOCK)	ON Branch.LendersBranchID		= Bid.LendersBranchID
		--JOIN	tblLoanApps						CreditApp			WITH (NOLOCK)	ON CreditApp.LoanAppID	= Bid.LoanAppID
		--JOIN	tblLenders						Lender				WITH (NOLOCK)	ON Lender.LenderID			= Branch.LenderID

	WHERE
			Bid.Status																	IN	('PENDING_DEALER', 'DECLINE_LENDER') 
		AND Bid.Offer_Date																IS	NOT NULL
		AND Message.[DateTime]															IS	NOT NULL
		AND CONVERT(DATETIME,	PDE.DataValue)											>=	Bid.Offer_Date
		AND CONVERT(DATETIME,	PDE.DataValue)											>=	Message.[DateTime]
		AND ABS(DATEDIFF(mi, Bid.Offer_Date,		Bid.Offer_Date))					<=	5
		AND ABS(DATEDIFF(mi, Bid.Offer_Date,		CONVERT(DATETIME, PDE.DataValue)))	<	5
		AND	ABS(DATEDIFF(mi, Message.[DateTime],	CONVERT(DATETIME, PDE.DataValue)))	<	5
		AND ABS(DATEDIFF(hh, PDE.UpdateDateTime,	GETDATE()))							<	24 * 3		
	ORDER BY
		Message.LoanApp_BidID		DESC




