/****** Object:  View dbo.viewPartnerData    Script Date: 7/31/2024 12:57:18 PM ******/
CREATE VIEW viewPartnerData AS
	SELECT
		LoanApp_BidID				= PDE.LoanApp_BidID,
		LoanAppID					= ISNULL(NULLIF(PDE.LoanAppID,			0),	App.LoanAppID			),
		LenderID					= ISNULL(NULLIF(PDE.LenderID,			0),	Branch.LenderID			),
		LendersBranchID				= ISNULL(NULLIF(PDE.LendersBranchID,	0), Branch.LendersBranchID	),
		DealerID					= ISNULL(NULLIF(PDE.DealerID,			0),	Dealer.DealerID			),
		PartnerDataElementID		= PDE.PartnerDataElementID,
		PartnerToolID				= PDE.PartnerToolID,
		Partner						= Partner.ShortName,
		Field						= ISNULL(PED.Field, PDE.Field),
		Value						= PDE.DataValue,

		Value_Date					= DBO.csParseDate(PDE.DataValue, GETDATE(), GETUTCDATE()),
		Value_Int					= DBO.csParseInt(PDE.DataValue),
		ValueType					= ISNULL(NULLIF(PED.ValueType, ''), 'UNKNOWN'),
		Caption						= ISNULL(NULLIF(PED.Caption, ''), REPLACE(ISNULL(PED.Field, PDE.Field), '_', ' ')),

		Version						= PDE.rowVersion,
		Created						= PDE.CreateDateTime,
		Updated						= PDE.UpdateDateTime,
		CreatedBy					= PDE.CreateUser,
		UpdatedBy					= PDE.UpdateUser

		/*
		PDE_DealerID				= PDE.DealerID,
		PDE_LenderID				= PDE.LenderID,
		PDE_LendersBranchID			= PDE.LendersBranchID,
		PDE_LoanAppID				= PDE.LoanAppID,
		PDE_LoanApp_BidID			= PDE.LoanApp_BidID,
		*/
	FROM 
					tblPartnerDataElement		PDE			WITH (NOLOCK)
		LEFT JOIN	tblPartnerTools				Partner		WITH (NOLOCK) ON Partner.PartnerToolID		= PDE.PartnerToolID
		LEFT JOIN	tblPartnerElementDefinition	PED			WITH (NOLOCK) ON PED.PartnerToolID			= PDE.PartnerToolID		AND PED.Field	= PDE.Field
		LEFT JOIN	tblLoanApp_Bids				Bid			WITH (NOLOCK) ON Bid.LoanApp_BidID			= PDE.LoanApp_BidID
		LEFT JOIN	tblLoanApps					App			WITH (NOLOCK) ON App.LoanAppID				= Bid.LoanAppID
		LEFT JOIN	tblLendersBranches			Branch		WITH (NOLOCK) ON Branch.LendersBranchID		= Bid.LendersBranchID
		LEFT JOIN	tblDealers					Dealer		WITH (NOLOCK) ON Dealer.DealerID			= App.DealerID
	WHERE
		PDE.LoanApp_BidID							<> 0			AND
		PDE.DealerID								=  0			AND
		PDE.LenderID								=  0			AND
		PDE.LendersBranchID							=  0			AND
		PDE.LoanAppID								=  0			AND
		ISNULL(PED.KeyedFromLoanApp_BidID, 1)		=  1

	/*
	ORDER BY
		PDE.PartnerDataElementID DESC;
	*/


