/****** Object:  View dbo.viewPartnerDataElementPurgeInvalidKeys    Script Date: 7/31/2024 12:57:18 PM ******/
CREATE VIEW viewPartnerDataElementPurgeInvalidKeys AS
	SELECT [KeyType] = 'LoanAppID', [KeyValue] = [PDE].[LoanAppID], [PartnerDataElementID] FROM [tblPartnerDataElement] [PDE] WITH (NOLOCK) WHERE 
	/*[LenderID] = 0 AND [PDE].[LendersBranchID] = 0 AND [PDE].[DealerID] = 0 AND*/ [PDE].[LoanAppID] > 0
		AND NOT EXISTS(SELECT * FROM [tblLoanApps] [Apps] WITH (NOLOCK) WHERE [Apps].[LoanAppID] = [PDE].[LoanAppID])
		AND NOT EXISTS(SELECT * FROM [tblLoanApp_Bids] [Target] WITH (NOLOCK) WHERE [Target].[LoanAppID] = [PDE].[LoanAppID])
	UNION ALL
	SELECT [KeyType] = 'LoanApp_BidID', [KeyValue] = [PDE].[LoanApp_BidID], [PartnerDataElementID] FROM [tblPartnerDataElement] [PDE] WITH (NOLOCK) WHERE 
	/*[LenderID] = 0 AND [PDE].[LendersBranchID] = 0 AND [PDE].[DealerID] = 0 AND*/ [PDE].[LoanApp_BidID] > 0
		AND NOT EXISTS(SELECT * FROM [tblLoanApp_Bids] [Target] WITH (NOLOCK) WHERE [Target].[LoanApp_BidID] = [PDE].[LoanApp_BidID])
	UNION ALL
	SELECT [KeyType] = 'LenderID', [KeyValue] = [PDE].[LenderID], [PartnerDataElementID] FROM [tblPartnerDataElement] [PDE] WITH (NOLOCK) WHERE 
		[PDE].[LenderID] > 0
		AND NOT EXISTS(SELECT * FROM [tblLenders] [Target] WITH (NOLOCK) WHERE [Target].[LenderID] = [PDE].[LenderID])
	UNION ALL
	SELECT [KeyType] = 'DealerID', [KeyValue] = [PDE].[DealerID], [PartnerDataElementID] FROM [tblPartnerDataElement] [PDE] WITH (NOLOCK) WHERE
	[PDE].[DealerID] > 0
		AND NOT EXISTS(SELECT * FROM [tblDealers] [Target] WITH (NOLOCK) WHERE [Target].[DealerID] = [PDE].[DealerID])

