/****** Object:  View dbo.viewPartnerElementDefinition    Script Date: 7/31/2024 12:57:18 PM ******/

CREATE VIEW viewPartnerElementDefinition AS
	SELECT TOP 100 PERCENT
		PartnerToolID				= PartnerTool.PartnerToolID,
		Partner						= PartnerTool.ShortName,
		Field						= PED.Field,
		Caption						= PED.Caption,
		ValueType					= PED.ValueType,
		Description					= LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(DBO.ProperCase(ISNULL(NULLIF(PED.Description, ''), REPLACE(ValueType, '_', ' '))) + ' ', ' Id ', ' ID '), ' Url', ' URL '), ' FTP ', ' FTP '), ' SFTP ', ' SFTP '), ' AUTH ', ' '))),
		Show_Dealer					= PED.ShowOnDealerAdmin,
		Show_Lender					= PED.ShowOnLenderAdmin,
		Show_Branch					= PED.ShowOnLendersBranchAdmin,
		--Show_Affiliate			= PED.ShowOnAffiliateAdmin,
		Keyed_LoanAppID				= PED.KeyedFromLoanAppID,
		Keyed_LoanApp_BidID			= PED.KeyedFromLoanApp_BidID,
		Keyed_LenderID				= PED.KeyedFromLenderID,
		Keyed_LendersBranchID		= PED.KeyedFromLendersBranchID,
		Keyed_DealerID				= PED.KeyedFromDealerID
	FROM
				tblPartnerTools				PartnerTool		WITH (NOLOCK)
		JOIN	tblPartnerElementDefinition PED				with (NOLOCK) ON PED.PartnerToolID = PartnerTool.PartnerToolID	AND	PED.Active = 1
	WHERE
			PartnerTool.Active	= 1
	ORDER BY
		PartnerTool.ShortName,
		PartnerTool.PartnerToolID,
		SortSequence,
		Field
	



