/****** Object:  View dbo.viewPartnerFieldDefinitions    Script Date: 7/31/2024 12:57:18 PM ******/
	CREATE VIEW viewPartnerFieldDefinitions AS
		SELECT
			[PartnerToolID]									= [PED].[PartnerToolID],
			[PartnerElementDefinitionID]		= [PED].[PartnerElementDefinitionID],
			[Partner]												= LEFT([Partner].[ShortName], 30),
			[Field]													= [PED].[Field],
			[ValueType]											= [PED].[ValueType],
			[Value]													= NULLIF(RTRIM([PED].[Value]), ''),

			[isPartnerLenderID]							= CONVERT(BIT, CASE WHEN [PED].[Active] = 1 AND [PED].[ValueType] = 'PARTNER_LENDER_ID' THEN 1 ELSE 0 END),
			[isPartnerLoanID]								= CONVERT(BIT, CASE WHEN [PED].[Active] = 1 AND [PED].[ValueType] = 'PARTNER_LOAN_ID'		THEN 1 ELSE 0 END),
			[isPartnerDealerID]							= CONVERT(BIT, CASE WHEN [PED].[Active] = 1 AND [PED].[ValueType] = 'PARTNER_DEALER_ID' THEN 1 ELSE 0 END),

			[KeyedFromLoan]									= CONVERT(BIT, CASE WHEN ISNULL([PED].[KeyedFromLoanAppID],	1) = 1 OR ISNULL([PED].[KeyedFromLoanApp_BidID],		1)	= 1	THEN 1 ELSE 0 END),
			[KeyedFromLender]								= CONVERT(BIT, CASE WHEN ISNULL([PED].[KeyedFromLenderID],	1) = 1 OR ISNULL([PED].[KeyedFromLendersBranchID],	1)	= 1	THEN 1 ELSE 0 END),
			[KeyedFromLoanAppID]						= CONVERT(BIT, ISNULL([PED].[KeyedFromLoanAppID],				1)),
			[KeyedFromLoanApp_BidID]				= CONVERT(BIT, ISNULL([PED].[KeyedFromLoanApp_BidID],		1)),
			[KeyedFromLenderID]							= CONVERT(BIT, ISNULL([PED].[KeyedFromLenderID],				1)),
			[KeyedFromLendersBranchID]			= CONVERT(BIT, ISNULL([PED].[KeyedFromLendersBranchID],	1)),
			[KeyedFromDealerID]							= CONVERT(BIT, ISNULL([PED].[KeyedFromDealerID],				1)),
			[Created]												= [PED].[CreateDateTime],
			[UpdatedAgo]										= DATEDIFF(ss, [PED].[UpdateDateTime], GETDATE())
		FROM
						[tblPartnerTools]							[Partner]		WITH (NOLOCK)
			JOIN	[tblPartnerElementDefinition] [PED] 			WITH (NOLOCK) ON [PED].[PartnerToolID]		= [Partner].[PartnerToolID]
		WHERE
					[PED].[Active] = 1
			AND [PED].[Field] NOT IN ('Dealer Enabled (CreditSmarts)', 'Dealer Enabled (Lender)')
			-- AND [PED].[PartnerToolID] = 2
		-- ORDER BY
			-- [Partner].[PartnerToolID],
			-- [PED].[Field]

