/****** Object:  View dbo.viewPartnerFields    Script Date: 7/31/2024 12:57:18 PM ******/

CREATE VIEW viewPartnerFields AS
	SELECT TOP 100 PERCENT
		PartnerToolID	= PARTNER.PartnerToolID,
		Partner			= PARTNER.ShortName,
		PartnerName		= PARTNER.DisplayName,
		Field			= DEFINITION.Field,
		ValueType		= DEFINITION.ValueType,
		Caption			= DEFINITION.Caption,
	
		KeyedBy	= REPLACE(LTRIM(
			CASE WHEN ISNULL(DEFINITION.KeyedFromLoanAppID,			0) = 1 THEN ' App'			ELSE '' END +
			CASE WHEN ISNULL(DEFINITION.KeyedFromLoanApp_BidID,		0) = 1 THEN ' Bid'			ELSE '' END +
			CASE WHEN ISNULL(DEFINITION.KeyedFromLenderID,			0) = 1 THEN ' Lender'		ELSE '' END +
			CASE WHEN ISNULL(DEFINITION.KeyedFromLendersBranchID,	0) = 1 THEN ' Branch'		ELSE '' END +
			CASE WHEN ISNULL(DEFINITION.KeyedFromDealerID,			0) = 1 THEN ' Dealer'		ELSE '' END +
			CASE WHEN ISNULL(DEFINITION.KeyedFromAffiliateID,		0) = 1 THEN ' Affiliate'	ELSE '' END ), ' ', ', '),
	
		ShowOn	= REPLACE(LTRIM(
			CASE WHEN ISNULL(ShowOnDealerAdmin,						0) = 1 THEN ' Dealer'		ELSE '' END +
			CASE WHEN ISNULL(ShowOnLenderAdmin,						0) = 1 THEN ' Lender'		ELSE '' END +
			CASE WHEN ISNULL(ShowOnLendersBranchAdmin,				0) = 1 THEN ' Branch'		ELSE '' END +
			CASE WHEN ISNULL(ShowOnAffiliateAdmin,					0) = 1 THEN ' Affiliate'	ELSE '' END +
			CASE WHEN ISNULL(ShowOnLenderDealerConsoleAdmin,		0) = 1 THEN ' Console'		ELSE '' END), ' ', ', '),
		PartnerElementDefinitionID	= DEFINITION.PartnerElementDefinitionID,
		Value						= DEFINITION.Value,
		SortSequence				= DEFINITION.SortSequence
	
		FROM 
					tblPartnerTools					PARTNER			WITH (NOLOCK)
			JOIN	tblPartnerElementDefinition		DEFINITION		WITH (NOLOCK) ON	DEFINITION.PartnerToolID = PARTNER.PartnerToolID	
		WHERE
			ISNULL(PARTNER.Active, 1) = 1
		ORDER BY
			PARTNER.ShortName,
			DEFINITION.SortSequence,
			DEFINITION.Caption




