/****** Object:  View dbo.viewPartnerIdentifierFields    Script Date: 7/31/2024 12:57:18 PM ******/
CREATE VIEW viewPartnerIdentifierFields AS
	SELECT
		[PartnerToolID]				= [Partner].[PartnerToolID],
		[Partner]							= MIN([Partner].[ShortName]),
		[hasApplicationID]		= CONVERT(BIT, CASE WHEN [PED_Application_ID].[Field]	IS NULL THEN 0 ELSE 1 END),
		[hasLenderID]					= CONVERT(BIT, CASE WHEN [PED_Lender_ID].[Field]			IS NULL THEN 0 ELSE 1 END),
		[hasDealerID]					= CONVERT(BIT, CASE WHEN [PED_Dealer_ID].[Field]			IS NULL THEN 0 ELSE 1 END),
		[ApplicationID]				= ISNULL([PED_Application_ID].[Field],	''),
		[LenderID]						= ISNULL([PED_Lender_ID].[Field],				''),
		[DealerID]						= ISNULL([PED_Dealer_ID].[Field],				'')
	FROM
							[tblPartnerTools]									[Partner]								WITH (NOLOCK)
		LEFT JOIN	[tblPartnerElementDefinition]			[PED_Application_ID]		WITH (NOLOCK) ON [PED_Application_ID].[PartnerToolID]	= [Partner].[PartnerToolID] AND [PED_Application_ID].[Active]	= 1 AND [PED_Application_ID].[ValueType]	= 'PARTNER_LOAN_ID'
		LEFT JOIN	[tblPartnerElementDefinition]			[PED_Lender_ID]					WITH (NOLOCK) ON [PED_Lender_ID].[PartnerToolID]			= [Partner].[PartnerToolID] AND [PED_Lender_ID].[Active]			= 1 AND [PED_Lender_ID].[ValueType]				= 'PARTNER_LENDER_ID'
		LEFT JOIN	[tblPartnerElementDefinition]			[PED_Dealer_ID]					WITH (NOLOCK) ON [PED_Dealer_ID].[PartnerToolID]			= [Partner].[PartnerToolID] AND [PED_Dealer_ID].[Active] 			= 1 AND [PED_Dealer_ID].[ValueType]				= 'PARTNER_DEALER_ID'
	WHERE
		[PED_Application_ID].[Field]	IS NOT NULL		OR
		[PED_Lender_ID].[Field]			IS NOT NULL		OR
		[PED_Lender_ID].[Field]			IS NOT NULL
	GROUP BY
		[Partner].[PartnerToolID],
		[PED_Application_ID].[Field],
		[PED_Lender_ID].[Field],
		[PED_Dealer_ID].[Field]

	--= 'PARTNER_LOAN_ID' AND ([PED].[KeyedFromLoanApp_BidID] = 1 OR [PED].[KeyedFromLoanAppID] = 1)

/*
	[PED].[ValueType]
*/


