/****** Object:  View dbo.viewPartnerLenderDealerMatch    Script Date: 7/31/2024 12:57:18 PM ******/
create VIEW viewPartnerLenderDealerMatch AS
SELECT 
	PED.PartnerToolID, 
	PED.Field, 
	PED.ValueType,
	PDE.DataValue as 'PartnerValue',
	Dealer.DealerID,
	Dealer				= UPPER(Dealer.DealerName),
	Dealer_Location		= UPPER(Dealer.City + ', ' + Dealer.State),
	DealerType			= ISNULL(NULLIF(Dealer.DealerType, ''), 'Independent')
	--,pde.Partnerdataelementid 
FROM 
	tblPartnerTools PT WITH (NOLOCK) 
	JOIN tblPartnerElementDefinition PED WITH (NOLOCK) ON PED.PartnerToolID = PT.PartnerToolID 
	JOIN tblPartnerDataElement PDE WITH (NOLOCK) on PDE.PartnerToolID=PT.PartnerToolID AND PDE.Field=PED.Field
	JOIN tblDealers Dealer WITH (NOLOCK) on Dealer.DealerID=PDE.DealerID
WHERE PT.Active = 1 AND PED.Active = 1 AND PED.ValueType='PARTNER_DEALER_ID' AND PDE.DealerID > 0
--AND PT.ShortName = 'CUDL' 
--ORDER BY PDE.Field

