/****** Object:  View dbo.viewPartnerLenderSetup_Inner    Script Date: 7/31/2024 12:57:18 PM ******/
	CREATE VIEW [viewPartnerLenderSetup_Inner] AS
		SELECT
			[Lender_En].[PartnerToolID],
			[LenderID] = MIN([Branch].[LenderID]),
			[Branch].[LendersBranchID],
			[Active] = CONVERT(BIT, CASE WHEN MIN([Lender_En].[DataValue]) = '' THEN NULL WHEN LEFT(MIN([Lender_En].[DataValue]), 1) IN ('T', '1', '-') THEN 1 ELSE 0 END),
			[ActiveID] = MIN([Lender_En].[PartnerDataElementID]),
			[IdID] = ISNULL([Branch_ID].[PartnerDataElementID], [Lender_ID].[PartnerDataElementID]),
			[UnID] = [Value_UN].[PartnerDataElementID],
			[UnFixed] = ISNULL([Field_Un].[Value], ''),
			[PwID] = [Value_PW].[PartnerDataElementID],
			[PwFixed] = ISNULL([Field_Pw].[Value], ''),
			[UrlID] = [Value_URL].[PartnerDataElementID],
			[UrlFixed] = ISNULL([Field_Url].[Value], ''),
			[CrtID] = [Value_CRT].[PartnerDataElementID],
			[CrtFixed] = ISNULL([Field_Crt].[Value], '')
		FROM
								[tblPartnerDataElement]					[Lender_En]				WITH (NOLOCK)
			LEFT JOIN [tblLendersBranches]						[Branch1] 				WITH (NOLOCK)	ON																									[Branch1].[LendersBranchID]	= [Lender_En].[LendersBranchID]
			LEFT JOIN [tblLendersBranches]						[Branch2] 				WITH (NOLOCK)	ON																									[Branch2].[LenderID] 				= [Lender_En].[LenderID]
			JOIN			[tblLendersBranches]						[Branch] 					WITH (NOLOCK)	ON																									[Branch].[LendersBranchID]		= ISNULL([Branch1].[LendersBranchID], [Branch2].[LendersBranchID])
			LEFT JOIN	[tblPartnerElementDefinition]		[Field_ID]				WITH (NOLOCK)	ON																									[Field_ID].[PartnerToolID]		= [Lender_En].[PartnerToolID]		AND [Field_ID].[ValueType]	= 'PARTNER_LENDER_ID'				AND [Field_ID].[Active]						= 1																						AND ([Field_ID].[KeyedFromLenderID]	= 1 	OR	[Field_ID].[KeyedFromLendersBranchID]	= 1)
			LEFT JOIN	[tblPartnerDataElement]					[Branch_ID]				WITH (NOLOCK)	ON																									[Branch_ID].[PartnerToolID]	= [Field_ID].[PartnerToolID]		AND [Branch_ID].[Field]			= [Field_ID].[Field]				AND [Branch_ID].[LendersBranchID]	= [Branch].[LendersBranchID]									AND [Branch_ID].[LenderID]					= 0 	AND [Branch_ID].[LoanAppID]	= 0	AND [Branch_ID].[LoanApp_BidID]	= 0	AND [Branch_ID].[DealerID]	= 0	AND [Branch_ID].[DataValue] <> ''
			LEFT JOIN	[tblPartnerDataElement]					[Lender_ID]				WITH (NOLOCK)	ON [Branch_ID].[PartnerDataElementID] IS NULL AND 	[Lender_ID].[PartnerToolID]	= [Field_ID].[PartnerToolID]		AND [Lender_ID].[Field]			= [Field_ID].[Field] 				AND [Lender_ID].[LenderID]				= [Branch].[LenderID]													AND [Lender_ID].[LendersBranchID]		= 0 	AND [Lender_ID].[LoanAppID]	= 0	AND [Lender_ID].[LoanApp_BidID]	= 0	AND [Lender_ID].[DealerID]	= 0	AND [Lender_ID].[DataValue] <> ''

			LEFT JOIN	[tblPartnerElementDefinition]		[Field_URL]				WITH (NOLOCK)	ON																									[Field_URL].[PartnerToolID]	= [Lender_En].[PartnerToolID]		AND [Field_URL].[ValueType]	= 'PARTNER_POST_URL'				AND [Field_URL].[Active]					= 1 --	AND ([Field_URL].[KeyedFromLenderID]		= 1	OR 	[Field_URL].[KeyedFromLendersBranchID]	= 1)
			LEFT JOIN	[tblPartnerDataElement]					[Branch_URL]			WITH (NOLOCK)	ON ISNULL([Field_URL].[KeyedFromLendersBranchID], 0)	= 1	AND																								[Branch_URL].[PartnerToolID]	= [Field_URL].[PartnerToolID]		AND [Branch_URL].[Field]		= [Field_URL].[Field]				AND [Branch_URL].[LendersBranchID]	= [Branch].[LendersBranchID]								AND [Branch_URL].[LenderID] = 0   	AND [Branch_URL].[LoanAppID]	= 0	AND [Branch_URL].[LoanApp_BidID]	= 0	AND [Branch_URL].[DealerID]	= 0	AND [Branch_URL].[DataValue] 	<> ''
			LEFT JOIN	[tblPartnerDataElement]					[Lender_URL]			WITH (NOLOCK)	ON ISNULL([Field_URL].[KeyedFromLenderID], 0)	= 1	AND	 [Branch_URL].[PartnerDataElementID] 	IS NULL AND [Lender_URL].[PartnerToolID]	= [Field_URL].[PartnerToolID]		AND [Lender_URL].[Field]		= [Field_URL].[Field] 			AND [Lender_URL].[LenderID]				= [Branch].[LenderID]													AND [Lender_URL].[LendersBranchID]					= 0 	AND [Lender_URL].[LoanAppID]	= 0	AND [Lender_URL].[LoanApp_BidID]	= 0	AND [Lender_URL].[DealerID]	= 0	AND [Lender_URL].[DataValue] 	<> ''
			LEFT JOIN [tblPartnerDataElement]					[Partner_URL]			WITH (NOLOCK)	ON [Partner_URL].[PartnerToolID]		= [Field_URL].[PartnerToolID]		AND [Partner_URL].[Field]			= [Field_URL].[Field] 				AND [Partner_URL].[LenderID]				= 0													AND [Partner_URL].[LendersBranchID]						= 0 	AND [Partner_URL].[LoanAppID]	= 0		AND [Partner_URL].[LoanApp_BidID]		= 0	AND [Partner_URL].[DealerID]	= 0	AND [Partner_URL].[DataValue] 	<> ''
			LEFT JOIN	[tblPartnerDataElement]					[Value_URL]				WITH (NOLOCK)	ON [Value_URL].[PartnerDataElementID] = ISNULL([Branch_URL].[PartnerDataElementID], ISNULL([Lender_URL].[PartnerDataElementID], [Partner_URL].[PartnerDataElementID]))

			LEFT JOIN	[tblPartnerElementDefinition]		[Field_CRT]				WITH (NOLOCK)	ON																									[Field_CRT].[PartnerToolID]	= [Lender_En].[PartnerToolID]		AND ([Field_CRT].[Field] = 'CERTIFICATE' OR [Field_CRT].[ValueType]	= 'PARTNER_POST_CERTIFICATE')				AND [Field_CRT].[Active]					= 1 --	AND ([Field_CRT].[KeyedFromLenderID]		= 1	OR 	[Field_CRT].[KeyedFromLendersBranchID]	= 1)
			LEFT JOIN [tblPartnerDataElement]					[Value_CRT]				WITH (NOLOCK)	ON [Value_CRT].[PartnerToolID]		= [Lender_En].[PartnerToolID]		AND [Value_CRT].[Field]			= 'CERTIFICATE' 				AND [Value_CRT].[LenderID]				= 0													AND [Value_CRT].[LendersBranchID]						= 0 	AND [Value_CRT].[LoanAppID]	= 0		AND [Value_CRT].[LoanApp_BidID]		= 0	AND [Value_CRT].[DealerID]	= 0	AND [Value_CRT].[DataValue] 	<> ''

			LEFT JOIN	[tblPartnerElementDefinition]		[Field_UN]				WITH (NOLOCK)	ON [Field_UN].[PartnerToolID]		= [Lender_En].[PartnerToolID]		AND [Field_UN].[ValueType]	= 'PARTNER_AUTH_LOGIN'			AND [Field_UN].[Active]						= 1	--AND ([Field_UN].[KeyedFromLenderID]		= 1	OR	[Field_UN].[KeyedFromLendersBranchID]		= 1)
			LEFT JOIN	[tblPartnerDataElement]					[Branch_UN]				WITH (NOLOCK)	ON ISNULL([Field_UN].[KeyedFromLendersBranchID], 0)	= 1	AND																										[Branch_UN].[PartnerToolID]		= [Field_UN].[PartnerToolID]		AND [Branch_UN].[Field]			= [Field_UN].[Field]				AND [Branch_UN].[LendersBranchID]	= [Branch].[LendersBranchID]									AND [Branch_UN].[LenderID]									= 0 	AND [Branch_UN].[LoanAppID]	= 0		AND [Branch_UN].[LoanApp_BidID]		= 0	AND [Branch_UN].[DealerID]	= 0	AND [Branch_UN].[DataValue] 	<> ''
			LEFT JOIN	[tblPartnerDataElement]					[Lender_UN]				WITH (NOLOCK)	ON ISNULL([Field_URL].[KeyedFromLenderID], 0)	= 1	AND	  [Lender_UN].[PartnerToolID]		= [Field_UN].[PartnerToolID]		AND [Lender_UN].[Field]			= [Field_UN].[Field] 				AND [Lender_UN].[LenderID]				= [Branch].[LenderID]													AND [Lender_UN].[LendersBranchID]						= 0 	AND [Lender_UN].[LoanAppID]	= 0		AND [Lender_UN].[LoanApp_BidID]		= 0	AND [Lender_UN].[DealerID]	= 0	AND [Lender_UN].[DataValue] 	<> ''
			LEFT JOIN [tblPartnerDataElement]					[Partner_UN]			WITH (NOLOCK)	ON [Partner_UN].[PartnerToolID]		= [Field_UN].[PartnerToolID]		AND [Partner_UN].[Field]			= [Field_UN].[Field] 				AND [Partner_UN].[LenderID]				= 0													AND [Partner_UN].[LendersBranchID]						= 0 	AND [Partner_UN].[LoanAppID]	= 0		AND [Partner_UN].[LoanApp_BidID]		= 0	AND [Partner_UN].[DealerID]	= 0	AND [Partner_UN].[DataValue] 	<> ''
			LEFT JOIN	[tblPartnerDataElement]					[Value_UN]				WITH (NOLOCK)	ON [Value_UN].[PartnerDataElementID] = ISNULL([Branch_UN].[PartnerDataElementID], ISNULL([Lender_UN].[PartnerDataElementID], [Partner_UN].[PartnerDataElementID]))

			LEFT JOIN	[tblPartnerElementDefinition]		[Field_PW]				WITH (NOLOCK)	ON [Field_PW].[PartnerToolID]		= [Lender_En].[PartnerToolID]		AND [Field_PW].[ValueType]	= 'PARTNER_AUTH_PASSWORD'		AND [Field_PW].[Active]						= 1	--AND ([Field_PW].[KeyedFromLenderID]		= 1	OR 	[Field_PW].[KeyedFromLendersBranchID]		= 1)
			LEFT JOIN	[tblPartnerDataElement]					[Branch_PW]				WITH (NOLOCK)	ON ISNULL([Field_PW].[KeyedFromLendersBranchID], 0)	= 1	AND																										[Branch_PW].[PartnerToolID]		= [Field_PW].[PartnerToolID]		AND [Branch_PW].[Field]			= [Field_PW].[Field]				AND [Branch_PW].[LendersBranchID]	= [Branch].[LendersBranchID]									AND [Branch_PW].[LenderID]									= 0 	AND [Branch_PW].[LoanAppID]	= 0		AND [Branch_PW].[LoanApp_BidID]		= 0	AND [Branch_PW].[DealerID]	= 0	AND [Branch_PW].[DataValue] 	<> ''
			LEFT JOIN	[tblPartnerDataElement]					[Lender_PW]				WITH (NOLOCK)	ON ISNULL([Field_PW].[KeyedFromLenderID], 0)	= 1	AND	[Lender_PW].[PartnerToolID]		= [Field_PW].[PartnerToolID]		AND [Lender_PW].[Field]			= [Field_PW].[Field] 				AND [Lender_PW].[LenderID]				= [Branch].[LenderID]													AND [Lender_PW].[LendersBranchID]						= 0 	AND [Lender_PW].[LoanAppID]	= 0		AND [Lender_PW].[LoanApp_BidID]		= 0	AND [Lender_PW].[DealerID]	= 0	AND [Lender_PW].[DataValue] 	<> ''
			LEFT JOIN [tblPartnerDataElement]					[Partner_PW]			WITH (NOLOCK)	ON [Partner_PW].[PartnerToolID]		= [Field_PW].[PartnerToolID]		AND [Partner_PW].[Field]			= [Field_PW].[Field] 				AND [Partner_PW].[LenderID]				= 0													AND [Partner_PW].[LendersBranchID]						= 0 	AND [Partner_PW].[LoanAppID]	= 0		AND [Partner_PW].[LoanApp_BidID]		= 0	AND [Partner_PW].[DealerID]	= 0	AND [Partner_PW].[DataValue] 	<> ''
			LEFT JOIN	[tblPartnerDataElement]					[Value_PW]				WITH (NOLOCK)	ON [Value_PW].[PartnerDataElementID] = ISNULL([Branch_PW].[PartnerDataElementID], ISNULL([Lender_PW].[PartnerDataElementID], [Partner_PW].[PartnerDataElementID]))
		WHERE
					[Lender_En].[Field] = 'Lender Enabled (CreditSmarts)'
			AND [Lender_En].[LoanApp_BidID] = 0 AND [Lender_En].[LoanAppID] = 0 --AND [Lender_En].[LendersBranchID] = 0 AND [Lender_En].[LenderID] > 0
			AND EXISTS(SELECT * FROM [tblPartnerElementDefinition] [Field_En] WITH (NOLOCK) WHERE [Field_En].[PartnerToolID] = [Lender_En].[PartnerToolID] AND [Field_En].[Field] = [Lender_En].[Field] AND [Field_En].[Active] = 1)
			AND EXISTS(SELECT * FROM [tblLenders] 			[Lender]	WITH (NOLOCK) WHERE [Lender].[LenderID] = [Branch].[LenderID] AND [Lender].[LenderStatus] NOT IN ('INACTIVE', 'FAX', ''))
			AND	EXISTS(SELECT * FROM [tblPartnerTools] 	[Partner] WITH (NOLOCK) WHERE [Partner].[PartnerToolID] = [Lender_En].[PartnerToolID] AND [Partner].[Active] = 1)
			-- AND [Branch].[LenderID] = 45 AND [Partner].[PartnerToolID] = 2
		GROUP BY
			[Lender_En].[PartnerToolID],
			[Branch].[LendersBranchID],
			[Branch_ID].[PartnerDataElementID], [Lender_ID].[PartnerDataElementID],
			[Value_URL].[PartnerDataElementID],
			[Value_UN].[PartnerDataElementID],
			[Value_PW].[PartnerDataElementID],
			[Value_CRT].[PartnerDataElementID],
			[Field_UN].[Value],
			[Field_PW].[Value],
			[Field_URL].[Value],
			[Field_CRT].[Value]

