/****** Object:  View dbo.viewPartnerToolsExchangeServices    Script Date: 7/31/2024 12:57:19 PM ******/


CREATE VIEW [dbo].[viewPartnerToolsExchangeServices]
AS
SELECT     TOP 100 PERCENT PT.PartnerToolID, PT.ShortName AS ToolName, ISNULL(NULLIF (PT.DisplayName, ''), PT.ShortName) AS ToolDisplayName,
                      PTT.PartnerToolsTriggerID, PTT.Name AS TriggerName, ISNULL(PTT.Description, '') AS TriggerDescription, NULLIF (PTT.URL, '') AS URL
FROM         tblPartnerTools AS PT WITH (NOLOCK) INNER JOIN
                      tblPartnerToolsTriggers AS PTT WITH (NOLOCK) ON PT.PartnerToolID = PTT.PartnerToolID
WHERE
	PTT.TYPE IN ('VALUATION', 'EXCHANGE')
ORDER BY
	PTT.TYPE, ToolDisplayName





