		AND [PDE].[LendersBranchID] IN (0, [Branch].[LendersBranchID])
		AND [PDE].[LenderID] IN (0, [Branch].[LenderID])
		AND	LEN([PDE].[DataValue]) > 0
*/

CREATE VIEW viewPartnerValues_DealerID_2022_11_11 AS
	SELECT --TOP 50
		[PDE].[PartnerToolID],
		[LenderID]					= NULLIF([PDE].[LenderID], 0),
		[LendersBranchID]		= NULLIF([PDE].[LendersBranchID], 0),
		[DealerID]					= [PDE].[DealerID],
		[PDE].[Field],
		[PDE].[DataValue]
	FROM
								[tblPartnerDataElement]					[PDE]						WITH (NOLOCK)
					JOIN	[tblPartnerElementDefinition]		[PED]						WITH (NOLOCK) ON [PED].[PartnerToolID]					= [PDE].[PartnerToolID]			AND [PED].[Field] = [PDE].[Field]
					JOIN	[tblDealers]										[Dealer]				WITH (NOLOCK) ON [Dealer].[DealerID]						= [PDE].[DealerID]
	WHERE
		[PDE].[Active] = 1 AND [PED].[Active] = 1 AND [PDE].[LoanAppID] = 0 AND [PDE].[LoanApp_BidID] = 0 AND [PDE].[DealerID] > 0 AND	LEN([PDE].[DataValue]) > 0

