/****** Object:  View dbo.viewPartnerValues_Inner_2022_11_11    Script Date: 7/31/2024 12:57:19 PM ******/


CREATE VIEW [viewPartnerValues_Inner_2022_11_11] AS
SELECT
		[PDE].[PartnerToolID],
		[PDE].[Field],
		[Bid].[LoanAppID],
		[Bid].[LoanApp_BidID],
		[Score] = CASE WHEN [PDE].[LoanApp_BidID] > 0 THEN 500 ELSE 0 END + CASE WHEN [PDE].[LoanAppID] > 0 THEN 400 ELSE 0 END + CASE WHEN [PDE].[LendersBranchID] > 0 THEN 300 ELSE 0 END + CASE WHEN [PDE].[LenderID] > 0 THEN 200 ELSE 0 END + CASE WHEN [PDE].[DealerID] > 0 THEN 100 ELSE 0 END,
		[PDE].[DataValue]
FROM
				[tblLoanApp_Bids]					[Bid]			WITH (NOLOCK)
	JOIN	[tblLendersBranches]			[Branch]	WITH (NOLOCK) ON [Branch].[LendersBranchID]				= [Bid].[LendersBranchID]
	JOIN	[tblLoanApps]							[App]			WITH (NOLOCK) ON [App].[LoanAppID]								= [App].[LoanAppID]
	JOIN	[tblDealers]							[Dealer]	WITH (NOLOCK) ON [Dealer].[DealerID]							= [App].[DealerID]
	JOIN	[tblPartnerDataElement]		[PDE]			WITH (NOLOCK) ON [PDE].[LoanAppID]								= [Bid].[LoanAppID]
WHERE
	[PDE].[LoanApp_BidID] IN (0, [Bid].[LoanApp_BidID]) AND [PDE].[LenderID] IN (0, [Branch].[LenderID]) AND [PDE].[LendersBranchID] IN (0, [Branch].[LendersBranchID]) AND [PDE].[DealerID] IN (0, [Dealer].[DealerID]) AND LEN([PDE].[DataValue]) > 0
UNION ALL
SELECT
		[PDE].[PartnerToolID],
		[PDE].[Field],
		[Bid].[LoanAppID],
		[Bid].[LoanApp_BidID],
		[Score] = CASE WHEN [PDE].[LoanApp_BidID] > 0 THEN 500 ELSE 0 END + CASE WHEN [PDE].[LoanAppID] > 0 THEN 400 ELSE 0 END + CASE WHEN [PDE].[LendersBranchID] > 0 THEN 300 ELSE 0 END + CASE WHEN [PDE].[LenderID] > 0 THEN 200 ELSE 0 END + CASE WHEN [PDE].[DealerID] > 0 THEN 100 ELSE 0 END,
		[PDE].[DataValue]
FROM
				[tblLoanApp_Bids]					[Bid]			WITH (NOLOCK)
	JOIN	[tblLendersBranches]			[Branch]	WITH (NOLOCK) ON [Branch].[LendersBranchID]				= [Bid].[LendersBranchID]
	JOIN	[tblLoanApps]							[App]			WITH (NOLOCK) ON [App].[LoanAppID]								= [App].[LoanAppID]
	JOIN	[tblDealers]							[Dealer]	WITH (NOLOCK) ON [Dealer].[DealerID]							= [App].[DealerID]
	JOIN	[tblPartnerDataElement]		[PDE]			WITH (NOLOCK) ON [PDE].[LoanApp_BidID]						= [Bid].[LoanApp_BidID]
WHERE
	[PDE].[LoanAppID] IN (0, [Bid].[LoanAppID]) AND [PDE].[LenderID] IN (0, [Branch].[LenderID]) AND [PDE].[LendersBranchID] IN (0, [Branch].[LendersBranchID]) AND [PDE].[DealerID] IN (0, [Dealer].[DealerID]) AND LEN([PDE].[DataValue]) > 0
UNION ALL
SELECT
		[PDE].[PartnerToolID],
		[PDE].[Field],
		[Bid].[LoanAppID],
		[Bid].[LoanApp_BidID],
		[Score] = CASE WHEN [PDE].[LoanApp_BidID] > 0 THEN 500 ELSE 0 END + CASE WHEN [PDE].[LoanAppID] > 0 THEN 400 ELSE 0 END + CASE WHEN [PDE].[LendersBranchID] > 0 THEN 300 ELSE 0 END + CASE WHEN [PDE].[LenderID] > 0 THEN 200 ELSE 0 END + CASE WHEN [PDE].[DealerID] > 0 THEN 100 ELSE 0 END,
		[PDE].[DataValue]
FROM
				[tblLoanApp_Bids]					[Bid]			WITH (NOLOCK)
	JOIN	[tblLendersBranches]			[Branch]	WITH (NOLOCK) ON [Branch].[LendersBranchID]				= [Bid].[LendersBranchID]
	JOIN	[tblLoanApps]							[App]			WITH (NOLOCK) ON [App].[LoanAppID]								= [App].[LoanAppID]
	JOIN	[tblDealers]							[Dealer]	WITH (NOLOCK) ON [Dealer].[DealerID]							= [App].[DealerID]
	JOIN	[tblPartnerDataElement]		[PDE]			WITH (NOLOCK) ON [PDE].[LenderID]									= [Branch].[LenderID]
WHERE
	[PDE].[LoanAppID] IN (0, [Bid].[LoanAppID]) AND [PDE].[LoanApp_BidID] IN (0, [Bid].[LoanApp_BidID]) AND [PDE].[LenderID] IN (0, [Branch].[LenderID]) AND [PDE].[LendersBranchID] IN (0, [Branch].[LendersBranchID]) AND [PDE].[DealerID] IN (0, [Dealer].[DealerID]) AND LEN([PDE].[DataValue]) > 0




