/****** Object:  View dbo.viewPartnerValues_LenderID_2022_11_11    Script Date: 7/31/2024 12:57:19 PM ******/

CREATE VIEW viewPartnerValues_LenderID_2022_11_11 AS
	SELECT --TOP 50
		[PDE].[PartnerToolID],
		[Branch].[LenderID],
		[Branch].[LendersBranchID],
		[DealerID]		= NULLIF([PDE].[DealerID], 0),
		[PDE].[Field],
		[PDE].[DataValue]
	FROM
								[tblPartnerDataElement]					[PDE]						WITH (NOLOCK)
					JOIN	[tblPartnerElementDefinition]		[PED]						WITH (NOLOCK) ON [PED].[PartnerToolID]					= [PDE].[PartnerToolID]			AND [PED].[Field] = [PDE].[Field]
					JOIN	[tblLendersBranches]						[Branch]				WITH (NOLOCK) ON [Branch].[LenderID]						= [PDE].[LenderID]					OR 	[Branch].[LendersBranchID] = [PDE].[LendersBranchID]
	WHERE
		[PDE].[Active] = 1 AND [PED].[Active] = 1
		AND [PDE].[LoanAppID] = 0 AND [PDE].[LoanApp_BidID] = 0
		AND ([PDE].[LenderID] > 0 OR [PDE].[LendersBranchID] > 0)
		AND [PDE].[LendersBranchID] IN (0, [Branch].[LendersBranchID])
		AND [PDE].[LenderID] IN (0, [Branch].[LenderID])
		AND	LEN([PDE].[DataValue]) > 0

