/****** Object:  View dbo.viewPartners_Innovate_Activation    Script Date: 7/31/2024 12:57:19 PM ******/
CREATE VIEW viewPartners_Innovate_Activation AS
	SELECT
		[PartnerToolID]		= [Partner].[PartnerToolID],
		[Partner]			= [Partner].[ShortName],
		[LenderID]			= [Branch].[LenderID],
		[LendersBranchID]	= [Branch].[LendersBranchID]
	FROM
				[tblLendersBranches]		[Branch]		WITH (NOLOCK)
		JOIN	[tblLenders]				[Lender]		WITH (NOLOCK) ON	[Branch].[LenderID]         = [Lender].[LenderID]
		JOIN	[tblPartnerTools]			[Partner]		WITH (NOLOCK) ON    [Partner].[ShortName]		= 'INNOVATE'
		JOIN	[tblPartnerDataElement]		[PDE_Enable]	WITH (NOLOCK) ON		
					[PDE_Enable].[PartnerToolID]	= [Partner].[PartnerToolID]			AND
					[PDE_Enable].[DealerID]			= 0									AND
					[PDE_Enable].[LenderID]			= 0									AND
					[PDE_Enable].[LendersBranchID]	= [Branch].[LendersBranchID]		AND
					[PDE_Enable].[LoanAppID]		= 0									AND
					[PDE_Enable].[LoanApp_BidID]	= 0									AND
					[PDE_Enable].[Field]			= 'Lender Enabled (CreditSmarts)'	AND
					[PDE_Enable].[DataValue]		= 'TRUE'
		JOIN	[tblPartnerDataElement]		[PDE_Vendor]	WITH (NOLOCK) ON
					[PDE_Vendor].[PartnerToolID]	= [Partner].[PartnerToolID]			AND
					[PDE_Vendor].[DealerID]			= 0									AND
					[PDE_Vendor].[LenderID] 		= 0									AND
					[PDE_Vendor].[LendersBranchID]	= [Branch].[LendersBranchID]		AND
					[PDE_Vendor].[LoanAppID]		= 0									AND
					[PDE_Vendor].[LoanApp_BidID]	= 0									AND
					[PDE_Vendor].[Field]			= 'Vendor.ID'						AND
					LEN([PDE_Vendor].[DataValue])	> 0
	GROUP BY
		[Partner].[PartnerToolID],
		[Partner].[ShortName],
		[Branch].[LenderID],
		[Branch].[LendersBranchID]


