/****** Object:  View dbo.viewReportingLenderInvoicing    Script Date: 7/31/2024 12:57:19 PM ******/

CREATE VIEW viewReportingLenderInvoicing AS
	SELECT --TOP 100 PERCENT
		LoanAppID				= BID.LoanAppID,
		LenderID				= LENDER.LenderID,
		LenderName				= LEFT(LENDER.LenderName,			64),
		LenderAddress			= LEFT(LENDER.Address,				50),
		LenderCity				= LEFT(LENDER.City,					30),
		LenderState				= LEFT(LENDER.State,				2),
		LenderZIP				= RIGHT('00000' + LENDER.ZIP,		5),
		DealerName				= LEFT(DEALER.DealerName,			64),
		Applicant_Names			= LEFT(APPLICATION.APPLICANT_NAMES,	64),
		BidCreateDateTime		= BID.CreateDateTime,
		BidUpdateDateTime		= BID.UpdateDateTime,
		BidSubmitDateTime		= CASE WHEN BID.SUBMIT_DATE IS NOT NULL THEN BID.SUBMIT_DATE ELSE BID.CreateDateTime END,
		Fee_Method				= LEFT(LENDER.FEE_METHOD,			20),
		Fee_Per_Unit			= LENDER.FEE_PER_UNIT,
		Financing_Amount		= BID.FINANCING_AMOUNT,
		Funded					= CONVERT(BIT, CASE WHEN BID.FUNDED = 1 THEN 1 WHEN BID.FUNDED_DATE IS NOT NULL THEN 1 ELSE 0 END),
		Date_Funded				= BID.FUNDED_DATE,
		Funded_Date				= BID.FUNDED_DATE,
		Status					= BID.Status
	FROM
				tblLoanApp_Bids			BID				WITH (NOLOCK)
		JOIN	tblLoanApps				APPLICATION		WITH (NOLOCK) ON APPLICATION.LoanAppID		= BID.LoanAppID
		JOIN	tblLendersBranches		BRANCH			WITH (NOLOCK) ON BRANCH.LendersBranchID		= BID.LendersBranchID
		JOIN	tblLenders				LENDER			WITH (NOLOCK) ON LENDER.LenderID			= BRANCH.LenderID
		JOIN	tblDealers				DEALER			WITH (NOLOCK) ON DEALER.DealerID			= APPLICATION.DealerID

/*
	ORDER BY 
		LENDER.LenderID,
		BID.SUBMIT_DATE,
		BID.LoanAppID
*/



