/****** Object:  View dbo.viewReporting_BidDisposition    Script Date: 7/31/2024 12:57:19 PM ******/


CREATE VIEW viewReporting_BidDisposition AS

SELECT
	B1.LoanAppID,
	B1.LoanApp_BidID,
	CONVERT(int, A.DealerID) DealerID,
	LenderID = (SELECT LenderID from tblLendersBranches LB WHERE LB.LendersBranchID = B1.LendersBranchID),
	B1.LendersBranchID,	

	EFFECTIVE_DATE =	CASE
		WHEN (SELECT COUNT(*) FROM tblLoanApp_Bids B2 WHERE B2.LendersBranchID=B1.LendersBranchID AND B1.LoanAppID=B2.LoanAppID AND FUNDED_DATE IS NOT NULL) > 0 THEN (SELECT MAX(FUNDED_DATE) FROM tblLoanApp_Bids B2 WHERE B2.LendersBranchID=B1.LendersBranchID AND B1.LoanAppID=B2.LoanAppID)
		WHEN OFFER_DATE IS NOT NULL THEN OFFER_DATE
		WHEN SUBMIT_DATE IS NOT NULL THEN SUBMIT_DATE
		ELSE B1.UPDATEDATETIME
		END,

	Funded = CASE (SELECT COUNT(*) FROM tblLoanApp_Bids B2 WHERE B2.LendersBranchID=B1.LendersBranchID AND B1.LoanAppID=B2.LoanAppID AND FUNDED_DATE IS NOT NULL)
		WHEN 0 THEN CONVERT(bit, 0)
		ELSE CONVERT(bit, 1)
	END,

	Automated = CASE UPPER(LEFT(Offered_By, 11))
		WHEN 'AUTOMATION@' THEN CONVERT(bit, 1)
		ELSE CONVERT(bit, 0)
	END,

	Approved = CASE (SELECT COUNT(*) FROM tblLoanApp_Bids B2 WHERE B2.LendersBranchID=B1.LendersBranchID AND B1.LoanAppID=B2.LoanAppID AND STATUS IN('PENDING_DEALER', 'DECLINE_DEALER', 'ACCEPTED'))
		WHEN 0 THEN CONVERT(bit, 0)
		ELSE CONVERT(bit, 1)
	END,

	Accepted =
		CASE (SELECT COUNT(*) FROM tblLoanApp_Bids B2 WHERE B2.LendersBranchID=B1.LendersBranchID AND B1.LoanAppID=B2.LoanAppID AND STATUS='ACCEPTED')
		WHEN 0 THEN CONVERT(bit, 0)
		ELSE CONVERT(bit, 1)
	END,

	Score_1 = B1.Primary_Score,

	Score_2 = B1.Secondary_Score,

	Score_Hi = CASE
		WHEN Secondary_Score > Primary_Score THEN Secondary_Score
		ELSE Primary_Score
	END,	

	Tier = CASE
		WHEN Secondary_Score > Primary_Score AND Secondary_Score >= 700 THEN 'A'
		WHEN Secondary_Score > Primary_Score AND Secondary_Score >= 680 THEN 'B'
		WHEN Secondary_Score > Primary_Score AND Secondary_Score >= 660 THEN 'C'
		WHEN Secondary_Score > Primary_Score AND Secondary_Score >= 640 THEN 'D'
		WHEN Secondary_Score > Primary_Score AND Secondary_Score >= 600 THEN 'E'
		WHEN Secondary_Score > Primary_Score AND Secondary_Score >= 300 THEN 'F'
		WHEN Primary_Score >= 700 THEN 'A'
		WHEN Primary_Score >= 680 THEN 'B'
		WHEN Primary_Score >= 660 THEN 'C'
		WHEN Primary_Score >= 640 THEN 'D'
		WHEN Primary_Score >= 600 THEN 'E'
		WHEN Primary_Score >= 300 THEN 'F'
		WHEN Secondary_Score = 0 OR Primary_Score = 0		THEN 'Z'
	END,

	Amount_Offered = B1.Financing_Amount

FROM
	tblLoanApp_Bids B1,
	tblLoanApps	A

WHERE	
	A.LoanAppID = B1.LoanAppID
	AND		B1.LoanApp_BidID = (SELECT MIN(LoanApp_BidID) FROM tblLoanApp_Bids B2 WHERE B2.LendersBranchID=B1.LendersBranchID AND B1.LoanAppID=B2.LoanAppID)

--	and A.DealerID=1 and lendersbranchid=223





