/****** Object:  View dbo.viewTblPartnerToolsChannels    Script Date: 7/31/2024 12:57:19 PM ******/


CREATE VIEW viewTblPartnerToolsChannels AS

SELECT
	TOP 100 PERCENT

    PartnerToolID,
    ShortName,
    DisplayName                    =  ISNULL(NULLIF(PT.DisplayName, ''), ShortName),
    Active                         =  ISNULL(PT.Active,                       0),
    Dealer                         =  ISNULL(PT.Dealer,                       0),
    Lender                         =  ISNULL(PT.Lender,                       0),
    LenderBranch                   =  ISNULL(PT.LenderBranch,                 0),
    Logo                           =  ISNULL(PT.Logo,                         ''),
    Tooltip                        =  ISNULL(PT.Tooltip,                      ''),
    InformationURL                 =  ISNULL(PT.InformationURL,               ''),
    SignUpURL                      =  ISNULL(PT.SignUpURL,                    ''),
    LoginURL                       =  ISNULL(PT.LoginURL,                     ''),
    Notes                          =  ISNULL(PT.Notes,                        ''),

    IndDealerNeedsCS               =  CASE
		WHEN ShortName IN ('CreditSmarts, Internal') THEN 0
		ELSE ISNULL(PT.IndDealerNeedsCS, 1)
	END,

    IndDealerLenderActivation      =  ISNULL(PT.IndDealerLenderActivation,    'LENDER'),
    FranchiseDealer                =  ISNULL(PT.FranchiseDealer,              1),
    FranDealerNeedsCS              =  ISNULL(PT.FranDealerNeedsCS,            0),
    FranDealerLenderActivation     =  ISNULL(PT.FranDealerLenderActivation,   1),
    IsChannel                      =  ISNULL(PT.IsChannel,                    0),
    IsInternal                     =  ISNULL(PT.IsInternal,                   0),
    IsCreditSmarts                 =  ISNULL(PT.IsCreditSmarts,               0),
    TYPE,

    CreateDateTime                 =  ISNULL(PT.CreateDateTime,               PT.UpdateDateTime),
    UpdateDateTime                 =  ISNULL(PT.UpdateDateTime,               PT.UpdateDateTime),
    CreateUser                     =  ISNULL(PT.CreateUser,                   PT.CreateUser),
    UpdateUser                     =  ISNULL(PT.UpdateUser,                   PT.UpdateUser),

    rowVersion                     =  ISNULL(PT.rowVersion,                   0)

FROM
	tblPartnerTools PT WITH (NOLOCK)
WHERE
	IsChannel = 1
	OR	
	ShortName IN ('LES')
ORDER BY
	IsInternal DESC,
	IsCreditSmarts DESC,

	DisplayName,
	ShortName





