/****** Object:  View dbo.viewTimeZones    Script Date: 7/31/2024 12:57:19 PM ******/


CREATE VIEW viewTimeZones AS

SELECT
	Z.ZipCode,
	City = C.City,
	State = S.StateCode,
	County = CT.County,
	Z.CountyFIPS,
	Z.Latitude,
	Z.Longitude,
	MSA = C.MSA,
	C.GMTOffset,
	C.DST,
	TimeZone = CASE C.GMTOffset
		WHEN -8 THEN	'Pacific'
		WHEN -7 THEN	'Mountain'
		WhEN -6 THEN	'Central'
		WHEN -5 THEN	'Eastern'
		ELSE 'Unknown'
	END
FROM
				tblZips		Z	WITH (NOLOCK)	
	INNER JOIN	tblCities	C	WITH (NOLOCK)		ON (Z.CityID = C.CityID)
	INNER JOIN	tblStates	S	WITH (NOLOCK)		ON (Z.StateFIPS = S.StateFIPS)
	INNER JOIN	tblCounties CT	WITH (NOLOCK)		ON (Z.CountyFIPS = CT.CountyFIPS)
WHERE
	Z.ZIPCodeType = 'S'







