	LEFT JOIN tblPartnerDataElement 	pde WITH (NOLOCK) ON (pde.LoanApp_BidID = BID.LoanApp_BidID AND pde.PartnerToolID = GTS.PartnerToolID AND pde.Field = 'LastSendDate')
