/****** Object:  View dbo.view_B2B_BranchesActiveForPartnerTool    Script Date: 7/31/2024 12:57:19 PM ******/

create VIEW [dbo].[view_B2B_BranchesActiveForPartnerTool] AS
	SELECT
		PartnerToolID	= Partner.PartnerToolID,
		PartnerCode		= Partner.ShortName,
		Partner			= Partner.DisplayName,
		LenderID		= Lender.LenderID,
		LendersBranchID	= Branch.LendersBranchID,
		BranchName		= UPPER(Branch.BranchName),
		AuthorizedByCS	= CONVERT(BIT, CASE WHEN PDE.DataValue IS NOT NULL AND PDE.DataValue = 'TRUE' THEN 1 ELSE 0 END)
	FROM
					tblPartnerTools			Partner		WITH (NOLOCK)
		LEFT JOIN	tblLenders				Lender		WITH (NOLOCK) ON Lender.LenderStatus NOT IN('INACTIVE', 'FAX')
		LEFT JOIN	tblLendersBranches		Branch		WITH (NOLOCK) ON Branch.LenderID=Lender.LenderID
		LEFT JOIN	tblPartnerDataElement	PDE			WITH (NOLOCK) ON 	PDE.PartnerToolID	= Partner.PartnerToolID
																		AND PDE.LendersBranchID		= Branch.LendersBranchID
																		AND PDE.Field			= 'Lender Enabled (CreditSmarts)'
																		AND PDE.Active			= 1
	WHERE
			Partner.Active = 1
		AND Partner.IsCreditSmarts = 0

/*
  SELECT TOP 100 PERCENT * FROM
	(SELECT DISTINCT TOP 100 PERCENT
	Partner.PartnerToolID,
	PartnerCode = Partner.ShortName,
	Partner = Partner.DisplayName,
	Lender.LenderID,
	LenderName = UPPER(Lender.LenderName),
	AuthorizedByCS = CASE
		WHEN EXISTS(SELECT * FROM  tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LenderID = Lender.LenderID AND Field='Lender Enabled (CreditSmarts)' AND DataValue='TRUE')
		THEN CONVERT(BIT, 1)
		ELSE CONVERT(BIT, 0)
	END
	FROM
	tblLenders Lender WITH (NOLOCK),
	tblPartnerTools Partner WITH (NOLOCK)
	) TABLE_X

	WHERE LenderID = 278

  ORDER BY
	PartnerToolID,
	AuthorizedByCS DESC,
	LenderName
*/




