		DealerName		= UPPER(Dealer.DealerName),
		AuthorizedByCS	= CONVERT(BIT, CASE WHEN PDE.DataValue IS NOT NULL AND PDE.DataValue = 'TRUE' THEN 1 ELSE 0 END)
	FROM
		tblPartnerTools			Partner		WITH (NOLOCK)
		LEFT JOIN	tblDealers				Dealer		WITH (NOLOCK) ON Dealer.DealerStatus NOT IN('INACTIVE')
		LEFT JOIN	tblPartnerDataElement	PDE			WITH (NOLOCK) ON 	
		PDE.PartnerToolID	= Partner.PartnerToolID
		AND PDE.DealerID		= Dealer.DealerID
		AND PDE.Field			= 'Dealer Activation' /*correct field name */
		--AND PDE.Field			= 'Dealer Enabled (CreditSmarts)' /* incorrect field name */				 
		AND PDE.Active			= 1
	WHERE
			Partner.Active = 1
		AND Partner.IsCreditSmarts = 0
  ORDER BY
	PartnerToolID,
	AuthorizedByCS DESC,
	DealerName

/*
  SELECT TOP 100 PERCENT * FROM
	(SELECT DISTINCT TOP 100 PERCENT
	Partner.PartnerToolID,
	PartnerCode = Partner.ShortName,
	Partner = Partner.DisplayName,
	Lender.LenderID,
	LenderName = UPPER(Lender.LenderName),
	AuthorizedByCS = CASE
		WHEN EXISTS(SELECT * FROM  tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LenderID = Lender.LenderID AND Field='Lender Enabled (CreditSmarts)' AND DataValue='TRUE')
		THEN CONVERT(BIT, 1)
		ELSE CONVERT(BIT, 0)
	END
	FROM
	tblLenders Lender WITH (NOLOCK),
	tblPartnerTools Partner WITH (NOLOCK)
	) TABLE_X

	WHERE LenderID = 278

  ORDER BY
	PartnerToolID,
	AuthorizedByCS DESC,
	LenderName
*/





