/****** Object:  View dbo.view_B2B_Exchange_Bids    Script Date: 7/31/2024 12:57:19 PM ******/

CREATE VIEW view_B2B_Exchange_Bids AS
	SELECT DISTINCT
		LoanAppID					= Bid.LoanAppID,
		LoanApp_BidID				= Bid.LoanApp_BidID,
		LenderID					= Bid.LenderID,
		DealerID					= Bid.DealerID,
		LendersBranchID				= Bid2.LendersBranchID,
		PartnerToolID				= PartnerTool.PartnerToolID,
		Partner						= PartnerTool.ShortName,
		PartnerName					= PartnerTool.DisplayName,
		PartnerIsChannel			= ISNULL(PartnerTool.IsChannel,			0),
		PartnerIsInternal			= ISNULL(PartnerTool.IsInternal,		0),
		PartnerIsCreditSmarts		= ISNULL(PartnerTool.IsCreditSmarts,	0),
		PartnerType					= ISNULL(PartnerTool.Type,				0)
	FROM
					viewBids_Funded								Bid
			JOIN	view_B2B_LendersActiveForPartnerTool		R					WITH (NOLOCK) ON	Bid.LenderID					= R.LenderID				AND R.AuthorizedByCS		= 1
			JOIN	tblPartnerToolsTriggers						PTT					WITH (NOLOCK) ON	PTT.PartnerToolID				= R.PartnerToolID			AND PTT.TYPE				= 'EXCHANGE'
			JOIN	tblPartnerTools								PartnerTool			WITH (NOLOCK) ON	PartnerTool.PartnerToolID		= PTT.PartnerToolID
			JOIN	tblPartnerDataElement						PDE					WITH (NOLOCK) ON	PDE.LoanApp_BidID				= Bid.LoanApp_BidID
			JOIN	tblLoanApp_Bids								Bid2				WITH (NOLOCK) ON	Bid2.LoanApp_BidID				= Bid.LoanApp_BidID
	
	
	--	JOIN	tblPartnerDataElement		Last_Sent	WITH (NOLOCK)		ON Last_Sent.LoanApp_BidID = Bid.LoanApp_BidID 
	--AND Last_Sent.Field = 'LastSentDateTime'
	--AND Last_Sent.Field = 'LastSentDateTime'
	WHERE
			PartnerTool.Active = 1
			AND Bid.Funded_Date > '2014-01-01'
		--AND Last_Sent.Field = 'LastSentDateTime'



