/****** Object:  View dbo.view_Bids    Script Date: 7/31/2024 12:57:19 PM ******/

CREATE VIEW view_Bids AS

SELECT TOP 100 PERCENT
	PartnerToolID		= PARTNER_TOOL.PartnerToolID,
	PartnerCode			= PARTNER_TOOL.ShortName,
	LoanAppID			= BIDS.LoanAppID,
	LoanApp_BidID		= BIDS.LoanApp_BidID,
	Dealer.DealerID,
	Dealer				= UPPER(Dealer.DealerName),
	DealerLocation		= UPPER(Dealer.City) + ', ' + UPPER(Dealer.State),
	Applicants			= UPPER(APP.Applicant_Names),
--	DealerID			= DEALER.DealerID,
--	Dealer				= UPPER(DEALER.DealerName),				
	Field				= ELEMENT.Field,
	DataValue			= ELEMENT.DataValue,
	LendersBranchID		= (SELECT LendersBranchID FROM tblLoanApp_Bids WITH (NOLOCK) WHERE LoanApp_BidID = BIDS.LoanApp_BidID),
	URL					= TRIGGER_SEND.URL,
/*
	URL					= CASE
		WHEN Bids.LoanAppID = 978953 THEN 'https://messaging.itl.routeone.net/IF1_ITL/CASSBMessagingReceiver'
		ELSE TRIGGER_SEND.URL
	END,
*/

--TRIGGER_SEND.URL,
	UserName			= TRIGGER_SEND.Username,
	Password			= TRIGGER_SEND.Password,
	XML					= TRIGGER_SEND.XML,
	LastSentDateTime	= DBO.StripToDate((SELECT MAX(DataValue) FROM tblPartnerDataElement  WITH (NOLOCK)  WHERE LoanApp_BidID=BIDS.LoanApp_BidID AND Field='LastSentDateTime')),
	LastUpdateDateTime	= DBO.StripToDate(BIDS.UpdateDateTime),
	BidStatus			= BIDS.Status

FROM
    		tblLoanApp_Bids					BIDS			WITH (NOLOCK)
	JOIN	tblLoanApps						APP					WITH (NOLOCK)		ON APP.LoanAppID = BIDS.LoanAppID
	JOIN	tblDealers						DEALER				WITH (NOLOCK)		ON APP.DealerID = DEALER.DealerID

    LEFT OUTER JOIN	tblPartnerDataElement			ELEMENT			WITH (NOLOCK) ON (BIDS.LoanApp_BidID = ELEMENT.LoanApp_BidID )
    LEFT OUTER JOIN	tblPartnerToolsTriggers			TRIGGER_SEND	WITH (NOLOCK) ON (TRIGGER_SEND.PartnerToolID=12 AND TRIGGER_SEND.TYPE='SEND_DECISION')
	LEFT OUTER JOIN	tblPartnerTools 				PARTNER_TOOL	WITH (NOLOCK) ON (PARTNER_TOOL.PartnerToolID = 12)
	LEFT OUTER JOIN	tblLendersBranches				BRANCH			WITH (NOLOCK) ON (BRANCH.LendersBranchID = BIDS.LendersBranchID)
	LEFT OUTER JOIN	tblLenders 						LENDER			WITH (NOLOCK) ON LENDER.LenderID = Branch.LenderID
WHERE
	ELEMENT.Field =  'Application.ID'

--		(SELECT TOP 1 Field FROM tblPartnerElementDefinition DEFINITION  WITH (NOLOCK)  WHERE (DEFINITION.PartnerToolID=ELEMENT.PartnerToolID AND DEFINITION.ValueType='PARTNER_LOAN_ID'))

    AND		DBO.StripToDate(ISNULL((SELECT TOP 1 DataValue FROM tblPartnerDataElement  WITH (NOLOCK)  WHERE (LoanApp_BidID=BIDS.LoanApp_BidID )
	AND		Field='LastSentDateTime'), '1/1/2009')) < DBO.StripToDate(BIDS.UpdateDateTime)


--    AND		BIDS.Status IN ('DECLINE_LENDER')    AND		BIDS.Status IN ('PENDING_DEALER')
    AND		BIDS.Status IN ('DECLINE_LENDER', 'PENDING_DEALER')
    AND		DATEDIFF(dd, BIDS.UpdateDateTime, GETDATE()) <= 14
--	AND		LENDER.LenderID IN (SELECT LenderID FROM tblPartnerDataElement WITH (NOLOCK))
	AND		PARTNER_TOOL.PartnerToolID IN(12)
--	AND		BIDS.LoanApp_BidID IN(418019)

ORDER BY
    BIDS.UpdateDateTime DESC



GO

