CREATE VIEW view_Bids_Inner_Applicant_Stats AS
	SELECT
		LoanAppID					= App.LoanAppID,
		Applicants					= COUNT(DISTINCT Applicant.LoanApp_ApplicantID),
		PrimaryApplicantID			= MIN(Applicant.LoanApp_ApplicantID),
