/****** Object:  View dbo.view_LenderLoginLookup    Script Date: 7/31/2024 12:57:19 PM ******/


CREATE VIEW [dbo].[view_LenderLoginLookup] AS
	SELECT
		LenderID					= Lender.LenderID,
		LendersBranchID				= NULL,
		LoginPrefix					= LOWER(Lender.LoginPrefix),
		LenderName					= DBO.ProperCase(Lender.LenderName),
		BranchName					= 'Corporate',
	--	Address						= ISNULL(ISNULL(NULLIF(Branch.Address, ''), Lender.Address), ''),
		City						= DBO.ProperCase(ISNULL(Lender.City, '')),
		State						= UPPER(ISNULL(Lender.State, '')),
		ZIP							= ISNULL(Lender.Zip, ''),
		Phone						= ISNULL(Lender.Phone, ''),
		Fax							= ISNULL(Lender.Fax, ''),
		LoginCellPhone				= ISNULL(Users.CellPhone, ''),
		LoginOfficePhone			= ISNULL(Users.OfficePhone, ''),
		LendersLoginID				= Users.LendersLoginID,
		LendersBranchLoginID		= NULL,
		UserName					= LOWER(Lender.LoginPrefix + '\' + Users.UserName),
		AltUserName					= LOWER(Users.UserName + '@' + Lender.LoginPrefix),
		Name						=	CASE	WHEN LEN(LTRIM(ISNULL(FullName, ''))) > 0	THEN	DBO.ProperCase(FullName)
												ELSE LOWER(UserName) END,
	
		Description					= ISNULL(Users.Description, ''),
		Status						= ISNULL(Users.Status, ''),
		Employee_Number				= ISNULL(Users.Employee_Number, ''),
		EMail						= LOWER(ISNULL(Users.EMail, ''))
	FROM
				tblLenders				Lender		WITH (NOLOCK)
		JOIN	tblLendersLogins		Users		WITH (NOLOCK)	ON Users.LenderID = Lender.LenderID

	UNION
	
	SELECT
		LenderID					= Lender.LenderID,
		LendersBranchID				= Branch.LendersBranchID,
		LoginPrefix					= LOWER(Branch.LoginPrefix),
		LenderName					= DBO.ProperCase(Lender.LenderName),
		BranchName					= DBO.ProperCase(Branch.BranchName),
	--	Address						= ISNULL(ISNULL(NULLIF(Branch.Address, ''), Lender.Address), ''),
		City						= DBO.ProperCase(ISNULL(ISNULL(NULLIF(Branch.City, ''), Lender.City), '')),
		State						= UPPER(ISNULL(ISNULL(NULLIF(Branch.State, ''), Lender.State), '')),
		ZIP							= ISNULL(ISNULL(NULLIF(Branch.Zip, ''), Lender.Zip), ''),
		Phone						= ISNULL(NULLIF(Branch.Phone, ''), Lender.Phone),
		Fax							= ISNULL(NULLIF(Branch.Fax, ''), Lender.Fax),
		LoginCellPhone				= ISNULL(Users.CellPhone, ''),
		LoginOfficePhone			= ISNULL(Users.OfficePhone, ''),
		LendersLoginID				= NULL,
		LendersBranchLoginID		= Users.LendersBranchLoginID,
		UserName					= LOWER(Branch.LoginPrefix + '\' + Users.UserName),
		AltUserName					= LOWER(Users.UserName + '@' + Branch.LoginPrefix),
		Name						=	CASE	WHEN LEN(LTRIM(ISNULL(FullName, ''))) > 0	THEN	DBO.ProperCase(FullName)
												ELSE LOWER(UserName) END,
	
	
		Description					= ISNULL(Users.Description, ''),
		Status						= ISNULL(Users.Status, ''),
		Employee_Number				= ISNULL(Users.Employee_Number, ''),
		EMail						= LOWER(ISNULL(Users.EMail, ''))
	FROM
				tblLendersBranches			Branch		WITH (NOLOCK)
		JOIN	tblLenders					Lender		WITH (NOLOCK)	ON Lender.LenderID			= Branch.LenderID
		JOIN	tblLendersBranchLogins		Users		WITH (NOLOCK)	ON Users.LendersBranchID	= Branch.LendersBranchID





