/****** Object:  View dbo.view_Lenders_New    Script Date: 7/31/2024 12:57:19 PM ******/


CREATE VIEW dbo.view_Lenders_New AS

SELECT TOP 100 PERCENT
  L.*,
  BranchCount = (SELECT COUNT(*) FROM tblLendersBranches B WITH (NOLOCK) WHERE B.LenderID = L.LenderID),
  L.City + ', ' + L.State AS Location
FROM
  tblLenders L WITH (NOLOCK)
ORDER BY
  L.LenderName





