/****** Object:  View dbo.view_LoanAppApplicantsForCarleton    Script Date: 7/31/2024 12:57:19 PM ******/








CREATE  VIEW [dbo].[view_LoanAppApplicantsForCarleton] AS

SELECT
	a.LoanAppID,
	right('0000'+ rtrim(CAST(ISNULL(SSN_1,'') as VARCHAR(3))), 3) + '-' + right('0000'+ rtrim(CAST(ISNULL(SSN_2,'') as VARCHAR(2))), 2) + '-' + right('0000'+ rtrim(CAST(ISNULL(SSN_3,'') as VARCHAR(4))), 4) as SSN,
	CAST(ISNULL(SSN_1,'') as VARCHAR(3)) + '-' + CAST(ISNULL(SSN_2,'') as VARCHAR(2)) + '-' + CAST(ISNULL(SSN_3,'') as VARCHAR(4)) as SSN1,
	ISNULL(FIRST_NAME,'') as FIRST_NAME,
	ISNULL(LAST_NAME,'') as LAST_NAME,
	ISNULL(MIDDLE_INITIAL,'') as MIDDLE_INITIAL,
	CASE WHEN DOB_MONTH IS NOT NULL AND DOB_MONTH > 0 AND
		DOB_DAY IS NOT NULL AND DOB_DAY > 0 AND
		DOB_YEAR IS NOT NULL AND DOB_YEAR > 0 THEN
			CAST(DOB_MONTH as VARCHAR(2)) + '/' + CAST(DOB_DAY as VARCHAR(2)) + '/' + CAST(DOB_YEAR as VARCHAR(4))
		ELSE ''
	END as DOB,
	CASE WHEN HOME_PHONE_AREA_CODE IS NOT NULL AND HOME_PHONE_AREA_CODE > 0 AND
		HOME_PHONE_PREFIX IS NOT NULL AND HOME_PHONE_PREFIX > 0 AND
		HOME_PHONE_NUMBER IS NOT NULL AND HOME_PHONE_NUMBER > 0 THEN
--			'(' + CAST(HOME_PHONE_AREA_CODE as VARCHAR(3)) + ') ' + CAST(HOME_PHONE_PREFIX as VARCHAR(3)) + '-' + CAST(HOME_PHONE_NUMBER as VARCHAR(4))
			'(' + right('0000'+ rtrim(CAST(ISNULL(HOME_PHONE_AREA_CODE,'') as VARCHAR(3))), 3) + ') ' + right('0000'+ rtrim(CAST(ISNULL(HOME_PHONE_PREFIX,'') as VARCHAR(3))), 3) + '-' + right('0000'+ rtrim(CAST(ISNULL(HOME_PHONE_NUMBER,'') as VARCHAR(4))), 4)
		ELSE ''
	END as HPHONE,

	CASE WHEN MOBILE_PHONE_AREA_CODE IS NOT NULL AND MOBILE_PHONE_AREA_CODE > 0 AND
		MOBILE_PHONE_PREFIX IS NOT NULL AND MOBILE_PHONE_PREFIX > 0 AND
		MOBILE_PHONE_NUMBER IS NOT NULL AND MOBILE_PHONE_NUMBER > 0 THEN
--			'(' + CAST(MOBILE_PHONE_AREA_CODE as VARCHAR(3)) + ') ' + CAST(MOBILE_PHONE_PREFIX as VARCHAR(3)) + '-' + CAST(MOBILE_PHONE_NUMBER as VARCHAR(4))
			'(' + right('0000'+ rtrim(CAST(ISNULL(MOBILE_PHONE_AREA_CODE,'') as VARCHAR(3))), 3) + ') ' + right('0000'+ rtrim(CAST(ISNULL(MOBILE_PHONE_PREFIX,'') as VARCHAR(3))), 3) + '-' + right('000'+ rtrim(CAST(ISNULL(MOBILE_PHONE_NUMBER,'') as VARCHAR(4))), 4)
		ELSE ''
	END as MPHONE,
	ISNULL(ca.STREET_1,'') as STREET_1,
	ISNULL(ca.STREET_2,'') as STREET_2,
	ISNULL(ca.CITY,'') as CITY,
	ISNULL(ca.STATE,'') AS STATE,
	RIGHT('000000'+ RTRIM(ISNULL(ca.ZIP,'')), 5) AS ZIP,
	CASE WHEN MILITARY_RANK IS NOT NULL AND Len(MILITARY_RANK) > 0 AND MILITARY_RANK <> 'NONE' THEN 1 ELSE 0 END as IS_MILITARY,
	ISNULL(EMAIL_ADDRESS,'') as EMAIL_ADDRESS,
	ca.YEARS * 12 + ca.MONTHS as ResidenceMonths,
	CASE WHEN HOME_OWNER IS NOT NULL AND HOME_OWNER > 0 THEN 'Owner' ELSE 'Rent' END as HomeOwner,
	--a.HOUSING_PAYMENT as RentAmt,
	OTHER_TYPE as OtherIncomeDesc,
	OTHER_MONTHLY as OtherIncomeAmt,
	GROSS_MONTHLY as EmploymentIncomeMonthly,
	RELATIONSHIP_TO_PRIMARY as RelationToBorrower,
	ce.COMPANY as CurrentEmployer,
	ce.POSITION as Position,
	ce.ADDRESS_STREET_1 as EmployerStreet1,
	'' as EmployerStreet2,
	ce.ADDRESS_CITY as EmployerCity,
	ce.ADDRESS_STATE as EmployerState,
	RIGHT('000000'+ RTRIM(ce.ADDRESS_ZIP), 5) as EmployerZip,
	CASE WHEN ce.PHONE_AREA_CODE IS NOT NULL AND ce.PHONE_AREA_CODE > 0 AND
		ce.PHONE_PREFIX IS NOT NULL AND ce.PHONE_PREFIX > 0 AND
		ce.PHONE_NUMBER IS NOT NULL AND ce.PHONE_NUMBER > 0 THEN
--			'(' + CAST(ce.PHONE_AREA_CODE as VARCHAR(3)) + ') ' + CAST(ce.PHONE_PREFIX as VARCHAR(3)) + '-' + CAST(ce.PHONE_NUMBER as VARCHAR(4))
			'(' + right('0000'+ rtrim(CAST(ISNULL(ce.PHONE_AREA_CODE,'') as VARCHAR(3))), 3) + ') ' + right('0000'+ rtrim(CAST(ISNULL(ce.PHONE_PREFIX,'') as VARCHAR(3))), 3) + '-' + right('000'+ rtrim(CAST(ISNULL(ce.PHONE_NUMBER,'') as VARCHAR(4))), 4)
		ELSE ''
	END as EmployerPhone,
	ce.YEARS as EmployerYears,
	ce.MONTHS as EmployerMonths
	
FROM tblLoanApp_Applicant a WITH (NOLOCK)
	LEFT JOIN tblLoanApp_CurrAddress ca WITH (NOLOCK) ON a.LoanApp_ApplicantID = ca.LoanApp_ApplicantID
	LEFT JOIN tblLoanApp_CurrEmployer ce WITH (NOLOCK) ON a.LoanApp_ApplicantID = ce.LoanApp_ApplicantID
	













