/****** Object:  View dbo.view_LoanAppForCarleton    Script Date: 7/31/2024 12:57:19 PM ******/




CREATE VIEW [dbo].[view_LoanAppForCarleton] AS

SELECT 
	l.LoanAppID
	,l.HOUSING_PAYMENT
	,case when (l.TRADE_IN_MAKE Is Not Null and l.TRADE_IN_MODEL Is Not Null And l.TRADE_IN_YEAR Is Not Null) Then 1 else 0 end as hasTradeIn
	,l.TRADE_IN_MAKE
	,l.TRADE_IN_MODEL
	,l.TRADE_IN_CREDITOR
	,l.TRADE_IN_ALLOWANCE
	,l.TRADE_IN_DEBT
	,l.TRADE_IN_YEAR
	,l.TRADE_IN_MILEAGE
	,l.TRADE_IN_VIN
	,l.LOAN_TRADE_IN_PAYMENT
	,d.DealerID
	,d.DealerName as dealerName
	,d.Address as dealerAddress
	,d.City as dealerCity
	,d.State as dealerState
	,d.ZIP as dealerZip
	--,ISNULL(l.LOAN_MISC2,0) as loanFeeMisc
FROM tblLoanApps l WITH (NOLOCK)
	INNER JOIN tblDealers d WITH (NOLOCK) ON d.DealerID = l.DealerID





