/****** Object:  View dbo.view_LoanApp_Borrower_For_HarlandFS    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW view_LoanApp_Borrower_For_HarlandFS AS
SELECT
	a.LoanAppID,
	a.LoanApp_ApplicantID,
	RIGHT('0000000'+ CAST(a.SSN_1 AS VARCHAR(3)), 3) + RIGHT('0000000'+ CAST(a.SSN_2 AS VARCHAR(2)), 2) + RIGHT('0000000'+ CAST(a.SSN_3 AS VARCHAR(4)), 4) as SSN,
	CAST(a.DOB_YEAR as VARCHAR(4)) + '-' +
	CASE WHEN Len(a.DOB_MONTH) < 2 THEN '0'+CAST(a.DOB_MONTH as varchar(2)) ELSE  CAST(a.DOB_MONTH as varchar(2)) END + '-' +
	CASE WHEN Len(a.DOB_DAY) < 2 THEN '0'+CAST(a.DOB_DAY as varchar(2)) ELSE CAST(a.DOB_DAY as varchar(2)) END as DOB,
	a.LAST_NAME,
	a.FIRST_NAME,
	a.MIDDLE_INITIAL,
	CASE WHEN ISNULL(a.HOME_OWNER,0) = 1 THEN 'O' ELSE 'R' END as TypeOfHousing,
	a.HOUSING_PAYMENT,
	aca.STREET_1 cSTREET_1,

	cSTREET_2 = CASE
		WHEN aca.STREET_2	IS NULL		THEN ''
		WHEN REPLACE(aca.STREET_2, '.', '')	LIKE 'PO %' THEN ''
		ELSE ACA.STREET_2
		END,
	--aca.STREET_2 ,
	aca.CITY cCITY,
	aca.STATE cSTATE,
	aca.ZIP cZIP,
	CAST(a.HOME_PHONE_AREA_CODE as varchar(3)) + CAST(a.HOME_PHONE_PREFIX as varchar(3)) + CAST(a.HOME_PHONE_NUMBER as varchar(4)) as HOME_PHONE,
	aca.YEARS cYEARS,
	apa.STREET_1 pSTREET_1,
	apa.STREET_2 pSTREET_2,
	apa.CITY pCITY,
	apa.STATE pSTATE,
	apa.ZIP pZIP,
	apa.YEARS pYEARS,
	ace.COMPANY ceCOMPANY,
	ace.ADDRESS_STREET_1 ceADDRESS_STREET_1,
	'' ceADDRESS_STREET_2,
	ace.ADDRESS_CITY ceADDRESS_CITY,
	ace.ADDRESS_STATE ceADDRESS_STATE,
	ace.ADDRESS_ZIP ceADDRESS_ZIP,
	CAST(ace.PHONE_AREA_CODE as varchar(3)) + CAST(ace.PHONE_PREFIX as varchar(3)) + CAST(ace.PHONE_NUMBER as varchar(4)) as cePHONE,
	ace.PHONE_EXTENSION cePHONE_EXTENSION,
	ace.POSITION cePOSITION,
	ace.YEARS ceYEARS,
	CASE WHEN ISNULL(SELF_EMPLOYED, 0) = 1 THEN 3 ELSE 1 END as ceEmploymentStatus,
	DATEADD(year, -ace.YEARS, DATEADD(month, -ace.MONTHS, getdate())) as ceHireDate,
	a.GROSS_MONTHLY,
	CASE a.MARITAL_STATUS
		WHEN 'Married' THEN 'M'
		WHEN 'Not Married' THEN 'U'
		WHEN 'Separated' THEN 'S'
		WHEN 'Unmarried' THEN 'U' ELSE 'U'
	END as MARITAL_STATUS,
	a.LICENSE_NUMBER,
	a.LICENSE_STATE,
	a.DEPENDENTS_AGES,
	CASE a.RELATIONSHIP_TO_PRIMARY
		WHEN 'SPOUSE' THEN 2
		WHEN 'RELATIVE' THEN 10
		WHEN 'PARENT_CHILD' THEN 3
		WHEN 'OTHER' THEN 9 ELSE ''
	END as RELATIONSHIP_TO_PRIMARY,
	a.OTHER_SOURCE,
	a.OTHER_MONTHLY
FROM tblLoanApp_Applicant a WITH (NOLOCK)
	LEFT JOIN tblLoanApp_CurrAddress aca  WITH (NOLOCK) ON aca.LoanApp_ApplicantID = a.LoanApp_ApplicantID
	LEFT JOIN tblLoanApp_PrevAddress apa WITH (NOLOCK) ON apa.LoanApp_ApplicantID = a.LoanApp_ApplicantID
	LEFT JOIN tblLoanApp_CurrEmployer ace WITH (NOLOCK) ON ace.LoanApp_ApplicantID = a.LoanApp_ApplicantID


--WHERE 	a.LoanAppID=995190



