/****** Object:  View dbo.view_LoanApp_FIPS    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW view_LoanApp_FIPS AS
	SELECT
	    LoanAppID           = APPLICANT.LoanAppID,
	    DealerZIP           = DEALER.ZIP,
	    DealerState         = DEALER.State,
	    DealerFIPS          = ZIP_DEALER.CountyFIPS,
	    CustomerZIP         = APPLICANT_ADDRESS.ZIP,
	    CustomerState       = APPLICANT_ADDRESS.State,
	    CustomerFIPS        = ZIP_APPLICANT.CountyFIPS
	
	FROM
	         tblLoanApps                 APPLICATION                 WITH (NOLOCK)
	    JOIN tblLoanApp_Applicant        APPLICANT                   WITH (NOLOCK)  ON  APPLICANT.LoanAppID                     =   APPLICATION.LoanAppID
	    JOIN tblLoanApp_CurrAddress      APPLICANT_ADDRESS           WITH (NOLOCK)  ON  APPLICANT_ADDRESS.LoanApp_ApplicantID   =   APPLICANT.LoanApp_ApplicantID
	    JOIN viewDealerZipCodes          DEALER                      WITH (NOLOCK)  ON  DEALER.DealerID                         =   APPLICATION.DealerID
	    JOIN tblZips                     ZIP_DEALER                  WITH (NOLOCK)  ON  ZIP_DEALER.ZIPCode                      =   DEALER.ZIP
	    JOIN tblZips                     ZIP_APPLICANT               WITH (NOLOCK)  ON  ZIP_APPLICANT.ZIPCode                   =   APPLICANT_ADDRESS.ZIP





