CREATE VIEW view_ZipCodes AS

SELECT     dbo.tblZips.ZIPCode, dbo.tblCities.City, dbo.tblStates.StateAbbrev, dbo.tblStates.StateName, dbo.tblCounties.County, dbo.tblZips.CountyFIPS,
                      dbo.tblZips.StateFIPS, dbo.tblCities.MSA, dbo.tblZips.AreaCode, dbo.tblZips.Latitude, dbo.tblZips.Longitude, dbo.tblZips.ZIPCodeType
