/****** Object:  View dbo.view_ZipCodes_2    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW view_ZipCodes_2 AS

SELECT
  TOP 100 PERCENT

  ZIP.ZIPCode,
  CITY.City,
  STATE.StateAbbrev,
  STATE.StateName,
  COUNTY.County,
  ZIP.CountyFIPS,
  ZIP.StateFIPS,
  CITY.MSA,
  ZIP.AreaCode,
  ZIP.Latitude,
  ZIP.Longitude,
  ZIP.ZIPCodeType
FROM
	tblZips ZIP
		JOIN tblCities CITY ON ZIP.CityID=CITY.CityID
		JOIN tblStates STATE ON STATE.StateFIPS=ZIP.StateFIPS
		JOIN tblCounties COUNTY ON ZIP.CountyFIPS = COUNTY.CountyFIPS

ORDER BY
	(SELECT COUNT(*) FROM tblCities C2 WHERE C2.City=CITY.City AND C2.StateFIPS=ZIP.StateFIPS)+(SELECT COUNT(*) FROM tblZips Z2 WHERE Z2.CityID=CITY.CityID) DESC, CITY.City





