-- * 64 of 64    vwERD_CreditReports   ID: 320056226
CREATE VIEW dbo.vwERD_CreditReports
AS
SELECT     TOP 100 PERCENT dbo.tblLoanApps.APPLICANT_NAMES, dbo.tblCreditReports.sGUID, dbo.tblLoanApp_Bids.LENDER_CREDIT_GUID,
                      dbo.tblCreditReports.credit_bureau_cd, dbo.tblLoanApp_Bids.LENDER_CREDIT_EQ, dbo.tblLoanApp_Bids.LENDER_CREDIT_EX,
                      dbo.tblLoanApps.LENDER_CREDIT_EQ AS Expr2, dbo.tblLoanApps.LENDER_CREDIT_EX AS Expr3, dbo.tblLoanApps.DEALER_CREDIT_EQ,
                      dbo.tblLoanApps.DEALER_CREDIT_EX
FROM         dbo.tblCreditReports INNER JOIN
                      dbo.tblLoanApps ON dbo.tblCreditReports.LoanAppID = dbo.tblLoanApps.LoanAppID INNER JOIN
                      dbo.tblLoanApp_Bids ON dbo.tblLoanApps.LoanAppID = dbo.tblLoanApp_Bids.LoanAppID
GROUP BY dbo.tblLoanApps.APPLICANT_NAMES, dbo.tblCreditReports.sGUID, dbo.tblLoanApp_Bids.LENDER_CREDIT_GUID,
                      dbo.tblCreditReports.credit_bureau_cd, dbo.tblLoanApp_Bids.LENDER_CREDIT_EQ, dbo.tblLoanApp_Bids.LENDER_CREDIT_EX,
                      dbo.tblLoanApps.LENDER_CREDIT_EQ, dbo.tblLoanApps.LENDER_CREDIT_EX, dbo.tblLoanApps.DEALER_CREDIT_EQ,
                      dbo.tblLoanApps.DEALER_CREDIT_EX
ORDER BY dbo.tblLoanApps.APPLICANT_NAMES








