/****** Object:  View dbo.TEMP_ERIK_viewLoanApps_OutstandingReportBackFill    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW TEMP_ERIK_viewLoanApps_OutstandingReportBackFill AS
	SELECT 
		DTI						= BID.DTI,
		PTI						= BID.PTI,
		Primary_Score			= BID.Primary_Score,
		AppPayment				= ISNULL(ISNULL(WORKSHEET.LOAN_ESTIMATED_PAYMENT, APP.LOAN_ESTIMATED_PAYMENT), 0),
		LOAN_TOTAL_LOAN_AMOUNT	= ISNULL(ISNULL(WORKSHEET.LOAN_TOTAL_LOAN_AMOUNT, APP.LOAN_TOTAL_LOAN_AMOUNT), 0),
		TERM_REQUESTED			= ISNULL(APP.LOAN_TERM_REQUESTED, 0),
		LoanAppID				= BID.LoanAppID,
		LoanApp_BidID			= BID.LoanApp_BidID,
		AppCreate				= APP.CreateDateTime,
		AppUpdate				= APP.UpdateDateTime,
		Applicants				= UPPER(RTRIM(LTRIM(APP.Applicant_Names))),
		LenderID				= BRANCH.LenderID,
		LenderName				= UPPER(RTRIM(LTRIM(MASTER.LenderName))),
		LendersBranchID			= BRANCH.LendersBranchID,
		BranchName				= UPPER(RTRIM(LTRIM(BRANCH.BranchName))),
		DealerID				= DEALER.DealerID,
		DealerName				= UPPER(RTRIM(LTRIM(DEALER.DealerName))),
		Term					= RTRIM(LTRIM(REPLACE(ISNULL(BID.TERM, ''), 'mo', ''))),
		Rate					= RTRIM(LTRIM(REPLACE(REPLACE(REPLACE(BID.RATE, ' ', ''), '%', ''), ',', '.'))),
		Financing_Amount		= Financing_Amount,
		Payment					= Payment,
		BidCreate				= BID.CreateDateTime,
		BidUpdate				= BID.UpdateDateTime,
	  	Lender_Credit 			= CASE
				WHEN LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) > 0  THEN BID.LENDER_CREDIT_EX
				WHEN LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) > 0  THEN BID.LENDER_CREDIT_TU
				WHEN LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) > 0  THEN BID.LENDER_CREDIT_EQ
			END,
		WorksheetID			= ISNULL(WORKSHEET.LoanApp_WorksheetID, 0),
		BidAge					= DATEDIFF(d, BID.CreateDateTime, GETDATE())
	FROM
					tblLoanApp_Bids				BID				WITH (NOLOCK)
			 JOIN	tblLoanApps					APP				WITH (NOLOCK) ON APP.LoanAppID			= BID.LoanAppID
			 JOIN	tblLendersBranches			BRANCH			WITH (NOLOCK) ON BRANCH.LendersBranchID	= BID.LendersBranchID
			 JOIN	tblLenders					MASTER			WITH (NOLOCK) ON MASTER.LenderID		= BRANCH.LenderID
			 JOIN	tblDealers					DEALER			WITH (NOLOCK) ON DEALER.DealerID		= APP.DealerID
		LEFT JOIN	tblLoanApp_Worksheet		WORKSHEET		WITH (NOLOCK) ON ISNULL(WORKSHEET.Active, 0) = 1 AND WORKSHEET.LoanApp_BidID = BID.LoanApp_BidID
		LEFT JOIN	tblCreditPulls				Credit_EQ		WITH (NOLOCK) ON NULLIF(BID.Lender_Credit_EQ, '') IS NOT NULL AND Credit_EQ.GUID = BID.Lender_Credit_EQ
		LEFT JOIN	tblCreditPulls				Credit_EX		WITH (NOLOCK) ON NULLIF(BID.Lender_Credit_EX, '') IS NOT NULL AND Credit_EX.GUID = BID.Lender_Credit_EX
		LEFT JOIN	tblCreditPulls				Credit_TU		WITH (NOLOCK) ON NULLIF(BID.Lender_Credit_TU, '') IS NOT NULL AND Credit_TU.GUID = BID.Lender_Credit_TU
	WHERE		
			DATEDIFF(d, BID.CreateDateTime, GETDATE()) <= 30
		AND BID.Status NOT IN ('PENDING_LENDER')
		AND ISNULL(ISNULL(WORKSHEET.LOAN_TOTAL_LOAN_AMOUNT, APP.LOAN_TOTAL_LOAN_AMOUNT), -1) > 0
		AND (	BID.Primary_Score IS NULL OR ISNULL(BID.DTI, -1) <= 0 OR ISNULL(BID.PTI, -1) <= 0)

		AND (		ISNULL(DATALENGTH(Credit_EQ.Data_Raw), 0) > 500
				OR	ISNULL(DATALENGTH(Credit_EX.Data_Raw), 0) > 500
				OR	ISNULL(DATALENGTH(Credit_TU.Data_Raw), 0) > 500)
		AND	BID.LoanApp_BidID NOT IN (SELECT LOANAPP_BIDID FROM tblLoanApp_BackFilled WITH (NOLOCK))




