/****** Object:  View dbo.TEMP_ERIK_viewLoanApps_OutstandingReportBackFill_Inner    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW TEMP_ERIK_viewLoanApps_OutstandingReportBackFill_Inner AS
SELECT
	LoanAppID				= BID.LoanAppID,
	LoanApp_BidID			= BID.LoanApp_BidID,

	AppPayment				= CASE
		WHEN ISNULL(WORKSHEET.LOAN_ESTIMATED_PAYMENT, 0) > 0	THEN WORKSHEET.LOAN_ESTIMATED_PAYMENT
		WHEN ISNULL(APP.LOAN_ESTIMATED_PAYMENT, 0) > 0			THEN APP.LOAN_ESTIMATED_PAYMENT
		ELSE 0
	END,

	LOAN_TOTAL_LOAN_AMOUNT	= CASE
		WHEN ISNULL(WORKSHEET.LOAN_TOTAL_LOAN_AMOUNT, 0) > 0	THEN WORKSHEET.LOAN_TOTAL_LOAN_AMOUNT
		WHEN ISNULL(APP.LOAN_TOTAL_LOAN_AMOUNT, 0) > 0			THEN APP.LOAN_TOTAL_LOAN_AMOUNT
		ELSE 0
	END,

	TERM_REQUESTED = CASE
		WHEN ISNULL(WORKSHEET.LOAN_TERM_REQUESTED, 0) > 0	THEN WORKSHEET.LOAN_TERM_REQUESTED
		WHEN ISNULL(APP.LOAN_TERM_REQUESTED, 0) > 0			THEN APP.LOAN_TERM_REQUESTED
		ELSE 0
	END,

	AppCreate				= APP.CreateDateTime,
	AppUpdate				= APP.UpdateDateTime,
	Applicants				= UPPER(RTRIM(LTRIM(APP.Applicant_Names))),
	LendersBranchID			= BID.LendersBranchID,
	DealerID				= APP.DealerID,
	Term					= RTRIM(LTRIM(REPLACE(ISNULL(BID.TERM, ''), 'mo', ''))),
	Rate					= RTRIM(LTRIM(REPLACE(REPLACE(REPLACE(BID.RATE, ' ', ''), '%', ''), ',', '.'))),
	Financing_Amount		= Financing_Amount,
	Payment					= Payment,
	BidCreate				= BID.CreateDateTime,
	BidUpdate				= BID.UpdateDateTime,
	Lender_Credit 	= CASE
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) > 0  THEN BID.LENDER_CREDIT_EX
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) > 0  THEN BID.LENDER_CREDIT_TU
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) > 0  THEN BID.LENDER_CREDIT_EQ
	END

FROM
				tblLoanApp_Bids			BID 		WITH (NOLOCK)
	JOIN		tblLoanApps				APP			WITH (NOLOCK) ON BID.LoanAppID = APP.LoanAppID
	JOIN		tblLendersBranches		BRANCH		WITH (NOLOCK) ON BID.LendersBranchID = BRANCH.LendersBranchID
	LEFT JOIN	tblLoanApp_Worksheet	WORKSHEET	WITH (NOLOCK) ON ISNULL(WORKSHEET.Active, 0) = 1 AND WORKSHEET.LoanApp_BidID = BID.LoanApp_BidID

WHERE
	DATEDIFF(d, BID.CreateDateTime, GETDATE()) <= 60
	AND (NOT EXISTS (SELECT * FROM tblLoanApp_BackFilled BF WITH (NOLOCK) WHERE BF.LoanApp_BidID = BID.LoanApp_BidID))
	AND	(ISNULL(BID.DTI, -1) <= 0 OR ISNULL(BID.PTI, -1) <= 0)
	AND ISNULL(APP.LOAN_TOTAL_LOAN_AMOUNT, 0) > 0
	AND (	(LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) > 0)
	OR		(LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) > 0)	
	OR		(LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) > 0))	





GO

