/****** Object:  View dbo.TEMP_LenderLESActivationStatus    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW TEMP_LenderLESActivationStatus AS

SELECT
	PartnerToolID	= TOOL.PartnerToolID,
	PartnerTool		= TOOL.ShortName,
	Partner			= ISNULL(TOOL.DisplayName, TOOL.ShortName),
	LenderID		= LENDER.LenderID,
	LenderName		= LENDER.LenderName,
	LendersBranchID	= BRANCH.LendersBranchID,
	Active			= ISNULL(RELATION.Active, CONVERT(BIT, 0)),
	ActiveBy		= CASE
		WHEN RELATION.Active IN (NULL, 0)							THEN	''
		WHEN RELATION.LendersBranchID	= BRANCH.LendersBranchID	THEN	'BRANCH'
		WHEN RELATION.LenderID			= LENDER.LenderID			THEN	'LENDER'
		ELSE ''
	END,
	Login			= ISNULL(RELATION.Login, ''),
	Password		= ISNULL(RELATION.Password, ''),
	URL				= ISNULL(RELATION.URL, '')

FROM
						tblLenders			LENDER		WITH (NOLOCK)
	INNER JOIN 			tblLendersBranches	BRANCH		WITH (NOLOCK) ON LENDER.LenderID = BRANCH.LenderID
	CROSS JOIN			tblPartnerTools		TOOL		WITH (NOLOCK)
	LEFT OUTER JOIN 	tblPartnerRelation	RELATION 	WITH (NOLOCK)	
			ON			RELATION.PartnerToolID	= TOOL.PartnerToolID
				AND		(	(TOOL.LenderBranch = 1 AND ISNULL(RELATION.LenderID, LENDER.LenderID) = BRANCH.LenderID AND RELATION.LendersBranchID = BRANCH.LendersBranchID)
						OR	(TOOL.Lender = 1 AND RELATION.LenderID = LENDER.LenderID AND RELATION.LendersBranchID IS NULL))
WHERE
			TOOL.ShortName			= 'LES'		
		AND TOOL.Active				= 1
		AND (TOOL.Lender = 1 OR TOOL.LenderBranch = 1)





