/****** Object:  View dbo.TEMP_ProgramDetails    Script Date: 7/31/2024 12:57:20 PM ******/



CREATE VIEW TEMP_ProgramDetails AS
SELECT
	P.LenderID,
	P.ProgramID,
  Program             = CASE
    WHEN LEN(ISNULL(P.ProgramName, '')) > 0 AND (CHARINDEX(' TIER ', ' ' + P.ProgramName + ' ') > 0 OR CHARINDEX(' LEVEL ', ' ' + P.ProgramName + ' ') > 0) THEN
      UPPER(P.ProgramName)
    WHEN LEN(ISNULL(P.ProgramName, '')) > 0 AND LEN(ISNULL(P.CreditTier, '')) > 0 THEN
      UPPER(P.ProgramName + ' (' + P.CreditTier + ' TIER)')
    WHEN LEN(ISNULL(P.ProgramName, '')) > 0 THEN
      UPPER(P.ProgramName)
    WHEN LEN(ISNULL(P.ProgramName, '')) = 0 AND LEN(ISNULL(P.CreditTier, '')) > 0 THEN
      UPPER(P.CreditTier + ' TIER')
    ELSE
      'UN-NAMED PROGRAM WITH NO TIER'
  END,
  AMOUNT_MIN          = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'AMOUNT_MIN'              AND S.ProgramID = P.ProgramID),
  AMOUNT_MAX          = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'AMOUNT_MAX'              AND S.ProgramID = P.ProgramID),
  DTI_MIN             = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'PRIMARY_DTI_MIN'         AND S.ProgramID = P.ProgramID),
  DTI_MAX             = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'PRIMARY_DTI_MAX'         AND S.ProgramID = P.ProgramID),
  DTI_J_MIN           = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'JOINT_DTI_MIN'           AND S.ProgramID = P.ProgramID),
  DTI_J_MAX           = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'JOINT_DTI_MAX'           AND S.ProgramID = P.ProgramID),
  DTI_J_OVERRIDES     = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'JOINT_DTI_CAN_OVERRIDE'  AND S.ProgramID = P.ProgramID),
  LTV_BOOK            = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'LTV_BOOK'                AND S.ProgramID = P.ProgramID),
  LTV_R_ADJ_MAX       = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'LTV_RETAIL_ADJ_MAX'      AND S.ProgramID = P.ProgramID),
  LTV_R_MAX           = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'LTV_RETAIL_MAX'          AND S.ProgramID = P.ProgramID),
  LTV_W_ADJ_MAX       = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'LTV_WHOLESALE_ADJ_MAX'   AND S.ProgramID = P.ProgramID),
  LTV_W_MAX           = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'LTV_WHOLESALE_MAX'       AND S.ProgramID = P.ProgramID),
  PTI_MIN             = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'PRIMARY_PTI_MIN'         AND S.ProgramID = P.ProgramID),
  PTI_MAX             = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'PRIMARY_PTI_MAX'         AND S.ProgramID = P.ProgramID),
  PTI_J_MIN           = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'JOINT_PTI_MIN'           AND S.ProgramID = P.ProgramID),
  PTI_J_MAX           = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'JOINT_PTI_MAX'           AND S.ProgramID = P.ProgramID),
  PTI_J_OVERRIDES     = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'JOINT_PTI_CAN_OVERRIDE'  AND S.ProgramID = P.ProgramID),
  SCORE_CARD          = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'CREDIT_SCORECARD'        AND S.ProgramID = P.ProgramID),
  SCORE_MIN           = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'CREDIT_SCORE_APP_MIN'    AND S.ProgramID = P.ProgramID),
  SCORE_MAX           = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'CREDIT_SCORE_APP_MAX'    AND S.ProgramID = P.ProgramID),
  SCORE_CO_MIN        = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'CREDIT_SCORE_COBO_MIN'   AND S.ProgramID = P.ProgramID),
  SCORE_CO_MAX        = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'CREDIT_SCORE_COBO_MAX'   AND S.ProgramID = P.ProgramID),
  TERM_MIN            = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'TERM_MIN'                AND S.ProgramID = P.ProgramID),
  TERM_MAX            = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'TERM_MAX'                AND S.ProgramID = P.ProgramID),
  VEHICLE_W_MIN       = (SELECT TOP 1 VALUE FROM TEMP_viewUnderwritingProgramStatistics S WITH (NOLOCK) WHERE  WHAT = 'VEHICLE_WHOLESALE_MIN'   AND S.ProgramID = P.ProgramID)
FROM
	tblPrograms P WITH (NOLOCK)
WHERE
  (ISNULL(P.Underwriting, 0) = 1 OR ISNULL(P.Automated, 0) = 1)
  AND ProgramID IN (SELECT ProgramID FROM TEMP_viewUnderwritingProgramStatistics WITH (NOLOCK))
  AND (P.LenderID IN (SELECT LenderID FROM tblLenders L WITH (NOLOCK) WHERE NOT SUBMIT_STATUS='CLOSED'))






