/****** Object:  View dbo.TEST_viewQueryReportingBidsDisplay    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW TEST_viewQueryReportingBidsDisplay AS
  SELECT
   LAB.BidUpdateDateTime,
   LAB.UpdateDateTime,
   LAB.LoanAppID,
   LAB.MESSAGING_STATUS,
   LAB.Loan_Purchase_Price,
   LAB.Loan_Total_Loan_Amount,
   LAB.FINANCING_AMOUNT,
   LAB.LoanApp_BidID,
   LAB.DealerID,
   LAB."DealerCity",
   LAB."DealerState",
   LAB."VEHICLE_MODEL",
   LAB."VEHICLE_MAKE",
   LAB."APPLICANT_NAMES",
   LAB.LenderID,
   LAB.LendersBranchID,
   "Dealer"       = LAB.DealerName,
--dbo.dealerFormatDisplayNameFromValues(LAB.dealerName, LAB.dealerCity, LAB.DealerState, LAB.DealerID),
   "Application"   = DBO.PropCase(CONVERT(VARCHAR(64), LAB.APPLICANT_NAMES + ' (' + LAB.VEHICLE + ')')),
   "Loan #"       = dbo.formatInteger(LAB.LoanAppID),
   "Status"       = LAB.STATUS,
	BidFundingStatus = LAB.BidFundingStatus,
   "Offer #"      = dbo.formatInteger(LAB.LoanApp_BidID),
   "Lender" = CASE
      WHEN LAB.LenderName = LAB.BranchName THEN
        REPLACE( CONVERT(VARCHAR(64), DBO.PropCase(LAB.LenderName)), '.', '')
      ELSE REPLACE(CONVERT(VARCHAR(64), DBO.PropCase(LAB.LenderName + ' - ' + LAB.BranchName)), '.', '')
      END,
  Funded_Date = LAB.funded_date,
  GapCoverageStatus = GCI.Status
FROM
  VIEW_LoanApps_Bids LAB WITH (NOLOCK)
	LEFT OUTER JOIN tblGapCoverageInfo	GCI  WITH (NOLOCK) ON LAB.LoanAppID = GCI.LoanAppID

--WHERE 	LAB.DealerName LIKE 'LendingTree%' 	AND FUNDED_DATE > '2013-01-01'



