App_Bids_Fax].[UpdateDateTime] as _hypmv_9_col_35,  [dbo].[tblLenderDealerRelation].[LenderID] as _hypmv_9_col_36,  [dbo].[tblLoanApp_Bids].[ADVANCE] as _hypmv_9_col_37,  [dbo].[tblLoanApp_Bids].[CreateDateTime] as _hypmv_9_col_38,  [dbo].[tblPartnerDataElement].[PartnerToolID] as _hypmv_9_col_39,  [dbo].[tblLoanApp_Bids_Fax].[STATUS] as _hypmv_9_col_40,  [dbo].[tblLendersLogins].[UserName] as _hypmv_9_col_41,  [dbo].[tblLendersLogins].[FullName] as _hypmv_9_col_42,  [dbo].[tblLendersLogins].[ColorCode] as _hypmv_9_col_43,  [dbo].[tblLoanApp_Bids].[LoanAppID] as _hypmv_9_col_44,  [dbo].[tblPartnerElementDefinition].[PartnerToolID] as _hypmv_9_col_45,  [dbo].[tblPartnerElementDefinition].[Field] as _hypmv_9_col_46,  [dbo].[tblLoanApp_Bids_Fax].[LoanApp_Bids_FaxID] as _hypmv_9_col_47,  [dbo].[tblLenderDealerRelation].[LenderDealerRelationID] as _hypmv_9_col_48,  [dbo].[tblPartnerDataElement].[PartnerDataElementID] as _hypmv_9_col_49,  [dbo].[tblPartnerElementDefinition].[PartnerElementDefinitionID] as _hypmv_9_col_50,  [dbo].[tblDealers].[DealerID] as _hypmv_9_col_51,  [dbo].[tblLendersLogins].[LendersLoginID] as _hypmv_9_col_52,  [dbo].[tblLoanAppAssignedDealers].[LoanAppID] as _hypmv_9_col_53,  [dbo].[tblLoanAppAssignedDealers].[DealersLoginID] as _hypmv_9_col_54 FROM  [dbo].[tblLoanApp_Bids],  [dbo].[tblLoanApp_Bids_Fax],  [dbo].[tblLenderDealerRelation],  [dbo].[tblLoanApps],  [dbo].[tblPartnerDataElement],  [dbo].[tblPartnerElementDefinition],  [dbo].[tblDealers],  [dbo].[tblLendersLogins],  [dbo].[tblLoanAppAssignedDealers],  [dbo].[tblLoanApp_Worksheet]   WHERE ( [dbo].[tblLoanApp_Bids].[LoanAppID] = [dbo].[tblLoanApps].[LoanAppID] ) AND ( [dbo].[tblPartnerElementDefinition].[ValueType] = 'PARTNER_LOAN_ID' ) AND (( [dbo].[tblPartnerDataElement].[PartnerToolID] = [dbo].[tblPartnerElementDefinition].[PartnerToolID] ) AND ( [dbo].[tblLoanApp_Bids].[LoanApp_BidID] = [dbo].[tblPartnerDataElement].[LoanApp_BidID] )) AND ( [dbo].[tblLoanApp_Bids].[LoanApp_BidID] = [dbo].[tblLoanApp_Bids_Fax].[LoanApp_BidID] ) AND ( [dbo].[tblLoanApps].[LoanAppID] = [dbo].[tblLoanAppAssignedDealers].[LoanAppID] ) AND ( [dbo].[tblLoanApps].[DealerID] = [dbo].[tblDealers].[DealerID] ) AND ( [dbo].[tblLenderDealerRelation].[DealerID] = [dbo].[tblDealers].[DealerID] ) AND ( [dbo].[tblLenderDealerRelation].[LenderAgentID] = [dbo].[tblLendersLogins].[LendersLoginID] ) AND ( [dbo].[tblLoanApp_Bids].[LoanApp_BidID] = [dbo].[tblLoanApp_Worksheet].[LoanApp_BidID] ) AND ( [dbo].[tblLoanApp_Worksheet].[ACTIVE] = 1 ) 
