/****** Object:  View dbo.bak_2014_12_01_bak_viewDealersBillingActivePayFlow    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW bak_2014_12_01_bak_viewDealersBillingActivePayFlow AS
	SELECT 
		Dealers.DealerID,
		Billing.Dealer_Service_ID,
		Billing.ARB_ProfileID
	FROM 		
				tblDealersBilling		Billing		WITH (NOLOCK)
		JOIN	tblDealers				Dealers		WITH (NOLOCK) ON Dealers.DealerID = Billing.DealerID
	WHERE
			Dealers.DealerStatus IN('ACTIVE')
		AND	Billing.Status NOT IN ('DEACTIVATED', 'DEACTIVATED BY MERCHANT')
		AND Billing.ARB_ProfileID NOT IN('ACH', 'ACH-Zimple', 'Zimple')






