/****** Object:  View dbo.spWorksheet_GetProperties    Script Date: 7/31/2024 12:57:20 PM ******/



CREATE VIEW spWorksheet_GetProperties AS	

	--DECLARE @WSID INTEGER, @LoanAppID INTEGER; SET @WSID=187371; SET @LoanAppID = 1161093;

	SELECT TOP 100 PERCENT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		LenderID				= Branch.LenderID,
		LendersBranchID			= Branch.LendersBranchID,
		LoanApp_WorksheetID		= WS.LoanApp_WorksheetID,
		WorksheetActive			= ISNULL(WS.Active, 0),
		BidStatus				= Bid.Status,
		Vehicle					= CONVERT(VARCHAR(60),	DBO.VehicleDescription(WS.Vehicle_Year, WS.Vehicle_Make, WS.Vehicle_Model, WS.Vehicle_Mileage, WS.Vehicle_VIN)),
		CanEditWorksheet		= CONVERT(BIT, CASE	WHEN WS.Active IS NULL THEN 1 WHEN WS.Active = 0 THEN 1 WHEN WS.Active = 1 AND Bid.Status IN('PENDING_LENDER', 'REFERRED') THEN 1 ELSE 0 END),
		IsUsed					= CONVERT(BIT, CASE ISNULL(WS.New_Used, '') WHEN 'NEW' THEN 1 ELSE 0 END),
		IsNew					= CONVERT(BIT, CASE ISNULL(WS.New_Used, '') WHEN 'NEW' THEN 0 ELSE 1 END),
		Make                	= CONVERT(VARCHAR(30),	DBO.ProperCase(IsNull(WS.Vehicle_Make,		''))),
		Model               	= CONVERT(VARCHAR(30),	DBO.ProperCase(IsNull(WS.Vehicle_Model,		''))),
		Mileage             	= WS.Vehicle_Mileage,
		VIN                 	= CONVERT(VARCHAR(17),	UPPER(REPLACE(ISNULL(WS.Vehicle_Vin, ''), ' ', ''))),
		Type                	= CONVERT(VARCHAR(20),	DBO.ProperCase(IsNull(WS.Vehicle_Type,		''))),
		New_Used				= CASE ISNULL(WS.New_Used, '') WHEN 'NEW' THEN 'New' ELSE 'Used' END,
		WS_Created				= ISNULL(WS.CreateDateTime, WS.UpdateDateTime),
		WS_Updated				= ISNULL(WS.UpdateDateTime, WS.CreateDateTime)
	FROM
					tblLoanApp_Worksheet	WS		WITH (NOLOCK)
		JOIN	tblLoanApp_Bids			Bid		WITH (NOLOCK)	ON Bid.LoanApp_BidID		= WS.LoanApp_BidID
		JOIN	tblLendersBranches		Branch	WITH (NOLOCK)	ON Branch.LendersBranchID	= Bid.LendersBranchID
/*	WHERE
		--WS.LoanApp_WorksheetID = @WSID
		Bid.LoanAppID			= @LoanAppID

	ORDER BY
		CanEditWorksheet,
		WS.UpdateDateTime	DESC,
		WS.CreateDateTime	DESC,
		Bid.UpdateDateTime	DESC,
		Bid.CreateDateTime	DESC
*/

	





GO

