/****** Object:  View dbo.temp_erik_nac_match    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW temp_erik_nac_match as


SELECT D.DealerID, T.DealerNumber, D.DealerName CS_DealerName, T.DealerName NAC_DealerName, 'Fax' MatchType, dbo.scrubPhoneNumber(D.Fax) CS, dbo.scrubPhoneNumber(T.Fax) NAC
FROM
  temp_erik_nac_dealers T
    JOIN tblDealers D ON (LEN(dbo.stripToNumbers(T.Fax)) > 0 And Len(dbo.stripToNumbers(D.Fax)) > 0 And dbo.stripToNumbers(T.Fax)=dbo.stripToNumbers(D.Fax))
WHERE
  NULLIF(T.CS_DealerID, 0) IS NULL


UNION ALL

SELECT D.DealerID, T.DealerNumber, D.DealerName CS_DealerName, T.DealerName NAC_DealerName, 'Telephone' MatchType, dbo.scrubPhoneNumber(D.Telephone) CS, dbo.scrubPhoneNumber(T.Telephone) NAC
FROM
  temp_erik_nac_dealers T
    JOIN tblDealers D ON (LEN(dbo.stripToNumbers(T.Telephone)) > 0 And Len(dbo.stripToNumbers(D.Telephone)) > 0 And dbo.stripToNumbers(T.Telephone)=dbo.stripToNumbers(D.Telephone))
WHERE
  NULLIF(T.CS_DealerID, 0) IS NULL

UNION ALL

SELECT D.DealerID, NAC.DealerNumber, D.DealerName CS_DealerName, NAC.DealerName NAC_DealerName, 'Name+Location' MatchType, D.City + ', ' + D.State + ' ' + D.ZIP Location_CS,   NAC.City + ', ' + NAC.State + ' ' + NAC.ZIP Location_NAC
FROM
  temp_erik_nac_dealers NAC
    JOIN tblDealers D on
      (
        dbo.stripToCompare(NAC.DealerName, 1)=dbo.stripToCompare(D.DealerName, 1)
        AND (
          ( dbo.stripToCompare(NAC.Zip, 0) = dbo.stripToCompare(D.Zip, 0) )
            OR ( dbo.stripToCompare(NAC.City, 1) = dbo.stripToCompare(D.City, 1) AND NAC.State = D.State )
        )
      )
WHERE
  NULLIF(NAC.CS_DealerID, 0) IS NULL






