/****** Object:  View dbo.viewAffiliateDealersActivity    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW [dbo].[viewAffiliateDealersActivity]
AS
SELECT DISTINCT
                      dbo.tblAffiliateLogins.AffiliateLoginID, dbo.tblAffiliateLogins.AffiliateID, dbo.tblAffiliates.Name, dbo.tblDealers.DealerID, dbo.tblDealers.DealerName,
                      dbo.tblDealers.Contact, dbo.tblDealers.Address, dbo.tblDealers.City, dbo.tblDealers.State, dbo.tblDealers.ZIP,
                      dbo.tblDealers.activated AS DealerActive,
                      dbo.tblDealers.DealerStatus AS DealerStatus,
                      dbo.tblDealers.DealerStatusUpdateDateTime,
                      dbo.tblAffiliateLogins.Active, NULL AS LoanAppCount, dbo.tblDealersBilling.status AS BillingStatus,
                      dbo.tblRatePlans.monthly_cost, dbo.tblRatePlans.rate_plan, dbo.tblDealersBilling.nextpayment,
                      CASE WHEN dbo.tblDealersBilling.aggregateamt IS NULL THEN '0.00' ELSE dbo.tblDealersBilling.aggregateamt END AS aggregateamt,
                          (SELECT     TOP 1 ts_added
                            FROM          tblPayFlowTransactions WITH (NOLOCK)
                            WHERE      dealerid = tblDealers.DealerID
                            ORDER BY ts_added DESC) AS Last_Payment_Dt
FROM         dbo.tblPayFlowTransactions WITH (NOLOCK)
	RIGHT OUTER JOIN dbo.tblAffiliates WITH (NOLOCK)
	INNER JOIN dbo.tblDealers WITH (NOLOCK) ON dbo.tblAffiliates.AffiliateID = dbo.tblDealers.AffiliateID
	INNER JOIN dbo.tblAffiliateLogins WITH (NOLOCK) ON dbo.tblAffiliates.AffiliateID = dbo.tblAffiliateLogins.AffiliateID ON
                      dbo.tblPayFlowTransactions.dealerid = dbo.tblDealers.DealerID
    LEFT OUTER JOIN dbo.tblRatePlans WITH (NOLOCK)
    RIGHT OUTER JOIN dbo.tblDealersBilling WITH (NOLOCK) ON dbo.tblRatePlans.rate_plan_cd = dbo.tblDealersBilling.rate_plan_cd ON
                      dbo.tblDealers.DealerID = dbo.tblDealersBilling.dealerid





