/****** Object:  View dbo.viewAffiliatesMonthlyAP    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW dbo.viewAffiliatesMonthlyAP
AS
SELECT     TOP 100 PERCENT dbo.tblAffiliates.AffiliateID, dbo.tblAffiliates.Name, DATENAME([month], dbo.viewPayFlow_UniqueTransactions.ts_added) AS [AP Month],
                      DATEPART(mm, dbo.viewPayFlow_UniqueTransactions.ts_added) AS [Billing Month], DATEPART(yyyy, dbo.viewPayFlow_UniqueTransactions.ts_added) AS [AP Year],
                      SUM(dbo.viewPayFlow_UniqueTransactions.amt * (dbo.tblAffiliatePayouts.payout_pct_external / 100)) AS [Payout Amt],
                      SUM(dbo.viewPayFlow_UniqueTransactions.amt * (dbo.tblAffiliatePayouts.payout_pct_internal / 100)) AS [Net Revenue], COUNT(dbo.tblDealers.DealerID)
                      AS [Num Dealers], SUM(CAST(dbo.viewPayFlow_UniqueTransactions.amt AS money) * 1) AS [Gross Revenue]
FROM         dbo.tblDealersBilling INNER JOIN
                      dbo.tblDealers ON dbo.tblDealersBilling.dealerid = dbo.tblDealers.DealerID INNER JOIN
                      dbo.viewPayFlow_UniqueTransactions ON dbo.tblDealersBilling.dealer_service_id = dbo.viewPayFlow_UniqueTransactions.dealer_service_id INNER JOIN
                      dbo.tblAffiliatePayouts INNER JOIN
                      dbo.tblAffiliates ON dbo.tblAffiliatePayouts.payout_id = dbo.tblAffiliates.payout_id ON dbo.tblDealers.AffiliateID = dbo.tblAffiliates.AffiliateID
WHERE     (dbo.viewPayFlow_UniqueTransactions.result = 0)
GROUP BY dbo.tblAffiliates.AffiliateID, dbo.tblAffiliates.Name, DATENAME([month], dbo.viewPayFlow_UniqueTransactions.ts_added), DATEPART(mm,
                      dbo.viewPayFlow_UniqueTransactions.ts_added), DATEPART(yyyy, dbo.viewPayFlow_UniqueTransactions.ts_added)
ORDER BY dbo.tblAffiliates.AffiliateID, DATEPART(yyyy, dbo.viewPayFlow_UniqueTransactions.ts_added) DESC, DATEPART(mm, dbo.viewPayFlow_UniqueTransactions.ts_added)







