                      dbo.tblDealers.DealerID, dbo.tblDealers.DealerName, dbo.tblRatePlans.rate_plan, dbo.viewPayFlow_UniqueTransactions.amt,
                      dbo.viewPayFlow_UniqueTransactions.amt * (dbo.tblAffiliatePayouts.payout_pct_external / 100) AS [Payout Amt], dbo.tblDealersBilling.status,
                      dbo.viewPayFlow_UniqueTransactions.respmsg, dbo.viewPayFlow_UniqueTransactions.result, dbo.tblPayFlowResultCodes.pf_respmsg,
                      dbo.viewPayFlow_UniqueTransactions.ts_added
FROM         dbo.tblDealersBilling INNER JOIN
                      dbo.tblDealers ON dbo.tblDealersBilling.dealerid = dbo.tblDealers.DealerID INNER JOIN
                      dbo.viewPayFlow_UniqueTransactions ON dbo.tblDealersBilling.dealer_service_id = dbo.viewPayFlow_UniqueTransactions.dealer_service_id INNER JOIN
                      dbo.tblAffiliatePayouts INNER JOIN
                      dbo.tblAffiliates ON dbo.tblAffiliatePayouts.payout_id = dbo.tblAffiliates.payout_id ON dbo.tblDealers.AffiliateID = dbo.tblAffiliates.AffiliateID INNER JOIN
                      dbo.tblRatePlans ON dbo.tblDealersBilling.rate_plan_cd = dbo.tblRatePlans.rate_plan_cd LEFT OUTER JOIN
                      dbo.tblPayFlowResultCodes ON dbo.viewPayFlow_UniqueTransactions.result = dbo.tblPayFlowResultCodes.pf_result
GROUP BY dbo.tblAffiliates.AffiliateID, dbo.tblAffiliates.Name, DATENAME([month], dbo.viewPayFlow_UniqueTransactions.ts_added), DATEPART(mm,
                      dbo.viewPayFlow_UniqueTransactions.ts_added), DATEPART(yyyy, dbo.viewPayFlow_UniqueTransactions.ts_added), dbo.tblDealers.DealerID, dbo.tblDealers.DealerName,
                      dbo.tblRatePlans.rate_plan, dbo.viewPayFlow_UniqueTransactions.amt, dbo.viewPayFlow_UniqueTransactions.amt * (dbo.tblAffiliatePayouts.payout_pct_external / 100),
                      dbo.tblDealersBilling.status, dbo.viewPayFlow_UniqueTransactions.respmsg, dbo.viewPayFlow_UniqueTransactions.result, dbo.tblPayFlowResultCodes.pf_respmsg,
                      dbo.viewPayFlow_UniqueTransactions.ts_added
ORDER BY dbo.tblAffiliates.AffiliateID, DATEPART(yyyy, dbo.viewPayFlow_UniqueTransactions.ts_added) DESC, DATEPART(mm, dbo.viewPayFlow_UniqueTransactions.ts_added)






