	SELECT
		LoanAppID						= Applicants.LoanAppID,
		Applicants						= MAX(Applicants.Applicants),
		ApplicantID_Primary				= MAX(Applicants.ApplicantID_Primary),
		ApplicantID_Secondary			= MAX(Applicants.ApplicantID_Secondary),
		AAddressID_Primary				= MAX(Applicant_Address_Primary.LoanApp_CurrAddresID),
		AddressID_Secondary				= MAX(Applicant_Address_Secondary.LoanApp_CurrAddresID)
	FROM 
					viewApplication_Applicants_Inner_Inner	Applicants						WITH (NOLOCK)
		LEFT JOIN	tblLoanApp_CurrAddress					Applicant_Address_Primary		WITH (NOLOCK) ON Applicant_Address_Primary.LoanApp_ApplicantID		= Applicants.ApplicantID_Primary
		LEFT JOIN	tblLoanApp_CurrAddress					Applicant_Address_Secondary		WITH (NOLOCK) ON Applicant_Address_Secondary.LoanApp_ApplicantID	= Applicants.ApplicantID_Secondary
	--WHERE
		--Applicants.LoanAppID = 1946835
	GROUP BY
		Applicants.LoanAppID



