/****** Object:  View dbo.viewAssignedLenderAgents    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE VIEW viewAssignedLenderAgents AS 
SELECT 
	TLDR.LenderID,
	TLDR.DealerID,
	ISNULL(LBL.fullname,LL.fullname) AS LenderAgent,
	LBL.fullname AS LenderBranchAgent,
	TLDR.LenderAgentID,
	TLDR.LenderBranchAgentID
FROM tblLenderDealerRelation TLDR WITH (NOLOCK)
LEFT JOIN tblLendersLogins LL WITH (NOLOCK) ON (LL.LendersLoginID=TLDR.LenderAgentID)
LEFT JOIN tblLendersBranchLogins LBL WITH (NOLOCK) ON (LBL.LendersBranchLoginID=TLDR.LenderBranchAgentID)
