/****** Object:  View dbo.viewAutomationLenders    Script Date: 7/31/2024 12:57:20 PM ******/
--SELECT TABLE_NAME, COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WITH (NOLOCK) WHERE TABLE_NAME IN ('tblLenders', 'tblLendersBranches') AND COLUMN_NAME LIKE '%AUTO%'
/*
	SELECT
		LenderStatus,
		COUNT(*)
	FROM	
		tblLenders		Lender		WITH (NOLOCK)
	GROUP BY
		LenderStatus
	ORDER BY
		COUNT(*) DESC;

	RETURN;
*/

CREATE VIEW viewAutomationLenders AS
	SELECT
		Lender.LenderID,
		Lender.LenderName,
		CreditProvider = ISNULL(NULLIF(AUTOMATION_CREDIT_PROVIDER, ''), 'EX'),
		Count(Program.ProgramID) as AutomatedProgramCount


	FROM
				tblLenders			Lender			WITH (NOLOCK)
		JOIN	tblPrograms			Program			WITH (NOLOCK) ON Program.LenderID	= Lender.LenderID		AND	
																	 Program.Active		= 1						AND
																	 Program.Automated	= 1
	WHERE
		Lender.LenderStatus IN ('ACTIVE', 'TRIAL_30')
	GROUP BY
		Lender.LenderID,
		Lender.LenderName,
		Lender.Automation_Credit_Provider

