/****** Object:  View dbo.viewB2B_BidFundingStatusEX    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE VIEW viewB2B_BidFundingStatusEX AS
	SELECT
		LoanAppID						= Bid.LoanAppID,
		LoanApp_BidID					= Bid.LoanApp_BidID,
		LoanApp_BidID_Original			= Bid_Original.LoanApp_BidID,
		LenderID						= Branch.LenderID,
		Lender							= UPPER(Lender.LenderName),
		LendersBranchID					= Branch.LendersBranchID,
		DealerID						= Dealer.DealerID,
		Dealer							= UPPER(Dealer.DealerName),
		LoanApp_WorksheetID				= Worksheet.LoanApp_WorksheetID,
		UnderwritingID					= Underwriting.UnderwritingID,

		Loan_Term						= CONVERT(INTEGER, CASE
			WHEN Underwriting.Funding_Term		IS NOT NULL										AND ISNULL(CONVERT(INTEGER, Underwriting.Funding_Term),	0)	>	0	THEN CONVERT(INTEGER, Underwriting.Funding_Term)
			WHEN Bid_Funded.Term				IS NOT NULL AND ISNUMERIC(Bid_Funded.Term)					= 1	AND ISNULL(CONVERT(INTEGER, Bid_Funded.Term),			0)	>	0	THEN CONVERT(INTEGER, Bid_Funded.Term)
			WHEN Bid_Offer.Term 					IS NOT NULL AND ISNUMERIC(Bid_Offer.Term)					= 1	AND ISNULL(CONVERT(INTEGER, Bid_Offer.Term),			0)	>	0	THEN CONVERT(INTEGER, Bid_Offer.Term)
			WHEN Bid.Term							IS NOT NULL AND ISNUMERIC(Bid.Term)							= 1	AND ISNULL(CONVERT(INTEGER, Bid.Term),					0)	>	0	THEN CONVERT(INTEGER, Bid.Term)
			WHEN Worksheet.LoanApp_WorksheetID		IS NOT NULL	AND Worksheet.Loan_Term_Requested	IS NOT NULL AND ISNUMERIC(Worksheet.Loan_Term_Requested)	= 1 AND ISNULL(CONVERT(INTEGER, Worksheet.Loan_Term_Requested), 0) > 0 THEN CONVERT(INTEGER, Worksheet.Loan_Term_Requested)
			WHEN Application.Loan_Term_Requested	IS NOT NULL AND ISNUMERIC(Application.Loan_Term_Requested)	= 1 AND ISNULL(CONVERT(INTEGER, Application.Loan_Term_Requested), 0) > 0 THEN CONVERT(INTEGER, Application.Loan_Term_Requested)
			ELSE NULL END),

		Loan_Term_Source				= CONVERT(VARCHAR(32), CASE
			WHEN Underwriting.Funding_Term		IS NOT NULL										AND ISNULL(CONVERT(INTEGER, Underwriting.Funding_Term),	0)	>	0	THEN 'FUNDING'
			WHEN Bid_Funded.Term				IS NOT NULL AND ISNUMERIC(Bid_Funded.Term)	= 1	AND ISNULL(CONVERT(INTEGER, Bid_Funded.Term),			0)	>	0	THEN 'BID_FUNDED'
			WHEN Bid_Offer.Term 				IS NOT NULL AND ISNUMERIC(Bid_Offer.Term)	= 1	AND ISNULL(CONVERT(INTEGER, Bid_Offer.Term),			0)	>	0	THEN 'BID_OFFER'
			WHEN Bid.Term						IS NOT NULL AND ISNUMERIC(Bid.Term)			= 1	AND ISNULL(CONVERT(INTEGER, Bid.Term),					0)	>	0	THEN 'BID'
			WHEN Worksheet.LoanApp_WorksheetID	IS NOT NULL	AND Worksheet.Loan_Term_Requested	IS NOT NULL AND ISNUMERIC(Worksheet.Loan_Term_Requested)	= 1 AND ISNULL(CONVERT(INTEGER, Worksheet.Loan_Term_Requested), 0) > 0 THEN 'WORKSHEET'
			WHEN Application.Loan_Term_Requested	IS NOT NULL AND ISNUMERIC(Application.Loan_Term_Requested)	= 1 AND ISNULL(CONVERT(INTEGER, Application.Loan_Term_Requested), 0) > 0 THEN 'APPLICATION'
			ELSE NULL END),

		Loan_Amount						= CONVERT(MONEY, CASE
			WHEN ISNULL(Underwriting.Funding_Financed_Amount,	0)	>	0																						THEN CONVERT(MONEY, Underwriting.Funding_Financed_Amount)
			WHEN ISNULL(Bid_Funded.Financing_Amount,			0)	>	0																						THEN CONVERT(MONEY, Bid_Funded.Financing_Amount)
			WHEN ISNULL(Bid_Offer.Financing_Amount,				0)	>	0																						THEN CONVERT(MONEY, Bid_Offer.Financing_Amount)
			WHEN ISNULL(Bid.Financing_Amount,					0)	>	0																						THEN CONVERT(MONEY, Bid.Financing_Amount)
			WHEN ISNULL(Worksheet.Loan_Total_Loan_Amount,		0)	>	0																						THEN CONVERT(MONEY, Worksheet.Loan_Total_Loan_Amount)
			WHEN ISNULL(Application.Loan_Total_Loan_Amount,		0)	>	0																						THEN CONVERT(MONEY, Application.Loan_Total_Loan_Amount)
			ELSE NULL END),

		Loan_Amount_Source				= CONVERT(VARCHAR(32), CASE
			WHEN ISNULL(Underwriting.Funding_Financed_Amount,	0)	>	0																						THEN 'FUNDING'
			WHEN ISNULL(Bid_Funded.Financing_Amount,			0)	>	0																						THEN 'BID_FUNDED'
			WHEN ISNULL(Bid_Offer.Financing_Amount,				0)	>	0																						THEN 'BID_OFFER'
			WHEN ISNULL(Bid.Financing_Amount,					0)	>	0																						THEN 'BID'
			WHEN ISNULL(Worksheet.Loan_Total_Loan_Amount,		0)	>	0																						THEN 'WORKSHEET'
			WHEN ISNULL(Application.Loan_Total_Loan_Amount,		0)	>	0																						THEN 'APPLICATION'
			ELSE NULL END),

		Loan_Payment					= CONVERT(MONEY, CASE
			WHEN ISNULL(Underwriting.Funding_Monthly_Payment,	0)	>	0																						THEN CONVERT(MONEY, Underwriting.Funding_Monthly_Payment)
			WHEN ISNULL(Bid_Funded.Payment,						0)	>	0																						THEN CONVERT(MONEY, Bid_Funded.Payment)
			WHEN ISNULL(Bid_Offer.Payment,						0)	>	0																						THEN CONVERT(MONEY, Bid_Offer.Payment)
			WHEN ISNULL(Bid.Payment,							0)	>	0																						THEN CONVERT(MONEY, Bid.Payment)
			WHEN ISNULL(Worksheet.Loan_Estimated_Payment,		0)	>	0																						THEN CONVERT(MONEY, Worksheet.Loan_Estimated_Payment)
			WHEN ISNULL(Application.Loan_Estimated_Payment,		0)	>	0																						THEN CONVERT(MONEY, Application.Loan_Estimated_Payment)
			ELSE NULL END),

		Loan_Payment_Source				= CONVERT(VARCHAR(32), CASE
			WHEN ISNULL(Underwriting.Funding_Monthly_Payment,	0)	>	0																						THEN 'FUNDING'
			WHEN ISNULL(Bid_Funded.Payment,						0)	>	0																						THEN 'BID_FUNDED'
			WHEN ISNULL(Bid_Offer.Payment,						0)	>	0																						THEN 'BID_OFFER'
			WHEN ISNULL(Bid.Payment,							0)	>	0																						THEN 'BID'
			WHEN ISNULL(Worksheet.Loan_Estimated_Payment,		0)	>	0																						THEN 'WORKSHEET'
			WHEN ISNULL(Application.Loan_Estimated_Payment,		0)	>	0																						THEN 'APPLICATION'

			ELSE NULL END),

		--Underwriting.*,
		Underwriting.Funding_Monthly_Payment,

		Loan_Rate						= CONVERT(DECIMAL(10, 2), CASE
			WHEN DBO.CMoney(CONVERT(VARCHAR(20), Underwriting.Funding_Rate),	-1)	>	0																		THEN DBO.CMoney(CONVERT(VARCHAR(20), Underwriting.Funding_Rate), -1)
			WHEN DBO.CMoney(Underwriting.Interest,								-1)	>	0																		THEN DBO.CMoney(Underwriting.Interest, -1)
			WHEN DBO.CMoney(Bid_Funded.Rate,									-1)	>	0																		THEN DBO.CMoney(Bid_Funded.Rate, -1)
			WHEN DBO.CMoney(Bid_Offer.Rate,										-1)	>	0																		THEN DBO.CMoney(Bid_Offer.Rate, -1)
			WHEN DBO.CMoney(Bid.Rate,											-1)	>	0																		THEN DBO.CMoney(Bid.Rate, -1)
			ELSE NULL END),

		Loan_Rate_Source				= CONVERT(VARCHAR(20), CASE
			WHEN DBO.CMoney(CONVERT(VARCHAR(20), Underwriting.Funding_Rate),	-1)	>	0																		THEN 'FUNDING'
			WHEN DBO.CMoney(Underwriting.Interest,								-1)	>	0																		THEN 'FUNDING_INTEREST'
			WHEN DBO.CMoney(Bid_Funded.Rate,									-1)	>	0																		THEN 'BID_FUNDED'
			WHEN DBO.CMoney(Bid_Offer.Rate,										-1)	>	0																		THEN 'BID_OFFER'
			WHEN DBO.CMoney(Bid.Rate,											-1)	>	0																		THEN 'BID'
			ELSE NULL END),

		Funded_Date						= CASE
			WHEN Bid_Funded.Funded_Date				IS NULL	AND	BFS_Funded.StatusDateTime	IS NULL															THEN	NULL
			WHEN Bid_Funded.Funded_Date				IS NULL																									THEN	BFS_Funded.StatusDateTime
			WHEN 												BFS_Funded.StatusDateTime	IS NULL															THEN	Bid_Funded.Funded_Date
			WHEN Bid_Funded.Funded_Date				>=			BFS_Funded.StatusDateTime																	THEN	Bid_Funded.Funded_Date
			ELSE BFS_Funded.StatusDateTime END,

		Funded_Date_Source				= CONVERT(VARCHAR(20), CASE
			WHEN Bid_Funded.Funded_Date				IS		NULL		AND	BFS_Funded.StatusDateTime		IS		NULL									THEN	NULL
			WHEN Bid_Funded.Funded_Date				IS		NULL		AND BFS_Funded.StatusDateTime		IS	NOT	NULL									THEN	'BFS_FUNDED'
			WHEN Bid_Funded.Funded_Date				IS	NOT	NULL		AND	BFS_Funded.StatusDateTime		IS		NULL									THEN	'BID_FUNDED'
			WHEN Bid_Funded.Funded_Date				>=					BFS_Funded.StatusDateTime															THEN	'BID_FUNDED'
																																							ELSE	'BFS_FUNDED'	END	),
		BidFundingStatus 				= CASE
			WHEN BFS_Funded.StatusDateTime	IS NOT NULL	THEN	'FUNDED'
			WHEN BFS_Rejected.StatusDateTime	IS NOT NULL	THEN	'REJECTED'
			WHEN BFS_Received.StatusDateTime	IS NOT NULL	THEN	'RECEIVED'
			WHEN Bid_Funded.Funded_Date				IS NOT NULL	THEN	'FUNDED'
			ELSE '' END,

		LastStatus_UpdateDateTime		= CASE
			WHEN BFS_Funded.StatusDateTime	IS NOT NULL	AND	LastStatus.UpdateDateTime IS NOT NULL	AND BFS_Funded.StatusDateTime		>= LastStatus.UpdateDateTime	THEN BFS_Funded.StatusDateTime
			WHEN BFS_Rejected.StatusDateTime	IS NOT NULL	AND	LastStatus.UpdateDateTime IS NOT NULL	AND BFS_Rejected.StatusDateTime	>= LastStatus.UpdateDateTime	THEN BFS_Rejected.StatusDateTime
			WHEN BFS_Received.StatusDateTime	IS NOT NULL	AND	LastStatus.UpdateDateTime IS NOT NULL	AND BFS_Received.StatusDateTime	>= LastStatus.UpdateDateTime	THEN BFS_Received.StatusDateTime
			WHEN 													LastStatus.UpdateDateTime IS NOT NULL																			THEN LastStatus.UpdateDateTime
			WHEN Bid_Funded.UpdateDateTime			IS NOT NULL		THEN Bid_Funded.UpdateDateTime
			ELSE Bid.UpdateDateTime END,

		StatusUpdateDateTime 			= CASE
			WHEN BFS_Funded.StatusDateTime	IS NOT NULL	THEN	BFS_Funded.StatusDateTime
			WHEN BFS_Rejected.StatusDateTime	IS NOT NULL	THEN	BFS_Rejected.StatusDateTime
			WHEN BFS_Received.StatusDateTime	IS NOT NULL	THEN	BFS_Received.StatusDateTime
			ELSE NULL END,

		StatusUpdateUser 				= ISNULL(CASE
			WHEN BFS_Funded.StatusUser	IS NOT NULL	THEN	BFS_Funded.StatusUser
			WHEN BFS_Rejected.StatusUser	IS NOT NULL	THEN	BFS_Rejected.StatusUser
			WHEN BFS_Received.StatusUser	IS NOT NULL	THEN	BFS_Received.StatusUser
			ELSE '' END, ''),

		LastSent_Date					= (SELECT	MAX(LS.FundingSent)	FROM
						tblLoanApp_Bids_LastStatus		LS				WITH (NOLOCK)
				JOIN	tblLoanApp_Bids					Bid_Inner		WITH (NOLOCK) ON Bid_Inner.LoanAppID			= Bid.LoanAppID					AND Bid_Inner.LoanApp_BidID = LS.LoanApp_BidID
				JOIN	tblLendersBranches				Branch_Inner	WITH (NOLOCK) ON Branch_Inner.LendersBranchID	= Bid_Inner.LendersBranchID		AND Branch_Inner.LenderID	= Lender.LenderID),

		Funding							= CONVERT(BIT, CASE
			WHEN LastStatus.FundingSent			IS NOT NULL		THEN	1
			WHEN BFS_Funded.LoanApp_BidID		IS NOT NULL		THEN	1
			WHEN BFS_Rejected.LoanApp_BidID		IS NOT NULL		THEN	1
			WHEN BFS_Received.LoanApp_BidID		IS NOT NULL		THEN	1
			WHEN Bid_Funded.LoanApp_BidID		IS NOT NULL		THEN	1
			ELSE 0 END),

		Funding_Source					= CONVERT(VARCHAR(20), CASE
			WHEN LastStatus.FundingSent			IS NOT NULL		THEN	'LAST_STATUS'
			WHEN BFS_Funded.LoanApp_BidID		IS NOT NULL		THEN	'BFS_FUNDED'
			WHEN BFS_Rejected.LoanApp_BidID		IS NOT NULL		THEN	'BFS_REJECTED'
			WHEN BFS_Received.LoanApp_BidID		IS NOT NULL		THEN	'BFS_RECEIVED'
			WHEN Bid_Funded.LoanApp_BidID		IS NOT NULL		THEN	'BID_FUNDED'
			ELSE '' END),

		PreFunding						= CONVERT(BIT, CASE
			WHEN BFS_Funded.LoanApp_BidID		IS NOT NULL		THEN	0
			WHEN BFS_Rejected.LoanApp_BidID		IS NOT NULL		THEN	1
			WHEN BFS_Received.LoanApp_BidID		IS NOT NULL		THEN	1	
			WHEN Bid_Funded.LoanApp_BidID		IS NOT NULL		THEN	1
			ELSE 0 END),		

		PreFunding_Source				= CONVERT(VARCHAR(20), CASE
			WHEN BFS_Funded.LoanApp_BidID		IS NOT NULL		THEN	'BFS_FUNDED'
			WHEN BFS_Rejected.LoanApp_BidID		IS NOT NULL		THEN	'BFS_REJECTED'
			WHEN BFS_Received.LoanApp_BidID		IS NOT NULL		THEN	'BFS_RECEIVED'
			WHEN Bid_Funded.LoanApp_BidID		IS NOT NULL		THEN	'BID_FUNDED'
			ELSE '' END),		

		Funded							= CONVERT(  BIT, CASE
			WHEN BFS_Funded.LoanApp_BidID		IS NOT NULL		THEN	1
			WHEN Bid_Funded.LoanApp_BidID		IS NOT NULL		THEN	1
			ELSE 0 END),

		Funded_Source					= CONVERT(VARCHAR(20), CASE
			WHEN BFS_Funded.LoanApp_BidID		IS NOT NULL		THEN	'BFS_FUNDED'
			WHEN Bid_Funded.LoanApp_BidID		IS NOT NULL		THEN	'BID_FUNDED'
			ELSE '' END),

		Received_StatusDate				= BFS_Received.StatusDateTime,
		Received_StatusUser				= ISNULL(BFS_Received.StatusUser,							''	),
		Received_LoanApp_BidID			= BFS_Received.LoanApp_BidID,

		Rejected_StatusDate				= BFS_Rejected.StatusDateTime,
		Rejected_StatusUser				= ISNULL(BFS_Rejected.StatusUser,							''	),
		Rejected_LoanApp_BidID			= BFS_Rejected.LoanApp_BidID,

		Funded_StatusDate				= BFS_Funded.StatusDateTime,
		Funded_StatusUser				= ISNULL(BFS_Funded.StatusUser,							''	),
		Funded_LoanApp_BidID			= BFS_Funded.LoanApp_BidID

	FROM
						tblLoanApp_Bids							Bid						WITH (NOLOCK)
				JOIN	tblLoanApps								Application				WITH (NOLOCK)		ON Application.LoanAppID		= Bid.LoanAppID
				JOIN	tblDealers								Dealer					WITH (NOLOCK)		ON Dealer.DealerID				= Application.DealerID
				JOIN	tblLendersBranches						Branch					WITH (NOLOCK)		ON Branch.LendersBranchID		= Bid.LendersBranchID
				JOIN	tblLenders								Lender					WITH (NOLOCK)		ON Lender.LenderID				= Branch.LenderID

				JOIN	tblLoanApp_Bids							Bid_Original			WITH (NOLOCK)		ON Bid_Original.LoanAppID		= Bid.LoanAppID				AND Bid_Original.LoanApp_BidID	IN	(SELECT MIN(LoanApp_BidID)	FROM tblLoanApp_Bids	Bid_Inner	WITH (NOLOCK) WHERE Bid_Inner.LoanAppID = Bid.LoanAppID 													AND Bid_Inner.LendersBranchID	IN (SELECT LendersBranchID FROM tblLendersBranches Branch_Inner WITH (NOLOCK) WHERE Branch_Inner.LenderID = Lender.LenderID)	)

		LEFT	JOIN	tblLoanApp_Bids							Bid_Funded				WITH (NOLOCK)		ON Bid_Funded.LoanAppID			= Bid.LoanAppID				AND Bid_Funded.LoanApp_BidID	IN	(SELECT MAX(LoanApp_BidID)	FROM tblLoanApp_Bids	Bid_Inner	WITH (NOLOCK) WHERE Bid_Inner.LoanAppID = Bid.LoanAppID AND Bid_Inner.Funded_Date			IS NOT NULL		AND Bid_Inner.LendersBranchID	IN (SELECT LendersBranchID FROM tblLendersBranches Branch_Inner WITH (NOLOCK) WHERE Branch_Inner.LenderID = Lender.LenderID)	)
		LEFT	JOIN	tblLoanApp_Bids							Bid_Offer				WITH (NOLOCK)		ON Bid_Offer.LoanAppID			= Bid.LoanAppID				AND Bid_Offer.LoanApp_BidID		IN	
			(SELECT TOP 1 LoanApp_BidID	FROM tblLoanApp_Bids	Bid_Inner				WITH (NOLOCK) 
				WHERE
						Bid_Inner.LoanAppID				=	Bid.LoanAppID
					AND	ISNULL(Bid_Inner.Payment, 0)	> 	0
					AND LEN(ISNULL(Bid_Inner.Rate, ''))	>	0
					AND Bid_Inner.LendersBranchID		IN	(SELECT LendersBranchID FROM tblLendersBranches Branch_Inner WITH (NOLOCK) WHERE Branch_Inner.LenderID = Lender.LenderID) ORDER BY Bid_Inner.Offer_Date DESC)

		LEFT	JOIN	tblLoanApp_Worksheet					Worksheet				WITH (NOLOCK)		ON Worksheet.LoanApp_BidID		= Bid.LoanApp_BidID			AND Worksheet.Active			=	1
		LEFT	JOIN	tblLoanApp_Underwriting					Underwriting			WITH (NOLOCK)		ON Underwriting.LoanAppID		= Bid.LoanAppID				AND Underwriting.LenderID		=	Lender.LenderID
		LEFT	JOIN	tblLoanApp_Bids_LastStatus				LastStatus 				WITH (NOLOCK)		ON Bid.LoanApp_BidID			= LastStatus.LoanApp_BidID

		LEFT	JOIN	viewBidFundingStatus					BFS_Received			WITH (NOLOCK)		ON BFS_Received.LoanAppID		= Bid.LoanAppID				AND	BFS_Received.LenderID		=	Lender.LenderID	AND	BFS_Received.FundingStatus	= 'RECEIVED'
		LEFT	JOIN	viewBidFundingStatus					BFS_Funded				WITH (NOLOCK)		ON BFS_Funded.LoanAppID			= Bid.LoanAppID				AND	BFS_Funded.LenderID			=	Lender.LenderID	AND	BFS_Funded.FundingStatus		= 'FUNDED'
		LEFT	JOIN	viewBidFundingStatus					BFS_Rejected			WITH (NOLOCK)		ON BFS_Rejected.LoanAppID		= Bid.LoanAppID				AND	BFS_Rejected.LenderID		=	Lender.LenderID	AND	BFS_Rejected.FundingStatus	= 'REJECTED'
	WHERE
		Bid.LoanApp_BidID	= ISNULL(Bid_Funded.LoanApp_BidID, ISNULL(BFS_Funded.LoanApp_BidID, ISNULL(BFS_Rejected.LoanApp_BidID, ISNULL(BFS_Received.LoanApp_BidID, -1))))
		--AND Underwriting.CreateDateTime >= '2014-01-01'
		--AND Bid.LoanAppID IN	(962006, 970706, 971613, 972936, 976414, 976892, 978607, 978979, 979951, 980922, 981057, 981716, 982008)


