/****** Object:  View dbo.viewB2B_Bid_StatusChanged    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW viewB2B_Bid_StatusChanged AS
	SELECT
		LoanApp_BidID	= BID.LoanApp_BidID,
		BidStatus		= BID.STATUS,
		StatusStatus	= STATUS.STATUS
	FROM
				tblLoanApp_Bids					BID 		WITH (NOLOCK)	
		JOIN	tblLoanApp_Bids_LastStatus		STATUS		WITH (NOLOCK) 		ON		(BID.LoanApp_BidID = STATUS.LoanApp_BidID)
	
	WHERE
		BID.CreateDateTime >= DATEADD(dd, -90, GETDATE())
		AND		(NOT BID.STATUS = STATUS.STATUS)
	





