/****** Object:  View dbo.viewB2B_BidsPendingToSend_FIFS    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewB2B_BidsPendingToSend_fifs AS

SELECT TOP 100 PERCENT--TOP 50
	APP.LoanAppID,
	LoanApp_BidID,
	APP.DealerID DealerID,
	LBFP.*,
	ReceiveResponseImmediate = ISNULL(INTERFACE.ReceiveResponseImmediate, 0),
	INTERFACE.PostURL,
	INTERFACE.PostUserName,
	INTERFACE.PostPassword,
	INTERFACE.PostSuccessfulIsXML,
	INTERFACE.PostSuccessfulMatchText,
	INTERFACE.PostSuccessfulQuery,
	INTERFACE.PostSuccessfulRemoteLoanNumber,
	INTERFACE.PostFailureIsXML,
	INTERFACE.PostFailureMatchText,
	INTERFACE.PostFailureQuery,
	INTERFACE.PostFailureErrorMessageQuery,
	MustHaveCustomerNumber = ISNULL(INTERFACE.MustHaveCustomerNumber, 0),
	SendNotificationMessageToLender = ISNULL(INTERFACE.SendNotificationMessageToLender, 0),
	DealerNotificationMessage = ISNULL(INTERFACE.DealerNotificationMessage, 'PUT MESSAGE HERE'),
	CustomerNumber = (SELECT CustomerNumber FROM tblLenderDealerRelation R WITH (NOLOCK) WHERE R.LenderID = BRANCH.LenderID AND R.DealerID = APP.DealerID),
	(SELECT COUNT(*) FROM tblLendersInterfacesFormFields WITH (NOLOCK) WHERE LendersInterfaceID=INTERFACE.LendersInterfaceID AND Active=1) PostFieldsCount

FROM
			tblLoanApps					APP		WITH (NOLOCK)
	JOIN	tblDealers					DEALER		WITH (NOLOCK) ON APP.DealerID = DEALER.DealerID
	JOIN	tblLoanApp_Bids				BID		WITH (NOLOCK) ON APP.LoanAppID = BID.LoanAppID
	JOIN	viewB2B_LenderBranchForPost LBFP	WITH (NOLOCK) ON BID.LendersBranchID = LBFP.LendersBranchID
	JOIN 	tblLendersInterfaces		INTERFACE		WITH (NOLOCK) ON INTERFACE.LendersInterfaceID = LBFP.LendersInterfaceID
	JOIN	tblLendersBranches			BRANCH		WITH (NOLOCK) ON BRANCH.LendersBranchID = BID.LendersBranchID

WHERE
		DateDiff(d, BID.UpdateDateTime, GetDate()) <=30
	AND BID.STATUS IN ('PENDING_B2B', 'PENDING_LENDER')
	AND BID.CANCELED_DATE IS NULL
	AND BID.LoanApp_BidID NOT IN (SELECT LoanApp_BidID FROM tblB2B_BidLastSent WITH (NOLOCK))
--AND NOT BRANCH.LenderID = 64

and bid.LendersBranchID IN (2462)

ORDER BY
	BID.UpdateDateTime




