/****** Object:  View dbo.viewB2B_Bids_UsingBeta_V3    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE  VIEW [dbo].[viewB2B_Bids_UsingBeta_V3] AS
	SELECT 
		LoanAppID			= Bids.LoanAppID,
		LoanApp_BidID		= Bids.LoanApp_BidID,
		Status				= Bids.Status,
		PartnerToolID		= PDE.PartnerToolID,
		Field				= PDE.Field,
		DataValue			= PDE.DataValue,
		Partner_LoanID_Name	= PDE.Field,
		Partner_LoanID		= PDE.DataValue,
		Pending_Lender		= Valid.Pending_Lender,
		Pending_Dealer		= Valid.Pending_Dealer,
		Term				= Valid.Term,
		Amount				= Valid.Amount,
		Payment				= Valid.Payment,
		Rate				= Valid.Rate
	FROM
					tblLoanApp_Bids					Bids	WITH (NOLOCK)
			JOIN	tblPartnerDataElement			PDE		WITH (NOLOCK) ON	PDE.LoanApp_BidID	= Bids.LoanApp_BidID		AND
																				PDE.PartnerToolID	= PDE.PartnerToolID
			JOIN	tblPartnerElementDefinition		PED		WITH (NOLOCK) ON	PED.PartnerToolID	= PDE.PartnerToolID			AND
																				PED.Field			= PDE.Field					AND
																				PED.Active			= 1							AND
																				PED.ValueType		= 'PARTNER_LOAN_ID'
			JOIN	viewBids_OfferIsValid			VALID	WITH (NOLOCK) ON	VALID.LoanApp_BidID	= Bids.LoanApp_BidID
--added viewB2B_Lenders_UsingBeta_V3 filter by partnertool because it generated multiple records if multiple lenders used V3 interface
--multiple records generated produced the following error:
--  Violation of PRIMARY KEY constraint 'PK__tblPartnerDecisi__1EF1D4A7'. Cannot insert duplicate key in object 'tblPartnerDecision_Receipt'.
	LEFT	JOIN	viewB2B_Lenders_UsingBeta_V3	V3		WITH (NOLOCK) ON	V3.LendersBranchID	= Bids.LendersBranchID AND 
																				V3.PartnerToolID = PDE.PartnerToolID
WHERE
		--Bids.CreateDateTime > '2016-12-28' AND
		Bids.Status				IN	('PENDING_DEALER', 'DECLINE_LENDER')			AND
		Valid.Pending_Lender	=	0												AND
		Valid.Pending_Dealer	=	1												AND
		(PDE.PartnerToolID		=	2 OR (V3.PartnerToolID IS NOT NULL AND V3.LenderID IS NOT NULL))


