/****** Object:  View dbo.viewB2B_CommentsOutstandingToSend_TEST_ROUTEONE    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE   VIEW viewB2B_CommentsOutstandingToSend_TEST_ROUTEONE AS
	SELECT TOP 0 --PERCENT
		PartnerToolID				= ELEMENT.PartnerToolID,
		PartnerCode					= PARTNER_TOOL.ShortName,
		LoanAppID					= BIDS.LoanAppID,
		LoanApp_BidID				= ELEMENT.LoanApp_BidID,
		Field						= ELEMENT.Field,
		DataValue					= ELEMENT.DataValue,
		LenderID					= BRANCH.LenderID,
		LendersBranchID				= BIDS.LendersBranchID,
		URL							= TRIGGER_SEND.URL,
		Username					= TRIGGER_SEND.Username,
		Password					= TRIGGER_SEND.Password,
		XML							= TRIGGER_SEND.XML
	FROM
					tblLoanApp_Bids 									BIDS 			WITH (NOLOCK)
		INNER JOIN	viewCommentLogLenderMessageDates					COMMENTS		WITH (NOLOCK) ON		COMMENTS.LoanApp_BidID			= BIDS.LoanApp_BidID
		INNER JOIN	tblLendersBranches									BRANCH			WITH (NOLOCK) ON		BRANCH.LendersBranchID			= BIDS.LendersBranchID
		INNER JOIN	tblPartnerDataElement 								ELEMENT 		WITH (NOLOCK) ON		BIDS.LoanApp_BidID				= ELEMENT.LoanApp_BidID 		

		INNER JOIN	tblPartnerElementDefinition 						DEFINITION 		WITH (NOLOCK) ON		DEFINITION.PartnerToolID		= ELEMENT.PartnerToolID
																											AND	DEFINITION.Field				= ELEMENT.Field					
																											AND	DEFINITION.ValueType 			= 'PARTNER_LOAN_ID'

		INNER JOIN	tblPartnerTools										PARTNER_TOOL	WITH (NOLOCK) ON		ELEMENT.PartnerToolID			= PARTNER_TOOL.PartnerToolID
		INNER JOIN	tblPartnerToolsTriggers								TRIGGER_SEND 	WITH (NOLOCK) ON		TRIGGER_SEND.PartnerToolID		= ELEMENT.PartnerToolID
																											AND TRIGGER_SEND.TYPE				= 'SEND_MESSAGING'

		 LEFT JOIN	tblPartnerDataElement								PDE_SEND		WITH (NOLOCK) ON		PDE_SEND.LoanApp_BidID			= BIDS.LoanApp_BidID
																											AND	PDE_SEND.PartnerToolID			= PARTNER_TOOL.PartnerToolID
																											AND PDE_SEND.Field					= 'LastSentDateTime'

		 LEFT JOIN	viewB2B_DecisionsOutstandingToSend_TEST_ROUTEONE	TO_SEND			WITH (NOLOCK) ON		TO_SEND.LoanApp_BidID			= BIDS.LoanApp_BidID
	WHERE
					TO_SEND.LoanApp_BidID					IS		NULL
		AND 		Element.PartnerToolID					=		12
		AND			COMMENTS.Newest							>=		'2014-07-01'
		AND	(		ISDATE(PDE_SEND.DataValue)				=		0
				OR	DBO.StripToDate(PDE_SEND.DataValue)		<		DBO.StripToDate(COMMENTS.Newest))

		AND Bids.LoanApp_BidID NOT IN(1217209)

		--		AND BIDS.LoanApp_BidID NOT IN (SELECT LoanApp_BidID FROM viewB2B_DecisionsOutstandingToSend_TEST_ROUTEONE WITH (NOLOCK))
	ORDER BY
		COMMENTS.Newest



GO

