/****** Object:  View dbo.viewB2B_DealerTrack_OutstandingFunding_2013_02_06    Script Date: 7/31/2024 12:57:20 PM ******/




CREATE VIEW viewB2B_DealerTrack_OutstandingFunding_2013_02_06 AS
 SELECT --TOP 100 PERCENT
 DISTINCT
  LoanAppID   = BID.LoanAppID,
  LoanApp_BidID  = BID.LoanApp_BidID,
  ApplicationID  = LTRIM(STR(BID.LoanAppID)) + '-' + LTRIM(STR(BID.LoanApp_BidID)),
  Vehicle    = UPPER(BID.Vehicle),
  Applicants   = UPPER(BID.Applicant_Names),
  Status    = UPPER(BID.Status),
  DealerID   = BID.DealerID,
  Dealer    = UPPER(Bid.Dealer),
  DateFunded   = BID.Funded_Date,
  LenderID   = BID.LenderID,
  LendersBranchID  = BID.LendersBranchID,
  LenderName   = UPPER(BID.LenderName),
  LastUpdate   = ISNULL(LAST_SENT.UpdateDateTime, CONVERT(dateTime, '2011-01-01')),
  PartnerToolID  = TOOL.PartnerToolID,
  PostURL    = PARAMETERS.PostURL,
  PostUser   = PARAMETERS.PostUser,
  PostPassword  = PARAMETERS.PostPassword,
  PullURL    =
   'https://www.CreditSmarts.com/CreditSmarts/v2/Partners/Outbound.asp?LoanAppID=' +
   LTRIM(STR(BID.LoanAppID)) +
   '&BidID=' + LTRIM(STR(BID.LoanApp_BidID)) +
   '&Native=1'
 
 FROM
  view_LoanApps_Bids      BID   WITH (NOLOCK)
 
  INNER JOIN tblLoanApp_Bids_LastStatus LAST_SENT WITH (NOLOCK)
   ON BID.LoanApp_BidID = LAST_SENT.LoanApp_BidID
 
  INNER JOIN tblPartnerTools    TOOL  WITH (NOLOCK)
   ON BID.PartnerName = TOOL.Shortname
 
  INNER JOIN viewB2B_LenderPartnerParameters PARAMETERS WITH (NOLOCK)
   ON  TOOL.PartnerToolID = PARAMETERS.PartnerToolID
    AND PARAMETERS.LendersBranchID = BID.LendersBranchID
  INNER JOIN tblLoanApp_BidFundingStatus BFS WITH (NOLOCK)
	ON BFS.LoanApp_BidID = BID.LoanApp_BidID
 
 WHERE
   BID.CreateDateTime > '2012-01-01'
  AND BID.PartnerName='DEALERTRACK'
  AND LEN(RTRIM(LTRIM(ISNULL(PARAMETERS.PostURL, '')))) > 0
  AND LEN(RTRIM(LTRIM(ISNULL(PARAMETERS.PostUser, '')))) > 0
  AND LEN(RTRIM(LTRIM(ISNULL(PARAMETERS.PostPassword, '')))) > 0
  AND TOOL.Active = 1 
  AND ((BID.FUNDED_DATE IS NOT NULL AND BID.Funded_Date > CONVERT(datetime, '2012-01-01')) OR BFS.BidFundingStatus in ('RECEIVED', 'REJECTED'))
  AND (LAST_SENT.FundingSent IS NULL OR BID.Funded_Date > LAST_SENT.FundingSent)
  AND BID.STATUS NOT IN ('DECLINE_LENDER')
-- ORDER BY
--  BID.FUNDED_DATE DESC







