/****** Object:  View dbo.viewB2B_DealerTrack_OutstandingFunding_NEW_TEST    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW viewB2B_DealerTrack_OutstandingFunding_NEW_TEST AS
	SELECT TOP 100 PERCENT 

		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		ApplicationID			= LTRIM(STR(Bid.LoanAppID)) + '-' + LTRIM(STR(Bid.LoanApp_BidID)),
		Vehicle					= CASE WHEN Worksheet.LoanApp_WorksheetID IS NULL THEN DBO.VehicleDescription(Application.Vehicle_Year, Application.Vehicle_Make, Application.Vehicle_Model, Application.Vehicle_Mileage, Application.Vehicle_VIN) ELSE DBO.VehicleDescription(Worksheet.Vehicle_Year, Worksheet.Vehicle_Make, Worksheet.Vehicle_Model, Worksheet.Vehicle_Mileage, Worksheet.Vehicle_VIN) END,
		Applicants				= UPPER(Application.Applicant_Names),
		Status					= UPPER(Bid.Status),
		DealerID				= Dealer.DealerID,
		Dealer					= UPPER(Dealer.DealerName),
		DateFunded				= Bid.Funded_Date,
		BidFundingStatus		= ISNULL(BFS.FundingStatus, ''),
		LenderID				= Branch.LenderID,
		LendersBranchID			= Bid.LendersBranchID,
		LenderName				= UPPER(Lender.LenderName),
		LastSent				= BLS.FundingSent,
		LastUpdate				= ISNULL(BLS.UpdateDateTime, CONVERT(dateTime, '2011-01-01')),
		LastFundingStatus		= BFS.StatusDateTime,
		PartnerToolID			= PartnerTool.PartnerToolID,
		PostURL					= ToolParameters.PostURL,
		PostUser				= ToolParameters.PostUser,
		PostPassword			= ToolParameters.PostPassword,
		PullURL					= 'https://www.CreditSmarts.com/CreditSmarts/v2/Partners/Outbound2.asp?Nocache=1&cache=0&Native=1&LoanAppID=' + LTRIM(STR(Bid.LoanAppID)) + '&BidID=' + LTRIM(STR(Bid.LoanApp_BidID))
	FROM
								tblLoanApp_Bids						Bid					WITH (NOLOCK)
						JOIN	tblLendersBranches					Branch				WITH (NOLOCK) ON Branch.LendersBranchID		= Bid.LendersBranchID
						JOIN	tblLoanApps							Application			WITH (NOLOCK) ON Application.LoanAppID				= Bid.LoanAppID
						JOIN	tblLenders							Lender				WITH (NOLOCK) ON Lender.LenderID					= Branch.LenderID
						JOIN	tblDealers							Dealer				WITH (NOLOCK) ON Dealer.DealerID					= Application.DealerID
						--JOIN	tblPartnerDataElement				PDE					WITH (NOLOCK) ON PDE.PartnerToolID			= 2						AND	PDE.LoanApp_BidID	= Bid.LoanApp_BidID	AND	PDE.Field = 'dt_app_id'
						JOIN	tblPartnerTools						PartnerTool			WITH (NOLOCK) ON PartnerTool.Shortname				= 'DealerTRACK'
						JOIN	tblLoanApp_Underwriting				UW					WITH (NOLOCK) ON UW.LoanAppID				= Bid.LoanAppID		AND UW.LenderID			= Branch.LenderID
						JOIN	viewB2B_LenderPartnerParametersEx 	ToolParameters		WITH (NOLOCK) ON PartnerTool.PartnerToolID			= ToolParameters.PartnerToolID		AND	ToolParameters.LendersBranchID = Bid.LendersBranchID
				LEFT	JOIN	tblLoanApp_Bids_LastStatus			BLS					WITH (NOLOCK) ON BLS.LoanApp_BidID			= Bid.LoanApp_BidID
				LEFT	JOIN	viewBidFundingStatus				BFS					WITH (NOLOCK) ON BFS.LoanApp_BidID			= Bid.LoanApp_BidID
				LEFT	JOIN	tblLoanApp_Worksheet				Worksheet			WITH (NOLOCK) ON Worksheet.LoanApp_BidID			= Bid.LoanApp_BidID					AND Worksheet.Active		= 1

	WHERE
			(		Bid.Funded_Date			IS NOT	NULL		OR	NULLIF(BFS.FundingStatus, '')	IS NOT			NULL)
		--AND	(		BLS.UpdateDateTime		IS		NULL		OR	BLS.UpdateDateTime							>=	DATEADD(d, -60, GETDATE()	))

		AND	((		Bid.Funded_Date			IS 		NULL		OR	Bid.Funded_Date								>=	DATEADD(d, -60, GETDATE()	))
		AND (		BFS.StatusDateTime		IS		NULL		OR	BFS.StatusDateTime							>=	DATEADD(d, -60, GETDATE()	)) OR Bid.LoanApp_BidID=767734)
		AND (		BLS.FundingSent			IS		NULL
			  OR  (	Bid.Funded_Date			IS NOT	NULL		AND	Bid.Funded_Date			>=	BLS.FundingSent	)
			  OR  (	Bid.Funded_Date			IS		NULL		AND BFS.StatusDateTime		IS NOT	NULL		AND BFS.StatusDateTime	>=	BLS.FundingSent AND BFS.StatusDateTime > '2014-02-01'	) )
		AND		Bid.Status NOT IN ('DECLINE_LENDER')
		AND		Bid.LoanApp_BidID IN(SELECT LoanApp_BidID FROM tblPartnerDataElement WITH (NOLOCK) WHERE PartnerToolID = 2)
	ORDER BY
		Bid.Funded_Date DESC,
		BFS.StatusDateTime DESC
--	OPTION		(MAXDOP 1)






GO

