/****** Object:  View dbo.viewB2B_DecisionsOutstandingToSend_Other    Script Date: 7/31/2024 12:57:20 PM ******/



-- |             1 |    AUL          |
-- |             2 |    DEALERTRACK  |
-- |             3 |    SECURETRANS  |
-- |             4 |    STRANS_TEST  |
-- |             5 |    KBB          |
-- |             6 |    NADA         |
-- |             7 |    BLACK_BOOK   |
-- |             8 |    LENDINGTREE  |
-- |             9 |    Internal     |
-- |            10 |    CreditSmarts |
-- |            11 |    LES          |
-- |            12 |    RouteOne     |
-- |            13 |    CARLETON     |
-- |            14 |    GAP          |
-- |            18 |    HarlandFS    |
-- |            19 |    ZM           |
-- |            20 |    BLUEYIELD_L  |
-- |            21 |    DECLINE_PDF  |
-- |            22 |    CASHCALL     |
-- |            23 |    PEAK_FUNDING |
-- |            24 |    LOANME       |
-- |            25 |    MERIDIAN     |
-- |            26 |    MEGASYS      |
-- |            27 |    RIGHTSIZE    |
-- |            28 |    PINNACLE     |
-- |            29 |    CREDITIQ     |

CREATE     VIEW [dbo].[viewB2B_DecisionsOutstandingToSend_Other] AS

	SELECT TOP 25-- PERCENT
		PartnerToolID		= PARTNER_TOOL.PartnerToolID,
		PartnerCode			= PARTNER_TOOL.ShortName,
		LoanAppID			= BIDS.LoanAppID,
		LoanApp_BidID		= BIDS.LoanApp_BidID,
		LenderID			= BRANCH.LenderID,
		LendersBranchID		= BRANCH.LendersBranchID,
		Field				= ELEMENT.Field,
		DataValue			= ELEMENT.DataValue,
		LastUpdateDateTime	= DBO.StripToDate(BIDS.UpdateDateTime),
		BidStatus			= BIDS.Status,
		Bids.Status,
		Bids.Rate,
		Bids.Term,	
		URL			= CASE	
--						WHEN PARTNER_TOOL.PartnerToolID	= 20		THEN 'http://10.3.200.1/sdk/blueyield.asp'	
						WHEN LEN(ISNULL(TRIGGER_SEND.URL, ''))	> 0 	THEN TRIGGER_SEND.URL	
						WHEN LEN(ISNULL(PDE_POST_URL.DataValue, '')) > 0 	THEN PDE_POST_URL.DataValue							
						WHEN PARTNER_TOOL.ShortName = 'LENDINGTREE' 	THEN 'https://lenderweb.lendingtree.com/LenderDecisions/AutoOfferPost.aspx'					
						ELSE ''	
					END,
		UserName			= CASE		WHEN TRIGGER_SEND.UserName									IS	NULL	THEN LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthUser,		'')))				WHEN LEN(LTRIM(TRIGGER_SEND.UserName))	= 0		THEN LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthUser, '')))																																							ELSE LTRIM(RTRIM(ISNULL(TRIGGER_SEND.UserName, '')))			END,
		Password			= CASE		WHEN LEN(RTRIM(LTRIM(ISNULL(TRIGGER_SEND.Password, ''))))	=	0 		THEN LTRIM(RTRIM(ISNULL(AUTHENTICATION.AuthPassword,	'')))																																																																				ELSE LTRIM(RTRIM(ISNULL(TRIGGER_SEND.Password, '')))			END,
		XML					= TRIGGER_SEND.XML

	FROM
						tblLoanApp_Bids					BIDS				WITH (NOLOCK)
				JOIN	tblPartnerDataElement	 		ELEMENT				WITH (NOLOCK) ON 	BIDS.LoanApp_BidID							= ELEMENT.LoanApp_BidID
																							AND ELEMENT.PartnerDataElementID				> 5345892
																								
				JOIN	tblPartnerToolsTriggers 		TRIGGER_SEND 		WITH (NOLOCK) ON 	TRIGGER_SEND.PartnerToolID					= ELEMENT.PartnerToolID
																							AND TRIGGER_SEND.TYPE							= 'SEND_DECISION'

				JOIN	tblPartnerTools					PARTNER_TOOL 		WITH (NOLOCK) ON 	ELEMENT.PartnerToolID						= PARTNER_TOOL.PartnerToolID
				JOIN	tblLendersBranches 				BRANCH				WITH (NOLOCK) ON 	BRANCH.LendersBranchID						= BIDS.LendersBranchID
				JOIN	tblLenders 	 					LENDER				WITH (NOLOCK) ON 	LENDER.LenderID								= Branch.LenderID

				JOIN	tblPartnerElementDefinition		DEFINITION			WITH (NOLOCK) ON	DEFINITION.PartnerToolID					= ELEMENT.PartnerToolID 
																							AND DEFINITION.ValueType						= 'PARTNER_LOAN_ID'
																							AND DEFINITION.Field							= ELEMENT.Field

		LEFT	JOIN	viewB2B_PartnerAuthentication	AUTHENTICATION 		WITH (NOLOCK) ON	AUTHENTICATION.LenderID						= BRANCH.LenderID
																							AND AUTHENTICATION.PartnerToolID				= ELEMENT.PartnerToolID

		LEFT	JOIN	tblPartnerDataElement			PDE_LAST_SENT		WITH (NOLOCK) ON	PDE_LAST_SENT.PartnerToolID					= PARTNER_TOOL.PartnerToolID
							AND PDE_LAST_SENT.PartnerDataElementID			> 5345892
							AND PDE_LAST_SENT.Field							= 'LastSentDateTime'
							AND	PDE_LAST_SENT.LoanApp_BidID					= BIDS.LoanApp_BidID
							--AND PDE_LAST_SENT.DataValue						IS NOT NULL
							AND LEN(PDE_LAST_SENT.DataValue)				> 0
							AND ISDATE(PDE_LAST_SENT.DataValue)		= 1

		LEFT JOIN tblPartnerDataElement		PDE_POST_URL			WITH (NOLOCK)	
							ON	PARTNER_TOOL.PartnerToolID	= PDE_POST_URL.PartnerToolID				
							AND PDE_POST_URL.PartnerDataElementID			> 5345892
							AND PDE_POST_URL.Field			= 'PARTNER_POST_URL'						
							AND PDE_POST_URL.LenderID		= BRANCH.LenderID

	WHERE
			--Bids.UpdateDateTime				>=	DATEADD(dd, -60, GETDATE())
			Bids.UpdateDateTime				>=	DATEADD(dd, -5, GETDATE())
		AND Bids.CreateDateTime				>=	DATEADD(dd, -60, GETDATE())

		AND Bids.Funded_Date IS NULL
		--AND ELEMENT.CreateDateTime		>=	DATEADD(dd, -30, GETDATE()) 
		--AND ELEMENT.PartnerToolID			=		PARTNER_TOOL.PartnerToolID
		--Bids.CreateDateTime				>	'2016-02-01'
		AND Element.PartnerToolID			IN		(8, 20, 37)
		--AND LENDER.LenderID				NOT	IN (1069)
		AND BIDS.Status						IN	('PENDING_DEALER', 'DECLINE_LENDER')

		
		--AND	ELEMENT.Field					=	(SELECT TOP 1 Field FROM tblPartnerElementDefinition DEFINITION	WITH (NOLOCK)	WHERE DEFINITION.PartnerToolID=ELEMENT.PartnerToolID AND DEFINITION.ValueType='PARTNER_LOAN_ID')

		AND (NULLIF(PDE_LAST_SENT.DataValue,	'')		IS	NULL OR	CONVERT(DATETIME, LEFT(CONVERT(VARCHAR(32), BIDS.UpdateDateTime, 113), 17))		>	CONVERT(DATETIME, PDE_LAST_SENT.DataValue))	
		AND EXISTS(SELECT PartnerDataElementID FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LenderID = Lender.LenderID)
		AND	PARTNER_TOOL.Active				 =	ISNULL(PARTNER_TOOL.Active, 0)
		
		--AND NOT bids.lendersbranchid IN(SELECT LendersBranchID FROM tblLendersBranches WITH (NOLOCK) WHERE LenderID IN (SELECT LenderID from tblLenders WITH (NOLOCK) where LenderName LIKE 'first inv%'))
		AND (			BIDS.Status IN ('DECLINE_LENDER') 		
				OR	(	BIDS.Status IN ('PENDING_DEALER')
						AND Bids.Rate												IS NOT NULL	
						AND Bids.Term 												IS NOT NULL
						AND	ISNUMERIC(LTRIM(RTRIM(REPLACE(BIDS.Rate, '%', ''))))	= 1
						AND ISNUMERIC(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(Bids.Term, ' ', ''), '/', ''), 'M', ''), 'O', ''), 'N', ''), 'T', ''), 'H', ''), 'S', ''))	= 1
					)
		)

		AND (NOT EXISTS(SELECT LoanApp_BidID FROM tblPartner_SuspendedBids PSB WITH (NOLOCK) WHERE PSB.LoanApp_BidID = Bids.LoanApp_BidID))
		--AND (NOT (Lender.LenderID = 1109 AND Bids.Status = 'DECLINE_LENDER'))
		AND (NOT (ISNUMERIC(Bids.Term) = 1 AND CONVERT(INT, Bids.Term) > 360))

--AND Bids.Status = 'PENDING_DEALER' AND ISNUMERIC(RATE) =1 AND CONVERT(FLOAT, RATE) > 5.0

	AND (Lender.LenderID <> 1069 OR Bids.UpdateDateTime >' 2016-03-01')

--	GROUP BY
--		[PARTNER_TOOL].[PartnerToolID], [PARTNER_TOOL].[ShortName], [BIDS].[LoanAppID], [BIDS].[LoanApp_BidID], [BRANCH].[LenderID], [BRANCH].[LendersBranchID], [ELEMENT].[Field], [ELEMENT].[DataValue], [BIDS].[UpdateDateTime], [BIDS].[STATUS], [BIDS].[STATUS], [BIDS].[RATE], [BIDS].[TERM], [TRIGGER_SEND].[URL], [TRIGGER_SEND].[URL], [PARTNER_TOOL].[ShortName], [AUTHENTICATION].[AuthUser], [TRIGGER_SEND].[UserName], [AUTHENTICATION].[AuthUser], [TRIGGER_SEND].[UserName], [TRIGGER_SEND].[UserName], [AUTHENTICATION].[AuthPassword], [TRIGGER_SEND].[Password], [TRIGGER_SEND].[Password], [TRIGGER_SEND].[XML]


	ORDER BY
		--Bids.LoanAppID						
		Bids.UpdateDateTime					DESC



	


		--Bids.LoanAppID
		--Partner_Tool.PartnerToolID,
		--Bids.LoanAppID					DESC,
		--Bids.LoanApp_BidID				DESC
		--BIDS.UpdateDateTime		DESC
		--Bids.UpdateDateTime ASC
 





GO

