/****** Object:  View dbo.viewB2B_DecisionsOutstandingToSend_TEST_ROUTEONE    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW [dbo].[viewB2B_DecisionsOutstandingToSend_TEST_ROUTEONE] AS
	SELECT TOP 50 --PERCENT
		PartnerToolID		= PARTNER_TOOL.PartnerToolID,
		PartnerCode			= PARTNER_TOOL.ShortName,
		LoanAppID			= BIDS.LoanAppID,
		LoanApp_BidID		= BIDS.LoanApp_BidID,
		Dealer.DealerID,
		Dealer				= UPPER(Dealer.DealerName),
		DealerLocation		= UPPER(Dealer.City) + ', ' + UPPER(Dealer.State),
		Applicants			= UPPER(APP.Applicant_Names),
		Field				= ELEMENT.Field,
		DataValue			= ELEMENT.DataValue,
		LendersBranchID		= (SELECT LendersBranchID FROM tblLoanApp_Bids  WHERE LoanApp_BidID = BIDS.LoanApp_BidID),



		URL					= ISNULL(NULLIF(LTRIM(PDE_Lender_URL.DataValue),	''),	Trigger_Send.URL),

--		URL					= 'http://10.3.200.1/sdk/generic/?url=' + ISNULL(NULLIF(LTRIM(PDE_Lender_URL.DataValue),	''),	Trigger_Send.URL),


		UserName			= ISNULL(ISNULL(NULLIF(LTRIM(PDE_Lender_User.DataValue),	''),	TRIGGER_SEND.Username),	''),
		Password			= ISNULL(ISNULL(NULLIF(LTRIM(PDE_Lender_PW.DataValue),		''),	TRIGGER_SEND.Password),	''),

		--UserName			= TRIGGER_SEND.Username,
		--User2				= PDE_LENDER_USER.DATAVALUE,
		--Password			= TRIGGER_SEND.Password,
		--PW					= PDE_LENDER_PW.DataValue,

		XML					= TRIGGER_SEND.XML,
		LastSentDateTime	= DBO.SimpleDateTime(PDE_Sent.DataValue),
		LastUpdateDateTime	= DBO.SimpleDateTime(BIDS.UpdateDateTime),
		BidStatus			= BIDS.Status,
		LastSent			= PDE_SENT.DataValue
	FROM
	    				tblLoanApp_Bids							BIDS			 WITH (NOLOCK)
			JOIN		tblLoanApps								APP				 WITH (NOLOCK) ON APP.LoanAppID					= BIDS.LoanAppID
			JOIN		tblDealers								DEALER			 WITH (NOLOCK) ON APP.DealerID					= DEALER.DealerID
			JOIN		tblLendersBranches						BRANCH			 WITH (NOLOCK) ON BRANCH.LendersBranchID		= BIDS.LendersBranchID
			JOIN		tblLenders 								LENDER			 WITH (NOLOCK) ON LENDER.LenderID				= Branch.LenderID
			JOIN		tblPartnerTools							PARTNER_TOOL	 WITH (NOLOCK) ON PARTNER_TOOL.PartnerToolID	= 12
	    	JOIN		tblPartnerDataElement					ELEMENT			 WITH (NOLOCK) ON BIDS.LoanApp_BidID			= ELEMENT.LoanApp_BidID	AND Element.PartnerDataElementID > 5750000 AND ELEMENT.PartnerToolID = PARTNER_TOOL.PartnerToolID AND Element.Field = 'Application.ID'
	    	JOIN		tblPartnerToolsTriggers					TRIGGER_SEND	 WITH (NOLOCK) ON TRIGGER_SEND.PartnerToolID	= PARTNER_TOOL.PartnerToolID AND TRIGGER_SEND.TYPE = 'SEND_DECISION'
			JOIN		viewBids_NewestBidForLenderApplication	NEWEST_BID		 WITH (NOLOCK) ON NEWEST_BID.LoanApp_BidID		= BIDS.LoanApp_BidID
			LEFT JOIN	tblPartnerDataElement					PDE_SENT		 WITH (NOLOCK) ON PDE_Sent.PartnerDataElementID	> 5750000 AND	PDE_SENT.LoanApp_BidID	= BIDS.LoanApp_BidID AND	PDE_SENT.Field = 'LastSentDateTime' AND PDE_SENT.PartnerToolID = PARTNER_TOOL.PartnerToolID

			LEFT JOIN	tblPartnerDataElement					PDE_Lender_URL	WITH (NOLOCK) ON	PDE_Lender_URL.PartnerToolID	= Partner_Tool.PartnerToolID	AND
																									PDE_Lender_URL.LenderID			= Lender.LenderID				AND
																									PDE_Lender_URL.Field			= 'POST_URL'					AND
																									PDE_Lender_URL.LoanAppID		= 0								AND
																									PDE_Lender_URL.LoanApp_BidID	= 0								AND
																									PDE_Lender_URL.DealerID			= 0

			LEFT JOIN	tblPartnerDataElement					PDE_Lender_User	WITH (NOLOCK) ON	PDE_Lender_User.PartnerToolID	= Partner_Tool.PartnerToolID	AND
																									PDE_Lender_User.LenderID		= Lender.LenderID				AND
																									PDE_Lender_User.Field			= 'POST_USER'					AND
																									PDE_Lender_User.LoanAppID		= 0								AND
																									PDE_Lender_User.LoanApp_BidID	= 0								AND
																									PDE_Lender_User.DealerID		= 0

			LEFT JOIN	tblPartnerDataElement					PDE_Lender_PW	WITH (NOLOCK) ON	PDE_Lender_PW.PartnerToolID		= Partner_Tool.PartnerToolID	AND
																									PDE_Lender_PW.LenderID			= Lender.LenderID				AND
																									PDE_Lender_PW.Field				= 'POST_PASSWORD'				AND
																									PDE_Lender_PW.LoanAppID			= 0								AND
																									PDE_Lender_PW.LoanApp_BidID		= 0								AND
																									PDE_Lender_PW.DealerID			= 0


		WHERE
			PARTNER_TOOL.PartnerToolID	IN	(12)									AND
			BIDS.Status 				IN	('DECLINE_LENDER', 'PENDING_DEALER')	AND
			Bids.UpdateDateTime			>=	DATEADD(dd, -60, GETDATE() ) 			AND
--			Bids.Offer_Date				IS	NOT NULL								AND 
--			Bids.Offer_Date				>=	DATEADD(dd, -60, GETDATE() ) 			AND
			
			(		ISDATE(PDE_SENT.DataValue)				= 0											OR	
					DBO.SimpleDateTime(PDE_SENT.DataValue)	< DBO.SimpleDateTime(Bids.UpdateDateTime)	OR
					DBO.SimpleDateTime(PDE_SENT.DataValue)	< DBO.SimpleDateTime(Bids.Offer_Date)		)	AND

			

		    --AND	(DATEDIFF(dd, BIDS.UpdateDateTime, GETDATE()) <= 60		OR		DATEDIFF(dd, BIDS.Offer_Date, GETDATE()) <= 60)
			NOT EXISTS(SELECT LoanApp_BidID FROM tblPartner_SuspendedBids PSB WITH (NOLOCK) WHERE PSB.LoanApp_BidID = Bids.LoanApp_BidID)
			AND Bids.LendersBranchID NOT IN (SELECT LendersBranchID FROM viewB2B_Lenders_UsingBeta_V3 WITH (NOLOCK) WHERE PartnerToolID = PARTNER_TOOL.PartnerToolID)			
--	ORDER BY
--		Bids.LoanApp_BidID




