/****** Object:  View dbo.viewB2B_EMail_Notification_Pending_NEW    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE VIEW [dbo].[viewB2B_EMail_Notification_Pending_NEW] AS
	SELECT
		PartnerToolID										= PDE_EMailFlag.PartnerToolID,
		LoanAppID												= Bid.LoanAppID,
		LoanApp_BidID										= Bid.LoanApp_BidID,
		LenderName											= Lender.LenderName + ' - ' + Branch.BranchName,
		[To:]														= Branch.Notification_Email,
		[Subject:]											= 'New ' + REPLACE(REPLACE(PartnerApplicationID.Partner, 'DEALERTRACK', 'DealerTrack'), 'ROUTEONE', 'RouteOne') + ' Loan Received! (' + PartnerApplicationID.ID_Name + ': '  + PartnerApplicationID.ID + ')',
		[Content: Originator]						=	REPLACE(REPLACE(PartnerApplicationID.Partner, 'DEALERTRACK', 'DealerTrack'), 'ROUTEONE', 'RouteOne'),
		[Content: CreditSmarts Loan #]	= Bid.LoanAppID,
		[Content: Originator Loan #]		= PartnerApplicationID.ID,
		[Content: Received]							= Bid.CreateDateTime,
		[Content: Dealer]								= DBO.ProperCase(Dealer.DealerName) + ' (' + DBO.ProperCase(Dealer.City) + ', ' + UPPER(Dealer.State) + ')',
		[Content: Applicant(s)]					= DBO.ProperCase(App.Applicant_Names),
		[Status]					 							= 'UNSENT' --ISNULL(NULLIF(EMail.DataValue, ''), 'UNSENT')
	FROM
								tblLoanApp_Bids									Bid											WITH (NOLOCK)
					JOIN	tblLoanApps											App											WITH (NOLOCK) ON	App.LoanAppID													= Bid.LoanAppID
					JOIN	tblLendersBranches							Branch									WITH (NOLOCK) ON	Branch.LendersBranchID								= Bid.LendersBranchID
					JOIN	tblLenders											Lender									WITH (NOLOCK) ON	Lender.LenderID												= Branch.LenderID
					JOIN	tblDealers											Dealer									WITH (NOLOCK) ON	Dealer.DealerID												= App.DealerID
					JOIN	tblPartnerDataElement						PDE_EMailFlag						WITH (NOLOCK) ON	PDE_EMailFlag.PartnerDataElementID		> 6895673													AND
																																													PDE_EMailFlag.LenderID								= Branch.LenderID									AND
																																													PDE_EMailFlag.Field										= 'NOTIFY_APP_EMAIL'							AND
																																													PDE_EMailFlag.DataValue								= 'TRUE'													AND
																																													PDE_EMailFlag.LendersBranchID					= 0																AND
																																													PDE_EMailFlag.DealerID								= 0																AND
																																													PDE_EMailFlag.LoanAppID								= 0																AND
																																													PDE_EMailFlag.LoanApp_BidID						= 0
					JOIN	viewBids_OriginalBidID					Bid_Original						WITH (NOLOCK) ON	Bid_Original.LoanAppID								= App.LoanAppID										AND 
																																													Bid_Original.LenderID									= Lender.LenderID									AND 
																																													Bid_Original.LoanApp_BidID						= Bid.LoanApp_BidID
					JOIN [viewB2B_PartnerApplicationID]		PartnerApplicationID		WITH (NOLOCK) ON	PartnerApplicationID.PartnerToolID		= PDE_EMailFlag.PartnerToolID			AND 
																																													PartnerApplicationID.LoanApp_BidID		= Bid.LoanApp_BidID
	WHERE
		Bid.CreateDateTime							>=	DATEADD(d, -2, GETDATE())						AND
		Branch.Notification_EMail				IS	NOT NULL														AND 		
		LEN(Branch.Notification_EMail)	>		0																		AND
		NOT EXISTS (SELECT * FROM tblPartnerDataElement EMail WITH (NOLOCK) WHERE EMail.PartnerDataElementID > PDE_EMailFlag.PartnerDataElementID AND EMail.PartnerToolID = PDE_EMailFlag.PartnerToolID AND EMail.Field = 'NOTIFY_EMAIL_SENT' AND EMail.LoanApp_BidID = Bid.LoanApp_BidID AND EMail.LoanAppID = 0 AND EMail.LenderID = 0 AND EMail.LendersBranchID = 0 AND EMail.DealerID = 0 AND EMail.DataValue IS NOT NULL)

GO

