/****** Object:  View dbo.viewB2B_EMail_Notification_Pending_NEW_2019_03_06    Script Date: 7/31/2024 12:57:20 PM ******/

	
create VIEW [dbo].[viewB2B_EMail_Notification_Pending_NEW_2019_03_06] AS
	SELECT
	--TOP 10
--TOP 100 PERCENT
		PartnerToolID					= PDE_EMailFlag.PartnerToolID,
		LoanAppID						= Bid.LoanAppID,
		LoanApp_BidID					= MIN(Bid.LoanApp_BidID),
		[To:]							= Branch.Notification_Email,

		--[Subject:]						= 'New ' + REPLACE(REPLACE(Partner.ShortName, 'DEALERTRACK', 'DealerTrack'), 'ROUTEONE', 'RouteOne') + ' Loan Received! (' + PDE_LoanID.Field + ': '  + PDE_LoanID.DataValue + ')',
		[Subject:]						= 'New ' + REPLACE(REPLACE(PartnerApplicationID.Partner, 'DEALERTRACK', 'DealerTrack'), 'ROUTEONE', 'RouteOne') + ' Loan Received! (' + PartnerApplicationID.ID_Name + ': '  + PartnerApplicationID.ID + ')',

		--[Content: Originator]			= REPLACE(REPLACE(Partner.ShortName, 'DEALERTRACK', 'DealerTrack'), 'ROUTEONE', 'RouteOne'),
		[Content: Originator]			= REPLACE(REPLACE(PartnerApplicationID.Partner, 'DEALERTRACK', 'DealerTrack'), 'ROUTEONE', 'RouteOne'),

		[Content: CreditSmarts Loan #]	= Bid.LoanAppID,
		--[Content: Originator Loan #]	= PDE_LoanID.DataValue,
		[Content: Originator Loan #]	= PartnerApplicationID.ID,

		[Content: Received]				= MIN(Bid.CreateDateTime),
		[Content: Dealer]				= DBO.ProperCase(Dealer.DealerName) + ' (' + DBO.ProperCase(Dealer.City) + ', ' + UPPER(Dealer.State) + ')',
		[Content: Applicant(s)]			= DBO.ProperCase(App.Applicant_Names),
		[Status]					 	= ISNULL(NULLIF(EMail.DataValue, ''), 'UNSENT')

		
	FROM
					tblLoanApp_Bids						Bid				WITH (NOLOCK)
			 JOIN	tblLoanApps							App				WITH (NOLOCK) ON	App.LoanAppID				= Bid.LoanAppID
			 JOIN	tblLendersBranches					Branch			WITH (NOLOCK) ON	Branch.LendersBranchID		= Bid.LendersBranchID
			 JOIN	tblLenders							Lender			WITH (NOLOCK) ON Lender.LenderID			= Branch.LenderID
			 JOIN	tblDealers							Dealer			WITH (NOLOCK) ON Dealer.DealerID			= App.DealerID


			 JOIN	tblPartnerDataElement				PDE_EMailFlag	WITH (NOLOCK) ON	PDE_EMailFlag.PartnerDataElementID > 6890000
																						AND PDE_EMailFlag.LenderID			= Branch.LenderID 
																						AND	PDE_EMailFlag.Field				= 'NOTIFY_APP_EMAIL'
																						AND PDE_EMailFlag.DataValue			= 'TRUE'
																						--AND PDE_EMailFlag.LenderID			= 0 this is conflicting with first condition on this join
																						AND PDE_EMailFlag.LendersBranchID	= 0
																						AND PDE_EMailFlag.DealerID			= 0
																						AND PDE_EMailFlag.LoanAppID			= 0
																						AND PDE_EMailFlag.LoanApp_BidID		= 0
																						
/* 
			 JOIN	tblPartnerTools						Partner			WITH (NOLOCK) ON Partner.PartnerToolID		= PDE_EMailFlag.PartnerToolID

			 JOIN	tblPartnerElementDefinition			PED_LoanID		WITH (NOLOCK) ON PED_LoanID.PartnerToolID		= PDE_EMailFlag.PartnerToolID
																						AND PED_LoanID.ValueType		= 'PARTNER_LOAN_ID'

			 JOIN	tblPartnerDataElement				PDE_LoanID		WITH (NOLOCK) ON	--PDE_LoanID.PartnerDataElementID > 6890000 AND
																						PDE_LoanID.PartnerToolID	= PDE_EMailFlag.PartnerToolID
																						AND PDE_LoanID.Field			= PED_LoanID.Field
																						AND PDE_LoanID.LoanApp_BidID	= Bid.LoanApp_BidID 
																						AND PDE_LoanID.LoanAppID		= 0
																						AND PDE_LoanID.DealerID			= 0
																						AND PDE_LoanID.LenderID			= 0
																						AND PDE_LoanID.LendersBranchID	= 0

*/

			JOIN [viewB2B_PartnerApplicationID] PartnerApplicationID WITH (NOLOCK) ON	PartnerApplicationID.PartnerToolID		= PDE_EMailFlag.PartnerToolID
																						AND PartnerApplicationID.LoanApp_BidID	= Bid.LoanApp_BidID 

			LEFT JOIN	tblPartnerDataElement				EMail			WITH (NOLOCK) ON	EMail.PartnerDataElementID > 6890000
																						AND EMail.PartnerToolID			= PDE_EMailFlag.PartnerToolID
																						AND EMail.Field					= 'NOTIFY_EMAIL_SENT'
																						AND EMail.LoanApp_BidID			= Bid.LoanApp_BidID																						
																						AND EMail.LoanAppID				= 0
																						AND EMail.LenderID				= 0
																						AND EMail.LendersBranchID		= 0

	WHERE
		Bid.CreateDateTime >= DATEADD(d, -2, GETDATE())	AND
		EMail.DataValue IS NULL 
		AND Bid.LoanApp_BidID IN (SELECT MIN(LoanApp_BidID) FROM tblLoanApp_Bids Bids WITH (NOLOCK) JOIN tblLendersBranches Branch WITH (NOLOCK) ON Branch.LendersBranchID = Bids.LendersBranchID WHERE Bids.LoanAppID = Bid.LoanAppID AND Branch.LenderID = Lender.LenderID)


	GROUP BY
		PDE_EMailFlag.PartnerToolID,
		--Partner.ShortName,
		PartnerApplicationID.Partner,
		--PDE_LoanID.DataValue,
		PartnerApplicationID.ID,
		DEALER.DealerName,
		App.Applicant_Names,
		Branch.Notification_Email,
		Dealer.City,
		Dealer.State,
		Bid.LoanAppID,
		--PDE_LoanID.Field,
		PartnerApplicationID.ID_Name,
		Bid.CreateDateTime,
		EMail.DataValue

	--ORDER BY APP.LOANAPPID, BID.LOANAPP_BIDID

	

GO

