/****** Object:  View dbo.viewB2B_Exchange_Funding_PartnerToolStatus    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewB2B_Exchange_Funding_PartnerToolStatus AS
	SELECT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		LenderID				= Lender.LenderID,
		LendersBranchID			= Branch.LendersBranchID,
		DealerID				= Dealer.DealerID,
		PartnerToolID			= PTT.PartnerToolID,
		Status					= PTS.Status,
		Sent					= PTS.Sent,
		PostError				= PTS.PostError,
		PostErrorDescription	= PTS.PostErrorDescription,
		UpdateDateTime			= PTS.UpdateDateTime

	FROM
						tblLoanApp_Bids					Bid			WITH (NOLOCK)
				JOIN	tblLoanApps						App			WITH (NOLOCK)	ON	App.LoanAppID				=	Bid.LoanAppID
				JOIN	tblDealers						Dealer		WITH (NOLOCK)	ON	Dealer.DealerID				=	App.DealerID
				JOIN	tblLendersBranches				Branch		WITH (NOLOCK)	ON	Branch.LendersBranchID		=	Bid.LendersBranchID
				JOIN	tblLenders						Lender		WITH (NOLOCK)	ON	Lender.LenderID				=	Branch.LenderID
		LEFT	JOIN	tblPartnerToolStatus			PTS			WITH (NOLOCK) 	ON	PTS.LoanApp_BidID			IN 	(SELECT LoanApp_BidID FROM tblLoanApp_Bids Bid_Inner WITH (NOLOCK) WHERE Bid_Inner.LoanAppID = Bid.LoanAppID AND Bid_Inner.LendersBranchID IN (SELECT LendersBranchID FROM tblLendersBranches Branch_Inner WITH (NOLOCK) WHERE Branch_Inner.LenderID = Branch.LenderID))
		LEFT	JOIN	tblPartnerTools					PTT			WITH (NOLOCK)	ON	PTT.PartnerToolID			=	PTS.PartnerToolID




