/****** Object:  View dbo.viewB2B_Exchange_OutstandingFunding    Script Date: 7/31/2024 12:57:20 PM ******/


/*
	PTS.Status:
		'Sending'
		'Error'
		'Success'
*/

CREATE VIEW [dbo].[viewB2B_Exchange_OutstandingFunding] AS
	SELECT TOP 100 PERCENT
		LoanAppID			= BID.LoanAppID,
		LoanApp_BidID		= BID.LoanApp_BidID,
		ApplicationID		= LTRIM(STR(BID.LoanAppID)) + '-' + LTRIM(STR(BID.LoanApp_BidID)),
		Vehicle				= BID.Vehicle,
		Applicants			= BID.Applicant_Names,
		Status				= BID.Status,
		DealerID			= BID.DealerID,
		Dealer				= BID.Dealer,
		DateFunded			= BID.Funded_Date,
		LenderID			= BID.LenderID,
		LendersBranchID		= BID.LendersBranchID,
		LenderName			= BID.LenderName,
		LastUpdate			= ISNULL(PTS.UpdateDateTime, CONVERT(dateTime, '2011-01-01')),
		CustomerNumber		= LDR.CustomerNumber,
		PostURL				= R.URL,
		PostUser			= R.Login,
		PostPassword		= R.Password,
		PullURL				=
			'https://www.CreditSmarts.com/CreditSmarts/v2/Partners/Outbound.asp?LoanAppID=' +
			LTRIM(STR(BID.LoanAppID)) +
			'&BidID=' + LTRIM(STR(BID.LoanApp_BidID)) +
			'&Native=1',
		IsPTStatusExist		= CASE
			WHEN ISNULL(PTS.PartnerToolID, 0) > 0 THEN 1 ELSE 0	END,
		PartnerToolID		= R.PartnerToolID,
		XSLT				= PTT.XML,
		U.CONTRACT_DATE,
		FUNDING_DISCOUNT_FEE = ISNULL(U.FUNDING_DISCOUNT_FEE, 0)
	
	FROM
		view_LoanApps_Bids								BID			WITH (NOLOCK)
		
		INNER JOIN tblLenderDealerRelation				LDR			WITH (NOLOCK)
			ON	BID.LenderID = LDR.LenderID
			AND BID.DealerID = LDR.DealerID	
		
		INNER JOIN tblPartnerRelation					R			WITH (NOLOCK)
			ON	BID.LenderID = R.LenderID
			AND R.Active = 1		
					
		INNER JOIN tblPartnerToolsTriggers				PTT			WITH (NOLOCK)
			ON	PTT.PartnerToolID = R.PartnerToolID
			AND PTT.TYPE = 'EXCHANGE'			
		
		LEFT OUTER JOIN tblPartnerToolStatus			PTS			WITH (NOLOCK)
			ON	BID.LoanApp_BidID = PTS.LoanApp_BidID
			AND PTS.PartnerToolID = R.PartnerToolID
			
		INNER JOIN tblLoanApp_Underwriting				U			WITH (NOLOCK)
			ON BId.LoanAppID = U.LoanAppID AND ISNULL(U.FUNDED , 0) = 1
					
	WHERE		
		BID.CANCELED_DATE IS NULL
		AND (LDR.CustomerNumber IS NOT NULL AND LEN(LDR.CustomerNumber) > 0)
		AND ((BID.FUNDED_DATE IS NOT NULL AND BID.Funded_Date > CONVERT(datetime, '2011-01-01')) OR (BID.FUNDED Is Not Null AND Bid.FUNDED = 1))
		AND ((PTS.Status IS NULL OR PTS.Status = 'Sending') OR (PTS.Sent IS NULL OR BID.Funded_Date > PTS.Sent))
		AND (PTS.PostError IS NULL OR PTS.PostError <> 0)
		--AND (PTS.Sent IS NULL OR BID.Funded_Date > PTS.Sent)
		AND BID.STATUS NOT IN ('DECLINE_LENDER')
	ORDER BY
		BID.FUNDED_DATE DESC














GO

SET QUOTED_IDENTIFIER OFF 
GO
SET ANSI_NULLS ON 
GO

