/****** Object:  View dbo.viewB2B_Exchange_OutstandingFunding_new    Script Date: 7/31/2024 12:57:20 PM ******/
/*
	PTS.Status:
		'Sending'
		'Error'
		'Success'
*/

CREATE   VIEW viewB2B_Exchange_OutstandingFunding_new AS
	SELECT TOP 100 PERCENT
		LoanAppID			= BID.LoanAppID,
		LoanApp_BidID		= BID.LoanApp_BidID,
		ApplicationID		= LTRIM(STR(BID.LoanAppID)) + '-' + LTRIM(STR(BID.LoanApp_BidID)),
		--Vehicle				= BID.Vehicle,

		Vehicle				= CASE	WHEN Worksheet.LoanApp_WorksheetID IS NULL		THEN ISNULL(CONVERT(CHAR(4), App.Vehicle_Year) + ' ', '') + ISNULL(DBO.ProperCase(App.Vehicle_Make) + ' ', '') + ISNULL(DBO.ProperCase(App.Vehicle_Model) + ' ', '') + ISNULL('(' + REPLACE(CONVERT(VARCHAR(16), CONVERT(money, App.Vehicle_Mileage), 1), '.00', '') + ' Miles)', '')
									ELSE ISNULL(CONVERT(CHAR(4), Worksheet.Vehicle_Year) + ' ', '') + ISNULL(DBO.ProperCase(Worksheet.Vehicle_Make) + ' ', '') + ISNULL(DBO.ProperCase(Worksheet.Vehicle_Model) + ' ', '') + ISNULL('(' + REPLACE(CONVERT(VARCHAR(16), CONVERT(money, Worksheet.Vehicle_Mileage), 1), '.00', '') + ' Miles)', '')
								END,
		
		Applicants			= DBO.ProperCase(App.Applicant_Names),
		Status				= BID.Status,
		DealerID			= Dealer.DealerID,
		--Dealer				= BID.Dealer,
		Dealer				= Dealer.DealerName,
		DateFunded			= BID.Funded_Date,
		LenderID			= Branch.LenderID,
		LendersBranchID		= BID.LendersBranchID,
		LenderName			= DBO.ProperCase(Lender.LenderName),
		LastUpdate			= ISNULL(PTS.UpdateDateTime, DATEADD(dd, -2, Bid.Funded_Date)),
		CustomerNumber		= LDR.CustomerNumber,
		PostURL				= PDE_URL.DataValue,
		PostUser			= PDE_USER.DataValue,
		PostPassword			= PDE_PWD.DataValue,
		PullURL				=
			'https://www.creditsmarts.com/CreditSmarts/v2/Partners/Outbound2.asp?LoanAppID=' +
			LTRIM(STR(BID.LoanAppID)) +
			'&BidID=' + LTRIM(STR(BID.LoanApp_BidID)) +
			'&Native=1&NoCache=1',
		IsPTStatusExist		= CASE
			WHEN ISNULL(PTS.PartnerToolID, 0) > 0 THEN 1 ELSE 0	END,
		PartnerToolID		= R.PartnerToolID,
		XSLT				= PTT.XML,
		U.CONTRACT_DATE,
		FUNDING_DISCOUNT_FEE = ISNULL(U.FUNDING_DISCOUNT_FEE, 0)
	
	FROM
		--view_LoanApps_Bids								BID			WITH (NOLOCK)

				tblLoanApp_Bids								BID			WITH (NOLOCK)
		JOIN	tblLoanApps									App			WITH (NOLOCK) ON App.LoanAppID			= Bid.LoanAppID

		JOIN	tblDealers									Dealer		WITH (NOLOCK) ON Dealer.DealerID		= App.DealerID
		JOIN	tblLendersBranches							Branch		WITH (NOLOCK) ON Branch.LendersBranchID = Bid.LendersBranchID
		JOIN	tblLenders									Lender		WITH (NOLOCK) ON Lender.LenderID		= Branch.LenderID
		JOIN	tblLenderDealerRelation						LDR			WITH (NOLOCK) ON Branch.LenderID		= LDR.LenderID		AND Dealer.DealerID		= LDR.DealerID	
		JOIN	view_B2B_LendersActiveForPartnerTool		R			WITH (NOLOCK) ON Branch.LenderID		= R.LenderID		AND R.AuthorizedByCS	= 1
		JOIN	tblPartnerToolsTriggers						PTT			WITH (NOLOCK) ON PTT.PartnerToolID		= R.PartnerToolID	AND PTT.TYPE			= 'EXCHANGE'	
		JOIN	tblPartnerDataElement						PDE_URL		WITH (NOLOCK)
			ON PDE_URL.LenderID = Branch.LenderID
			AND PDE_URL.PartnerToolID = PTT.PartnerToolID
			AND PDE_URL.Field='POST_URL_FOR_FUNDING'
			AND PDE_URL.Active = 1
		
		JOIN	tblPartnerDataElement				PDE_USER			WITH (NOLOCK)
			ON PDE_USER.LenderID = Branch.LenderID
			AND PDE_USER.PartnerToolID = PTT.PartnerToolID
			AND PDE_USER.Field='POST_USER_FOR_FUNDING'
			AND PDE_USER.Active = 1

		JOIN	tblPartnerDataElement				PDE_PWD			WITH (NOLOCK)
			ON PDE_PWD.LenderID = Branch.LenderID
			AND PDE_PWD.PartnerToolID = PTT.PartnerToolID
			AND PDE_PWD.Field='POST_PASSWORD_FOR_FUNDING'
			AND PDE_PWD.Active = 1

		LEFT JOIN	tblPartnerDataElement				PDE_SENT			WITH (NOLOCK)
			ON 		PDE_SENT.PartnerToolID	= PTT.PartnerToolID
				AND	PDE_Sent.LoanApp_BidID	= Bid.LoanApp_BidID
				AND	PDE_Sent.Field			= 'LastSentDateTime'

		JOIN	tblLoanApp_Underwriting				U					WITH (NOLOCK)
			ON BID.LoanAppID = U.LoanAppID AND U.LenderID = Branch.LenderID AND ISNULL(U.FUNDED , 0) = 1

		LEFT JOIN	tblLoanApp_Worksheet						Worksheet	WITH (NOLOCK) ON Worksheet.LoanApp_BidID	= Bid.LoanApp_BidID	AND ISNULL(Worksheet.Active, 0) = 1

		LEFT JOIN tblPartnerToolStatus			PTS			WITH (NOLOCK)
			ON	BID.LoanApp_BidID = PTS.LoanApp_BidID
			AND PTS.PartnerToolID = PTT.PartnerToolID		
	WHERE
			DATEDIFF(dd, ISNULL(Bid.Funded_Date, Bid.UpdateDateTime), GETDATE())	< 90
		AND	BID.FUNDED_DATE	IS NOT NULL
		
			--BID.UpdateDateTime	>	DATEADD(dd, -90, GETDATE()) and		
		AND	Bid.LoanAppID IN (SELECT LoanAppID FROM tblLoanApp_Bids Bid_Inner WITH (NOLOCK) WHERE LendersBranchID IN (SELECT LendersBranchID FROM tblLendersBranches Branch_Inner WITH (NOLOCK) WHERE Branch_Inner.LenderID = Lender.LenderID) 
									AND	Bid_Inner.LoanApp_BidID	IN (SELECT LoanApp_BidID FROM tblPartnerDataElement PDE_Inner WITH (NOLOCK) WHERE PDE_Inner.PartnerToolID = PTT.PartnerToolID)
								)

		--AND BID.Funded_Date	>=	DATEADD(dd, -90, GETDATE())
		--AND BID.Funded_Date	>	ISNULL(PTS.Sent, DATEADD(d, -360, Bid.Funded_Date))
		AND (PTS.Sent IS NULL OR BID.Funded_Date > PTS.Sent)
		AND BID.CANCELED_DATE	IS NULL
		AND BID.Status		NOT IN 	('DECLINE_LENDER')
