/****** Object:  View dbo.viewB2B_FundingLastSent    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewB2B_FundingLastSent AS
	SELECT --TOP 100
		LoanAppID		= Bid.LoanAppID,
		LenderID		= Branch.LenderID,
		FundingSent		= MAX(BLS.FundingSent)
	FROM
				tblLoanApp_Bids				Bid			WITH (NOLOCK)
		JOIN	tblLendersBranches			Branch		WITH (NOLOCK) ON Branch.LendersBranchID		= Bid.LendersBranchID
		JOIN	tblLoanApp_Bids_LastStatus	BLS			WITH (NOLOCK) ON BLS.LoanApp_BidID			= Bid.LoanApp_BidID
	WHERE
			BLS.FundingSent									IS NOT	NULL
	GROUP BY
		Bid.LoanAppID,
		Branch.LenderID

	--ORDER BY		MAX(BLS.FundingSent)




