CREATE     VIEW [dbo].[viewB2B_FundingPartners] AS

	SELECT 
		TOOL.*,
		TRIG.PartnerToolsTriggerID,
		TRIG.Type as TriggerType,
		TRIG.Active as TriggerActive
	FROM 
		tblPartnerTools TOOL WITH (NOLOCK)
		LEFT JOIN tblPartnerToolsTriggers TRIG WITH (NOLOCK) ON TRIG.PartnerToolID=TOOL.PartnerToolID
	WHERE
		TOOL.ShortName IN ('MEGASYS', 'MEGASYS_V2', 'RIGHTSIZE', 'PINNACLE', 'AUTOSOFT', 'ABCOA', 'ACC', 'FIRM_AUTO', 'EQUITYAUTO', 'AGORA')
		OR (ISNULL(TRIG.Active, 0) = 1 AND TRIG.Type IN ('SEND_FUNDING_PACKET', 'SEND_FUNDING_DATA'))

