/****** Object:  View dbo.viewB2B_FundingPartnersStatus_test    Script Date: 7/31/2024 12:57:20 PM ******/



CREATE     VIEW [dbo].[viewB2B_FundingPartnersStatus_test] AS

SELECT DISTINCT TOP 100 PERCENT
	LoanAppID		= BID.LoanAppID,
	LoanApp_BidID	= BID.LoanApp_BidID,
	Funded			= CASE WHEN ISNULL(FUNDING.BidFundingStatus, '') = 'FUNDED' THEN CONVERT(BIT, 1) ELSE CONVERT(BIT, 0) END,
	PartnerToolID	= TOOL.PartnerToolID,
	Partner			= TOOL.ShortName,
	PartnerName		= TOOL.DisplayName,
	LenderID		= BRANCH.LenderID,
	LendersBranchID	= BRANCH.LendersBranchID,
	LenderActivated	= CASE WHEN ELEMENT_DECISIONS_ENABLED.DataValue IN('TRUE', 'T', '1', 'YES', 'Y') THEN CONVERT(BIT, 1) ELSE CONVERT(BIT, 0) END,
	Available		= CASE 
						WHEN 
							(
								ISNULL(FUNDING.BidFundingStatus, '') = 'FUNDED' 
								OR							
								--Sean, 31.08.2022 20:00 can that button be available when loan is package received as well? not just funded for Agora
								ISNULL(FUNDING.BidFundingStatus, '') IN ('RECEIVED', 'REJECTED') AND TOOL.ShortName IN ('AGORA')
							)
							AND ELEMENT_DECISIONS_ENABLED.DataValue IN('TRUE', 'T', '1', 'YES', 'Y') 
							/*AND (U.Contract_Date IS NOT NULL AND U.First_Pay_Date IS NOT NULL)*/ 
							THEN CONVERT(BIT, 1) 
						ELSE CONVERT(BIT, 0) 
					  END,
test1 = ELEMENT_DECISIONS_ENABLED.DataValue,
test2 = ISNULL(FUNDING.BidFundingStatus, ''),
--test1 = LEN(ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue, '')),
--test2 = ISNULL(ELEMENT_FUNDING_SENT.PartnerDataElementID, 0) = 0,
--test3 = ELEMENT_FUNDING_SENT.PartnerDataElementID,
test5 = ELEMENT_DECISIONS_ENABLED.PartnerDataElementID,
	Status			= CASE 
					WHEN ISNULL(ELEMENT_FUNDING_QUEUED.PartnerDataElementID, 0) > 0 THEN 'SENDING' 
					WHEN LEN(ISNULL(ELEMENT_FUNDING_ERROR.DataValue, '')) = 0 AND  LEN(ISNULL(ELEMENT_FUNDING_SENT.DataValue,	'')) = 0 THEN 'NOT SENT'
--					WHEN LEN(ISNULL(ELEMENT_FUNDING_ERROR.DataValue, '')) > 0 AND  LEN(ISNULL(ELEMENT_FUNDING_SENT.DataValue,	'')) = 0 THEN 'SENDING' 
					WHEN LEN(ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue, '')) > 0 THEN 'SUCCESS' 
					WHEN ELEMENT_FUNDING_ERROR.DataValue LIKE '%Customer SSN%' THEN 'ERROR: DUPLICATE SSN' 
					ELSE 'ERROR' 
				END,
partnerid=ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue, ''),
--ISNULL(ELEMENT_FUNDING_QUEUED.PartnerToolID, 0) AS QUEUED,
	Successful		= CASE WHEN LEN(ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue, '')) > 0 THEN CONVERT(BIT, 1) ELSE CONVERT(BIT, 0) END,
	Error			= ISNULL(ELEMENT_FUNDING_ERROR.DataValue,	''),
	Sent			= ISNULL(ELEMENT_FUNDING_SENT.UpdateDateTime,	''),
	PartnerLoanID		= ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue,	''),
	SentRecordID 		= ELEMENT_FUNDING_SENT.PartnerDataElementID,
	ContractDate 		= U.Contract_Date,
	FirstPayDate 		= U.First_Pay_Date
FROM
	tblLoanApp_Bids 						BID 	WITH (NOLOCK)
	JOIN tblLendersBranches					BRANCH	WITH (NOLOCK)	ON BRANCH.LendersBranchID = BID.LendersBranchID
	JOIN tblLenders							LENDER	WITH (NOLOCK)	ON BRANCH.LenderID = LENDER.LenderID
	JOIN tblPartnerTools					TOOL	WITH (NOLOCK)	ON TOOL.ShortName IN ('MEGASYS', 'MEGASYS_V2', 'RIGHTSIZE', 'PINNACLE', 'AUTOSOFT', 'ABCOA', 'ACC', 'FIRM_AUTO', 'EQUITYAUTO', 'AGORA')
--	JOIN tblPartnerTools					TOOL	WITH (NOLOCK)	ON TOOL.ShortName IN ('MEGASYS', 'RIGHTSIZE')

	LEFT JOIN tblLoanApp_BidFundingStatus	FUNDING	WITH (NOLOCK)	ON FUNDING.LoanApp_BidID = BID.LoanApp_BidID
	LEFT JOIN tblPartnerDataElement			ELEMENT_FUNDING_ERROR	WITH (NOLOCK)   
		ON TOOL.PartnerToolID	= ELEMENT_FUNDING_ERROR.PartnerToolID 
		AND ELEMENT_FUNDING_ERROR.Field	= 'FUNDING_SENDING_ERROR'		
		AND (ELEMENT_FUNDING_ERROR.LenderID	= BRANCH.LenderID OR ELEMENT_FUNDING_ERROR.LendersBranchID	= BRANCH.LendersBranchID)
		AND ELEMENT_FUNDING_ERROR.LoanApp_BidID=BID.LoanApp_BidID
	LEFT JOIN tblPartnerDataElement			ELEMENT_DECISIONS_ENABLED WITH (NOLOCK)	
		ON TOOL.PartnerToolID	= ELEMENT_DECISIONS_ENABLED.PartnerToolID 
		AND ELEMENT_DECISIONS_ENABLED.Field	= 'Lender Enabled (CreditSmarts)' 	
		AND (ELEMENT_DECISIONS_ENABLED.LenderID	= BRANCH.LenderID OR ELEMENT_DECISIONS_ENABLED.LendersBranchID	= BRANCH.LendersBranchID)
	LEFT JOIN tblPartnerDataElement			ELEMENT_FUNDING_SENT	WITH (NOLOCK)	
		ON TOOL.PartnerToolID	= ELEMENT_FUNDING_SENT.PartnerToolID 
		AND	ELEMENT_FUNDING_SENT.Field	= 'FUNDING_SENDING_DATE'		
		AND (ELEMENT_FUNDING_SENT.LenderID	= BRANCH.LenderID  OR ELEMENT_FUNDING_SENT.LendersBranchID	= BRANCH.LendersBranchID)
		AND ELEMENT_FUNDING_SENT.LoanApp_BidID=BID.LoanApp_BidID
	LEFT JOIN tblPartnerDataElement			ELEMENT_FUNDING_PARTNER_ID	WITH (NOLOCK)	
		ON TOOL.PartnerToolID	= ELEMENT_FUNDING_PARTNER_ID.PartnerToolID 
		AND	ELEMENT_FUNDING_PARTNER_ID.Field	= 'PARTNER_LOAN_ID'		
		AND (ELEMENT_FUNDING_PARTNER_ID.LenderID	= BRANCH.LenderID  OR ELEMENT_FUNDING_PARTNER_ID.LendersBranchID	= BRANCH.LendersBranchID)
		AND ELEMENT_FUNDING_PARTNER_ID.LoanApp_BidID=BID.LoanApp_BidID
	LEFT JOIN tblPartnerDataElement			ELEMENT_FUNDING_QUEUED	WITH (NOLOCK)   
		ON TOOL.PartnerToolID	= ELEMENT_FUNDING_QUEUED.PartnerToolID 
		AND ELEMENT_FUNDING_QUEUED.Field	= 'FUNDING_SENDING_QUEUED'		
		AND (ELEMENT_FUNDING_QUEUED.LenderID	= BRANCH.LenderID  OR ELEMENT_FUNDING_QUEUED.LendersBranchID	= BRANCH.LendersBranchID)
		AND ELEMENT_FUNDING_QUEUED.LoanApp_BidID=BID.LoanApp_BidID
	LEFT JOIN tblLoanApp_Underwriting		U			WITH (NOLOCK)	
		ON BId.LoanAppID = U.LoanAppID 
		AND U.LenderID = BRANCH.LenderID 
		AND ISNULL(U.FUNDED , 0) = 1

WHERE
	ELEMENT_DECISIONS_ENABLED.DataValue IN('TRUE', 'T', '1', 'YES', 'Y')
		AND	ISNULL(TOOL.Active,	1	)	=	1
		--AND	ISNULL(LENDER.LenderStatus,	''	)	<>	'INACTIVE'
		--AND	ISNULL(ELEMENT_DECISIONS_ENABLED.DataValue, 'N'	)	IN	('TRUE', 'T', '1', 'YES', 'Y')

ORDER BY
	BID.LoanAppID DESC, 
	BID.LoanApp_BidID DESC


























