	U_NEW_USED	=	U.NEW_USED, 
	U_MEMBER_FEE	=	U.MEMBER_FEE, 
	U_MISC_FEE	=	U.MISC_FEE, 
	U_WIRE_CHECK_NUM	=	U.WIRE_CHECK_NUM, 
	U_MAILING_STREET1	=	U.MAILING_STREET1, 
	U_MAILING_CITY	=	U.MAILING_CITY, 
	U_MAILING_STATE	=	U.MAILING_STATE, 
	U_MAILING_ZIP	=	U.MAILING_ZIP, 
	U_YIELD_TYPE	=	U.YIELD_TYPE, 
	U_FUNDING_METHOD	=	U.FUNDING_METHOD, 
	U_SPECIAL_INSTRUCTIONS	=	U.SPECIAL_INSTRUCTIONS, 
	U_CREDIT_GUID	=	U.CREDIT_GUID, 
	U_WIRE_CUSTOMER_ACCT	=	U.WIRE_CUSTOMER_ACCT, 
	U_PREFERRED_PAYMENT	=	U.PREFERRED_PAYMENT, 
	U_VEHICLE_MAKE	=	U.VEHICLE_MAKE, 
	U_VEHICLE_MODEL	=	U.VEHICLE_MODEL, 
	U_VEHICLE_YEAR	=	U.VEHICLE_YEAR, 
	U_OTHER_INCOME_OVERRIDE_1	=	U.OTHER_INCOME_OVERRIDE_1, 
	U_OTHER_INCOME_OVERRIDE_1_AMT	=	U.OTHER_INCOME_OVERRIDE_1_AMT, 
	U_OTHER_INCOME_OVERRIDE_2	=	U.OTHER_INCOME_OVERRIDE_2, 
	U_OTHER_INCOME_OVERRIDE_2_AMT	=	U.OTHER_INCOME_OVERRIDE_2_AMT, 
	U_SALARY_OVERRIDE_1	=	U.SALARY_OVERRIDE_1, 
	U_SALARY_OVERRIDE_1_AMT	=	U.SALARY_OVERRIDE_1_AMT, 
	U_SALARY_OVERRIDE_2	=	U.SALARY_OVERRIDE_2, 
	U_SALARY_OVERRIDE_2_AMT	=	U.SALARY_OVERRIDE_2_AMT, 
	U_SALARY_OVERRIDE_1_REASON	=	U.SALARY_OVERRIDE_1_REASON, 
	U_SALARY_OVERRIDE_2_REASON	=	U.SALARY_OVERRIDE_2_REASON, 
	U_OTHER_INCOME_OVERRIDE_1_REASON	=	U.OTHER_INCOME_OVERRIDE_1_REASON, 
	U_OTHER_INCOME_OVERRIDE_2_REASON	=	U.OTHER_INCOME_OVERRIDE_2_REASON, 
	U_PAYMENT_OVERRIDE_REASON	=	U.PAYMENT_OVERRIDE_REASON, 
	U_Received_Date	=	U.Received_Date, 
	U_Received_User	=	U.Received_User, 
	U_Rejected_Date	=	U.Rejected_Date, 
	U_Rejected_User	=	U.Rejected_User, 
	U_Funded_Date	=	U.Funded_Date, 
	U_Funded_User	=	U.Funded_User, 
	U_FundingStatus	=	U.FundingStatus, 
	U_FundingStatus_User	=	U.FundingStatus_User, 
	U_FundingStatus_DateTime	=	U.FundingStatus_DateTime, 
	U_SERVICE_CONTRACT_NAME	=	U.SERVICE_CONTRACT_NAME, 
	U_CUSTOMER_DOWNPAYMENT	=	U.CUSTOMER_DOWNPAYMENT, 
	U_TOTAL_INTEREST_CHARGED	=	U.TOTAL_INTEREST_CHARGED, 
	U_TOTAL_OF_PAYMENTS	=	U.TOTAL_OF_PAYMENTS, 
	U_VSI	=	U.VSI, 
	U_SERVICE_CONTRACT_AMOUNT	=	U.SERVICE_CONTRACT_AMOUNT, 
	U_SERVICE_CONTRACT_TERM	=	U.SERVICE_CONTRACT_TERM, 
	U_SERVICE_CONTRACT_PROVIDER	=	U.SERVICE_CONTRACT_PROVIDER, 
	U_GAP_AMOUNT	=	U.GAP_AMOUNT, 
	U_GAP_TERM	=	U.GAP_TERM, 
	U_GAP_PROVIDER	=	U.GAP_PROVIDER, 
	U_TOTAL_OTHER_CHARGES	=	U.TOTAL_OTHER_CHARGES, 
	U_SALES_PRICE	=	U.SALES_PRICE, 
	U_ActiveWorksheetID	=	U.ActiveWorksheetID, 
	U_Maturity_Date	=	U.Maturity_Date, 
	U_TRADE_IN_NET	=	U.TRADE_IN_NET, 

	--BidFundingStatus		= ISNULL(FUNDING.BidFundingStatus, ''),
	CurrentDate			= GETDATE(),
	CustomerNumber			= ISNULL(RELATION.CustomerNumber, '')

FROM
	view_LoanApps_Bids BID WITH (NOLOCK)
	JOIN tblLenderDealerRelation RELATION WITH (NOLOCK) ON RELATION.DealerID=BID.DealerID AND RELATION.LenderID=BID.LenderID

	LEFT JOIN view_LoanApp_Applicant A WITH (NOLOCK) ON A.LoanApp_ApplicantID=(SELECT TOP 1 LoanApp_ApplicantID FROM view_LoanApp_Applicant appl WITH(NOLOCK) WHERE appl.LoanAppID=BID.LoanAppID ORDER BY LoanApp_ApplicantID)
	LEFT JOIN tblLoanApp_BidFundingStatus	FUNDING	WITH (NOLOCK)	ON FUNDING.LoanApp_BidID = BID.LoanApp_BidID
	LEFT JOIN viewLoanApp_Underwriting U			WITH (NOLOCK)	ON BId.LoanAppID = U.LoanAppID AND U.LenderID = BID.LenderID AND ISNULL(U.FUNDED , 0) = 1


ORDER BY
	BID.LoanAppID DESC, 
	BID.LoanApp_BidID DESC























