/****** Object:  View dbo.viewB2B_LenderDealerRegistrationCheck    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW viewB2B_LenderDealerRegistrationCheck AS
SELECT
  A.LoanAppID,
  B.LoanApp_BidID,
  DealerID = CONVERT(int, ISNULL((NULLIF(A.DealerID, '')), 0)),
  Submit_Date = ISNULL(B.Submit_Date, B.UpdateDateTime),
  Applicant_Names = UPPER(A.Applicant_Names),
  VEHICLE = UPPER(ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), A.VEHICLE_YEAR) + ' ' + A.VEHICLE_MAKE + ' ' + A.VEHICLE_MODEL)),
  DealerName = UPPER(D.DealerName),
  DealerAddress=UPPER(D.Address),
  DealerCity=UPPER(D.City),
  DealerState = UPPER(D.State),
  DealerZip = dbo.fmt_zip(D.Zip),
  DealerPhone = dbo.stripToNumbers(D.Telephone),
  DealerFax = dbo.stripToNumbers(D.Fax),
  CustomerNumber = ISNULL(R.CustomerNumber, ''),
  R.LenderDealerRelationID,
  LastNotificationDateTime = R.LastNotificationDateTime,
  LastNotification = DATEDIFF(hh, ISNULL(R.LastNotificationDateTime, CONVERT(DateTime, '01-01-2000')), GETDATE()),
  DealerNotificationMessage = CASE
  WHEN (NULLIF(RTRIM(LTRIM(CONVERT(VARCHAR(64), I.DealerNotificationMessage))), '') IS NULL) THEN
      'You are not currently a registered customer of "' + UPPER(LBI.LenderName) + '".  Your contact information was forwarded to them on ' + CONVERT(VARCHAR(17), GETDATE()) + '.'
  ELSE
      RTRIM(LTRIM(CONVERT(VARCHAR(2048), I.DealerNotificationMessage)))
  END,
  AllowedToSend = CASE
    WHEN (LBI.MustHaveCustomerNumber=1 AND (NULLIF(LTRIM(RTRIM(R.CustomerNumber)), '') IS NULL)) THEN 0
--    WHEN LBI.PostActive=1 OR PostTest=1 THEN 1
    ELSE 1
  END,
  ShouldNotify = CASE
    WHEN (LBI.MustHaveCustomerNumber=1 AND (NULLIF(LTRIM(RTRIM(R.CustomerNumber)), '') IS NULL)) AND DATEDIFF(hh, ISNULL(R.LastNotificationDateTime, CONVERT(DateTime, '01-01-2000')), GETDATE()) > 18 THEN 1
    ELSE 0
  END,

  LendersInterfaceID              = LBI.LendersInterfaceID,
  Name                            = LBI.Name,
  InterfaceAge                    = LBI.InterfaceAge,
  PartnerCode                     = LBI.PartnerCode,
  PostActive                      = LBI.PostActive,
  PostText                        = LBI.PostText,
  ReceiveActive                   = LBI.ReceiveActive,
  ReceiveTest                     = LBI.ReceiveTest,
  MustHaveCustomerNumber          = LBI.MustHaveCustomerNumber,
  SendNotificationMessageToLender = LBI.SendNotificationMessageToLender,
  LenderID                        = LBI.LenderID,
  LenderName                      = LBI.LenderName,
  LenderCompanyCode               = LBI.LenderCompanyCode,
  LenderAge                       = LBI.LenderAge,
  LendersBranchID                 = LBI.LendersBranchID,
  BranchName                      = LBI.BranchName,
  BranchCompanyCode               = LBI.BranchCompanyCode,
  BranchAge                       = LBI.BranchAge,
  Notification_Email              = CASE
    WHEN LBI.LenderID = 369 THEN 'sales@cudps.org'
    WHEN LEN(ISNULL(Notification_Email, '')) = 0 THEN ''
    ELSE LBI.Notification_Email
  END

--LendersInterfaceID	
--Name	InterfaceAge	PartnerCode	PostActive	PostText	ReceiveActive	ReceiveTest	MustHaveCustomerNumber	SendNotificationMessageToLender	LenderID	LenderName	LenderCompanyCode	LenderAge	LendersBranchID	BranchName	BranchCompanyCode	BranchAge	Notification_Email
--  LBI.*

FROM
  tblLoanApp_Bids B WITH (NOLOCK)
    JOIN tblLoanApps A WITH (NOLOCK) ON(B.LoanAppID=A.LoanAppID)
    JOIN tblDealers D  WITH (NOLOCK) ON(A.DealerID=D.DealerID)
    JOIN viewB2B_LenderBranchInterfaces LBI  WITH (NOLOCK) ON (LBI.LendersBranchID = B.LendersBranchID)
    JOIN tblLendersInterfaces I  WITH (NOLOCK) ON (I.LendersInterfaceID = LBI.LendersInterfaceID)
    LEFT JOIN tblLenderDealerRelation R  WITH (NOLOCK) ON (R.LenderID=LBI.LenderID AND R.DealerID=D.DealerID)
    LEFT OUTER JOIN tblLoanApp_Worksheet WS  WITH (NOLOCK) ON(B.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)







