/****** Object:  View dbo.viewB2B_MegasysStatus_2014_12_15    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW viewB2B_MegasysStatus_2014_12_15 AS

SELECT DISTINCT TOP 100 PERCENT
	LoanAppID		= BID.LoanAppID,
	LoanApp_BidID		= BID.LoanApp_BidID,
	Funded			= CASE WHEN ISNULL(FUNDING.BidFundingStatus, '') = 'FUNDED' THEN CONVERT(BIT, 1) ELSE CONVERT(BIT, 0) END,
	PartnerToolID		= TOOL.PartnerToolID,
	Partner			= TOOL.ShortName,
	PartnerName		= TOOL.DisplayName,
	LenderID		= BRANCH.LenderID,
	LenderActivated		= CASE WHEN ELEMENT_DECISIONS_ENABLED.DataValue IN('TRUE', 'T', '1', 'YES', 'Y') THEN CONVERT(BIT, 1) ELSE CONVERT(BIT, 0) END,
	Available		= CASE WHEN ISNULL(FUNDING.BidFundingStatus, '') = 'FUNDED' AND ELEMENT_DECISIONS_ENABLED.DataValue IN('TRUE', 'T', '1', 'YES', 'Y') /*AND (U.Contract_Date IS NOT NULL AND U.First_Pay_Date IS NOT NULL)*/ THEN CONVERT(BIT, 1) ELSE CONVERT(BIT, 0) END,
--test1 = LEN(ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue, '')),
--test2 = ISNULL(ELEMENT_FUNDING_SENT.PartnerDataElementID, 0) = 0,
--test3 = ELEMENT_FUNDING_SENT.PartnerDataElementID,
	Status			= CASE 
					WHEN LEN(ISNULL(ELEMENT_FUNDING_ERROR.DataValue, '')) = 0 AND  LEN(ISNULL(ELEMENT_FUNDING_SENT.DataValue,	'')) = 0 THEN 'NOT SENT'
					WHEN LEN(ISNULL(ELEMENT_FUNDING_ERROR.DataValue, '')) > 0 AND  LEN(ISNULL(ELEMENT_FUNDING_SENT.DataValue,	'')) = 0 THEN 'SENDING' 
					WHEN LEN(ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue, '')) > 0 THEN 'SUCCESS' 
					ELSE 'ERROR' 
				END,
	Successful		= CASE WHEN LEN(ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue, '')) > 0 THEN CONVERT(BIT, 1) ELSE CONVERT(BIT, 0) END,
	Error			= ISNULL(ELEMENT_FUNDING_ERROR.DataValue,	''),
	Sent			= ISNULL(ELEMENT_FUNDING_SENT.UpdateDateTime,	''),
	PartnerLoanID		= ISNULL(ELEMENT_FUNDING_PARTNER_ID.DataValue,	''),
	SentRecordID 		= ELEMENT_FUNDING_SENT.PartnerDataElementID,
	ContractDate 		= U.Contract_Date,
	FirstPayDate 		= U.First_Pay_Date
FROM
	tblLoanApp_Bids 			BID 	WITH (NOLOCK)
	JOIN tblLendersBranches			BRANCH	WITH (NOLOCK)	ON BRANCH.LendersBranchID = BID.LendersBranchID
	JOIN tblLenders				LENDER	WITH (NOLOCK)	ON BRANCH.LenderID = LENDER.LenderID
	JOIN tblPartnerTools			TOOL	WITH (NOLOCK)	ON TOOL.ShortName='MEGASYS'

	LEFT JOIN tblLoanApp_BidFundingStatus	FUNDING	WITH (NOLOCK)	ON FUNDING.LoanApp_BidID = BID.LoanApp_BidID
	LEFT JOIN tblPartnerDataElement	ELEMENT_FUNDING_ERROR	WITH (NOLOCK)   ON TOOL.PartnerToolID	= ELEMENT_FUNDING_ERROR.PartnerToolID AND ELEMENT_FUNDING_ERROR.Field	= 'FUNDING_SENDING_ERROR'		AND ELEMENT_FUNDING_ERROR.LenderID	= BRANCH.LenderID AND ELEMENT_FUNDING_ERROR.LoanApp_BidID=BID.LoanApp_BidID
	LEFT JOIN tblPartnerDataElement	ELEMENT_DECISIONS_ENABLED WITH (NOLOCK)	ON TOOL.PartnerToolID	= ELEMENT_DECISIONS_ENABLED.PartnerToolID AND ELEMENT_DECISIONS_ENABLED.Field	= 'Lender Enabled (CreditSmarts)' 	AND ELEMENT_DECISIONS_ENABLED.LenderID	= BRANCH.LenderID
	LEFT JOIN tblPartnerDataElement	ELEMENT_FUNDING_SENT	WITH (NOLOCK)	ON TOOL.PartnerToolID	= ELEMENT_FUNDING_SENT.PartnerToolID AND	ELEMENT_FUNDING_SENT.Field	= 'FUNDING_SENDING_DATE'		AND ELEMENT_FUNDING_SENT.LenderID	= BRANCH.LenderID AND ELEMENT_FUNDING_SENT.LoanApp_BidID=BID.LoanApp_BidID
	LEFT JOIN tblPartnerDataElement	ELEMENT_FUNDING_PARTNER_ID	WITH (NOLOCK)	ON TOOL.PartnerToolID	= ELEMENT_FUNDING_PARTNER_ID.PartnerToolID AND	ELEMENT_FUNDING_PARTNER_ID.Field	= 'PARTNER_LOAN_ID'		AND ELEMENT_FUNDING_PARTNER_ID.LenderID	= BRANCH.LenderID AND ELEMENT_FUNDING_PARTNER_ID.LoanApp_BidID=BID.LoanApp_BidID
	LEFT JOIN tblLoanApp_Underwriting U			WITH (NOLOCK)	ON BId.LoanAppID = U.LoanAppID AND U.LenderID = BRANCH.LenderID AND ISNULL(U.FUNDED , 0) = 1

WHERE
	ELEMENT_DECISIONS_ENABLED.DataValue IN('TRUE', 'T', '1', 'YES', 'Y')
		--AND	ISNULL(TOOL.Active,	1	)	=	1
		--AND	ISNULL(LENDER.LenderStatus,	''	)	<>	'INACTIVE'
		--AND	ISNULL(ELEMENT_DECISIONS_ENABLED.DataValue, 'N'	)	IN	('TRUE', 'T', '1', 'YES', 'Y')

ORDER BY
	BID.LoanAppID DESC, 
	BID.LoanApp_BidID DESC








