/****** Object:  View dbo.viewB2B_Megasys_OutstandingFunding_2014_12_15    Script Date: 7/31/2024 12:57:20 PM ******/




CREATE VIEW viewB2B_Megasys_OutstandingFunding_2014_12_15 AS
	SELECT DISTINCT TOP 100 PERCENT 
--		LastStatus.*,

		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		ApplicationID			= LTRIM(STR(Bid.LoanAppID)) + '-' + LTRIM(STR(Bid.LoanApp_BidID)),
		Vehicle					= CASE WHEN Worksheet.LoanApp_WorksheetID IS NULL THEN DBO.VehicleDescription(Application.Vehicle_Year, Application.Vehicle_Make, Application.Vehicle_Model, Application.Vehicle_Mileage, Application.Vehicle_VIN) ELSE DBO.VehicleDescription(Worksheet.Vehicle_Year, Worksheet.Vehicle_Make, Worksheet.Vehicle_Model, Worksheet.Vehicle_Mileage, Worksheet.Vehicle_VIN) END,
		Applicants				= UPPER(Application.Applicant_Names),
		Status					= UPPER(Bid.Status),
		DealerID				= Dealer.DealerID,
		Dealer					= UPPER(Dealer.DealerName),
		DateFunded				= Bid.Funded_Date,
		BidFundingStatus		= ISNULL(BidFundingStatus.BidFundingStatus, ''),
		LenderID				= Branch.LenderID,
		LendersBranchID			= Bid.LendersBranchID,
		LenderName				= UPPER(Lender.LenderName),
		LastSent				= LastStatus.UpdateDateTime,
		LastUpdate				= ISNULL(LastStatus.UpdateDateTime, CONVERT(dateTime, '2011-01-01')),
		PartnerToolID			= PartnerTool.PartnerToolID,
		PostURL					= ToolParameters.FundingURL,
		PostUser				= ToolParameters.FundingUser,
		PostPassword			= ToolParameters.FundingPassword,
		AccountImportCode		= PDE_IMPORT_CODE.DataValue,
		ClientNumber			= PDE_CLIENT_NUMBER.DataValue,
		PullURL					= 'https://www.CreditSmarts.com/CreditSmarts/v2/Partners/Outbound.asp?Nocache=1&cache=0&Native=1&LoanAppID=' + LTRIM(STR(Bid.LoanAppID)) + '&BidID=' + LTRIM(STR(Bid.LoanApp_BidID))
	FROM
		tblLoanApp_Bids						Bid			WITH (NOLOCK)
		LEFT	JOIN	tblLoanApp_Worksheet			Worksheet		WITH (NOLOCK)		ON Worksheet.LoanApp_BidID	= Bid.LoanApp_BidID		AND Worksheet.Active = 1				
--		LEFT	JOIN	tblLoanApp_Bids_LastStatus		LastStatus 		WITH (NOLOCK)		ON Bid.LoanApp_BidID		= LastStatus.LoanApp_BidID
		LEFT	JOIN	tblLoanApp_BidFundingStatus		BidFundingStatus				WITH (NOLOCK)		ON BidFundingStatus.LoanApp_BidID		= Bid.LoanApp_BidID
		INNER	JOIN	tblLoanApps				Application		WITH (NOLOCK)		ON Application.LoanAppID			= Bid.LoanAppID
		INNER	JOIN	tblDealers				Dealer			WITH (NOLOCK)		ON Dealer.DealerID			= Application.DealerID
		INNER	JOIN	tblLendersBranches			Branch			WITH (NOLOCK)		ON Branch.LendersBranchID	= Bid.LendersBranchID
		INNER	JOIN	tblLenders				Lender			WITH (NOLOCK)		ON Lender.LenderID			= Branch.LenderID
		LEFT	JOIN	tblPartnerDataElement			LastStatus				WITH (NOLOCK)		ON LastStatus.LoanApp_BidID		= Bid.LoanApp_BidID				AND LastStatus.Field = 'FUNDING_SENDING_DATE'		AND LEN(ISNULL(LastStatus.DataValue, '')) > 0
		INNER	JOIN	tblPartnerTools				PartnerTool			WITH (NOLOCK)		ON PartnerTool.Shortname			= 'MEGASYS'
		INNER	JOIN	viewB2B_LenderPartnerParametersEx 	ToolParameters		WITH (NOLOCK)		ON PartnerTool.PartnerToolID		= ToolParameters.PartnerToolID		AND	ToolParameters.LendersBranchID = Bid.LendersBranchID

		INNER JOIN tblPartnerDataElement				PDE_IMPORT_CODE			WITH (NOLOCK)
			ON PDE_IMPORT_CODE.LenderID = Branch.LenderID
			AND PDE_IMPORT_CODE.PartnerToolID = PartnerTool.PartnerToolID
			AND PDE_IMPORT_CODE.Field='AccountImportCode'
			AND PDE_IMPORT_CODE.Active = 1

		INNER JOIN tblPartnerDataElement				PDE_CLIENT_NUMBER			WITH (NOLOCK)
			ON PDE_CLIENT_NUMBER.LenderID = Branch.LenderID
			AND PDE_CLIENT_NUMBER.PartnerToolID = PartnerTool.PartnerToolID
			AND PDE_CLIENT_NUMBER.Field='ClientNumber'
			AND PDE_CLIENT_NUMBER.Active = 1

		left JOIN tblLoanApp_Underwriting				U			WITH (NOLOCK)
			ON BId.LoanAppID = U.LoanAppID AND U.LenderID = Branch.LenderID AND ISNULL(U.FUNDED , 0) = 1

	WHERE
			(		Bid.CreateDateTime		> DATEADD(d, -60, GETDATE())
				OR	Bid.UpdateDateTime		> DATEADD(d, -60, GETDATE())
				OR	Bid.Submit_Date			> DATEADD(d, -60, GETDATE())
				OR	Bid.Offer_Date			> DATEADD(d, -60, GETDATE())
or 1=1
			)

		AND	(Bid.CreateDateTime	> '2009-09-01' )
		AND 	(Bid.Funded_Date > '2014-12-10')


		--AND LEN(RTRIM(LTRIM(ISNULL(ToolParameters.PostURL, ''))))					> 0
		--AND LEN(RTRIM(LTRIM(ISNULL(ToolParameters.PostUser, ''))))					> 0
		--AND LEN(RTRIM(LTRIM(ISNULL(ToolParameters.PostPassword, ''))))				> 0
		AND Bid.STATUS 		NOT IN	('DECLINE_Lender')
		AND PartnerTool.Active	= 1


		--AND Bid.LoanApp_BidID = 838705

		AND	(	BidFundingStatus.BidFundingStatus 	IN	('RECEIVED', 'REJECTED', 'FUNDED')
				OR	Bid.Funded_Date 		>	CONVERT(datetime, '2010-12-01')	
				--or  1=1
			)


		/*
		AND (		LastStatus.UpdateDateTime IS NULL 
				OR	Bid.Funded_Date > LastStatus.UpdateDateTime
		)
		*/


		AND	(		BidFundingStatus.StatusUpdateDateTime	IS NULL
				OR	LastStatus.UpdateDateTime		IS NULL
				OR	BidFundingStatus.StatusUpdateDateTime > LastStatus.UpdateDateTime	
				OR (
					Bid.Funded_Date IS NOT NULL
					AND ISNULL(LastStatus.UpdateDateTime, '2010-04-01') < Bid.Funded_Date
				)
				--or 1=1
			)
AND (U.Contract_Date IS NOT NULL AND U.First_Pay_Date IS NOT NULL)
--and bid.loanapp_bidid=856295
--and lender.lenderid=45
	ORDER BY
		Bid.FUNDED_DATE DESC








