CREATE VIEW viewB2B_ObsoleteLastSentElements AS
	SELECT
		STATUS.LoanApp_BidID
	FROM
				tblPartnerDataElement 		ELEMENT	WITH (NOLOCK)
		JOIN	tblLoanApp_Bids_LastStatus	STATUS	WITH (NOLOCK)	ON ELEMENT.LoanApp_BidID = STATUS.LoanApp_BidID
	WHERE				
		ELEMENT.Field = 'LastSentDateTime'
		AND CONVERT(DATETIME, DataValue) >= DATEADD(dd, -60, GETDATE())
 		AND CONVERT(DATETIME, STR(DATEPART(yy, DataValue)) + '-'  + STR(DATEPART(mm, DataValue)) + '-' + STR(DATEPART(dd, DataValue))) 		< 		CONVERT(DATETIME, STR(DATEPART(yy, STATUS.UpdateDateTime)) + '-'  + STR(DATEPART(mm, STATUS.UpdateDateTime)) + '-' + STR(DATEPART(dd, STATUS.UpdateDateTime)))
