CREATE VIEW viewB2B_OriginalBidID AS
	SELECT DISTINCT TOP 100 PERCENT
		LoanAppID				= BID.LoanAppID,
		LoanApp_BidID			= BID.LoanApp_BidID,
		LenderID				= STAT.LenderID,
		LendersBranchID			= BID.LendersBranchID,
		LoanApp_BidID_Count		= STAT.LoanApp_BidID_Count,
		LoanApp_BidID_Low		= STAT.LoanApp_BidID_Low,
		LoanApp_BidID_High		= STAT.LoanApp_BidID_High,
		LoanApp_BidID_Original	= STAT.LoanApp_BidID_Low
	FROM
					tblLoanApp_Bids			BID			WITH (NOLOCK)
			JOIN	tblLendersBranches		BRANCH		WITH (NOLOCK) ON BRANCH.LendersBranchID = BID.LendersBranchID
			JOIN	viewB2B_BidStatistics	STAT		WITH (NOLOCK) ON STAT.LoanAppID = BID.LoanAppID AND STAT.LenderID = BRANCH.LenderID
	ORDER BY
