CREATE VIEW viewB2B_OriginalBidID_Inner AS
	SELECT DISTINCT TOP 100 PERCENT
		LoanAppID				= BID.LoanAppID,
		LoanApp_BidID			= BID.LoanApp_BidID,
		IsOnlyBid				= CONVERT(BIT, CASE WHEN BID.LoanApp_BidID = STAT.LoanApp_BidID_Low AND BID.LoanApp_BidID = STAT.LoanApp_BidID_High THEN 1 ELSE 0 END),
		IsLowBid				= CONVERT(BIT, CASE WHEN BID.LoanApp_BidID = STAT.LoanApp_BidID_Low													THEN 1 ELSE 0 END),
		IsHighBid				= CONVERT(BIT, CASE WHEN BID.LoanApp_BidID = STAT.LoanApp_BidID_High												THEN 1 ELSE 0 END),

		LenderID				= STAT.LenderID,
		LendersBranchID			= BID.LendersBranchID,
		LoanApp_BidID_Count		= STAT.LoanApp_BidID_Count,
		LoanApp_BidID_Low		= STAT.LoanApp_BidID_Low,
		LoanApp_BidID_High		= STAT.LoanApp_BidID_High,

		LoanApp_BidID_Origianl	= STAT.LoanApp_BidID_Low
