/****** Object:  View dbo.viewB2B_OutstandingFunding_Rightsize_2015_01_06    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW [dbo].[viewB2B_OutstandingFunding_Rightsize_2015_01_06] AS
SELECT TOP 100 PERCENT 
		LoanAppID			= BID.LoanAppID,
		LoanApp_BidID		= BID.LoanApp_BidID,
		ApplicationID		= CONVERT(VARCHAR(16), BID.LoanAppID) + '-' + CONVERT(VARCHAR(16), BID.LoanApp_BidID),
		Funded				= CONVERT(BIT, CASE WHEN BID.Funded_Date IS NOT NULL THEN 1 WHEN Bid.Funded = 1 THEN 1 ELSE 0 END),
		Vehicle				= CASE WHEN Worksheet.LoanApp_WorksheetID IS NULL THEN DBO.VehicleDescription(App.Vehicle_Year, App.Vehicle_Make, App.Vehicle_Model, App.Vehicle_Mileage, App.Vehicle_VIN) ELSE DBO.VehicleDescription(Worksheet.Vehicle_Year, Worksheet.Vehicle_Make, Worksheet.Vehicle_Model, Worksheet.Vehicle_Mileage, Worksheet.Vehicle_VIN) END,
		Applicants			= App.Applicant_Names,
		Status				= BID.Status,
		DealerID			= Dealer.DealerID,
		Dealer				= Dealer.DealerName,
		DateFunded			= BID.Funded_Date,
		LenderID			= Lender.LenderID,
		LendersBranchID		= Branch.LendersBranchID,
		LenderName			= Lender.LenderName,
		LastUpdate			= ISNULL(PDE_Sent.DataValue, CONVERT(dateTime, '2013-01-01')),
		CustomerNumber		= ISNULL(LDR.CustomerNumber,	''),
		--PostURL			= PDE_URL.DataValue,
		--PostUser			= PDE_USER.DataValue,
		--PostPassword		= PDE_PWD.DataValue,
		--PullURL				= 'http://legacy.creditsmarts.com/CreditSmarts/v2/Partners/Outbound.asp?Native=1&LoanAppID=' + CONVERT(VARCHAR(16), BID.LoanAppID) + '&BidID=' + CONVERT(VARCHAR(16), BID.LoanApp_BidID),
		PullURL				= 'http://www.creditsmarts.com/CreditSmarts/v2/Partners/Outbound.asp?Native=1&LoanAppID=' + CONVERT(VARCHAR(16), BID.LoanAppID) + '&BidID=' + CONVERT(VARCHAR(16), BID.LoanApp_BidID),
		IsSent				= CONVERT(BIT, CASE WHEN ISDATE(PDE_Sent.DataValue)	= 1 THEN 1 ELSE 0 END),
		CreateDateTime		= BID.CreateDateTime
		--XSLT				= PTT.XML,
		--U.CONTRACT_DATE,
		--FUNDING_DISCOUNT_FEE = ISNULL(U.FUNDING_DISCOUNT_FEE, 0)
	FROM
					tblLoanApp_Bids					BID			WITH (NOLOCK)
		INNER JOIN	tblLoanApps						App			WITH (NOLOCK) ON App.LoanAppID				= Bid.LoanAppID
		INNER JOIN	tblDealers						Dealer		WITH (NOLOCK) ON Dealer.DealerID			= App.DealerID
		INNER JOIN	tblLendersBranches				Branch		WITH (NOLOCK) ON Branch.LendersBranchID		= BID.LendersBranchID
		INNER JOIN	tblLenders						Lender		WITH (NOLOCK) ON Lender.LenderID			= Branch.LenderID		
		INNER JOIN	tblLenderDealerRelation			LDR			WITH (NOLOCK) ON LDR.LenderID				= Lender.LenderID 			AND	LDR.DealerID		= Dealer.DealerID	
		LEFT JOIN	tblPartnerDataElement 			PDE_Sent	WITH (NOLOCK) ON PDE_Sent.LoanApp_BidID		= BID.LoanApp_BidID			AND	PDE_Sent.Field		= 'FundingLastSendDate'
		LEFT JOIN	tblLoanApp_Worksheet			Worksheet	WITH (NOLOCK) ON Worksheet.LoanApp_BidID	= Bid.LoanApp_BidID			AND Worksheet.Active	= 1
		--INNER JOIN tblPartnerToolsTriggers				PTT			WITH (NOLOCK)
		--	ON	PTT.PartnerToolID = R.PartnerToolID
		--	AND PTT.TYPE = 'EXCHANGE'	

		--INNER JOIN tblPartnerDataElement				PDE_URL			WITH (NOLOCK)
		--	ON PDE_URL.LenderID = BID.LenderID
		--	AND PDE_URL.PartnerToolID = PTT.PartnerToolID
		--	AND PDE_URL.Field='POST_URL_FOR_FUNDING'
		--	AND PDE_URL.Active = 1
		
		--INNER JOIN tblPartnerDataElement				PDE_USER			WITH (NOLOCK)
		--	ON PDE_USER.LenderID = BID.LenderID
		--	AND PDE_USER.PartnerToolID = PTT.PartnerToolID
		--	AND PDE_USER.Field='POST_USER_FOR_FUNDING'
		--	AND PDE_USER.Active = 1

		--INNER JOIN tblPartnerDataElement				PDE_PWD			WITH (NOLOCK)
		--	ON PDE_PWD.LenderID = BID.LenderID
		--	AND PDE_PWD.PartnerToolID = PTT.PartnerToolID
		--	AND PDE_PWD.Field='POST_PASSWORD_FOR_FUNDING'
		--	AND PDE_PWD.Active = 1


		--LEFT OUTER JOIN tblPartnerToolStatus			PTS			WITH (NOLOCK)
		--	ON	BID.LoanApp_BidID = PTS.LoanApp_BidID
		--	AND PTS.PartnerToolID = PTT.PartnerToolID
			
				

		--INNER JOIN tblLoanApp_Underwriting				U			WITH (NOLOCK)
		--	ON BId.LoanAppID = U.LoanAppID AND ISNULL(U.FUNDED , 0) = 1
	WHERE					
			Bid.CreateDateTime 		>		'2014-03-01'
		AND	BID.CANCELED_DATE		IS		NULL
		AND BID.STATUS				NOT IN	('DECLINE_LENDER')
		AND	(Bid.Funded = 1						OR		Bid.Funded_Date > '2014-03-01')
		AND (ISDATE(PDE_Sent.DataValue) = 0		OR		CONVERT(DATETIME, PDE_SENT.DataValue) < BID.Funded_Date)
		AND Lender.LenderID				= 1016
		--AND (LDR.CustomerNumber IS NOT NULL AND LEN(LDR.CustomerNumber) > 0)
		--AND (PTS.PostError IS NULL OR PTS.PostError <> 0)
	ORDER BY
		BID.FUNDED_DATE DESC

--OPTION (MAXDOP 1)























