/****** Object:  View dbo.viewB2B_PartnerElementValues_LenderMaster    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW viewB2B_PartnerElementValues_LenderMaster AS
	SELECT TOP 100 PERCENT
		FIELDS.PartnerToolID,
		FIELDS.PartnerElementDefinitionID,
		FIELDS.Field,
		FIELDS.ValueType,
		LENDER_MASTER.LenderID,
		PDE.PartnerDataElementID,
		DataValue = NULLIF(PDE.DataValue, '')
	FROM
		tblLenders																													LENDER_MASTER		WITH (NOLOCK)
		FULL OUTER JOIN viewB2B_PartnerElementDefinitions_LenderMaster 			FIELDS					WITH (NOLOCK) ON (1=1)
		LEFT JOIN tblPartnerDataElement PDE WITH (NOLOCK) ON (PDE.Field = FIELDS.Field AND PDE.LenderID = LENDER_MASTER.LenderID)
	ORDER BY
		LENDER_MASTER.LenderID,
		FIELDS.PartnerToolID,
		FIELDS.Field





