/****** Object:  View dbo.viewB2B_PartnerStatInit_TEST    Script Date: 7/31/2024 12:57:20 PM ******/


CREATE VIEW viewB2B_PartnerStatInit_TEST AS

SELECT TOP 100 PERCENT
  D.*,
  TRIGGER_SEND.XML
FROM
(SELECT DISTINCT
  B.LenderID,
  B.LenderName,
  B.LendersBranchID,
  B.BranchName,
  D.PartnerToolID,
  PartnerCode,
  URL,
  Username,
  Password,
  ISNULL(NULLIF(P.DisplayName, ''), D.PartnerCode) Name
FROM
  viewB2B_DecisionsOutstandingToSend_TEST D WITH (NOLOCK)
    INNER JOIN tblPartnerTools P WITH (NOLOCK) ON (D.PartnerToolID=P.PartnerToolID)
    INNER JOIN viewLenderBranches B WITH (NOLOCK) ON (B.LendersBranchID=D.LendersBranchID)) D

    INNER JOIN tblPartnerTools P WITH (NOLOCK) ON (D.PartnerToolID=P.PartnerToolID)
    INNER JOIN tblPartnerToolsTriggers TRIGGER_SEND WITH (NOLOCK) ON (TRIGGER_SEND.PartnerToolID=D.PartnerToolID AND TRIGGER_SEND.TYPE='SEND_DECISION')

ORDER BY
  D.PartnerCode

--PartnerToolID PartnerCode LoanApp_BidID Field DataValue LendersBranchID URL Username Password XML LastSentDateTime LastUpdateDateTime BidStatus






