/****** Object:  View dbo.viewB2B_PartnerToolsForDealerConsole    Script Date: 7/31/2024 12:57:20 PM ******/



CREATE VIEW [dbo].[viewB2B_PartnerToolsForDealerConsole] AS
	SELECT TOP 100 PERCENT
		PartnerToolID		= TOOL.PartnerToolID,
		LenderID			= TOOL.LenderID,
		Lender				= UPPER(LENDER.LenderName),
		PartnerCode,
		Partner,
		Display = RTRIM(LTRim(REPLACE(REPLACE(REPLACE(Partner, '®', '') , ' Integration', ''), ', LLC', ''))),
		HREF = '/CreditSmarts/v2/Partners/Management/Default.asp?PartnerToolID=' + LTRIM(STR(TOOL.PartnerToolID))
	FROM
					view_B2B_LendersActiveForPartnerTool	TOOL   WITH (NOLOCK)
		INNER JOIN	tblLenders								LENDER WITH (NOLOCK)	ON LENDER.LenderID = TOOL.LenderID
		INNER JOIN	tblPartnerDataElement 					PDE		WITH (NOLOCK)	ON PDE.LenderID = LENDER.LenderID AND PDE.PartnerToolID = TOOL.PartnerToolID AND PDE.Field In('Lender Enabled (CreditSmarts)') AND ISNULL(PDE.DataValue, '') = 'TRUE'
	WHERE
			--TOOL.PartnerToolID	IN (2, 12)
			TOOL.PartnerToolID	IN (2, 12, 58)
		AND	AuthorizedByCS=1
	ORDER BY
		Partner





