/****** Object:  View dbo.viewB2B_Pending    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewB2B_Pending AS
	SELECT
		LoanAppID					= ApplicationID.LoanAppID,
		LoanApp_BidID				= ApplicationID.LoanApp_BidID,
		PartnerToolID				= ApplicationID.PartnerToolID,
		Partner						= ApplicationID.Partner,
		PartnerAppID_Name			= ApplicationID.ID_Name,
		PartnerAppID				= ApplicationID.ID,
		BidStatus					= Dates.BidStatus,

		NeedToSend_Offer			= CONVERT(BIT, CASE		WHEN Dates.BidStatus			NOT IN		('PENDING_DEALER', 'DECLINE_LENDER')					THEN 0
															WHEN Dates.Decision_Date		IS			NULL													THEN 0
															WHEN LS_Offer.Date				IS			NULL													THEN 1
															WHEN LS_Offer.Date				<=			Dates.Decision_Date										THEN 1
																																								ELSE 0 END),

		NeedToSend_Messaging		= CONVERT(BIT, CASE		WHEN Messaging.MessageCount		=			0														THEN 0
															WHEN Messaging.Newest			IS 			NULL													THEN 0
															WHEN LS_Messaging.Date			IS 			NULL													THEN 1
															WHEN LS_Messaging.Date			<=			Messaging.Newest										THEN 1
															WHEN LS_Messaging.Date			<=			Messaging.Oldest										THEN 1
																																								ELSE 0 END),

		NeedToSend_Funding			= CONVERT(BIT, CASE		WHEN Dates.Funded_Date			IS 			NULL													THEN 0
															WHEN LS_Funding.Date			IS 			NULL													THEN 1
															WHEN LS_Funding.Date			<=			Dates.Funded_Date										THEN 1
																																								ELSE 0 END),
		Submit_Date					= Dates.Submit_Date,
		Decision_Date				= Dates.Decision_Date,
		Funded_Date					= Dates.Funded_Date,
		Newest_Message				= Messaging.Newest,
		Offer_Sent					= LS_Offer.Date,
		Funding_Sent				= LS_Funding.Date,
		Messaging_Sent				= LS_Messaging.Date

		/*
		Message_Count_Dealer		= Messaging.MessageCount_Dealer,
		Message_First_Dealer		= Messaging.Oldest_Dealer,
		Message_Last_Dealer			= Messaging.Newest_Dealer,

		Message_Count_Lender		= Messaging.MessageCount_Lender,
		Message_First_Lender		= Messaging.Oldest_Lender,
		Message_Last_Lender			= Messaging.Newest_Lender,

		Message_Count				= Messaging.MessageCount,
		Message_First				= Messaging.Oldest,
		Message_First_Source		= Messaging.Oldest_Source,
		Message_Last_Source			= Messaging.Newest_Source
		*/
	FROM
					viewB2B_PartnerApplicationID		ApplicationID		WITH (NOLOCK)
			 JOIN	viewB2B_Bids_Dates					Dates				WITH (NOLOCK) ON Dates.LoanApp_BidID			= ApplicationID.LoanApp_BidID
			 JOIN	tblLoanApp_Bids						Bids				WITH (NOLOCK) ON Bids.LoanApp_BidID				= ApplicationID.LoanApp_BidID
			 JOIN	tblLoanApps							Application			WITH (NOLOCK) ON Application.LoanAppID			= Bids.LoanAppID
			 JOIN	tblLendersBranches					Branch				WITH (NOLOCK) ON Branch.LendersBranchID			= Bids.LendersBranchID
			 JOIN	tblLenders							Lender				WITH (NOLOCK) ON Lender.LenderID				= Branch.LenderID
			 JOIN	tblDealers							Dealer				WITH (NOLOCK) ON Dealer.DealerID				= Application.DealerID
		LEFT JOIN	viewB2B_LastSent_Offer				LS_Offer			WITH (NOLOCK) ON LS_Offer.LoanApp_BidID			= ApplicationID.LoanApp_BidID	AND LS_Offer.PartnerToolID		= ApplicationID.PartnerToolID
		LEFT JOIN	viewB2B_LastSent_Messaging			LS_Messaging		WITH (NOLOCK) ON LS_Messaging.LoanApp_BidID		= ApplicationID.LoanApp_BidID	AND LS_Messaging.PartnerToolID	= ApplicationID.PartnerToolID
		LEFT JOIN	viewB2B_LastSent_Funding			LS_Funding			WITH (NOLOCK) ON LS_Funding.LoanApp_BidID		= ApplicationID.LoanApp_BidID	AND LS_Funding.PartnerToolID	= ApplicationID.PartnerToolID
		LEFT JOIN	viewCommentLogMetaData				Messaging			WITH (NOLOCK) ON Messaging.LoanApp_BidID		= ApplicationID.LoanApp_BidID

	WHERE
		ApplicationID.LoanApp_BidID >= (SELECT MIN(LoanApp_BidID) FROM tblLoanApp_Bids WITH (NOLOCK) WHERE CreateDateTime >= DATEADD(d, -90, GETDATE()))




GO

