/****** Object:  View dbo.viewB2B_Pinnacle_OutstandingFunding_2016_08_29    Script Date: 7/31/2024 12:57:20 PM ******/

create  VIEW viewB2B_Pinnacle_OutstandingFunding_2016_08_29 AS
	SELECT TOP 100 PERCENT --SELECT DISTINCT TOP 100 PERCENT 
--		LastStatus.*,

		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= Bid.LoanApp_BidID,
		ApplicationID			= LTRIM(STR(Bid.LoanAppID)) + '-' + LTRIM(STR(Bid.LoanApp_BidID)),
		Vehicle					= CASE WHEN Worksheet.LoanApp_WorksheetID IS NULL THEN DBO.VehicleDescription(Application.Vehicle_Year, Application.Vehicle_Make, Application.Vehicle_Model, Application.Vehicle_Mileage, Application.Vehicle_VIN) ELSE DBO.VehicleDescription(Worksheet.Vehicle_Year, Worksheet.Vehicle_Make, Worksheet.Vehicle_Model, Worksheet.Vehicle_Mileage, Worksheet.Vehicle_VIN) END,
		Applicants				= UPPER(Application.Applicant_Names),
		Customer				= UPPER(Application.Applicant_Names),
		Status					= UPPER(Bid.Status),
		DealerID				= Dealer.DealerID,
		Dealer					= UPPER(Dealer.DealerName),
		DateFunded				= Bid.Funded_Date,
		BidFundingStatus		= ISNULL(BidFundingStatus.BidFundingStatus, ''),
		LenderID				= Branch.LenderID,
		Lender						= UPPER(LENDER.LenderName),
		LendersBranchID			= Bid.LendersBranchID,
		LenderName				= UPPER(Lender.LenderName),
		LenderPrefix				= LENDER.LoginPrefix,
		Branch						= UPPER(BRANCH.BranchName),
		BranchPrefix				= CASE WHEN LEN(RTRIM(LTRIM(ISNULL(BRANCH.LoginPrefix, '')))) = 0 THEN LENDER.LoginPrefix ELSE BRANCH.LoginPrefix END,

		LastSent				= LastStatus.UpdateDateTime,
		LastUpdate				= ISNULL(LastStatus.UpdateDateTime, CONVERT(dateTime, '2011-01-01')),
		PartnerToolID			= PartnerTool.PartnerToolID,
		PostURL				= ISNULL(ELEMENT_FUNDING_URL.DataValue,	''),
		PostUser			= ISNULL(ELEMENT_FUNDING_USER.DataValue,	''),
		PostPassword			= ISNULL(ELEMENT_FUNDING_PASSWORD.DataValue,''),
FUNDING_SENDING_QUEUED.PartnerDataElementID,
		PullURL					= 'https://www.CreditSmarts.com/CreditSmarts/v2/Partners/Outbound.asp?Nocache=1&cache=0&Native=1&BidID=' + LTRIM(STR(Bid.LoanApp_BidID)),


CUSTOM_CREDIT_SCORE.Score as CustomCreditScore,
CUSTOM_CREDIT_SCORE.CreateDateTime as CustomCreditScoreCreateDateTime,
CUSTOM_CREDIT_SCORE.UpdateDateTime as CustomCreditScoreUpadateDateTime,

ApplicationNumber = ISNULL(SOURCE.DataValue, ''),

ISNULL(BID.Counter, 0) Counter

,RelationshipName =
	CASE
		WHEN (Application.LenderID IS NOT NULL AND Application.LenderID > 0)   THEN 'Internal'
		WHEN (Application.LenderID IS NULL AND SOURCE.LoanApp_BidID IS NOT NULL) THEN SOURCE_TOOL.ShortName
--ISNULL(SOURCE_TOOL.DisplayName, SOURCE_TOOL.ShortName)
		ELSE 'CreditSmarts'
	END,


		CreditReportAccount = CASE
			WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN CONVERT(BIT, 1)
			WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0) END,

		CreditReportAccountSource = CASE
			WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN 'LENDER_BRANCH'
			WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN 'LENDER_MASTER'
			ELSE 'NONE' END,

		CreditReportUserName = CASE
			WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(BRANCH.MicroBilt_Login))
			WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(LENDER.MicroBilt_Login))
			ELSE '' END,

		CreditReportPassword = CASE
			WHEN LEN(ISNULL(BRANCH.Microbilt_Login, '')) > 0 AND LEN(ISNULL(BRANCH.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(BRANCH.MicroBilt_Password))
			WHEN LEN(ISNULL(LENDER.Microbilt_Login, '')) > 0 AND LEN(ISNULL(LENDER.Microbilt_Password, '')) > 0 THEN LTRIM(RTRIM(LENDER.MicroBilt_Password))
			ELSE '' END,

		Automation_Bureau = LENDER.AUTOMATION_CREDIT_PROVIDER,

		Existing_Bureau = CASE
			WHEN ISNULL(Lender.AUTOMATION_CREDIT_PROVIDER, '') = 'EX' AND LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) = 38 AND CREDIT_EX.BUREAU = 'EX'	THEN BID.LENDER_CREDIT_EX
			WHEN ISNULL(Lender.AUTOMATION_CREDIT_PROVIDER, '') = 'TU' AND LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) = 38 AND CREDIT_TU.BUREAU = 'TU'	THEN BID.LENDER_CREDIT_TU
			WHEN ISNULL(Lender.AUTOMATION_CREDIT_PROVIDER, '') = 'EQ' AND LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) = 38 AND CREDIT_EQ.BUREAU = 'EQ'	THEN BID.LENDER_CREDIT_EQ

			WHEN ISNULL(Lender.AUTOMATION_CREDIT_PROVIDER, '') = 'EX' AND LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) <> 38	THEN ''
			WHEN ISNULL(Lender.AUTOMATION_CREDIT_PROVIDER, '') = 'TU' AND LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) <> 38	THEN ''
			WHEN ISNULL(Lender.AUTOMATION_CREDIT_PROVIDER, '') = 'EQ' AND LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) <> 38	THEN ''
			WHEN 														  LEN(ISNULL(BID.LENDER_CREDIT_EX, ''))  = 38	THEN BID.LENDER_CREDIT_EX
			WHEN														  LEN(ISNULL(BID.LENDER_CREDIT_TU, ''))  = 38	THEN BID.LENDER_CREDIT_TU
			WHEN														  LEN(ISNULL(BID.LENDER_CREDIT_EQ, ''))  = 38	THEN BID.LENDER_CREDIT_EQ
			ELSE '' END,
		Age					= DATEDIFF(s, BID.UpdateDateTime, GETDATE()),

		CollectorValue = ISNULL(Collector.DataValue, ''),
		LoanApproveEmpValue = ISNULL(LoanApproveEmp.DataValue, ''),
		CarLocSaleValue = ISNULL(CarLocSale.DataValue, ''),
		LoanCodeValue = ISNULL(LoanCode.DataValue, ''),
		LoanTypeValue = ISNULL(LoanType.DataValue, ''),
		CurrLoanOwnerValue = ISNULL(CurrLoanOwner.DataValue, '')
/*
 Collector
 LoanApproveEmp
 CarLocSale
 LoanCode
 LoanType
 CurrLoanOwner 
*/

FROM
		tblLoanApp_Bids						Bid			WITH (NOLOCK)
		LEFT	JOIN	tblLoanApp_Worksheet			Worksheet		WITH (NOLOCK)		ON Worksheet.LoanApp_BidID	= Bid.LoanApp_BidID		AND Worksheet.Active = 1				
--		LEFT	JOIN	tblLoanApp_Bids_LastStatus		LastStatus 		WITH (NOLOCK)		ON Bid.LoanApp_BidID		= LastStatus.LoanApp_BidID
		LEFT	JOIN	tblLoanApp_BidFundingStatus		BidFundingStatus				WITH (NOLOCK)		ON BidFundingStatus.LoanApp_BidID		= Bid.LoanApp_BidID
		INNER	JOIN	tblLoanApps				Application		WITH (NOLOCK)		ON Application.LoanAppID			= Bid.LoanAppID
		INNER	JOIN	tblDealers				Dealer			WITH (NOLOCK)		ON Dealer.DealerID			= Application.DealerID
		INNER	JOIN	tblLendersBranches			Branch			WITH (NOLOCK)		ON Branch.LendersBranchID	= Bid.LendersBranchID
		INNER	JOIN	tblLenders				Lender			WITH (NOLOCK)		ON Lender.LenderID			= Branch.LenderID
		INNER	JOIN	tblPartnerTools				PartnerTool			WITH (NOLOCK)		ON PartnerTool.Shortname			= 'PINNACLE'
--		INNER	JOIN	viewB2B_LenderPartnerParametersEx 	ToolParameters		WITH (NOLOCK)		ON PartnerTool.PartnerToolID		= ToolParameters.PartnerToolID		AND	ToolParameters.LendersBranchID = Bid.LendersBranchID

		LEFT	JOIN	tblPartnerDataElement			LastStatus				WITH (NOLOCK)		
			ON LastStatus.LoanApp_BidID		= Bid.LoanApp_BidID
			AND LastStatus.LenderID = Branch.LenderID
			AND LastStatus.PartnerToolID = PartnerTool.PartnerToolID
			AND LastStatus.Field = 'FUNDING_SENDING_DATE'
			AND LEN(ISNULL(LastStatus.DataValue, '')) > 0

		LEFT	JOIN	tblPartnerDataElement			FUNDING_SENDING_QUEUED				WITH (NOLOCK)		
			ON FUNDING_SENDING_QUEUED.LoanApp_BidID		= Bid.LoanApp_BidID				
			AND FUNDING_SENDING_QUEUED.LenderID = Branch.LenderID
			AND FUNDING_SENDING_QUEUED.PartnerToolID = PartnerTool.PartnerToolID
			AND FUNDING_SENDING_QUEUED.Field = 'FUNDING_SENDING_QUEUED'

		LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_URL			WITH (NOLOCK)	
			ON	PartnerTool.PartnerToolID	= ELEMENT_FUNDING_URL.PartnerToolID				
			AND ELEMENT_FUNDING_URL.Field			= 'POST_URL_FOR_FUNDING'						
			AND ELEMENT_FUNDING_URL.LenderID		= BRANCH.LenderID

		LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_USER			WITH (NOLOCK)   
			ON	PartnerTool.PartnerToolID	= ELEMENT_FUNDING_USER.PartnerToolID			
			AND ELEMENT_FUNDING_USER.Field			= 'POST_USER_FOR_FUNDING'			
			AND ELEMENT_FUNDING_USER.LenderID		= BRANCH.LenderID

		LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_PASSWORD		WITH (NOLOCK)   
			ON	PartnerTool.PartnerToolID	= ELEMENT_FUNDING_PASSWORD.PartnerToolID		
			AND ELEMENT_FUNDING_PASSWORD.Field		= 'POST_PASSWORD_FOR_FUNDING'		
			AND ELEMENT_FUNDING_PASSWORD.LenderID	= BRANCH.LenderID

		LEFT JOIN tblPartnerDataElement		ELEMENT_DECISIONS_ENABLED		WITH (NOLOCK)	
			ON	PartnerTool.PartnerToolID	= ELEMENT_DECISIONS_ENABLED.PartnerToolID		
			AND ELEMENT_DECISIONS_ENABLED.Field		= 'Lender Enabled (CreditSmarts)' 	
			AND ELEMENT_DECISIONS_ENABLED.LenderID	= BRANCH.LenderID


		 LEFT JOIN tblPartnerDataElement				Collector		WITH (NOLOCK)
			ON Collector.LenderID = Branch.LenderID
			AND Collector.PartnerToolID = PartnerTool.PartnerToolID
			AND Collector.Field='Collector'
			AND Collector.Active = 1

		 LEFT JOIN tblPartnerDataElement				LoanApproveEmp		WITH (NOLOCK)
			ON LoanApproveEmp.LenderID = Branch.LenderID
			AND LoanApproveEmp.PartnerToolID = PartnerTool.PartnerToolID
			AND LoanApproveEmp.Field='LoanApproveEmp'
			AND LoanApproveEmp.Active = 1

		 LEFT JOIN tblPartnerDataElement				CarLocSale		WITH (NOLOCK)
			ON CarLocSale.LenderID = Branch.LenderID
			AND CarLocSale.PartnerToolID = PartnerTool.PartnerToolID
			AND CarLocSale.Field='CarLocSale'
			AND CarLocSale.Active = 1

		 LEFT JOIN tblPartnerDataElement				LoanCode		WITH (NOLOCK)
			ON LoanCode.LenderID = Branch.LenderID
			AND LoanCode.PartnerToolID = PartnerTool.PartnerToolID
			AND LoanCode.Field='LoanCode'
			AND LoanCode.Active = 1

		 LEFT JOIN tblPartnerDataElement				LoanType		WITH (NOLOCK)
			ON LoanType.LenderID = Branch.LenderID
			AND LoanType.PartnerToolID = PartnerTool.PartnerToolID
			AND LoanType.Field='LoanType'
			AND LoanType.Active = 1

		 LEFT JOIN tblPartnerDataElement				CurrLoanOwner		WITH (NOLOCK)
			ON CurrLoanOwner.LenderID = Branch.LenderID
			AND CurrLoanOwner.PartnerToolID = PartnerTool.PartnerToolID
			AND CurrLoanOwner.Field='CurrLoanOwner'
			AND CurrLoanOwner.Active = 1



		left JOIN tblLoanApp_Underwriting				U			WITH (NOLOCK)
			ON BId.LoanAppID = U.LoanAppID AND U.LenderID = Branch.LenderID AND ISNULL(U.FUNDED , 0) = 1

		LEFT JOIN tblLoanApp_CustomCreditScore CUSTOM_CREDIT_SCORE WITH (NOLOCK) ON (CUSTOM_CREDIT_SCORE.LoanApp_BidID=BID.LoanApp_BidID)	

		LEFT JOIN tblPartnerDataElement SOURCE on SOURCE.LoanApp_BidID = BID.LoanApp_BidID
		JOIN tblPartnerElementDefinition SOURCE_DEFINITION on SOURCE_DEFINITION.Field = SOURCE.Field AND SOURCE_DEFINITION.ValueType = 'PARTNER_LOAN_ID'
		JOIN tblPartnerTools SOURCE_TOOL on SOURCE_TOOL.partnertoolid = SOURCE.PartnerToolID

		LEFT	JOIN tblCreditPulls	CREDIT_EX	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(BID.Lender_Credit_EX, '')) = 1	AND	ISNULL(Credit_EX.Bureau, '') IN('EX', '')	AND	Credit_EX.GUID				= NULLIF(BID.Lender_Credit_EX, '')
		LEFT	JOIN tblCreditPulls	CREDIT_TU	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(BID.Lender_Credit_TU, '')) = 1	AND	ISNULL(Credit_TU.Bureau, '') IN('TU', '')	AND	Credit_TU.GUID				= NULLIF(BID.Lender_Credit_TU, '')
		LEFT	JOIN tblCreditPulls	CREDIT_EQ	WITH (NOLOCK) ON DBO.IsGUID(NULLIF(BID.Lender_Credit_EQ, '')) = 1	AND	ISNULL(Credit_EQ.Bureau, '') IN('EQ', '')	AND	Credit_EQ.GUID				= NULLIF(BID.Lender_Credit_EQ, '')



	WHERE
			(		Bid.CreateDateTime		> DATEADD(d, -60, GETDATE())
				OR	Bid.UpdateDateTime		> DATEADD(d, -60, GETDATE())
				OR	Bid.Submit_Date			> DATEADD(d, -60, GETDATE())
				OR	Bid.Offer_Date			> DATEADD(d, -60, GETDATE())
or 1=1
			)

		AND	(Bid.CreateDateTime	> '2009-09-01' )
		AND 	(Bid.Funded_Date > '2014-12-10')


		--AND LEN(RTRIM(LTRIM(ISNULL(ToolParameters.PostURL, ''))))					> 0
		--AND LEN(RTRIM(LTRIM(ISNULL(ToolParameters.PostUser, ''))))					> 0
		--AND LEN(RTRIM(LTRIM(ISNULL(ToolParameters.PostPassword, ''))))				> 0
		AND Bid.STATUS 		NOT IN	('DECLINE_Lender')
		AND PartnerTool.Active	= 1


		--AND Bid.LoanApp_BidID = 838705

		AND	(	BidFundingStatus.BidFundingStatus 	IN	('RECEIVED', 'REJECTED', 'FUNDED')
				OR	Bid.Funded_Date 		>	CONVERT(datetime, '2010-12-01')	
				--or  1=1
			)


		/*
		AND (		LastStatus.UpdateDateTime IS NULL 
				OR	Bid.Funded_Date > LastStatus.UpdateDateTime
		)
		*/


		AND	(		BidFundingStatus.StatusUpdateDateTime	IS NULL
				OR	LastStatus.UpdateDateTime		IS NULL
				OR	BidFundingStatus.StatusUpdateDateTime > LastStatus.UpdateDateTime	
				OR (
					Bid.Funded_Date IS NOT NULL
					AND ISNULL(LastStatus.UpdateDateTime, '2010-04-01') < Bid.Funded_Date
				)
				--or 1=1
			)
AND (U.Contract_Date IS NOT NULL AND U.First_Pay_Date IS NOT NULL)
AND (
	FUNDING_SENDING_QUEUED.PartnerDataElementID IS NOT NULL 
--	OR bid.loanapp_bidid=1161067
)
--	ORDER BY		Bid.FUNDED_DATE DESC

GROUP BY
 Bid.LoanAppID, Bid.LoanApp_BidID, Bid.LoanApp_BidID, Application.VEHICLE_VIN, Application.VEHICLE_MILEAGE, Application.VEHICLE_MODEL, Application.VEHICLE_MAKE,
 Application.VEHICLE_YEAR, Worksheet.LoanApp_WorksheetID, Worksheet.VEHICLE_VIN, Worksheet.VEHICLE_MILEAGE, Worksheet.VEHICLE_MODEL, Worksheet.VEHICLE_MAKE,
 Worksheet.VEHICLE_YEAR, Application.APPLICANT_NAMES, Application.APPLICANT_NAMES, Bid.STATUS, Dealer.DealerID, Dealer.DealerName, Bid.FUNDED_DATE,
 BidFundingStatus.BidFundingStatus, Branch.LenderID, Lender.LenderName, Bid.LendersBranchID, Lender.LenderName, Lender.LoginPrefix, Branch.BranchName,
 Lender.LoginPrefix, Branch.LoginPrefix, Branch.LoginPrefix, LastStatus.UpdateDateTime, LastStatus.UpdateDateTime, PartnerTool.PartnerToolID,
 ELEMENT_FUNDING_URL.DataValue, ELEMENT_FUNDING_USER.DataValue, ELEMENT_FUNDING_PASSWORD.DataValue, FUNDING_SENDING_QUEUED.PartnerDataElementID,
 Bid.LoanApp_BidID, CUSTOM_CREDIT_SCORE.Score, CUSTOM_CREDIT_SCORE.CreateDateTime, CUSTOM_CREDIT_SCORE.UpdateDateTime, SOURCE.DataValue, Bid.COUNTER,
 Application.LenderID, Application.LenderID, SOURCE_TOOL.ShortName, Application.LenderID, SOURCE.LoanApp_BidID, Branch.Microbilt_Login,
 Branch.Microbilt_Password, Lender.Microbilt_Login, Lender.Microbilt_Password, Branch.Microbilt_Login, Branch.Microbilt_Password, Lender.Microbilt_Login,
 Lender.Microbilt_Password, Branch.Microbilt_Login, Branch.Microbilt_Login, Branch.Microbilt_Password, Lender.Microbilt_Login, Lender.Microbilt_Login,
 Lender.Microbilt_Password, Branch.Microbilt_Password, Branch.Microbilt_Login, Branch.Microbilt_Password, Lender.Microbilt_Password, Lender.Microbilt_Login,
 Lender.Microbilt_Password, Lender.AUTOMATION_CREDIT_PROVIDER, Bid.LENDER_CREDIT_EX, Lender.AUTOMATION_CREDIT_PROVIDER, Bid.LENDER_CREDIT_EX, CREDIT_EX.Bureau,
 Bid.LENDER_CREDIT_TU, Lender.AUTOMATION_CREDIT_PROVIDER, Bid.LENDER_CREDIT_TU, CREDIT_TU.Bureau, Bid.LENDER_CREDIT_EQ, Lender.AUTOMATION_CREDIT_PROVIDER,
 Bid.LENDER_CREDIT_EQ, CREDIT_EQ.Bureau, Lender.AUTOMATION_CREDIT_PROVIDER, Bid.LENDER_CREDIT_EX, Lender.AUTOMATION_CREDIT_PROVIDER, Bid.LENDER_CREDIT_TU,
 Lender.AUTOMATION_CREDIT_PROVIDER, Bid.LENDER_CREDIT_EQ, Bid.LENDER_CREDIT_EX, Bid.LENDER_CREDIT_EX, Bid.LENDER_CREDIT_TU, Bid.LENDER_CREDIT_TU,
 Bid.LENDER_CREDIT_EQ, Bid.LENDER_CREDIT_EQ, Bid.UpdateDateTime, Collector.DataValue, LoanApproveEmp.DataValue, CarLocSale.DataValue, LoanCode.DataValue,
 LoanType.DataValue, CurrLoanOwner.DataValue






