/****** Object:  View dbo.viewB2B_RawPartnerXML    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE VIEW [viewB2B_RawPartnerXML] AS
	SELECT
		[Partner].[PartnerToolID],
		[Partner].[ShortName],
		[Branch].[LenderID],
		[Bid].[LendersBranchID],
		[Bid].[LoanAppID],
		[Bid].[LoanApp_BidID],
		[File].[File],
		[XML].[ContentType],
		[XML].[ContentLength],
		[XML].[ContentHash],
		[XML].[Content]
	FROM
				[tblPartnerXML]							[XML]		WITH (NOLOCK)
		JOIN	[tblPartnerTools]						[Partner]	WITH (NOLOCK) ON	[Partner].[PartnerToolID]		= [XML].[PartnerToolID]
		JOIN	[tblLoanApp_Bids]						[Bid]		WITH (NOLOCK) ON	[Bid].[LoanApp_BidID]			= [XML].[LoanApp_BidID]
		JOIN	[tblLendersBranches]					[Branch]	WITH (NOLOCK) ON	[Branch].[LendersBranchID]		= [Bid].[LendersBranchID]
		JOIN	[viewB2B_RawPartnerFileLocations]		[File]		WITH (NOLOCK) ON	[File].[PartnerToolID]			= [Partner].[PartnerToolID]		AND
																						[File].[LoanApp_BidID]			= [Bid].[LoanApp_BidID]

