/****** Object:  View dbo.viewB2B_RawPartnerXMLFileImport    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE VIEW viewB2B_RawPartnerXMLFileImport AS
	SELECT TOP 100 PERCENT
		[File].*
	FROM 
				[viewB2B_RawPartnerFileLocations]		[File]	WITH (NOLOCK) 
		JOIN	[tblLoanApp_Bids]						[Bid]	WITH (NOLOCK) ON [Bid].[LoanApp_BidID]	= [File].[LoanApp_BidID]
		JOIN	[tblLoanApps]							[App]	WITH (NOLOCK) ON [App].[LoanAppID]		= [Bid].[LoanAppID]
	WHERE 
		[App].[CreateDateTime] >= DATEADD(d, -15, GETDATE())
		AND NOT EXISTS(SELECT * FROM [tblPartnerXML] [XML] WITH (NOLOCK) WHERE [XML].[PartnerToolID] = [File].[PartnerToolID] AND [XML].[LoanApp_BidID] = [File].[LoanApp_BidID])
	GROUP BY 
		[File].[PartnerToolID],
		[File].[PartnerTool],
		[File].[LoanAppID],
		[File].[LoanApp_BidID],
		[File].[LenderID],
		[File].[LendersBranchID],
		[File].[DealerID],
		[File].[File]
	ORDER BY
		[File].[LoanApp_BidID] DESC

