/****** Object:  View dbo.viewB2B_ResendData    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewB2B_ResendData AS
--SELECT TOP 50 * FROM viewLenderBranches_Simple;

	SELECT --TOP 10
		PARTNER_TOOL.PartnerToolID,
		Partner 						= PARTNER_TOOL.ShortName,
		PartnerActive					= ISNULL(PARTNER_TOOL.ACTIVE, 1),
		LoanAppID						= BIDS.LoanAppID,
		LoanApp_BidID					= BIDS.LoanApp_BidID,
		--Partner_Application_ID_Name		= LOAN_INFO.Identifier,
		--Partner_Application_ID			= LOAN_INFO.ID,
		LenderID						= LENDER_BRANCH.LenderID,
		LendersBranchID					= LENDER_BRANCH.LendersBranchID,
		Lender							= LENDER_BRANCH.DisplayName,
		DealerID						= DEALER.DealerID,
		DealerName						= DEALER.DealerName,
		Date_BidUpdate					= BIDS.UpdateDateTime,
		Date_Offer						= BIDS.OFFER_DATE,
		Date_Funded						= BIDS.FUNDED_DATE,
		Date_Sent						= LAST_SENT.Date_LastSent,
		Date_UWUpdate					= UNDERWRITING.UpdateDateTime,
	
		Resend	= CONVERT(BIT, CASE
			WHEN BIDS.OFFER_DATE				IS NULL						THEN 0
			WHEN BIDS.UpdateDateTime			IS NULL						THEN 0
			WHEN LAST_SENT.Date_LastSent		IS NULL						THEN 1
	
			WHEN BIDS.Funded_Date IS NULL AND BIDS.Offer_Date IS NOT NULL AND ABS(DATEDIFF(ss, BIDS.Offer_Date, LAST_SENT.Date_LastSent)) < 60	THEN 0
			WHEN BIDS.Offer_Date				> LAST_SENT.Date_LastSent	THEN 1
	--		WHEN BIDS.UpdateDateTime			> LAST_SENT.Date_LastSent	THEN 1
			WHEN BIDS.FUNDED_DATE				IS NULL						THEN 0
			WHEN BIDS.FUNDED_DATE				> LAST_SENT.Date_LastSent	THEN 1
			WHEN UNDERWRITING.UpdateDateTime	IS NULL						THEN 0
			WHEN DATEDIFF(dd, BIDS.Funded_Date, UNDERWRITING.UpdateDateTime) > 60 THEN 0
			WHEN UNDERWRITING.UpdateDateTime	> LAST_SENT.Date_LastSent	THEN 1
			ELSE 0 END),
	
		Resend_Never_Sent		= CONVERT(BIT, CASE WHEN LAST_SENT.Date_LastSent IS NULL THEN 1 ELSE 0 END),
	
		Resend_Update_Decision	= CONVERT(BIT, CASE
			WHEN BIDS.OFFER_DATE			IS	NULL									THEN 0
			WHEN BIDS.FUNDED_DATE			IS	NOT NULL								THEN 0
			WHEN BIDS.UpdateDateTime		IS	NULL									THEN 0
			WHEN LAST_SENT.Date_LastSent	>		BIDS.Offer_Date						THEN 0
			WHEN ABS(DATEDIFF(ss, BIDS.Offer_Date, LAST_SENT.Date_LastSent)) < 60		THEN 0
			WHEN BIDS.Offer_Date			>	LAST_SENT.Date_LastSent					THEN 1
			ELSE 0 END),		
	
		Resend_Update_Funding	= CONVERT(BIT, CASE
			WHEN LAST_SENT.Date_LastSent		IS NULL						THEN 0
			WHEN BIDS.FUNDED_DATE				IS NULL						THEN 0
			WHEN BIDS.FUNDED_DATE				> LAST_SENT.Date_LastSent	THEN 1
			WHEN UNDERWRITING.UpdateDateTime	IS NULL						THEN 0
			WHEN DATEDIFF(dd, BIDS.Funded_Date, UNDERWRITING.UpdateDateTime) > 60 THEN 0
			WHEN UNDERWRITING.UpdateDateTime	> LAST_SENT.Date_LastSent	THEN 1
			ELSE 0 END),

		UWAge = DATEDIFF(dd, BIDS.Funded_Date, UNDERWRITING.UpdateDateTime)
	
	
	FROM
						tblLoanApp_Bids					BIDS				WITH (NOLOCK)
--		INNER JOIN		viewB2B_PartnerLoanIdentifiers	LOAN_INFO			WITH (NOLOCK) ON LOAN_INFO.LoanApp_BidID = BIDS.LoanApp_BidID
		INNER JOIN		tblPartnerDataElement	 		ELEMENT				WITH (NOLOCK) ON BIDS.LoanApp_BidID	= ELEMENT.LoanApp_BidID AND ELEMENT.DataValue IS NOT NULL AND LEN(ELEMENT.DataValue) > 0
		INNER JOIN		tblPartnerElementDefinition		DEFINITION_APP_ID	WITH (NOLOCK) ON DEFINITION_APP_ID.PartnerToolID = ELEMENT.PartnerToolID AND DEFINITION_APP_ID.ValueType='PARTNER_LOAN_ID' --AND DEFINITION_APP_ID.Field = ELEMENT.Field		
	
		INNER JOIN		tblPartnerToolsTriggers 		TRIGGER_SEND 		WITH (NOLOCK) ON TRIGGER_SEND.PartnerToolID	= ELEMENT.PartnerToolID AND TRIGGER_SEND.TYPE='SEND_DECISION'
		INNER JOIN		tblPartnerTools					PARTNER_TOOL 		WITH (NOLOCK) ON ELEMENT.PartnerToolID		= PARTNER_TOOL.PartnerToolID

		INNER JOIN		viewLenderBranches_Simple		LENDER_BRANCH		WITH (NOLOCK) ON BIDS.LendersBranchID		= LENDER_BRANCH.LendersBranchID

		INNER JOIN		viewB2B_PartnerAuthentication	AUTHENTICATION 		WITH (NOLOCK) ON AUTHENTICATION.LenderID	= LENDER_BRANCH.LenderID AND AUTHENTICATION.PartnerToolID = ELEMENT.PartnerToolID
		INNER JOIN		tblLoanApps						APPLICATION			WITH (NOLOCK) ON APPLICATION.LoanAppID		= BIDS.LoanAppID
		INNER JOIN		tblDealers						DEALER				WITH (NOLOCK) ON DEALER.DealerID = APPLICATION.DealerID
		
		LEFT OUTER JOIN		viewB2B_Bids_LastSent		LAST_SENT		WITH (NOLOCK) ON 
			LAST_SENT.LoanApp_BidID		= BIDS.LoanApp_BidID 
	
		LEFT OUTER JOIN		tblLoanApp_Underwriting			UNDERWRITING	WITH (NOLOCK) ON
				UNDERWRITING.LoanAppID		= BIDS.LoanAppID
			AND	UNDERWRITING.LenderID		= LENDER_BRANCH.LenderID
	
	WHERE
				BIDS.Status	IN ('PENDING_DEALER', 'DECLINE_LENDER', 'ACCEPTED')
		AND		(		(BIDS.FUNDED_DATE IS NULL 		AND BIDS.UpdateDateTime > DATEADD(dd, -30, GETDATE()))
					OR	(BIDS.FUNDED_DATE IS NOT NULL	AND BIDS.FUNDED_DATE > DATEADD(dd, -30, GETDATE()))
					OR	(BIDS.FUNDED_DATE IS NOT NULL	AND BIDS.FUNDED_DATE > DATEADD(dd, -30, GETDATE()) AND UNDERWRITING.UpdateDateTime IS NOT NULL	AND UNDERWRITING.UpdateDateTime > DATEADD(dd, -30, GETDATE()))
				)




GO

