/****** Object:  View dbo.viewB2B_ToInsert    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewB2B_ToInsert AS
	SELECT DISTINCT TOP 100 PERCENT
		LoanAppID			= BID.LoanAppID,
		LoanApp_BidID		= BID.LoanApp_BidID,
		PartnerToolID		= BID_B2B.PartnerToolID,
		Field				= BID_B2B.Field,
		CreateDateTime		= GETDATE(),
		UpdateDateTime		= GETDATE(),
		CreateUser			= 'system:b2b',
		UpdateUser			= 'system:b2b'
	FROM
					viewB2B_Bids		BID_B2B		WITH (NOLOCK)
		JOIN		tblLoanApp_Bids		BID			WITH (NOLOCK)	ON BID.LoanAppID = BID_B2B.LoanAppID AND BID_B2B.LendersBranchID = BID.LendersBranchID
	WHERE
		(NOT BID.LoanApp_BidID = BID_B2B.LoanApp_BidID)
		AND Bid.LoanApp_BidID > 900000
		AND DATEDIFF(dd, BID_B2B.CreateDateTime, GETDATE()) < 10
		AND BID.LoanApp_BidID NOT IN
				(SELECT LoanApp_BidID FROM tblPartnerDataElement WITH (NOLOCK) WHERE
						LoanApp_BidID = BID.LoanApp_BidID
					AND BID_B2B.PartnerToolID = BID_B2B.PartnerToolID
					AND Field = BID_B2B.Field
				)						
		--ORDER BY			BID.LoanApp_BidID DESC
--	OPTION		(MAXDOP 1)






