/****** Object:  View dbo.viewB2B_V3_QueuePriority_Application    Script Date: 7/31/2024 12:57:20 PM ******/



CREATE VIEW [dbo].[viewB2B_V3_QueuePriority_Application] AS
	SELECT
		LoanApp_BidID		= Bid.LoanApp_BidID,		
		--LoanAppID			= MIN(Bid.LoanAppID),
		--LenderID			= MIN(Branch.LenderID),
		--LendersBranchID		= MIN(Branch.LendersBranchID),
		--Original_BidID		= Bid_Base.LoanApp_BidID,
		PartnerToolID		= PDR.PartnerToolID,
		Priority = CASE
				WHEN Bid.Status NOT IN ('PENDING_LENDER') THEN -100				
				WHEN PDR.TS_LastAttempt IS NOT NULL AND DATEDIFF(ss, PDR.TS_LastAttempt, GETDATE()) < 30 THEN -500
				WHEN PDR.TS_Success IS NULL THEN 1000 + ( PDR.ErrorCount * 100 ) + ( PDR.TryCount * 10 )
				WHEN DATEDIFF(ss, APP.[UpdateDateTime], PDR.[TS_LastAttempt]) < 0 THEN 1000 + ( PDR.ErrorCount * 100 ) + ( PDR.TryCount * 10 ) + 1
				WHEN PDR.TS_Success	IS NOT NULL AND PDR.TryCount >=2 THEN -600
				WHEN PDR.TS_Success	IS NOT NULL AND DATEDIFF(d, PDR.TS_Success, GETDATE()) > 1 THEN -400			
				WHEN PDR.TS_Success	IS NOT NULL AND PDR.TryCount < 2 THEN 2000 + ( PDR.ErrorCount * 100 ) + ( PDR.TryCount * 10 )
			END
	FROM
				tblLoanApp_Bids					Bid				WITH (NOLOCK)
		JOIN	tblPartnerApplication_Receipt	PDR				WITH (NOLOCK) ON	PDR.LoanApp_BidID				= Bid.LoanApp_BidID
		JOIN	tblLoanApps						APP				WITH (NOLOCK) ON	APP.LoanAppID					= Bid.LoanAppID
/*		JOIN	tblLoanApp_Bids					Bid_Base		WITH (NOLOCK) ON	Bid_Base.LoanAppID				= Bid.LoanAppID					AND
																			 		Bid_Base.LoanApp_BidID			= (SELECT MIN(Bids_Inner.LoanApp_BidID) FROM tblLoanApp_Bids Bids_Inner WITH (NOLOCK) JOIN tblLendersBranches Branch_Inner WITH (NOLOCK) ON Branch_Inner.LendersBranchID = Bids_Inner.LendersBranchID WHERE Bids_Inner.LoanAppID = Bid.LoanAppID AND Branch_Inner.LenderID = Branch.LenderID)

	WHERE 
		PDR.CreateDateTime > DATEADD(d, -5, GETDATE())		AND

		(	PDR.TS_Success		IS	NULL		OR
			PDR.ErrorCount		>	0			OR
			PDR.TryCount		<	2
--			(PDR.TS_Success >= DATEADD(mi, -60, GETDATE())) -- AND PDR.TryCount < 2 )
		)
*/
	GROUP BY
		Bid.LoanApp_BidID,
		PDR.PartnerToolID,
		Bid.Status,
		APP.[UpdateDateTime],
		PDR.TS_LastAttempt,
		PDR.TS_Success,
		PDR.ErrorCount,
		PDR.TryCount
/*

		Bid.Offer_Date,
		PDR.TS_LastAttempt,
		PDR.TS_Success,
		PDR.TryCount,
		PDR.ErrorCount

*/

/*

WHERE ISNULL(X.Priority, 0) >= 0

ORDER BY Priority, LoanAppID DESC, LoanApp_BidID
*/


/*
		(PDR.TryCount * 5 + PDR.ErrorCount * 10),
		Bid.Offer_Date DESC
*/





