/****** Object:  View dbo.viewBidDecisionStatus_Inner    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE VIEW [viewBidDecisionStatus_Inner] AS
	SELECT
		[Status].*,
		[LatestDecision] 	= CASE WHEN [Status].[Bids] = 1 AND [Status].[isDecision] = 1 THEN [Status].[LoanApp_BidID] WHEN [Status].[Bids] > 1 THEN (SELECT TOP 1 [Bids].[LoanApp_BidID]	FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK) JOIN [tblLendersBranches] [Branches] WITH (NOLOCK) ON [Branches].[LendersBranchID] = [Bids].[LendersBranchID] WHERE	[Bids].[LoanAppID] = [Status].[LoanAppID] AND [Branches].[LenderID] = [Status].[LenderID] AND [Bids].[Status] IN ('PENDING_DEALER', 'DECLINE_DEALER', 'DECLINE_LENDER', 'ACCEPTED') AND [Bids].[Canceled_Date] IS NULL AND [Bids].[Offer_Date] IS NOT NULL ORDER BY 	[Bids].[Offer_Date] DESC)	END,
		[LatestPending] 	= CASE WHEN [Status].[Bids] = 1 AND [Status].[isPending]	= 1 THEN [Status].[LoanApp_BidID] WHEN [Status].[Bids] > 1 THEN (SELECT MAX([Bids].[LoanApp_BidID])		FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK) JOIN [tblLendersBranches] [Branches] WITH (NOLOCK) ON [Branches].[LendersBranchID] = [Bids].[LendersBranchID] WHERE	[Bids].[LoanAppID] = [Status].[LoanAppID] AND [Branches].[LenderID] = [Status].[LenderID] AND [Bids].[Status] IN ('PENDING_LENDER', 'REFERRED') AND [Bids].[Canceled_Date] IS NULL)																												END
	FROM
		[viewBidDecisionStatus_Outer]	[Status]		WITH (NOLOCK)


