/****** Object:  View dbo.viewBidFundingStatus    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewBidFundingStatus AS
	SELECT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID			= BFS.LoanApp_BidID,
		LenderID				= Branch.LenderID,
		LendersBranchID			= Bid.LendersBranchID,
		FundingStatus			= BFS.BidFundingStatus, 
		StatusDateTime			= BFS.StatusUpdateDateTime, 
		StatusUser				= BFS.StatusUpdateUser
	FROM 
				tblLoanApp_BidFundingStatus 	BFS				WITH (NOLOCK)
		JOIN	tblLoanApp_Bids					Bid 			WITH (NOLOCK) ON	Bid.LoanApp_BidID		= BFS.LoanApp_BidID
		JOIN	tblLendersBranches				Branch			WITH (NOLOCK) ON	Branch.LendersBranchID	= Bid.LendersBranchID
	WHERE
		LEN(BFS.BidFundingStatus)	> 0



