/****** Object:  View dbo.viewBidLastStatus    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewBidLastStatus AS
	SELECT --TOP 50
		LoanAppID						= Bid.LoanAppID,
		LenderID						= Branch.LenderID,
		LendersBranchID					= Bid.LendersBranchID,
		DealerID						= Dealer.DealerID,
		--UpdateDateTime					= MAX(LastStatus.UpdateDateTime),
		--FundingSentDateTime				= MAX(LastStatus.FundingSent),

		UpdateDateTime					= MAX(LastStatus_Update.UpdateDateTime),
		FundingSentDateTime				= MAX(LastStatus_Sent.FundingSent),
		FundingPostError				= ISNULL(MAX(LastStatus_Sent.FundingPostError), 0),
		FundingPostErrorDescription		= ISNULL(MAX(LastStatus_Sent.FundingPostErrorDescription), '')
	FROM 
						tblLoanApp_Bids					Bid 				WITH (NOLOCK)
				JOIN	tblLoanApps						App					WITH (NOLOCK) ON 	App.LoanAppID						= Bid.LoanAppID
				JOIN	tblLendersBranches				Branch				WITH (NOLOCK) ON 	Branch.LendersBranchID				= Bid.LendersBranchID
				JOIN	tblDealers						Dealer				WITH (NOLOCK) ON 	Dealer.DealerID						= App.DealerID
				JOIN	tblLoanApp_Bids					Bid_LastStatus		WITH (NOLOCK) ON	Bid_LastStatus.LoanAppID			= Bid.LoanAppID
				JOIN	tblLendersBranches				Branch_LastStatus	WITH (NOLOCK) ON	Branch_LastStatus.LendersBranchID	= Bid_LastStatus.LendersBranchID		AND	Branch_LastStatus.LenderID			= Branch.LenderID

				JOIN	tblLoanApp_Bids					Bid_LS_Update		WITH (NOLOCK) ON	Bid_LS_Update.LoanAppID				= Bid.LoanAppID
				JOIN	tblLendersBranches				Branch_LS_Update	WITH (NOLOCK) ON	Branch_LS_Update.LendersBranchID	= Bid_LS_Update.LendersBranchID			AND Branch_LS_Update.LenderID			= Branch.LenderID

				JOIN	tblLoanApp_Bids					Bid_LS_Sent			WITH (NOLOCK) ON	Bid_LS_Sent.LoanAppID				= Bid.LoanAppID
				JOIN	tblLendersBranches				Branch_LS_Sent		WITH (NOLOCK) ON	Branch_LS_Sent.LendersBranchID	= Bid_LS_Sent.LendersBranchID			AND Branch_LS_Sent.LenderID			= Branch.LenderID

		LEFT	JOIN	tblLoanApp_Bids_LastStatus		LastStatus_Update	WITH (NOLOCK) ON	LastStatus_Update.LoanApp_BidID		= Bid_LS_Update.LoanApp_BidID		AND LastStatus_Update.UpdateDateTime IS NOT NULL
		LEFT	JOIN	tblLoanApp_Bids_LastStatus		LastStatus_Sent		WITH (NOLOCK) ON	LastStatus_Sent.LoanApp_BidID		= Bid_LS_Sent.LoanApp_BidID			AND LastStatus_Sent.FundingSent IS NOT NULL
	WHERE
		Bid.CreateDateTime >= '2013-01-01'
		--AND LastStatus_Sent.FundingSent IS NOT NULL
		--AND LastStatus.FundingSent IS NOT NULL		AND LastStatus.FundingSent >= '2014-01-01'
	GROUP BY
		Bid.LoanAppID,
		Branch.LenderID,
		Bid.LendersBranchID,
		Dealer.DealerID

	/*ORDER BY
		Bid.LoanAppID					DESC,
		Branch.LenderID,
		MAX(LastStatus.FundingSent)
	*/

