/****** Object:  View dbo.viewBidVehicles    Script Date: 7/31/2024 12:57:20 PM ******/
--SET NOCOUNT ON;
CREATE  VIEW viewBidVehicles AS

	SELECT
		Vehicle							= LTRIM(RTRIM(REPLACE(CONVERT(VARCHAR(255), CASE WHEN Worksheet.LoanApp_WorksheetID IS NULL THEN
											CASE WHEN ISNULL(Application.Vehicle_Year,		 0)		> 1900	THEN CONVERT(VARCHAR(4), Application.Vehicle_Year)	+ ' ' ELSE '' END +
											CASE WHEN LEN(ISNULL(Application.Vehicle_Make,	''))	> 0 	THEN DBO.ProperCase(Application.Vehicle_Make)			+ ' ' ELSE '' END +
											CASE WHEN LEN(ISNULL(Application.Vehicle_Model,	''))	> 0 	THEN DBO.ProperCase(Application.Vehicle_Model)		+ ' ' ELSE '' END +
											--CASE WHEN ISNULL(Application.Vehicle_Mileage,		 0)		> 0 	THEN '(' + REPLACE(CONVERT(VARCHAR(20), CONVERT(money, Application.Vehicle_Mileage), 1), '.00', '') + ' Miles) ' ELSE '' END +
											--CASE WHEN LEN(ISNULL(Application.Vehicle_VIN,		'')) = 17 THEN '(VIN: ' + UPPER(Application.Vehicle_VIN) + ')' ELSE '' END +
											''

										ELSE
											CASE WHEN ISNULL(Worksheet.Vehicle_Year,		 0)		> 1900	THEN CONVERT(VARCHAR(4), Worksheet.Vehicle_Year)	+ ' ' ELSE '' END +
											CASE WHEN LEN(ISNULL(Worksheet.Vehicle_Make,	''))	> 0 	THEN DBO.ProperCase(Worksheet.Vehicle_Make)			+ ' ' ELSE '' END +
											CASE WHEN LEN(ISNULL(Worksheet.Vehicle_Model,	''))	> 0 	THEN DBO.ProperCase(Worksheet.Vehicle_Model)		+ ' ' ELSE '' END +
											--CASE WHEN ISNULL(Worksheet.Vehicle_Mileage,		 0)		> 0 	THEN '(' + REPLACE(CONVERT(VARCHAR(20), CONVERT(money, Worksheet.Vehicle_Mileage), 1), '.00', '') + ' Miles) ' ELSE '' END +
											--CASE WHEN LEN(ISNULL(Worksheet.Vehicle_VIN,		'')) = 17 THEN '(VIN: ' + UPPER(Worksheet.Vehicle_VIN) + ')' ELSE '' END +
											''
										END), ') (', '; '))),


		LoanApp_BidID					= Bids.LoanApp_BidID,
		LoanAppID						= Bids.LoanAppID,
		LenderID						= Branch.LenderID,
		LendersBranchID					= Bids.LendersBranchID,
		LoanApp_WorksheetID				= Worksheet.LoanApp_WorksheetID,
		WorksheetActive					= ISNULL(Worksheet.Active, 0),
--		UISelected						=
