		New_Used						= ISNULL(CASE WHEN Worksheet.LoanApp_WorksheetID IS NULL		THEN Application.New_Used								ELSE Worksheet.New_Used								END,		''),
		Vehicle_Make					= DBO.ProperCase(ISNULL(CASE WHEN Worksheet.LoanApp_WorksheetID IS NULL		THEN Application.Vehicle_Make							ELSE Worksheet.Vehicle_Make							END,		'')),
