/****** Object:  View dbo.viewBidsAutomationPending_Outer    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE  VIEW [dbo].[viewBidsAutomationPending_Outer] AS
	SELECT
		[LoanAppID]										= [Bid].[LoanAppID],
		[DealerID]										= MIN([Dealer].[DealerID]),
		[LenderID]										= [Lender].[LenderID],
		[LendersBranchID]							= MIN([Branch].[LendersBranchID]),
		[LoanApp_BidID]								= MIN([Bid].[LoanApp_BidID]),
		[Lender]											= UPPER(MIN([Lender].[LenderName])),
		[Branch]											= UPPER(MIN([Branch].[BranchName])),
		[Dealer]											= UPPER(MIN([Dealer].[DealerName])),
		[Customer]										= UPPER(RTRIM(LTRIM(REPLACE(REPLACE(MIN([App].[Applicant_Names]), CHAR(10), ' '), '  ', ' ')))),
		[LenderPrefix]								= UPPER(MIN([Lender].[LoginPrefix])),
		[BranchPrefix]								= UPPER(ISNULL(NULLIF(MIN([Branch].[LoginPrefix]), ''), MIN([Lender].[LoginPrefix]))),
		[Status]											= MIN([Bid].[Status]),
		[CreditReportAccount]					= CONVERT(BIT, CASE WHEN NULLIF([Branch].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Branch].[Microbilt_Password], '') IS NOT NULL THEN 1 WHEN NULLIF([Lender].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Lender].[Microbilt_Password], '') IS NOT NULL THEN 1 ELSE 0 END),
		[CreditReportAccountSource]		= CASE WHEN NULLIF([Branch].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Branch].[Microbilt_Password], '') IS NOT NULL THEN 'LENDER_BRANCH' WHEN NULLIF([Lender].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Lender].[Microbilt_Password], '') IS NOT NULL THEN 'LENDER_MASTER' ELSE 'NONE' END,
		[CreditReportLogin]						= CASE WHEN NULLIF([Branch].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Branch].[Microbilt_Password], '') IS NOT NULL THEN [Branch].[Microbilt_Login] WHEN NULLIF([Lender].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Lender].[Microbilt_Password], '') IS NOT NULL THEN [Lender].[Microbilt_Login] ELSE '' END,
		[CreditReportPassword]				= CASE WHEN NULLIF([Branch].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Branch].[Microbilt_Password], '') IS NOT NULL THEN [Branch].[Microbilt_Password] WHEN NULLIF([Lender].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Lender].[Microbilt_Password], '') IS NOT NULL THEN [Lender].[Microbilt_Password] ELSE '' END,
		[Automation_Bureau]						= [Lender].[Automation_Credit_Provider],
		[Existing_Bureau]							= CASE WHEN [Credit].[CreditPullID] IS NULL OR [Credit].[GUID] IS NULL THEN '' ELSE CONVERT(VARCHAR(38), [Credit].[GUID]) END,
		[Has_Existing_Bureau]					= CONVERT(BIT, CASE WHEN [Credit].[CreditPullID] IS NULL OR [Credit].[GUID] IS NULL OR DATALENGTH([Credit].[Data_Raw]) < 32 THEN 0 ELSE 1 END),
		[CreditPullID_EX]							= CASE WHEN [Credit].[CreditPullID] IS NOT NULL AND ISNULL([Credit].[Bureau], '') = 'EX' THEN [Credit].[CreditPullID] END,
		[CreditPullID_EQ]							= CASE WHEN [Credit].[CreditPullID] IS NOT NULL AND ISNULL([Credit].[Bureau], '') = 'EQ' THEN [Credit].[CreditPullID] END,
		[CreditPullID_TU]							= CASE WHEN [Credit].[CreditPullID] IS NOT NULL AND ISNULL([Credit].[Bureau], '') = 'TU' THEN [Credit].[CreditPullID] END,
		[BureauAge]										= CASE WHEN [Credit].[CreateDateTime] IS NULL THEN -1 ELSE DATEDIFF(ss, [Credit].[CreateDateTime], GETDATE()) END,
		[Age]													= DATEDIFF(s, MAX([Bid].[UpdateDateTime]), GETDATE()),
		[BidSubmit]										= DATEDIFF(d, MAX([Bid].[Submit_Date]), GETDATE()),
		[BidOffer]										= DATEDIFF(d, MAX(ISNULL([Bid].[Offer_Date], [Bid].[UpdateDateTime])), GETDATE()),
		[AutoDeclinePrograms]					= CASE WHEN MAX(ISNULL([DeclinePrograms].[ProgramID], 0)) = 0 THEN 0 ELSE COUNT(DISTINCT ISNULL([DeclinePrograms].[ProgramID], 0)) END,
		[AutoOfferPrograms]						= CASE WHEN MAX(ISNULL([OfferPrograms].[ProgramID], 0)) = 0 THEN 0 ELSE COUNT(DISTINCT ISNULL([OfferPrograms].[ProgramID], 0)) END,
		[NeedsPull]										= CONVERT(INT, CASE
			WHEN ISNULL([Lender].[Automation_Credit_Provider], '') = '' THEN 0
			WHEN (NULLIF([Branch].[Microbilt_Login], '') IS NULL OR NULLIF([Branch].[Microbilt_Password], '') IS NULL) AND (NULLIF([Lender].[Microbilt_Login], '') IS NULL OR NULLIF([Lender].[Microbilt_Password], '') IS NULL) THEN 0
			WHEN [Credit].[CreditPullID] IS NOT NULL AND [Credit].[GUID] IS NOT NULL AND DATALENGTH([Credit].[Data_Raw]) >= 32 THEN 0
			WHEN DATEDIFF(ss, MAX([Bid].[UpdateDateTime]), GETDATE()) < 30 AND (MIN([Bid].[UpdateUser]) = 'CSMarts_Automation_Credit' OR MIN([Bid].[Status]) = 'PROCESSING_AUTOMATION') THEN 0
			ELSE 1 END),
		[NeedsAutoDecline]						= CONVERT(BIT, CASE
			WHEN MAX(ISNULL([DeclinePrograms].[ProgramID], 0)) = 0 OR MIN([Bid].[Status]) NOT IN ('PENDING_AUTOMATION', 'PROCESSING_AUTOMATION') OR [Credit].[CreditPullID] IS NULL OR [Credit].[GUID] IS NULL OR DATALENGTH([Credit].[Data_Raw]) < 32 OR DATEDIFF(dd, [Credit].[CreateDateTime], GETDATE()) > 90 THEN 0
			WHEN EXISTS(SELECT * FROM [tblLoanApp_AutoDeclineResult] [Decline] WITH (NOLOCK) WHERE [Decline].[LenderID] = [Lender].[LenderID] AND [Decline].[LoanAppID]	= [Bid].[LoanAppID] AND [Decline].[Credit_GUID] = [Credit].[GUID] AND [Decline].[UpdateDateTime] >= MIN([Bid].[Submit_Date]) /*AND [Decline].[ProgramCount] = COUNT(DISTINCT ISNULL([DeclinePrograms].[ProgramID], 0)) AND [Decline].[FailedCount] < COUNT(DISTINCT ISNULL([DeclinePrograms].[ProgramID], 0))*/) THEN 0
			WHEN EXISTS(SELECT * FROM [tblLoanApp_AutoDeclineResult] [Decline] WITH (NOLOCK) WHERE [Decline].[LenderID] = [Lender].[LenderID] AND [Decline].[LoanAppID]	= [Bid].[LoanAppID] AND [Decline].[Credit_GUID] = [Credit].[GUID] AND [Decline].[UpdateDateTime] >= MIN([Bid].[Submit_Date]) AND [Decline].[ProgramCount] = COUNT(DISTINCT ISNULL([DeclinePrograms].[ProgramID], 0)) AND [Decline].[FailedCount] < COUNT(DISTINCT ISNULL([DeclinePrograms].[ProgramID], 0))) THEN 0
			ELSE 1 END),
		[NeedsAutoOffer]									= CONVERT(BIT, CASE
			WHEN MAX(ISNULL([OfferPrograms].[ProgramID], 0)) = 0 OR MIN([Bid].[Status]) NOT IN ('PENDING_AUTOMATION', 'PROCESSING_AUTOMATION') OR [Credit].[CreditPullID] IS NULL OR [Credit].[GUID] IS NULL OR DATALENGTH([Credit].[Data_Raw]) < 32 OR DATEDIFF(dd, [Credit].[CreateDateTime], GETDATE()) > 90 THEN 0
			WHEN MAX(ISNULL([DeclinePrograms].[ProgramID], 0)) = 0 THEN 1
			WHEN NOT EXISTS(SELECT * FROM [tblLoanApp_AutoDeclineResult] [Decline] WITH (NOLOCK) WHERE [Decline].[LenderID] = [Lender].[LenderID] AND [Decline].[LoanAppID]	= [Bid].[LoanAppID] AND [Decline].[Credit_GUID] = [Credit].[GUID] AND [Decline].[UpdateDateTime] >= MIN([Bid].[Submit_Date]) /*AND [Decline].[ProgramCount] = COUNT(DISTINCT ISNULL([DeclinePrograms].[ProgramID], 0))*/			) THEN 0
--			WHEN EXISTS(SELECT * FROM [tblLoanApp_AutoDeclineResult] [Decline] WITH (NOLOCK) WHERE [Decline].[LenderID] = [Lender].[LenderID] AND [Decline].[LoanAppID]	= [Bid].[LoanAppID] AND [Decline].[Credit_GUID] = [Credit].[GUID] AND [Decline].[UpdateDateTime] >= MIN([Bid].[Submit_Date]) /*AND [Decline].[ProgramCount] = COUNT(DISTINCT ISNULL([DeclinePrograms].[ProgramID], 0)) AND [Decline].[FailedCount] = COUNT(DISTINCT ISNULL([DeclinePrograms].[ProgramID], 0))*/) THEN 0
			ELSE 1 END)
	FROM
							[tblLoanApp_Bids]						[Bid]								WITH (NOLOCK)
		JOIN			[tblLoanApps]								[App]								WITH (NOLOCK) ON [Bid].[LoanAppID] = [App].[LoanAppID]
		JOIN			[tblDealers]								[Dealer]						WITH (NOLOCK) ON [Dealer].[DealerID] = [App].[DealerID]
		JOIN			[tblLendersBranches]				[Branch]						WITH (NOLOCK) ON [Branch].[LendersBranchID] = [Bid].[LendersBranchID]
		JOIN			[tblLenders]								[Lender]						WITH (NOLOCK) ON [Branch].[LenderID] = [Lender].[LenderID]
		JOIN			[tblPrograms]								[Programs]					WITH (NOLOCK) ON [Programs].[LenderID] = [Lender].[LenderID] AND [Programs].[Active] = 1 AND (ISNULL([Programs].[Automated], 0) = 1 OR ISNULL([Programs].[AutoDecline], 0) = 1)
		LEFT JOIN	[tblPrograms]								[OfferPrograms]			WITH (NOLOCK) ON [OfferPrograms].[LenderID] = [Lender].[LenderID] AND [OfferPrograms].[Active] = 1 AND ISNULL([OfferPrograms].[Automated], 0) = 1 AND ISNULL([OfferPrograms].[AutoDecline], 0) = 0
		LEFT JOIN	[tblPrograms]								[DeclinePrograms]		WITH (NOLOCK) ON [DeclinePrograms].[LenderID] = [Lender].[LenderID] AND [DeclinePrograms].[Active] = 1 AND ISNULL([DeclinePrograms].[AutoDecline], 0) = 1
		LEFT JOIN	[tblCreditPulls]						[Credit]						WITH (NOLOCK) on [Credit].[GUID] = ISNULL(NULLIF([Bid].[Lender_Credit_EX], ''), ISNULL(NULLIF([Bid].[Lender_Credit_EQ], ''), NULLIF([Bid].[Lender_Credit_TU], '')))
	WHERE
				[Bid].[LoanApp_BidID]										>= (SELECT MIN([LoanApp_BidID]) FROM [tblLoanApp_Bids] WITH (NOLOCK) WHERE [CreateDateTime] > DATEADD(d, -30, GETDATE()))
		AND [Bid].[Status]													IN ('PENDING_AUTOMATION', 'PENDING_LENDER', 'PROCESSING_AUTOMATION')
		AND [Lender].[Automation_Credit_Provider]		IS NOT NULL
		AND [Lender].[Automation_Credit_Provider]		IN ('EX', 'EQ', 'TU') 
		AND [Bid].[Canceled_Date]										IS NULL
		AND	NULLIF(NULLIF([App].[LenderID], 0), '')	IS NULL 
		AND	([Bid].[UpdateDateTime] >= DATEADD(d, -5, GETDATE()) OR ([Bid].[Submit_Date] IS NOT NULL AND [Bid].[Submit_Date] >= DATEADD(d, -5, GETDATE())))
		AND NOT EXISTS(SELECT * FROM [tblLoanApp_Bids] [Bid_Decision] WITH (NOLOCK) WHERE [Bid_Decision].[LoanAppID] = [Bid].[LoanAppID] AND [Bid_Decision].[LendersBranchID] IN (SELECT [LendersBranchID] FROM [tblLendersBranches] [Branch_Decision] WITH (NOLOCK) WHERE [Branch_Decision].[LenderID] = [Lender].[LenderID]) AND [Bid_Decision].[Canceled_Date] IS NULL AND [Bid_Decision].[Offer_Date] IS NOT NULL AND ([Bid_Decision].[Status] = 'DECLINE_LENDER' OR ([Bid_Decision].[Status] = 'PENDING_DEALER' AND NULLIF([Bid_Decision].[Rate], '') IS NOT NULL AND ISNULL([Bid_Decision].[Financing_Amount], 0) > 0 AND ISNULL([Bid_Decision].[Payment], 0) > 0)))
	GROUP BY
		[Bid].[LoanAppID], 
		[Lender].[LenderID], 
		[Lender].[Automation_Credit_Provider],
		[Branch].[Microbilt_Login], 
		[Branch].[Microbilt_Password], 
		[Lender].[Microbilt_Login], 
		[Lender].[Microbilt_Password],
		[Credit].[GUID],
		[Credit].[Bureau],
		[Credit].[CreditPullID],
		[Credit].[CreateDateTime],
		DATALENGTH([Credit].[Data_Raw])



