/****** Object:  View dbo.viewBidsAutomationPending_Outer_2    Script Date: 7/31/2024 12:57:20 PM ******/
CREATE VIEW [viewBidsAutomationPending_Outer_2] AS
	SELECT
		[NeedsPull]										= CONVERT(INT, CASE
			WHEN ISNULL([Lender].[Automation_Credit_Provider], '') = '' THEN 0
			WHEN [Lender].[Automation_Credit_Provider] = 'EX' AND (LEN(ISNULL([Bid].[Lender_Credit_EX], '')) <> 38 OR [Credit_EX].[CreditPullID] IS NULL) THEN 1
			WHEN [Lender].[Automation_Credit_Provider] = 'EQ' AND (LEN(ISNULL([Bid].[Lender_Credit_EQ], '')) <> 38 OR [Credit_EQ].[CreditPullID] IS NULL) THEN 1
			WHEN [Lender].[Automation_Credit_Provider] = 'TU' AND (LEN(ISNULL([Bid].[Lender_Credit_EX], '')) <> 38 OR [Credit_EX].[CreditPullID] IS NULL) THEN 1
			WHEN [Lender].[Automation_Credit_Provider] = 'EX' AND DATALENGTH([Credit_EX].[Data_Raw]) IS NULL THEN 1
			WHEN [Lender].[Automation_Credit_Provider] = 'EQ' AND DATALENGTH([Credit_EQ].[Data_Raw]) IS NULL THEN 1
			WHEN [Lender].[Automation_Credit_Provider] = 'TU' AND DATALENGTH([Credit_TU].[Data_Raw]) IS NULL THEN 1
			WHEN [Lender].[Automation_Credit_Provider] = 'EX' AND DATALENGTH([Credit_EX].[Data_Raw]) < 32 THEN 1
			WHEN [Lender].[Automation_Credit_Provider] = 'EQ' AND DATALENGTH([Credit_EQ].[Data_Raw]) < 32 THEN 1
			WHEN [Lender].[Automation_Credit_Provider] = 'TU' AND DATALENGTH([Credit_TU].[Data_Raw]) < 32 THEN 1
			ELSE 0 END),

			[LoanAppID]										= [Bid].[LoanAppID],
			[DealerID]										= MIN([Dealer].[DealerID]),
			[LenderID]										= [Lender].[LenderID],
			[LendersBranchID]							= MIN([Branch].[LendersBranchID]),
			[LoanApp_BidID]								= MIN([Bid].[LoanApp_BidID]),
			[Lender]											= UPPER(MIN([Lender].[LenderName])),
			[Branch]											= UPPER(MIN([Branch].[BranchName])),
			[Dealer]											= UPPER(MIN([Dealer].[DealerName])),
			[Customer]										= UPPER(MIN([App].[Applicant_Names])),
			[LenderPrefix]								= UPPER(MIN([Lender].[LoginPrefix])),
			[BranchPrefix]								= UPPER(ISNULL(NULLIF(MIN([Branch].[LoginPrefix]), ''), MIN([Lender].[LoginPrefix]))),
			[Status]											= MIN([Bid].[Status]),
			[CreditReportAccount]					= CONVERT(BIT, CASE WHEN NULLIF([Branch].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Branch].[Microbilt_Password], '') IS NOT NULL THEN 1 WHEN NULLIF([Lender].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Lender].[Microbilt_Password], '') IS NOT NULL THEN 1 ELSE 0 END),
			[CreditReportAccountSource]		= CASE WHEN NULLIF([Branch].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Branch].[Microbilt_Password], '') IS NOT NULL THEN 'LENDER_BRANCH' WHEN NULLIF([Lender].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Lender].[Microbilt_Password], '') IS NOT NULL THEN 'LENDER_MASTER' ELSE 'NONE' END,
			[CreditReportPassword]				= CASE WHEN NULLIF([Branch].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Branch].[Microbilt_Password], '') IS NOT NULL THEN [Branch].[Microbilt_Password] WHEN NULLIF([Lender].[Microbilt_Login], '') IS NOT NULL AND NULLIF([Lender].[Microbilt_Password], '') IS NOT NULL THEN [Lender].[Microbilt_Password] ELSE '' END,
			[Automation_Bureau]						= [Lender].[Automation_Credit_Provider],
			[Existing_Bureau]							= CASE WHEN ISNULL([Lender].[Automation_Credit_Provider], '') = '' THEN '' WHEN [Lender].[Automation_Credit_Provider] = 'EX' AND LEN(ISNULL([Bid].[Lender_Credit_EX], '')) = 38 AND [Credit_EX].[CreditPullID] IS NOT NULL THEN [Bid].[Lender_Credit_EX] WHEN [Lender].[Automation_Credit_Provider] = 'EQ' AND LEN(ISNULL([Bid].[Lender_Credit_EQ], '')) = 38 AND [Credit_EQ].[CreditPullID] IS NOT NULL THEN [Bid].[Lender_Credit_EQ] WHEN [Lender].[Automation_Credit_Provider] = 'TU' AND LEN(ISNULL([Bid].[Lender_Credit_TU], '')) = 38 AND [Credit_TU].[CreditPullID] IS NOT NULL THEN [Bid].[Lender_Credit_TU] END,
			[Has_Existing_Bureau]					= CONVERT(BIT, CASE WHEN ISNULL([Lender].[Automation_Credit_Provider], '') = '' THEN '' WHEN [Lender].[Automation_Credit_Provider] = 'EX' AND LEN(ISNULL([Bid].[Lender_Credit_EX], '')) = 38 AND [Credit_EX].[CreditPullID] IS NOT NULL THEN 1 WHEN [Lender].[Automation_Credit_Provider] = 'EQ' AND LEN(ISNULL([Bid].[Lender_Credit_EQ], '')) = 38 AND [Credit_EQ].[CreditPullID] IS NOT NULL THEN 1 WHEN [Lender].[Automation_Credit_Provider] = 'TU' AND LEN(ISNULL([Bid].[Lender_Credit_TU], '')) = 38 AND [Credit_TU].[CreditPullID] IS NOT NULL THEN 1 ELSE 0 END),
			[CreditPullID_EQ]							= [Credit_EQ].[CreditPullID],
			[CreditPullID_EX]							= [Credit_EX].[CreditPullID],
			[CreditPullID_TU]							= [Credit_TU].[CreditPullID],
			[Age]													= DATEDIFF(s, MIN([Bid].[UpdateDateTime]), GETDATE()),
			[BidSubmit]										= DATEDIFF(d, MIN([Bid].[Submit_Date]), GETDATE()),
			[BidOffer]										= DATEDIFF(d, MIN(ISNULL([Bid].[Offer_Date], [Bid].[UpdateDateTime])), GETDATE())
		FROM
								[tblLoanApp_Bids]				[Bid]					WITH (NOLOCK)
			JOIN			[tblLoanApps]						[App]					WITH (NOLOCK) ON [Bid].[LoanAppID]									= [App].[LoanAppID]
			JOIN			[tblDealers]						[Dealer]			WITH (NOLOCK) ON [Dealer].[DealerID]								= [App].[DealerID]
			JOIN			[tblLendersBranches]		[Branch]			WITH (NOLOCK) ON [Branch].[LendersBranchID]					= [Bid].[LendersBranchID]
			JOIN			[tblLenders]						[Lender]			WITH (NOLOCK) ON [Branch].[LenderID]								= [Lender].[LenderID]
			JOIN			[tblPrograms]						[PROGRAM]			WITH (NOLOCK) ON [Program].[LenderID]								= [Lender].[LenderID]		AND [Program].[Active] = 1		AND [Program].[Automated] = 1
			LEFT JOIN	[tblCreditPulls]				[Credit_EX]		WITH (NOLOCK) ON [Lender].[Automation_Credit_Provider] = 'EX' AND LEN(ISNULL([Bid].[Lender_Credit_EX], '')) = 38 AND [Credit_EX].[GUID]	= [Bid].[Lender_Credit_EX]
			LEFT JOIN	[tblCreditPulls]				[Credit_EQ]		WITH (NOLOCK) ON [Lender].[Automation_Credit_Provider] = 'EQ' AND LEN(ISNULL([Bid].[Lender_Credit_EQ], '')) = 38 AND [Credit_EQ].[GUID]	= [Bid].[Lender_Credit_EQ]
			LEFT JOIN	[tblCreditPulls]				[Credit_TU]		WITH (NOLOCK) ON [Lender].[Automation_Credit_Provider] = 'TU' AND LEN(ISNULL([Bid].[Lender_Credit_TU], '')) = 38 AND [Credit_TU].[GUID]	= [Bid].[Lender_Credit_TU]
		WHERE
		(
					[Bid].[LoanApp_BidID] >= (SELECT MAX([LoanApp_BidID]) FROM [tblLoanApp_Bids] WITH (NOLOCK) WHERE [CreateDateTime] <= DATEADD(d, -30, GETDATE()))
			AND NULLIF(RTRIM([Lender].[Automation_Credit_Provider]), '') IS NOT NULL
			AND	NULLIF(NULLIF([App].[LenderID], 0), '') IS NULL
			AND	([Bid].[UpdateDateTime] >= DATEADD(d, -3, GETDATE()) OR ISNULL([Bid].[Submit_Date], [Bid].[UpdateDateTime]) >= DATEADD(d, -3, GETDATE()))
			AND	Bid.Status IN ('PENDING_AUTOMATION', 'PROCESSING_AUTOMATION', 'PENDING_LENDER')
		)
--	OR [Bid].[LoanApp_BidID] = 2536273
	-- AND [Bid].[LoanApp_BidID] >= 2536176
		GROUP BY
			[Bid].[LoanAppID],
			[Bid].[Lender_Credit_EX],
			[Bid].[Lender_Credit_EQ],
			[Bid].[Lender_Credit_TU],
			[Lender].[LenderID],
			[Branch].[Microbilt_Login],
			[Branch].[Microbilt_Password],
			[Lender].[Microbilt_Login],
			[Lender].[Microbilt_Password],
			[Lender].[Automation_Credit_Provider],
			[Credit_EX].[CreditPullID],
			[Credit_EQ].[CreditPullID],
			[Credit_TU].[CreditPullID],
			DATALENGTH([Credit_EX].[Data_Raw]),
			DATALENGTH([Credit_EQ].[Data_Raw]),
			DATALENGTH([Credit_TU].[Data_Raw])
	/*
	*/

	/*
			[Bid].[UpdateDateTime],
			[Bid].[Submit_Date],
			[Bid].[Offer_Date],
			[Bid].[Offered_By],
			[Credit_EX].[Bureau],
			[Credit_TU].[Bureau],
			[Credit_EQ].[Bureau],
	*/
	/*
		ORDER BY
			[Bid].[LoanAppID],
			[Lender].[LenderID]
	*/

	-- SELECT [Rows] = @@ROWCOUNT, [Elapsed] = DATEDIFF(ms, @D, GETDATE());

-- ROLLBACK TRANSACTION;
--RETURN;



