/****** Object:  View dbo.viewBidsAutomation_AutoDeclineProgramResult    Script Date: 7/31/2024 12:57:20 PM ******/
--DECLARE @D DATETIME; SET @D = GETDATE();
CREATE VIEW viewBidsAutomation_AutoDeclineProgramResult AS
	SELECT
		[Bid].[LoanAppID],
		[Bid].[LoanApp_BidID],
		[Branch].[LenderID],
		[Bid].[Status],
		[BidUpdated] = [BId].[UpdateDateTime],
		[Programs] = COUNT(DISTINCT [Program].[ProgramID]),
		[Ran] = CASE WHEN MAX(ISNULL([ProgramResult].[ProgramID], 0)) = 0 THEN 0 ELSE CASE WHEN MAX(ISNULL([Pass].[ProgramID], 0)) = 0 THEN 0 ELSE COUNT(DISTINCT ISNULL([Pass].[ProgramID], 0)) END + CASE WHEN MAX(ISNULL([Fail].[ProgramID], 0)) = 0 THEN 0 ELSE COUNT(DISTINCT ISNULL([Fail].[ProgramID], 0)) END END,
		[Passed] = CASE WHEN MAX(ISNULL([ProgramResult].[ProgramID], 0)) = 0 THEN 0 WHEN MAX(ISNULL([Pass].[ProgramID], 0)) = 0 THEN 0 ELSE COUNT(DISTINCT ISNULL([Pass].[ProgramID], 0)) END,
		[Failed] = CASE WHEN MAX(ISNULL([ProgramResult].[ProgramID], 0)) = 0 THEN 0 WHEN MAX(ISNULL([Fail].[ProgramID], 0)) = 0 THEN 0 ELSE COUNT(DISTINCT ISNULL([Fail].[ProgramID], 0)) END,
		[Updated] = CASE WHEN MAX(ISNULL([ProgramResult].[ProgramID], 0)) > 0 THEN MAX(ISNULL([ProgramResult].[UpdateDateTime], [Bid].[UpdateDateTime])) END,
		[Complete] = CONVERT(BIT, CASE
			WHEN [Result].[UpdateDateTime] IS NULL OR MAX(ISNULL([ProgramResult].[ProgramID], 0)) = 0 THEN 0
			WHEN CASE WHEN MAX(ISNULL([Pass].[ProgramID], 0)) = 0 THEN 0 ELSE COUNT(DISTINCT ISNULL([Pass].[ProgramID], 0)) END + CASE WHEN MAX(ISNULL([Fail].[ProgramID], 0)) = 0 THEN 0 ELSE COUNT(DISTINCT ISNULL([Fail].[ProgramID], 0)) END >= COUNT(DISTINCT [Program].[ProgramID]) THEN 1 ELSE 0 END)
	FROM
							[tblLoanApp_Bids]												[Bid]								WITH (NOLOCK)
		JOIN			[tblLendersBranches]										[Branch]						WITH (NOLOCK) ON [Branch].[LendersBranchID] = [Bid].[LendersBranchID]
		JOIN			[tblLenders]														[Lender]						WITH (NOLOCK) ON [Branch].[LenderID]				= [Lender].[LenderID]
		JOIN			[tblPrograms]														[Program]						WITH (NOLOCK) ON [Program].[LenderID]				= [Lender].[LenderID] AND [Program].[Active]					= 1									AND ISNULL([Program].[AutoDecline], 0) = 1
		LEFT JOIN	[tblLoanApp_AutoDeclineResult]					[Result]						WITH (NOLOCK) ON [Result].[LenderID]				= [Lender].[LenderID] AND [Result].[LoanAppID]				= [Bid].[LoanAppID]
		LEFT JOIN	[tblLoanApp_AutoDeclineProgramResult]		[ProgramResult]			WITH (NOLOCK) ON [ProgramResult].[LenderID]	= [Lender].[LenderID] AND [ProgramResult].[LoanAppID]	= [Bid].[LoanAppID] --AND [ProgramResult].[ProgramID]	= [Program].[ProgramID]
		LEFT JOIN	[tblLoanApp_AutoDeclineProgramResult]		[Pass]							WITH (NOLOCK) ON [Pass].[LenderID]					= [Lender].[LenderID] AND [Pass].[LoanAppID]					= [Bid].[LoanAppID] AND ISNULL([Pass].[Pass], 0) = 1 AND ISNULL([Pass].[Fail], 0) = 0	--AND [Pass].[ProgramID]					= [Program].[ProgramID]
		LEFT JOIN	[tblLoanApp_AutoDeclineProgramResult]		[Fail]							WITH (NOLOCK) ON [Fail].[LenderID]					= [Lender].[LenderID] AND [Fail].[LoanAppID]					= [Bid].[LoanAppID] AND ISNULL([Fail].[Pass], 0) = 0 AND ISNULL([Fail].[Fail], 0) = 1 --AND [Fail].[ProgramID]					= [Program].[ProgramID]

	-- WHERE
--		[Bid].[LoanApp_BidID] in (2542765, 2542757)
		-- [Result].cREATEDATETIME >= '2023-01-19'
	GROUP BY
		[Bid].[LoanAppID],
		[Bid].[LoanApp_BidID],
		[Branch].[LenderID],
		[Bid].[Status],
		[BId].[UpdateDateTime],
		[Result].[UpdateDateTime]

-- SELECT @@ROWCOUNT [Rows], DATEDIFF(ms, @D, GETDATE()) [Elapsed];


