/****** Object:  View dbo.viewBidsDateStats    Script Date: 7/31/2024 12:57:20 PM ******/

CREATE VIEW viewBidsDateStats AS
	SELECT
		LoanAppID			= Bids.LoanAppID,
		LoanApp_BidID		= Bids.LoanApp_BidID,
		Status				= Bids.Status,
		LendersBranchID		= Bids.LendersBranchID,
		LenderID			= Branch.LenderID,
		Lender				= DBO.FormatCompanyName(Lender.LenderName, Lender.City, Lender.State),
		DealerID			= CONVERT(INTEGER, Apps.DealerID),
		Dealer				= DBO.FormatCompanyName(Dealer.DealerName, Dealer.City, Dealer.State),
		ActivityDate		= DBO.SimpleDateTime(DBO.GreaterDate(DBO.GreaterDate(Bids.Offer_Date, Bids.UpdateDateTime), Underwriting.UpdateDateTime)),
		DecisionDate		= DBO.SimpleDateTime(ISNULL(Bids.Offer_Date, Bids.UpdateDateTime)),
		MessageDate			= DBO.SimpleDateTime((SELECT MAX([DateTime]) FROM tblLoanApp_Bids_CommentLog Messages WITH (NOLOCK) WHERE Messages.LoanApp_BidID = Bids.LoanApp_BidID AND [From] = 'LENDER'))
	FROM
					tblLoanApp_Bids					Bids			WITH (NOLOCK)
			 JOIN	tblLoanApps						Apps			WITH (NOLOCK)	ON Apps.LoanAppID			= Bids.LoanAppID
			 JOIN	tblLendersBranches				Branch			WITH (NOLOCK)	ON Branch.LendersBranchID	= Bids.LendersBranchID
			 JOIN	tblLenders						Lender			WITH (NOLOCK)	ON Lender.LenderID			= Branch.LenderID
		LEFT JOIN	tblDealers						Dealer			WITH (NOLOCK)	ON Dealer.DealerID			= Apps.DealerID
		LEFT JOIN	tblLoanApp_Underwriting			Underwriting	WITH (NOLOCK) 	ON Underwriting.LoanAppID	= Bids.LoanAppID		AND	 Underwriting.LenderID = Lender.LenderID




