CREATE VIEW [dbo].[viewBidsLoanAppAssignment] AS
	SELECT
		BID.LoanAppID,
		BID.LoanApp_BidID,
		BID.LendersBranchID,
		DEALER.DealerID,
		RELATION.CustomerNumber,
		RELATION.LastNotificationDateTime,
		RELATION.LenderAgentID,
		RELATION.LenderBranchAgentID,
		LOGIN_LENDER.LendersLoginID,
		LenderUserName = ISNULL(LOGIN_LENDER.UserName, ''),
		LenderFullName = ISNULL(LOGIN_LENDER.FullName, ''),
		LenderColorCode = ISNULL(LOGIN_LENDER.ColorCode, ''),
		LOGIN_BRANCH.LendersBranchLoginID,
		BranchUserName = ISNULL(LOGIN_BRANCH.UserName, ''),
		BranchFullName = ISNULL(LOGIN_BRANCH.FullName, ''),
		--BranchColorCode = ISNULL(LOGIN_BRANCH.FullName, ''),
		LOGIN_DEALER.DealersLoginID,
		DealerUserName = ISNULL(LOGIN_DEALER.UserName, ''),
		DealerFullName = ISNULL(LOGIN_DEALER.FullName, '')
	

	FROM
							tblLoanApps					APPLICATION		WITH (NOLOCK)
				INNER JOIN	tblLoanApp_Bids				BID				WITH (NOLOCK)	ON APPLICATION.LoanAppID				= BID.LoanAppID
				INNER JOIN	tblLendersBranches			BRANCH			WITH (NOLOCK)	ON BID.LendersBranchID					= BRANCH.LendersBranchID
				INNER JOIN	tblDealers					DEALER			WITH (NOLOCK)	ON APPLICATION.DealerID					= DEALER.DealerID
		LEFT	OUTER JOIN	tblLenderDealerRelation		RELATION		WITH (NOLOCK)	ON RELATION.DealerID					= DEALER.DealerID AND BRANCH.LenderID = RELATION.LenderID
		LEFT	OUTER JOIN	tblLendersLogins		    LOGIN_LENDER	WITH (NOLOCK)	ON LOGIN_LENDER.LendersLoginID			= RELATION.LenderAgentID
		LEFT	OUTER JOIN	tblLendersBranchLogins		LOGIN_BRANCH	WITH (NOLOCK)	ON LOGIN_BRANCH.LendersBranchLoginID 	= RELATION.LenderBranchAgentID
		LEFT	OUTER JOIN	tblLoanAppAssignedDealers	ASSIGNED		WITH (NOLOCK)	ON ASSIGNED.LoanAppID					= APPLICATION.LoanAppID
	    LEFT	OUTER JOIN	tblDealersLogins			LOGIN_DEALER	WITH (NOLOCK)	ON LOGIN_DEALER.DealersLoginID			= ASSIGNED.DealersLoginID






