/****** Object:  View dbo.viewBids_AdditionalPartnerDecisions    Script Date: 7/31/2024 12:57:21 PM ******/
CREATE VIEW [dbo].[viewBids_AdditionalPartnerDecisions] AS
	SELECT 
		[LoanApp_Bids_AdditionalPartnerDecisionsID]			= [Decision].[LoanApp_Bids_AdditionalPartnerDecisionsID],
		[PartnerToolID]										= [Partner].[PartnerToolID],
		[Partner]											= [Partner].[ShortName],
		[Source_LoanApp_BidID]								= [Bid].[LoanApp_BidID],
		[Source_LendersBranchID]							= [Branch].[LendersBranchID],
		[LoanAppID]											= [Bid].[LoanAppID],
		[LoanApp_BidID]										= [Bid_Other].[LoanApp_BidID],
		[LenderID]											= [Lender].[LenderID],
		[Lender]											= UPPER([Lender].[LenderName]),
		[LendersBranchID]									= [Branch_Other].[LendersBranchID],
		[Branch]											= UPPER([Branch_Other].[BranchName]),
		[SortSequence]										= [Decision].[SortSequence],
		[YIELD_TYPE]										= [Decision].[YIELD_TYPE],
		[RATE]												= CONVERT(FLOAT, [Decision].[RATE]),
		[TERM]												= [Decision].[TERM],
		[PAYMENT]											= ISNULL([Decision].[PAYMENT],				0),
		[FEE_AMOUNT]										= ISNULL([Decision].[FEE_AMOUNT],			0),
		[DISCOUNT_FEE]										= ISNULL([Decision].[DISCOUNT_FEE],			0),
		[PARTICIPATION_FEE]									= ISNULL([Decision].[PARTICIPATION_FEE],	0),
		[ACQUISITION_FEE]									= ISNULL([Decision].[ACQUISITION_FEE],		0),
		[FINANCING_AMOUNT]									= ISNULL([Decision].[FINANCING_AMOUNT],		0),
		[FUNDED_AMOUNT]										= ISNULL([Decision].[FUNDED_AMOUNT],		0),
		[COMMENTS_HTML]										= [Decision].[COMMENTS_HTML],
		[COMMENTS]											= ISNULL([Decision].[COMMENTS],			''),
		[CreateDateTime]									= [Decision].[CreateDateTime],
		[UpdateDateTime]									= [Decision].[UpdateDateTime],
		[CreateUser]										= [Decision].[CreateUser],
		[UpdateUser]										= [Decision].[UpdateUser],
		[rowVersion]										= [Decision].[rowVersion]
	FROM 
				[tblLoanApp_Bids_AdditionalPartnerDecisions]	[Decision]		WITH (NOLOCK)
		JOIN	[tblPartnerTools]								[Partner]		WITH (NOLOCK) ON [Partner].[PartnerToolID]			= [Decision].[PartnerToolID]
		JOIN	[tblLoanApp_Bids]								[Bid]			WITH (NOLOCK) ON [Bid].[LoanApp_BidID]				= [Decision].[LoanApp_BidID]
		JOIN	[tblLendersBranches]							[Branch]		WITH (NOLOCK) ON [Branch].[LendersBranchID]			= [Bid].[LendersBranchID]
		JOIN	[tblLenders]									[Lender]		WITH (NOLOCK) ON [Lender].[LenderID]				= [Branch].[LenderID]
		JOIN	[tblLoanApp_Bids]								[Bid_Other]		WITH (NOLOCK) ON [Bid_Other].[LoanAppID]			= [Bid].[LoanAppID]
		JOIN	[tblLendersBranches]							[Branch_Other]	WITH (NOLOCK) ON [Branch_Other].[LendersBranchID]	= [Bid_Other].[LendersBranchID]		AND	[Branch_Other].[LenderID]	= [Branch].[LenderID]
	WHERE 
		[Decision].[LoanApp_Bids_AdditionalPartnerDecisionsID] IN (
			SELECT
				MIN([LoanApp_Bids_AdditionalPartnerDecisionsID])
			FROM 
				[tblLoanApp_Bids_AdditionalPartnerDecisions]	[Decision_Inner]	WITH (NOLOCK)
			WHERE 
				[Decision_Inner].[LoanApp_BidID] = [Bid_Other].[LoanApp_BidID] AND [Decision_Inner].[PartnerToolID] = [Decision].[PartnerToolID]
			GROUP BY
				[Decision_Inner].[YIELD_TYPE], [Decision_Inner].[RATE], [Decision_Inner].[TERM], [Decision_Inner].[PAYMENT], [Decision_Inner].[FEE_AMOUNT], [Decision_Inner].[DISCOUNT_FEE], [Decision_Inner].[PARTICIPATION_FEE], [Decision_Inner].[ACQUISITION_FEE], [Decision_Inner].[FINANCING_AMOUNT], [Decision_Inner].[FUNDED_AMOUNT]
		)

