/****** Object:  View dbo.viewBids_CanDelete    Script Date: 7/31/2024 12:57:21 PM ******/
CREATE VIEW viewBids_CanDelete AS
	SELECT
		LoanAppID				= Bid.LoanAppID,
		LoanApp_BidID		= Bid.LoanApp_BidID,
		LenderID				= Branch.LenderID,
		OriginalBidID		= [Original].[LoanApp_BidID],
		CanDelete				=	CONVERT(BIT, CASE WHEN [Bid].[LoanApp_BidID] = [Original].[LoanApp_BidID] THEN 0 WHEN [Bid].[Funded] = 1 THEN 0 WHEN [Bid].[Funded_Date] IS NOT NULL THEN 0 WHEN NULLIF([BFS].[BidFundingStatus], '') IS NOT NULL THEN 0 WHEN [PDE].[PartnerDataElementID] IS NOT NULL THEN 0 ELSE 1 END)
	FROM 
								[tblLoanApp_Bids]									[Bid]				WITH (NOLOCK) 
					JOIN	[tblLendersBranches]							[Branch]		WITH (NOLOCK) ON [Bid].[LendersBranchID]	= [Branch].[LendersBranchID]
					JOIN	[viewBids_OriginalBidID]					[Original]	WITH (NOLOCK) ON [Original].[LoanAppID]		= [Bid].[LoanAppID]					AND [Original].[LenderID] = [Branch].[LenderID]
		LEFT	JOIN	[tblLoanApp_BidFundingStatus]			[BFS]				WITH (NOLOCK) ON [BFS].[LoanApp_BidID]		= [Bid].[LoanApp_BidID]
		LEFT	JOIN	[tblPartnerDataElement]						[PDE]				WITH (NOLOCK) ON [PDE].[LoanApp_BidID]		= [Bid].[LoanApp_BidID]			AND [PDE].[PartnerToolID] = 52

