/****** Object:  View dbo.viewCarletonLenderSpecificDocs    Script Date: 7/31/2024 12:57:21 PM ******/






CREATE      VIEW viewCarletonLenderSpecificDocs AS


/*

  var script = 'ajax/carleton_ajax.asp'

  if ($('#selectLoanDoc').val() == 1050) {
	script = 'ajax/kemba_ajax.asp';
  } else if ($('#selectLoanDoc').val() == 366 ) { 
  	script = 'ajax/sal_ajax.asp';
  } else if ($('#selectLoanDoc').val() == 1134 ) { 
  	script = 'ajax/lotus_ajax.asp';
  } else if ($('#selectLoanDoc').val() == 1197 ) { 
  	script = 'ajax/auto_factors_ajax.asp';

  }


*/

SELECT 
	LB.LenderID, 
	count(*) as num ,
	CASE LB.LenderID 
		WHEN 1050 THEN 'Kemba CU' 
		WHEN 366 THEN 'Security Auto Loans' 
		WHEN 1134 THEN 'Lotus Preferred Funding' 
		WHEN 1197 THEN 'Auto Factors' 
		WHEN 1190 THEN 'Signal Auto Finance' 
		ELSE L.LenderName
	END as DocName,
	CASE LB.LenderID 
		WHEN 1050 THEN 'ajax/kemba_ajax.asp' 
		WHEN 366 THEN 'ajax/sal_ajax.asp' 
		WHEN 1134 THEN 'ajax/lotus_ajax.asp' 
		WHEN 1197 THEN 'ajax/auto_factors_ajax.asp' 
		WHEN 1190 THEN 'ajax/signal_auto_ajax.asp' 
		ELSE 'ajax/carleton_ajax.asp'
	END as DocValue,
	B.LoanAppID 
FROM 
	tblLoanApp_Bids B with (nolock) 
	INNER JOIN tblLendersBranches LB with (nolock) ON LB.LendersBranchID = B.LendersBranchID 
	INNER JOIN tblLenders L with (nolock) ON LB.LenderID = L.LenderID 

	INNER JOIN tblPartnerTools P WITH (NOLOCK) ON P.ShortName = 'CARLETON' AND P.Active = 1
	INNER JOIN tblPartnerRelation PR WITH (NOLOCK) ON P.PartnerToolID = PR.PartnerToolID AND PR.LenderID=L.LenderID 

--		sSQL = "	SELECT r.Active " & _
--						"	FROM tblPartnerTools t WITH (NOLOCK) " & _
--						"		INNER JOIN tblPartnerRelation r WITH (NOLOCK) ON r.PartnerToolID = t.PartnerToolID "  & _
--						"		INNER JOIN tblLenders l WITH (NOLOCK) ON r.LenderID = l.LenderID " & _
--						"	WHERE t.ShortName = 'CARLETON' AND l.LenderID =" & SuperCLng(Session("LenderID"))

WHERE 
PR.Active=1
--	LB.LenderID IN (1050, 366, 1134, 1197, 1190) 

GROUP BY 
	LB.LenderID,
	B.LoanAppID,
	L.LenderName








GO

