/****** Object:  View dbo.viewCreditPulls_AdditionalReasons    Script Date: 7/31/2024 12:57:21 PM ******/

--DECLARE @_CreditPullID INTEGER; SET @_CreditPullID = 834994;

CREATE VIEW viewCreditPulls_AdditionalReasons AS
	SELECT TOP 100 PERCENT
		CreditPullID	= ASI_1.CreditPullID,
		GUID			= ASI_1.GUID,
		ReasonID_1	= ASI_1.AdditionalScoreReasonID,
		Caption_1	= ISNULL(ASR_1.Caption,		''),

		ReasonID_2	= NULLIF(CASE	WHEN	ASR_2.Caption	IS NULL										THEN 0
									WHEN	ISNULL(ASR_2.Caption, '')	=	ISNULL(ASR_1.Caption, '')	THEN 0
									WHEN	ISNULL(ASR_2.Caption, '')	=	ISNULL(ASR_3.Caption, '')	THEN 0
									WHEN	ISNULL(ASR_2.Caption, '')	=	ISNULL(ASR_4.Caption, '')	THEN 0
									ELSE	ASR_2.AdditionalScoreReasonID END, 0),

		Caption_2	= CASE	WHEN	ASR_2.Caption	IS NULL										THEN ''
							WHEN	ISNULL(ASR_2.Caption, '')	=	ISNULL(ASR_1.Caption, '')	THEN ''
							WHEN	ISNULL(ASR_2.Caption, '')	=	ISNULL(ASR_3.Caption, '')	THEN ''
							WHEN	ISNULL(ASR_2.Caption, '')	=	ISNULL(ASR_4.Caption, '')	THEN ''
							ELSE	ASR_2.Caption END,

		ReasonID_3	= NULLIF(CASE	WHEN	ASR_3.Caption	IS NULL										THEN 0
									WHEN	ISNULL(ASR_3.Caption, '')	=	ISNULL(ASR_1.Caption, '')	THEN 0
									WHEN	ISNULL(ASR_3.Caption, '')	=	ISNULL(ASR_2.Caption, '')	THEN 0
									WHEN	ISNULL(ASR_3.Caption, '')	=	ISNULL(ASR_4.Caption, '')	THEN 0
									ELSE	ASR_3.AdditionalScoreReasonID END, 0),

		Caption_3	= CASE	WHEN	ASR_3.Caption	IS NULL										THEN ''
							WHEN	ISNULL(ASR_3.Caption, '')	=	ISNULL(ASR_1.Caption, '')	THEN ''
							WHEN	ISNULL(ASR_3.Caption, '')	=	ISNULL(ASR_2.Caption, '')	THEN ''
							WHEN	ISNULL(ASR_3.Caption, '')	=	ISNULL(ASR_4.Caption, '')	THEN ''
							ELSE	ASR_3.Caption END,


		ReasonID_4	= NULLIF(CASE	WHEN	ASR_4.Caption	IS NULL										THEN 0
									WHEN	ISNULL(ASR_4.Caption, '')	=	ISNULL(ASR_1.Caption, '')	THEN 0
									WHEN	ISNULL(ASR_4.Caption, '')	=	ISNULL(ASR_2.Caption, '')	THEN 0
									WHEN	ISNULL(ASR_4.Caption, '')	=	ISNULL(ASR_3.Caption, '')	THEN 0
									ELSE	ASR_4.AdditionalScoreReasonID END, 0),

		Caption_4	= CASE	WHEN	ASR_4.Caption	IS NULL										THEN ''
							WHEN	ISNULL(ASR_4.Caption, '')	=	ISNULL(ASR_1.Caption, '')	THEN ''
							WHEN	ISNULL(ASR_4.Caption, '')	=	ISNULL(ASR_2.Caption, '')	THEN ''
							WHEN	ISNULL(ASR_4.Caption, '')	=	ISNULL(ASR_3.Caption, '')	THEN ''
							ELSE	ASR_4.Caption END
	FROM
					tblCreditPulls								CREDIT	WITH (NOLOCK)
		LEFT JOIN	tblCreditPulls_AdditionalScoreInformation 	ASI_1	WITH (NOLOCK) ON ASI_1.CreditPullID				= CREDIT.CreditPullID
		LEFT JOIN	view_Credit_AdditionalScoreReasons			ASR_1	WITH (NOLOCK) ON ASR_1.AdditionalScoreReasonID	= ASI_1.AdditionalScoreReasonID

		LEFT JOIN	tblCreditPulls_AdditionalScoreInformation 	ASI_2	WITH (NOLOCK) ON ASI_2.CreditPullID				= ASI_1.CreditPullID				AND	ASI_2.AdditionalScoreReasonID 	> ASI_1.AdditionalScoreReasonID
		LEFT JOIN	view_Credit_AdditionalScoreReasons			ASR_2	WITH (NOLOCK) ON ASR_2.AdditionalScoreReasonID	= ASI_2.AdditionalScoreReasonID		

		LEFT JOIN	tblCreditPulls_AdditionalScoreInformation 	ASI_3	WITH (NOLOCK) ON ASI_3.CreditPullID				= ASI_1.CreditPullID				AND	ASI_3.AdditionalScoreReasonID > ASI_2.AdditionalScoreReasonID
		LEFT JOIN	view_Credit_AdditionalScoreReasons			ASR_3	WITH (NOLOCK) ON ASR_3.AdditionalScoreReasonID	= ASI_3.AdditionalScoreReasonID

		LEFT JOIN	tblCreditPulls_AdditionalScoreInformation 	ASI_4	WITH (NOLOCK) ON ASI_4.CreditPullID				= ASI_1.CreditPullID				AND	ASI_4.AdditionalScoreReasonID > ASI_3.AdditionalScoreReasonID
		LEFT JOIN	view_Credit_AdditionalScoreReasons			ASR_4	WITH (NOLOCK) ON ASR_4.AdditionalScoreReasonID	= ASI_4.AdditionalScoreReasonID
	WHERE
			--ASI_1.CreditPullID = @_CreditPullID and
			ASI_1.AdditionalScoreReasonID = (SELECT MIN(AdditionalScoreReasonID) FROM tblCreditPulls_AdditionalScoreInformation ASI_INNER WITH (NOLOCK) WHERE ASI_INNER.CreditPullID = ASI_1.CreditPullID AND ASI_INNER.AdditionalScoreReasonID IN (SELECT AdditionalScoreReasonID FROM view_Credit_AdditionalScoreReasons))
	ORDER BY
		ASI_1.AdditionalScoreReasonID,
		ASI_2.AdditionalScoreReasonID,
		ASI_3.AdditionalScoreReasonID,
		ASI_4.AdditionalScoreReasonID





GO

