/****** Object:  View dbo.viewCurrentlyLoggedInStamp_Inner    Script Date: 7/31/2024 12:57:21 PM ******/

	CREATE VIEW viewCurrentlyLoggedInStamp_Inner AS
		SELECT
			[Stamp].[CurrentlyLoggedInID],
			[Date]									= DATEADD(s, -DATEDIFF(s, GETDATE(), GETUTCDATE()) + [Stamp].[Time], '1970-01-01'),
			-- [Day]								= CONVERT(DATETIME, LEFT(CONVERT(VARCHAR(30), MIN([LoggedIn].[LoginDateTime]), 120), 10)),
			[Start] = [Stamp].[time],
			-- [After] = (SELECT COUNT(*) FROM [tblCurrentlyLoggedInStamp] [Next] WITH (NOLOCK) WHERE [Next].[CurrentlyLoggedInID] = [Stamp].[CurrentlyLoggedInID] AND [Next].[Time] > [Stamp].[Time] AND [Next].[Time] - [Stamp].[Time] < 1800),
			-- [Before] = (SELECT COUNT(*) FROM [tblCurrentlyLoggedInStamp] [Next] WITH (NOLOCK) WHERE [Next].[CurrentlyLoggedInID] = [Stamp].[CurrentlyLoggedInID] AND [Next].[Time] < [Stamp].[Time] AND [Stamp].[Time] - [Next].[Time] < 1800),
			[Duration] = (SELECT MIN([Time]) FROM [tblCurrentlyLoggedInStamp] [Next] WITH (NOLOCK) WHERE [Next].[CurrentlyLoggedInID] = [Stamp].[CurrentlyLoggedInID] AND [Next].[Time] >= [Stamp].[Time] AND NOT EXISTS(SELECT * FROM [tblCurrentlyLoggedInStamp] [AfterNext] WITH (NOLOCK) WHERE [AfterNext].[CurrentlyLoggedInID] = [Stamp].[CurrentlyLoggedInID] AND [AfterNext].[Time] > [Next].[Time] AND ([AfterNext].[Time] - [Next].[Time]) < 1800) ) - [Stamp].[Time],
			-- DATEADD(ss, [Stamp].[Time] + DATEDIFF(ss, GETUTCDATE(), GETDATE()), '1970-01-01') [SessionStart],
			-- DATEADD(ss, ([Last].[Time]) + DATEDIFF(ss, GETUTCDATE(), GETDATE()), '1970-01-01') [SessionStop]
			[CustomerID]						= ISNULL([Dealer_Login].[DealerID], ISNULL([Branch_Login].[LendersBranchID], ISNULL([Lender].[LenderID], ISNULL([Affiliate_Login].[AffiliateID], 0)))),
			[Type]									= CASE WHEN [LoggedIn].[DealersLoginID] IS NOT NULL THEN 'DealerID' WHEN [LoggedIn].[LendersLoginID] IS NOT NULL THEN 'LenderID' WHEN [LoggedIn].[LendersBranchLoginID] IS NOT NULL THEN 'LendersBranchID' WHEN [LoggedIn].[AdminLoginID] IS NOT NULL THEN 'Admin' WHEN [LoggedIn].[AffiliateLoginID] IS NOT NULL THEN 'AffiliateID' ELSE 'Other' END,
			[KeyValueType]					= CASE WHEN [LoggedIn].[DealersLoginID] IS NOT NULL THEN 'DealersLoginID' WHEN [LoggedIn].[LendersLoginID] IS NOT NULL THEN 'LendersLoginID' WHEN [LoggedIn].[LendersBranchLoginID] IS NOT NULL THEN 'LendersBranchLoginID' WHEN [LoggedIn].[AdminLoginID] IS NOT NULL THEN 'AdminLoginID' WHEN [LoggedIn].[AffiliateLoginID] IS NOT NULL THEN 'AffiliateLoginID' ELSE 'Other' END,
			[KeyValue]							= CASE WHEN [LoggedIn].[DealersLoginID] IS NOT NULL THEN [LoggedIn].[DealersLoginID] WHEN [LoggedIn].[LendersLoginID] IS NOT NULL THEN [LoggedIn].[LendersLoginID] WHEN [LoggedIn].[LendersBranchLoginID] IS NOT NULL THEN [LoggedIn].[LendersBranchLoginID] WHEN [LoggedIn].[AdminLoginID] IS NOT NULL THEN [LoggedIn].[AdminLoginID] WHEN [LoggedIn].[AffiliateLoginID] IS NOT NULL THEN [LoggedIn].[AffiliateLoginID] END,
			[LoggedIn].[DealersLoginID],
			[LoggedIn].[LendersLoginID],
			[LoggedIn].[LendersBranchLoginID],
			[LoggedIn].[AdminLoginID],
			[LoggedIn].[AffiliateLoginID],
			[DealerID]							= [Dealer_Login].[DealerID],
			[LendersBranchID] 			= [Branch_Login].[LendersBranchID],
			[LenderID]							= [Lender].[LenderID]
		FROM
									[tblCurrentlyLoggedInStamp]						[Stamp] 						WITH (NOLOCK)
						JOIN	[tblCurrentlyLoggedIn] 								[LoggedIn]					WITH (NOLOCK) ON [LoggedIn].[CurrentlyLoggedInID] 	= [Stamp].[CurrentlyLoggedInID]
			LEFT	JOIN	[tblAdminLogins]											[Admin_Login]				WITH (NOLOCK)	ON [LoggedIn].[AdminLoginID]					= [Admin_Login].[AdminLoginID]
			LEFT	JOIN	[tblLendersLogins]										[Lender_Login]			WITH (NOLOCK)	ON [LoggedIn].[LendersLoginID]				= [Lender_Login].[LendersLoginID]
			LEFT	JOIN	[tblLendersBranchLogins]							[Branch_Login]			WITH (NOLOCK)	ON [LoggedIn].[LendersBranchLoginID]	= [Branch_Login].[LendersBranchLoginID]
			LEFT	JOIN	[tblDealersLogins]										[Dealer_Login]			WITH (NOLOCK)	ON [LoggedIn].[DealersLoginID]				= [Dealer_Login].[DealersLoginID]
			LEFT	JOIN	[tblAffiliateLogins]									[Affiliate_Login]		WITH (NOLOCK)	ON [LoggedIn].[AffiliateLoginID]			= [Affiliate_Login].[AffiliateLoginID]
			LEFT	JOIN	[tblLendersBranches]									[Branch]						WITH (NOLOCK) ON [Branch].[LendersBranchID]					= [Branch_Login].[LendersBranchID]
			LEFT	JOIN	[tblLenders]													[Lender]						WITH (NOLOCK) ON [Lender].[LenderID]								= ISNULL([Lender_Login].[LenderID], [Branch].[LenderID])
			LEFT	JOIN	[tblDealers]													[Dealer]						WITH (NOLOCK) ON [Dealer].[DealerID]								= [Dealer_Login].[DealerID]
		WHERE
			NOT EXISTS(SELECT * FROM [tblCurrentlyLoggedInStamp] [Before] WITH (NOLOCK) WHERE [Before].[CurrentlyLoggedInID]	= [Stamp].[CurrentlyLoggedInID] AND [Before].[Time]	< [Stamp].[Time] AND [Stamp].[Time]	- [Before].[Time]	< 1800)
		GROUP BY
			[Stamp].[CurrentlyLoggedInID],
			[LoggedIn].[DealersLoginID],
			[LoggedIn].[LendersLoginID],
			[LoggedIn].[LendersBranchLoginID],
			[LoggedIn].[AdminLoginID],
			[LoggedIn].[AffiliateLoginID],
			[Lender].[LenderID],
			[Branch_Login].[LendersBranchID],
			[Dealer_Login].[DealerID],
			[Affiliate_Login].[AffiliateID],
			[Stamp].[Time]

