/****** Object:  View dbo.viewCurrentlyLoggedIn_Outer    Script Date: 7/31/2024 12:57:21 PM ******/

	CREATE VIEW viewCurrentlyLoggedIn_Outer AS
		SELECT
			[CurrentlyLoggedInID]		= [LoggedIn].[CurrentlyLoggedInID],
			[UserName]							= ISNULL([Dealer_Login].[UserName], ISNULL([Branch_Login].[UserName], ISNULL([Lender_Login].[UserName], [Admin_Login].[UserName]))),
			[FullName]							= ISNULL(NULLIF(RTRIM(ISNULL([Dealer_Login].[FullName], ISNULL([Branch_Login].[FullName], ISNULL([Lender_Login].[FullName], [Admin_Login].[FullName])))), ''), ISNULL([Dealer_Login].[UserName], ISNULL([Branch_Login].[UserName], ISNULL([Lender_Login].[UserName], [Admin_Login].[UserName])))),
			[Day]										= CONVERT(DATETIME, LEFT(CONVERT(VARCHAR(30), [LoggedIn].[LoginDateTime], 120), 10)),
			[FirstActivity]					= DATEADD(s, -DATEDIFF(s, GETDATE(), GETUTCDATE()) + (SELECT MIN([Time]) FROM [tblCurrentlyLoggedInStamp] [Stamp] WITH (NOLOCK) WHERE [Stamp].[CurrentlyLoggedInID] = [LoggedIn].[CurrentlyLoggedInID]), '1970-01-01'),
			[LastActivity]					= DATEADD(s, -DATEDIFF(s, GETDATE(), GETUTCDATE()) + (SELECT MAX([Time]) FROM [tblCurrentlyLoggedInStamp] [Stamp] WITH (NOLOCK) WHERE [Stamp].[CurrentlyLoggedInID] = [LoggedIn].[CurrentlyLoggedInID]), '1970-01-01'),
			[CustomerID]						= ISNULL([Dealer_Login].[DealerID], ISNULL([Branch_Login].[LendersBranchID], ISNULL([Lender].[LenderID], ISNULL([Affiliate_Login].[AffiliateID], 0)))),
			[CustomerIDType]				= CASE WHEN [LoggedIn].[DealersLoginID] IS NOT NULL THEN 'DealerID' WHEN [LoggedIn].[LendersLoginID] IS NOT NULL THEN 'LenderID' WHEN [LoggedIn].[LendersBranchLoginID] IS NOT NULL THEN 'LendersBranchID' WHEN [LoggedIn].[AdminLoginID] IS NOT NULL THEN 'Admin' WHEN [LoggedIn].[AffiliateLoginID] IS NOT NULL THEN 'AffiliateID' ELSE 'Other' END,
			[Customer]							= ISNULL([Dealer].[DealerName], ISNULL([Branch].[BranchName], ISNULL([Lender].[LenderName], ISNULL([Affiliate].[Name], 'CreditSmarts')))),
			[CompanyCode]						= ISNULL([Dealer].[LoginPrefix], ISNULL([Branch].[LoginPrefix], ISNULL([Lender].[LoginPrefix], CASE WHEN [LoggedIn].[AdminLoginID] IS NOT NULL THEN 'CSMarts_Internal' ELSE '' END))),
			[LoginID]								= CASE WHEN [LoggedIn].[DealersLoginID] IS NOT NULL THEN [LoggedIn].[DealersLoginID] WHEN [LoggedIn].[LendersLoginID] IS NOT NULL THEN [LoggedIn].[LendersLoginID] WHEN [LoggedIn].[LendersBranchLoginID] IS NOT NULL THEN [LoggedIn].[LendersBranchLoginID] WHEN [LoggedIn].[AdminLoginID] IS NOT NULL THEN [LoggedIn].[AdminLoginID] WHEN [LoggedIn].[AffiliateLoginID] IS NOT NULL THEN [LoggedIn].[AffiliateLoginID] END,
			[LoginIDType]						= CASE WHEN [LoggedIn].[DealersLoginID] IS NOT NULL THEN 'DealersLoginID' WHEN [LoggedIn].[LendersLoginID] IS NOT NULL THEN 'LendersLoginID' WHEN [LoggedIn].[LendersBranchLoginID] IS NOT NULL THEN 'LendersBranchLoginID' WHEN [LoggedIn].[AdminLoginID] IS NOT NULL THEN 'AdminLoginID' WHEN [LoggedIn].[AffiliateLoginID] IS NOT NULL THEN 'AffiliateLoginID' ELSE 'Other' END,
			[DealersLoginID]				= [LoggedIn].[DealersLoginID],
			[LendersLoginID]				= [LoggedIn].[LendersLoginID],
			[LendersBranchLoginID]	= [LoggedIn].[LendersBranchLoginID],
			[AdminLoginID]					= [LoggedIn].[AdminLoginID],
			[AffiliateLoginID]			= [LoggedIn].[AffiliateLoginID],
			[DealerID]							= [Dealer_Login].[DealerID],
			[LendersBranchID] 			= [Branch_Login].[LendersBranchID],
			[LenderID]							= [Lender].[LenderID],
			[AffiliateID]						= [Affiliate].[AffiliateID]
		FROM
									[tblCurrentlyLoggedIn] 								[LoggedIn]					WITH (NOLOCK)
			LEFT	JOIN	[tblAdminLogins]											[Admin_Login]				WITH (NOLOCK)	ON [LoggedIn].[AdminLoginID]					= [Admin_Login].[AdminLoginID]
			LEFT	JOIN	[tblLendersLogins]										[Lender_Login]			WITH (NOLOCK)	ON [LoggedIn].[LendersLoginID]				= [Lender_Login].[LendersLoginID]
			LEFT	JOIN	[tblLendersBranchLogins]							[Branch_Login]			WITH (NOLOCK)	ON [LoggedIn].[LendersBranchLoginID]	= [Branch_Login].[LendersBranchLoginID]
			LEFT	JOIN	[tblDealersLogins]										[Dealer_Login]			WITH (NOLOCK)	ON [LoggedIn].[DealersLoginID]				= [Dealer_Login].[DealersLoginID]
			LEFT	JOIN	[tblAffiliateLogins]									[Affiliate_Login]		WITH (NOLOCK)	ON [LoggedIn].[AffiliateLoginID]			= [Affiliate_Login].[AffiliateLoginID]
			LEFT	JOIN	[tblLendersBranches]									[Branch]						WITH (NOLOCK) ON [Branch].[LendersBranchID]					= [Branch_Login].[LendersBranchID]
			LEFT	JOIN	[tblLenders]													[Lender]						WITH (NOLOCK) ON [Lender].[LenderID]								= ISNULL([Lender_Login].[LenderID], [Branch].[LenderID])
			LEFT	JOIN	[tblDealers]													[Dealer]						WITH (NOLOCK) ON [Dealer].[DealerID]								= [Dealer_Login].[DealerID]
			LEFT	JOIN	[tblAffiliates]												[Affiliate]					WITH (NOLOCK) ON [Affiliate].[AffiliateID]					= [Affiliate_Login].[AffiliateID]
	WHERE
		EXISTS(SELECT * FROM [tblCurrentlyLoggedInStamp] [Stamp] WITH (NOLOCK) WHERE [Stamp].[CurrentlyLoggedInID] = [LoggedIn].[CurrentlyLoggedInID])
		-- AND [LoggedIn].[LoginDateTime] >= LEFT(CONVERT(VARCHAR(30), GETDATE(), 120), 10)

