                      dbo.tblDealersBilling.dealer_service_id, dbo.tblRatePlans.rate_plan_cd, dbo.tblRatePlans.rate_plan, dbo.tblRatePlans.service_loan,
                      dbo.tblRatePlans.service_inventory, dbo.tblRatePlans.setup_cost, dbo.tblRatePlans.monthly_cost, dbo.tblDealersBilling.billing_start_dt,
