/****** Object:  View dbo.viewDealersBillingActivePayFlow    Script Date: 7/31/2024 12:57:21 PM ******/


CREATE VIEW [dbo].[viewDealersBillingActivePayFlow] AS
	SELECT 
		DealerID			= Dealers.DealerID,
		Dealer_Service_ID	= Billing.Dealer_Service_ID,
		ARB_ProfileID		= Billing.ARB_ProfileID,
		BillingStatus		= Billing.Status,
		DealerStatus		= Dealers.DealerStatus
	FROM 		
				tblDealersBilling		Billing		WITH (NOLOCK)
