/****** Object:  View dbo.viewDealersDefaultAssetType    Script Date: 7/31/2024 12:57:21 PM ******/

--
CREATE VIEW viewDealersDefaultAssetType		AS
	SELECT --TOP 100
		DealerID				= DEALER.DealerID,
		AssetType				= ISNULL(MODES.AssetType,		0),
		AssetTypeName			= CASE ISNULL(MODES.AssetType, 0)
										WHEN	0	THEN	'AUTO'
										WHEN	1	THEN	'CONSUMER'
										WHEN	2	THEN	'SOLAR'
										WHEN	3	THEN	'FAX'
										WHEN	4	THEN	'CREDIT'
										ELSE 'UNKNOWN'	END,

		IsAutomobile			= CONVERT(BIT, CASE WHEN ISNULL(MODES.AssetType, 0) = 0 THEN 1 ELSE 0 END),
		IsConsumer				= CONVERT(BIT, CASE WHEN ISNULL(MODES.AssetType, 0) = 1 THEN 1 ELSE 0 END),
		IsSolar					= CONVERT(BIT, CASE WHEN ISNULL(MODES.AssetType, 0) = 2 THEN 1 ELSE 0 END),
		IsFax					= CONVERT(BIT, CASE WHEN ISNULL(MODES.AssetType, 0) = 3 THEN 1 ELSE 0 END),
		IsCredit				= CONVERT(BIT, CASE WHEN ISNULL(MODES.AssetType, 0) = 4 THEN 1 ELSE 0 END),
		IsDefault				= ISNULL(MODES.IsDefault,		1),

		CreditApplicationURL	= '/CreditSmarts/LoanApps/' + CASE ISNULL(MODES.AssetType, 0)
									WHEN 2		THEN 'Solar.2'
									ELSE 'Auto'
								END + '/Step_1.asp',

		CreateDateTime			= ISNULL(MODES.CreateDateTime,	GETDATE()),
		CreateUser				= ISNULL(MODES.CreateUser,		'CreditSmarts:System'),
		UpdateDateTime			= ISNULL(MODES.UpdateDateTime,	GETDATE()),
		UpdateUser				= ISNULL(MODES.UpdateUser,		'CreditSmarts:System')
	FROM
				tblDealers								DEALER	WITH (NOLOCK)
		JOIN	tblDealers_AllowedApplicationModes		MODES	WITH (NOLOCK)	ON	MODES.DealerID = DEALER.DealerID
	WHERE
				DEALER.DealerStatus NOT IN ('INACTIVE')
--AND MODES.AssetType = 2





