/****** Object:  View dbo.viewDealers_Active    Script Date: 7/31/2024 12:57:21 PM ******/


CREATE VIEW [dbo].[viewDealers_Active] AS
  SELECT TOP 100 PERCENT
    DealerID = CONVERT(int, DealerID),
    LoginPrefix,
    DealerName = DEALER.DealerName,
    City,
    State,
    ZIP,
    Independent = CASE
      WHEN DealerType = 'Franchise' THEN 0
      Else 1
    END,
    Franchise = CASE
      WHEN DealerType = 'Franchise' THEN 1
      ELSE 0
    END
  FROM
    tblDealers DEALER WITH (NOLOCK)
  WHERE
    (     ISNULL(DealerStatus, 'INACTIVE') <> 'INACTIVE'
      AND LoginPrefix IS NOT NULL
      AND Len(LoginPrefix) > 0
      AND loginPrefix NOT LIKE '%cancel%'
      AND LoginPrefix NOT LIKE '%disc%'
      AND LoginPrefix NOT LIKE '%CLOSED%'
      AND LoginPrefix NOT LIKE '%CLOSING%'
      AND LoginPrefix NOT LIKE '%bill%'
      AND LoginPrefix NOT LIKE '%lock%'
      AND LoginPrefix NOT LIKE '%not%interested%'
      AND LoginPrefix NOT LIKE '%see%note%'
      AND LoginPrefix NOT LIKE '%de%act%'
      AND LoginPrefix NOT LIKE '%out%'
      AND LoginPrefix NOT LIKE '%want%'
      AND LoginPrefix NOT LIKE '%shut%'
      AND LoginPrefix NOT LIKE '%denied%'
      AND LoginPrefix NOT LIKE '%charge%back%'
      AND LoginPrefix NOT LIKE 'not %'
      AND LoginPrefix NOT LIKE 'turned%of%'
      AND LoginPrefix NOT LIKE 'no %'
      AND LoginPrefix NOT LIKE 'bad %'
      AND LoginPrefix NOT LIKE 'needs %'
      AND LoginPrefix NOT LIKE 'wrong %')
    OR EXISTS (SELECT * from tblLenderDealerRelation R WITH (NOLOCK) WHERE R.DealerID = DEALER.DealerID AND R.CUSTOMER_TYPE='INTERNAL')
  ORDER BY
    DealerID





