/****** Object:  View dbo.viewFreeForm_FundingCheckList    Script Date: 7/31/2024 12:57:21 PM ******/


CREATE VIEW viewFreeForm_FundingCheckList AS

SELECT TOP 100 PERCENT
	FundingCheckListID = FF.ID,
	FC.LoanAppID,
	FC.LenderID,

	Property = CASE
		WHEN SUBSTRING(FF.Property, 1, 45) = 'FUNDING_CHECKLIST/FUNDING_CHECKLIST_APPLICANT' THEN
			SUBSTRING(FF.Property, 37, 8000)

		WHEN SUBSTRING(FF.Property, 1, 45) = 'FUNDING_CHECKLIST/FUNDING_CHECKLIST_REFERENCE' THEN
			SUBSTRING(FF.Property, 37, 8000)

		WHEN SUBSTRING(FF.Property, 1, 18) = 'FUNDING_CHECKLIST/' THEN
			SUBSTRING(FF.Property, 19, 8000)

		ELSE
			FF.Property

	END,
	FF.PlainText,
	FF.FreeFormID,
	FF.UpdateDateTime,
	FF.UpdateUser

FROM
	viewFreeForm FF WITH (NOLOCK)
	JOIN tblLoanApp_FundingCheckList FC WITH (NOLOCK) ON (FF.Object = 'tblLoanApp_FundingChecklist' AND FF.ID = FC.FundingCheckListID)
ORDER BY
	FF.UpdateDateTime DESC




