/****** Object:  View dbo.viewInterfaceDealerNewDeals_BACKUP_2013_07_04    Script Date: 7/31/2024 12:57:21 PM ******/

--ALTER   VIEW viewInterfaceDealerNewDeals AS

--viewDealersDefaultAssetType
CREATE view viewInterfaceDealerNewDeals_BACKUP_2013_07_04 AS
	SELECT
		BID.LoanAppID,
		BID.LoanApp_BidID,
		DEALER.DealerID,
		AUTO_LOAN_APP.APPLICANT_NAMES,
		BID.YIELD_TYPE,
		COMMENTS = '',

	TERM = CASE
		WHEN TERM IS NULL 				THEN NULL
		WHEN ISNUMERIC(TERM) = 1		THEN TERM
		WHEN TERM = ''					THEN NULL
		WHEN CHARINDEX('M', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('M', TERM) - 1))
		WHEN CHARINDEX('/', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('/', TERM) - 1))
		WHEN CHARINDEX(' ', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX(' ', TERM) - 1))
		ELSE -1
	END,
		PAYMENT,
		MESSAGING_STATUS,
		REBATE_PERCT,
		ADVANCE,
		LENDER.LenderID,

		BidAge = DATEDIFF(day, Bid.UpdateDateTime, GetDate()),

		LENDER_ARCHIVED = ISNULL(BID.LENDER_ARCHIVED, 0),

		Canceled = CASE
			WHEN Canceled_Date IS NULL THEN CONVERT(BIT, 0)
			ELSE CONVERT(BIT, 1)
		End,

		Canceled_Date,

		Funded = CASE
			WHEN FUNDED_DATE IS NOT NULL THEN CONVERT(BIT, 1)
			WHEN Funded IS NULL THEN CONVERT(BIT, 0)
			ELSE CONVERT(BIT, Funded)
		End,

		ShowInLenderNewDeals = 0,
		ShowInLenderPendingFunding = 0,
		ShowInLenderMessaging = 0,
		ShowInDealerNewDeals = 1,
		ShowInDealerMessaging = CASE
			WHEN NOT Canceled_Date	IS NULL									THEN CONVERT(BIT, 0)
			WHEN BID.LENDER_ARCHIVED	=  1 									THEN CONVERT(BIT, 0)
			WHEN DATEDIFF(day, Bid.UpdateDateTime, GetDate()) > 14			THEN CONVERT(BIT, 0)
			WHEN Messaging_Status = 'COMMENT_FOR_DEALER'					THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
		END,

		ShowInDealerFunding = CASE
			WHEN StatusUpdateDateTime	IS	NULL						THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus		IS	NULL						THEN CONVERT(BIT, 0)
			WHEN LEN(BidFundingStatus)	=	0							THEN CONVERT(BIT, 0)
			WHEN DATEDIFF(day, StatusUpdateDateTime, getdate()) > 45	THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'RECEIVED'							THEN CONVERT(BIT, 1)
			WHEN DATEDIFF(day, StatusUpdateDateTime, getdate()) > 30	THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'REJECTED'							THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
			--ELSE CONVERT(BIT, 1)
		END,

		ANTICIPATED_RATE			= ISNULL(WS.ANTICIPATED_RATE,       AUTO_LOAN_APP.ANTICIPATED_RATE),
		LOAN_DOWN_PAYMENT			= ISNULL(WS.LOAN_DOWN_PAYMENT,      AUTO_LOAN_APP.LOAN_DOWN_PAYMENT),
		LOAN_ESTIMATED_PAYMENT		= ISNULL(WS.LOAN_ESTIMATED_PAYMENT, AUTO_LOAN_APP.LOAN_ESTIMATED_PAYMENT),
		LOAN_LICENSE				= ISNULL(WS.LOAN_LICENSE,           AUTO_LOAN_APP.LOAN_LICENSE),
		LOAN_MISC					= ISNULL(WS.LOAN_MISC,              AUTO_LOAN_APP.LOAN_MISC),
		LOAN_PURCHASE_PRICE			= ISNULL(WS.LOAN_PURCHASE_PRICE,    AUTO_LOAN_APP.LOAN_PURCHASE_PRICE),
		LOAN_TAX					= ISNULL(WS.LOAN_TAX,               AUTO_LOAN_APP.LOAN_TAX),
		LOAN_TERM_REQUESTED			= ISNULL(WS.LOAN_TERM_REQUESTED,    AUTO_LOAN_APP.LOAN_TERM_REQUESTED),
		LOAN_TOTAL_LOAN_AMOUNT		= ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT),
		LOAN_WARRANTY				= ISNULL(WS.LOAN_WARRANTY,          AUTO_LOAN_APP.LOAN_WARRANTY),
		VEHICLE_DESCRIPTION			= ISNULL(WS.VEHICLE_DESCRIPTION,    AUTO_LOAN_APP.VEHICLE_DESCRIPTION),
		VEHICLE_MAKE				= ISNULL(WS.VEHICLE_MAKE,           AUTO_LOAN_APP.VEHICLE_MAKE),
		VEHICLE_MILEAGE				= ISNULL(WS.VEHICLE_MILEAGE,        AUTO_LOAN_APP.VEHICLE_MILEAGE),	
		VEHICLE_MODEL				= ISNULL(WS.VEHICLE_MODEL,          AUTO_LOAN_APP.VEHICLE_MODEL),
		VEHICLE_VIN					= ISNULL(WS.VEHICLE_VIN,            AUTO_LOAN_APP.VEHICLE_VIN),
		VEHICLE_YEAR				= ISNULL(WS.VEHICLE_YEAR,           AUTO_LOAN_APP.VEHICLE_YEAR),
		VEHICLE						= ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), AUTO_LOAN_APP.VEHICLE_YEAR) + ' ' + AUTO_LOAN_APP.VEHICLE_MAKE + ' ' + AUTO_LOAN_APP.VEHICLE_MODEL),

		FUNDED_DATE,

		FINANCING_AMOUNT,
		WorkSheetID					= WS.LoanApp_WorksheetID,
		AUTO_LOAN_APP.NEW_USED,
		BID.STATUS,
		ARCHIVED = ISNULL(AUTO_LOAN_APP.ARCHIVED, 0),
		Dealer						=   DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State,
		DealerEMail					= DEALER.EMail,
		AUTO_LOAN_APP.UpdateUser,
		AUTO_LOAN_APP.CreateUser,
		AUTO_LOAN_APP.UpdateDateTime,
		AUTO_LOAN_APP.CreateDateTime,
		RATE,
		LENDER_BRANCH.LendersBranchID,
	Lender            = LENDER_BRANCH.LenderName + N' - ' + LENDER_BRANCH.BranchName + N' (' + LENDER_BRANCH.CITY + N', ' + LENDER_BRANCH.STATE + N')',
	LenderName        = ISNULL(LENDER.LenderName, ''),
		BidCreateDateTime				= BID.CreateDateTime,
		BidUpdateDateTime				= Bid.UpdateDateTime,
		BidSubmitDateTime				= BID.Submit_Date,
			LenderCity					= ISNULL(LENDER.City, ''),
			LenderState					= ISNULL(LENDER.State, ''),

		DealerName = DEALER.DealerName,

		Stips,
		Reason,

		-- DEALER CREDIT
		DEALER_CREDIT_EX				= ISNULL(AUTO_LOAN_APP.DEALER_CREDIT_EX, ''),
		DEALER_CREDIT_EQ				= ISNULL(AUTO_LOAN_APP.DEALER_CREDIT_EQ, ''),
		DEALER_CREDIT_TU				= ISNULL(AUTO_LOAN_APP.DEALER_CREDIT_TU, ''),
		
		-- LENDER CREDIT
		LENDER_CREDIT_EQ				= ISNULL(BID.LENDER_CREDIT_EQ, ISNULL(AUTO_LOAN_APP.LENDER_CREDIT_EQ, '')),
		LENDER_CREDIT_TU				= ISNULL(BID.LENDER_CREDIT_TU, ISNULL(AUTO_LOAN_APP.LENDER_CREDIT_TU, '')),
		LENDER_CREDIT_EX				= ISNULL(BID.LENDER_CREDIT_EX, ISNULL(AUTO_LOAN_APP.LENDER_CREDIT_EX, '')),
		Reasons,
		DISCOUNT_FEE,
		AUTOMATED,

		OFFER_DATE,

		OFFERED_BY,
		ACCEPT_DATE,
		SUBMIT_DATE,
		SUBMIT_BY,
		PRIMARY_SCORE,
		SECONDARY_SCORE,
		ACCEPT_BY,
		PTI,
		DTI,
		REMINDER_DATE					= BID.REMINDER_DATE,

	------------------------------------------------------------------------------------------------------
	-- BRANCH AREA
	------------------------------------------------------------------------------------------------------

		BranchStreet1					= ISNULL(ISNULL(LENDER_BRANCH.STREET_1, LENDER.Address), ''),		
		BranchPhone						= ISNULL(ISNULL(LENDER_BRANCH.Phone, LENDER.Phone), ''),
		BranchFax						= ISNULL(ISNULL(LENDER_BRANCH.Fax, LENDER.Fax), ''),
		BranchCity						= ISNULL(ISNULL(LENDER_BRANCH.City, LENDER.City), ''),
		BranchState						= ISNULL(ISNULL(LENDER_BRANCH.State, LENDER.State), ''),
		BranchZip						= ISNULL(ISNULL(LENDER_BRANCH.Zip, LENDER.Zip), ''),

		BranchFaxOnly = ISNULL(LENDER_BRANCH.FAX_ONLY, 0),



		LenderDealerID			= AUTO_LOAN_APP.LenderID,
		Fax_Status				= ISNULL(Fax.Status, ''),
		Fax_LastUpdate			= FAX.UpdateDateTime,

		DealerCity						= ISNULL(DEALER.City, ''),
		DealerState						= ISNULL(DEALER.State, ''),

		Counter,
		RESUBMIT_POLICY,
		PartnerName						= ISNULL(PARTNER.ShortName, ''),
		PARTNER.PartnerToolID,
		BidFundingStatus,
		StatusUpdateDateTime,
		LenderAgentName					= ISNULL(ll.FullName, ''),
		BranchAgentName					= ISNULL(lbl.FullName, ''),
		DealerSalesPerson				= ISNULL(dl.FullName, '')


FROM
  tblLoanApps AUTO_LOAN_APP WITH (NOLOCK)
    INNER JOIN				tblLoanApp_Bids				BID						WITH (NOLOCK)			ON	AUTO_LOAN_APP.LoanAppID			= BID.LoanAppID
    INNER JOIN				viewLenderBranches			LENDER_BRANCH			WITH (NOLOCK)			ON	BID.LendersBranchID				= LENDER_BRANCH.LendersBranchID
    INNER JOIN				tblLenders					LENDER					WITH (NOLOCK)			ON	LENDER_BRANCH.LenderID			= LENDER.LenderID

	LEFT OUTER JOIN 		viewLoanPartner				PARTNER					WITH (NOLOCK) 			ON	AUTO_LOAN_APP.LoanAppID			= PARTNER.LoanAppID
    LEFT OUTER JOIN			tblLoanApp_Bids_Fax			FAX						WITH (NOLOCK)			ON	BID.LoanApp_BidID				= FAX.LoanApp_BidID
    LEFT OUTER JOIN			tblDealers					DEALER					WITH (NOLOCK)			ON	AUTO_LOAN_APP.DealerID			= DEALER.DealerID
    LEFT OUTER JOIN			tblLoanApp_Worksheet		WS						WITH (NOLOCK)			ON	BID.LoanApp_BidID				= WS.LoanApp_BidID AND WS.ACTIVE=1

	LEFT OUTER JOIN		tblLoanApp_BidFundingStatus			FUNDING_STATUS		WITH (NOLOCK) ON BID.LoanApp_BidID			= FUNDING_STATUS.LoanApp_BidID



--    LEFT OUTER JOIN tblPartnerDataElement		e		  WITH (NOLOCK) ON AUTO_LOAN_APP.LoanAppID = e.LoanAppID
--	LEFT OUTER JOIN tblPartnerTools				t	      WITH (NOLOCK) ON t.PartnerToolID = e.PartnerToolID
	LEFT OUTER JOIN tblLenderDealerRelation		r	      WITH (NOLOCK) ON r.DealerID = DEALER.DealerID AND LENDER_BRANCH.LenderID = r.LenderID
	LEFT OUTER JOIN tblLendersLogins		    ll		  WITH (NOLOCK) ON ll.LendersLoginID = r.LenderAgentID
	LEFT OUTER JOIN tblLendersBranchLogins		lbl		  WITH (NOLOCK) ON lbl.LendersBranchLoginID = r.LenderBranchAgentID
	LEFT OUTER JOIN tblLoanAppAssignedDealers	ad		  WITH (NOLOCK) ON ad.LoanAppID = AUTO_LOAN_APP.LoanAppID
    LEFT OUTER JOIN tblDealersLogins			dl		  WITH (NOLOCK) ON dl.DealersLoginID = ad.DealersLoginID

WHERE

DATEDIFF(day, Bid.UpdateDateTime, GetDate()) <= 20
AND ISNULL(AUTO_LOAN_APP.ARCHIVED, 0) = 0

AND  (	BID.STATUS			IN('ACCEPTED','REFERRED', 'PENDING_DEALER', 'DECLINE_LENDER', 'PENDING_LENDER', 'PENDING_AUTOMATION', 'PROCESSING_AUTOMATION', 'B2B_ERROR', 'PENDING_B2B', 'DUPLICATE')
	OR	MESSAGING_STATUS	IN ('COMMENT_FOR_DEALER')
	OR	BidFundingStatus	IN ('REJECTED'))
--AND BID.LoanAppID = 883210


--ORDER BY BID.UpdateDateTime DESC, AUTO_LOAN_APP.UpdateDateTime DESC





GO

