/****** Object:  View dbo.viewInterfaceLenderNewDeals_Backup_20151023    Script Date: 7/31/2024 12:57:21 PM ******/

CREATE VIEW viewInterfaceLenderNewDeals_Backup_20151023 AS
	SELECT
		LoanAppID		= BID.LoanAppID,
		LoanApp_BidID	= BID.LoanApp_BidID,
		DealerID		= DEALER.DealerID,
		Applicant_Names	= DBO.ProperCase(AUTO_LOAN_APP.APPLICANT_NAMES),
		YIELD_TYPE		= BID.YIELD_TYPE,
		COMMENTS		= '',

	TERM = CASE
		WHEN TERM IS NULL				THEN NULL
		WHEN ISNUMERIC(TERM) = 1		THEN TERM
		WHEN TERM = ''					THEN NULL
		WHEN CHARINDEX('M', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('M', TERM) - 1))
		WHEN CHARINDEX('/', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('/', TERM) - 1))
		WHEN CHARINDEX(' ', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX(' ', TERM) - 1))
		ELSE -1
	END,
		PAYMENT,
		MESSAGING_STATUS,
		REBATE_PERCT,
		ADVANCE,
		LENDER.LenderID,
		BidAge			= DATEDIFF(day, Bid.UpdateDateTime, GetDate()),
		LENDER_ARCHIVED	= ISNULL(BID.LENDER_ARCHIVED, 0),
		Canceled		= CONVERT(BIT, CASE WHEN Canceled_Date IS NULL THEN 0 ELSE 1 END),
		Canceled_Date,
		Funded = CONVERT(BIT, CASE WHEN FUNDED_DATE	IS NOT NULL THEN 1 ELSE ISNULL(Funded, 0) END),
		ShowInLenderNewDeals		= CONVERT(BIT, 1),
		ShowInLenderPendingFunding	= CONVERT(BIT, CASE
			WHEN StatusUpdateDateTime	IS	NULL						THEN 0
			WHEN BidFundingStatus		IS	NULL						THEN 0
			WHEN LEN(BidFundingStatus)	=	0							THEN 0
			WHEN DATEDIFF(day, StatusUpdateDateTime, getdate()) > 45	THEN 0
			WHEN BidFundingStatus = 'RECEIVED'							THEN 1
			WHEN DATEDIFF(day, StatusUpdateDateTime, getdate()) > 30	THEN 0
			WHEN BidFundingStatus = 'REJECTED'							THEN 1
		END),

		ShowInLenderMessaging = CONVERT(BIT, CASE
			WHEN NOT Canceled_Date								IS	NULL					THEN 0
			WHEN BID.LENDER_ARCHIVED							=		1					THEN 0
			WHEN DATEDIFF(day, Bid.UpdateDateTime, GetDate())	>	14						THEN 0
			WHEN Messaging_Status								=	'COMMENT_FOR_LENDER'	THEN 1
			ELSE 0
		END),

		ShowInDealerNewDeals		= CONVERT(BIT, 0),
		ShowInDealerMessaging		= CONVERT(BIT, 0),
		ShowInDealerFunding			= CONVERT(BIT, 0),

		ANTICIPATED_RATE			= ISNULL(WS.ANTICIPATED_RATE,		AUTO_LOAN_APP.ANTICIPATED_RATE),
		LOAN_DOWN_PAYMENT			= ISNULL(WS.LOAN_DOWN_PAYMENT,		AUTO_LOAN_APP.LOAN_DOWN_PAYMENT),
		LOAN_ESTIMATED_PAYMENT		= ISNULL(WS.LOAN_ESTIMATED_PAYMENT, AUTO_LOAN_APP.LOAN_ESTIMATED_PAYMENT),
		LOAN_LICENSE				= ISNULL(WS.LOAN_LICENSE,			AUTO_LOAN_APP.LOAN_LICENSE),
		LOAN_MISC					= ISNULL(WS.LOAN_MISC,				AUTO_LOAN_APP.LOAN_MISC),
		LOAN_PURCHASE_PRICE			= ISNULL(WS.LOAN_PURCHASE_PRICE,	AUTO_LOAN_APP.LOAN_PURCHASE_PRICE),
		LOAN_TAX					= ISNULL(WS.LOAN_TAX,				AUTO_LOAN_APP.LOAN_TAX),
		LOAN_TERM_REQUESTED			= ISNULL(WS.LOAN_TERM_REQUESTED,	AUTO_LOAN_APP.LOAN_TERM_REQUESTED),
		LOAN_TOTAL_LOAN_AMOUNT		= ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT),
		LOAN_WARRANTY				= ISNULL(WS.LOAN_WARRANTY,			AUTO_LOAN_APP.LOAN_WARRANTY),
		VEHICLE_DESCRIPTION			= ISNULL(WS.VEHICLE_DESCRIPTION,	AUTO_LOAN_APP.VEHICLE_DESCRIPTION),
		VEHICLE_MAKE				= DBO.ProperCase(ISNULL(WS.VEHICLE_MAKE,			AUTO_LOAN_APP.VEHICLE_MAKE)),
		VEHICLE_MILEAGE				= ISNULL(WS.VEHICLE_MILEAGE,		AUTO_LOAN_APP.VEHICLE_MILEAGE),	
		VEHICLE_MODEL				= DBO.ProperCase(ISNULL(WS.VEHICLE_MODEL,			AUTO_LOAN_APP.VEHICLE_MODEL)),
		VEHICLE_VIN					= ISNULL(WS.VEHICLE_VIN,			AUTO_LOAN_APP.VEHICLE_VIN),
		VEHICLE_YEAR				= ISNULL(WS.VEHICLE_YEAR,			AUTO_LOAN_APP.VEHICLE_YEAR),
		VEHICLE						= ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), AUTO_LOAN_APP.VEHICLE_YEAR) + ' ' + AUTO_LOAN_APP.VEHICLE_MAKE + ' ' + AUTO_LOAN_APP.VEHICLE_MODEL),
		FUNDED_DATE,
		FINANCING_AMOUNT,
		WorkSheetID					= WS.LoanApp_WorksheetID,
		NEW_USED					= ISNULL(NULLIF(ISNULL(WS.NEW_USED, AUTO_LOAN_APP.NEW_USED), ''), 'USED'),
		BID.STATUS,
		ARCHIVED					= ISNULL(AUTO_LOAN_APP.ARCHIVED, 0),
		Dealer						= DBO.ProperCase(DEALER.DealerName + ' (' + DEALER.City) + ', ' + UPPER(DEALER.State) + ')',
		DealerEMail					= DEALER.EMail,
		AUTO_LOAN_APP.UpdateUser,
		AUTO_LOAN_APP.CreateUser,
		AUTO_LOAN_APP.UpdateDateTime,
		AUTO_LOAN_APP.CreateDateTime,
		RATE,
		LENDER_BRANCH.LendersBranchID,

		Lender            = DBO.ProperCase(CASE
			WHEN	LENDER.LenderName	= LENDER_BRANCH.BranchName	THEN LENDER.LenderName
			WHEN	LENDER.LenderName	= 'Matadors Community Credit Union'		AND	LENDER_BRANCH.BranchName LIKE 'Matadors Credit Union %'	THEN LENDER.LenderName + ' - ' + SUBSTRING(LENDER_BRANCH.BranchName, 23, 100)
			ELSE	LENDER.LenderName + ' - ' + LENDER_BRANCH.BranchName
			END) + ' (' + DBO.ProperCase(LENDER_BRANCH.CITY) + ', ' + UPPER(LENDER_BRANCH.State) + ')',
	
		LenderName        = DBO.ProperCase(ISNULL(LENDER.LenderName, '')),

		BidCreateDateTime				= BID.CreateDateTime,
		BidUpdateDateTime				= Bid.UpdateDateTime,
		BidSubmitDateTime				= BID.Submit_Date,
		LenderCity						= DBO.ProperCase(ISNULL(LENDER.City, '')),
		LenderState						= UPPER(ISNULL(LENDER.State, '')),

		DealerName						= DBO.ProperCase(DEALER.DealerName),

		Stips,
		Reason,

		-- DEALER CREDIT
		DEALER_CREDIT_EX				= ISNULL(AUTO_LOAN_APP.DEALER_CREDIT_EX, ''),
		DEALER_CREDIT_EQ				= ISNULL(AUTO_LOAN_APP.DEALER_CREDIT_EQ, ''),
		DEALER_CREDIT_TU				= ISNULL(AUTO_LOAN_APP.DEALER_CREDIT_TU, ''),
		
		-- LENDER CREDIT
		LENDER_CREDIT_EQ				= ISNULL(BID.LENDER_CREDIT_EQ, ISNULL(AUTO_LOAN_APP.LENDER_CREDIT_EQ, '')),
		LENDER_CREDIT_TU				= ISNULL(BID.LENDER_CREDIT_TU, ISNULL(AUTO_LOAN_APP.LENDER_CREDIT_TU, '')),
		LENDER_CREDIT_EX				= ISNULL(BID.LENDER_CREDIT_EX, ISNULL(AUTO_LOAN_APP.LENDER_CREDIT_EX, '')),
		Reasons,
		DISCOUNT_FEE,
		AUTOMATED,

		OFFER_DATE,

		OFFERED_BY,
		ACCEPT_DATE,
		SUBMIT_DATE,
		SUBMIT_BY,
		PRIMARY_SCORE,
		SECONDARY_SCORE,
		ACCEPT_BY,
		PTI,
		DTI,
		REMINDER_DATE					= BID.REMINDER_DATE,

	------------------------------------------------------------------------------------------------------
	-- BRANCH AREA
	------------------------------------------------------------------------------------------------------

		BranchStreet1					= ISNULL(ISNULL(LENDER_BRANCH.STREET_1, LENDER.Address), ''),		
		BranchPhone						= ISNULL(ISNULL(LENDER_BRANCH.Phone, LENDER.Phone), ''),
		BranchFax						= ISNULL(ISNULL(LENDER_BRANCH.Fax, LENDER.Fax), ''),
		BranchCity						= ISNULL(ISNULL(LENDER_BRANCH.City, LENDER.City), ''),
		BranchState						= ISNULL(ISNULL(LENDER_BRANCH.State, LENDER.State), ''),
		BranchZip						= ISNULL(ISNULL(LENDER_BRANCH.Zip, LENDER.Zip), ''),

		BranchFaxOnly = ISNULL(LENDER_BRANCH.FAX_ONLY, 0),

		LenderDealerID					= AUTO_LOAN_APP.LenderID,
		Fax_Status						= ISNULL(Fax.Status, ''),
		Fax_LastUpdate					= FAX.UpdateDateTime,

		DealerCity						= ISNULL(DEALER.City, ''),
		DealerState						= ISNULL(DEALER.State, ''),

		Counter,
		RESUBMIT_POLICY,
		PartnerName						= DBO.FormatPartnerName(ISNULL(PARTNER.ShortName, '')),
		PARTNER.PartnerToolID,
		BidFundingStatus,
		StatusUpdateDateTime,
		LenderAgentName					= ISNULL(LENDER_LOGIN.FullName, ''),
		BranchAgentName					= ISNULL(BRANCH_LOGIN.FullName, ''),
		DealerSalesPerson				= ISNULL(DEALER_LOGIN.FullName, '')

	FROM
						tblLoanApps						AUTO_LOAN_APP			WITH (NOLOCK)
				JOIN	tblLoanApp_Bids					BID						WITH (NOLOCK) ON AUTO_LOAN_APP.LoanAppID				= BID.LoanAppID
--				JOIN	viewLenderBranches				LENDER_BRANCH			WITH (NOLOCK) ON BID.LendersBranchID					= LENDER_BRANCH.LendersBranchID
				JOIN	tblLendersBranches				LENDER_BRANCH			WITH (NOLOCK) ON BID.LendersBranchID					= LENDER_BRANCH.LendersBranchID
				JOIN	tblLenders						LENDER					WITH (NOLOCK) ON LENDER_BRANCH.LenderID					= LENDER.LenderID
		LEFT	JOIN	viewLoanPartner					PARTNER					WITH (NOLOCK) ON AUTO_LOAN_APP.LoanAppID				= PARTNER.LoanAppID
		LEFT	JOIN	tblLoanApp_Bids_Fax				FAX						WITH (NOLOCK) ON BID.LoanApp_BidID						= FAX.LoanApp_BidID
		LEFT	JOIN	tblDealers						DEALER					WITH (NOLOCK) ON AUTO_LOAN_APP.DealerID					= DEALER.DealerID
		LEFT	JOIN	tblLoanApp_Worksheet			WS						WITH (NOLOCK) ON BID.LoanApp_BidID						= WS.LoanApp_BidID  AND ISNULL(WS.ACTIVE, 0) = 1 
--AND WS.LoanApp_WorksheetID IN (SELECT MAX(LoanApp_WorksheetID) FROM tblLoanApp_Worksheet WS2 WITH (NOLOCK) WHERE WS2.LoanApp_BidID = BID.LoanApp_BidID AND ISNULL(WS2.Active, 0) = 1)
		LEFT	JOIN	tblLoanApp_BidFundingStatus		FUNDING_STATUS			WITH (NOLOCK) ON BID.LoanApp_BidID						= FUNDING_STATUS.LoanApp_BidID
		LEFT	JOIN	tblLenderDealerRelation			RELATION				WITH (NOLOCK) ON RELATION.DealerID						= DEALER.DealerID AND LENDER_BRANCH.LenderID = RELATION.LenderID
		LEFT	JOIN	tblLendersLogins				LENDER_LOGIN			WITH (NOLOCK) ON LENDER_LOGIN.LendersLoginID			= RELATION.LenderAgentID
		LEFT	JOIN	tblLendersBranchLogins			BRANCH_LOGIN			WITH (NOLOCK) ON BRANCH_LOGIN.LendersBranchLoginID 		= RELATION.LenderBranchAgentID
		LEFT	JOIN	tblLoanAppAssignedDealers		ASSIGNED_DEALER			WITH (NOLOCK) ON ASSIGNED_DEALER.LoanAppID				= AUTO_LOAN_APP.LoanAppID
		LEFT	JOIN	tblDealersLogins				DEALER_LOGIN			WITH (NOLOCK) ON DEALER_LOGIN.DealersLoginID			= ASSIGNED_DEALER.DealersLoginID

WHERE
		DATEDIFF(day, Bid.UpdateDateTime, GetDate()) <= 30
	AND Canceled_Date IS NULL
	AND ISNULL(BID.LENDER_ARCHIVED, 0) = 0
	AND BID.STATUS IN ('PENDING_LENDER', 'REFERRED', 'PENDING_B2B')
	AND ISNULL(BidFundingStatus, '') NOT IN ('RECEIVED', 'REJECTED')
	--AND (WS.LoanApp_WorksheetID IS NULL OR WS.LoanApp_WorksheetID IN (SELECT MAX(LoanApp_WorksheetID) FROM tblLoanApp_Worksheet WS2 WITH (NOLOCK) WHERE WS2.LoanApp_BidID = BID.LoanApp_BidID AND ISNULL(WS2.Active, 0) = 1))
	--AND LENDER.LenderID = 366







