/****** Object:  View dbo.viewLendersBranchContactInfo    Script Date: 7/31/2024 12:57:22 PM ******/


CREATE VIEW viewLendersBranchContactInfo AS
SELECT TOP 100 PERCENT
    LenderID = LENDER.LenderID,
    LendersBranchID = BRANCH.LendersBranchID,
    LenderLoginPrefix = LENDER.LoginPrefix,
    BranchLoginPrefix = CASE
        WHEN LEN(ISNULL(BRANCH.LoginPrefix, '')) > 0 THEN BRANCH.LoginPrefix
        ELSE LENDER.LoginPrefix
        END,

    LenderName = UPPER(LENDER.LenderName),
    BranchName = UPPER(BRANCH.BranchName),
    BranchDisplayName = CASE
        WHEN LEN(ISNULL(BRANCH.BranchName, '')) = 0 THEN UPPER(LENDER.LenderName)
        WHEN LEN(ISNULL(LENDER.LenderName, '')) = 0 THEN UPPER(BRANCH.BranchName)
        WHEN UPPER(ISNULL(BRANCH.BranchName, '')) = UPPER(ISNULL(LENDER.LenderName, '')) THEN UPPER(LENDER.LenderName)
        WHEN LEFT(UPPER(ISNULL(BRANCH.BranchName, '')), LEN(ISNULL(LENDER.LenderName, ''))) = UPPER(ISNULL(LENDER.LenderName, '')) THEN UPPER(BRANCH.BranchName)
        ELSE UPPER(LENDER.LenderName + ' - ' + BRANCH.BranchName)
    END,

    Phone = CASE
        WHEN LEN(ISNULL(BRANCH.Phone, '')) > 0 THEN dbo.scrubPhoneNumber(BRANCH.PHONE)
        ELSE dbo.scrubPhoneNumber(LENDER.PHONE)
    END,

    Fax = CASE
        WHEN LEN(ISNULL(BRANCH.Fax, '')) > 0 THEN dbo.scrubPhoneNumber(BRANCH.Fax)
        ELSE dbo.scrubPhoneNumber(LENDER.Fax)
    END
FROM
    tblLenders LENDER
        JOIN tblLendersBranches BRANCH ON (LENDER.LenderID = BRANCH.LenderID)
ORDER BY
    LenderID,
    LendersBranchID






