/****** Object:  View dbo.viewLendersProgramStatus_Inner    Script Date: 7/31/2024 12:57:22 PM ******/
CREATE VIEW viewLendersProgramStatus_Inner AS
	SELECT
		[LenderID]					= [Lender].[LenderID],
		[Lender]					= LEFT(UPPER([Lender].[LenderName]), 60),
		[LenderStatus]				= [Lender].[LenderStatus],
		[Programs]					= (SELECT COUNT(*) FROM [tblPrograms] [P] WITH (NOLOCK) WHERE [P].[LenderID] = [Lender].[LenderID] AND [P].[Active] = 1),
		[UnderwritingPrograms]		= (SELECT COUNT(*) FROM [tblPrograms] [P] WITH (NOLOCK) WHERE [P].[LenderID] = [Lender].[LenderID] AND [P].[Active] = 1 AND [P].[Underwriting] = 1),
		[AutoOfferPrograms]			= (SELECT COUNT(*) FROM [tblPrograms] [P] WITH (NOLOCK) WHERE [P].[LenderID] = [Lender].[LenderID] AND [P].[Active] = 1 AND [P].[Automated] = 1 AND ISNULL([P].[AutoDecline], 0) = 0),
		[AutoDeclinePrograms]		= (SELECT COUNT(*) FROM [tblPrograms] [P] WITH (NOLOCK) WHERE [P].[LenderID] = [Lender].[LenderID] AND [P].[Active] = 1 AND ISNULL([P].[AutoDecline], 0) = 1)
	FROM
							[tblLenders]		[Lender]									WITH (NOLOCK)


