/****** Object:  View dbo.viewLendersUserInformation    Script Date: 7/31/2024 12:57:22 PM ******/



CREATE VIEW [dbo].[viewLendersUserInformation] AS
SELECT TOP 100 PERCENT
    LenderID = LENDER.LenderID,
    LendersBranchID = NULL,
    LenderLoginPrefix = LENDER.LoginPrefix,
    BranchLoginPrefix = NULL,
    LoginName = LENDER_LOGIN.UserName + '@' + LENDER.LoginPrefix,
    DisplayName = CASE
        WHEN LEN(ISNULL(LENDER_LOGIN.FullName, '')) > 0 THEN UPPER(LENDER_LOGIN.FullName)
        ELSE UPPER(LENDER_LOGIN.UserName)
        END,
    LenderName = UPPER(LENDER.LenderName),
    BranchName = '(Corporate)',
    --Phone = dbo.scrubPhoneNumber(LENDER.PHONE),
	--Fax =  dbo.scrubPhoneNumber(LENDER.FAX)

    Phone = CASE
        WHEN LEN(ISNULL(LENDER_LOGIN.OfficePhone, '')) > 0 THEN dbo.scrubPhoneNumber(LENDER_LOGIN.OfficePhone)
        ELSE dbo.scrubPhoneNumber(LENDER.PHONE)
    END,

    Fax =  dbo.scrubPhoneNumber(LENDER.FAX)
FROM
    tblLenders LENDER
        JOIN tblLendersLogins LENDER_LOGIN ON (LENDER.LenderID = LENDER_LOGIN.LenderID)

UNION

SELECT TOP 100 PERCENT
    LenderID = LENDER.LenderID,
    LendersBranchID = BRANCH.LendersBranchID,
    LenderLoginPrefix = LENDER.LoginPrefix,
    BranchLoginPrefix = CASE
        WHEN LEN(ISNULL(BRANCH.LoginPrefix, '')) > 0 THEN BRANCH.LoginPrefix
        ELSE LENDER.LoginPrefix
        END,

    LoginName = CASE
        WHEN LEN(ISNULL(BRANCH.LoginPrefix, '')) > 0 THEN BRANCH_LOGIN.UserName + '@' + BRANCH.LoginPrefix
        ELSE BRANCH_LOGIN.UserName + '@' + LENDER.LoginPrefix
        END,

    DisplayName = CASE
        WHEN LEN(ISNULL(BRANCH_LOGIN.FullName, '')) > 0 THEN UPPER(BRANCH_LOGIN.FullName)
        ELSE UPPER(BRANCH_LOGIN.UserName)
        END,
    LenderName = UPPER(LENDER.LenderName),
    BranchName = UPPER(BRANCH.BranchName),

--    Phone = CASE
--        WHEN LEN(ISNULL(BRANCH.Phone, '')) > 0 THEN dbo.scrubPhoneNumber(BRANCH.PHONE)
--        ELSE dbo.scrubPhoneNumber(LENDER.PHONE)
--    END,
    Phone = CASE
        WHEN LEN(ISNULL(BRANCH_LOGIN.OfficePhone, '')) > 0 THEN dbo.scrubPhoneNumber(BRANCH_LOGIN.OfficePhone)
		WHEN LEN(ISNULL(BRANCH.PHONE, '')) > 0 THEN dbo.scrubPhoneNumber(BRANCH.PHONE)
        ELSE dbo.scrubPhoneNumber(LENDER.PHONE)
    END,

    Fax = CASE
        WHEN LEN(ISNULL(BRANCH.Fax, '')) > 0 THEN dbo.scrubPhoneNumber(BRANCH.Fax)
        ELSE dbo.scrubPhoneNumber(LENDER.Fax)
    END
FROM
    tblLenders LENDER
        JOIN tblLendersBranches BRANCH ON (LENDER.LenderID = BRANCH.LenderID)
        JOIN tblLendersBranchLogins BRANCH_LOGIN ON (Branch.LendersBranchID = BRANCH_LOGIN.LendersBranchID)

UNION

SELECT TOP 100 PERCENT
    LenderID = NULL,
    LendersBranchID = NULL,
    LenderLoginPrefix = 'CSMARTS_INTERNAL',
    BranchLoginPrefix = 'CSMARTS_INTERNAL',
    LoginName = UserName + '@CSMARTS_INTERNAL',
    DisplayName = CASE
        WHEN LEN(ISNULL(FullName, '')) > 0 THEN UPPER(FullName)
        ELSE UPPER(UserName)
        END,
    LenderName = 'CreditSmarts Internal',
    BranchName = 'CreditSmarts Internal',
    Phone = NULL,
    Fax = NULL
FROM
    tblAdminLogins

ORDER BY
    LenderID,
    LendersBranchID,
    LoginName






