/****** Object:  View dbo.viewLoanApp_ActiveWorksheet    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewLoanApp_ActiveWorksheet AS
--DECLARE @_BID_ID INT, @_APP_ID INT; SET @_BID_ID = 746288; --SET @_BID_ID = 659730;
	SELECT --TOP 1
		LoanAppID						= [Bid].[LoanAppID],
		LoanApp_BidID					= [Bid].[LoanApp_BidID],
		LoanApp_WorksheetID				= [Worksheet].[LoanApp_WorksheetID],

		Source						= CASE
			WHEN [Worksheet].[LoanApp_BidID]		IS NULL			THEN 'APPLICATION'
			WHEN [Worksheet].[LoanApp_BidID]		IS NOT NULL		THEN 'WORKSHEET'
			ELSE 'UNKNOWN' END,

		Vehicle						= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL(CONVERT(CHAR(4), [Application].VEHICLE_YEAR),	'')	+ ' '	+ ISNULL([Application].VEHICLE_MAKE, '')	+ ' ' + ISNULL([Application].VEHICLE_MODEL,	'')	+ CASE WHEN ISNULL([Application].Vehicle_Mileage,	0) = 0 THEN '' ELSE ' ' + CreditSmarts.DBO.FormatIntegerEx(Application.Vehicle_Mileage, 'Zero')	+ ' Miles'		END
											ELSE													ISNULL(CONVERT(CHAR(4), [Worksheet].VEHICLE_YEAR), '')		+ ' '	+ ISNULL([Worksheet].VEHICLE_MAKE, '')		+ ' ' + ISNULL([Worksheet].VEHICLE_MODEL, 	'')	+ CASE WHEN ISNULL([Worksheet].Vehicle_Mileage,		0) = 0 THEN '' ELSE ' ' + CreditSmarts.DBO.FormatIntegerEx(Worksheet.Vehicle_Mileage, 'Zero')	+ ' Miles'	END
		END,

		ANTICIPATED_RATE			= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[ANTICIPATED_RATE],			''	)	ELSE ISNULL( [Worksheet].[ANTICIPATED_RATE],			''	)	END,
		BOOK_SOURCE					= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[BOOK_SOURCE],				''	)	ELSE ISNULL( [Worksheet].[BOOK_SOURCE],					''	)	END,
		LOAN_DEPOSIT				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN			[Application].[LOAN_DEPOSIT]						ELSE 		 [Worksheet].[LOAN_DEPOSIT]							END,
		LOAN_DOC_FEE				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN			[Application].[LOAN_DOC_FEE]						ELSE 		 [Worksheet].[LOAN_DOC_FEE]							END,
		LOAN_DOC_FEE_TAXABLE		= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[LOAN_DOC_FEE_TAXABLE],		0	)	ELSE ISNULL( [Worksheet].[LOAN_DOC_FEE_TAXABLE],		0 	)	END,
		LOAN_DOCSMOG_TAXABLE		= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[LOAN_DOCSMOG_TAXABLE],		0	)	ELSE ISNULL( [Worksheet].[LOAN_DOCSMOG_TAXABLE],		0	)	END,
