		LOAN_TRADE_IN_PAYMENT		= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[LOAN_TRADE_IN_PAYMENT],		0	)	ELSE ISNULL( [Worksheet].[LOAN_TRADE_IN_PAYMENT],		0	)	END,
		LOAN_UP_FRONT_PAYMENTS		= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[LOAN_UP_FRONT_PAYMENTS],		0	)	ELSE ISNULL( [Worksheet].[LOAN_UP_FRONT_PAYMENTS],		0	)	END,
		LOAN_WARRANTY				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	NULLIF( [Application].[LOAN_WARRANTY],				0	)	ELSE NULLIF( [Worksheet].[LOAN_WARRANTY],				0	)	END,
