		PREFERRED_PAYMENT			= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[PREFERRED_PAYMENT],			0	)	ELSE ISNULL( [Worksheet].[PREFERRED_PAYMENT],			0	)	END,
		PURCHASE_TYPE				= CASE  WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[PURCHASE_TYPE],				''	)	ELSE ISNULL( [Worksheet].[PURCHASE_TYPE],				''	)	END,
		SMOG_CERTIFY_FEE			= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN			[Application].[SMOG_CERTIFY_FEE]					ELSE 		 [Worksheet].[SMOG_CERTIFY_FEE]						END,
		SMOG_CERTIFY_FEE_TAXABLE	= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[SMOG_CERTIFY_FEE_TAXABLE],	0	)	ELSE ISNULL( [Worksheet].[SMOG_CERTIFY_FEE_TAXABLE],	0	)	END,
		SMOG_SELLER_FEE				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN			[Application].[SMOG_SELLER_FEE]						ELSE 		 [Worksheet].[SMOG_SELLER_FEE]						END,
		SMOG_SELLER_FEE_TAXABLE		= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[SMOG_SELLER_FEE_TAXABLE],	0	)	ELSE ISNULL( [Worksheet].[SMOG_SELLER_FEE_TAXABLE],		0	)	END,
		VEHICLE_DESCRIPTION			= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_DESCRIPTION],		''	)	ELSE ISNULL( [Worksheet].[VEHICLE_DESCRIPTION],			''	)	END,
		VEHICLE_MAKE				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_MAKE],				''	)	ELSE ISNULL( [Worksheet].[VEHICLE_MAKE],				''	)	END,
		VEHICLE_MILEAGE				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_MILEAGE],			0	)	ELSE ISNULL( [Worksheet].[VEHICLE_MILEAGE],				0	)	END,
		VEHICLE_MODEL				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_MODEL],				''	)	ELSE ISNULL( [Worksheet].[VEHICLE_MODEL],				''	)	END,
		VEHICLE_RETAIL				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_RETAIL],				0	)	ELSE ISNULL( [Worksheet].[VEHICLE_RETAIL],				0	)	END,
		VEHICLE_RETAIL_ADJUSTED		= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_RETAIL_ADJUSTED],	0	)	ELSE ISNULL( [Worksheet].[VEHICLE_RETAIL_ADJUSTED],		0	)	END,
		VEHICLE_TYPE				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_TYPE],				''	)	ELSE ISNULL( [Worksheet].[VEHICLE_TYPE],				''	)	END,
		VEHICLE_VIN					= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_VIN],				''	)	ELSE ISNULL( [Worksheet].[VEHICLE_VIN],					''	)	END,
		VEHICLE_WHOLESALE			= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_WHOLESALE],			0	)	ELSE ISNULL( [Worksheet].[VEHICLE_WHOLESALE],			0	)	END,
		VEHICLE_WHOLESALE_ADJUSTED	= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_WHOLESALE_ADJUSTED], 0	)	ELSE ISNULL( [Worksheet].[VEHICLE_WHOLESALE_ADJUSTED],	0	)	END,
		VEHICLE_YEAR				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[VEHICLE_YEAR],				0	)	ELSE ISNULL( [Worksheet].[VEHICLE_YEAR],				0	)	END,
		WARRANTY_TERM				= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	NULLIF( [Application].[WARRANTY_TERM],				0	)	ELSE NULLIF( [Worksheet].[WARRANTY_TERM],				0	)	END,
		YIELD_TYPE					= CASE	WHEN [Worksheet].[LoanApp_BidID]		IS NULL	THEN	ISNULL( [Application].[YIELD_TYPE],					''	)	ELSE ISNULL( [Worksheet].[YIELD_TYPE],					''	)	END,

		CreateUser					= CASE	WHEN NULLIF([Worksheet].[CreateUser],		'')		IS NOT NULL		THEN	[Worksheet].[CreateUser]
											WHEN NULLIF([Worksheet].[UpdateUser],		'')		IS NOT NULL		THEN	[Worksheet].[UpdateUser]
											WHEN NULLIF([Application].[CreateUser],		'')		IS NOT NULL		THEN	[Application].[CreateUser]
											WHEN NULLIF([Application].[UpdateUser],		'') 	IS NOT NULL		THEN	[Application].[UpdateUser]
											WHEN NULLIF([Bid].[CreateUser],				'')		IS NOT NULL		THEN	[Bid].[CreateUser]
											WHEN NULLIF([Bid].[UpdateUser],				'') 	IS NOT NULL		THEN	[Bid].[UpdateUser]
											ELSE 'UNKNOWN'
										END,

		UpdateUser					= CASE  WHEN NULLIF([Worksheet].[UpdateUser],		'')		IS NOT NULL		THEN	[Worksheet].[UpdateUser]
											WHEN NULLIF([Worksheet].[CreateUser],		'')		IS NOT NULL		THEN	[Worksheet].[CreateUser]
											WHEN NULLIF([Application].[UpdateUser],		'') 	IS NOT NULL		THEN	[Application].[UpdateUser]
											WHEN NULLIF([Application].[CreateUser],		'')		IS NOT NULL		THEN	[Application].[CreateUser]
											WHEN NULLIF([Bid].[UpdateUser],				'') 	IS NOT NULL		THEN	[Bid].[UpdateUser]
											WHEN NULLIF([Bid].[CreateUser],				'')		IS NOT NULL		THEN	[Bid].[CreateUser]
											ELSE 'UNKNOWN'
										END,


		CreateDateTime				= CASE	WHEN [Worksheet].[CreateDateTime]					IS NOT NULL		THEN	[Worksheet].[CreateDateTime]
											WHEN [Worksheet].[UpdateDateTime]					IS NOT NULL		THEN	[Worksheet].[UpdateDateTime]
											WHEN [Application].[CreateDateTime]					IS NOT NULL		THEN	[Application].[CreateDateTime]
											WHEN [Application].[UpdateDateTime]		 			IS NOT NULL		THEN	[Application].[UpdateDateTime]
											WHEN [Bid].[CreateDateTime]							IS NOT NULL		THEN	[Bid].[CreateDateTime]
											WHEN [Bid].[UpdateDateTime]				 			IS NOT NULL		THEN	[Bid].[UpdateDateTime]
											ELSE 'UNKNOWN'
										END,

		UpdateDateTime				= CASE  WHEN [Worksheet].[UpdateDateTime]					IS NOT NULL		THEN	[Worksheet].[UpdateDateTime]
											WHEN [Worksheet].[CreateDateTime]					IS NOT NULL		THEN	[Worksheet].[CreateDateTime]
											WHEN [Application].[UpdateDateTime]		 			IS NOT NULL		THEN	[Application].[UpdateDateTime]
											WHEN [Application].[CreateDateTime]					IS NOT NULL		THEN	[Application].[CreateDateTime]
											WHEN [Bid].[UpdateDateTime]				 			IS NOT NULL		THEN	[Bid].[UpdateDateTime]
											WHEN [Bid].[CreateDateTime]							IS NOT NULL		THEN	[Bid].[CreateDateTime]
											ELSE 'UNKNOWN'
										END

	FROM
					tblLoanApps				Application		WITH (NOLOCK)
		INNER JOIN	tblLoanApp_Bids			Bid				WITH (NOLOCK)	ON Application.LoanAppID = Bid.LoanAppID
		INNER JOIN	viewOriginalBidID		OriginalBid		WITH (NOLOCK)	ON OriginalBid.LoanApp_BidID = Bid.LoanApp_BidID
--		LEFT  JOIN	tblLoanApp_Worksheet	Worksheet		WITH (NOLOCK)	ON Worksheet.LoanApp_BidID	= OriginalBid.OriginalBidID		AND		ISNULL(Worksheet.Active, 0) = 1
		LEFT  JOIN	tblLoanApp_Worksheet	Worksheet		WITH (NOLOCK)	ON Worksheet.LoanApp_BidID	= Bid.LoanApp_BidID		AND		ISNULL(Worksheet.Active, 0) = 1
--	WHERE		Bid.LoanApp_BidID = @_BID_ID







