/****** Object:  View dbo.viewLoanApp_ApplicantSocials    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewLoanApp_ApplicantSocials AS
	SELECT
		APP.LoanAppID,
		Applicant = 1,
		APPLICANT.LoanApp_ApplicantID,
		APPLICANT.Last_Name,
		APPLICANT.First_Name,
		APPLICANT.SSN_1,
		APPLICANT.SSN_2,
		APPLICANT.SSN_3
	FROM 
					viewLoanApp_ApplicantCountID	APP 		WITH (NOLOCK)	
		INNER JOIN	tblLoanApp_Applicant			APPLICANT	WITH (NOLOCK)	
			ON APPLICANT.LoanApp_ApplicantID = APP.ApplicantID_Primary
	WHERE
		APPLICANT.SSN_1 > 0 AND APPLICANT.SSN_2 > 0 AND APPLICANT.SSN_3 > 0

	UNION ALL

	SELECT
		APP.LoanAppID,
		Applicant = 2,
		APPLICANT.LoanApp_ApplicantID,
		APPLICANT.Last_Name,
		APPLICANT.First_Name,
		APPLICANT.SSN_1,
		APPLICANT.SSN_2,
		APPLICANT.SSN_3
	FROM 
					viewLoanApp_ApplicantCountID	APP 		WITH (NOLOCK)	
		INNER JOIN	tblLoanApp_Applicant			APPLICANT	WITH (NOLOCK)	
			ON APPLICANT.LoanApp_ApplicantID = APP.ApplicantID_Secondary
	WHERE
		APP.Applicants = 2 AND APPLICANT.SSN_1 > 0 AND APPLICANT.SSN_2 > 0 AND APPLICANT.SSN_3 > 0




