/****** Object:  View dbo.viewLoanApp_ApplicantsNameSocial    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewLoanApp_ApplicantsNameSocial AS
	SELECT
		LoanAppID				= APP.LoanAppID,
		Applicants				= APP.Applicants,
		Primary_ApplicantID		= APP.ApplicantID_Primary,
	
		Primary_Last	= CASE
			WHEN A1.LAST_NAME IS NULL		THEN NULL
			WHEN LEN(A1.LAST_NAME) = 0		THEN NULL
			WHEN LEN(A1.LAST_NAME) = 1		THEN UPPER(A1.LAST_NAME)
			ELSE UPPER(SUBSTRING(A1.LAST_NAME, 1, 1)) + LOWER(SUBSTRING(A1.LAST_NAME, 2, 99))
		END,
	
		Primary_First	= CASE
			WHEN A1.FIRST_NAME IS NULL		THEN NULL
			WHEN LEN(A1.FIRST_NAME) = 0		THEN NULL
			WHEN LEN(A1.FIRST_NAME) = 1		THEN UPPER(A1.FIRST_NAME)
			ELSE UPPER(SUBSTRING(A1.FIRST_NAME, 1, 1)) + LOWER(SUBSTRING(A1.FIRST_NAME, 2, 99))
		END,
	
		Primary_Name = CASE
			WHEN NULLIF(A1.FIRST_NAME, '') IS NULL AND NULLIF(A1.LAST_NAME, '') IS NULL		THEN NULL
			WHEN NULLIF(A1.FIRST_NAME, '') IS NULL THEN UPPER(SUBSTRING(A1.LAST_NAME, 1, 1)) + LOWER(SUBSTRING(A1.LAST_NAME, 2, 99))
			WHEN NULLIF(A1.LAST_NAME, '')  IS NULL THEN UPPER(SUBSTRING(A1.FIRST_NAME, 1, 1)) + LOWER(SUBSTRING(A1.FIRST_NAME, 2, 99))
			ELSE UPPER(SUBSTRING(A1.FIRST_NAME, 1, 1)) + LOWER(SUBSTRING(A1.FIRST_NAME, 2, 99)) + ' ' + UPPER(SUBSTRING(A1.LAST_NAME, 1, 1)) + LOWER(SUBSTRING(A1.LAST_NAME, 2, 99))
		END,
	
		Primary_SSN		= CASE
			WHEN A1.SSN_1		IS NULL THEN NULL
			WHEN A1.SSN_2		IS NULL THEN NULL
			WHEN A1.SSN_3 		IS NULL THEN NULL
			WHEN A1.SSN_1		= 0		THEN NULL
			WHEN A1.SSN_2		= 0		THEN NULL
			WHEN A1.SSN_3		= 0		THEN NULL
			ELSE
				RIGHT('000' + LTRIM(STR(A1.SSN_1)), 3) + '-' +
				RIGHT('000' + LTRIM(STR(A1.SSN_2)), 2) + '-' +
				RIGHT('0000' + LTRIM(STR(A1.SSN_3)), 4)
			END,
	
		Primary_SSN_1	= NULLIF(A1.SSN_1, 0),
		Primary_SSN_2	= NULLIF(A1.SSN_2, 0),
		Primary_SSN_3	= NULLIF(A1.SSN_3, 0),
	
		Secondary_ApplicantID	= CASE
			WHEN A2.LoanApp_ApplicantID = A1.LoanApp_ApplicantID	THEN NULL
			ELSE APP.ApplicantID_Secondary
		END,
	
		Secondary_Last	= CASE
			WHEN A2.LoanApp_ApplicantID = A1.LoanApp_ApplicantID	THEN NULL
			WHEN A2.LAST_NAME IS NULL		THEN NULL
			WHEN LEN(A2.LAST_NAME) = 0		THEN NULL
			WHEN LEN(A2.LAST_NAME) = 1		THEN UPPER(A2.LAST_NAME)
			ELSE UPPER(SUBSTRING(A2.LAST_NAME, 1, 1)) + LOWER(SUBSTRING(A2.LAST_NAME, 2, 99))
		END,
	
		Secondary_First	= CASE
			WHEN A2.LoanApp_ApplicantID = A1.LoanApp_ApplicantID	THEN NULL
			WHEN A2.FIRST_NAME IS NULL		THEN NULL
			WHEN LEN(A2.FIRST_NAME) = 0		THEN NULL
			WHEN LEN(A2.FIRST_NAME) = 1		THEN UPPER(A2.FIRST_NAME)
			ELSE UPPER(SUBSTRING(A2.FIRST_NAME, 1, 1)) + LOWER(SUBSTRING(A2.FIRST_NAME, 2, 99))
		END,
	
		Secondary_Name = CASE
			WHEN A2.LoanApp_ApplicantID = A1.LoanApp_ApplicantID	THEN NULL
			WHEN NULLIF(A2.FIRST_NAME, '') IS NULL AND NULLIF(A2.LAST_NAME, '') IS NULL		THEN NULL
			WHEN NULLIF(A2.FIRST_NAME, '') IS NULL THEN UPPER(SUBSTRING(A2.LAST_NAME, 1, 1)) + LOWER(SUBSTRING(A2.LAST_NAME, 2, 99))
			WHEN NULLIF(A2.LAST_NAME, '')  IS NULL THEN UPPER(SUBSTRING(A2.FIRST_NAME, 1, 1)) + LOWER(SUBSTRING(A2.FIRST_NAME, 2, 99))
			ELSE UPPER(SUBSTRING(A2.FIRST_NAME, 1, 1)) + LOWER(SUBSTRING(A2.FIRST_NAME, 2, 99)) + ' ' + UPPER(SUBSTRING(A2.LAST_NAME, 1, 1)) + LOWER(SUBSTRING(A2.LAST_NAME, 2, 99))
		END,
	
		Secondary_SSN		= CASE
			WHEN A2.LoanApp_ApplicantID = A1.LoanApp_ApplicantID	THEN NULL
			WHEN A2.SSN_1		IS NULL THEN NULL
			WHEN A2.SSN_2		IS NULL THEN NULL
			WHEN A2.SSN_3 		IS NULL THEN NULL
			WHEN A2.SSN_1		= 0		THEN NULL
			WHEN A2.SSN_2		= 0		THEN NULL
			WHEN A2.SSN_3		= 0		THEN NULL
			ELSE
				RIGHT('000' + LTRIM(STR(A2.SSN_1)), 3) + '-' +
				RIGHT('000' + LTRIM(STR(A2.SSN_2)), 2) + '-' +
				RIGHT('0000' + LTRIM(STR(A2.SSN_3)), 4)
			END,
	
		Secondary_SSN_1 = CASE
			WHEN A2.LoanApp_ApplicantID = A1.LoanApp_ApplicantID	THEN NULL
			WHEN A2.SSN_1 = 0										THEN NULL
			ELSE A2.SSN_1 END,
	
		Secondary_SSN_2 = CASE
			WHEN A2.LoanApp_ApplicantID = A1.LoanApp_ApplicantID	THEN NULL
			WHEN A2.SSN_2 = 0										THEN NULL
			ELSE A2.SSN_2 END,
	
		Secondary_SSN_3 = CASE
			WHEN A2.LoanApp_ApplicantID = A1.LoanApp_ApplicantID	THEN NULL
			WHEN A2.SSN_3 = 0										THEN NULL
			ELSE A2.SSN_3 END	
	FROM
					viewLoanApp_ApplicantCountID	APP WITH (NOLOCK)
		INNER JOIN	tblLoanApp_Applicant			A1	WITH (NOLOCK) ON A1.LoanApp_ApplicantID = APP.ApplicantID_Primary
		INNER JOIN	tblLoanApp_Applicant			A2	WITH (NOLOCK) ON A2.LoanApp_ApplicantID = APP.ApplicantID_Secondary
	--ORDER BY APP.LoanAppID DESC




