/****** Object:  View dbo.viewLoanApp_Redirect    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewLoanApp_Redirect AS
SELECT TOP 100 PERCENT
		LoanApp_RedirectID			= Redirect.LoanApp_RedirectID,
		Active						= ISNULL(Redirect.Active, 0),
		StartDate					= Redirect.StartDate,
		EndDate						= Redirect.EndDate,
		Name						= ISNULL(Redirect.Name, ''),
		Description					= ISNULL(Redirect.Description, ''),
		Notes						= Redirect.Notes,
		CreateDateTime				= ISNULL(ISNULL(Redirect.CreateDateTime, Redirect.UpdateDateTime), GETDATE()),
		UpdateDateTime				= ISNULL(ISNULL(Redirect.UpdateDateTime, Redirect.CreateDateTime), GETDATE()),
		CreateUser					= ISNULL(ISNULL(Redirect.CreateUser, Redirect.UpdateUser), ''),
		UpdateUser					= ISNULL(ISNULL(Redirect.UpdateUser, Redirect.CreateUser), ''),
		rowVersion					= ISNULL(NULLIF(Redirect.rowVersion, 0), 1),

		SourceLenderID				= Redirect.SourceLenderID,
		SourceLender				= CASE	WHEN Redirect.SourceLenderID IS NULL THEN ''
											ELSE ISNULL(DBO.ProperCase(Lender_From.LenderName), '') END,

		SourceLenderLocation		= CASE	WHEN Redirect.SourceLenderID IS NULL THEN ''			
											ELSE ISNULL(DBO.ProperCase(Lender_From.City) + ', ' + UPPER(Lender_From.State), '') END,

		SourceLendersBranchID				= Redirect.SourceLendersBranchID,

		SourceBranch			= CASE	WHEN Redirect.SourceLendersBranchID IS NULL THEN ''
											WHEN LTRIM(RTRIM(BranchLender_From.LenderName))								= LTRIM(RTRIM(Branch_From.BranchName))	THEN DBO.ProperCase(Branch_From.BranchName)
											WHEN LEFT(Branch_From.BranchName,		LEN(BranchLender_From.LenderName))	= BranchLender_From.LenderName			THEN DBO.ProperCase(LTRIM(RTRIM(SUBSTRING(Branch_From.BranchName,		Len(Branch_From.BranchName) - 1,		LEN(Branch_From.BranchName)))))
											WHEN LEFT(BranchLender_From.LenderName,	LEN(Branch_From.BranchName))		= Branch_From.BranchName				THEN DBO.ProperCase(LTRIM(RTRIM(SUBSTRING(BranchLender_From.LenderName,	Len(BranchLender_From.LenderName) - 1,	LEN(BranchLender_From.LenderName)))))	END,

		SourceBranchLocation		= CASE	WHEN Redirect.SourceLendersBranchID IS NULL THEN ''
											ELSE DBO.ProperCase(Branch_From.City) + ', ' + UPPER(Branch_From.State)	END,


		SourceDealerID				= Redirect.SourceDealerID,

		SourceDealer				= CASE	WHEN Redirect.SourceDealerID IS NULL THEN ''
											ELSE	ISNULL(DBO.ProperCase(SourceDealer.DealerName), '')	END,

		SourceDealerLocation		= CASE	WHEN Redirect.SourceDealerID IS NULL THEN ''
											ELSE	ISNULL(DBO.ProperCase(SourceDealer.City) + ', ' + UPPER(SourceDealer.State), '')	END,

		SourcePartnerToolID			= Redirect.SourcePartnerToolID,

		SourcePartner				= CASE	WHEN Redirect.SourcePartnerToolID IS NULL THEN ''
											ELSE Partner_From.ShortName	END,

		SourcePartnerName			= CASE	WHEN Redirect.SourcePartnerToolID IS NULL THEN ''
											WHEN NULLIF(Partner_From.DisplayName, '')	IS NULL THEN Partner_To.ShortName END,

		DestinationLenderID			= Redirect.DestinationLenderID,
		DestinationLender			= CASE	WHEN Redirect.DestinationLenderID IS NULL THEN ''			
											ELSE ISNULL(DBO.ProperCase(Lender_To.LenderName), '')	END,

		DestinationLenderLocation	= CASE	WHEN Redirect.DestinationLenderID IS NULL THEN ''			
											ELSE ISNULL(DBO.ProperCase(Lender_To.City) + ', ' + UPPER(Lender_To.State), '')	END,

		DestinationLendersBranchID	= Redirect.DestinationLendersBranchID,


		DestinationBranch			= CASE	WHEN Redirect.DestinationLendersBranchID IS NULL THEN ''
											WHEN LTRIM(RTRIM(BranchLender_To.LenderName))								= LTRIM(RTRIM(Branch_To.BranchName))	THEN DBO.ProperCase(Branch_To.BranchName)
											WHEN LEFT(Branch_To.BranchName,			LEN(BranchLender_To.LenderName))	= BranchLender_To.LenderName			THEN DBO.ProperCase(LTRIM(RTRIM(SUBSTRING(Branch_To.BranchName, Len(Branch_To.BranchName) - 1, LEN(Branch_To.BranchName)))))
											WHEN LEFT(BranchLender_To.LenderName,	LEN(Branch_To.BranchName))			= Branch_To.BranchName					THEN DBO.ProperCase(LTRIM(RTRIM(SUBSTRING(BranchLender_To.LenderName, Len(BranchLender_To.LenderName) - 1, LEN(BranchLender_To.LenderName)))))
																																								ELSE DBO.ProperCase(BranchLender_To.LenderName) + ' - ' + DBO.ProperCase(Branch_To.BranchName)	END,

		DestinationBranchLocation	= CASE	WHEN Redirect.DestinationLendersBranchID IS NULL THEN ''
											ELSE DBO.ProperCase(Branch_To.City) + ', ' + UPPER(Branch_To.State)	END,

		DestinationDealerID			= Redirect.DestinationDealerID,

		DestinationDealer			= CASE	WHEN Redirect.DestinationDealerID IS NULL THEN ''
											ELSE ISNULL(DBO.ProperCase(DestinationDealer.DealerName), '') + ISNULL( DBO.ProperCase(DestinationDealer.City) + ', ' + UPPER(DestinationDealer.State), '')	END,
		DestinationPartnerToolID	= Redirect.DestinationPartnerToolID,

		DestinationPartner			= CASE	WHEN Redirect.DestinationPartnerToolID IS NULL THEN ''
											ELSE Partner_To.ShortName	END,

		DestinationPartnerName		= CASE	WHEN Redirect.DestinationPartnerToolID IS NULL THEN ''
											WHEN NULLIF(Partner_To.DisplayName, '')	IS NULL THEN Partner_To.ShortName
											ELSE Partner_To.DisplayName END


	FROM
					tblLoanApp_Redirect			Redirect				WITH (NOLOCK)
		LEFT JOIN	tblLenders					Lender_From				WITH (NOLOCK) ON Redirect.SourceLenderID				= Lender_From.LenderID
		LEFT JOIN	tblLenders					Lender_To				WITH (NOLOCK) ON Redirect.DestinationLenderID			= Lender_To.LenderID
		LEFT JOIN	tblDealers					SourceDealer			WITH (NOLOCK) ON Redirect.SourceDealerID				= SourceDealer.DealerID
		LEFT JOIN	tblDealers					DestinationDealer		WITH (NOLOCK) ON Redirect.DestinationDealerID			= DestinationDealer.DealerID
		LEFT JOIN	tblLendersBranches			Branch_From				WITH (NOLOCK) ON Redirect.SourceLendersBranchID			= Branch_From.LendersBranchID
		LEFT JOIN	tblLenders					BranchLender_From		WITH (NOLOCK) ON Branch_From.LenderID					= BranchLender_From.LenderID
		LEFT JOIN	tblLendersBranches			Branch_To				WITH (NOLOCK) ON Redirect.DestinationLendersBranchID	= Branch_To.LendersBranchID
		LEFT JOIN	tblLenders					BranchLender_To			WITH (NOLOCK) ON Branch_To.LenderID						= BranchLender_To.LenderID
		LEFT JOIN	tblPartnerTools				Partner_From			WITH (NOLOCK) ON Redirect.SourcePartnerToolID			= Partner_From.PartnerToolID
		LEFT JOIN	tblPartnerTools				Partner_To				WITH (NOLOCK) ON Redirect.DestinationPartnerToolID		= Partner_To.PartnerToolID			AND		ISNULL(Partner_To.Active, 1)	= 1

	ORDER BY
		ISNULL(Redirect.Active, 1) DESC,
		Name,
		LoanApp_RedirectID

--Partner_To.Active=1





