/****** Object:  View dbo.viewLoanInformation    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewLoanInformation AS
SELECT --TOP 100 PERCENT

  LoanAppID                     = APP.LoanAppID,
  LoanApp_BidID                 = BID.LoanApp_BidID,
  WorksheetID                   = WORKSHEET.LoanApp_WorksheetID,
  APPLICANT_NAMES               = CreditSmarts.DBO.Capitalize(APP.APPLICANT_NAMES),

  ---------------------------------------
  -- DEALERSHIP INFORMATION
  ---------------------------------------

  DealerID                      = DEALER.DealerID,
--  Dealer                        = DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State,

  DealerName                    = CreditSmarts.DBO.Capitalize(DEALER.DealerName),
  DealerAddress					= CreditSmarts.DBO.Capitalize(DEALER.Address),
  DealerCity                    = CreditSmarts.DBO.Capitalize(DEALER.City),
  DealerState                   = UPPER(DEALER.State),
  DealerEMail                   = LOWER(DEALER.EMail),

  ---------------------------------------
  -- LENDER MASTER INFORMATION
  ---------------------------------------
  LenderID                      = LENDER_BRANCH.LenderID,
  LenderName                    = CreditSmarts.DBO.Capitalize(LENDER.LenderName),
  LenderEMail                   = LOWER(ISNULL(LENDER_BRANCH.notification_email, '')),
  LenderAddress                 = LENDER.Address,
  LenderCity                    = CreditSmarts.DBO.Capitalize(LENDER.City),
  LenderState                   = UPPER(LENDER.State),
  LenderZip                     = LENDER.ZIP,
  LenderDealerID                = APP.LenderID,


  ---------------------------------------
  -- LENDER BRANCH INFORMATION
  ---------------------------------------
  LendersBranchID               = BID.LendersBranchID,
  BranchName                    = CreditSmarts.DBO.Capitalize(LENDER_BRANCH.BranchName),
  BranchPhone                   = LENDER_BRANCH.Phone,
  BranchFax                     = LENDER_BRANCH.Fax,
  BranchStreet1                 = LENDER_BRANCH.STREET_1,
  BranchStreet2                 = LENDER_BRANCH.STREET_2,
  BranchState                   = LENDER_BRANCH.STATE,
  BranchZip                     = LENDER_BRANCH.ZIP,
  BranchCity                    = CreditSmarts.DBO.Capitalize(LENDER_BRANCH.CITY),

  YIELD_TYPE                    = BID.YIELD_TYPE,
  COMMENTS                      = BID.COMMENTS,
  TERM                          = BID.TERM,
  PAYMENT                       = BID.PAYMENT,
  MESSAGING_STATUS              = BID.MESSAGING_STATUS,
  REBATE_PERCT                  = BID.REBATE_PERCT,
  FINANCING_AMOUNT              = BID.FINANCING_AMOUNT,
  STATUS                        = BID.STATUS,
  ARCHIVED                      = BID.ARCHIVED,
  RATE                          = BID.RATE,
  LENDER_ARCHIVED               = BID.LENDER_ARCHIVED,
  FUNDED                        = BID.FUNDED,
  Stips                         = BID.Stips,
  Reason                        = BID.Reason,
  LENDER_CREDIT_EQ              = BID.LENDER_CREDIT_EQ,
  LENDER_CREDIT_TU              = BID.LENDER_CREDIT_TU,
  LENDER_CREDIT_EX              = BID.LENDER_CREDIT_EX,
  Reasons                       = BID.Reasons,
  DISCOUNT_FEE                  = BID.DISCOUNT_FEE,
  AUTOMATED                     = BID.AUTOMATED,
  CANCELED_DATE                 = BID.CANCELED_DATE,
  OFFER_DATE                    = BID.OFFER_DATE,
  FUNDED_DATE                   = BID.FUNDED_DATE,
  OFFERED_BY                    = BID.OFFERED_BY,
  ACCEPT_DATE                   = BID.ACCEPT_DATE,
  SUBMIT_DATE                   = BID.SUBMIT_DATE,
  SUBMIT_BY                     = BID.SUBMIT_BY,
  PRIMARY_SCORE                 = BID.PRIMARY_SCORE,
  SECONDARY_SCORE               = BID.SECONDARY_SCORE,
  ACCEPT_BY                     = BID.ACCEPT_BY,
  PTI                           = BID.PTI,
  DTI                           = BID.DTI,
  Counter                       = BID.Counter,
  ADVANCE                       = ISNULL(BID.ADVANCE,     0),


  ---------------------------------------
  -- VEHICLE INFORMATION
  ---------------------------------------

  VEHICLE                       = CASE
	WHEN WORKSHEET.VEHICLE_YEAR IS NOT NULL AND NULLIF(WORKSHEET.VEHICLE_MAKE, '') IS NOT NULL AND NULLIF(WORKSHEET.VEHICLE_MODEL, '') IS NOT NULL THEN
		CONVERT(CHAR(4), WORKSHEET.VEHICLE_YEAR) + ' ' + CreditSmarts.DBO.Capitalize(WORKSHEET.VEHICLE_MAKE + ' ' + WORKSHEET.VEHICLE_MODEL)  + ' (' + CreditSmarts.DBO.FormatNumber(WORKSHEET.VEHICLE_MILEAGE) + ' Miles)' 
	ELSE
		CONVERT(CHAR(4), APP.VEHICLE_YEAR) + ' ' + CreditSmarts.DBO.Capitalize(APP.VEHICLE_MAKE + ' ' + APP.VEHICLE_MODEL) + ' (' + CreditSmarts.DBO.FormatNumber(APP.VEHICLE_MILEAGE) + ' Miles)' 
	END,	

  VEHICLE_YEAR                  = ISNULL(WORKSHEET.VEHICLE_YEAR,                 APP.VEHICLE_YEAR),
  VEHICLE_MAKE                  = CreditSmarts.DBO.Capitalize(ISNULL(WORKSHEET.VEHICLE_MAKE,                 APP.VEHICLE_MAKE)),
  VEHICLE_MODEL                 = CreditSmarts.DBO.Capitalize(ISNULL(WORKSHEET.VEHICLE_MODEL,                APP.VEHICLE_MODEL)),
  VEHICLE_MILEAGE               = ISNULL(WORKSHEET.VEHICLE_MILEAGE,              APP.VEHICLE_MILEAGE),
  VEHICLE_VIN                   = UPPER(ISNULL(WORKSHEET.VEHICLE_VIN,            APP.VEHICLE_VIN)),
  VEHICLE_TYPE                  = ISNULL(WORKSHEET.VEHICLE_TYPE,                 APP.VEHICLE_TYPE),

  VEHICLE_NEW					= CONVERT(BIT, CASE ISNULL(WORKSHEET.NEW_USED, APP.NEW_USED)
									WHEN 'NEW'		THEN 1
									ELSE			0
								END),

  VEHICLE_DESCRIPTION           = CreditSmarts.DBO.Capitalize(ISNULL(WORKSHEET.VEHICLE_DESCRIPTION,          APP.VEHICLE_DESCRIPTION)),


  ---------------------------------------
  -- WORKSHEET INFORMATION
  ---------------------------------------


  ANTICIPATED_RATE              = ISNULL(WORKSHEET.ANTICIPATED_RATE,             APP.ANTICIPATED_RATE),
  LOAN_DOWN_PAYMENT             = ISNULL(WORKSHEET.LOAN_DOWN_PAYMENT,            APP.LOAN_DOWN_PAYMENT),
  LOAN_ESTIMATED_PAYMENT        = ISNULL(WORKSHEET.LOAN_ESTIMATED_PAYMENT,       APP.LOAN_ESTIMATED_PAYMENT),
  LOAN_LICENSE                  = ISNULL(WORKSHEET.LOAN_LICENSE,                 APP.LOAN_LICENSE),
  LOAN_MISC                     = ISNULL(WORKSHEET.LOAN_MISC,                    APP.LOAN_MISC),
  LOAN_PURCHASE_PRICE           = ISNULL(WORKSHEET.LOAN_PURCHASE_PRICE,          APP.LOAN_PURCHASE_PRICE),
  LOAN_TAX                      = ISNULL(WORKSHEET.LOAN_TAX,                     APP.LOAN_TAX),
  LOAN_TERM_REQUESTED           = ISNULL(WORKSHEET.LOAN_TERM_REQUESTED,          APP.LOAN_TERM_REQUESTED),
  LOAN_TOTAL_LOAN_AMOUNT        = ISNULL(WORKSHEET.LOAN_TOTAL_LOAN_AMOUNT,       APP.LOAN_TOTAL_LOAN_AMOUNT),
  LOAN_WARRANTY                 = ISNULL(WORKSHEET.LOAN_WARRANTY,                APP.LOAN_WARRANTY),
  LOAN_SALES_TAX_RATE           = ISNULL(WORKSHEET.LOAN_SALES_TAX_RATE,          APP.LOAN_SALES_TAX_RATE),
  LOAN_TRADE_IN_NET             = ISNULL(WORKSHEET.LOAN_TRADE_IN_NET,            APP.LOAN_TRADE_IN_NET),
  LOAN_LICENSE_TAXABLE          = ISNULL(WORKSHEET.LOAN_LICENSE_TAXABLE,         APP.LOAN_LICENSE_TAXABLE),
  LOAN_DOCSMOG_TAXABLE          = ISNULL(WORKSHEET.LOAN_DOCSMOG_TAXABLE,         APP.LOAN_DOCSMOG_TAXABLE),
  SMOG_CERTIFY_FEE              = ISNULL(WORKSHEET.SMOG_CERTIFY_FEE,             APP.SMOG_CERTIFY_FEE),
  SMOG_CERTIFY_FEE_TAXABLE      = ISNULL(WORKSHEET.SMOG_CERTIFY_FEE_TAXABLE,     APP.SMOG_CERTIFY_FEE_TAXABLE),
  SMOG_SELLER_FEE               = ISNULL(WORKSHEET.SMOG_SELLER_FEE,              APP.SMOG_SELLER_FEE),
  SMOG_SELLER_FEE_TAXABLE       = ISNULL(WORKSHEET.SMOG_SELLER_FEE_TAXABLE,      APP.SMOG_SELLER_FEE_TAXABLE),
  LOAN_GAP                      = ISNULL(WORKSHEET.LOAN_GAP,                     APP.LOAN_GAP),
  LOAN_GAP_TAXABLE              = ISNULL(WORKSHEET.LOAN_GAP_TAXABLE,             APP.LOAN_GAP_TAXABLE),
  LOAN_WARRANTY_TAXABLE         = ISNULL(WORKSHEET.LOAN_WARRANTY_TAXABLE,        APP.LOAN_WARRANTY_TAXABLE),
  LOAN_MISC2                    = ISNULL(WORKSHEET.LOAN_MISC2,                   APP.LOAN_MISC2),
  LOAN_MISC_TAXABLE             = ISNULL(WORKSHEET.LOAN_MISC_TAXABLE,            APP.LOAN_MISC_TAXABLE),


  LoanAppCOMMENTS               = CreditSmarts.DBO.Capitalize(APP.COMMENTS),

  BidSubmitDateTime             = ISNULL(BID.SUBMIT_DATE, BID.CreateDateTime),

  PartnerName                   = CreditSmarts.DBO.Capitalize(PARTNER.ShortName),
  LenderAgentName               = ISNULL(LENDER_LOGIN.FullName, ISNULL(BRANCH_LOGIN.FullName,'')),
  DealerSalesPerson             = ISNULL(DEALER_LOGIN.UserName, ''),
  BidFundingStatus              = ISNULL(FUNDING_STATUS.BidFundingStatus, '')

FROM
                    tblLoanApps                   APP       WITH (NOLOCK)
    INNER JOIN      tblLoanApp_Bids               BID                 WITH (NOLOCK) ON APP.LoanAppID						= BID.LoanAppID
    INNER JOIN      viewLenderBranches            LENDER_BRANCH       WITH (NOLOCK) ON BID.LendersBranchID					= LENDER_BRANCH.LendersBranchID
    INNER JOIN      tblLenders                    LENDER              WITH (NOLOCK) ON LENDER_BRANCH.LenderID  				= LENDER.LenderID
    LEFT OUTER JOIN tblDealers                    DEALER              WITH (NOLOCK) ON APP.DealerID  						= DEALER.DealerID
    LEFT OUTER JOIN tblLoanApp_Worksheet          WORKSHEET           WITH (NOLOCK) ON BID.LoanApp_BidID  					= WORKSHEET.LoanApp_BidID  AND WORKSHEET.ACTIVE =1
    LEFT OUTER JOIN viewLoanPartner               PARTNER             WITH (NOLOCK) ON APP.LoanAppID  						= PARTNER.LoanAppID
    LEFT OUTER JOIN tblLenderDealerRelation       LENDER_DEALER       WITH (NOLOCK) ON LENDER_DEALER.DealerID  				= DEALER.DealerID AND LENDER_BRANCH.LenderID  = LENDER_DEALER.LenderID
    LEFT OUTER JOIN tblLendersLogins              LENDER_LOGIN        WITH (NOLOCK) ON LENDER_LOGIN.LendersLoginID  		= LENDER_DEALER.LenderAgentID
    LEFT OUTER JOIN tblLendersBranchLogins        BRANCH_LOGIN        WITH (NOLOCK) ON BRANCH_LOGIN.LendersBranchLoginID  	= LENDER_DEALER.LenderBranchAgentID
    LEFT OUTER JOIN tblLoanAppAssignedDealers     ASSIGNED_DEALERS    WITH (NOLOCK) ON ASSIGNED_DEALERS.LoanAppID  			= APP.LoanAppID
    LEFT OUTER JOIN tblDealersLogins              DEALER_LOGIN        WITH (NOLOCK) ON DEALER_LOGIN.DealersLoginID  		= ASSIGNED_DEALERS.DealersLoginID
    LEFT OUTER JOIN tblLoanApp_BidFundingStatus   FUNDING_STATUS      WITH (NOLOCK) ON FUNDING_STATUS.LoanApp_BidID  		= BID.LoanApp_BidID

--WHERE APP.LOANAPPID = 829220
--ORDER BY    BID.LoanApp_BidID DESC,    APP.LoanAppID DESC





