/****** Object:  View dbo.viewLoanListGrid_Lender_NewDeals    Script Date: 7/31/2024 12:57:22 PM ******/
CREATE VIEW viewLoanListGrid_Lender_NewDeals AS
	SELECT --TOP 10
		------------------------------------------------------------------------------------------------------
		-- HEADER AREA
		------------------------------------------------------------------------------------------------------

		[UI.ShowInDealerNewDeals]		= CONVERT(BIT, 0),
		[UI.ShowInDealerMessaging]		= CONVERT(BIT, 0),
		[UI.ShowInDealerFunding	]		= CONVERT(BIT, 0),
		[UI.ShowInLenderNewDeals]		= CONVERT(BIT, 1),
		[UI.ShowInLenderPendingFunding]	= CONVERT(BIT, CASE
			WHEN StatusUpdateDateTime							IS	NULL		THEN 0
			WHEN BidFundingStatus								IS	NULL		THEN 0
			WHEN LEN(BidFundingStatus)							=	0			THEN 0
			WHEN DATEDIFF(day, StatusUpdateDateTime, GETDATE())	>	45			THEN 0
			WHEN BidFundingStatus								= 'RECEIVED'	THEN 1
			WHEN DATEDIFF(day, StatusUpdateDateTime, GETDATE()) > 30			THEN 0
			WHEN BidFundingStatus								= 'REJECTED'	THEN 1
		END),

		[UI.ShowInLenderMessaging] = CONVERT(BIT, CASE
			WHEN NOT Canceled_Date								IS	NULL					THEN 0
			WHEN Bid.Lender_Archived							=		1					THEN 0
			WHEN DATEDIFF(day, Bid.UpdateDateTime, GETDATE())	>	14						THEN 0
			WHEN Messaging_Status								=	'COMMENT_FOR_Lender'	THEN 1
			ELSE 0
		END),

		------------------------------------------------------------------------------------------------------
		-- Credit AREA
		------------------------------------------------------------------------------------------------------
		[Credit.Dealer.Count]					= CONVERT(INT, CASE WHEN	NULLIF(App.Dealer_Credit_EX, '') IS NULL THEN 0 ELSE 1 END + CASE WHEN	NULLIF(App.Dealer_Credit_EQ, '') IS NULL THEN 0 ELSE 1 END + CASE WHEN	NULLIF(App.Dealer_Credit_TU, '') IS NULL THEN 0 ELSE 1 END),
		[Credit.Dealer.EX]						= CONVERT(BIT, CASE WHEN	NULLIF(App.Dealer_Credit_EX, '') IS NOT NULL THEN 1 ELSE 0 END),
		[Credit.Dealer.EQ]						= CONVERT(BIT, CASE WHEN	NULLIF(App.Dealer_Credit_EQ, '') IS NOT NULL THEN 1 ELSE 0 END),
		[Credit.Dealer.TU]						= CONVERT(BIT, CASE WHEN	NULLIF(App.Dealer_Credit_TU, '') IS NOT NULL THEN 1 ELSE 0 END),
		[Credit.Lender.Count]					= CONVERT(INT, CASE WHEN	NULLIF(Bid.Lender_Credit_EX, '') IS NOT NULL THEN 1  WHEN   NULLIF(App.Lender_Credit_EX, '') IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN	NULLIF(Bid.Lender_Credit_EQ, '') IS NOT NULL THEN 1  WHEN   NULLIF(App.Lender_Credit_EQ, '') IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN	NULLIF(Bid.Lender_Credit_TU, '') IS NOT NULL THEN 1  WHEN   NULLIF(App.Lender_Credit_TU, '') IS NOT NULL THEN 1 ELSE 0 END),
		[Credit.Lender.EX]						= CONVERT(BIT, CASE WHEN	NULLIF(Bid.Lender_Credit_EX, '') IS NOT NULL THEN 1	WHEN    NULLIF(App.Lender_Credit_EX, '') IS NOT NULL THEN 1  ELSE 0 END),
		[Credit.Lender.EQ]						= CONVERT(BIT, CASE WHEN	NULLIF(Bid.Lender_Credit_EQ, '') IS NOT NULL THEN 1	WHEN    NULLIF(App.Lender_Credit_EQ, '') IS NOT NULL THEN 1  ELSE 0 END),
		[Credit.Lender.TU]						= CONVERT(BIT, CASE WHEN	NULLIF(Bid.Lender_Credit_TU, '') IS NOT NULL THEN 1	WHEN    NULLIF(App.Lender_Credit_TU, '') IS NOT NULL THEN 1  ELSE 0 END),


		------------------------------------------------------------------------------------------------------
		-- REQUEST AREA
		------------------------------------------------------------------------------------------------------
		[Request.LoanAppID]						= Bid.LoanAppID,
		[Request.LoanApp_BidID]					= Bid.LoanApp_BidID,
		[Request.AppID]							= CONVERT(VARCHAR(25), CONVERT(VARCHAR(12), Bid.LoanAppID) + '-' + CONVERT(VARCHAR(12), Bid.LoanApp_BidID)),
		[Request.Applicant_Names]				= DBO.ProperCase(App.Applicant_Names),
--		[Request.Internal]						= CONVERT(BIT, CASE WHEN )LenderDealerID					= App.LenderID
		[Request.Submitted]						= Bid.Submit_Date,
		[Request.SubmittedBy]					= Bid.Submit_By,
		[Request.Accepted]						= Bid.Accept_Date,
        [Request.Accept_By]						= Bid.Accept_By,
		[Request.Archived]						= ISNULL(App.Archived, 0),

		------------------------------------------------------------------------------------------------------
		-- Loan WORKSHET
		------------------------------------------------------------------------------------------------------
		[Request.Loan.Anticipated_Rate]			= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Anticipated_Rate				ELSE	App.Anticipated_Rate		END,	0	),
		[Request.Loan.Down_Payment]				= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_Down_Payment			ELSE	App.Loan_Down_Payment		END,	0	),
		[Request.Loan.Estimated_Payment]		= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_Estimated_Payment		ELSE	App.Loan_Estimated_Payment	END,	0	),
		[Request.Loan.License]					= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_License					ELSE	App.Loan_License			END,	0	),
		[Request.Loan.Misc]						= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_Misc					ELSE	App.Loan_Misc				END,	0	),
		[Request.Loan.Purchase_Price]			= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_Purchase_Price			ELSE	App.Loan_Purchase_Price		END,	0	),
		[Request.Loan.Tax]						= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_Tax						ELSE	App.Loan_Tax				END,	0	),
		[Request.Loan.Term_Requested]			= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_TERM_Requested			ELSE	App.Loan_TERM_Requested		END,	0	),
		[Request.Loan.Total_Loan_Amount]		= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_Total_Loan_Amount		ELSE	App.Loan_Total_Loan_Amount	END,	0	),
		[Request.Loan.Warranty]					= ISNULL(CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Loan_Warranty				ELSE	App.Loan_Warranty			END,	0	),
		[Request.Loan.CreatedBu]				= App.CreateUser,
		[Request.Loan.Created]					= ISNULL(App.CreateDateTime, App.UpdateDateTime),
		[Request.Loan.UpdatedBu]				= App.UpdateUser,
		[Request.Loan.Updated]					= ISNULL(App.UpdateDateTime, App.CreateDateTime),

		------------------------------------------------------------------------------------------------------
		-- Loan COLLATERAL AREA
		------------------------------------------------------------------------------------------------------
		[Request.Vehicle.WorksheetID]			= WS.LoanApp_WorksheetID,
		[Request.Vehicle.Caption]				= 					CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	CONVERT(CHAR(4), WS.Vehicle_Year) + ' ' + DBO.ProperCase(WS.Vehicle_Make + ' ' + WS.Vehicle_Model)		ELSE		CONVERT(CHAR(4), App.Vehicle_Year) + ' ' + DBO.ProperCase(App.Vehicle_Make + ' ' + App.Vehicle_Model)	END,
		[Request.Vehicle.Year]					= 					CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Vehicle_Year			ELSE	App.Vehicle_Year			END,
		[Request.Vehicle.Make]					= DBO.ProperCase(	CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Vehicle_Make			ELSE	App.Vehicle_Make			END),
		[Request.Vehicle.Model]					= DBO.ProperCase(	CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Vehicle_Model		ELSE	App.Vehicle_Model			END),
		[Request.Vehicle.VIN]					=					CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Vehicle_VIN			ELSE	App.Vehicle_VIN				END,
		[Request.Vehicle.Mileage]				=					CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Vehicle_Mileage		ELSE	App.Vehicle_Mileage			END,
		[Request.Vehicle.New_Used]				=					CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.New_Used				ELSE	App.New_Used				END,
		[Request.Vehicle.Description]			=					CASE WHEN WS.LoanApp_WorksheetID	IS NOT NULL	THEN	WS.Vehicle_Description	ELSE	App.Vehicle_Description		END,

		------------------------------------------------------------------------------------------------------
		-- PARTNER AREA
		------------------------------------------------------------------------------------------------------
		[Partner.ID]							= Partner.PartnerToolID,
		[Partner.Name]							= DBO.FormatPartnerName(ISNULL(Partner.Partner, '')),

		------------------------------------------------------------------------------------------------------
		-- RESPONSE AREA
		------------------------------------------------------------------------------------------------------
		[Response.Status]						= Bid.Status,
		[Response.Messaging]					= Messaging_Status,

		[Response.When]							= Bid.Offer_Date,
		[Response.Underwriter]					= Bid.Offered_By,
		[Response.Reminder_Date]				= Bid.Reminder_Date,

		[Response.Age]							= DATEDIFF(day, Bid.UpdateDateTime, GETDATE()),
		[Response.Archived.Lender]				= ISNULL(Bid.Lender_Archived, 0),
		[Response.Canceled]						= CONVERT(BIT, CASE WHEN Bid.Canceled_Date IS NULL THEN 0 ELSE 1 END),
		[Response.Canceled_Date]				= Bid.Canceled_Date,
		[Response.Funded]						= CONVERT(BIT, CASE WHEN Funded_Date IS NOT NULL THEN 1 ELSE ISNULL(Funded, 0) END),
		[Response.Funded_Date]					= Bid.Funded_Date,

		[Response.Yield_Type]					= ISNULL(NULLIF(Bid.Yield_Type, ''), 'INTEREST'),
		[Response.Counter_Offer]				= ISNULL(Bid.Counter, 0),
		[Response.Amount]						= Bid.Financing_Amount,
		[Response.Rate]							= Bid.Rate,
		[Response.Stips]						= Bid.Stips,
		[Response.Reason]						= Bid.Reason,
		[Response.Term]							= CONVERT(INTEGER, CASE WHEN Bid.Term IS NULL THEN NULL WHEN ISNUMERIC(Bid.Term) = 1 THEN Bid.Term WHEN Bid.Term = '' THEN NULL WHEN CHARINDEX('M', Bid.Term) > 0 AND ISNUMERIC(LEFT(Bid.Term, CHARINDEX('M', Bid.Term) - 1)) = 1 THEN LEFT(Bid.Term, CHARINDEX('M', Bid.Term) - 1) WHEN CHARINDEX('/', Bid.Term) > 0	AND ISNUMERIC(LEFT(Bid.Term, CHARINDEX('/', Bid.Term) - 1)) = 1 THEN LEFT(Bid.Term, CHARINDEX('/', Bid.Term) - 1) WHEN CHARINDEX(' ', Bid.Term) > 0	AND ISNUMERIC(LEFT(Bid.Term, CHARINDEX(' ', Bid.Term) - 1)) = 1 THEN LEFT(Bid.Term, CHARINDEX(' ', Bid.Term) - 1) ELSE NULL END),
		[Response.Payment]						= Bid.Payment,
		[Response.Rebate_Perct]					= Bid.Rebate_Perct,
		[Response.Advance]						= Bid.Advance,

		[Response.Created]						= Bid.CreateDateTime,
		[Response.Updated]						= Bid.UpdateDateTime,

		[Response.Fax.Status]					= NULLIF(Fax.Status, ''),
		[Response.Fax.Updated]					= FAX.UpdateDateTime,

		[Response.Funding.Status]				= NULLIF(BidFundingStatus, ''),
		[Response.Funding.Updated]				= StatusUpdateDateTime,


		------------------------------------------------------------------------------------------------------
		-- Dealer AREA
		------------------------------------------------------------------------------------------------------
		[Dealer.ID]								= Dealer.DealerID,
		[Dealer.Name]							= DBO.ProperCase(Dealer.DealerName),
		[Dealer.Location]						= DBO.ProperCase(Dealer.City) + ', ' + UPPER(Dealer.State),
		[Dealer.Branch]							= DBO.ProperCase(Dealer.Branch),
		[Dealer.CompanyCode]					= Dealer.LoginPrefix,
		[Dealer.Contact]						= Dealer.Contact,
		[Dealer.Address]						= Dealer.Address,
		[Dealer.City]							= DBO.ProperCase(Dealer.City),
		[Dealer.State]							= UPPER(Dealer.State),
		[Dealer.ZIP]							= RIGHT('00000' + CONVERT(VARCHAR(16), Dealer.ZIP), 5),
		[Dealer.Phone]							= dbo.scrubPhoneNumber(Dealer.Telephone),
		[Dealer.Fax]							= dbo.scrubPhoneNumber(Dealer.Fax),
		[Dealer.EMail]							= Dealer.EMail,
		[Dealer.Type]							= Dealer.DealerType,
		[Dealer.YearsInBusiness]				= Dealer.YearsInBusiness,
		[Dealer.TaxID]							= Dealer.TaxID,
		[Dealer.AffiliateID]					= Dealer.AffiliateID,
		[Dealer.SalesPerson.Name]				= ISNULL(Dealer_Login.FullName, ''),

		------------------------------------------------------------------------------------------------------
		-- Lender AREA
		------------------------------------------------------------------------------------------------------
		[Lender.ID]								= Lender.LenderID,
		[Lender.Name]							= DBO.ProperCase(ISNULL(Lender.LenderName, '')),
		[Lender.Location]						= DBO.ProperCase(Lender.City) + ', ' + UPPER(Lender.State),
		[Lender.Address]						= DBO.ProperCase(ISNULL(Lender.Address, '')),
		[Lender.City]							= DBO.ProperCase(ISNULL(Lender.City, '')),
		[Lender.State]							= UPPER(ISNULL(Lender.State, '')),
		[Lender.Agent.Name]						= ISNULL(Lender_Login.FullName, ''),
		[Lender.Resubmit_Policy]				= Lender.Resubmit_Policy,

		------------------------------------------------------------------------------------------------------
		-- Branch AREA
		------------------------------------------------------------------------------------------------------
		[Lender.Branch.ID]						= Branch.LendersBranchID,
		[Lender.Branch.Name]					= DBO.ProperCase(Branch.BranchName),
		[Lender.Branch.Location]				= CASE	WHEN LEN(ISNULL(Branch.City, '')) > 0 AND LEN(ISNULL(Branch.State, '')) > 0	THEN DBO.ProperCase(Branch.City) + ', ' +  UPPER(Branch.State)		WHEN LEN(ISNULL(Lender.City, '')) > 0 AND LEN(ISNULL(Lender.State, '')) > 0	THEN DBO.ProperCase(Lender.City) + ', ' + UPPER(Lender.State)		ELSE '' END,
		[Lender.Branch.Address]					= ISNULL(DBO.ProperCase(		ISNULL(NULLIF(Branch.Street_1,	''),	Lender.Address)),	''),
		[Lender.Branch.City]					= ISNULL(DBO.ProperCase(		ISNULL(NULLIF(Branch.City,		''),	Lender.City)),		''),
		[Lender.Branch.State]					= ISNULL(ISNULL(						NULLIF(Branch.State,				''),	Lender.State),		''),
		[Lender.Branch.ZIP]						= CASE WHEN ISNULL(Branch.ZIP, -1) >= 1 THEN RIGHT('00000' + CONVERT(VARCHAR(16), Branch.ZIP), 5) WHEN ISNULL(Lender.ZIP, -1) >= 1 THEN RIGHT('00000' + CONVERT(VARCHAR(16), Lender.ZIP), 5) ELSE '' end,
		[Lender.Branch.Phone]					= ISNULL(dbo.scrubPhoneNumber(	ISNULL(NULLIF(Branch.Phone,		''),	Lender.Phone)),		''),
		[Lender.Branch.Fax]						= ISNULL(dbo.scrubPhoneNumber(	ISNULL(NULLIF(Branch.Fax,		''),	Lender.Fax)),		''),
		[Lender.Branch.FaxOnly]					= ISNULL(						Branch.Fax_Only,								0),
		[Lender.Branch.Agent.Name]				= ISNULL(Branch_Login.FullName, '')
	FROM
						tblLoanApps						App			WITH (NOLOCK)
				JOIN	tblLoanApp_Bids					Bid						WITH (NOLOCK) ON App.LoanAppID				= Bid.LoanAppID
--				JOIN	viewLenderBranches				Branch			WITH (NOLOCK) ON Bid.LendersBranchID					= Branch.LendersBranchID
				JOIN	tblLendersBranches				Branch					WITH (NOLOCK) ON Bid.LendersBranchID					= Branch.LendersBranchID
				JOIN	tblLenders						Lender					WITH (NOLOCK) ON Branch.LenderID					= Lender.LenderID
--		LEFT	JOIN	viewLoanPartner					Partner					WITH (NOLOCK) ON App.LoanAppID				= Partner.LoanAppID
		LEFT	JOIN	viewBid_PartnerInformation		Partner					WITH (NOLOCK) ON Partner.LoanApp_BidID					= Bid.LoanApp_BidID
		LEFT	JOIN	tblLoanApp_Bids_Fax				FAX						WITH (NOLOCK) ON Bid.LoanApp_BidID						= FAX.LoanApp_BidID
		LEFT	JOIN	tblDealers						Dealer					WITH (NOLOCK) ON App.DealerID					= Dealer.DealerID
		LEFT	JOIN	tblLoanApp_Worksheet			WS						WITH (NOLOCK) ON Bid.LoanApp_BidID						= WS.LoanApp_BidID	AND ISNULL(WS.ACTIVE, 0) = 1
--AND WS.LoanApp_WorksheetID IN (SELECT MAX(LoanApp_WorksheetID) FROM tblLoanApp_Worksheet WS2 WITH (NOLOCK) WHERE WS2.LoanApp_BidID = Bid.LoanApp_BidID AND ISNULL(WS2.Active, 0) = 1)
		LEFT	JOIN	tblLoanApp_BidFundingStatus		FUNDING_Status			WITH (NOLOCK) ON Bid.LoanApp_BidID						= FUNDING_Status.LoanApp_BidID
		LEFT	JOIN	tblLenderDealerRelation			RELATION				WITH (NOLOCK) ON RELATION.DealerID						= Dealer.DealerID AND Branch.LenderID = RELATION.LenderID
		LEFT	JOIN	tblLendersLogins				Lender_Login			WITH (NOLOCK) ON Lender_Login.LendersLoginID			= RELATION.LenderAgentID
		LEFT	JOIN	tblLendersBranchLogins			Branch_Login			WITH (NOLOCK) ON Branch_Login.LendersBranchLoginID 		= RELATION.LenderBranchAgentID
		LEFT	JOIN	tblLoanAppAssignedDealers		ASSIGNED_Dealer			WITH (NOLOCK) ON ASSIGNED_Dealer.LoanAppID				= App.LoanAppID
		LEFT	JOIN	tblDealersLogins				Dealer_Login			WITH (NOLOCK) ON Dealer_Login.DealersLoginID			= ASSIGNED_Dealer.DealersLoginID

WHERE
		Bid.UpdateDateTime								>=		DateADD(day, -30, GETDATE())
	AND Canceled_Date									IS		NULL
	AND ISNULL(Bid.Lender_Archived, 0)					=		0
	AND Bid.Status										IN 		('PENDING_Lender', 'REFERRED', 'PENDING_B2B')
	AND ISNULL(BidFundingStatus, '')					NOT IN 	('RECEIVED', 'REJECTED')

		--AND Bid.CreateDateTime >= DateADD(dd, -30, GETDATE())
		--AND Lender.LenderID = 1133






GO

