/****** Object:  View dbo.viewLoanRouting_PartnerStateDealerType    Script Date: 7/31/2024 12:57:22 PM ******/

--SELECT * FROM tblLoanRouting_PartnerStateDealerType WITH (NOLOCK) ORDER BY LenderID, Priority, LendersBranchID;
--SELECT * FROM viewLoanRouting_PartnerStateDealerType

CREATE VIEW [dbo].[viewLoanRouting_PartnerStateDealerType] AS
	SELECT TOP 100 PERCENT
		RuleID							= Routing.Routing_StateDealerTypeID,
		RuleSource						= 'PartnerStateDealerType',
		Name							= CONVERT(VARCHAR(60),	UPPER(CASE WHEN NULLIF(MIN(Routing.Name), '') IS NOT NULL THEN MIN(Routing.Name) ELSE 'Un-Named Partner/State/DealerType Rule # ' + CONVERT(VARCHAR(16), Routing.Routing_StateDealerTypeID) END)),
		Description						= CONVERT(VARCHAR(60),	UPPER(ISNULL(MIN(Routing.Description), ''))),
		Score							= (				ISNULL(NULLIF(MIN(Routing.Priority),		 0), 100) + 1) * 10 + 120	-
											CASE ISNULL(MIN(Partner.PartnerToolID),					 0)		WHEN 0	THEN 0		ELSE 10		END		-
											CASE ISNULL(MIN(CONVERT(INTEGER, Routing.B2B_Only)),	 0)		WHEN 0	THEN 0		ELSE 10		END		-
											CASE ISNULL(MIN(Routing.LenderID),						 0)		WHEN 0	THEN 0		ELSE 10		END		-
											CASE ISNULL(MIN(Branch.LendersBranchID),				 0)		WHEN 0	THEN 0		ELSE 10		END		-
											CASE ISNULL(MIN(Dealer.DealerID),						 0)		WHEN 0	THEN 0		ELSE 10		END		-
											CASE LEN(ISNULL(MIN(Routing.DealerType),				''))	WHEN 0	THEN 0		ELSE 10		END		-
											CASE LEN(ISNULL(MIN(Routing.Dealer_State),				''))	WHEN 0	THEN 0		ELSE 20		END		-
											CASE LEN(ISNULL(MIN(Routing.Primary_Applicant_State),	''))	WHEN 0	THEN 0		ELSE 20 	END		-
											CASE LEN(ISNULL(MIN(Routing.All_Applicant_State),		''))	WHEN 0	THEN 0		ELSE 20		END,
		Priority						= MIN(Routing.Priority),

		LenderID						= MIN(Lender.LenderID),
		LendersBranchID					= MIN(Branch.LendersBranchID),
		DealerID						= MIN(Dealer.DealerID),
		PartnerToolID					= MIN(Partner.PartnerToolID),

		Lender							= CONVERT(VARCHAR(60), CASE WHEN NULLIF(MIN(Lender.LenderID), 0)		IS NULL	THEN ''	ELSE UPPER(MIN(Lender.LenderName)	+ ' (' + MIN(Lender.City)	+ ', '	+ MIN(Lender.State) + ')')	END),
		Branch							= CONVERT(VARCHAR(60), CASE WHEN NULLIF(MIN(Branch.LendersBranchID), 0)	IS NULL THEN ''	ELSE UPPER(MIN(Branch.BranchName)	+ ' (' + MIN(Branch.City)	+ ', '	+ MIN(Branch.State) + ')')	END),
		Dealer							= CONVERT(VARCHAR(60), CASE WHEN NULLIF(MIN(Dealer.DealerID), 0)		IS NULL THEN ''	ELSE UPPER(MIN(Dealer.DealerName)	+ ' (' + MIN(Dealer.City)	+ ', '	+ MIN(Dealer.State) + ')')	END),
		Partner							= CONVERT(VARCHAR(60), UPPER(ISNULL(MIN(Partner.ShortName), ''))),
		DealerType						= CONVERT(VARCHAR(20), MIN(Routing.DealerType)),
		Dealer_State					= CONVERT(VARCHAR( 2), UPPER(MIN(Routing.Dealer_State))),
		Primary_Applicant_State			= CONVERT(VARCHAR( 2), UPPER(MIN(Routing.Primary_Applicant_State))),
		All_Applicant_State				= CONVERT(VARCHAR( 2), UPPER(MIN(Routing.All_Applicant_State))),

		Filter_DealerType				= CONVERT(BIT, CASE WHEN MIN(Routing.DealerType)							IN		('FRANCHISE', 'INDEPENDENT')	THEN 1		ELSE 0		END),
		Filter_DealerState				= CONVERT(BIT, CASE WHEN LEN(MIN(Routing.Dealer_State))						=		2								THEN 1		ELSE 0		END),
		Filter_Partner					= CONVERT(BIT, CASE WHEN MIN(Partner.PartnerToolID)							IS		NULL							THEN 0		ELSE 1		END),
		Filter_PrimaryApplicantState	= CONVERT(BIT, CASE WHEN LEN(MIN(Routing.Primary_Applicant_State))			=		2								THEN 1		ELSE 0		END),
		Filter_ApplicantState			= CONVERT(BIT, CASE WHEN LEN(MIN(Routing.All_Applicant_State))				=		2								THEN 1		ELSE 0		END),
		Filter_Dealer					= CONVERT(BIT, CASE WHEN MIN(Dealer.DealerID)								IS		NOT NULL						THEN 1		ELSE 0		END),
		Filter_B2B_Only					= ISNULL(MIN(CONVERT(INTEGER, Routing.B2B_Only)), 0)

	FROM
				  tblLoanRouting_PartnerStateDealerType			Routing		WITH (NOLOCK)
		LEFT JOIN tblLenders									Lender		WITH (NOLOCK) ON	Lender.LenderID				= Routing.LenderID
		LEFT JOIN tblLendersBranches							Branch		WITH (NOLOCK) ON	Branch.LendersBranchID		= Routing.LendersBranchID		
		LEFT JOIN tblPartnerTools								Partner		WITH (NOLOCK) ON	Partner.PartnerToolID		= Routing.PartnerToolID
		LEFT JOIN tblDealers									Dealer		WITH (NOLOCK) ON	Dealer.DealerID				= Routing.DealerID
	WHERE
		Routing.Active					=  1						AND
		ISNULL(Partner.Active,	1)		=  1
	GROUP BY
		Routing.Routing_StateDealerTypeID
	ORDER BY
		LenderID,
		Score,
		LendersBranchID,
		DealerID,
		PartnerToolID,
		Name,
		Description



GO

SET QUOTED_IDENTIFIER OFF 
GO
SET ANSI_NULLS ON 
GO

