/****** Object:  View dbo.viewLoanRouting_PartnerStateDealerType_Middle    Script Date: 7/31/2024 12:57:22 PM ******/

--ALTER   VIEW viewLoanRouting_PartnerStateDealerType_Outer AS
CREATE VIEW viewLoanRouting_PartnerStateDealerType_Middle AS
	SELECT --TOP 10--0 PERCENT
		
		RuleID							= Rules.RuleID,
		RuleSource						= Rules.RuleSource,
		Name							= Rules.Name,
		Description						= Rules.Description,
		Rule_Dealer_State				= ISNULL(Rules.Dealer_State, ''),
		Score							= Rules.Score,
		Priority						= Rules.Priority,
		LoanApp_BidID					= Bid.LoanApp_BidID,
		LoanAppID						= Bid.LoanAppID,
		LenderID						= Branch.LenderID,
		LendersBranchID_Current			= Branch.LendersBranchID,
		LendersBranchID_Destination		= Rules.LendersBranchID,
		DealerID						= Dealer.DealerID,
		Dealer_State					= Dealer.State,

		[rule:Dealer_State]		= Rules.Dealer_State,
		[this:Dealer_State]		= Dealer.State,
		[this:isB2B]			= CASE 
			WHEN EXISTS(SELECT * FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LoanApp_BidID = Bid.LoanApp_BidID) THEN 1
			WHEN EXISTS(SELECT * FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LoanAppID = Bid.LoanAppID) THEN 1
			ELSE 0 END

--(SELECT COUNT(*) FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LoanApp_BidID = Bid.LoanApp_BidID)
--(SELECT COUNT(DISTINCT PartnerDataElementID) FROM tblPartnerDataElement PDE WITH (NOLOCK) WHERE PDE.LoanApp_BidID = Bid.LoanApp_BidID AND PDE.LoanAppID = 0 AND PDE.DealerID = 0 AND PDE.LenderID = 0 AND PDE.LendersBranchID = 0))


		--Rules.*
	FROM
				tblLoanApp_Bids								Bid			WITH (NOLOCK)
		JOIN	tblLoanApps									App			WITH (NOLOCK) ON App.LoanAppID				= Bid.LoanAppID
		JOIN	tblLendersBranches							Branch		WITH (NOLOCK) ON Branch.LendersBranchID		= Bid.LendersBranchID
		JOIN	tblLenders									Lender		WITH (NOLOCK) ON Lender.LenderID			= Branch.LenderID
		JOIN	tblDealers									Dealer		WITH (NOLOCK) ON Dealer.DealerID			= App.DealerID
		JOIN	viewLoanRouting_PartnerStateDealerType		Rules		WITH (NOLOCK) ON Rules.LenderID				= Lender.LenderID


	WHERE
		Bid.CreateDateTime		>=	DATEADD(d, -7, GETDATE())					AND
		(Rules.Filter_DealerState = 0	OR	ISNULL(Dealer.State, '')		= ISNULL(Rules.Dealer_State, ''))			AND
		(NOT EXISTS(SELECT * FROM tblLoanRoutingQueue RQ WITH (NOLOCK) WHERE RQ.LoanApp_BidID = Bid.LoanApp_BidID))
/*
	ORDER BY
		Score,
		Bid.LoanAppID,
		Bid.LoanApp_BidID
*/

GO

