/****** Object:  View dbo.viewLoanRouting_PartnerStateDealerType_Outer    Script Date: 7/31/2024 12:57:22 PM ******/
CREATE  VIEW viewLoanRouting_PartnerStateDealerType_Outer AS
	SELECT TOP 100--0 PERCENT
		Bids.LoanAppID,
		Bids.LoanApp_BidID,
		Branch.LenderID,
		LendersBranchID_Current		= Branch.LendersBranchID,
		LendersBranchID_Destination	= Rules.LendersBranchID,
		Dealer.DealerID,
		Dealer.State,
		Priority	= MIN(Rules.Priority),
		RuleName	= MIN(Rules.Name)
	FROM
				tblLoanApp_Bids								Bids	WITH (NOLOCK)
		JOIN	tblLoanApps									App		WITH (NOLOCK) ON App.LoanAppID				= Bids.LoanAppID
		JOIN	tblLendersBranches							Branch	WITH (NOLOCK) ON Branch.LendersBranchID		= Bids.LendersBranchID
		JOIN	tblDealers									Dealer	WITH (NOLOCK) ON Dealer.DealerID			= App.DealerID
		JOIN	viewLoanRouting_PartnerStateDealerType		Rules	WITH (NOLOCK) ON Rules.LenderID				= Branch.LenderID
	WHERE
		Bids.CreateDateTime		>=	DATEADD(d, -7, GETDATE())					AND
		Bids.LendersBranchID	<>	Rules.LendersBranchID						AND
--		Bids.RowVersion			=	1											AND
		App.RowVersion			=	1											AND
		Dealer.State			=	ISNULL(Rules.Dealer_State,	Dealer.State)	AND
		NOT EXISTS(SELECT * FROM tblLoanRoutingQueue RQ WITH (NOLOCK) WHERE RQ.LoanApp_BidID = Bids.LoanApp_BidID)


		--AND Dealer.State = 'FL'
	GROUP BY
		Bids.LoanAppID,
		Bids.LoanApp_BidID,
		Rules.Dealer_State,
		Dealer.DealerID,
		Dealer.State,
		Branch.LenderID,
		Branch.LendersBranchID,
		Rules.LendersBranchID,
		Rules.Priority

	ORDER BY
		Bids.LoanApp_BidID,
		Branch.LenderID,
		Rules.Priority





