/****** Object:  View dbo.viewLoggedin_Simple    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewLoggedin_Simple AS

SELECT TOP 100 PERCENT
	CurrentlyLoggedInID,

	LenderID			= CASE
		WHEN BL.LendersBranchID IS NULL AND LL.LenderID IS NOT NULL 	THEN LL.LenderID
		WHEN BL.LendersBranchID	IS NOT NULL AND B.LenderID IS NOT NULL	THEN B.LenderID
		ELSE NULL
	END,

	LendersBranchID		= BL.LendersBranchID,
	DealerID			= DL.DealerID,

	Company			= CASE
		WHEN B.BranchName		IS NOT NULL	THEN L.LenderName + ' - ' + B.BranchName
		WHEN L.LenderName		IS NOT NULL THEN L.LenderName
		WHEN D.DealerName		IS NOT NULL	THEN D.DealerName
		WHEN CLI.AdminLoginID	IS NOT NULL	THEN 'CreditSmarts'
		ELSE ''
	END,

	Location		= CASE
		WHEN B.BranchName		IS NOT NULL	THEN B.City + ', ' + B.State
		WHEN L.LenderName		IS NOT NULL THEN L.City + ', ' + L.State
		WHEN D.DealerName		IS NOT NULL	THEN D.City + ', ' + D.State
		WHEN CLI.AdminLoginID	IS NOT NULL	THEN 'Riverside, CA'
		ELSE ''
	END,

	Login			= CASE
		WHEN LL.UserName	IS NOT NULL THEN LL.UserName
		WHEN BL.UserName	IS NOT NULL	THEN BL.UserName
		WHEN DL.UserName	IS NOT NULL	THEN DL.UserName
		WHEN AL.UserName	IS NOT NULL	THEN AL.UserName
		ELSE ''
	END,

	Name			= CASE
		WHEN LEN(ISNULL(LL.UserName, '')) 	> 0		THEN LL.FullName
		WHEN LEN(ISNULL(BL.FullName, ''))	> 0		THEN BL.FullName
		WHEN LEN(ISNULL(DL.FullName, ''))	> 0		THEN DL.FullName
		WHEN LEN(ISNULL(AL.FullName, ''))	> 0		THEN AL.FullName
		WHEN LL.UserName	IS NOT NULL 			THEN LL.UserName
		WHEN BL.UserName	IS NOT NULL				THEN BL.UserName
		WHEN DL.UserName	IS NOT NULL				THEN DL.UserName
		WHEN AL.UserName	IS NOT NULL				THEN AL.UserName
		ELSE ''
	END,

	Description			= CASE
		WHEN LL.Description	IS NOT NULL THEN LL.Description
		WHEN BL.Description	IS NOT NULL	THEN BL.Description
		WHEN DL.Description	IS NOT NULL	THEN DL.Description
		WHEN AL.Description	IS NOT NULL	THEN AL.Description
		ELSE ''
	END,

	LoginDateTime

FROM
				tblCurrentlyLoggedIn	CLI	WITH (NOLOCK)

	LEFT JOIN	tblLendersLogins		LL	WITH (NOLOCK)	ON CLI.LendersLoginID		= LL.LendersLoginID
	LEFT JOIN	tblLendersBranchLogins	BL	WITH (NOLOCK)	ON CLI.LendersBranchLoginID	= BL.LendersBranchLoginID
	LEFT JOIN	tblDealersLogins		DL	WITH (NOLOCK)	ON CLI.DealersLoginID		= DL.DealersLoginID
	LEFT JOIN	tblAdminLogins			AL	WITH (NOLOCK)	ON CLI.AdminLoginID			= AL.AdminLoginID

	LEFT JOIN	tblLendersBranches		B	WITH (NOLOCK)	ON B.LendersBranchID		= BL.LendersBranchID
	LEFT JOIN	tblLenders				L	WITH (NOLOCK)	ON 
		(B.LenderID IS NOT NULL AND L.LenderID = B.LenderID)			
		OR (B.LenderID IS NULL AND L.LenderID = LL.LenderID)


	LEFT JOIN	tblDealers				D	WITH (NOLOCK)	ON D.DealerID				= DL.DealerID															OR L.LenderID				= B.LenderID

WHERE
	CLI.LoginDateTime > '2012-01-01'
	AND NOT (BL.LendersBranchID IS NOT NULL AND L.LenderID IS NULL)

ORDER BY 
	CLI.CurrentlyLoggedInID DESC



GO

