/****** Object:  View dbo.viewLoginNames    Script Date: 7/31/2024 12:57:22 PM ******/
CREATE  VIEW viewLoginNames AS
	SELECT
		Type						= 'Admin',
		Company						= 'CreditSmarts',
		SubCompany					= '',
		CompanyCode					= 'CSmarts_Internal',
		AdminLoginID				= L.AdminLoginID,
		LenderID					= NULL,
		LendersBranchID				= NULL,
		DealerID					= NULL,
		LendersLoginID				= NULL,
		LendersBranchLoginID		= NULL,
		DealersLoginID				= NULL,
		UserName					= LOWER(L.UserName),
		UserID						= 'CSMarts_Internal\' + LOWER(L.UserName),
		AltUserID					= LOWER(L.UserName) + '@' + 'CSmarts_Internal',
		Name						= DBO.ProperCase(CASE WHEN L.FullName IS NULL THEN L.UserName WHEN LEN(L.FullName) = 0 THEN L.UserName ELSE L.FullName END),
		Description					= CASE WHEN L.Description IS NULL THEN '' WHEN LEN(L.Description) = 0 THEN '' ELSE DBO.ProperCase(L.Description) END
	FROM
		tblAdminLogins	L	WITH (NOLOCK)
	WHERE
		L.UserName			IS	NOT NULL		AND
		L.Password			IS	NOT NULL		AND
		LEN(L.UserName)		>	0				AND
		LEN(L.Password)		>	0

	UNION ALL

	SELECT
		Type						= 'Lender',
		Company						= DBO.ProperCase(C.LenderName),
		SubCompany					= '',
		CompanyCode					= LOWER(C.LoginPrefix),
		AdminLoginID				= NULL,
		LenderID					= L.LenderID,
		LendersBranchID				= NULL,
		DealerID					= NULL,
		LendersLoginID				= L.LendersLoginID,
		LendersBranchLoginID		= NULL,
		DealersLoginID				= NULL,
		UserName					= LOWER(L.UserName),
		UserID						= LOWER(ISNULL(C.LoginPrefix, '')) + '\' + LOWER(L.UserName),
		AltUserID					= LOWER(L.UserName) + '@' + ISNULL(C.LoginPrefix, ''),
		Name						= DBO.ProperCase(CASE WHEN L.FullName IS NULL THEN L.UserName WHEN LEN(L.FullName) = 0 THEN L.UserName ELSE L.FullName END),
		Description					= CASE WHEN L.Description IS NULL THEN '' WHEN LEN(L.Description) = 0 THEN '' ELSE DBO.ProperCase(L.Description) END
	FROM
					tblLendersLogins	L	WITH (NOLOCK)
		INNER JOIN	tblLenders			C	WITH (NOLOCK)	ON C.LenderID = L.LenderID
	WHERE
		C.LenderStatus 		IN	('ACTIVE', 'TRIAL_30')		AND
		L.UserName			IS	NOT NULL					AND
		L.Password			IS	NOT NULL					AND
		LEN(L.UserName)		>	0							AND
		LEN(L.Password)		>	0

	UNION ALL

	SELECT
		Type						= 'Branch',
		Company						= DBO.ProperCase(C.LenderName),
		SubCompany					= DBO.ProperCase(SC.BranchName),
		CompanyCode					= LOWER(SC.LoginPrefix),
		AdminLoginID				= NULL,
		LenderID					= C.LenderID,
		LendersBranchID				= SC.LendersBranchID,
		DealerID					= NULL,
		LendersLoginID				= NULL,
		LendersBranchLoginID		= L.LendersBranchLoginID,
		DealersLoginID				= NULL,
		UserName					= LOWER(L.UserName),
		UserID						= LOWER(ISNULL(SC.LoginPrefix, '') + '\' + L.UserName),
		AltUserID					= LOWER(L.UserName + '@' + ISNULL(C.LoginPrefix, '')),
		Name						= DBO.ProperCase(CASE WHEN L.FullName IS NULL THEN L.UserName WHEN LEN(L.FullName) = 0 THEN L.UserName ELSE L.FullName END),
		Description					= CASE WHEN L.Description IS NULL THEN '' WHEN LEN(L.Description) = 0 THEN '' ELSE DBO.ProperCase(L.Description) END
	FROM
					tblLendersBranchLogins			L	WITH (NOLOCK)
		INNER JOIN	tblLendersBranches				SC	WITH (NOLOCK)	ON SC.LendersBranchID = L.LendersBranchID
		INNER JOIN	tblLenders						C	WITH (NOLOCK)	ON C.LenderID = SC.LenderID
	WHERE
		C.LenderStatus		IN ('ACTIVE', 'TRIAL_30')		AND
		L.UserName			IS	NOT NULL					AND
		L.Password			IS	NOT NULL					AND
		LEN(L.UserName)		>	0							AND
		LEN(L.Password)		>	0

	UNION ALL

	SELECT
		Type						= 'Dealer',
		Company						= DBO.ProperCase(C.DealerName),
		SubCompany					= '',
		CompanyCode					= LOWER(C.LoginPrefix),
		AdminLoginID				= NULL,
		LenderID					= NULL,
		LendersBranchID				= NULL,
		DealerID					= C.DealerID,
		LendersLoginID				= NULL,
		LendersBranchLoginID		= NULL,
		DealersLoginID				= L.DealersLoginID,
		UserName					= LOWER(L.UserName),
		UserID						= LOWER(ISNULL(C.LoginPrefix, '') + '\' + L.UserName),
		AltUserID					= LOWER(L.UserName + '@' + ISNULL(C.LoginPrefix, '')),
		Name						= DBO.ProperCase(CASE WHEN L.FullName IS NULL THEN L.UserName WHEN LEN(L.FullName) = 0 THEN L.UserName ELSE L.FullName END),
		Description					= CASE WHEN L.Description IS NULL THEN '' WHEN LEN(L.Description) = 0 THEN '' ELSE DBO.ProperCase(L.Description) END
	FROM
					tblDealersLogins	L	WITH (NOLOCK)
		INNER JOIN	tblDealers			C	WITH (NOLOCK)	ON C.DealerID = L.DealerID
	WHERE
		C.DealerStatus		IN	('ACTIVE', 'TRIAL_10', 'NO_CREDIT')		AND
		L.UserName			IS	NOT NULL								AND
		L.Password			IS	NOT NULL								AND
		LEN(L.UserName)		>	0										AND
		LEN(L.Password)		>	0



