/****** Object:  View dbo.viewPartnerApplication_ShouldSend    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW [dbo].[viewPartnerApplication_ShouldSend] AS
	SELECT 
		LoanAppID			= Bid.LoanAppID,
		LoanApp_BidID		= PDR.LoanApp_BidID,
		LenderID			= Branch.LenderID,
		PartnerToolID		= PDR.PartnerToolID,
		SentAgo				= DATEDIFF(mi, TS_Success,		GETDATE()),
		ErrorAgo			= DATEDIFF(mi, TS_LastError,	GETDATE()),
		ShouldSend			= CONVERT(BIT, CASE	
								WHEN 						 TS_Success		IS NOT NULL AND TS_Success	< APP.UpdateDateTime			THEN 1
								WHEN SuccessCount	>= 1 AND TS_Success		IS NOT NULL AND DATEDIFF(mi, TS_Success,	GETDATE()) < 180 THEN 0
								WHEN ErrorCount		>= 1 AND TS_LastError	IS NOT NULL AND DATEDIFF(mi, TS_LastError,	GETDATE()) < 10 THEN 0
								WHEN TS_Success		IS NULL THEN 1 ELSE 0 END)
	FROM
				tblPartnerApplication_Receipt	PDR		WITH (NOLOCK)
		JOIN	tblLoanApp_Bids				Bid		WITH (NOLOCK) ON Bid.LoanApp_BidID			= PDR.LoanApp_BidID
		JOIN	tblLoanApps					APP		WITH (NOLOCK) ON APP.LoanAppID				= Bid.LoanAppID
		JOIN	tblLendersBranches			Branch	WITH (NOLOCK) ON Branch.LendersBranchID		= Bid.LendersBranchID




