/****** Object:  View dbo.viewPartnerLenderSetup    Script Date: 7/31/2024 12:57:22 PM ******/
--viewPartnerDataElementValues

-- DECLARE @_Now DATETIME; SET @_Now = GETDATE();
-- SET NOCOUNT ON;
-- SET ROWCOUNT 250;
CREATE VIEW [viewPartnerLenderSetup] AS
	SELECT
			[PartnerToolID]						= [Keys].[PartnerToolID],
			[Partner]									= LEFT(MIN([Partner].[ShortName]), 20),
			[PartnerActive]						= [Partner].[Active],
			[LenderID]								= [Branch].[LenderID],
			[Lender]									= LEFT(MIN([Lender].[LenderName]), 30),
			[LendersBranchID]					= [Branch].[LendersBranchID],
			[LenderActive]						= [Keys].[Active],
			[Partner_LenderID]				= [ID].[DataValue],
			[Partner_Certificate]			= ISNULL([Crt].[DataValue],	[Keys].[CrtFixed]),
			[Partner_URL]							= ISNULL([Url].[DataValue], [Keys].[UrlFixed]),
			[Partner_Login]						= ISNULL([Un].[DataValue],	[Keys].[UnFixed]),
			[Partner_Password]				= ISNULL([Pw].[DataValue],	[Keys].[PwFixed]),
			[Partner_LenderID_Name]		= [Fields].[LenderID],
			[Partner_LoanID_Name]			= [Fields].[ApplicationID],
			[Partner_DealerID_Name]		= [Fields].[DealerID]
	FROM
								[tblPartnerTools]									[Partner]
					JOIN	[viewPartnerLenderSetup_Inner]		[Keys] 					WITH	(NOLOCK)	ON	[Keys].[PartnerToolID]		 	= [Partner].[PartnerToolID]
					JOIN	[tblLendersBranches]							[Branch]				WITH	(NOLOCK)	ON	[Branch].[LendersBranchID]	= [Keys].[LendersBranchID]
					JOIN	[tblLenders]											[Lender]				WITH	(NOLOCK)	ON	[Lender].[LenderID]					= [Branch].[LenderID]
		LEFT	JOIN	[viewPartnerIdentifierFields]			[Fields]				WITH	(NOLOCK)	ON	[Fields].[PartnerToolID]		= [Keys].[PartnerToolID]
		LEFT	JOIN	[tblPartnerDataElement]						[ID]						WITH	(NOLOCK)	ON	[Keys].[idID]								 = [ID].[PartnerDataElementID]		AND	[Keys].[idID]			IS NOT NULL
		LEFT	JOIN	[tblPartnerDataElement]						[Un]						WITH	(NOLOCK)	ON	[Keys].[unID]								 = [Un].[PartnerDataElementID]		AND	[Keys].[unID]			IS NOT NULL
		LEFT	JOIN	[tblPartnerDataElement]						[Pw]						WITH	(NOLOCK)	ON	[Keys].[pwID]								 = [Pw].[PartnerDataElementID]		AND	[Keys].[pwID]			IS NOT NULL
		LEFT	JOIN	[tblPartnerDataElement]						[Url]						WITH	(NOLOCK)	ON	[Keys].[urlID]							 = [Url].[PartnerDataElementID]		AND [Keys].[urlID]		IS NOT NULL
		LEFT	JOIN	[tblPartnerDataElement]						[Crt]						WITH	(NOLOCK)	ON	[Keys].[crtID]							 = [crt].[PartnerDataElementID]		AND	[Keys].[crtID]		IS NOT NULL
	WHERE
		[Lender].[LenderStatus] NOT IN ('INACTIVE', 'FAX')
	GROUP BY
		[Keys].[PartnerToolID],
		[Partner].[Active],
		[Branch].[LenderID],
		[Branch].[LendersBranchID],
		[Keys].[Active],
		[ID].[DataValue],
		[UN].[DataValue],
		[PW].[DataValue],
		[URL].[DataValue],
		[CRT].[DataValue],
		[Keys].[UrlFixed],
		[Keys].[UnFixed],
		[Keys].[PwFixed],
		[Keys].[CrtFixed],
		[Fields].[LenderID],
		[Fields].[ApplicationID],
		[Fields].[DealerID]


