/****** Object:  View dbo.viewPartnerRelationFields    Script Date: 7/31/2024 12:57:22 PM ******/
CREATE view viewPartnerRelationFields as 
SELECT
	PR.*, 
	PED.PartnerElementDefinitionID,
	PED.Field,
	PED.Description,
	PED.ValueType,
	PED.ShowOnDealerAdmin,
	PED.ShowOnLenderAdmin,
	PED.ShowOnLendersBranchAdmin,
	PED.ShowOnAffiliateAdmin,
	PED.Caption,
	PED.[KeyedFromLoanAppID],
	PED.[KeyedFromLenderID],
	PED.[KeyedFromLendersBranchID],
	PED.[KeyedFromDealerID],
	PED.[KeyedFromAffiliateID],
	PED.[SortSequence],
	PED.[Value],
	PED.[Notes],
	PED.[ShowOnLenderDealerConsoleAdmin],
	--PDE.LenderID,
	--PDE.DealerID,
	--PDE.LendersBranchID,
	PDE.PartnerDataElementID,
	PDE.LoanAppID, 
	PDE.LoanApp_BidID,
	PDE.DataValue,
	PDE.CreateDateTime as PDE_CreateDateTime,
	PDE.UpdateDateTime as PDE_UpdateDateTime
