/****** Object:  View dbo.viewPartnerReport_APC    Script Date: 7/31/2024 12:57:22 PM ******/



CREATE view viewPartnerReport_APC AS

SELECT TOP 5000
  LoanAppID               = APP.LoanAppID,
  "Export Label"          = CONVERT(VARCHAR(32), APP.LoanAppID) + '-' + CONVERT(VARCHAR(32), APP.LoanApp_BidID),                                                     -- A HISTORICALLY UNIQUE IDENTIFIER FOR THIS FILE A NAME FOR THIS FILE                                            | GoodLeads02012003
  "Export Date"           = GETDATE()                                                             , -- DATE THIS DATA WAS EXPORTED                                                                                    | 02/28/2003
  "CustomerID"            = APP.DealerID                               , -- CUSTOMER IDENTIFIER FROM YOUR SYSTEM                                                                           | 1
  "DealerID"              = ''                                                          , -- UNIQUE DEALER IDENTIFIER FROM YOUR SYSTEM THAT DESCRIBES WHAT DEALER OR SUB-GROUP THIS CUSTOMER IS FROM        | DLR2, Club3, Region1
  "Salutation"            = ''                                                                    , -- SALUTATION PREFIX FOR CUSTOMERS NAME                                                                           | Dr, Mr, Mrs, etc
  "First Name"            = UPPER(APPLICANT.FIRST_NAME)                                           , -- CUSTOMERS FIRST NAME                                                                                           | Kyle
  "Middle Name"           = UPPER(ISNULL(APPLICANT.MIDDLE_INITIAL, ''))                              , -- CUSTOMERS MIDDLE NAME OR MIDDLE INITIAL                                                                        | P
  "Last Name"             = UPPER(APPLICANT.LAST_NAME)                                            , -- CUSTOMERS LAST NAME                                                                                            | McEvoy
  "Suffix"                = UPPER(ISNULL(APPLICANT.SUFFIX, ''))                                   , -- CUSTOMERS SURNAME SUFFIX                                                                                       | Jr, III, IV, etc
  "Address 1"             = UPPER(ISNULL(APPLICANT_ADDRESS.STREET_1, ''))                         , -- CUSTOMERS ADDRESS                                                                                              | 1313 Mockingbird Drive
  "Address 2"             = UPPER(ISNULL(APPLICANT_ADDRESS.STREET_2, ''))                         , -- ADDITIONAL ADDRESS FOR CUSTOMER                                                                                | Apt 3D
  "City"                  = UPPER(ISNULL(APPLICANT_ADDRESS.CITY, ''))                             , -- CUSTOMERS CITY                                                                                                 | Chesterfield
  "State"                 = UPPER(ISNULL(APPLICANT_ADDRESS.STATE, ''))                            , -- CUSTOMERS STATE                                                                                                | MO
  "Zip Code"              = DBO.fmt_zip(ISNULL(APPLICANT_ADDRESS.ZIP, ''))                        , -- CUSTOMERS ZIP CODE CAN BE UP TO 10 DIGITS BUT MUST MINIMALLY BE AT LEAST FIVE DIGITS                           | 63043
  "Day Phone"             = CASE                                                                  -- CUSTOMERS HOME NUMBER                                                                                          | 6367333317
    WHEN ISNULL(APPLICANT.HOME_PHONE_AREA_CODE, 0) > 0 AND
         ISNULL(APPLICANT.HOME_PHONE_PREFIX, 0) > 0 AND
         ISNULL(APPLICANT.HOME_PHONE_NUMBER, 0) > 0 THEN
        REPLACE(DBO.fmt_phone_simple(
          APPLICANT.HOME_PHONE_AREA_CODE,
          APPLICANT.HOME_PHONE_PREFIX,
          APPLICANT.HOME_PHONE_NUMBER), '-', '')
    ELSE
      ''
    END,
  "Evening Phone"         = ''                                                            , -- CUSTOMERS WORK NUMBER                                                                                          | 6365551212
  "Email Address"         = LOWER(ISNULL(APPLICANT.EMAIL_ADDRESS, ''))                                                            , -- EMAIL ADDRESS                                                                                                  |
  "Purchase Date"         =       ISNULL(APP.OFFER_DATE, APP.BidUpdateDateTime)                                              , -- PURCHASE DATE OF VEHICLE                                                                                       | 01/30/2003
  "Purchase Price"        =       APP.LOAN_PURCHASE_PRICE                                         , -- PURCHASE PRICE OF VEHICLE (DDDDDDCC)                                                                           | 55248.98
  "New or Used or Lease"  = CASE
    WHEN APP.VEHICLE_YEAR >= YEAR(APP.CreateDateTime) -1 AND APP.VEHICLE_MILEAGE < 500 THEN
      'N'
    ELSE
      'U'
    END,
  "VIN"                   =       APP.VEHICLE_VIN                                                 , -- VIN OF VEHICLE                                                                                                 | 12WFT61L025607608
  "Year"                  =       APP.VEHICLE_YEAR                                                , -- YEAR OF VEHICLE                                                                                                | 1999
  "Make"                  =       UPPER(APP.VEHICLE_MAKE)                                                , -- MAKE OF VEHICLE                                                                                                | Chevrolet
  "Model"                 =       UPPER(APP.VEHICLE_MODEL)                                               , -- MODEL OF VEHICLE                                                                                               | Cavalier
  "In Service Date"       =       ISNULL(APP.OFFER_DATE, APP.BidUpdateDateTime)                                              , -- VEHICLE IN SERVICE DATE (USE SALE DATE IF FIELD 20=N)                                                          | 01/01/2001
  "Mileage"               =       APP.VEHICLE_MILEAGE                                             , -- MILEAGE OF VEHICLE                                                                                             | 100000
  "Mileage Date"          =       APP.CreateDateTime                                              , -- DATE THE MILEAGE WAS RECORDED (IF 20 = N USE FIELD 18)                                                         | 01/01/2001
  "Warranty Flag"         =       'N'                                                             -- VEHICLE HAS AN EXTENDED WARRANTY                                                                               | "Y"= Yes, "N"= No
FROM
  view_LoanApps_Bids APP WITH (NOLOCK)
  JOIN tblLoanApp_Applicant APPLICANT WITH (NOLOCK) ON (APP.LoanAppID=APPLICANT.LoanAppID)
  JOIN tblLoanApp_CurrAddress APPLICANT_ADDRESS WITH (NOLOCK) ON (APPLICANT.LoanApp_ApplicantID=APPLICANT_ADDRESS.LoanApp_ApplicantID)
WHERE
  APPLICANT.LoanApp_ApplicantID = (SELECT MIN(LoanApp_ApplicantID) FROM tblLoanApp_Applicant A2 WITH (NOLOCK) WHERE APPLICANT.LoanAppID=A2.LoanAppID)
  AND LEN(ISNULL(APP.VEHICLE_VIN, '')) > 0 AND ISNULL(APP.LOAN_PURCHASE_PRICE, 0) > 0
  AND APP.LoanApp_BidID IN (SELECT MAX(LoanApp_BidID) FROM tblLoanApp_Bids B WITH (NOLOCK) WHERE B.LoanAppID=APP.LoanAppID AND (B.STATUS IN ('ACCEPTED') OR ISNULL(B.FUNDED, 0) = 1 OR B.FUNDED_DATE IS NOT NULL))
  AND APP.VEHICLE_YEAR >=1999
  AND APP.VEHICLE_MILEAGE < 80000
  AND DATEDIFF(yy, APP.CreateDateTime, GETDATE()) <=2
ORDER BY
  ISNULL(APP.OFFER_DATE, APP.BidUpdateDateTime) DESC





GO

