/****** Object:  View dbo.viewPartnerToolsExchangeServiceLogin    Script Date: 7/31/2024 12:57:22 PM ******/


CREATE VIEW [dbo].[viewPartnerToolsExchangeServiceLogin] AS
 SELECT --TOP 100 PERCENT
  PartnerRelationID   =  PR.PartnerRelationID,
  PartnerToolID    =  PTUS.PartnerToolID,
  ToolName     =  PTUS.ToolName,
  ToolDisplayName    =  PTUS.ToolDisplayName,
  PartnerToolsTriggerID  =  PTUS.PartnerToolsTriggerID,
  TriggerName     =  PTUS.TriggerName,
  TriggerDescription   =  CASE
   WHEN LEN(ISNULL(PTUS.TriggerDescription, '')) > 0 THEN
    PTUS.TriggerDescription
   WHEN LEN(ISNULL(PTUS.TriggerName, '')) > 0 THEN
    PTUS.TriggerName
   ELSE NULL
   END,
  Active = ISNULL(PR.Active, 1),
  PR.LenderID,
  LenderName = UPPER(LENDER.LenderName),
  LenderCity = UPPER(LENDER.City),
  LenderState = UPPER(LENDER.State),
  LenderCompanyCode = UPPER(Lender.LoginPrefix),

  URL = CASE
   WHEN LEN(ISNULL(PR.URL, '')) > 0  THEN PR.URL
   WHEN LEN(ISNULL(PTUS.URL, '')) > 0 THEN PTUS.URL
   ELSE NULL
  END,
  Login = PR.Login,
  Password = PR.Password,
  Password_Display = CASE
   WHEN LEN(ISNULL(PR.Password, '')) = 0 THEN '(none)'
   ELSE '(not displayed)'
  END,

  CreateDateTime = PR.CreateDateTime,
  CreateUser = PR.CreateUser,

  UpdateDateTime = PR.UpdateDateTime,
  UpdateUser = PR.UpdateUser,

  RowVersion = PR.RowVersion
 FROM
       tblLenders        LENDER  WITH (NOLOCK)
  LEFT OUTER JOIN  tblPartnerRelation      PR   WITH (NOLOCK) ON (PR.LenderID = LENDER.LenderID)
  INNER JOIN  viewPartnerToolsExchangeServices  PTUS  WITH (NOLOCK) ON (PR.PartnerToolID = PTUS.PartnerToolID)

-- ORDER BY
