/****** Object:  View dbo.viewPartnerTriggers_WithLenderOverride    Script Date: 7/31/2024 12:57:22 PM ******/
CREATE view viewPartnerTriggers_WithLenderOverride as 

SELECT 
	
	TOOL.PartnerToolID,
	TOOL.ShortName,
	--Name = TOOL.DisplayName,

	TRIG.PartnerToolsTriggerID,
	TRIG.[Type],
	TRIG.Name,
	
	[URL]		= ISNULL(NULLIF(ELEMENT_FUNDING_URL.DataValue, ''),	TRIG.URL),
	[Username]	= ISNULL(NULLIF(ELEMENT_FUNDING_USER.DataValue, ''),	TRIG.[Username]),
	[Password]	= ISNULL(NULLIF(ELEMENT_FUNDING_PASSWORD.DataValue, ''),	TRIG.[Password]),
	TRIG.[XML],

	BRANCH.LenderID,
	BRANCH.LendersBranchID

FROM 
	[tblPartnerTools] TOOL WITH(NOLOCK) 
	INNER	JOIN	tblLendersBranches			BRANCH			WITH (NOLOCK) ON 1=1
	INNER JOIN [tblPartnerToolsTriggers] TRIG WITH (NOLOCK) 
		ON TRIG.PartnerToolID=TOOL.PartnerToolID AND ISNULL(TRIG.Active, 0) = 1 
	LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_URL			WITH (NOLOCK)	
		ON	TOOL.PartnerToolID	= ELEMENT_FUNDING_URL.PartnerToolID				
		AND ELEMENT_FUNDING_URL.Field			= 'POST_URL'						
		AND (ELEMENT_FUNDING_URL.LenderID		= BRANCH.LenderID
		or ELEMENT_FUNDING_URL.LendersBranchID		= BRANCH.LendersBranchID)
	LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_USER			WITH (NOLOCK)   
		ON	TOOL.PartnerToolID	= ELEMENT_FUNDING_USER.PartnerToolID			
		AND ELEMENT_FUNDING_USER.Field			= 'POST_USER'			
		AND (ELEMENT_FUNDING_USER.LenderID		= BRANCH.LenderID
		OR ELEMENT_FUNDING_USER.LendersBranchID		= BRANCH.LendersBranchID)
	LEFT JOIN tblPartnerDataElement		ELEMENT_FUNDING_PASSWORD		WITH (NOLOCK)   
		ON	TOOL.PartnerToolID	= ELEMENT_FUNDING_PASSWORD.PartnerToolID		
		AND ELEMENT_FUNDING_PASSWORD.Field		= 'POST_PASSWORD'		
		AND (ELEMENT_FUNDING_PASSWORD.LenderID	= BRANCH.LenderID 
		OR ELEMENT_FUNDING_PASSWORD.LendersBranchID		= BRANCH.LendersBranchID)
--WHERE 
--	TOOl.PartnerToolID=65 AND TRIG.Type='SEND_FUNDING_PACKET' and branch.lenderid=45 and branch.lendersbranchid=4718

 
