/****** Object:  View dbo.viewPartnersActivatedForBranch_Inner    Script Date: 7/31/2024 12:57:22 PM ******/

--SELECT TOP 10 * FROM [viewPartnersActivatedForBranch] WITH (NOLOCK)
--SELECT DISTINCT [PartnerToolID], [LendersBranchID], [PartnerToolsTriggerID] FROM [viewPartnersActivatedForBranch] WITH (NOLOCK)
--RETURN

--SELECT * FROM [tblPartnerDataElement] [PDE] WITH (NOLOCK) WHERE [PartnerToolID] = 2 AND [PDE].[Field] = 'Lender Enabled (CreditSmarts)' AND ([LenderID] = 278 OR [LendersBranchID] = 533)



CREATE VIEW [viewPartnersActivatedForBranch_Inner] AS
	SELECT
		[PartnerToolID]					= [PDE].[PartnerToolID],
		[Partner]						= LEFT([Partner].[ShortName], 30),
		[LenderID]						= [Lender].[LenderID],
		[LendersBranchID]				= ISNULL([Branch1].[LendersBranchID], [Branch2].[LendersBranchID]),
		[Lender]						= LEFT([Lender].[LenderName], 30),
		[Branch]						= LEFT(ISNULL([Branch1].[BranchName], [Branch2].[BranchName]), 30),
		[ActivatedByLenderID]			= CONVERT(BIT, CASE WHEN [Branch1].[LendersBranchID] IS NULL THEN 0 ELSE 1 END),
		[ActivatedByLendersBranchID]	= CONVERT(BIT, CASE WHEN [Branch2].[LendersBranchID] IS NULL THEN 0 ELSE 1 END),
		[PartnerToolsTriggerID]			= [PTT].[PartnerToolsTriggerID],
		[TriggerType]					= [PTT].[Type],
		[Trigger]						= [PTT].[Name]
	FROM
						[tblPartnerDataElement]		[PDE]		WITH (NOLOCK)
				JOIN	[tblPartnerTools]			[Partner]	WITH (NOLOCK) ON [Partner].[PartnerToolID]		= [PDE].[PartnerToolID]
				JOIN	[tblPartnerToolsTriggers]	[PTT]		WITH (NOLOCK) ON [PTT].[PartnerToolID] = [Partner].[PartnerToolID] AND [PTT].[Active] = 1
		LEFT	JOIN	[tblLendersBranches]		[Branch1]	WITH (NOLOCK) ON [PDE].[LenderID] > 0 AND [PDE].[LenderID] = [Branch1].[LenderID] AND [PDE].[LendersBranchID] IN (0, [Branch1].[LendersBranchID])
		LEFT	JOIN	[tblLendersBranches]		[Branch2]	WITH (NOLOCK) ON [PDE].[LendersBranchID] > 0 AND [PDE].[LendersBranchID] = [Branch2].[LendersBranchID] AND [PDE].[LenderID] IN (0, [Branch2].[LenderID])
				JOIN	[tblLenders]				[Lender]	WITH (NOLOCK) ON [Lender].[LenderID] = ISNULL([Branch1].[LenderID], [Branch2].[LenderID])
	WHERE
			[PDE].[Field] = 'Lender Enabled (CreditSmarts)'
		AND [PDE].[DataValue] = 'TRUE' 
		AND [PDE].[LoanAppID] = 0 
		AND [PDE].[LoanApp_BidID] = 0 
		AND ([PDE].[LenderID] > 0 OR [PDE].[LendersBranchID] > 0)
/*
	GROUP BY
		[PDE].[PartnerToolID], [Partner].[ShortName],
		[Lender].[LenderID], [Lender].[LenderName],
		[Branch1].[LendersBranchID], [Branch1].[BranchName],
		[Branch2].[LendersBranchID], [Branch2].[BranchName],
		[PTT].[PartnerToolsTriggerID], [PTT].[Type], [PTT].[Name]
*/

GO

