/****** Object:  View dbo.viewPartnersR1_LenderIdentification    Script Date: 7/31/2024 12:57:22 PM ******/
--DECLARE @Value VARCHAR(32), @BidID INT, @LoanID INT, @FSID VARCHAR(8); SET @BidID = 2244172; SET @LoanID = 2400449; SET @Value = 'FE00A1-1-7201810'; SET @FSID = 'F0CR70';

CREATE VIEW [dbo].[viewPartnersR1_LenderIdentification] AS
	SELECT --TOP 50
		LoanAppID											= Bid.LoanAppID,
		LoanApp_BidID									= Bid.LoanApp_BidID,
		LoanApp_BidID_Original				= Original_Bid.LoanApp_BidID_Original,
		Application_ID								= PDE_Bid.DataValue,
		LenderID 											= Lender.LenderID,
		LendersBranchID								= Bid.LendersBranchID,
		PartnerToolID 								= Partner.PartnerToolID,
		Partner												= Partner.ShortName,		
		Lender												= UPPER(Lender.LenderName + ' (' + Lender.City + ', ' + Lender.State + ')'),		
		Branch												= UPPER(Branch.BranchName + ' (' + Branch.City + ', ' + Branch.State + ')'),
		FSID							 						= PDE_Lender_ID.DataValue,		
		Dealer_ID											= NULLIF(PDE_Dealer_ID.DataValue, ''),
		Dealer_Name										= NULLIF(PDE_Dealer_Name.DataValue, '')
	FROM
								tblLenders 									Lender 					WITH (NOLOCK)
		INNER JOIN	tblLendersBranches					Branch					WITH (NOLOCK) ON	Branch.LenderID											= Lender.LenderID
		INNER JOIN	tblLoanApp_Bids							Bid							WITH (NOLOCK) ON	Bid.LendersBranchID									= Branch.LendersBranchID			AND		Bid.CreateDateTime								> DATEADD(d, -365, GETDATE())
		INNER JOIN	tblLoanApps									App							WITH (NOLOCK) ON	App.LoanAppID												= Bid.LoanAppID								AND		App.CreateDateTime								> DATEADD(d, -365, GETDATE())
		INNER JOIN	tblDealers									Dealer					WITH (NOLOCK) ON	Dealer.DealerID											= App.DealerID
		INNER JOIN	tblPartnerTools							Partner					WITH (NOLOCK) ON	Partner.ShortName										= 'ROUTEONE'
		INNER JOIN	viewB2B_OriginalPartnerBid	Original_Bid		WITH (NOLOCK) ON	Original_Bid.LoanAppID							= Bid.LoanAppID								AND		Original_Bid.LoanApp_BidID				= Bid.LoanApp_BidID						AND
																																							Original_Bid.LenderID								= Lender.LenderID							AND		Original_Bid.PartnerToolID				= Partner.PartnerToolID				AND
																																							Original_Bid.LoanApp_BidID					> 1874113
		INNER JOIN	tblPartnerDataElement 			PDE_Bid					WITH (NOLOCK) ON 	PDE_Bid.Field												= 'Application.ID'						AND		PDE_Bid.DealerID									= 0														AND
																																							PDE_Bid.PartnerToolID								= Partner.PartnerToolID				AND		PDE_Bid.LenderID									= 0														AND
																																							PDE_Bid.LoanApp_BidID								= Bid.LoanApp_BidID						AND		PDE_Bid.LendersBranchID						= 0														AND
																																							PDE_Bid.Active											= 1														AND		PDE_Bid.LoanAppID									= 0														AND
																																							PDE_Bid.PartnerDataElementID				> 11789426										AND		PDE_Bid.CreateDateTime						> App.CreateDateTime
		LEFT JOIN		tblPartnerDataElement 			PDE_App					WITH (NOLOCK) ON	PDE_App.Field												= 'Application.ID'						AND		PDE_App.DealerID									= 0														AND
																																							PDE_App.PartnerToolID								= Partner.PartnerToolID				AND		PDE_App.LenderID									= 0														AND
																																							PDE_App.LoanAppID										= Bid.LoanAppID								AND		PDE_App.LendersBranchID						= 0														AND
																																							PDE_App.Active											= 1														AND		PDE_App.LoanApp_BidID							= 0														AND
																																							PDE_App.PartnerDataElementID				> 8057358											AND		PDE_App.CreateDateTime						> App.CreateDateTime
		LEFT JOIN		tblPartnerDataElement 			PDE_Dealer_ID		WITH (NOLOCK) ON 	PDE_Dealer_ID.Field									= 'Dealer.ID'									AND		PDE_Dealer_ID.DealerID						= 0														AND
																																							PDE_Dealer_ID.PartnerToolID					= Partner.PartnerToolID				AND		PDE_Dealer_ID.LenderID						= 0														AND
																																							PDE_Dealer_ID.LoanApp_BidID					= Bid.LoanApp_BidID						AND		PDE_Dealer_ID.LoanAppID						= 0														AND
																																							PDE_Dealer_ID.Active								= 1														AND		PDE_Dealer_ID.LendersBranchID			= 0														AND
																																							PDE_Dealer_ID.PartnerDataElementID	> 2070683											AND		PDE_Dealer_ID.CreateDateTime			> Dealer.CreateDateTime
		LEFT JOIN	tblPartnerDataElement 			PDE_Dealer_Name		WITH (NOLOCK) ON 	PDE_Dealer_Name.Field									= 'Dealer.Name'							AND		PDE_Dealer_Name.DealerID					= 0														AND
																																							PDE_Dealer_Name.PartnerToolID					= Partner.PartnerToolID			AND		PDE_Dealer_Name.LenderID					= 0														AND
																																							PDE_Dealer_Name.LoanApp_BidID					= Bid.LoanApp_BidID					AND		PDE_Dealer_Name.LendersBranchID		= 0														AND
																																							PDE_Dealer_Name.Active								= 1													AND		PDE_Dealer_Name.LoanAppID					= 0														AND
																																							PDE_Dealer_Name.PartnerDataElementID	> 8057365										AND		PDE_Dealer_Name.CreateDateTime		> Dealer.CreateDateTime																									
		INNER JOIN	tblPartnerDataElement 			PDE_Lender_ID 	WITH (NOLOCK) ON 	PDE_Lender_ID.Field										= 'Lender.ID'								AND		PDE_Lender_ID.LoanAppID						= 0														AND	
																																							PDE_Lender_ID.PartnerToolID						= Partner.PartnerToolID			AND		PDE_Lender_ID.LoanApp_BidID				= 0														AND
																																							PDE_Lender_ID.LenderID 								= Lender.LenderID						AND		PDE_Lender_ID.DealerID						= 0														AND
																																							PDE_Lender_ID.Active									= 1													AND		PDE_Lender_ID.LendersBranchID			= 0														AND
																																							PDE_Lender_ID.PartnerDataElementID		> 2069130										AND		PDE_Lender_ID.CreateDateTime			> Lender.CreateDateTime
	WHERE
		Bid.CreateDateTime >= App.CreateDateTime

