/****** Object:  View dbo.viewPayFlowTransactionDetails    Script Date: 7/31/2024 12:57:22 PM ******/


CREATE VIEW dbo.viewPayFlowTransactionDetails
AS
SELECT     TOP 100 PERCENT dbo.tblPayFlowTransactions.pf_transaction_id AS TransactionID, dbo.tblPayFlowTransactions.ts_added AS [Date/Time],
                      dbo.tblPayFlowTransactions.dealerid AS [Dealer ID], dbo.tblDealers.DealerName AS [Dealer Name], dbo.tblRatePlans.rate_plan AS [Rate Plan],
                      dbo.tblPayFlowActions.pf_action AS [Action], dbo.tblPayFlowPayPeriods.pf_payperiod_short_desc AS [Pay Period],
                      dbo.tblPayFlowTransactions.amt AS Amount, dbo.tblPayFlowResultCodes.pf_respmsg AS Response,
                      dbo.tblPayFlowTransactions.profileid AS [ARB Profile ID], dbo.tblPayFlowResultCodes.pf_result AS Result,
                      dbo.tblPayFlowTransactions.pf_trxtype AS [TRX Type], dbo.tblPayFlowTransactions.pf_tender AS [Tender Type],
                      dbo.tblCreditCardTypes.credit_card_type_desc AS [Credit Card Type], dbo.tblPayFlowTransactions.acct AS [Card Number],
                      dbo.tblPayFlowTransactions.cvv2, dbo.tblPayFlowTransactions.expdate AS [Card Expiration Date],
                      dbo.tblPayFlowTransactions.profilename AS [Prolfie Name], dbo.tblPayFlowTransactions.name AS Person, CONVERT(varchar(32),
                      dbo.tblPayFlowTransactions.start, 102) AS [Start Date], dbo.tblPayFlowTransactions.term,
                      dbo.tblPayFlowTransactions.maxfailpayments AS [Max Fail Payments], dbo.tblPayFlowTransactions.pnref,
                      dbo.tblPayFlowTransactions.authcode AS [Authorization Code], dbo.tblPayFlowTransactions.cvv2match AS [CVV2 Match],
                      dbo.tblPayFlowTransactions.origid
FROM         dbo.tblDealersBankingProfiles RIGHT OUTER JOIN
                      dbo.tblDealers INNER JOIN
                      dbo.tblPayFlowTransactions ON dbo.tblDealers.DealerID = dbo.tblPayFlowTransactions.dealerid ON
                      dbo.tblDealersBankingProfiles.dealerid = dbo.tblDealers.DealerID LEFT OUTER JOIN
                      dbo.tblRatePlans RIGHT OUTER JOIN
                      dbo.tblDealersBilling ON dbo.tblRatePlans.rate_plan_cd = dbo.tblDealersBilling.rate_plan_cd ON
                      dbo.tblPayFlowTransactions.dealer_service_id = dbo.tblDealersBilling.dealer_service_id LEFT OUTER JOIN
                      dbo.tblCreditCardTypes ON dbo.tblDealersBankingProfiles.credit_card_type = dbo.tblCreditCardTypes.credit_card_type LEFT OUTER JOIN
                      dbo.tblPayFlowResultCodes ON dbo.tblPayFlowTransactions.result = dbo.tblPayFlowResultCodes.pf_result LEFT OUTER JOIN
                      dbo.tblPayFlowActions ON dbo.tblPayFlowTransactions.pf_action = dbo.tblPayFlowActions.pf_action_code LEFT OUTER JOIN
                      dbo.tblPayFlowPayPeriods ON dbo.tblPayFlowTransactions.payperiod = dbo.tblPayFlowPayPeriods.pf_payperiod
ORDER BY dbo.tblPayFlowTransactions.ts_added DESC





GO

