/****** Object:  View dbo.viewPayFlowTransactionTimeouts    Script Date: 7/31/2024 12:57:22 PM ******/


CREATE VIEW dbo.viewPayFlowTransactionTimeouts
AS
SELECT     TOP 100 PERCENT dbo.tblPayFlowTransactions.pf_transaction_id AS TransactionID, dbo.tblDealersBilling.dt_edited AS [Date/Time],
                      dbo.tblDealers.DealerID, dbo.tblDealers.DealerName AS [Dealer Name], dbo.tblRatePlans.rate_plan AS [Rate Plan],
                      dbo.tblPayFlowActions.pf_action AS [Action], dbo.tblPayFlowPayPeriods.pf_payperiod_short_desc AS [Pay Period],
                      CASE WHEN dbo.tblPayFlowTransactions.amt IS NULL
                      THEN '0.00' WHEN dbo.tblPayFlowTransactions.amt = '' THEN '0.00' ELSE dbo.tblPayFlowTransactions.amt END AS Amount,
                      dbo.tblPayFlowResultCodes.pf_respmsg AS Response, dbo.tblDealersBilling.arb_profileid AS [ARB Profile ID], dbo.tblPayFlowTransactions.pnref,
                      dbo.tblPayFlowTransactions.result
FROM         dbo.tblRatePlans RIGHT OUTER JOIN
                      dbo.tblPayFlowPayPeriods RIGHT OUTER JOIN
                      dbo.tblDealers LEFT OUTER JOIN
                      dbo.tblPayFlowTransactions ON dbo.tblDealers.DealerID = dbo.tblPayFlowTransactions.dealerid LEFT OUTER JOIN
                      dbo.tblDealersBilling ON dbo.tblDealers.DealerID = dbo.tblDealersBilling.dealerid LEFT OUTER JOIN
                      dbo.tblPayFlowResultCodes ON dbo.tblPayFlowTransactions.result = dbo.tblPayFlowResultCodes.pf_result LEFT OUTER JOIN
                      dbo.tblPayFlowActions ON dbo.tblPayFlowTransactions.pf_action = dbo.tblPayFlowActions.pf_action_code ON
                      dbo.tblPayFlowPayPeriods.pf_payperiod = dbo.tblPayFlowTransactions.payperiod ON
                      dbo.tblRatePlans.rate_plan_cd = dbo.tblDealersBilling.rate_plan_cd
WHERE     (dbo.tblDealersBilling.arb_profileid LIKE '%TIMEOUT%')





