/****** Object:  View dbo.viewPurchaseAssetTypes    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewPurchaseAssetTypes AS
	SELECT TOP 100 PERCENT
		PurchaseAssetTypeID				= AssetType.PurchaseAssetTypeID,
		PurchaseAssetTypeCategoryID		= AssetCategory.PurchaseAssetTypeCategoryID,
		Category						= AssetCategory.PurchaseAssetTypeCategory,
		PurchaseAssetType				= AssetType.PurchaseAssetType,
		CategoryCaption					= AssetCategory.Caption,
		AssetCaption					= AssetType.Caption,
		AssetDescription				= AssetType.Description,
		CategoryDescription				= AssetCategory.Description,

		IsVehicle						= AssetType.IsVehicle,
		IsMotorCar						= AssetType.IsMotorCar,
		IsMotorHome						= AssetType.IsMotorHome,
		IsMotorCycle					= AssetType.IsMotorCycle,
		IsWaterCraft					= AssetType.IsWaterCraft,
		IsPowerSport					= AssetType.IsPowerSport,
		IsTravelTrailer					= AssetType.IsTravelTrailer,
		IsOtherTrailer					= AssetType.IsOtherTrailer,
		IsConsumerGoods					= AssetType.IsConsumerGoods,
		IsHomeImprovement				= AssetType.IsHomeImprovement,

		AllowInstallment				= AssetType.AllowInstallment,
		AllowLease						= AssetType.AllowLease,
		AllowMoneyFactor				= AssetType.AllowMoneyFactor,
		AllowRent						= AssetType.AllowRent,

		TermMinimum						= AssetType.TermMinimum,
		TermMax							= AssetType.TermMax
	FROM
			 tblPurchaseAssetType 			AssetType			WITH (NOLOCK)
		JOIN tblPurchaseAssetTypeCategory	AssetCategory		WITH (NOLOCK) ON AssetCategory.PurchaseAssetTypeCategoryID		= AssetType.PurchaseAssetTypeCategoryID
	WHERE
		AssetType.Active			= 1			AND
		AssetCategory.Active		= 1
	ORDER BY
		AssetCategory.Position,
		AssetCategory.PurchaseAssetTypeCategory,
		AssetType.Position,
		AssetType.PurchaseAssetType


GO

