CREATE VIEW [dbo].[viewQueryReportingBidsDisplay_2012_06_27] AS
  SELECT
   LAB.BidUpdateDateTime,
   LAB.UpdateDateTime,
   LAB.LoanAppID,
   LAB.MESSAGING_STATUS,
   LAB.Loan_Purchase_Price,
   LAB.Loan_Total_Loan_Amount,
   LAB.FINANCING_AMOUNT,
   LAB.LoanApp_BidID,
   LAB.DealerID,
   LAB."DealerCity",
   LAB."DealerState",
   LAB."VEHICLE_MODEL",
   LAB."VEHICLE_MAKE",
   LAB."APPLICANT_NAMES",
