      ELSE REPLACE(CONVERT(VARCHAR(64), DBO.PropCase(LAB.LenderName + ' - ' + LAB.BranchName)), '.', '')
      END,
  Funded_Date = LAB.funded_date,
  GapCoverageStatus = GCI.Status
FROM
