/****** Object:  View dbo.viewQueryReportingBidsDisplay_2014_03_09    Script Date: 7/31/2024 12:57:22 PM ******/


CREATE VIEW viewQueryReportingBidsDisplay_2014_03_09 AS
	SELECT --TOP 250
		BidUpdateDateTime			= BID.UpdateDateTime,
		UpdateDateTime				= BID.UpdateDateTime,
		LoanAppID					= BID.LoanAppID,
		Messaging_Status			= ISNULL(BID.Messaging_Status, ''),

		Loan_Purchase_Price			= CASE WHEN WORKSHEET.LoanApp_BidID IS NULL	THEN APP.Loan_Purchase_Price		ELSE WORKSHEET.Loan_Purchase_Price		END,
		Loan_Total_Loan_Amount		= CASE WHEN WORKSHEET.LoanApp_BidID IS NULL	THEN APP.Loan_Total_Loan_Amount		ELSE WORKSHEET.Loan_Total_Loan_Amount	END,
		FINANCING_AMOUNT			= BID.FINANCING_AMOUNT,
		LoanApp_BidID				= BID.LoanApp_BidID,
		DealerID					= DEALER.DealerID,
		DealerCity					= DBO.PropCase(DEALER.City),
		DealerState					= DEALER.State,
	
		VEHICLE_MODEL				= DBO.PropCase(ISNULL(CASE WHEN WORKSHEET.LoanApp_BidID IS NULL	THEN APP.Vehicle_Model	ELSE WORKSHEET.Vehicle_Model END, '')),
		VEHICLE_MAKE				= DBO.PropCase(ISNULL(CASE WHEN WORKSHEET.LoanApp_BidID IS NULL	THEN APP.Vehicle_Make	ELSE WORKSHEET.Vehicle_Make END, '')),
	
		APPLICANT_NAMES				= DBO.PropCase(APP.APPLICANT_NAMES),
		LenderID					= LENDER.LenderID,
		LendersBranchID				= BRANCH.LendersBranchID,

		[Loan #]					= dbo.formatInteger(BID.LoanAppID),	
		[Offer #]					= DBO.formatInteger(BID.LoanApp_BidID),

		Lender = CASE
			WHEN LENDER.LenderName = BRANCH.BranchName THEN
				REPLACE( CONVERT(VARCHAR(64), DBO.PropCase(LENDER.LenderName)), '.', '')
			ELSE REPLACE(CONVERT(VARCHAR(64), DBO.PropCase(LENDER.LenderName + ' - ' + BRANCH.BranchName)), '.', '')
		END,

		Dealer						= DBO.PropCase(DEALER.DealerName),
	
		Application					= REPLACE(REPLACE(REPLACE(DBO.PropCase(CONVERT(VARCHAR(64), APP.APPLICANT_NAMES + ' (' + DBO.PropCase(
			CASE 
				WHEN APP.Vehicle_Make = 'Solar' AND APP.Vehicle_Model = '(Non-Automotive)' THEN 'Solar Home Improvement'
				WHEN WORKSHEET.LoanApp_BidID IS NULL THEN 
					ISNULL(NULLIF(CONVERT(VARCHAR(8), APP.VEHICLE_YEAR), '0'), '') + ' ' +  APP.VEHICLE_MAKE + ' ' + APP.VEHICLE_MODEL
				ELSE
					ISNULL(NULLIF(CONVERT(VARCHAR(8), WORKSHEET.VEHICLE_YEAR), '0'), '') + ' ' +  WORKSHEET.VEHICLE_MAKE + ' ' + WORKSHEET.VEHICLE_MODEL
		END))) + ')', 'v6', 'V6'), 'v8', 'V8'), '4runner', '4Runner'),
	

		Status						= BID.STATUS,

		BidFundingStatus			= ISNULL(FUNDING_STATUS.BidFundingStatus, ''),
		Funded_Date					= BID.funded_date,
		GapCoverageStatus			= ISNULL(GAP_COVERAGE.Status, '')
	
	FROM
							tblLoanApp_Bids					BID					WITH (NOLOCK)
					JOIN	tblLoanApps						APP					WITH (NOLOCK) ON	APP.LoanAppID					= BID.LoanAppID
					JOIN	tblDealers						DEALER				WITH (NOLOCK) ON	DEALER.DealerID					= APP.DealerID
					JOIN	tblLendersBranches				BRANCH				WITH (NOLOCK) ON	BRANCH.LendersBranchID			= BID.LendersBranchID
					JOIN	tblLenders						LENDER				WITH (NOLOCK) ON	LENDER.LenderID					= BRANCH.LenderID
	
		LEFT OUTER	JOIN	tblLoanApp_Worksheet			WORKSHEET			WITH (NOLOCK) ON	WORKSHEET.LoanApp_BidID			= BID.LoanApp_BidID			AND ISNULL(WORKSHEET.Active, 0) = 1
		LEFT OUTER	JOIN	tblGapCoverageInfo				GAP_COVERAGE		WITH (NOLOCK) ON	GAP_COVERAGE.LoanAppID			= BID.LoanAppID
		LEFT OUTER	JOIN	tblLoanApp_BidFundingStatus		FUNDING_STATUS		WITH (NOLOCK) ON	FUNDING_STATUS.LoanApp_BidID	= BID.LoanApp_BidID





GO

