/****** Object:  View dbo.viewQueryReportingSavedAppsDisplay    Script Date: 7/31/2024 12:57:22 PM ******/



CREATE  VIEW [dbo].[viewQueryReportingSavedAppsDisplay] AS
SELECT
   BidUpdateDateTime = APPS.UpdateDateTime,
   APPS.UpdateDateTime,
   LoanAppID,
   MESSAGING_STATUS = NULL,
   Loan_Purchase_Price,
   Loan_Total_Loan_Amount,
   FINANCING_AMOUNT = NULL,
   LoanApp_BidID = NULL,
   APPS.DealerID,
   "DealerCity" = Dealer.City,
   "DealerState" = Dealer.State,
   "VEHICLE_MODEL",
   "VEHICLE_MAKE",
   "APPLICANT_NAMES",
   LenderID,
   LendersBranchID = NULL,
   "Dealer"       = dbo.dealerFormatDisplayNameFromValues(dealer.DealerName, dealer.City, Dealer.State, Dealer.DealerID),
   "Application"   = CASE
      WHEN LEN(RTRIM(LTRIM(ISNULL(VEHICLE, '')))) > 0 THEN
        DBO.PropCase(CONVERT(VARCHAR(64), APPLICANT_NAMES + ' (' + VEHICLE + ')'))
      WHEN LEN(RTRIM(LTRIM(ISNULL(VEHICLE, '')))) = 0 THEN
        DBO.PropCase(CONVERT(VARCHAR(64), APPLICANT_NAMES))
      WHEN LEN(RTRIM(LTRIM(ISNULL(VEHICLE, '')))) = 0 AND LEN(ISNULL(DEALER_CREDIT_EX, '') + ISNULL(DEALER_CREDIT_TU, '') + ISNULL(DEALER_CREDIT_EQ, '')) > 0 THEN
        DBO.PropCase(CONVERT(VARCHAR(64), APPLICANT_NAMES)) + ' (Credit)'
    END,
   "Loan #"       = dbo.formatInteger(LoanAppID),
   "Status"      = 'SAVED',
   BidFundingStatus = '',
   LenderDealerID = Apps.LenderDealerID		
FROM
  VIEW_Loan_Apps APPS
    JOIN tblDealers DEALER WITH (NOLOCK) ON (APPS.DealerID=DEALER.DealerID)
WHERE
  LEN(ISNULL(APPLICANT_NAMES, '')) > 0










