--sp_ProgramFiltersAllowedForDealer 359,'CA'

--USE CREDITSMARTS

CREATE VIEW viewReport_OutstandingB2BError AS
SELECT TOP 100 PERCENT
  Dealer.DealerID,
  Dealer = CONVERT(VARCHAR(32), UPPER(DEALER.DealerName)),
  Location = CONVERT(VARCHAR(32), UPPER(Dealer.City + ', ' + Dealer.State)),
  Phone = CONVERT(VARCHAR(32), Dealer.Telephone),
  EMail = LOWER(CONVERT(VARCHAR(64), Dealer.Email)),
  Qty = COUNT(*),
  First = CONVERT(VARCHAR(12),MIN(BID.CreateDateTime)),
  Last = CONVERT(VARCHAR(12),MAX(Bid.CreateDateTime))
FROM
    tblLoanApp_Bids BID
      JOIN tblLendersBranches BRANCH ON (BID.LendersBranchID=BRANCH.LendersBranchID)
      JOIN tblLenders LENDER ON (LENDER.lenderID=BRANCH.LenderID)
      JOIN tblLoanApps APP ON (APP.LoanAppID=BID.LoanAppID)
      JOIN tblDealers DEALER ON (APP.DealerID=DEALER.DealerID)
  WHERE
    DateDiff(d, BID.CreateDateTime, GETDATE()) <10
    AND BID.STATUS IN ('B2B_ERROR')
    AND BRANCH.LenderID=64
    AND APP.DealerID NOT IN (SELECT DealerID FROM tblLenderDealerRelation LDR WHERE LDR.LenderID=LENDER.LenderID AND LEN(CustomerNumber)>0)
  GROUP BY
    Dealer.DealerName,
    Dealer.DealerID,
    Dealer.City,
    Dealer.State,
    Dealer.Telephone,
    Dealer.EMail
  ORDER BY
    Dealer.DealerName





