/****** Object:  View dbo.viewServers    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewServers AS
	SELECT TOP 100 PERCENT
		ServerID			= SERVER.ServerID,
		Server				= SERVER.Server,

		ServerAliasID		= ALIAS.ServerAliasID, 
		AliasName			= ALIAS.AliasName, 

		Caption				= SERVER.DisplayCaption, 
		IP_Address			= ALIAS.IP_Address, 
		DNS_Address			= ALIAS.DNS_Address,
		AddressType			= ALIAS.AddressType
	FROM
					tblServers		SERVER		WITH (NOLOCK)
		INNER JOIN	tblServerAlias	ALIAS		WITH (NOLOCK) ON ALIAS.ServerID = SERVER.ServerID
	ORDER BY
		SERVER.Server,
		ALIAS.AliasName




