/****** Object:  View dbo.viewSessions    Script Date: 7/31/2024 12:57:22 PM ******/

CREATE VIEW viewSessions AS
	SELECT TOP 100 PERCENT
		SurrogateSessionID		= SESSION.SurrogateSessionID,
		SessionID				= SESSION.IIS_SessionID,
		LoginDateTime			= SESSION.Login_DateTime,

		LoginWhen				= CASE
			WHEN DATEDIFF(dd, SESSION.Login_DateTime, GETDATE())  =  1			THEN 'Yesterday'
			WHEN DATEDIFF(ss, SESSION.Login_DateTime, GETDATE()) <=  1			THEN '1 Second Ago'
			WHEN DATEDIFF(ss, SESSION.Login_DateTime, GETDATE()) <  60			THEN CONVERT(VARCHAR(16), DATEDIFF(ss, SESSION.Login_DateTime, GETDATE())) + ' Seconds Ago'
			WHEN DATEDIFF(mi, SESSION.Login_DateTime, GETDATE()) <=  1			THEN '1 Minute Ago'
			WHEN DATEDIFF(mi, SESSION.Login_DateTime, GETDATE()) <  60			THEN CONVERT(VARCHAR(16), DATEDIFF(mi, SESSION.Login_DateTime, GETDATE())) + ' Minutes Ago'
			WHEN DATEDIFF(hh, SESSION.Login_DateTime, GETDATE()) <=  1			THEN '1 Hour Ago'
			WHEN DATEDIFF(hh, SESSION.Login_DateTime, GETDATE()) <= 24			THEN CONVERT(VARCHAR(16), DATEDIFF(hh, SESSION.Login_DateTime, GETDATE())) + ' Hours Ago'			
			WHEN DATEDIFF(dd, SESSION.Login_DateTime, GETDATE()) <= 24			THEN CONVERT(VARCHAR(16), DATEDIFF(ss, SESSION.Login_DateTime, GETDATE())) + ' Days Ago'
			ELSE CONVERT(VARCHAR(16), SESSION.Login_DateTime)
		END,


		LastActivity_DateTime	= SESSION.LastActivity_DateTime,

		LastActivityWhen				= CASE
			WHEN DATEDIFF(dd, SESSION.LastActivity_DateTime, GETDATE())  =  1 	THEN 'Yesterday'
			WHEN DATEDIFF(ss, SESSION.LastActivity_DateTime, GETDATE()) <=  1 	THEN '1 Second Ago'
			WHEN DATEDIFF(ss, SESSION.LastActivity_DateTime, GETDATE()) <  60	THEN CONVERT(VARCHAR(16), DATEDIFF(ss, SESSION.LastActivity_DateTime, GETDATE())) + ' Seconds Ago'
			WHEN DATEDIFF(mi, SESSION.LastActivity_DateTime, GETDATE()) <=  1 	THEN '1 Minute Ago'
			WHEN DATEDIFF(mi, SESSION.LastActivity_DateTime, GETDATE()) <  60	THEN CONVERT(VARCHAR(16), DATEDIFF(mi, SESSION.LastActivity_DateTime, GETDATE())) + ' Minutes Ago'
			WHEN DATEDIFF(hh, SESSION.LastActivity_DateTime, GETDATE()) <=  1 	THEN '1 Hour Ago'
			WHEN DATEDIFF(hh, SESSION.LastActivity_DateTime, GETDATE()) <= 24	THEN CONVERT(VARCHAR(16), DATEDIFF(hh, SESSION.LastActivity_DateTime, GETDATE())) + ' Hours Ago'			
			WHEN DATEDIFF(dd, SESSION.LastActivity_DateTime, GETDATE()) <= 24	THEN CONVERT(VARCHAR(16), DATEDIFF(ss, SESSION.LastActivity_DateTime, GETDATE())) + ' Days Ago'
			ELSE CONVERT(VARCHAR(16), SESSION.LastActivity_DateTime)
		END,


		Logout_DateTime			= CASE
			WHEN DATEDIFF(mi, SESSION.LastActivity_DateTime, GETDATE()) >= 120	THEN SESSION.LastActivity_DateTime
			ELSE SESSION.Logout_DateTime END,

		LogoutWhen				= CASE
			WHEN DATEDIFF(mi, SESSION.LastActivity_DateTime, GETDATE()) >= 120	THEN CASE
				WHEN DATEDIFF(dd, SESSION.LastActivity_DateTime, GETDATE())  =  1 	THEN 'Yesterday'
				WHEN DATEDIFF(ss, SESSION.LastActivity_DateTime, GETDATE()) <=  1 	THEN '1 Second Ago'
				WHEN DATEDIFF(ss, SESSION.LastActivity_DateTime, GETDATE()) <  60	THEN CONVERT(VARCHAR(16), DATEDIFF(ss, SESSION.LastActivity_DateTime, GETDATE())) + ' Seconds Ago'
				WHEN DATEDIFF(mi, SESSION.LastActivity_DateTime, GETDATE()) <=  1 	THEN '1 Minute Ago'
				WHEN DATEDIFF(mi, SESSION.LastActivity_DateTime, GETDATE()) <  60	THEN CONVERT(VARCHAR(16), DATEDIFF(mi, SESSION.LastActivity_DateTime, GETDATE())) + ' Minutes Ago'
				WHEN DATEDIFF(hh, SESSION.LastActivity_DateTime, GETDATE()) <=  1 	THEN '1 Hour Ago'
				WHEN DATEDIFF(hh, SESSION.LastActivity_DateTime, GETDATE()) <= 24	THEN CONVERT(VARCHAR(16), DATEDIFF(hh, SESSION.LastActivity_DateTime, GETDATE())) + ' Hours Ago'			
				WHEN DATEDIFF(dd, SESSION.LastActivity_DateTime, GETDATE()) <= 24	THEN CONVERT(VARCHAR(16), DATEDIFF(ss, SESSION.LastActivity_DateTime, GETDATE())) + ' Days Ago'
				ELSE CONVERT(VARCHAR(16), SESSION.LastActivity_DateTime) END 
			WHEN DATEDIFF(dd, SESSION.Logout_DateTime, GETDATE())  =  1 		THEN 'Yesterday'
			WHEN DATEDIFF(ss, SESSION.Logout_DateTime, GETDATE()) <=  1 		THEN '1 Second Ago'
			WHEN DATEDIFF(ss, SESSION.Logout_DateTime, GETDATE()) <  60			THEN CONVERT(VARCHAR(16), DATEDIFF(ss, SESSION.Logout_DateTime, GETDATE())) + ' Seconds Ago'
			WHEN DATEDIFF(mi, SESSION.Logout_DateTime, GETDATE()) <=  1 		THEN '1 Minute Ago'
			WHEN DATEDIFF(mi, SESSION.Logout_DateTime, GETDATE()) <  60			THEN CONVERT(VARCHAR(16), DATEDIFF(mi, SESSION.Logout_DateTime, GETDATE())) + ' Minutes Ago'
			WHEN DATEDIFF(hh, SESSION.Logout_DateTime, GETDATE()) <=  1 		THEN '1 Hour Ago'
			WHEN DATEDIFF(hh, SESSION.Logout_DateTime, GETDATE()) <= 24			THEN CONVERT(VARCHAR(16), DATEDIFF(hh, SESSION.Logout_DateTime, GETDATE())) + ' Hours Ago'			
			WHEN DATEDIFF(dd, SESSION.Logout_DateTime, GETDATE()) <= 24			THEN CONVERT(VARCHAR(16), DATEDIFF(ss, SESSION.Logout_DateTime, GETDATE())) + ' Days Ago'
			ELSE CONVERT(VARCHAR(16), SESSION.Logout_DateTime)
		END,


		IP						= SESSION.Remote_IP,
		HOST					= CASE
			WHEN SESSION.Remote_IP = 	'66.214.181.126'	THEN 'CreditSmarts'
			WHEN SESSION.Remote_IP =    '127.0.0.1'			THEN 'Loopback'
			WHEN SESSION.Remote_IP LIKE '46.20_.%.%'		THEN 'Ukraine'
			WHEN SESSION.Remote_IP LIKE '80.245.114.%'		THEN 'Ukraine'
			WHEN SESSION.Remote_IP LIKE '94.178.%.%'		THEN 'Ukraine'
			WHEN SESSION.Remote_IP LIKE '95.134.%.%'		THEN 'Ukraine'
			WHEN SESSION.Remote_IP LIKE '109.200.130.%'		THEN 'Ukraine'
			ELSE	SESSION.Remote_IP
		END,

		SESSION.Remote_IP,
		Server					= SESSION.Server,
		User_Agent				= SESSION.User_Agent,

		DealerID				= DEALER.DealerID,
		LendersBranchID			= BRANCH.LendersBranchID,
		LenderID				= LENDER.LenderID,
		AffiliateID				= AFFILIATE.AffiliateID,

		AdminLoginID			= SESSION.AdminLoginID,
		AffiliateLoginID		= SESSION.AffiliateLoginID,
		DealersLoginID			= SESSION.DealersLoginID,
		LendersBranchLoginID	= SESSION.LendersBranchLoginID,
		LendersLoginID			= SESSION.LendersLoginID,



		Type			= CASE
			WHEN ADMIN_LOGINS.AdminLoginID				IS NOT NULL		THEN 'Admin'
			WHEN DEALER_LOGINS.DealersLoginID			IS NOT NULL		THEN 'Dealer'
			WHEN BRANCH_LOGINS.LendersBranchLoginID		IS NOT NULL		THEN 'Lender Branch'
			WHEN LENDER_LOGINS.LendersLoginID			IS NOT NULL		THEN 'Lender Master'
			WHEN AFFILIATE_LOGINS.AffiliateLoginID		IS NOT NULL		THEN 'Affiliate'
			ELSE ''
		END,

		Company			= CASE
			WHEN ADMIN_LOGINS.AdminLoginID			IS NOT NULL		THEN 'CreditSmarts'
			WHEN DEALER.DealerID					IS NOT NULL		THEN DEALER.DealerName
			WHEN BRANCH.LendersBranchID				IS NOT NULL AND BRANCH.BranchName = LENDER.LenderName THEN
				BRANCH.BranchName
			WHEN BRANCH.LendersBranchID				IS NOT NULL 	THEN LENDER.LenderName + ' - ' + BRANCH.BranchName
			WHEN LENDER.LenderID					IS NOT NULL		THEN LENDER.LenderName
			WHEN AFFILIATE.AffiliateID				IS NOT NULL		THEN AFFILIATE.Name
			ELSE ''
		END,

		LoginPrefix		= CASE
			WHEN ADMIN_LOGINS.AdminLoginID				IS NOT NULL		THEN 'CSMarts_Internal'
			WHEN DEALER.LoginPrefix						IS NOT NULL		THEN DEALER.LoginPrefix
			WHEN BRANCH.LoginPrefix						IS NOT NULL		THEN BRANCH.LoginPrefix
			WHEN LENDER.LoginPrefix						IS NOT NULL		THEN LENDER.LoginPrefix
			WHEN AFFILIATE.LoginPrefix					IS NOT NULL		THEN AFFILIATE.LoginPrefix
			ELSE ''
		END,

		City		= CASE
			WHEN ADMIN_LOGINS.AdminLoginID			IS NOT NULL		THEN 'Riverside'
			WHEN DEALER.City 						IS NOT NULL		THEN DEALER.City
			WHEN BRANCH.City						IS NOT NULL		THEN BRANCH.City
			WHEN LENDER.City						IS NOT NULL		THEN LENDER.City
			WHEN AFFILIATE.City						IS NOT NULL		THEN AFFILIATE.City
			ELSE ''
		END,

		State		= CASE
			WHEN ADMIN_LOGINS.AdminLoginID			IS NOT NULL		THEN 'CA'
			WHEN DEALER.State 						IS NOT NULL		THEN DEALER.State
			WHEN BRANCH.State						IS NOT NULL		THEN BRANCH.State
			WHEN LENDER.State						IS NOT NULL		THEN LENDER.State
			WHEN AFFILIATE.State					IS NOT NULL		THEN AFFILIATE.State
			ELSE ''
		END,

		UserName		= CASE
			WHEN ADMIN_LOGINS.UserName				IS NOT NULL		THEN ADMIN_LOGINS.UserName
			WHEN DEALER_LOGINS.UserName				IS NOT NULL		THEN DEALER_LOGINS.UserName
			WHEN BRANCH_LOGINS.UserName				IS NOT NULL		THEN BRANCH_LOGINS.UserName
			WHEN LENDER_LOGINS.UserName				IS NOT NULL		THEN LENDER_LOGINS.UserName
			WHEN AFFILIATE_LOGINS.UserName			IS NOT NULL		THEN AFFILIATE_LOGINS.UserName
			ELSE ''
		END,

		FullName		= CASE
			WHEN NULLIF(ADMIN_LOGINS.FullName,		'')		IS NOT NULL		THEN ADMIN_LOGINS.FullName
			WHEN NULLIF(DEALER_LOGINS.FullName,		'')		IS NOT NULL		THEN DEALER_LOGINS.FullName
			WHEN NULLIF(BRANCH_LOGINS.FullName,		'')		IS NOT NULL		THEN BRANCH_LOGINS.FullName
			WHEN NULLIF(LENDER_LOGINS.FullName,		'')		IS NOT NULL		THEN LENDER_LOGINS.FullName
			WHEN NULLIF(AFFILIATE_LOGINS.FullName,	'')		IS NOT NULL		THEN AFFILIATE_LOGINS.FullName
			WHEN ADMIN_LOGINS.UserName						IS NOT NULL		THEN ADMIN_LOGINS.UserName
			WHEN DEALER_LOGINS.UserName						IS NOT NULL		THEN DEALER_LOGINS.UserName
			WHEN BRANCH_LOGINS.UserName						IS NOT NULL		THEN BRANCH_LOGINS.UserName
			WHEN LENDER_LOGINS.UserName						IS NOT NULL		THEN LENDER_LOGINS.UserName
			WHEN AFFILIATE_LOGINS.UserName					IS NOT NULL		THEN AFFILIATE_LOGINS.UserName
			ELSE ''
		END,

		Description		= CASE
			WHEN ADMIN_LOGINS.Description				IS NOT NULL		THEN ADMIN_LOGINS.Description
			WHEN DEALER_LOGINS.Description				IS NOT NULL		THEN DEALER_LOGINS.Description
			WHEN BRANCH_LOGINS.Description				IS NOT NULL		THEN BRANCH_LOGINS.Description
			WHEN LENDER_LOGINS.Description				IS NOT NULL		THEN LENDER_LOGINS.Description
			WHEN AFFILIATE_LOGINS.Description			IS NOT NULL		THEN AFFILIATE_LOGINS.Description
			ELSE ''
		END,

		EMail		= CASE
			WHEN DEALER_LOGINS.EMail					IS NOT NULL		THEN DEALER_LOGINS.EMail
			WHEN BRANCH_LOGINS.EMail					IS NOT NULL		THEN BRANCH_LOGINS.EMail
			WHEN LENDER_LOGINS.EMail					IS NOT NULL		THEN LENDER_LOGINS.EMail
			WHEN AFFILIATE_LOGINS.EMail					IS NOT NULL		THEN AFFILIATE_LOGINS.EMail
			ELSE ''
		END,

		Day = CASE
			WHEN 
					DATEPART(yy, SESSION.Login_DateTime) = DATEPART(yy, GETDATE())
				AND	DATEPART(mm, SESSION.Login_DateTime) = DATEPART(mm, GETDATE())
				AND DATEPART(dy, SESSION.Login_DateTime) = DATEPART(dy, GETDATE())	THEN 'Today'

			WHEN ABS(DATEDIFF(dy, SESSION.Login_DateTime, GETDATE())) <= 1			THEN 'Yesterday'
			ELSE CONVERT(VARCHAR(16), ABS(DATEDIFF(d, SESSION.Login_DateTime, GETDATE()))) + ' Days Ago'
		END,


		IsDealer				= CASE WHEN DEALER.DealerID				IS NOT NULL THEN 1 ELSE 0 END,
		IsLenderMaster			= CASE WHEN LENDER.LenderID				IS NOT NULL AND BRANCH.LendersBranchID IS NULL THEN 1 ELSE 0 END,
		IsLenderBranch			= CASE WHEN BRANCH.LendersBranchID		IS NOT NULL THEN 1 ELSE 0 END,
		IsAdmin					= CASE WHEN SESSION.AdminLoginID		IS NOT NULL THEN 1 ELSE 0 END,
		IsAffiliate				= CASE WHEN AFFILIATE.AffiliateID		IS NOT NULL THEN 1 ELSE 0 END

	FROM 
							tblSessions					SESSION				WITH (NOLOCK)	
		LEFT OUTER JOIN		tblAdminLogins				ADMIN_LOGINS		WITH (NOLOCK)	ON ADMIN_LOGINS.AdminLoginID			= SESSION.AdminLoginID
		LEFT OUTER JOIN		tblDealersLogins			DEALER_LOGINS		WITH (NOLOCK)	ON DEALER_LOGINS.DealersLoginID			= SESSION.DealersLoginID
		LEFT OUTER JOIN		tblLendersLogins			LENDER_LOGINS		WITH (NOLOCK)	ON LENDER_LOGINS.LendersLoginID			= SESSION.LendersLoginID
		LEFT OUTER JOIN		tblLendersBranchLogins		BRANCH_LOGINS		WITH (NOLOCK)	ON BRANCH_LOGINS.LendersBranchLoginID	= SESSION.LendersBranchLoginID
		LEFT OUTER JOIN		tblAffiliateLogins			AFFILIATE_LOGINS	WITH (NOLOCK)	ON AFFILIATE_LOGINS.AffiliateLoginID	= SESSION.AffiliateLoginID

		LEFT OUTER JOIN		tblDealers					DEALER				WITH (NOLOCK)	ON DEALER.DealerID						= DEALER_LOGINS.DealerID
		LEFT OUTER JOIN		tblLendersBranches			BRANCH				WITH (NOLOCK)	ON BRANCH.LendersBranchID				= BRANCH_LOGINS.LendersBranchID
		LEFT OUTER JOIN		tblLenders					LENDER				WITH (NOLOCK)	ON LENDER.LenderID						= LENDER_LOGINS.LenderID OR LENDER.LenderID = BRANCH.LenderID
		LEFT OUTER JOIN		tblAffiliates				AFFILIATE			WITH (NOLOCK)	ON AFFILIATE.AffiliateID				= AFFILIATE_LOGINS.AffiliateID

	WHERE
		Login_DateTime >= DATEADD(hh, -24, GETDATE())
		AND
			(		ADMIN_LOGINS.AdminLoginID	IS NOT NULL
				OR	DEALER.DealerID				IS NOT NULL
				OR	BRANCH.LendersBranchID		IS NOT NULL
				OR	LENDER.LenderID				IS NOT NULL
				OR	AFFILIATE.AffiliateID		IS NOT NULL)


	ORDER BY 
		Login_DateTime DESC





GO

