/****** Object:  View dbo.viewVINMatch    Script Date: 7/31/2024 12:57:22 PM ******/



CREATE VIEW viewVINMatch AS

SELECT TOP 100 PERCENT
  'Loan #'              = AUTO_LOAN_APP.LoanAppID,
  'Offer #'             = BID.LoanApp_BidID,
  Applicants            = CONVERT(VARCHAR(32), UPPER(AUTO_LOAN_APP.APPLICANT_NAMES)),
  Vehicle               = UPPER(CONVERT(VARCHAR(64),
                           CONVERT(VARCHAR(4), ISNULL(WS.VEHICLE_YEAR, AUTO_LOAN_APP.VEHICLE_YEAR)) + ' ' +
                           ISNULL(WS.VEHICLE_MAKE, AUTO_LOAN_APP.VEHICLE_MAKE) + ' ' +
                           ISNULL(WS.VEHICLE_MODEL, AUTO_LOAN_APP.VEHICLE_MODEL))),
  VIN                   = ISNULL(WS.VEHICLE_VIN, AUTO_LOAN_APP.VEHICLE_VIN),
  'Dealer #'            = AUTO_LOAN_APP.DealerID,
  Dealer                = CONVERT(VARCHAR(32), UPPER(DEALER.DealerName)),
  'Dealer Location'     =  CONVERT(VARCHAR(32), UPPER(DEALER.City + ' ' + DEALER.State)),
  'Lender #'            = LENDER_BRANCH.LenderID,
  Lender                = CONVERT(VARCHAR(32), UPPER(LENDER_BRANCH.LenderName)),
  LenderLocation        = CONVERT(VARCHAR(32), UPPER(LENDER.City + ' ' + LENDER.State)),
  Branch                = CONVERT(VARCHAR(32), UPPER(LENDER_BRANCH.BranchName)),
  BranchLocation        = CONVERT(VARCHAR(32), UPPER(LENDER_BRANCH.CITY + ' ' + LENDER_BRANCH.STATE)),
  LoanStatus			= BID.STATUS,
  BidFundingStaus		= BFS.BidFundingStatus,
  OfferDate				= BID.OFFER_DATE
FROM
  tblLoanApps AUTO_LOAN_APP WITH (NOLOCK)
    INNER JOIN        tblLoanApp_Bids BID WITH (NOLOCK)                 ON   AUTO_LOAN_APP.LoanAppID = BID.LoanAppID
    INNER JOIN        viewLenderBranches LENDER_BRANCH WITH (NOLOCK)    ON   BID.LendersBranchID = LENDER_BRANCH.LendersBranchID
    INNER JOIN        tblLenders LENDER WITH (NOLOCK)                   ON   LENDER_BRANCH.LenderID = LENDER.LenderID
    LEFT OUTER JOIN   tblDealers DEALER  WITH (NOLOCK)                  ON   AUTO_LOAN_APP.DealerID = DEALER.DealerID
    LEFT OUTER JOIN   tblLoanApp_Worksheet WS  WITH (NOLOCK)            ON  (BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)
	LEFT OUTER JOIN   tblLoanApp_BidFundingStatus BFS WITH (NOLOCK) 	ON  (BID.LoanApp_BidID = BFS.LoanApp_BidID) 

ORDER BY
  BID.LoanApp_BidID DESC,
  AUTO_LOAN_APP.LoanAppID DESC





