		ELSE ISNULL(DEALER.DealerName, '') + ' - ' + ISNULL(DEALER.City, '') + ' ' + ISNULL(DEALER.State, '')
	END,

	DealerName						= CASE
		WHEN DEALER.DealerID IN(26321, 27659, 27662) THEN 'LendingTree'
		ELSE UPPER(ISNULL(DEALER.DealerName, ''))
	END,

