	LOAN_TOTAL_LOAN_AMOUNT			= ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, ISNULL(APP.LOAN_TOTAL_LOAN_AMOUNT, 0)),
	LAST_NAME						= UPPER(ISNULL(PRIMARY_APPLICANT.LAST_NAME, '')),
	FIRST_NAME						= UPPER(ISNULL(PRIMARY_APPLICANT.FIRST_NAME, '')),
	MIDDLE_INITIAL					= UPPER(ISNULL(PRIMARY_APPLICANT.MIDDLE_INITIAL, '')),
	SUFFIX							= UPPER(ISNULL(PRIMARY_APPLICANT.SUFFIX, '')),
	SECONDARY_LAST_NAME				= UPPER(ISNULL(SECONDARY_APPLICANT.LAST_NAME, '')),
	SECONDARY_FIRST_NAME			= UPPER(ISNULL(SECONDARY_APPLICANT.FIRST_NAME, '')),
	SECONDARY_MIDDLE_INITIAL		= UPPER(ISNULL(SECONDARY_APPLICANT.MIDDLE_INITIAL, '')),
	SECONDARY_SUFFIX				= UPPER(ISNULL(SECONDARY_APPLICANT.SUFFIX, '')),
	STREET_1						= UPPER(ISNULL(PRIMARY_ADDRESS.STREET_1, '')),
	STREET_2						= UPPER(ISNULL(PRIMARY_ADDRESS.STREET_2, '')),
	CITY							= UPPER(ISNULL(PRIMARY_ADDRESS.CITY, '')),
	STATE							= UPPER(ISNULL(PRIMARY_ADDRESS.STATE, '')),
	ZIP								= ISNULL(PRIMARY_ADDRESS.ZIP, 0),
	SECONDARY_STREET_1				= UPPER(ISNULL(SECONDARY_ADDRESS.STREET_1, '')),
	SECONDARY_STREET_2				= UPPER(ISNULL(SECONDARY_ADDRESS.STREET_2, '')),
	SECONDARY_CITY					= UPPER(ISNULL(SECONDARY_ADDRESS.CITY, '')),
	SECONDARY_STATE					= UPPER(ISNULL(SECONDARY_ADDRESS.STATE, '')),
	SECONDARY_ZIP					= ISNULL(SECONDARY_ADDRESS.ZIP, 0),
	LendersBranchID					= BID.LendersBranchID,
	LenderID						= Lender.LenderID,
	CreateDateTime					= ISNULL(APP.CreateDateTime, APP.UpdateDateTime),
	UpdateDateTime					= ISNULL(APP.UpdateDateTime, APP.CreateDateTime),
--	BidCreateDateTime				= ISNULL(Bid.CreateDateTime, Bid.UpdateDateTime),
--	BidUpdateDateTime				= ISNULL(BID.UpdateDateTime, BID.CreateDateTime),

	BidCreateDateTime				= Bid.CreateDateTime,
	BidUpdateDateTime				= BID.UpdateDateTime,


	BranchName						= ISNULL(BRANCH.BranchName, LENDER.LenderName),

	BranchAddress					= CASE
		WHEN LEN(ISNULL(BRANCH.Street_1, '')) > 0 AND LEN(ISNULL(BRANCH.Street_1, '')) > 0
			THEN BRANCH.Street_1 + ' ' + BRANCH.Street_2
		WHEN LEN(ISNULL(BRANCH.Street_1, '')) > 0
			THEN BRANCH.Street_1
		WHEN LEN(ISNULL(BRANCH.Street_2, '')) > 0
			THEN BRANCH.Street_2
		ELSE
			ISNULL(Lender.Address, '')
		END,

	BranchCity						= CASE
		WHEN LEN(ISNULL(BRANCH.City, '')) > 0 THEN BRANCH.City
		WHEN LEN(ISNULL(LENDER.City, '')) > 0 THEN LENDER.City
		ELSE ''
	END,

	BranchState						= CASE
		WHEN LEN(ISNULL(BRANCH.State, '')) > 0 THEN BRANCH.State
