		WHEN 'EX'		THEN	'www.experian.com/reportaccess'
		WHEN 'EQ'		THEN	''
	END,

	--LENDER_S.* as LENDER_,



	LENDER_CreditPull.[CreditPullID] as LENDER_CreditPullID,
	LENDER_CreditPull.[GUID] as LENDER_GUID,
	LENDER_CreditPull.[Bureau] as LENDER_Bureau,
	LENDER_S.[Primary_Score] as LENDER_Primary_Score,
	LENDER_S.[Primary_CardID] as LENDER_Primary_CardID,
	LENDER_S.[Primary_Card] as LENDER_Primary_Card,
	LENDER_S.[Primary_Code_1] as LENDER_Primary_Code_1,
	LENDER_S.[Primary_Description_1] as LENDER_Primary_Description_1,
	LENDER_S.[Primary_Code_2] as LENDER_Primary_Code_2,
	LENDER_S.[Primary_Description_2] as LENDER_Primary_Description_2,
	LENDER_S.[Primary_Code_3] as LENDER_Primary_Code_3,
	LENDER_S.[Primary_Description_3] as LENDER_Primary_Description_3,
	LENDER_S.[Primary_Code_4] as LENDER_Primary_Code_4,
	LENDER_S.[Primary_Description_4] as LENDER_Primary_Description_4,
	LENDER_S.[Secondary_Score] as LENDER_Secondary_Score,
	LENDER_S.[Secondary_CardID] as LENDER_Secondary_CardID,
	LENDER_S.[Secondary_Card] as LENDER_Secondary_Card,
	LENDER_S.[Secondary_Code_1] as LENDER_Secondary_Code_1,
	LENDER_S.[Secondary_Description_1] as LENDER_Secondary_Description_1,
	LENDER_S.[Secondary_Code_2] as LENDER_Secondary_Code_2,
	LENDER_S.[Secondary_Description_2] as LENDER_Secondary_Description_2,
	LENDER_S.[Secondary_Code_3] as LENDER_Secondary_Code_3,
	LENDER_S.[Secondary_Description_3] as LENDER_Secondary_Description_3,
	LENDER_S.[Secondary_Code_4] as LENDER_Secondary_Code_4,
	LENDER_S.[Secondary_Description_4] as LENDER_Secondary_Description_4,
	--ISNULL(LENDER_CreditPull.CreateDateTime, LENDER_PendingCredit.UpdateDateTime) as LENDER_ScoreDateTime,
	ISNULL(LENDER_CreditPull.CreateDateTime, LENDER_CreditPull.UpdateDateTime)		as LENDER_ScoreDateTime,

	LENDER_Primary_Inquiry_Code					= LENDER_S.Primary_Inquiry_Code,
	LENDER_Primary_Inquiry_Description			= LENDER_S.Primary_Inquiry_Description,
	LENDER_Primary_Reject_Code					= LENDER_S.Primary_Reject_Code,
	LENDER_Primary_Reject_Description			= LENDER_S.Primary_Reject_Description,
	LENDER_Secondary_Inquiry_Code					= LENDER_S.Secondary_Inquiry_Code,
	LENDER_Secondary_Inquiry_Description			= LENDER_S.Secondary_Inquiry_Description,
	LENDER_Secondary_Reject_Code					= LENDER_S.Secondary_Reject_Code,
	LENDER_Secondary_Reject_Description			= LENDER_S.Secondary_Reject_Description,


	DEALER_CreditPull.[CreditPullID] as DEALER_CreditPullID,
	DEALER_CreditPull.[GUID] as DEALER_GUID,
	DEALER_CreditPull.[Bureau] as DEALER_Bureau,
	DEALER_S.[Primary_Score] as DEALER_Primary_Score,
	DEALER_S.[Primary_CardID] as DEALER_Primary_CardID,
	DEALER_S.[Primary_Card] as DEALER_Primary_Card,
	DEALER_S.[Primary_Code_1] as DEALER_Primary_Code_1,
	DEALER_S.[Primary_Description_1] as DEALER_Primary_Description_1,
	DEALER_S.[Primary_Code_2] as DEALER_Primary_Code_2,
	DEALER_S.[Primary_Description_2] as DEALER_Primary_Description_2,
	DEALER_S.[Primary_Code_3] as DEALER_Primary_Code_3,
	DEALER_S.[Primary_Description_3] as DEALER_Primary_Description_3,
	DEALER_S.[Primary_Code_4] as DEALER_Primary_Code_4,
	DEALER_S.[Primary_Description_4] as DEALER_Primary_Description_4,
	DEALER_S.[Secondary_Score] as DEALER_Secondary_Score,
	DEALER_S.[Secondary_CardID] as DEALER_Secondary_CardID,
	DEALER_S.[Secondary_Card] as DEALER_Secondary_Card,
	DEALER_S.[Secondary_Code_1] as DEALER_Secondary_Code_1,
	DEALER_S.[Secondary_Description_1] as DEALER_Secondary_Description_1,
	DEALER_S.[Secondary_Code_2] as DEALER_Secondary_Code_2,
	DEALER_S.[Secondary_Description_2] as DEALER_Secondary_Description_2,
	DEALER_S.[Secondary_Code_3] as DEALER_Secondary_Code_3,
	DEALER_S.[Secondary_Description_3] as DEALER_Secondary_Description_3,
	DEALER_S.[Secondary_Code_4] as DEALER_Secondary_Code_4,
	DEALER_S.[Secondary_Description_4] as DEALER_Secondary_Description_4,
	DEALER_Primary_Inquiry_Code					= DEALER_S.Primary_Inquiry_Code,
	DEALER_Primary_Inquiry_Description			= DEALER_S.Primary_Inquiry_Description,
	DEALER_Primary_Reject_Code					= DEALER_S.Primary_Reject_Code,
	DEALER_Primary_Reject_Description			= DEALER_S.Primary_Reject_Description,

	DEALER_Secondary_Inquiry_Code					= DEALER_S.Secondary_Inquiry_Code,
	DEALER_Secondary_Inquiry_Description			= DEALER_S.Secondary_Inquiry_Description,
	DEALER_Secondary_Reject_Code					= DEALER_S.Secondary_Reject_Code,
	DEALER_Secondary_Reject_Description			= DEALER_S.Secondary_Reject_Description,

	--ISNULL(DEALER_CreditPull.CreateDateTime, DEALER_PendingCredit.UpdateDateTime) as DEALER_ScoreDateTime,
	ISNULL(DEALER_CreditPull.CreateDateTime, Dealer_CreditPull.UpdateDateTime) AS Dealer_ScoreDateTime,
	--DEALER_S.* as DEALER_,

	LoanApp_BidID					= BID.LoanApp_BidID,
	LoanAppID						= BID.LoanAppID,

	Status							= BID.STATUS,
	OFFER_DATE						= ISNULL(BID.OFFER_DATE, BID.UPDATEDATETIME),
	DealerID						= DEALER.DealerID,

	Dealer							= CASE
		WHEN DEALER.DealerID IN(26321, 27659, 27662) THEN 'LendingTree'
		ELSE ISNULL(DEALER.DealerName, '') + ' - ' + ISNULL(DEALER.City, '') + ' ' + ISNULL(DEALER.State, '')
	END,

	DealerName						= CASE
		WHEN DEALER.DealerID IN(26321, 27659, 27662) THEN 'LendingTree'
		ELSE UPPER(ISNULL(DEALER.DealerName, ''))
	END,

	DealerAddress					= DEALER.Address,
	DealerLocation					= UPPER(ISNULL(DEALER.CITY, '')) + ', ' + ISNULL(DEALER.STATE, ''),
	DealerCity					= UPPER(ISNULL(DEALER.City,'')),
	DealerState					= UPPER(ISNULL(DEALER.State, '')),
	DealerZip					= UPPER(ISNULL(DEALER.Zip, '')),
	DealerPhone					= UPPER(ISNULL(DEALER.Telephone, '')),
	Reasons						= ISNULL(BID.Reasons, ''),
	LOAN_TOTAL_LOAN_AMOUNT				= ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, ISNULL(APP.LOAN_TOTAL_LOAN_AMOUNT, 0)),
	LAST_NAME					= UPPER(ISNULL(PRIMARY_APPLICANT.LAST_NAME, '')),
	FIRST_NAME					= UPPER(ISNULL(PRIMARY_APPLICANT.FIRST_NAME, '')),
	MIDDLE_INITIAL					= UPPER(ISNULL(PRIMARY_APPLICANT.MIDDLE_INITIAL, '')),
	SUFFIX							= UPPER(ISNULL(PRIMARY_APPLICANT.SUFFIX, '')),
	SECONDARY_LAST_NAME				= UPPER(ISNULL(SECONDARY_APPLICANT.LAST_NAME, '')),
	SECONDARY_FIRST_NAME			= UPPER(ISNULL(SECONDARY_APPLICANT.FIRST_NAME, '')),
	SECONDARY_MIDDLE_INITIAL		= UPPER(ISNULL(SECONDARY_APPLICANT.MIDDLE_INITIAL, '')),
	SECONDARY_SUFFIX				= UPPER(ISNULL(SECONDARY_APPLICANT.SUFFIX, '')),
	STREET_1						= UPPER(ISNULL(PRIMARY_ADDRESS.STREET_1, '')),
	STREET_2						= UPPER(ISNULL(PRIMARY_ADDRESS.STREET_2, '')),
	CITY							= UPPER(ISNULL(PRIMARY_ADDRESS.CITY, '')),
	STATE							= UPPER(ISNULL(PRIMARY_ADDRESS.STATE, '')),
	ZIP								= ISNULL(PRIMARY_ADDRESS.ZIP, 0),
	SECONDARY_STREET_1				= UPPER(ISNULL(SECONDARY_ADDRESS.STREET_1, '')),
	SECONDARY_STREET_2				= UPPER(ISNULL(SECONDARY_ADDRESS.STREET_2, '')),
	SECONDARY_CITY					= UPPER(ISNULL(SECONDARY_ADDRESS.CITY, '')),
	SECONDARY_STATE					= UPPER(ISNULL(SECONDARY_ADDRESS.STATE, '')),
	SECONDARY_ZIP					= ISNULL(SECONDARY_ADDRESS.ZIP, 0),
	LendersBranchID					= BID.LendersBranchID,
	LenderID						= Lender.LenderID,
	CreateDateTime					= ISNULL(APP.CreateDateTime, APP.UpdateDateTime),
	UpdateDateTime					= ISNULL(APP.UpdateDateTime, APP.CreateDateTime),
	BidCreateDateTime				= ISNULL(Bid.CreateDateTime, Bid.UpdateDateTime),
	BidUpdateDateTime				= ISNULL(BID.UpdateDateTime, BID.CreateDateTime),
	BranchName						= ISNULL(BRANCH.BranchName, LENDER.LenderName),

	BranchAddress					= CASE
		WHEN LEN(ISNULL(BRANCH.Street_1, '')) > 0 AND LEN(ISNULL(BRANCH.Street_1, '')) > 0
			THEN BRANCH.Street_1 + ' ' + BRANCH.Street_2
		WHEN LEN(ISNULL(BRANCH.Street_1, '')) > 0
			THEN BRANCH.Street_1
		WHEN LEN(ISNULL(BRANCH.Street_2, '')) > 0
			THEN BRANCH.Street_2
		ELSE
			ISNULL(Lender.Address, '')
		END,

	BranchCity						= CASE
		WHEN LEN(ISNULL(BRANCH.City, '')) > 0 THEN BRANCH.City
		WHEN LEN(ISNULL(LENDER.City, '')) > 0 THEN LENDER.City
		ELSE ''
	END,

	BranchState						= CASE
		WHEN LEN(ISNULL(BRANCH.State, '')) > 0 THEN BRANCH.State
		WHEN LEN(ISNULL(LENDER.State, '')) > 0 THEN LENDER.City
		ELSE ''
	END,

	BranchZip						= CASE
		WHEN LEN(ISNULL(BRANCH.Zip, '')) > 0 THEN BRANCH.Zip
		WHEN LEN(ISNULL(LENDER.Zip, '')) > 0 THEN LENDER.Zip
		ELSE ''
	END,

	BranchPhone						= ISNULL(BRANCH.Phone, ''),
	BranchFax						= ISNULL(BRANCH.Fax, ''),
	BranchContactFirstName					= ISNULL(BRANCH.ContactFirstName, ''),
	BranchContactLastName					= ISNULL(BRANCH.ContactLastName, ''),
	BranchContactPhone					= ISNULL(BRANCH.ContactPhone, ''),
	LenderName						= ISNULL(Lender.LenderName, ''),
	LenderAddress					= ISNULL(Lender.Address, ''),
	LenderCity						= ISNULL(Lender.City, ''),
	LenderState						= ISNULL(Lender.State, ''),
	LenderZip						= ISNULL(Lender.Zip, ''),
	Counter							= ISNULL(BID.Counter, 0),

BID.Lender_Credit_EX,BID.Lender_Credit_EQ,BID.Lender_Credit_TU

	FROM
					 tblLoanApp_Bids					BID						WITH (NOLOCK)
				JOIN tblLoanApps				APP						WITH (NOLOCK) ON BID.LoanAppID							= APP.LoanAppID
				JOIN tblDealers					DEALER					WITH (NOLOCK) ON DEALER.DealerID						= APP.DealerID
				JOIN tblLendersBranches			BRANCH					WITH (NOLOCK) ON BID.LendersBranchID					= BRANCH.LendersBranchID
				JOIN tblLenders					LENDER					WITH (NOLOCK) ON BRANCH.LenderID						= LENDER.LenderID
	LEFT OUTER	JOIN tblLoanApp_Applicant		PRIMARY_APPLICANT		WITH (NOLOCK) ON PRIMARY_APPLICANT.LoanAppID			= BID.LoanAppID --AND (NOT (PRIMARY_APPLICANT.[PRIMARY] IS NULL) OR PRIMARY_APPLICANT.RELATIONSHIP_TO_PRIMARY IS NULL) --AND NOT SECONDARY_APPLICANT.LoanApp_ApplicantID = PRIMARY_APPLICANT.LoanApp_ApplicantID
	LEFT OUTER	JOIN tblLoanApp_CurrAddress		PRIMARY_ADDRESS			WITH (NOLOCK) ON PRIMARY_ADDRESS.LoanApp_ApplicantID	= PRIMARY_APPLICANT.LoanApp_ApplicantID
	LEFT OUTER	JOIN tblLoanApp_Worksheet		WS						WITH (NOLOCK) ON BID.LoanApp_BidID						= WS.LoanApp_BidID AND WS.ACTIVE = 1
	LEFT OUTER	JOIN tblCreditPulls			LENDER_CreditPull		WITH (NOLOCK) ON LENDER_CreditPull.GUID							IN ( CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_EX), '')), CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_EQ), '')), CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_TU), '')) )
	LEFT OUTER	JOIN tblCreditPulls_Scores		LENDER_S				WITH (NOLOCK) ON LENDER_S.GUID							= LENDER_CreditPull.GUID
--	LEFT OUTER	JOIN tblCreditPulls			LENDER_CreditPull		WITH (NOLOCK) ON LENDER_S.GUID							= LENDER_CreditPull.GUID
--	LEFT JOIN	tblCreditPullsPending			LENDER_PendingCredit		WITH (NOLOCK)	ON LENDER_S.GUID = LENDER_PendingCredit.GUID

	LEFT JOIN tblCreditPulls	DEALER_CreditPull		WITH (NOLOCK)	ON DEALER_CreditPull.GUID IN ( CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(APP.DEALER_Credit_EX), '')), CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(APP.DEALER_Credit_EQ), '')), CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(APP.DEALER_Credit_TU), '')) )
	LEFT JOIN tblCreditPulls_Scores DEALER_S WITH (NOLOCK) ON DEALER_S.GUID = DEALER_CreditPull.GUID
--	LEFT JOIN tblCreditPulls		DEALER_CreditPull		WITH (NOLOCK)	ON DEALER_S.GUID = DEALER_CreditPull.GUID
--	LEFT JOIN	tblCreditPullsPending	DEALER_PendingCredit		WITH (NOLOCK)	ON DEALER_S.GUID = DEALER_PendingCredit.GUID


--	LEFT JOIN tblCreditPulls P WITH (NOLOCK) ON
--		S.CreditPullID = P.CreditPullID

	LEFT JOIN tblCreditScoreCard LENDER_SC WITH (NOLOCK) ON LENDER_SC.Bureau = LENDER_S.Bureau
	LEFT JOIN tblCreditScoreCard DEALER_SC WITH (NOLOCK) ON DEALER_SC.Bureau = LENDER_S.Bureau


	LEFT JOIN tblLoanApp_Applicant SECONDARY_APPLICANT WITH (NOLOCK) ON (SECONDARY_APPLICANT.LoanAppID = BID.LoanAppID AND SECONDARY_APPLICANT.LoanApp_ApplicantID > PRIMARY_APPLICANT.LoanApp_ApplicantID)
	LEFT JOIN tblLoanApp_CurrAddress SECONDARY_ADDRESS WITH (NOLOCK) ON (SECONDARY_ADDRESS.LoanApp_ApplicantID = SECONDARY_APPLICANT.LoanApp_ApplicantID)

WHERE 
	PRIMARY_APPLICANT.LoanApp_ApplicantID IN (SELECT MIN(LoanApp_ApplicantID) FROM tblLoanApp_Applicant Low_Applicant WITH (NOLOCK) WHERE Low_Applicant.LoanAppID = Bid.LoanAppID)

--AND	Bid.LoanApp_BidID = 1471692
--	(BID.Status = 'DECLINE_LENDER' OR COUNTER=1)




