/****** Object:  View dbo.view_DeclineLetters_Inner_20150106_PDF    Script Date: 7/31/2024 12:57:23 PM ******/











CREATE VIEW view_DeclineLetters_Inner_20150106_PDF AS

SELECT TOP 100 PERCENT
	PID = PRIMARY_APPLICANT.LoanApp_ApplicantID,
	SID = SECONDARY_APPLICANT.LoanApp_ApplicantID,

	SC.LowRange,
	SC.HighRange,
--	P.CreateDateTime CreditDate,

	BureauName						= CASE S.Bureau
		WHEN 'TU'		THEN	'Transunion'
		WHEN 'EX'		THEN	'Experian'
		WHEN 'EQ'		THEN	'Equifax'
	END,

	BAddress1						= CASE S.Bureau
		WHEN 'TU'		THEN	'PO Box 1000'
		WHEN 'EX'		THEN	'PO Box 2002'
		WHEN 'EQ'		THEN	'PO Box 105496'
	END,

	BAddress2						= CASE S.Bureau
		WHEN 'TU'		THEN	'Chester, PA 19022'
		WHEN 'EX'		THEN	'Allen, TX 75013'
		WHEN 'EQ'		THEN	'Atlanta, GA 30348'
	END,

	BAddress3						= CASE S.Bureau
		WHEN 'TU'		THEN	''
		WHEN 'EX'		THEN	''
		WHEN 'EQ'		THEN	''
	END,

	BPhone							= CASE S.Bureau
		WHEN 'TU'		THEN	'1-800-888-4213'
		WHEN 'EX'		THEN	'1-888-397-3742'
		WHEN 'EQ'		THEN	'1-800-685-1111'
	END,

	BURL							= CASE S.Bureau
		WHEN 'TU'		THEN	'www.transunion.com/myoptions'
		WHEN 'EX'		THEN	'www.experian.com/reportaccess'
		WHEN 'EQ'		THEN	''
	END,

	S.*,
	ISNULL(S_CreditPull.CreateDateTime, S_PendingCredit.UpdateDateTime) as ScoreDateTime,

	LoanApp_BidID					= BID.LoanApp_BidID,
	LoanAppID						= BID.LoanAppID,

	Status							= BID.STATUS,
	OFFER_DATE						= ISNULL(BID.OFFER_DATE, BID.UPDATEDATETIME),
	DealerID						= DEALER.DealerID,

	Dealer							= CASE
		WHEN DEALER.DealerID IN(26321, 27659, 27662) THEN 'LendingTree'
		ELSE ISNULL(DEALER.DealerName, '') + ' - ' + ISNULL(DEALER.City, '') + ' ' + ISNULL(DEALER.State, '')
	END,

	DealerName						= CASE
		WHEN DEALER.DealerID IN(26321, 27659, 27662) THEN 'LendingTree'
		ELSE UPPER(ISNULL(DEALER.DealerName, ''))
	END,

	DealerAddress					= DEALER.Address,
	DealerLocation					= UPPER(ISNULL(DEALER.CITY, '')) + ', ' + ISNULL(DEALER.STATE, ''),
	DealerCity						= UPPER(ISNULL(DEALER.City,'')),
	DealerState						= UPPER(ISNULL(DEALER.State, '')),
	DealerZip						= UPPER(ISNULL(DEALER.Zip, '')),
	DealerPhone						= UPPER(ISNULL(DEALER.Telephone, '')),
	Reasons							= ISNULL(BID.Reasons, ''),
	LOAN_TOTAL_LOAN_AMOUNT			= ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, ISNULL(APP.LOAN_TOTAL_LOAN_AMOUNT, 0)),
	LAST_NAME						= UPPER(ISNULL(PRIMARY_APPLICANT.LAST_NAME, '')),
	FIRST_NAME						= UPPER(ISNULL(PRIMARY_APPLICANT.FIRST_NAME, '')),
	MIDDLE_INITIAL					= UPPER(ISNULL(PRIMARY_APPLICANT.MIDDLE_INITIAL, '')),
	SUFFIX							= UPPER(ISNULL(PRIMARY_APPLICANT.SUFFIX, '')),
	SECONDARY_LAST_NAME				= UPPER(ISNULL(SECONDARY_APPLICANT.LAST_NAME, '')),
	SECONDARY_FIRST_NAME			= UPPER(ISNULL(SECONDARY_APPLICANT.FIRST_NAME, '')),
	SECONDARY_MIDDLE_INITIAL		= UPPER(ISNULL(SECONDARY_APPLICANT.MIDDLE_INITIAL, '')),
	SECONDARY_SUFFIX				= UPPER(ISNULL(SECONDARY_APPLICANT.SUFFIX, '')),
	STREET_1						= UPPER(ISNULL(PRIMARY_ADDRESS.STREET_1, '')),
	STREET_2						= UPPER(ISNULL(PRIMARY_ADDRESS.STREET_2, '')),
	CITY							= UPPER(ISNULL(PRIMARY_ADDRESS.CITY, '')),
	STATE							= UPPER(ISNULL(PRIMARY_ADDRESS.STATE, '')),
	ZIP								= ISNULL(PRIMARY_ADDRESS.ZIP, 0),
	SECONDARY_STREET_1				= UPPER(ISNULL(SECONDARY_ADDRESS.STREET_1, '')),
	SECONDARY_STREET_2				= UPPER(ISNULL(SECONDARY_ADDRESS.STREET_2, '')),
	SECONDARY_CITY					= UPPER(ISNULL(SECONDARY_ADDRESS.CITY, '')),
	SECONDARY_STATE					= UPPER(ISNULL(SECONDARY_ADDRESS.STATE, '')),
	SECONDARY_ZIP					= ISNULL(SECONDARY_ADDRESS.ZIP, 0),
	LendersBranchID					= BID.LendersBranchID,
	LenderID						= Lender.LenderID,
	CreateDateTime					= ISNULL(APP.CreateDateTime, APP.UpdateDateTime),
	UpdateDateTime					= ISNULL(APP.UpdateDateTime, APP.CreateDateTime),
/*
	BidCreateDateTime				= ISNULL(Bid.CreateDateTime, Bid.UpdateDateTime),
	BidUpdateDateTime				= ISNULL(BID.UpdateDateTime, BID.CreateDateTime),
*/
	BidCreateDateTime				= Bid.CreateDateTime, 
	BidUpdateDateTime				= BID.UpdateDateTime,
	BranchName						= ISNULL(BRANCH.BranchName, LENDER.LenderName),

	BranchAddress					= CASE
		WHEN LEN(ISNULL(BRANCH.Street_1, '')) > 0 AND LEN(ISNULL(BRANCH.Street_1, '')) > 0
			THEN BRANCH.Street_1 + ' ' + BRANCH.Street_2
		WHEN LEN(ISNULL(BRANCH.Street_1, '')) > 0
			THEN BRANCH.Street_1
		WHEN LEN(ISNULL(BRANCH.Street_2, '')) > 0
			THEN BRANCH.Street_2
		ELSE
			ISNULL(Lender.Address, '')
		END,

	BranchCity						= CASE
		WHEN LEN(ISNULL(BRANCH.City, '')) > 0 THEN BRANCH.City
		WHEN LEN(ISNULL(LENDER.City, '')) > 0 THEN LENDER.City
		ELSE ''
	END,

	BranchState						= CASE
		WHEN LEN(ISNULL(BRANCH.State, '')) > 0 THEN BRANCH.State
		WHEN LEN(ISNULL(LENDER.State, '')) > 0 THEN LENDER.City
		ELSE ''
	END,

	BranchZip						= CASE
		WHEN LEN(ISNULL(BRANCH.Zip, '')) > 0 THEN BRANCH.Zip
		WHEN LEN(ISNULL(LENDER.Zip, '')) > 0 THEN LENDER.Zip
		ELSE ''
	END,

	BranchPhone						= ISNULL(BRANCH.Phone, ''),
	BranchFax						= ISNULL(BRANCH.Fax, ''),
	BranchContactFirstName					= ISNULL(BRANCH.ContactFirstName, ''),
	BranchContactLastName					= ISNULL(BRANCH.ContactLastName, ''),
	BranchContactPhone					= ISNULL(BRANCH.ContactPhone, ''),
	LenderName						= ISNULL(Lender.LenderName, ''),
	LenderAddress					= ISNULL(Lender.Address, ''),
	LenderCity						= ISNULL(Lender.City, ''),
	LenderState						= ISNULL(Lender.State, ''),
	LenderZip						= ISNULL(Lender.Zip, ''),
	Counter							= ISNULL(BID.Counter, 0)

FROM
	tblLoanApp_Bids					BID WITH (NOLOCK)
	JOIN tblLoanApps				APP WITH (NOLOCK) ON (BID.LoanAppID = APP.LoanAppID)
	JOIN tblDealers					DEALER WITH (NOLOCK) ON (DEALER.DealerID=APP.DealerID)

	JOIN tblLoanApp_Applicant		PRIMARY_APPLICANT WITH (NOLOCK) ON (PRIMARY_APPLICANT.LoanAppID = BID.LoanAppID AND (NOT (PRIMARY_APPLICANT.[PRIMARY] IS NULL) OR PRIMARY_APPLICANT.RELATIONSHIP_TO_PRIMARY IS NULL)) --AND NOT SECONDARY_APPLICANT.LoanApp_ApplicantID = PRIMARY_APPLICANT.LoanApp_ApplicantID)
	JOIN tblLoanApp_CurrAddress		PRIMARY_ADDRESS WITH (NOLOCK) ON (PRIMARY_ADDRESS.LoanApp_ApplicantID = PRIMARY_APPLICANT.LoanApp_ApplicantID)
	JOIN tblLendersBranches			BRANCH WITH (NOLOCK) ON (BID.LendersBranchID = BRANCH.LendersBranchID)
	JOIN tblLenders					LENDER WITH (NOLOCK) ON (BRANCH.LenderID = LENDER.LenderID)

	LEFT OUTER JOIN	tblLoanApp_Worksheet WS WITH (NOLOCK)			
		ON	(BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)	

	LEFT JOIN tblCreditPulls_Scores S WITH (NOLOCK) ON
		S.GUID IN ( CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_EX), '')), CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_EQ), '')), CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_TU), '')) )
	LEFT JOIN	tblCreditPulls		S_CreditPull		WITH (NOLOCK)	ON S.GUID = S_CreditPull.GUID
	LEFT JOIN	tblCreditPullsPending	S_PendingCredit		WITH (NOLOCK)	ON S.GUID = S_PendingCredit.GUID

--	LEFT JOIN tblCreditPulls P WITH (NOLOCK) ON
--		S.CreditPullID = P.CreditPullID

	LEFT JOIN tblCreditScoreCard SC WITH (NOLOCK) ON SC.Bureau = S.Bureau

	LEFT JOIN tblLoanApp_Applicant SECONDARY_APPLICANT WITH (NOLOCK) ON (SECONDARY_APPLICANT.LoanAppID = BID.LoanAppID AND NOT SECONDARY_APPLICANT.LoanApp_ApplicantID = PRIMARY_APPLICANT.LoanApp_ApplicantID)
	LEFT JOIN tblLoanApp_CurrAddress SECONDARY_ADDRESS WITH (NOLOCK) ON (SECONDARY_ADDRESS.LoanApp_ApplicantID = SECONDARY_APPLICANT.LoanApp_ApplicantID)

--WHERE
--	(BID.Status = 'DECLINE_LENDER' OR COUNTER=1)














