/****** Object:  View dbo.view_DeclineLetters_New    Script Date: 7/31/2024 12:57:23 PM ******/




CREATE VIEW view_DeclineLetters_New AS
	SELECT
	DLI.*,
	Primary_Better = BETTER_P.Better,
	Secondary_Better = BETTER_S.Better

FROM	
	view_DeclineLetters_Inner DLI WITH (NOLOCK)
	LEFT OUTER JOIN viewCreditScoreCard BETTER_P WITH (NOLOCK) ON DLI.Bureau = BETTER_P.Bureau AND DLI.Primary_Score = BETTER_P.Score
	LEFT OUTER JOIN viewCreditScoreCard BETTER_S WITH (NOLOCK) ON DLI.Bureau = BETTER_S.Bureau AND DLI.Secondary_Score = BETTER_S.Score








