/****** Object:  View dbo.view_DeclineLetters_New_20141229    Script Date: 7/31/2024 12:57:23 PM ******/







CREATE  VIEW view_DeclineLetters_New_20141229  AS
	SELECT TOP 100 PERCENT
		DLI.*,
		LENDER_Primary_Better = LENDER_BETTER_P.Better,
		LENDER_Secondary_Better = LENDER_BETTER_S.Better,

		DEALER_Primary_Better = DEALER_BETTER_P.Better,
		DEALER_Secondary_Better = DEALER_BETTER_S.Better

	FROM
		view_DeclineLetters_Inner_20141229 DLI WITH (NOLOCK)
		LEFT OUTER JOIN viewCreditScoreCard LENDER_BETTER_P WITH (NOLOCK) ON DLI.LENDER_Bureau = LENDER_BETTER_P.Bureau AND DLI.LENDER_Primary_Score = LENDER_BETTER_P.Score
		LEFT OUTER JOIN viewCreditScoreCard LENDER_BETTER_S WITH (NOLOCK) ON DLI.LENDER_Bureau = LENDER_BETTER_S.Bureau AND DLI.LENDER_Secondary_Score = LENDER_BETTER_S.Score

		LEFT OUTER JOIN viewCreditScoreCard DEALER_BETTER_P WITH (NOLOCK) ON DLI.DEALER_Bureau = DEALER_BETTER_P.Bureau AND DLI.DEALER_Primary_Score = DEALER_BETTER_P.Score
		LEFT OUTER JOIN viewCreditScoreCard DEALER_BETTER_S WITH (NOLOCK) ON DLI.DEALER_Bureau = DEALER_BETTER_S.Bureau AND DLI.DEALER_Secondary_Score = DEALER_BETTER_S.Score









