Secondary_Better = BETTER_S.Better
FROM
	tblLoanApp_Bids					BID WITH (NOLOCK)
	JOIN tblLoanApps				APP WITH (NOLOCK) ON (BID.LoanAppID = APP.LoanAppID)
	JOIN tblDealers					DEALER WITH (NOLOCK) ON (DEALER.DealerID=APP.DealerID)

	JOIN tblLoanApp_Applicant		PRIMARY_APPLICANT WITH (NOLOCK) ON PRIMARY_APPLICANT.LoanAppID = BID.LoanAppID

	JOIN tblLoanApp_CurrAddress		PRIMARY_ADDRESS WITH (NOLOCK) ON (PRIMARY_ADDRESS.LoanApp_ApplicantID = PRIMARY_APPLICANT.LoanApp_ApplicantID)
	JOIN tblLendersBranches			BRANCH WITH (NOLOCK) ON (BID.LendersBranchID = BRANCH.LendersBranchID)
	JOIN tblLenders					LENDER WITH (NOLOCK) ON (BRANCH.LenderID = LENDER.LenderID)

	LEFT OUTER JOIN	tblLoanApp_Worksheet WS WITH (NOLOCK)			
		ON	(BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)	

	LEFT JOIN	tblCreditPulls		S_CreditPull		WITH (NOLOCK)	ON S_CreditPull.GUID IN (dbo.fn_getGUID(BID.Lender_Credit_EX), dbo.fn_getGUID(BID.Lender_Credit_EQ), dbo.fn_getGUID(BID.Lender_Credit_TU))
	LEFT JOIN tblCreditPulls_Scores S WITH (NOLOCK) ON
--		S.GUID IN ( CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_EX), '')), CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_EQ), '')), CONVERT(UNIQUEIDENTIFIER, NULLIF(LTRIM(BID.Lender_Credit_TU), '')) )
		S.GUID = S_CreditPull.GUID
	LEFT JOIN	tblCreditPullsPending	S_PendingCredit		WITH (NOLOCK)	ON S_CreditPull.GUID = S_PendingCredit.GUID
--	LEFT JOIN	tblCreditPulls		S_CreditPull		WITH (NOLOCK)	ON S.GUID = S_CreditPull.GUID
--	LEFT JOIN	tblCreditPullsPending	S_PendingCredit		WITH (NOLOCK)	ON S.GUID = S_PendingCredit.GUID

--	LEFT JOIN tblCreditPulls P WITH (NOLOCK) ON
--		S.CreditPullID = P.CreditPullID

	LEFT JOIN tblCreditScoreCard SC WITH (NOLOCK) ON SC.Bureau = S.Bureau

--	LEFT JOIN tblCreditScoreCard PRIMARY_SCORECARD WITH (NOLOCK) ON  S.Bureau = PRIMARY_SCORECARD.Bureau AND S.Primary_Score = PRIMARY_SCORECARD.Score
--	LEFT JOIN tblCreditScoreCard_BetterThan BETTER_P WITH (NOLOCK) ON PRIMARY_SCORECARD.ScoreCardID = BETTER_P.ScoreCardID

--	LEFT JOIN tblCreditScoreCard SECONDARY_SCORECARD WITH (NOLOCK) ON S.Bureau = SECONDARY_SCORECARD.Bureau AND S.Primary_Score = SECONDARY_SCORECARD.Score
--	LEFT JOIN tblCreditScoreCard_BetterThan BETTER_S WITH (NOLOCK) ON SECONDARY_SCORECARD.ScoreCardID = BETTER_S.ScoreCardID
	LEFT OUTER JOIN viewCreditScoreCard BETTER_P WITH (NOLOCK) ON S.Bureau = BETTER_P.Bureau AND S.Primary_Score = BETTER_P.Score
	LEFT OUTER JOIN viewCreditScoreCard BETTER_S WITH (NOLOCK) ON S.Bureau = BETTER_S.Bureau AND S.Secondary_Score = BETTER_S.Score


	LEFT JOIN tblLoanApp_Applicant SECONDARY_APPLICANT WITH (NOLOCK) ON (SECONDARY_APPLICANT.LoanAppID = BID.LoanAppID AND SECONDARY_APPLICANT.LoanApp_ApplicantID > PRIMARY_APPLICANT.LoanApp_ApplicantID)
	LEFT JOIN tblLoanApp_CurrAddress SECONDARY_ADDRESS WITH (NOLOCK) ON (SECONDARY_ADDRESS.LoanApp_ApplicantID = SECONDARY_APPLICANT.LoanApp_ApplicantID)
	LEFT JOIN tblLoanApp_BidFundingStatus  BID_FUNDING_STATUS WITH (NOLOCK) ON (BID_FUNDING_STATUS.LoanApp_BidID = BID.LoanApp_BidID)

WHERE
(
		BID.Status IN ('PENDING_DEALER','PENDING_LENDER','ACCEPTED','DECLINE_DEALER')
		AND BID.Funded = 0 
		AND BID.FUNDED_DATE IS NULL
		AND (
			BID_FUNDING_STATUS.BidFundingStatus IS NULL OR
			NOT BID_FUNDING_STATUS.BidFundingStatus IN ('RECEIVED','FUNDED')
		    )
		--AND DATEDIFF(day, ISNULL(Bid.CreateDateTime, Bid.UpdateDateTime), getdate()) > 30
  )


	AND PRIMARY_APPLICANT.LoanApp_ApplicantID IN (SELECT MIN(LoanApp_ApplicantID) FROM tblLoanApp_Applicant Low_Applicant WITH (NOLOCK) WHERE Low_Applicant.LoanAppID = Bid.LoanAppID)

--	AND	Bid.LoanApp_BidID = 1471692


