/****** Object:  View dbo.view_GAPCoverageContractInfo    Script Date: 7/31/2024 12:57:23 PM ******/


CREATE VIEW [dbo].[view_GAPCoverageContractInfo] AS
	
	SELECT TOP 100 PERCENT
		LoanAppID				= LA.LoanAppID,
		VehicleYear				= LA.VEHICLE_YEAR,
		VehicleMake				= LA.VEHICLE_MAKE,
		VehicleModel			= LA.VEHICLE_MODEL,
		VehicleVin				= LA.VEHICLE_VIN,
		VehicleMileage			= LA.VEHICLE_MILEAGE,
        VehicleRetailAdjusted	= LA.VEHICLE_RETAIL_ADJUSTED,
		
		
		ApplicantName			= ISNULL(LAA.FIRST_NAME, '') + ' ' + ISNULL(LAA.LAST_NAME, ''),
        ApplicantHomePhone		= CAST( ISNULL(LAA.HOME_PHONE_AREA_CODE,'') AS VARCHAR(3)) + '-'
								+ CAST( ISNULL(LAA.HOME_PHONE_PREFIX,'') AS VARCHAR(3)) + '-'
								+ CAST( ISNULL(HOME_PHONE_NUMBER,'') AS VARCHAR(4)),
        ApplicantWorkPhone		= CAST( ISNULL(AE.PHONE_AREA_CODE,'') AS VARCHAR(3)) + '-'
								+ CAST( ISNULL(AE.PHONE_PREFIX,'') AS VARCHAR(3)) + '-'
								+ CAST( ISNULL(AE.PHONE_NUMBER,'') AS VARCHAR(4)),
        ApplicantAddress		=  ISNULL(AA.STREET_1, ''),
        ApplicantCity			=  ISNULL(AA.CITY, ''),
        ApplicantState			=  ISNULL(AA.STATE, ''),
        ApplicantZIP			=  ISNULL(AA.ZIP, ''),


        DealerID				= D.DealerID,
        DealerName				= ISNULL(D.DealerName,''),
        DealerAddress			= ISNULL(D.Address,''),
        DealerCity				= ISNULL(D.City,''),
        DealerState				= ISNULL(D.State,''),
        DealerZIP				= ISNULL(D.ZIP,''),
        DealerContact			= ISNULL(D.Contact,''),
        DealerTelephone			= REPLACE(REPLACE(ISNULL(D.Telephone,''), '(' , ''),')', '-'),

        TERM					= GCI.Term,
        NEW						= CASE LA.NEW_USED WHEN 'New' THEN 'On' ELSE 'Off' END,
        USED					= CASE LA.NEW_USED WHEN 'Used' THEN 'On' ELSE 'Off' END



	FROM tblLoanApps								LA			WITH (NOLOCK)
	
		LEFT JOIN 	tblLoanApp_Applicant			LAA			WITH (NOLOCK)
				ON LA.LoanAppID = LAA.LoanAppID
				
		LEFT JOIN tblLoanApp_CurrAddress			AA			WITH (NOLOCK)
				ON LAA.LoanApp_ApplicantID = AA.LoanApp_ApplicantID

        LEFT JOIN  tblLoanApp_CurrEmployer			AE			WITH (NOLOCK)
				ON LAA.LoanApp_ApplicantID = AE.LoanApp_ApplicantID	
		
		LEFT JOIN tblDealers						D			WITH (NOLOCK)
				ON LA.DealerID = D.DealerID	
		
		LEFT JOIN tblGapCoverageInfo				GCI			WITH (NOLOCK)
				ON GCI.DealerID = D.DealerID AND GCI.LoanAppID = LA.LoanAppID
		





