        VehicleRetailAdjusted	= ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, LA.VEHICLE_RETAIL_ADJUSTED),
		
		
		ApplicantName			= LAA.FIRST_NAME + ' ' + LAA.LAST_NAME,
        ApplicantHomePhone		= CAST(LAA.HOME_PHONE_AREA_CODE AS VARCHAR(3)) + '-'
								+ CAST(LAA.HOME_PHONE_PREFIX AS VARCHAR(3)) + '-'
								+ CAST(HOME_PHONE_NUMBER AS VARCHAR(4)),
        ApplicantWorkPhone		= CAST(AE.PHONE_AREA_CODE AS VARCHAR(3)) + '-'
								+ CAST(AE.PHONE_PREFIX AS VARCHAR(3)) + '-'
								+ CAST(AE.PHONE_NUMBER AS VARCHAR(4)),
        ApplicantAddress		= AA.STREET_1,
        ApplicantCity			= AA.CITY,
        ApplicantState			= AA.STATE,
        ApplicantZIP			= AA.ZIP,


        DealerID				= D.DealerID,
        DealerName				= D.DealerName,
        DealerAddress			= D.Address,
        DealerCity				= D.City,
        DealerState				= D.State,
        DealerZIP				= D.ZIP,
        DealerContact			= D.Contact,
        DealerTelephone			= REPLACE(REPLACE(D.Telephone, '(' , ''),')', '-'),

        NEW						= CASE ISNULL(WS.NEW_USED, LA.NEW_USED) WHEN 'New' THEN 'On' ELSE 'Off' END,
        USED					= CASE ISNULL(WS.NEW_USED, LA.NEW_USED) WHEN 'Used' THEN 'On' ELSE 'Off' END



