        INNER JOIN  tblLoanApp_CurrEmployer			AE			WITH (NOLOCK)
				ON LAA.LoanApp_ApplicantID = AE.LoanApp_ApplicantID	
		
		INNER JOIN tblDealers						D			WITH (NOLOCK)
				ON LA.DealerID = D.DealerID
		




