/****** Object:  View dbo.view_LenderBranchLocations    Script Date: 7/31/2024 12:57:23 PM ******/


CREATE VIEW view_LenderBranchLocations AS
	SELECT TOP 100 PERCENT
		MASTER.LenderID,
		BRANCH.LendersBranchID,
		B_Lat																				= BRANCH_ZIP.Latitude,
		B_Lon																				= BRANCH_ZIP.Longitude,
		LenderCount																	= MASTER_COUNT.[Count],
		BRANCH_COUNT.BranchCount,
		FaxOnlyBranchCount													= ISNULL(FAX_COUNT.FaxOnlyBranchCount, 0),
		MASTER.LenderName,
		BRANCH.BranchName,
		BRANCH.CITY,
		BRANCH.STATE,
		MASTER.SUBMIT_STATUS,
		Telephone																		= BRANCH.Phone,
		BRANCH.Fax,
		BRANCH.ZIP,
		FAX_TYPE																		= ISNULL(BRANCH.FAX_TYPE, ''),
		FAX_ONLY																		= ISNULL(BRANCH.FAX_ONLY, 0),
		FAX_POLICY																	= ISNULL(MASTER.FAX_POLICY, '')

	FROM									tblLenders														MASTER								WITH (NOLOCK)
		INNER JOIN					tblLendersBranches										BRANCH								WITH (NOLOCK)				ON MASTER.LenderID 	=	BRANCH.LenderID
		INNER JOIN					view_LenderBranchCount								BRANCH_COUNT					WITH (NOLOCK)				ON MASTER.LenderID 	=	BRANCH_COUNT.LenderID
		LEFT OUTER JOIN			view_LenderFaxOnlyBranchCount					FAX_COUNT							WITH (NOLOCK)				ON MASTER.LenderID 	=	FAX_COUNT.LenderID
		LEFT OUTER JOIN			tblUniqueZips													BRANCH_ZIP						WITH (NOLOCK)				ON BRANCH.ZIP 			=	BRANCH_ZIP.ZipCode
		CROSS JOIN					view_LenderCount											MASTER_COUNT					WITH (NOLOCK)
	WHERE
		(NOT (MASTER.SUBMIT_STATUS = 'CLOSED'))
	ORDER BY
		MASTER.LenderName,
		BRANCH.BranchName





