/****** Object:  View dbo.view_LoanApp_For_HarlandFS    Script Date: 7/31/2024 12:57:23 PM ******/


CREATE VIEW view_LoanApp_For_HarlandFS AS
 SELECT distinct
	b.status,

	b.LoanAppID,
	b.LoanApp_BidID,
	u.UnderwritingID,
	w.LoanApp_WorksheetID,
	'CreditSmarts' as ApplicationSource,
	CASE
		WHEN Len(ISNULL(b.LENDER_CREDIT_TU, '')) > 0 THEN 'TRAN'
		WHEN Len(ISNULL(b.LENDER_CREDIT_EQ, '')) > 0 THEN 'EQUI'
		WHEN Len(ISNULL(b.LENDER_CREDIT_EX, '')) > 0 THEN 'EXPE'
		ELSE ''
	END AS BureauName,
	CASE
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('CAR', 'SUV', 'TRUCK') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'New' Then 'L62'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('CAR', 'SUV', 'TRUCK') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'Used' Then 'L63'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('MOTORCYCLE') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'New' Then 'L68'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('MOTORCYCLE') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'Used' Then 'L69'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('TRAILER') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'New' Then 'L56'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('TRAILER') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'Used' Then 'L57'
		WHEN
			(ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('CLASS_A', 'CLASS_B', 'CLASS_C', 'PARK') OR 
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('5TH_WHEEL', 'TENT_TRAILER', 'TOY_HAULER', 'TRAVEL_TRAILER') OR
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('TRUCK_CAMPER')) AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'New' Then 'L56'
		WHEN
			(ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('CLASS_A', 'CLASS_B', 'CLASS_C', 'PARK') OR 
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('5TH_WHEEL', 'TENT_TRAILER', 'TOY_HAULER', 'TRAVEL_TRAILER') OR
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('TRUCK_CAMPER')) AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'Used' Then 'L57'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('BOAT', 'PWC') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'New' Then 'L58'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('BOAT', 'PWC') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'Used' Then 'L59'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('ATV') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'New' Then 'L68'
		WHEN
			ISNULL(ISNULL(NULLIF(w.VEHICLE_TYPE,''), NULLIF(a.VEHICLE_TYPE,'')), 'CAR') in ('ATV') AND
			ISNULL(ISNULL(NULLIF(w.NEW_USED,''), NULLIF(a.NEW_USED,'')), 'Used') = 'Used' Then 'L69'

		ELSE 'L63'
	END as VEHICLE_TYPE,

	SecurityDescription =
	DBO.ProperCase(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Make ELSE w.Vehicle_Make END, '')) + ' ' +
	DBO.ProperCase(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Model		ELSE w.Vehicle_Model		END, '')) + ' ' +
	ISNULL(CONVERT(CHAR(4), CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Year		ELSE w.Vehicle_Year	END), '') + '    ' + 
	ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_VIN			ELSE w.Vehicle_VIN			END, ''),

	CASE ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.New_Used ELSE w.New_Used END, ''), 'Used')
		WHEN 'Used' THEN 2
		WHEN 'New' THEN 1
		ELSE 3
	END as PurposeCode,

	u.FUNDING_FINANCED_AMOUNT,
	u.FUNDING_TERM,
	'M' as Frequency,
	ISNULL(u.FUNDING_RATE, 0) as InterestRate,
	u.FUNDING_MONTHLY_PAYMENT,
	b.FUNDED_DATE,
	u.FIRST_PAY_DATE,
	CASE ISNULL(u.PREFERRED_PAYMENT,0)
		WHEN 0 THEN 1 ELSE 5
	END AS PaymentMethod,
	'LIP' as PaymentType,
	CASE
		WHEN
			ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Type ELSE w.Vehicle_Type END, ''), 'CAR') in ('CAR', 'SUV') Then 85
		WHEN
			ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Type ELSE w.Vehicle_Type END, ''), 'CAR') in ('TRUCK') Then 86
		WHEN
			ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Type ELSE w.Vehicle_Type END, ''), 'CAR') in ('MOTORCYCLE') Then 87
		WHEN
			ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Type ELSE w.Vehicle_Type END, ''), 'CAR') in ('CLASS_A', 'CLASS_B', 'CLASS_C', 'PARK', 'TRAILER') Then 89
		WHEN
			ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Type ELSE w.Vehicle_Type END, ''), 'CAR') in ('5TH_WHEEL', 'TENT_TRAILER', 'TOY_HAULER', 'TRAVEL_TRAILER') Then 88
		WHEN
			ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Type ELSE w.Vehicle_Type END, ''), 'CAR') in ('TRUCK_CAMPER') Then 90
		WHEN
			ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Type ELSE w.Vehicle_Type END, ''), 'CAR') in ('BOAT', 'PWC') Then 91
		WHEN
			ISNULL(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Type ELSE w.Vehicle_Type END, ''), 'CAR') in ('ATV') Then 93

		ELSE 85
	END as SecurityType,
	3 as ReportCode,
	CASE
		WHEN LDR.CustomerNumber IS NULL THEN '  '
		WHEN LEN(LDR.CustomerNumber) = 2 THEN LDR.CustomerNumber
		WHEN LEN(LDR.CustomerNumber) = 1 THEN LDR.CustomerNumber + ' ' ELSE '  '
	END as DealerName,
	CASE b.status
		WHEN 'DECLINE_DEALER' THEN 'D'
		WHEN 'DECLINE_LENDER' THEN 'D'
		WHEN 'ACCEPTED' THEN 'A' ELSE 'A'
	END as LoanDecision,
	SUBSTRING(ISNULL(REPLACE(REPLACE(REPLACE(cast(b.COMMENTS as nvarchar(4000)), CHAR(10), ''), CHAR(13), ''), CHAR(9), ''),''), 1, 72) as Comment1,
	SUBSTRING(ISNULL(REPLACE(REPLACE(REPLACE(cast(b.COMMENTS as nvarchar(4000)), CHAR(10), ''), CHAR(13), ''), CHAR(9), ''),''), 73, 72) as Comment2,
	SUBSTRING(ISNULL(REPLACE(REPLACE(REPLACE(cast(b.COMMENTS as nvarchar(4000)), CHAR(10), ''), CHAR(13), ''), CHAR(9), ''),''), 145, 72) as Comment3,
	SUBSTRING(ISNULL(REPLACE(REPLACE(REPLACE(cast(b.COMMENTS as nvarchar(4000)), CHAR(10), ''), CHAR(13), ''), CHAR(9), ''),''), 217, 72) as Comment4,

	DateOfLoanOfficerDecision = CASE
		WHEN b.OFFER_DATE IS NOT NULL THEN b.OFFER_DATE
		ELSE ISNULL((SELECT MAX(OFFER_DATE) FROM tblLoanApp_Bids B2 WITH (NOLOCK) WHERE B2.LoanAppID = b.LoanAppID AND B2.LendersBranchID IN (SELECT LendersBranchID FROM tblLendersBranches lb2 WITH (NOLOCK) WHERE lb2.lenderid = lb2.lenderid)), b.UpdateDateTime)
	end,

--	b.OFFER_DATE AS DateOfLoanOfficerDecision,

	Vehicle_Make		= DBO.ProperCase(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Make ELSE w.Vehicle_Make END, '')),
	Vehicle_Model		= DBO.ProperCase(ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Model		ELSE w.Vehicle_Model	END, '')),
	Vehicle_Year		= ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Year		ELSE w.Vehicle_Year			END, ''),
	Vehicle_Mileage		= ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_Mileage		ELSE w.Vehicle_Mileage		END, ''),
	Vehicle_VIN			= ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.Vehicle_VIN			ELSE w.Vehicle_VIN			END, ''),

	LOAN_LICENSE = ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.LOAN_LICENSE ELSE w.LOAN_LICENSE END, 0),
	LOAN_SALES_TAX_RATE	= ISNULL(CASE WHEN w.LoanApp_WorksheetID IS NULL THEN a.LOAN_SALES_TAX_RATE ELSE a.LOAN_SALES_TAX_RATE END, 0),
	2 as FileVersionNumber,
	'Y' as PotentialMember,
	lb.LenderID
 FROM tblLoanApp_Bids b WITH (NOLOCK)
    LEFT JOIN tblLoanApp_Worksheet w WITH (NOLOCK) ON w.LoanApp_BidID = b.LoanApp_BidID AND ISNULL(w.ACTIVE, 0) = 1
    INNER JOIN tblLoanApps a WITH (NOLOCK) ON a.LoanAppID = b.LoanAppID
	INNER JOIN tblLendersBranches lb WITH (NOLOCK) ON lb.LendersBranchID = b.LendersBranchID
	INNER JOIN viewB2B_Lender_GlobalToolStatus GTS WITH (NOLOCK) ON GTS.LenderID = lb.LenderID AND
		GTS.PartnerToolID in (select PartnerToolID from tblPartnerTools where ShortName = 'HarlandFS') AND GTS.Enabled = 1
	INNER JOIN tblLoanApp_Underwriting u WITH (NOLOCK) ON u.LoanAppID = b.LoanAppID AND u.LenderID = lb.LenderID-- AND u.UnderwritingID = u1.UnderwritingID
    INNER JOIN tblDealers d WITH (NOLOCK) ON d.DealerID = a.DealerID
	LEFT JOIN tblPartnerDataElement pde WITH (NOLOCK) ON pde.LoanAppID = a.LoanAppID AND pde.PartnerToolID in (select PartnerToolID from tblPartnerTools where ShortName = 'HarlandFS')
	LEFT JOIN tblLenderDealerRelation LDR WITH (NOLOCK) ON LDR.DealerID = a.DealerID AND LDR.LenderID = lb.LenderID
	
WHERE 
pde.PartnerDataElementID IS NULL AND
(b.funded_date is not null OR ISNULL(b.Funded, 0) = 1)
--and b.status not in ('PENDING_LENDER', 'REFERRED')









