			PATINDEX('%V8%', ISNULL(ISNULL(w.VEHICLE_DESCRIPTION, a.VEHICLE_DESCRIPTION), '')) = 0 Then 65
		WHEN
			ISNULL(ISNULL(w.VEHICLE_TYPE, a.VEHICLE_TYPE), 'CAR') in ('TRUCK', 'SUV') AND
			ISNULL(ISNULL(w.NEW_USED, a.NEW_USED), 'Used') = 'Used' AND
			PATINDEX('%V8%', ISNULL(ISNULL(w.VEHICLE_DESCRIPTION, a.VEHICLE_DESCRIPTION), '')) = 0 Then 67
		ELSE 2
	END as SecurityType,
	3 as ReportCode,
	CASE
		WHEN LDR.CustomerNumber IS NULL THEN '  '
		WHEN LEN(LDR.CustomerNumber) = 2 THEN LDR.CustomerNumber
		WHEN LEN(LDR.CustomerNumber) = 1 THEN LDR.CustomerNumber + ' ' ELSE '  '
	END as DealerName,
	CASE b.status
		WHEN 'DECLINE_DEALER' THEN 'D'
		WHEN 'DECLINE_LENDER' THEN 'D'
		WHEN 'ACCEPTED' THEN 'A' ELSE 'A'
	END as LoanDecision,
	SUBSTRING(ISNULL(REPLACE(REPLACE(REPLACE(cast(b.COMMENTS as nvarchar(4000)), CHAR(10), ''), CHAR(13), ''), CHAR(9), ''),''), 1, 72) as Comment1,
	SUBSTRING(ISNULL(REPLACE(REPLACE(REPLACE(cast(b.COMMENTS as nvarchar(4000)), CHAR(10), ''), CHAR(13), ''), CHAR(9), ''),''), 73, 72) as Comment2,
	SUBSTRING(ISNULL(REPLACE(REPLACE(REPLACE(cast(b.COMMENTS as nvarchar(4000)), CHAR(10), ''), CHAR(13), ''), CHAR(9), ''),''), 145, 72) as Comment3,
	SUBSTRING(ISNULL(REPLACE(REPLACE(REPLACE(cast(b.COMMENTS as nvarchar(4000)), CHAR(10), ''), CHAR(13), ''), CHAR(9), ''),''), 217, 72) as Comment4,
	b.OFFER_DATE AS DateOfLoanOfficerDecision,
--	ISNULL(u.VEHICLE_MAKE, a.VEHICLE_MAKE) as VEHICLE_MAKE,
--    ISNULL(u.VEHICLE_MODEL, a.VEHICLE_MODEL) as VEHICLE_MODEL,
--	ISNULL(u.VEHICLE_YEAR, a.VEHICLE_YEAR) as VEHICLE_YEAR,
	case when (len(ISNULL(u.VEHICLE_MAKE, a.VEHICLE_MAKE)) = 0) then a.VEHICLE_MAKE	end as VEHICLE_MAKE,
	case when (len(ISNULL(u.VEHICLE_MODEL, a.VEHICLE_MODEL)) = 0) then a.VEHICLE_MODEL end as VEHICLE_MODEL,
	case when (len(ISNULL(u.VEHICLE_YEAR, a.VEHICLE_YEAR)) = 0) then a.VEHICLE_YEAR	end as VEHICLE_YEAR,
	ISNULL(w.VEHICLE_MILEAGE, a.VEHICLE_MILEAGE) as VEHICLE_MILEAGE,
	ISNULL(w.LOAN_LICENSE, a.LOAN_LICENSE) as LOAN_LICENSE,
	ISNULL(w.VEHICLE_VIN, a.VEHICLE_VIN) as VEHICLE_VIN,
	ISNULL(w.LOAN_SALES_TAX_RATE, a.LOAN_SALES_TAX_RATE) as LOAN_SALES_TAX_RATE,
	2 as FileVersionNumber,
	'Y' as PotentialMember,
	lb.LenderID
 FROM tblLoanApp_Bids b WITH (NOLOCK)
    LEFT JOIN tblLoanApp_Worksheet w WITH (NOLOCK) ON w.LoanApp_BidID = b.LoanApp_BidID AND ISNULL(w.ACTIVE, 0) = 1
    INNER JOIN tblLoanApps a WITH (NOLOCK) ON a.LoanAppID = b.LoanAppID
	INNER JOIN tblLendersBranches lb WITH (NOLOCK) ON lb.LendersBranchID = b.LendersBranchID
	INNER JOIN viewB2B_Lender_GlobalToolStatus GTS WITH (NOLOCK) ON GTS.LenderID = lb.LenderID AND
		GTS.PartnerToolID in (select PartnerToolID from tblPartnerTools where ShortName = 'HarlandFS') AND GTS.Enabled = 1
	INNER JOIN tblLoanApp_Underwriting u WITH (NOLOCK) ON u.LoanAppID = b.LoanAppID AND u.LenderID = lb.LenderID-- AND u.UnderwritingID = u1.UnderwritingID
    INNER JOIN tblDealers d WITH (NOLOCK) ON d.DealerID = a.DealerID
	LEFT JOIN tblPartnerDataElement pde WITH (NOLOCK) ON pde.LoanAppID = a.LoanAppID AND pde.PartnerToolID in (select PartnerToolID from tblPartnerTools where ShortName = 'HarlandFS')
	LEFT JOIN tblLenderDealerRelation LDR WITH (NOLOCK) ON LDR.DealerID = a.DealerID AND LDR.LenderID = lb.LenderID
WHERE pde.PartnerDataElementID IS NULL AND
	ISNULL(b.Funded, 0) = 1-- and b.loanappid in (687302)








