	ISNULL(w.VEHICLE_VIN, a.VEHICLE_VIN) as SecurityDescription,
	CASE ISNULL(ISNULL(w.NEW_USED, a.NEW_USED), 'Used')
		WHEN 'Used' THEN 2
		WHEN 'New' THEN 1
		ELSE 3
