	0 Total_Dealer_Holdback,
	--1 Number_of_records_in_file
	CASE ISNULL(SECONDARY_APPLICANT.LoanApp_ApplicantID, 0)
		WHEN 0 THEN 2
		ELSE 3
	END as Number_of_records_in_file,


	CASE ISNULL(SECONDARY_APPLICANT.LoanApp_ApplicantID, 0)
		WHEN 0 THEN 0
		ELSE 1
	END as Joint,
bid.funded_date,
AUTO_LOAN_APP.createdatetime,
LENDER.LenderID,
AUTO_LOAN_APP.LoanAppID,
DEALER.State as DealerState
from 
  tblLoanApps AUTO_LOAN_APP WITH (NOLOCK)
    INNER JOIN        tblLoanApp_Bids BID WITH (NOLOCK)                  ON   AUTO_LOAN_APP.LoanAppID = BID.LoanAppID
    INNER JOIN        viewLenderBranches LENDER_BRANCH WITH (NOLOCK)     ON   BID.LendersBranchID = LENDER_BRANCH.LendersBranchID
    INNER JOIN        tblLenders LENDER WITH (NOLOCK)                    ON   LENDER_BRANCH.LenderID = LENDER.LenderID
    LEFT OUTER JOIN   tblDealers DEALER WITH (NOLOCK)                    ON   AUTO_LOAN_APP.DealerID = DEALER.DealerID
    LEFT OUTER JOIN   tblLoanApp_Worksheet WS WITH (NOLOCK)              ON  (BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)
    LEFT JOIN viewLoanAppPrimarySecondaryApplicant APPLICANT_PRIMARY_SECONDARY WITH (NOLOCK) ON (APPLICANT_PRIMARY_SECONDARY.LoanAppID = AUTO_LOAN_APP.LoanAppID) 
    LEFT JOIN view_LoanApp_Applicant PRIMARY_APPLICANT WITH (NOLOCK) ON (PRIMARY_APPLICANT.LoanApp_ApplicantID=APPLICANT_PRIMARY_SECONDARY.PrimaryApplicantID)--(PRIMARY_APPLICANT.LoanAppID=AUTO_LOAN_APP.LoanAppID AND PRIMARY_APPLICANT.[PRIMARY]=1)
    LEFT JOIN view_LoanApp_Applicant SECONDARY_APPLICANT WITH (NOLOCK) ON (SECONDARY_APPLICANT.LoanApp_ApplicantID=APPLICANT_PRIMARY_SECONDARY.SecondaryApplicantID AND NOT APPLICANT_PRIMARY_SECONDARY.SecondaryApplicantID=APPLICANT_PRIMARY_SECONDARY.PrimaryApplicantID)--(SECONDARY_APPLICANT.LoanAppID=AUTO_LOAN_APP.LoanAppID AND SECONDARY_APPLICANT.[PRIMARY]=0)

	LEFT OUTER JOIN		viewLoanPartner			t		WITH (NOLOCK) ON AUTO_LOAN_APP.LoanAppID = t.LoanAppID
	LEFT OUTER JOIN tblLenderDealerRelation		r	      WITH (NOLOCK) ON r.DealerID = DEALER.DealerID AND LENDER_BRANCH.LenderID = r.LenderID
	LEFT OUTER JOIN tblLoanApp_BidFundingStatus	bfs		  WITH (NOLOCK) ON bfs.LoanApp_BidID = BID.LoanApp_BidID
	left join tblLoanApp_Underwriting U  with (nolock) ON U.loanappid=BID.loanappid

--	INNER JOIN viewB2B_Lender_GlobalToolStatus GTS WITH (NOLOCK) ON GTS.LenderID = LENDER.LenderID AND
--		GTS.PartnerToolID in (select PartnerToolID from tblPartnerTools where ShortName = 'PEAK_FUNDING') AND GTS.Enabled = 1
	LEFT JOIN tblPartnerDataElement pde WITH (NOLOCK) ON pde.LoanAppID = AUTO_LOAN_APP.LoanAppID AND pde.PartnerToolID in (select PartnerToolID from tblPartnerTools where ShortName = 'PEAK_FUNDING')
	LEFT JOIN tblLenderDealerRelation LDR WITH (NOLOCK) ON LDR.DealerID = AUTO_LOAN_APP.DealerID AND LDR.LenderID = LENDER.LenderID


where --bid.loanapp_bidid=757413
pde.PartnerDataElementID IS NULL AND
(bid.funded_date is not null OR ISNULL(bid.Funded, 0) = 1)
and funding_financed_amount > 0 and LENDER.lenderid=278
--order by bid.loanappid desc



