                      AUTO_LOAN_APP.DEALER_CREDIT_TU, BID.LENDER_CREDIT_WANTS_EX, BID.LENDER_CREDIT_WANTS_TU, BID.LENDER_CREDIT_EQ,
                      BID.LENDER_CREDIT_TU, BID.LENDER_CREDIT_EX, BID.LENDER_CREDIT_WANTS_EQ, BID.Reasons, BID.DISCOUNT_FEE, BID.REMINDER_DATE,
