/****** Object:  View dbo.view_Search_2_test    Script Date: 7/31/2024 12:57:23 PM ******/















CREATE VIEW [dbo].[view_Search_2_test] AS
SELECT     TOP 100 PERCENT BID.RATE as brate,BID.TERM as bterm,WS.LOAN_TERM_REQUESTED as wsheet_term,AUTO_LOAN_APP.LOAN_TERM_REQUESTED as app_term, BID.PRIMARY_SCORE as bpscore,BID.SECONDARY_SCORE as bsscore,
CONVERT(int,LEFT(NULLIF(AUTO_LOAN_APP.LOAN_TERM_REQUESTED, 'NaN'), 2)) as tst_term,
AUTO_LOAN_APP.LoanAppID, BID.LoanApp_BidID, AUTO_LOAN_APP.CREDIT_GUID, BID.YIELD_TYPE, BID.COMMENTS,
                      LEFT(BID.TERM, 2) AS TERM, BID.PAYMENT, BID.MESSAGING_STATUS, BID.REBATE_PERCT, BID.ADVANCE,
                      LENDER_BRANCH.LenderID, BID.FINANCING_AMOUNT, ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT) as LOAN_TOTAL_LOAN_AMOUNT, ISNULL(WS.LOAN_PURCHASE_PRICE, AUTO_LOAN_APP.LOAN_PURCHASE_PRICE) as LOAN_PURCHASE_PRICE,
                      ISNULL(WS.LOAN_ESTIMATED_PAYMENT, AUTO_LOAN_APP.LOAN_ESTIMATED_PAYMENT) as LOAN_ESTIMATED_PAYMENT, ISNULL(WS.LOAN_DOWN_PAYMENT, AUTO_LOAN_APP.LOAN_DOWN_PAYMENT) as LOAN_DOWN_PAYMENT, AUTO_LOAN_APP.DealerID,
                      ISNULL(WS.VEHICLE_MODEL, AUTO_LOAN_APP.VEHICLE_MODEL) as VEHICLE_MODEL, ISNULL(WS.VEHICLE_MAKE, AUTO_LOAN_APP.VEHICLE_MAKE) as VEHICLE_MAKE, AUTO_LOAN_APP.APPLICANT_NAMES, ISNULL(WS.LOAN_MISC, AUTO_LOAN_APP.LOAN_MISC) as LOAN_MISC,
                      ISNULL(WS.LOAN_TAX, AUTO_LOAN_APP.LOAN_TAX) as LOAN_TAX, ISNULL(WS.LOAN_WARRANTY, AUTO_LOAN_APP.LOAN_WARRANTY) as LOAN_WARRANTY, ISNULL(WS.LOAN_LICENSE, AUTO_LOAN_APP.LOAN_LICENSE) as LOAN_LICENSE, BID.STATUS, BID.ARCHIVED,
                      DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State AS Dealer, ISNULL(WS.VEHICLE_MILEAGE, AUTO_LOAN_APP.VEHICLE_MILEAGE) as VEHICLE_MILEAGE, ISNULL(WS.VEHICLE_YEAR, AUTO_LOAN_APP.VEHICLE_YEAR) as VEHICLE_YEAR,
                      AUTO_LOAN_APP.COMMENTS AS LoanAppCOMMENTS, ISNULL(WS.VEHICLE_DESCRIPTION, AUTO_LOAN_APP.VEHICLE_DESCRIPTION) as VEHICLE_DESCRIPTION, ISNULL(LEFT(WS.LOAN_TERM_REQUESTED,2), LEFT(AUTO_LOAN_APP.LOAN_TERM_REQUESTED, 2)) AS LOAN_TERM_REQUESTED, DEALER.EMail AS DealerEMail, AUTO_LOAN_APP.rowVersion,
                      AUTO_LOAN_APP.UpdateUser, AUTO_LOAN_APP.CreateUser, AUTO_LOAN_APP.UpdateDateTime, AUTO_LOAN_APP.CreateDateTime, REPLACE(REPLACE(BID.RATE, '%', ''),'$', '') AS RATE, BID.LendersBranchID,
                      LENDER_BRANCH.LenderName + N' - ' + LENDER_BRANCH.BranchName + N' (' + LENDER_BRANCH.CITY + N', ' + LENDER_BRANCH.STATE + N')' AS Lender,
                       LENDER_BRANCH.BranchName, LENDER_BRANCH.notification_email AS lenderEmail, BID.CreateDateTime AS BidCreateDateTime,
                      BID.UpdateDateTime AS BidUpdateDateTime,
                      ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), AUTO_LOAN_APP.VEHICLE_YEAR) + ' ' + AUTO_LOAN_APP.VEHICLE_MAKE + ' ' + AUTO_LOAN_APP.VEHICLE_MODEL) AS Vehicle,
                      dbo.tblLenders.Address AS LenderAddress, dbo.tblLenders.City AS LenderCity, dbo.tblLenders.State AS LenderState, dbo.tblLenders.ZIP AS LenderZip,
                      BID.LENDER_ARCHIVED, DEALER.DealerName, BID.FUNDED, BID.Stips, ISNULL(WS.ANTICIPATED_RATE,       AUTO_LOAN_APP.ANTICIPATED_RATE) as ANTICIPATED_RATE, BID.Reason,
                      BID.LENDER_CREDIT_GUID, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EX, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EQ,
                      AUTO_LOAN_APP.DEALER_CREDIT_WANTS_TU, AUTO_LOAN_APP.DEALER_CREDIT_EX, AUTO_LOAN_APP.DEALER_CREDIT_EQ,
                      AUTO_LOAN_APP.DEALER_CREDIT_TU, BID.LENDER_CREDIT_WANTS_EX, BID.LENDER_CREDIT_WANTS_TU, BID.LENDER_CREDIT_EQ,
                      BID.LENDER_CREDIT_TU, BID.LENDER_CREDIT_EX, BID.LENDER_CREDIT_WANTS_EQ, BID.Reasons, BID.DISCOUNT_FEE, BID.REMINDER_DATE,
                      BID.AUTOMATED, BID.OFFERED_BY, BID.OFFER_DATE, BID.CANCELED_DATE, BID.FUNDED_DATE, BID.ACCEPT_DATE, BID.SUBMIT_DATE,
                      BID.SUBMIT_BY, BID.PRIMARY_SCORE AS PRIMARY_SCORE, BID.SECONDARY_SCORE AS SECONDARY_SCORE,
                      BID.ACCEPT_BY, BID.DTI AS DTI, BID.PTI AS PTI, AUTO_LOAN_APP.LenderID AS LenderDealerID,
                      dbo.viewLoanApp_Underwriting.FUNDING_FINANCED_AMOUNT, dbo.viewLoanApp_Underwriting.FUNDING_TERM,
                      dbo.viewLoanApp_Underwriting.FUNDING_RATE, dbo.viewLoanApp_Underwriting.FUNDING_FEES, dbo.viewLoanApp_Underwriting.FUNDING_REBATE,
                      dbo.viewLoanApp_Underwriting.FUNDING_RESERVE, dbo.viewLoanApp_Underwriting.FUNDING_DISCOUNT_FEE,
                      dbo.viewLoanApp_Underwriting.FUNDING_MONTHLY_PAYMENT, dbo.viewLoanApp_Underwriting.FUNDING_TOTAL_PAYMENTS,
                      dbo.tblLoanApp_Bids_Fax.STATUS AS Fax_Status, dbo.tblLoanApp_Bids_Fax.UpdateDateTime AS Fax_LastUpdate,
                      LENDER_BRANCH.FAX_TYPE AS BranchFaxType, LENDER_BRANCH.FAX_ONLY AS BranchFaxOnly,
                      dbo.viewLoanApp_Underwriting.CONTRACT_DATE, dbo.viewLoanApp_Underwriting.FIRST_PAY_DATE,
                      dbo.viewLoanApp_Underwriting.WIRE_DATE_WIRED, dbo.viewLoanApp_Underwriting.ADMIN_FEE,
                      dbo.viewLoanApp_Underwriting.WIRE_WIRED_AMOUNT, dbo.viewLoanApp_Underwriting.WIRE_BANK_NAME,
                      dbo.viewLoanApp_Underwriting.WIRE_ABA_NUM, dbo.viewLoanApp_Underwriting.WIRE_ACCOUNT_NUM,
                      dbo.viewLoanApp_Underwriting.NEW_USED, dbo.viewLoanApp_Underwriting.MEMBER_FEE, dbo.viewLoanApp_Underwriting.MISC_FEE,
                      dbo.viewLoanApp_Underwriting.WIRE_CHECK_NUM, dbo.viewLoanApp_Underwriting.YIELD_TYPE AS FUNDING_YIELD_TYPE,
                      dbo.viewLoanApp_Underwriting.FUNDING_METHOD, DEALER.City AS DealerCity, DEALER.State AS DealerState,
                      dbo.viewLoanAppPhoneNumbers.Primary_Home_Phone, dbo.viewLoanAppPhoneNumbers.Primary_Mobile_Phone,
                      dbo.viewLoanAppPhoneNumbers.Secondary_Home_Phone, dbo.viewLoanAppPhoneNumbers.DealerPhone,



--dbo.tblLoanApp_Bids_B2B.ApplicationNumber,


ApplicationNumber = ISNULL(PT.PartnerLoanIdentifier, ''),

ISNULL(BID.Counter, 0) Counter,

RelationshipName =
	CASE
		WHEN (AUTO_LOAN_APP.LenderID IS NOT NULL AND AUTO_LOAN_APP.LenderID > 0)   THEN 'Internal'
		WHEN (AUTO_LOAN_APP.LenderID IS NULL AND PT.LoanApp_BidID IS NOT NULL) THEN PT.PartnerDisplay
		ELSE 'CreditSmarts'
	END,



					  ISNULL(ll.FullName, ISNULL(lbl.FullName,'')) As LenderAgentName,
					  ISNULL(dl.UserName, '') as DealerSalesPerson,
					  ISNULL(ae.CustomerEmail, '') as CustomerEmail,
BidFundingStatus	= ISNULL(FUNDING.BidFundingStatus, ''),

APPLICANTS_INCOME.bIncome,
APPLICANTS_INCOME.bAddIncome,
APPLICANTS_INCOME.cobIncome,
APPLICANTS_INCOME.cobAddIncome,

FundedBy = CASE ISNULL(FUNDING.BidFundingStatus, '')
				WHEN 'FUNDED' THEN FUNDING.StatusUpdateUser
				ELSE ''
			END,
ProductionTime = DATEDIFF(Hour, BID.CreateDateTime, BID.OFFER_DATE),
tblLenders.LenderStatus,
PackageRecievedDate = CASE ISNULL(FUNDING.BidFundingStatus, '')
				WHEN 'RECEIVED' THEN FUNDING.StatusUpdateDateTime
				ELSE NULL
			END,




--    If SuperCLng(Filter.GetWorksheetValue("VEHICLE_RETAIL")) > 0 Then
 --     LTV_Retail_Base = (Filter.GetWorksheetValue("LOAN_TOTAL_LOAN_AMOUNT") / Filter.GetWorksheetValue("VEHICLE_RETAIL")) * 100
--    End If

--    If SuperCLng(Filter.GetWorksheetValue("VEHICLE_RETAIL_ADJUSTED")) > 0 Then
--      LTV_Retail_Adjusted = (Filter.GetWorksheetValue("LOAN_TOTAL_LOAN_AMOUNT") / Filter.GetWorksheetValue("VEHICLE_RETAIL_ADJUSTED")) * 100
--    End If

--    If SuperCLng(Filter.GetWorksheetValue("VEHICLE_WHOLESALE")) > 0 Then
--      LTV_Wholesale_Base = (Filter.GetWorksheetValue("LOAN_TOTAL_LOAN_AMOUNT") / Filter.GetWorksheetValue("VEHICLE_WHOLESALE")) * 100
--    End If

--    If SuperCLng(Filter.GetWorksheetValue("VEHICLE_WHOLESALE_ADJUSTED")) > 0 Then
--      LTV_Wholesale_Adjusted = (Filter.GetWorksheetValue("LOAN_TOTAL_LOAN_AMOUNT") / Filter.GetWorksheetValue("VEHICLE_WHOLESALE_ADJUSTED")) * 100
--    End If

Retail_Base = ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL),
Retail_Adjusted = ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED),
Wholesale_Base = ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE),
Wholesale_Adjusted = ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED)

,LTV_Retail_Base = CASE ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL)
			WHEN NULL THEN 999
			WHEN 0 THEN 999
			ELSE (ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL))*100
			END

,LTV_Retail_Adjusted = CASE ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED)
			WHEN NULL THEN 999
			WHEN 0 THEN 999
			ELSE (ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED))*100
			END

,LTV_Wholesale_Base = CASE ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE)
			WHEN NULL THEN 999
			WHEN 0 THEN 999
--			ELSE CAST((ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE))*100 AS numeric(10,2))
			ELSE (ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE))*100
			END

,LTV_Wholesale_Adjusted = CASE ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED)
			WHEN NULL THEN 999
			WHEN 0 THEN 999
--			ELSE CAST(ISNULL((ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED)*100),0) AS numeric(10,2))
ELSE ISNULL((ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED)*100),0)
			END
,ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED) as dbs,
WS.VEHICLE_WHOLESALE_ADJUSTED as cbs, 
AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED as vbs,
cast (ISNULL(NULL,0) AS numeric(10,2)) as test
--ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED)*100 as xbs
FROM         dbo.viewLoanApp_Underwriting
	RIGHT OUTER JOIN	dbo.viewLenderBranches LENDER_BRANCH
	INNER JOIN			dbo.tblLoanApp_Bids BID WITH (NOLOCK) ON LENDER_BRANCH.LendersBranchID = BID.LendersBranchID
	INNER JOIN			dbo.tblLenders WITH (NOLOCK) ON LENDER_BRANCH.LenderID = dbo.tblLenders.LenderID

	INNER JOIN			viewBidsPartnerTool	PT	WITH (NOLOCK)	ON 	PT.LoanApp_BidID = BID.LoanApp_BidID


	LEFT OUTER JOIN		dbo.tblLoanApp_Bids_B2B WITH (NOLOCK) ON BID.LoanApp_BidID = dbo.tblLoanApp_Bids_B2B.LoanApp_BidID
	LEFT OUTER JOIN		dbo.tblLoanApp_Bids_Fax WITH (NOLOCK) ON BID.LoanApp_BidID = dbo.tblLoanApp_Bids_Fax.LoanApp_BidID ON
						dbo.viewLoanApp_Underwriting.LoanApp_BidID = BID.LoanApp_BidID
    RIGHT OUTER JOIN	dbo.viewLoanAppPhoneNumbers
    INNER JOIN			dbo.tblLoanApps AUTO_LOAN_APP WITH (NOLOCK)
    INNER JOIN			dbo.tblDealers DEALER WITH (NOLOCK) ON AUTO_LOAN_APP.DealerID = DEALER.DealerID ON
						dbo.viewLoanAppPhoneNumbers.LoanAppID = AUTO_LOAN_APP.LoanAppID ON BID.LoanAppID = AUTO_LOAN_APP.LoanAppID
    LEFT OUTER JOIN		tblLenderDealerRelation		r	      WITH (NOLOCK) ON r.DealerID = DEALER.DealerID AND LENDER_BRANCH.LenderID = r.LenderID
	LEFT OUTER JOIN		tblLendersLogins		    ll		  WITH (NOLOCK) ON ll.LendersLoginID = r.LenderAgentID
	LEFT OUTER JOIN		tblLendersBranchLogins		lbl		  WITH (NOLOCK) ON lbl.LendersBranchLoginID = r.LenderBranchAgentID
	
--	LEFT OUTER JOIN     tblPartnerDataElement		de		  WITH (NOLOCK) ON AUTO_LOAN_APP.LoanAppID = de.LoanAppID
--	LEFT OUTER JOIN     tblPartnerTools				pt	      WITH (NOLOCK) ON pt.PartnerToolID = de.PartnerToolID

	LEFT OUTER JOIN tblLoanApp_Worksheet        WS        WITH (NOLOCK) ON (BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)
	LEFT OUTER JOIN tblLoanAppAssignedDealers	ad		  WITH (NOLOCK) ON ad.LoanAppID = AUTO_LOAN_APP.LoanAppID
    LEFT OUTER JOIN tblDealersLogins			dl		  WITH (NOLOCK) ON dl.DealersLoginID = ad.DealersLoginID
	LEFT OUTER JOIN viewLoanAppApplicants_Emails ae		  WITH (NOLOCK) ON ae.LoanAppID = AUTO_LOAN_APP.LoanAppID
	LEFT OUTER JOIN	viewBidsFundingStatus		FUNDING 		WITH (NOLOCK) ON FUNDING.LoanApp_BidID		= BID.LoanApp_BidID
	left outer JOIN viewApplicantsIncome APPLICANTS_INCOME WITH (NOLOCK) ON (AUTO_LOAN_APP.LoanAppID = APPLICANTS_INCOME.LoanAppID and APPLICANTS_INCOME.LoanApp_ApplicantID=(SELECT MIN(LoanApp_ApplicantID) FROM viewApplicantsIncome WHERE LoanAppID=AUTO_LOAN_APP.LoanAppID ))--(a.loanappid=l.loanappid and a.loanapp_applicantid = (select min(loanapp_applicantid) from viewapplicantsincome where loanappid=l.loanappid))
--ORDER BY BID.LoanApp_BidID DESC, AUTO_LOAN_APP.LoanAppID DESC

















