/****** Object:  View dbo.view_Search_Bid_XStatus    Script Date: 7/31/2024 12:57:23 PM ******/


CREATE VIEW dbo.view_Search_Bid_XStatus
AS
SELECT     U.*, ISNULL(R.CustomerNumber, '') AS CustomerNumber, ISNULL(R.CUSTOMER_TYPE, 'CreditSmarts') AS CUSTOMER_TYPE,
                      dbo.tblLoanApp_Bids_Fax.STATUS AS Fax_Status, dbo.tblLoanApp_Bids_Fax.UpdateDateTime AS Fax_LastUpdate,
                      dbo.tblLoanApp_Bids.PRIMARY_DTI, dbo.tblLoanApp_Bids.PRIMARY_PTI, dbo.tblLoanApp_Bids.PRIMARY_SCORE,
                      dbo.tblLoanApp_Bids.SECONDARY_DTI, dbo.tblLoanApp_Bids.SECONDARY_PTI, dbo.tblLoanApp_Bids.SECONDARY_SCORE
FROM         dbo.viewLoanApp_Underwriting U INNER JOIN
                      dbo.tblLoanApp_Bids ON U.LoanApp_BidID = dbo.tblLoanApp_Bids.LoanApp_BidID LEFT OUTER JOIN
                      dbo.tblLoanApp_Bids_Fax ON U.LoanApp_BidID = dbo.tblLoanApp_Bids_Fax.LoanApp_BidID LEFT OUTER JOIN
                      dbo.tblLenderDealerRelation R ON U.DealerID = R.DealerID AND U.LenderID = R.LenderID







