/****** Object:  View dbo.view_Telecom    Script Date: 7/31/2024 12:57:23 PM ******/

CREATE VIEW view_Telecom AS
	SELECT
		AreaCode					= EXCHANGE.AreaCode,
		Prefix						= EXCHANGE.Prefix,
		Block						= EXCHANGE.Block,
		PrefixType					= PREFIX_TYPE.PrefixType,
		Wireless					= CONVERT(BIT, CASE WHEN PREFIX_TYPE.PrefixType IN('PCS', 'W RESELLER', 'WIRELESS') THEN 1 ELSE 0 END),
		RateCenter					= ISNULL(NULLIF(RATE_CENTER.RateCenter,		''),	'Unknown'),
		CarrierIdentifier			= ISNULL(NULLIF(CARRIER.Carrier,			''),	'Unknown'),
		City						= ISNULL(LOCATION.City, 					''),
		County						= ISNULL(LOCATION.County,					''),
		State						= ISNULL(LOCATION.State,					''),
		StateName					= ISNULL(STATE.StateName,					''),
		OCN							= ISNULL(EXCHANGE.OCN,						''),
		Company						= ISNULL(NULLIF(OCN.Caption,				''),	'Unknown'),
		Company_Raw					= ISNULL(NULLIF(OCN.Company,				''),	'Unknown'),
		SwitchType					= ISNULL(NULLIF(SWITCH_TYPE.SwitchType,		''),	'Unknown'),
		ExchangeID					= EXCHANGE.ExchangeID/*,
		LocationID					= EXCHANGE.LocationID,
		RateCenterID				= EXCHANGE.RateCenterID,
		SwitchTypeID				= EXCHANGE.SwitchTypeID,
		CarrierID					= EXCHANGE.CarrierID,

		PrefixTypeID				= EXCHANGE.PrefixTypeID*/
	FROM
					telecom_Exchange		EXCHANGE		WITH (NOLOCK)
		LEFT JOIN	telecom_Location		LOCATION		WITH (NOLOCK) ON LOCATION.LocationID		= EXCHANGE.LocationID
		LEFT JOIN	telecom_RateCenter		RATE_CENTER		WITH (NOLOCK) ON RATE_CENTER.RateCenterID	= EXCHANGE.RateCenterID
		LEFT JOIN	telecom_PrefixType		PREFIX_TYPE		WITH (NOLOCK) ON PREFIX_TYPE.PrefixTypeID	= EXCHANGE.PrefixTypeID
		LEFT JOIN	telecom_Carrier			CARRIER			WITH (NOLOCK) ON CARRIER.CarrierID			= EXCHANGE.CarrierID
		LEFT JOIN	telecom_OCN				OCN				WITH (NOLOCK) ON OCN.OCN					= EXCHANGE.OCN
		LEFT JOIN	telecom_SwitchType		SWITCH_TYPE		WITH (NOLOCK) ON SWITCH_TYPE.SwitchTypeID	= EXCHANGE.SwitchTypeID
		LEFT JOIN	tblStates				STATE			WITH (NOLOCK) ON STATE.StateAbbrev			= LOCATION.State
	WHERE
		(NOT EXISTS(SELECT * FROM telecom_exchange_ignore EI WITH (NOLOCK) WHERE EI.ExchangeID = EXCHANGE.ExchangeID))

--AND EXCHANGE.AREACODE = 209 AND EXCHANGE.PREFIX = 466 --AND EXCHANGE.BLOCK=2






