                      ISNULL(WS.VEHICLE_MODEL, AUTO_LOAN_APP.VEHICLE_MODEL) as VEHICLE_MODEL, ISNULL(WS.VEHICLE_MAKE, AUTO_LOAN_APP.VEHICLE_MAKE) as VEHICLE_MAKE, AUTO_LOAN_APP.APPLICANT_NAMES, ISNULL(WS.LOAN_MISC, AUTO_LOAN_APP.LOAN_MISC) as LOAN_MISC,
                      ISNULL(WS.LOAN_TAX, AUTO_LOAN_APP.LOAN_TAX) as LOAN_TAX, ISNULL(WS.LOAN_WARRANTY, AUTO_LOAN_APP.LOAN_WARRANTY) as LOAN_WARRANTY, ISNULL(WS.LOAN_LICENSE, AUTO_LOAN_APP.LOAN_LICENSE) as LOAN_LICENSE, BID.STATUS, BID.ARCHIVED,
                      DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State AS Dealer, ISNULL(WS.VEHICLE_MILEAGE, AUTO_LOAN_APP.VEHICLE_MILEAGE) as VEHICLE_MILEAGE, ISNULL(WS.VEHICLE_YEAR, AUTO_LOAN_APP.VEHICLE_YEAR) as VEHICLE_YEAR,
                      AUTO_LOAN_APP.COMMENTS AS LoanAppCOMMENTS, ISNULL(WS.VEHICLE_DESCRIPTION, AUTO_LOAN_APP.VEHICLE_DESCRIPTION) as VEHICLE_DESCRIPTION, ISNULL(CONVERT(int,LEFT(WS.LOAN_TERM_REQUESTED,2)), CONVERT(int,LEFT(AUTO_LOAN_APP.LOAN_TERM_REQUESTED, 2))) AS LOAN_TERM_REQUESTED, DEALER.EMail AS DealerEMail, AUTO_LOAN_APP.rowVersion,
                      AUTO_LOAN_APP.UpdateUser, AUTO_LOAN_APP.CreateUser, AUTO_LOAN_APP.UpdateDateTime, AUTO_LOAN_APP.CreateDateTime, CONVERT(float, REPLACE(REPLACE(BID.RATE, '%', ''), '$', '')) AS RATE,
		     BID.LendersBranchID,
                      LENDER_BRANCH.LenderName + N' - ' + LENDER_BRANCH.BranchName + N' (' + LENDER_BRANCH.CITY + N', ' + LENDER_BRANCH.STATE + N')' AS Lender,
                       LENDER_BRANCH.BranchName, LENDER_BRANCH.notification_email AS lenderEmail, BID.CreateDateTime AS BidCreateDateTime,
                      BID.UpdateDateTime AS BidUpdateDateTime,
                      ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), AUTO_LOAN_APP.VEHICLE_YEAR) + ' ' + AUTO_LOAN_APP.VEHICLE_MAKE + ' ' + AUTO_LOAN_APP.VEHICLE_MODEL) AS Vehicle,
                      dbo.tblLenders.Address AS LenderAddress, dbo.tblLenders.City AS LenderCity, dbo.tblLenders.State AS LenderState, dbo.tblLenders.ZIP AS LenderZip,
                      BID.LENDER_ARCHIVED, DEALER.DealerName, BID.FUNDED, BID.Stips, ISNULL(WS.ANTICIPATED_RATE,       AUTO_LOAN_APP.ANTICIPATED_RATE) as ANTICIPATED_RATE, BID.Reason,
                      BID.LENDER_CREDIT_GUID, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EX, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EQ,
                      AUTO_LOAN_APP.DEALER_CREDIT_WANTS_TU, AUTO_LOAN_APP.DEALER_CREDIT_EX, AUTO_LOAN_APP.DEALER_CREDIT_EQ,
                      AUTO_LOAN_APP.DEALER_CREDIT_TU, BID.LENDER_CREDIT_WANTS_EX, BID.LENDER_CREDIT_WANTS_TU, BID.LENDER_CREDIT_EQ,
                      BID.LENDER_CREDIT_TU, BID.LENDER_CREDIT_EX, BID.LENDER_CREDIT_WANTS_EQ, BID.Reasons, BID.DISCOUNT_FEE, BID.REMINDER_DATE,
                      BID.AUTOMATED, BID.OFFERED_BY, BID.OFFER_DATE, BID.CANCELED_DATE, BID.FUNDED_DATE, BID.ACCEPT_DATE, BID.SUBMIT_DATE,
                      BID.SUBMIT_BY, CONVERT(int, BID.PRIMARY_SCORE) AS PRIMARY_SCORE, CONVERT(int, BID.SECONDARY_SCORE) AS SECONDARY_SCORE,
                      BID.ACCEPT_BY, CONVERT(int, BID.DTI) AS DTI, CONVERT(int, BID.PTI) AS PTI, AUTO_LOAN_APP.LenderID AS LenderDealerID,
                      dbo.viewLoanApp_Underwriting.FUNDING_FINANCED_AMOUNT, dbo.viewLoanApp_Underwriting.FUNDING_TERM,
                      dbo.viewLoanApp_Underwriting.FUNDING_RATE, dbo.viewLoanApp_Underwriting.FUNDING_FEES, dbo.viewLoanApp_Underwriting.FUNDING_REBATE,
                      dbo.viewLoanApp_Underwriting.FUNDING_RESERVE, dbo.viewLoanApp_Underwriting.FUNDING_DISCOUNT_FEE,
                      dbo.viewLoanApp_Underwriting.FUNDING_MONTHLY_PAYMENT, dbo.viewLoanApp_Underwriting.FUNDING_TOTAL_PAYMENTS,
                      dbo.tblLoanApp_Bids_Fax.STATUS AS Fax_Status, dbo.tblLoanApp_Bids_Fax.UpdateDateTime AS Fax_LastUpdate,
                      LENDER_BRANCH.FAX_TYPE AS BranchFaxType, LENDER_BRANCH.FAX_ONLY AS BranchFaxOnly,
                      dbo.viewLoanApp_Underwriting.CONTRACT_DATE, dbo.viewLoanApp_Underwriting.FIRST_PAY_DATE,
                      dbo.viewLoanApp_Underwriting.WIRE_DATE_WIRED, dbo.viewLoanApp_Underwriting.ADMIN_FEE,
                      dbo.viewLoanApp_Underwriting.WIRE_WIRED_AMOUNT, dbo.viewLoanApp_Underwriting.WIRE_BANK_NAME,
                      dbo.viewLoanApp_Underwriting.WIRE_ABA_NUM, dbo.viewLoanApp_Underwriting.WIRE_ACCOUNT_NUM,
                      dbo.viewLoanApp_Underwriting.NEW_USED, dbo.viewLoanApp_Underwriting.MEMBER_FEE, dbo.viewLoanApp_Underwriting.MISC_FEE,
                      dbo.viewLoanApp_Underwriting.WIRE_CHECK_NUM, dbo.viewLoanApp_Underwriting.YIELD_TYPE AS FUNDING_YIELD_TYPE,
                      dbo.viewLoanApp_Underwriting.FUNDING_METHOD, DEALER.City AS DealerCity, DEALER.State AS DealerState,
                      dbo.viewLoanAppPhoneNumbers.Primary_Home_Phone, dbo.viewLoanAppPhoneNumbers.Primary_Mobile_Phone,
                      dbo.viewLoanAppPhoneNumbers.Secondary_Home_Phone, dbo.viewLoanAppPhoneNumbers.DealerPhone,
                      dbo.tblLoanApp_Bids_B2B.ApplicationNumber, ISNULL(BID.Counter, 0) Counter,
                      CASE WHEN (AUTO_LOAN_APP.LenderID IS NOT NULL AND AUTO_LOAN_APP.LenderID > 0)   THEN 'Internal'
						WHEN (AUTO_LOAN_APP.LenderID IS NULL AND de.PartnerDataElementID IS NOT NULL) THEN pt.ShortName ELSE 'CreditSmarts'
					  END AS RelationshipName,
					  ISNULL(ll.FullName, ISNULL(lbl.FullName,'')) As LenderAgentName
FROM         dbo.viewLoanApp_Underwriting WITH (NOLOCK)
	RIGHT OUTER JOIN	dbo.viewLenderBranches  LENDER_BRANCH WITH (NOLOCK)
	INNER JOIN			dbo.tblLoanApp_Bids BID  WITH (NOLOCK)  ON LENDER_BRANCH.LendersBranchID = BID.LendersBranchID
	INNER JOIN			dbo.tblLenders  WITH (NOLOCK)  ON LENDER_BRANCH.LenderID = dbo.tblLenders.LenderID
	LEFT OUTER JOIN		dbo.tblLoanApp_Bids_B2B  WITH (NOLOCK)  ON BID.LoanApp_BidID = dbo.tblLoanApp_Bids_B2B.LoanApp_BidID
	LEFT OUTER JOIN		dbo.tblLoanApp_Bids_Fax  WITH (NOLOCK)  ON BID.LoanApp_BidID = dbo.tblLoanApp_Bids_Fax.LoanApp_BidID ON
						dbo.viewLoanApp_Underwriting.LoanApp_BidID = BID.LoanApp_BidID
    RIGHT OUTER JOIN	dbo.viewLoanAppPhoneNumbers WITH (NOLOCK)
    INNER JOIN			  dbo.tblLoanApps   AUTO_LOAN_APP WITH (NOLOCK)
    INNER JOIN			  dbo.tblDealers    DEALER WITH (NOLOCK) ON AUTO_LOAN_APP.DealerID = DEALER.DealerID ON
						dbo.viewLoanAppPhoneNumbers.LoanAppID = AUTO_LOAN_APP.LoanAppID ON BID.LoanAppID = AUTO_LOAN_APP.LoanAppID
    LEFT OUTER JOIN		tblLenderDealerRelation		r	      WITH (NOLOCK) ON r.DealerID = DEALER.DealerID AND LENDER_BRANCH.LenderID = r.LenderID
	LEFT OUTER JOIN		tblLendersLogins		    ll		  WITH (NOLOCK) ON ll.LendersLoginID = r.LenderAgentID
	LEFT OUTER JOIN		tblLendersBranchLogins		lbl		  WITH (NOLOCK) ON lbl.LendersBranchLoginID = r.LenderBranchAgentID

	LEFT OUTER JOIN     tblPartnerDataElement		de		  WITH (NOLOCK) ON AUTO_LOAN_APP.LoanAppID = de.LoanAppID
	LEFT OUTER JOIN     tblPartnerTools				pt	      WITH (NOLOCK) ON pt.PartnerToolID = de.PartnerToolID
	LEFT OUTER JOIN tblLoanApp_Worksheet        WS        WITH (NOLOCK) ON (BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)

ORDER BY BID.LoanApp_BidID DESC, AUTO_LOAN_APP.LoanAppID DESC









