/****** Object:  View dbo.erik_temp_filters    Script Date: 7/31/2024 12:57:23 PM ******/


--SELECT TOP 5 * FROM tblProgramFilter;

CREATE VIEW erik_temp_filters AS


SELECT TOP 100 PERCENT
  LenderID = L.LenderID,
  Lender = UPPER(L.LenderName),
  Program = UPPER(P.ProgramName),
  PF.ProgramID,
  PF.ProgramFilterID,
  ProgramActive = P.Active,
  Description = UPPER(ISNULL(PF.Description, ''))
FROM
  tblPrograms P
  JOIN tblProgramFilter PF ON(PF.ProgramID=P.ProgramID)
  JOIN tblLenders L ON(P.LenderID=L.LenderID)
WHERE
