/****** Object:  View dbo.viewActivePartnerSenderSessions    Script Date: 7/31/2024 12:57:23 PM ******/
CREATE VIEW [viewActivePartnerSenderSessions] AS
	SELECT
		[SessionID]					= [Session].[SessionID],
		[Name]						= [Session].[SessionName],
		[Application]				= DBO.SenderServiceName([Session].[ApplicationName]),
		[OperationID]				= [Session].[OperationID],
		[PartnerToolID]				= [Partner].[PartnerToolID],
		[Partner]					= UPPER([Partner].[ShortName]),
		[LenderID]					= CASE WHEN [Session].[LenderID]		IS NOT NULL AND EXISTS(SELECT * FROM [tblLenders]			[Lender] WITH (NOLOCK) WHERE [Lender].[LenderID]		= [Session].[LenderID])			THEN [Session].[LenderID]			ELSE NULL END,
		[LendersBranchID]			= CASE WHEN [Session].[LendersBranchID]	IS NOT NULL AND EXISTS(SELECT * FROM [tblLendersBranches]	[Branch] WITH (NOLOCK) WHERE [Branch].[LendersBranchID]	= [Session].[LendersBranchID])	THEN [Session].[LendersBranchID]	ELSE NULL END,
		[DealerID]					= CASE WHEN [Session].[DealerID]		IS NOT NULL AND EXISTS(SELECT * FROM [tblDealers]			[Dealer] WITH (NOLOCK) WHERE [Dealer].[DealerID]		= [Session].[DealerID])			THEN [Session].[DealerID]			ELSE NULL END,

		[Host]						= [Session].[HostName],
		[User]						= NULLIF([Session].[SessionUser], 'dbo'),
		[Seen]						= [Session].[LastSeen],
		[SeenAgo]					= DATEDIFF(ss, [Session].[LastSeen], GETDATE()),
		[PID]						= [Session].[ProcessID],
		[SPID]						= [Session].[LastSPID],
		[Locks]						= (SELECT COUNT(*) FROM [tblPartnerSender_Lock] [Locks] WITH (NOLOCK) WHERE [Locks].[SessionID] = [Session].[SessionID] AND [Locks].[ExpireDateTime] >= GETDATE())
	FROM
					[tblPartnerSender_Session]	[Session] 		WITH (NOLOCK)
		JOIN		[tblPartnerTools]			[Partner]		WITH (NOLOCK) ON [Partner].[PartnerToolID] = [Session].[PartnerToolID]
	WHERE
		[Session].[Active] 		 = 1							AND
		[Session].[LastSeen]	>= DATEADD(mi, -15, GETDATE())


