/****** Object:  View dbo.viewAssetTypes_Dealer    Script Date: 7/31/2024 12:57:23 PM ******/
CREATE VIEW viewAssetTypes_Dealer AS
	SELECT TOP 100 PERCENT
		AssignedPurchaseAssetTypeID		= Assignment.AssignedPurchaseAssetTypeID,
		DealerID						= Dealer.DealerID,
		PurchaseAssetTypeID				= Type.PurchaseAssetTypeID,
		PurchaseAssetTypeCategory		= Category.PurchaseAssetTypeCategory,
		PurchaseAssetType				= Type.PurchaseAssetType,
		CategoryCaption					= Category.Caption,
		Caption							= Type.Caption,
		Active							= ISNULL(Assignment.Active, Type.IsMotorCar),
		Virtual							= CAST(CASE WHEN Assignment.AssignedPurchaseAssetTypeID IS NULL THEN 1 ELSE 0 END AS BIT)
	FROM
						tblDealers							Dealer			WITH (NOLOCK)
			CROSS JOIN	tblPurchaseAssetType				Type			WITH (NOLOCK)
			INNER JOIN	tblPurchaseAssetTypeCategory		Category		WITH (NOLOCK) ON	Category.PurchaseAssetTypeCategoryID	= Type.PurchaseAssetTypeCategoryID
			LEFT  JOIN	tblAssignedPurchaseAssetType		Assignment		WITH (NOLOCK) ON	Assignment.DealerID						= Dealer.DealerID						AND
																								Assignment.PurchaseAssetTypeID			= Type.PurchaseAssetTypeID
	WHERE
		Dealer.DealerStatus		<>	'INACTIVE'		AND
		Type.Active				=	1				AND
		Category.Active			=	1
	ORDER BY
		--Dealer.DealerID,
		Category.Position,
		Category.PurchaseAssetTypeCategoryID,
		Type.Position,
		Type.PurchaseAssetTypeID


