/****** Object:  View dbo.viewAssetTypes_LendersBranch    Script Date: 7/31/2024 12:57:23 PM ******/
CREATE VIEW viewAssetTypes_LendersBranch AS
	SELECT TOP 100 PERCENT
		AssignedPurchaseAssetTypeID				= Link_Branch.AssignedPurchaseAssetTypeID,
		AssignedPurchaseAssetTypeID_Lender		= Link_Lender.AssignedPurchaseAssetTypeID,
		LenderID								= Lender.LenderID,
		LendersBranchID							= Branch.LendersBranchID,		

		PurchaseAssetTypeID						= Type.PurchaseAssetTypeID,
		PurchaseAssetTypeCategory				= Category.PurchaseAssetTypeCategory,
		PurchaseAssetType						= Type.PurchaseAssetType,
		CategoryCaption							= Category.Caption,
		Caption									= Type.Caption,
		Active									= ISNULL(Link_Branch.Active, ISNULL(Link_Lender.Active, Type.IsMotorCar)),
		Source									= CASE WHEN Link_Branch.AssignedPurchaseAssetTypeID IS NOT NULL THEN 'Branch' WHEN Link_Lender.AssignedPurchaseAssetTypeID IS NOT NULL THEN 'Lender' ELSE 'Virtual' END,
		Active_Lender							= ISNULL(Link_Lender.Active, Type.IsMotorCar),
		Virtual									= CAST(CASE WHEN Link_Branch.AssignedPurchaseAssetTypeID IS NULL THEN 1 ELSE 0 END AS BIT),
		Virtual_Lender							= CAST(CASE WHEN Link_Lender.AssignedPurchaseAssetTypeID IS NULL THEN 1 ELSE 0 END AS BIT)
	FROM
						tblLenders							Lender				WITH (NOLOCK)
			INNER JOIN	tblLendersBranches					Branch				WITH (NOLOCK) ON	Branch.LenderID							= Lender.LenderID
			CROSS JOIN	tblPurchaseAssetType				Type				WITH (NOLOCK)
			INNER JOIN	tblPurchaseAssetTypeCategory		Category			WITH (NOLOCK) ON	Category.PurchaseAssetTypeCategoryID	= Type.PurchaseAssetTypeCategoryID


			LEFT  JOIN	tblAssignedPurchaseAssetType		Link_Branch			WITH (NOLOCK) ON	Link_Branch.LendersBranchID				= Branch.LendersBranchID				AND
																									Link_Branch.PurchaseAssetTypeID			= Type.PurchaseAssetTypeID




			LEFT  JOIN	tblAssignedPurchaseAssetType		Link_Lender			WITH (NOLOCK) ON	Link_Lender.LenderID					= Lender.LenderID						AND
																									Link_Lender.PurchaseAssetTypeID			= Type.PurchaseAssetTypeID
	WHERE
		Lender.LenderStatus		<>	'INACTIVE'		AND
		--Lender.LenderStatus	<>	'FAX'			AND
		Type.Active				=	1				AND
		Category.Active			=	1
	ORDER BY
		Lender.LenderID,
		Branch.LendersBranchID,
		Category.Position,
		Category.PurchaseAssetTypeCategoryID,
		Type.Position,
		Type.PurchaseAssetTypeID


