/****** Object:  View dbo.viewB2B_DecisionSenderReceipts    Script Date: 7/31/2024 12:57:23 PM ******/
CREATE VIEW [dbo].[viewB2B_DecisionSenderReceipts] AS
	SELECT --TOP 2500
		[PartnerToolID]				= [PDR].[PartnerToolID],
		[LoanAppID]					= [Bid].[LoanAppID],
		[LenderID]					= [Branch].[LenderID],
		[LoanApp_BidID]				= [PDR].[LoanApp_BidID],
		[BidStatus]					= [Bid].[Status],
		[IsDecision]				= CONVERT(BIT, CASE WHEN [Bid].[Status] IN ('PENDING_DEALER', 'DECLINE_LENDER', 'ACCEPTED') THEN 1 ELSE 0 END),
		[PartnerToolsTriggerID]		= [PDR].[PartnerToolsTriggerID],
		[Offer_Date]				= [Bid].[Offer_Date],
		[OfferedAgo]				= DATEDIFF(ss, [Bid].[Offer_Date], GETDATE()),
		[Sent]						= CONVERT(BIT, CASE WHEN [PDR].[TS_Success] IS NULL OR [Bid].[Offer_Date] IS NULL THEN 0 ELSE 1 END),
		[SentLatest]				= CONVERT(BIT, CASE WHEN [PDR].[TS_Success] IS NULL OR [Bid].[Offer_Date] IS NULL THEN 0 WHEN [PDR].[TS_Success] >= [Bid].[Offer_Date] THEN 1 ELSE 0 END),
		[OfferSuccessDifference]	= DATEDIFF(ss, [Bid].[Offer_Date], [PDR].[TS_Success]),
		[Tries]						= [PDR].[TryCount],
		[Successes]					= [PDR].[SuccessCount],
		[Errors]					= [PDR].[ErrorCount],
		[LastError]					= [PDR].[TS_LastError],
		[LastErrorAgo]				= DATEDIFF(ss, [PDR].[TS_LastError], GETDATE()),
		[Success]					= [PDR].[TS_Success],
		[SuccessAgo]				= DATEDIFF(ss, [PDR].[TS_Success], GETDATE()),
		[FirstAttempt]				= [PDR].[TS_FirstAttempt],
		[FirstAttemptAgo]			= DATEDIFF(ss, [PDR].[TS_FirstAttempt], GETDATE()),
		[LastAttempt]				= [PDR].[TS_LastAttempt],
		[LastAttemptAgo]			= ISNULL(DATEDIFF(ss, [PDR].[TS_LastAttempt], GETDATE()), 999),
		[CreateDateTime]			= [PDR].[CreateDateTime],
		[UpdateDateTime]			= [PDR].[UpdateDateTime],
		[CreateUser]				= [PDR].[CreateUser],
		[UpdateUser]				= [PDR].[UpdateUser],
		[RowVersion]				= [PDR].[RowVersion],
		[CreatedByUser]				= CONVERT(BIT, CASE WHEN [PDR].[CreateUser] IN ('', 'innovate-pending-sweep', 'queueInserter', 'sp_B2B_Requeue_V3', 'sp_B2B_Requeue_V3v2') THEN 0 WHEN [PDR].[CreateUser] IN ('sp_B2B_Submit') THEN 1 ELSE 0 END),
		[UpdatedByUser]				= CONVERT(BIT, CASE WHEN [PDR].[UpdateUser] IN ('', 'innovate-pending-sweep', 'queueInserter', 'sp_B2B_Requeue_V3', 'sp_B2B_Requeue_V3v2') THEN 0 WHEN [PDR].[UpdateUser] IN ('sp_B2B_Submit') THEN 1 ELSE 0 END),
		[CreatedOrUpdatedByUser]	= CONVERT(BIT, CASE WHEN [PDR].[CreateUser] IN ('', 'innovate-pending-sweep', 'queueInserter', 'sp_B2B_Requeue_V3', 'sp_B2B_Requeue_V3v2') AND [PDR].[UpdateUser] IN ('', 'innovate-pending-sweep', 'queueInserter', 'sp_B2B_Requeue_V3', 'sp_B2B_Requeue_V3v2') THEN 0 WHEN [PDR].[CreateUser] IN ('sp_B2B_Submit') OR [PDR].[UpdateUser] IN ('sp_B2B_Submit') THEN 1 ELSE 0 END)
	FROM
					[tblPartnerDecision_Receipt]	[PDR]				WITH (NOLOCK)
		JOIN		[tblLoanApp_Bids]				[Bid]				WITH (NOLOCK) ON [Bid].[LoanApp_BidID]			= [PDR].[LoanApp_BidID]
		JOIN		[tblLendersBranches]			[Branch]			WITH (NOLOCK) ON [Branch].[LendersBranchID]		= [Bid].[LendersBranchID]
	WHERE
		[PDR].[CreateDateTime] >= DATEADD(d, -90, GETDATE())


