/****** Object:  View dbo.viewB2B_QueuePriority_Inner    Script Date: 7/31/2024 12:57:23 PM ******/
CREATE VIEW [viewB2B_QueuePriority_Inner] AS
	SELECT
		--TOP 100
		[PartnerToolID]				 		= [Partner].[PartnerToolID],
		[Partner]									= /*MIN(*/ [Partner].[ShortName] /*)*/,
		[LoanAppID]						 		= [Bid].[LoanAppID],
		[LoanApp_BidID]				 		= [Bid].[LoanApp_BidID],
		[LenderID]						 		= [Branch].[LenderID],
		[LendersBranchID]			 		= /*MIN(*/ [Branch].[LendersBranchID] /*)*/,
		--[Lender]								= UPPER(LEFT(/*MIN(*/ [Lender].[LenderName] /*)*/, 30)),
		--[DealerID]						 	= /*MIN(*/ [Dealer].[DealerID] /*)*/,
		--[Dealer]								= ISNULL(UPPER(LEFT(/*MIN(*/ [Dealer].[DealerName] /*)*/, 30)), ''),
		[BidStatus]								= /*MIN(*/ [Bid].[Status] /*)*/,
		[Offer_Date]							= /*CASE WHEN [Bid].[Canceled_Date] IS NULL AND [Bid].[Offer_Date] IS NOT NULL AND [Bid].[Status] IN ('PENDING_DEALER', 'DECLINE_LENDER') THEN*/ [Bid].[Offer_Date] /*END*/,
		[BidCreated]							= /*MIN(*/ [Bid].[CreateDateTime] /*)*/,
		[BidUpdated]							= /*MIN(*/ [Bid].[UpdateDateTime] /*)*/,
		[ReceiptCreated]					= /*MIN(*/ [PDR].[CreateDateTime] /*)*/,
		[ReceiptUpdated]					= /*MIN(*/ [PDR].[UpdateDateTime] /*)*/,
		[isManuallyTriggered]			= CONVERT(BIT, CASE WHEN /*MIN(*/ [PDR].[UpdateUser] /*)*/ = 'sp_B2B_Submit' THEN 1 ELSE 0 END),
		[isDecision]							= CONVERT(BIT, CASE WHEN /*[Bid].[Canceled_Date] IS NULL AND [Bid].[Offer_Date] IS NOT NULL AND*/ [Bid].[Status] IN ('PENDING_DEALER', 'DECLINE_DEALER', 'DECLINE_LENDER', 'ACCEPTED')	THEN 1	ELSE 0 END),
		[isPending]								= CONVERT(BIT, CASE WHEN /*[Bid].[Canceled_Date] IS NULL																		AND*/ [Bid].[Status] IN ('REFERRED', 'PENDING_LENDER')																			THEN 1	ELSE 0 END),

		[Bids]								 		= (SELECT COUNT(*)	FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK)		WHERE [Bids].[LoanAppID] = [Bid].[LoanAppID]		AND EXISTS(SELECT * FROM [tblLendersBranches] [Branches] WITH (NOLOCK) WHERE [Branches].[LendersBranchID] = [Bids].[LendersBranchID]		AND [Branches].[LenderID] = [Branch].[LenderID]) 	AND [Bids].[Canceled_Date] IS NULL																																																			),
		[Decisions]						 		= (SELECT COUNT(*)	FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK)		WHERE [Bids].[LoanAppID] = [Bid].[LoanAppID]		AND EXISTS(SELECT * FROM [tblLendersBranches] [Branches] WITH (NOLOCK) WHERE [Branches].[LendersBranchID] = [Bids].[LendersBranchID]		AND [Branches].[LenderID] = [Branch].[LenderID]) 	AND [Bids].[Canceled_Date] IS NULL		AND [Bids].[Status] IN ('PENDING_DEALER', 'DECLINE_LENDER')		/*AND [Bids].[Offer_Date]	IS NOT NULL*/	),
		[Pendings]					 			= (SELECT COUNT(*)	FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK)		WHERE [Bids].[LoanAppID] = [Bid].[LoanAppID]		AND EXISTS(SELECT * FROM [tblLendersBranches] [Branches] WITH (NOLOCK) WHERE [Branches].[LendersBranchID] = [Bids].[LendersBranchID]		AND [Branches].[LenderID] = [Branch].[LenderID]) 	AND [Bids].[Canceled_Date] IS NULL		AND [Bids].[Status] IN ('REFERRED', 'PENDING_LENDER')																							)
	FROM
					[tblPartnerDecision_Receipt]		[PDR]				WITH (NOLOCK)
		JOIN	[tblPartnerTools]								[Partner]		WITH (NOLOCK) ON	[Partner].[PartnerToolID]			 = [PDR].[PartnerToolID]
		JOIN	[tblLoanApp_Bids]								[Bid]				WITH (NOLOCK) ON	[Bid].[LoanApp_BidID]					 = [PDR].[LoanApp_BidID]
		JOIN	[tblLendersBranches]						[Branch]		WITH (NOLOCK) ON	[Branch].[LendersBranchID]		 = [Bid].[LendersBranchID]
		--JOIN			[tblLoanApps]							[App]				WITH (NOLOCK) ON	[App].[LoanAppID]							 = [Bid].[LoanAppID]
		--JOIN			[tblLenders]							[Lender]		WITH (NOLOCK) ON	[Lender].[LenderID]						 = [Branch].[LenderID]
		--LEFT JOIN	[tblDealers]							[Dealer]		WITH (NOLOCK) ON	[Dealer].[DealerID]						 = [App].[DealerID]
	WHERE
		[Bid].[CreateDateTime] >= DATEADD(d, -30, GETDATE()) AND [Bid].[Canceled_Date] IS NULL

/*
	GROUP BY
			[Partner].[PartnerToolID],
			[Bid].[LoanApp_BidID],
			[Bid].[LoanAppID],
			[Branch].[LenderID],
			[Bid].[Status],
			[Bid].[Offer_Date],
			[Bid].[Canceled_Date]
*/
