/****** Object:  View dbo.viewBidsInterfaceDisplay    Script Date: 7/31/2024 12:57:23 PM ******/




CREATE VIEW viewBidsInterfaceDisplay AS
	SELECT
		LoanAppID,
		LoanApp_BidID,
		DealerID,
		APPLICANT_NAMES,
		YIELD_TYPE,
		COMMENTS = '',

	TERM = CASE
		WHEN TERM IS NULL 				THEN NULL
		WHEN ISNUMERIC(TERM) = 1		THEN TERM
		WHEN TERM = ''					THEN NULL
		WHEN CHARINDEX('M', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('M', TERM) - 1))
		WHEN CHARINDEX('/', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('/', TERM) - 1))
		WHEN CHARINDEX(' ', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX(' ', TERM) - 1))
		ELSE -1
	END,
		PAYMENT,
		MESSAGING_STATUS,
		REBATE_PERCT,
		ADVANCE,
		LenderID,

		BidAge = DATEDIFF(day, BidUpdateDateTime, GetDate()),

		LENDER_ARCHIVED = ISNULL(LENDER_ARCHIVED, 0),

		Canceled = CASE
			WHEN Canceled_Date IS NULL THEN CONVERT(BIT, 0)
			ELSE CONVERT(BIT, 1)
		End,

		Canceled_Date,

		Funded = CASE
			WHEN FUNDED_DATE IS NOT NULL THEN CONVERT(BIT, 1)
			WHEN Funded IS NULL THEN CONVERT(BIT, 0)
			ELSE CONVERT(BIT, Funded)
		End,

		ShowInLenderNewDeals = CASE
			WHEN NOT Canceled_Date	IS NULL									THEN CONVERT(BIT, 0)
			WHEN LENDER_ARCHIVED	=  1 									THEN CONVERT(BIT, 0)
			WHEN DATEDIFF(day, BidUpdateDateTime, GetDate()) > 30			THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus IN ('RECEIVED', 'REJECTED')				THEN CONVERT(BIT, 0)
			WHEN STATUS IN ('PENDING_LENDER', 'REFERRED', 'PENDING_B2B') 	THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
		END,

		ShowInLenderPendingFunding = CASE
			WHEN StatusUpdateDateTime	IS	NULL						THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus		IS	NULL						THEN CONVERT(BIT, 0)
			WHEN LEN(BidFundingStatus)	=	0							THEN CONVERT(BIT, 0)
			WHEN DATEDIFF(day, StatusUpdateDateTime, getdate()) > 45	THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'RECEIVED'							THEN CONVERT(BIT, 1)
			WHEN DATEDIFF(day, StatusUpdateDateTime, getdate()) > 30	THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'REJECTED'							THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
			--ELSE CONVERT(BIT, 1)
		END,

		ShowInLenderMessaging = CASE
			WHEN NOT Canceled_Date	IS NULL									THEN CONVERT(BIT, 0)
			WHEN LENDER_ARCHIVED	=  1 									THEN CONVERT(BIT, 0)
			WHEN DATEDIFF(day, BidUpdateDateTime, GetDate()) > 14			THEN CONVERT(BIT, 0)
			WHEN Messaging_Status = 'COMMENT_FOR_LENDER'					THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
		END,

		ShowInDealerNewDeals = CASE
			WHEN DATEDIFF(day, BidUpdateDateTime, GetDate()) > 20			THEN CONVERT(BIT, 0)
			WHEN ARCHIVED			= 1										THEN CONVERT(BIT, 1)
			WHEN MESSAGING_STATUS	= 'COMMENT_FOR_DEALER'					THEN CONVERT(BIT, 1)
			WHEN BidFundingStatus IN ('RECEIVED', 'REJECTED')				THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'REJECTED'							THEN CONVERT(BIT, 1)

			WHEN STATUS				IN('REFERRED', 'PENDING_DEALER', 'DECLINE_LENDER', 'PENDING_LENDER', 'PENDING_AUTOMATION', 'PROCESSING_AUTOMATION', 'B2B_ERROR', 'PENDING_B2B', 'DUPLICATE')
				THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
		END,

		ShowInDealerMessaging = CASE
			WHEN NOT Canceled_Date	IS NULL									THEN CONVERT(BIT, 0)
			WHEN LENDER_ARCHIVED	=  1 									THEN CONVERT(BIT, 0)
			WHEN DATEDIFF(day, BidUpdateDateTime, GetDate()) > 14			THEN CONVERT(BIT, 0)
			WHEN Messaging_Status = 'COMMENT_FOR_DEALER'					THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
		END,



		ShowInDealerFunding = CASE
			WHEN StatusUpdateDateTime	IS	NULL						THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus		IS	NULL						THEN CONVERT(BIT, 0)
			WHEN LEN(BidFundingStatus)	=	0							THEN CONVERT(BIT, 0)
			WHEN DATEDIFF(day, StatusUpdateDateTime, getdate()) > 45	THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'RECEIVED'							THEN CONVERT(BIT, 1)
			WHEN DATEDIFF(day, StatusUpdateDateTime, getdate()) > 30	THEN CONVERT(BIT, 0)
			WHEN BidFundingStatus = 'REJECTED'							THEN CONVERT(BIT, 1)
			ELSE CONVERT(BIT, 0)
			--ELSE CONVERT(BIT, 1)
		END,




		FUNDED_DATE,

		FINANCING_AMOUNT,
		ANTICIPATED_RATE,
		LOAN_DOWN_PAYMENT,
		LOAN_ESTIMATED_PAYMENT,
		LOAN_LICENSE,
		LOAN_MISC,
		LOAN_PURCHASE_PRICE,
		LOAN_TAX,
		LOAN_TERM_REQUESTED,
		LOAN_TOTAL_LOAN_AMOUNT,
		LOAN_WARRANTY,
		VEHICLE_DESCRIPTION,
		VEHICLE_MAKE,
		VEHICLE_MILEAGE,
		VEHICLE_MODEL,
		VEHICLE_VIN,
		VEHICLE_YEAR,
		VEHICLE_TYPE,
		VEHICLE,
		WorksheetID,
		NEW_USED,
		STATUS,
		ARCHIVED = ISNULL(ARCHIVED, 0),
		Dealer,
		DealerEMail,
		UpdateUser,
		CreateUser,
		UpdateDateTime,
		CreateDateTime,
		RATE,
		LendersBranchID,
		Lender,
		BranchName,
		BidCreateDateTime,
		BidUpdateDateTime,
		BidSubmitDateTime,
		LenderCity,
		LenderState,

		DealerName,

		Stips,
		Reason,
		DEALER_CREDIT_EX,
		DEALER_CREDIT_EQ,
		DEALER_CREDIT_TU,
		LENDER_CREDIT_EQ,
		LENDER_CREDIT_TU,
		LENDER_CREDIT_EX,
		Reasons,
		DISCOUNT_FEE,
		AUTOMATED,

		OFFER_DATE,

		OFFERED_BY,
		ACCEPT_DATE,
		SUBMIT_DATE,
		SUBMIT_BY,
		PRIMARY_SCORE,
		SECONDARY_SCORE,
		ACCEPT_BY,
