  	Billing.nextpayment,
	Recent					=	(select max(ts_added) from tblPayFlowTransactions WITH (NOLOCK) WHERE profileid=Billing.ARB_ProfileID),
	Ago						=	DATEDIFF(dd, (select max(ts_added) from tblPayFlowTransactions WITH (NOLOCK) WHERE profileid=Billing.ARB_ProfileID), getdate())
	FROM
				viewDealerARBSummary				DARB 		WITH (NOLOCK)
		JOIN	tblDealersBilling					Billing 	WITH (NOLOCK) ON DARB.ARB_ProfileID	= Billing.ARB_ProfileID
