	Billing.DealerID IN(	
		SELECT DealerID FROM tblDealersBilling WITH (NOLOCK) WHERE LEN(ISNULL(arb_profileid,'')) > 0 AND DealerID NOT IN( SELECT DealerID FROM tblPayFlowTransactions WITH (NOLOCK)) AND Active='Y' AND LEN(ISNULL(Last_Bill_TransID, '')) = 0 AND DATEDIFF(dd, dt_added, GETDATE()) < 120
	)
OR

(	((Billing.Status='Active' OR Billing.Active='Y'))
	AND	LEN(ISNULL(DARB.ARB_ProfileID, ''))>0
  AND datediff(dd, Billing.nextpayment, getdate()) > 0
--  AND Billing.nextPayment

	AND (
		(ISNULL(DATEDIFF(dd, (select max(ts_added) from tblPayFlowTransactions WHERE profileid=Billing.ARB_ProfileID), Billing.dt_edited),31) >=30

			OR
		datediff(dd, getdate(), Billing.nextpayment) <=3)
      OR
    (Billing.Active='Y' OR Billing.Status='Active' AND Billing.nextpayment IS NULL))
)
--      OR
--    ISNULL(
