/****** Object:  View dbo.viewFilters    Script Date: 7/31/2024 12:57:23 PM ******/


CREATE VIEW viewFilters AS

SELECT DISTINCT TOP 100 PERCENT
	CategoryID                      = CATEGORY.CategoryID,
  ParameterID                     = PARAM.ParameterID,
  Category                        = CATEGORY.CategoryName,
  Filter                          = FILTER.ShortName,
  FilterDescription               = FILTER.LongName,
  Parameter                       = PARAM.ShortName,
  ParameterDescription            = PARAM.LongName,
  DataType                        = DATA_TYPE.ShortName,
  ShowDropDown                    = ISNULL(PARAM.ShowDropDown, 0),
	Value                           = '',
  DropDownValues                  = PARAM.DropDownValues,
	Operator                        = '',
  Units                           = PARAM.Units,
  RequiresCredit                  = ISNULL(FILTER.RequiresCredit, 1),

	S1 = ISNULL(CATEGORY.SortValue, CATEGORY.CategoryName),
	S2 = ISNULL(FILTER.SortValue, Filter.ShortName),
	S3 = ISNULL(PARAM.SortValue, 'ZZZZZZZZZZZZZZZZZZZZZZZZZ')

FROM
  					tblCategories		CATEGORY 		WITH (NOLOCK)
	JOIN			tblFilters			FILTER			WITH (NOLOCK) 	ON CATEGORY.CategoryID			= FILTER.CategoryID
	JOIN 			tblParameters 	PARAM 			WITH (NOLOCK)  	ON FILTER.FilterID          = PARAM.FilterID
	JOIN 			tblDataTypes 		DATA_TYPE 	WITH (NOLOCK) 	ON (DATA_TYPE.DataTypeID    = PARAM.DataTypeID)

ORDER BY
	ISNULL(CATEGORY.SortValue, CATEGORY.CategoryName),
	FILTER.ShortName

--	ISNULL(FILTER.SortValue, Filter.ShortName)
