/****** Object:  View dbo.viewInterfaceDealerNewDeals    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE  VIEW [viewInterfaceDealerNewDeals] AS
	SELECT
		[LoanAppID]										= [Bid].[LoanAppID],
		[LoanApp_BidID]									= [Bid].[LoanApp_BidID],
		[SortValue] 									= DATEDIFF(ss, (SELECT MAX([Bid_Newest].[UpdateDateTime]) FROM [tblLoanApp_Bids] [Bid_Newest] WITH (NOLOCK) WHERE [Bid_Newest].[LoanAppID] = [Bid].[LoanAppID]), GETDATE()),

		--[DealerID]									= [Dealer].[DealerID],
		[DealerID]										= [App].[DealerID],
		[Applicant_Names]								= [App].[Applicant_Names],
		[Yield_Type]									= [Bid].[Yield_Type],
		[Comments]										= '',
		[Term]											= CASE WHEN [Term] IS NULL THEN NULL WHEN ISNUMERIC([Term]) = 1 THEN [Term] WHEN [Term] = '' THEN NULL WHEN CHARINDEX('M', [Term]) > 0 THEN CONVERT(INTEGER, LEFT([Term], CHARINDEX('M', [Term]) - 1)) WHEN CHARINDEX('/', [Term]) > 0 THEN CONVERT(INTEGER, LEFT([Term], CHARINDEX('/', [Term]) - 1)) WHEN CHARINDEX(' ', [Term]) > 0 THEN CONVERT(INTEGER, LEFT([Term], CHARINDEX(' ', [Term]) - 1)) ELSE -1 END,

		[Payment]										= [Bid].[Payment],
		[Messaging_Status]								= [Bid].[Messaging_Status],
		[Rebate_Perct]									= [Bid].[Rebate_Perct],
		[Advance]										= [Bid].[Advance],
		[LenderID]										= [Lender].[LenderID],

		[BidAge]										= DATEDIFF(day, [Bid].[UpdateDateTime], GETDATE()),
		[Lender_Archived]								= ISNULL([Bid].[Lender_Archived], 0),
		[Canceled]										= CONVERT(BIT, CASE WHEN [Canceled_Date] IS NULL THEN 0 ELSE 1 END),
		[Canceled_Date]									= [Bid].[Canceled_Date],

		[Funded]										= CONVERT(BIT, CASE WHEN [Funded_Date] IS NOT NULL THEN 1 WHEN [Funded] IS NULL THEN 0 ELSE [Funded] END),

		[ShowInLenderNewDeals]							= CONVERT(BIT, 0),
		[ShowInLenderPendingFunding]					= CONVERT(BIT, 0),
		[ShowInLenderMessaging]							= CONVERT(BIT, 0),
		[ShowInDealerNewDeals]							= CONVERT(BIT, 1),
		[ShowInDealerMessaging]							= CONVERT(BIT, CASE WHEN NOT [Canceled_Date] IS NULL THEN 0 WHEN [Bid].[Lender_Archived] = 1 THEN 0 WHEN DATEDIFF(day, [Bid].[UpdateDateTime], GETDATE()) > 14 THEN 0 WHEN [Messaging_Status] = 'COMMENT_FOR_Dealer' THEN 1 ELSE 0 END),
		[ShowInDealerFunding]							= CONVERT(BIT, CASE WHEN [FundingStatus].[StatusUpdateDateTime] IS NULL THEN 0 WHEN [BidFundingStatus] IS NULL THEN 0 WHEN LEN([BidFundingStatus]) = 0 THEN 0 WHEN DATEDIFF(day, [FundingStatus].[StatusUpdateDateTime], GETDATE()) > 45 THEN 0 WHEN [BidFundingStatus] = 'RECEIVED' THEN 1 WHEN DATEDIFF(day, [FundingStatus].[StatusUpdateDateTime], GETDATE()) > 30 THEN 0 WHEN [BidFundingStatus] = 'REJECTED' THEN 1 ELSE 0 END),

		[Anticipated_Rate]								= ISNULL([Worksheet].[Anticipated_Rate],		[App].[Anticipated_Rate]),
		[Loan_Down_Payment]								= ISNULL([Worksheet].[Loan_Down_Payment],		[App].[Loan_Down_Payment]),
		[Loan_Estimated_Payment]						= ISNULL([Worksheet].[Loan_Estimated_Payment],	[App].[Loan_Estimated_Payment]),
		[Loan_License]									= ISNULL([Worksheet].[Loan_License],			[App].[Loan_License]),
		[Loan_Misc]										= ISNULL([Worksheet].[Loan_Misc],				[App].[Loan_Misc]),
		[Loan_Purchase_Price]							= ISNULL([Worksheet].[Loan_Purchase_Price],		[App].[Loan_Purchase_Price]),
		[Loan_Tax]										= ISNULL([Worksheet].[Loan_Tax],				[App].[Loan_Tax]),
		[Loan_Term_Requested]							= ISNULL([Worksheet].[Loan_Term_Requested],		[App].[Loan_Term_Requested]),
		[Loan_Total_Loan_Amount]						= ISNULL([Worksheet].[Loan_Total_Loan_Amount],	[App].[Loan_Total_Loan_Amount]),
		[Loan_Warranty]									= ISNULL([Worksheet].[Loan_Warranty],			[App].[Loan_Warranty]),
		[Vehicle_Description]							= ISNULL([Worksheet].[Vehicle_Description],		[App].[Vehicle_Description]),
		[Vehicle_Make]									= ISNULL([Worksheet].[Vehicle_Make],			[App].[Vehicle_Make]),
		[Vehicle_Mileage]								= ISNULL([Worksheet].[Vehicle_Mileage],			[App].[Vehicle_Mileage]),
		[Vehicle_Model]									= ISNULL([Worksheet].[Vehicle_Model],			[App].[Vehicle_Model]),
		[Vehicle_VIN]									= ISNULL([Worksheet].[Vehicle_VIN],				[App].[Vehicle_VIN]),
		[Vehicle_YEAR]									= ISNULL([Worksheet].[Vehicle_YEAR],			[App].[Vehicle_YEAR]),
		[Vehicle]										= LTRIM(RTRIM(ISNULL(CONVERT(CHAR(4), NULLIF([Worksheet].[Vehicle_YEAR], 0)) + ' ' + [Worksheet].[Vehicle_Make] + ' ' + [Worksheet].[Vehicle_Model], ISNULL(NULLIF(CONVERT(CHAR(4), [App].[Vehicle_YEAR]), 0), '') + ' ' + [App].[Vehicle_Make] + ' ' + [App].[Vehicle_Model]))),
		[Funded_Date]									= [Bid].[Funded_Date],
		[Financing_Amount]								= [Bid].[Financing_Amount],
		[WorkSheetID]									= [Worksheet].[LoanApp_WorksheetID],
		[New_Used]										= [App].[New_Used],
		[Status]										= [Bid].[Status],
		[Archived]										= ISNULL([App].[Archived], 0),

		[Dealer]										= [Dealer].[DealerName] + ' - ' + [Dealer].[City] + ' ' + [Dealer].[State],
		[DealerEMail]									= [Dealer].[EMail],
		[DealerName]									= [Dealer].[DealerName],
		[DealerCity]									= ISNULL([Dealer].[City], ''),
		[DealerState]									= ISNULL([Dealer].[State], ''),

		[UpdateUser]									= [App].[UpdateUser],
		[CreateUser]									= [App].[CreateUser],
		[UpdateDateTime]								= [App].[UpdateDateTime],
		[CreateDateTime]								= [App].[CreateDateTime],
		[Rate]											= [Bid].[Rate],
		[LendersBranchID]								= [Branch].[LendersBranchID],
		[Lender]										= [Branch].[LenderName] + ' - ' + [Branch].[BranchName] + ' (' + [Branch].[City] + ', ' + [Branch].[State] + ')',
		[LenderName]									= ISNULL([Lender].[LenderName], ''),
		[BidCreateDateTime]								= [Bid].[CreateDateTime],
		[BidUpdateDateTime]								= [Bid].[UpdateDateTime],
		[BidSubmitDateTime]								= [Bid].[Submit_Date],
		[LenderCity]									= ISNULL([Lender].[City], ''),
		[LenderState]									= ISNULL([Lender].[State], ''),
		[Stips]											= [Bid].[Stips],
		[Reason]										= [Bid].[Reason],
		[Dealer_Credit_EX]								= ISNULL([App].[Dealer_Credit_EX], ''),
		[Dealer_Credit_EQ]								= ISNULL([App].[Dealer_Credit_EQ], ''),
		[Dealer_Credit_TU]								= ISNULL([App].[Dealer_Credit_TU], ''),
		[Lender_Credit_EQ]								= ISNULL([Bid].[Lender_Credit_EQ], ISNULL([App].[Lender_Credit_EQ], '')),
		[Lender_Credit_TU]								= ISNULL([Bid].[Lender_Credit_TU], ISNULL([App].[Lender_Credit_TU], '')),
		[Lender_Credit_EX]								= ISNULL([Bid].[Lender_Credit_EX], ISNULL([App].[Lender_Credit_EX], '')),
		[Reasons]										= [Bid].[Reasons],
		[Discount_Fee]									= [Bid].[Discount_Fee],
		[Automated]										= [Bid].[Automated],
		[Offer_Date]									= [Bid].[Offer_Date],
		[Offered_By]									= [Bid].[Offered_By],
		[Accept_Date]									= [Bid].[Accept_Date],
		[Submit_Date]									= [Bid].[Submit_Date],
		[Submit_By]										= [Bid].[Submit_By],
		[Primary_Score]									= [Bid].[Primary_Score],
		[Secondary_Score]								= [Bid].[Secondary_Score],
		[Accept_By]										= [Bid].[Accept_By],
		[PTI]											= [Bid].[PTI],
		[DTI]											= [Bid].[DTI],
		[Reminder_Date]									= [Bid].[Reminder_Date],
		[BranchStreet1]									= ISNULL(ISNULL([Branch].[STREET_1], [Lender].[Address]), ''),
		[BranchPhone]									= ISNULL(ISNULL([Branch].[Phone], [Lender].[Phone]), ''),
		[BranchFax]										= ISNULL(ISNULL([Branch].[Fax], [Lender].[Fax]), ''),
		[BranchCity]									= ISNULL(ISNULL([Branch].[City], [Lender].[City]), ''),
		[BranchState]									= ISNULL(ISNULL([Branch].[State], [Lender].[State]), ''),
		[BranchZip]										= ISNULL(ISNULL([Branch].[Zip], [Lender].[Zip]), ''),
		[BranchFaxOnly]									= ISNULL([Branch].[Fax_ONLY], 0),
		[LenderDealerID]								= [App].[LenderID],

		[Fax_Status]									= ISNULL([Fax].[Status], ''),
		[Fax_LastUpdate]								= [Fax].[UpdateDateTime],

		[Counter]										= [Bid].[Counter],
		[ReSubmit_Policy]								= [Lender].[ReSubmit_Policy],

		[PartnerName]									= ISNULL([Partner].[Partner], ''),
		[PartnerToolID]									= [Partner].[PartnerToolID],

		[BidFundingStatus]								= [FundingStatus].[BidFundingStatus],
		[StatusUpdateDateTime]							= [FundingStatus].[StatusUpdateDateTime],

		[LenderAgentName]								= ISNULL([Login_Lender].[FullName], ''),
		[BranchAgentName]								= ISNULL([Login_Branch].[FullName], ''),
		[LenderAgentColorCode]							= CASE WHEN [Login_Lender].[ColorCode] IS NULL THEN 'BLACK' WHEN LEN(ISNULL([Login_Lender].[ColorCode], '')) > 0 THEN [Login_Lender].[ColorCode] ELSE 'BLACK' END,
		[DealerSalesPerson]								= ISNULL([Login_Dealer].[FullName], '')
	FROM
						[tblLoanApps]							[App]					WITH (NOLOCK)
				JOIN	[tblLoanApp_Bids]						[Bid]					WITH (NOLOCK) ON [App].[LoanAppID]								= [Bid].[LoanAppID]
				JOIN	[viewLenderBranches]					[Branch]				WITH (NOLOCK) ON [Bid].[LendersBranchID]						= [Branch].[LendersBranchID]
				JOIN	[tblLenders]							[Lender]				WITH (NOLOCK) ON [Branch].[LenderID]							= [Lender].[LenderID]
		LEFT	JOIN	[viewBid_PartnerInformation]			[Partner]				WITH (NOLOCK) ON [Partner].[LoanApp_BidID]						= [Bid].[LoanApp_BidID]
		LEFT	JOIN	[tblLoanApp_Bids_Fax]					[Fax]					WITH (NOLOCK) ON [Bid].[LoanApp_BidID]							= [Fax].[LoanApp_BidID]
		LEFT	JOIN	[tblDealers]							[Dealer]				WITH (NOLOCK) ON [App].[DealerID]								= [Dealer].[DealerID]
		LEFT	JOIN	[tblLoanApp_Worksheet]					[Worksheet]				WITH (NOLOCK) ON [Bid].[LoanApp_BidID]							= [Worksheet].[LoanApp_BidID]					AND [Worksheet].[Active]		= 1
		LEFT	JOIN	[tblLoanApp_BidFundingStatus]			[FundingStatus]			WITH (NOLOCK) ON [Bid].[LoanApp_BidID]							= [FundingStatus].[LoanApp_BidID]
		LEFT	JOIN	[tblLenderDealerRelation]				[LenderDealerRel]		WITH (NOLOCK) ON [LenderDealerRel].[DealerID]					= [Dealer].[DealerID]							AND [Branch].[LenderID]			= [LenderDealerRel].[LenderID]

		LEFT	JOIN	[tblLendersLogins]						[Login_Lender]			WITH (NOLOCK) ON [Login_Lender].[LendersLoginID]				= [LenderDealerRel].[LenderAgentID]
		LEFT	JOIN	[tblLendersBranchLogins]				[Login_Branch]			WITH (NOLOCK) ON [Login_Branch].[LendersBranchLoginID]			= [LenderDealerRel].[LenderBranchAgentID]
		LEFT	JOIN	[tblLoanAppAssignedDealers]				[Assigned_Dealer]		WITH (NOLOCK) ON [Assigned_Dealer].[LoanAppID]					= [App].[LoanAppID]
		LEFT	JOIN	[tblDealersLogins]						[Login_Dealer]			WITH (NOLOCK) ON [Login_Dealer].[DealersLoginID]				= [Assigned_Dealer].[DealersLoginID]
		LEFT	JOIN	[viewDealersDefaultAssetType]			[AssetType]				WITH (NOLOCK) ON [AssetType].[DealerID]							= [Dealer].[DealerID]							AND [AssetType].[IsDefault]		= 1
	WHERE 		
			[App].[CreateDateTime]		>=	DATEADD(day, -30, GETDATE())
		AND [Bid].[UpdateDateTime]		>=	DATEADD(day, -30, GETDATE())
		AND [App].[Archived]			!=	1
		AND ([Bid].[Status]				IN	('ACCEPTED','REFERRED', 'PENDING_DEALER', 'DECLINE_LENDER', 'PENDING_LENDER', 'PENDING_AUTOMATION', 'PROCESSING_AUTOMATION', 'B2B_ERROR', 'PENDING_B2B', 'DUPLICATE') OR [Bid].[Messaging_Status] IN ('COMMENT_FOR_DEALER') OR [BidFundingStatus] IN ('REJECTED'))
--		AND [App].[DealerID] = 1234


