/****** Object:  View dbo.viewInterfaceDealerNewDeals_20230717    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE	VIEW [dbo].[viewInterfaceDealerNewDeals_20230717] AS
	SELECT
--TOP 500
		[LoanAppID]				= [Bid].[LoanAppID],
		[LoanApp_BidID]			= [Bid].[LoanApp_BidID],
		[DealerID]				= [Dealer].[DealerID],
		[APPLICANT_NAMES]		= [AUTO_LOAN_APP].[APPLICANT_NAMES],
		[YIELD_TYPE]			= [Bid].[YIELD_TYPE],
		[COMMENTS]				= '',
		[TERM]					= CASE
			WHEN [Bid].[Term] IS NULL 				THEN NULL
			WHEN ISNUMERIC([Bid].[Term]) = 1		THEN [Bid].[Term]
			WHEN [Bid].[Term] = ''					THEN NULL
			WHEN CHARINDEX('M', [Bid].[Term]) > 0	THEN CONVERT(INTEGER, LEFT([Bid].[Term], CHARINDEX('M', [Bid].[Term]) - 1))
			WHEN CHARINDEX('/', [Bid].[Term]) > 0	THEN CONVERT(INTEGER, LEFT([Bid].[Term], CHARINDEX('/', [Bid].[Term]) - 1))
			WHEN CHARINDEX(' ', [Bid].[Term]) > 0	THEN CONVERT(INTEGER, LEFT([Bid].[Term], CHARINDEX(' ', [Bid].[Term]) - 1))
			ELSE -1 END,
		[PAYMENT]				= [Bid].[PAYMENT],
		[MESSAGING_STATUS]		= [Bid].[MESSAGING_STATUS],
		[REBATE_PERCT]			= [Bid].[REBATE_PERCT],
		[ADVANCE]				= [Bid].[ADVANCE],
		[LenderID]				= [Lender].[LenderID],
		[BidAge]				= DATEDIFF(day, [Bid].[UpdateDateTime], GetDate()),
		[LENDER_ARCHIVED]		= ISNULL([Bid].[LENDER_ARCHIVED], 0),
		[Canceled]				= CONVERT(BIT, CASE WHEN [Canceled_Date] IS NULL THEN 0 ELSE 1 END),
		[Canceled_Date]			= [Bid].[Canceled_Date],
		[Funded]				= CONVERT(BIT, CASE WHEN [Bid].[FUNDED_DATE] IS NOT NULL THEN 1 ELSE ISNULL([Bid].[Funded], 0) END),
		[ShowInLenderNewDeals]					= CONVERT(BIT, 0),
		[ShowInLenderPendingFunding]			= CONVERT(BIT, 0),
		[ShowInLenderMessaging]					= CONVERT(BIT, 0),

		[ShowInDealerNewDeals]					= CONVERT(BIT, 1),

/* CASE
			WHEN [Bid].[UpdateDateTime] 			< DATEADD(day, -30, GETDATE()) THEN 0
			WHEN [AUTO_LOAN_APP].[CreateDateTime]	< DATEADD(day, -30, GETDATE()) THEN 0
		ELSE 1 END),*/

		[ShowInDealerMessaging]					= CONVERT(BIT, CASE
			WHEN NOT [Bid].[Canceled_Date]	IS NULL									THEN 0
			WHEN [Bid].[LENDER_ARCHIVED]	=  1 									THEN 0
			WHEN DATEDIFF(day, [Bid].[UpdateDateTime], GetDate()) > 14			THEN 0
			WHEN [Bid].[Messaging_Status] = 'COMMENT_FOR_DEALER'					THEN 1
			ELSE 0 END),
		[ShowInDealerFunding]					= CONVERT(BIT, CASE
			WHEN [Funding_Status].[StatusUpdateDateTime]	IS	NULL						THEN 0
			WHEN [Funding_Status].[BidFundingStatus]		IS	NULL						THEN 0
			WHEN LEN([Funding_Status].[BidFundingStatus])	=	0							THEN 0
			WHEN DATEDIFF(day, [Funding_Status].[StatusUpdateDateTime], getdate()) > 45		THEN 0
			WHEN [Funding_Status].[BidFundingStatus] = 'RECEIVED'							THEN 1
			WHEN DATEDIFF(day, [Funding_Status].[StatusUpdateDateTime], getdate()) > 30		THEN 0
			WHEN [Funding_Status].[BidFundingStatus] = 'REJECTED'							THEN 1
			ELSE 0 END),
		[ANTICIPATED_RATE]			= ISNULL([Worksheet].[ANTICIPATED_RATE],		[AUTO_LOAN_APP].[ANTICIPATED_RATE]),
		[LOAN_DOWN_PAYMENT]			= ISNULL([Worksheet].[LOAN_DOWN_PAYMENT],		[AUTO_LOAN_APP].[LOAN_DOWN_PAYMENT]),
		[LOAN_ESTIMATED_PAYMENT]	= ISNULL([Worksheet].[LOAN_ESTIMATED_PAYMENT],	[AUTO_LOAN_APP].[LOAN_ESTIMATED_PAYMENT]),
		[LOAN_LICENSE]				= ISNULL([Worksheet].[LOAN_LICENSE],			[AUTO_LOAN_APP].[LOAN_LICENSE]),
		[LOAN_MISC]					= ISNULL([Worksheet].[LOAN_MISC],				[AUTO_LOAN_APP].[LOAN_MISC]),
		[LOAN_PURCHASE_PRICE]		= ISNULL([Worksheet].[LOAN_PURCHASE_PRICE],		[AUTO_LOAN_APP].[LOAN_PURCHASE_PRICE]),
		[LOAN_TAX]					= ISNULL([Worksheet].[LOAN_TAX],				[AUTO_LOAN_APP].[LOAN_TAX]),
		[LOAN_TERM_REQUESTED]		= ISNULL([Worksheet].[LOAN_TERM_REQUESTED],		[AUTO_LOAN_APP].[LOAN_TERM_REQUESTED]),
		[LOAN_TOTAL_LOAN_AMOUNT]	= ISNULL([Worksheet].[LOAN_TOTAL_LOAN_AMOUNT],	[AUTO_LOAN_APP].[LOAN_TOTAL_LOAN_AMOUNT]),
		[LOAN_WARRANTY]				= ISNULL([Worksheet].[LOAN_WARRANTY],			[AUTO_LOAN_APP].[LOAN_WARRANTY]),
		[VEHICLE_DESCRIPTION]		= ISNULL([Worksheet].[VEHICLE_DESCRIPTION],		[AUTO_LOAN_APP].[VEHICLE_DESCRIPTION]),
		[VEHICLE_MAKE]				= ISNULL([Worksheet].[VEHICLE_MAKE],			[AUTO_LOAN_APP].[VEHICLE_MAKE]),
		[VEHICLE_MILEAGE]			= ISNULL([Worksheet].[VEHICLE_MILEAGE],			[AUTO_LOAN_APP].[VEHICLE_MILEAGE]),
		[VEHICLE_MODEL]				= ISNULL([Worksheet].[VEHICLE_MODEL],			[AUTO_LOAN_APP].[VEHICLE_MODEL]),
		[VEHICLE_VIN]				= ISNULL([Worksheet].[VEHICLE_VIN],				[AUTO_LOAN_APP].[VEHICLE_VIN]),
		[VEHICLE_YEAR]				= ISNULL([Worksheet].[VEHICLE_YEAR],			[AUTO_LOAN_APP].[VEHICLE_YEAR]),
		[VEHICLE]					= LTRIM(RTRIM(ISNULL(CONVERT(CHAR(4), NULLIF([Worksheet].[VEHICLE_YEAR], 0)) + ' ' + [Worksheet].[VEHICLE_MAKE] + ' ' + [Worksheet].[VEHICLE_MODEL], ISNULL(NULLIF(CONVERT(CHAR(4), [AUTO_LOAN_APP].[VEHICLE_YEAR]), 0), '') + ' ' + [AUTO_LOAN_APP].[VEHICLE_MAKE] + ' ' + [AUTO_LOAN_APP].[VEHICLE_MODEL]))),
		[FUNDED_DATE]				= [Bid].[FUNDED_DATE],
		[FINANCING_AMOUNT]			= [Bid].[FINANCING_AMOUNT],
		[WorkSheetID]				= [Worksheet].[LoanApp_WorksheetID],
		[NEW_USED]					= [AUTO_LOAN_APP].[NEW_USED],
		[Status]					= [Bid].[STATUS],
		[ARCHIVED]					= ISNULL([AUTO_LOAN_APP].[ARCHIVED], 0),
		[Dealer]					= [Dealer].[DealerName] + ' - ' + [Dealer].[City] + ' ' + [Dealer].[State],
		[DealerEMail]				= [Dealer].[EMail],
		[AUTO_LOAN_APP].[UpdateUser],
		[AUTO_LOAN_APP].[CreateUser],
		[AUTO_LOAN_APP].[UpdateDateTime],
		[AUTO_LOAN_APP].[CreateDateTime],
		[RATE]			= [Bid].[RATE],
		[Branch].[LendersBranchID],
		[Lender]					= [Lender].[LenderName] + N' - ' + [Branch].[BranchName] + N' (' + [Branch].[CITY] + N', ' + [Branch].[STATE] + N')',
		[LenderName]				= ISNULL([Lender].[LenderName], ''),
		[BidCreateDateTime]			= [Bid].[CreateDateTime],
		[BidUpdateDateTime]			= [Bid].[UpdateDateTime],
		[BidSubmitDateTime]			= [Bid].[Submit_Date],
		[LenderCity]				= ISNULL([Lender].[City], ''),
		[LenderState]				= ISNULL([Lender].[State], ''),
		[DealerName]				= [Dealer].[DealerName],
		[Stips]						= [Bid].[Stips],
		[Reason]					= [Bid].[Reason],
		[DEALER_CREDIT_EX]			= ISNULL([AUTO_LOAN_APP].[DEALER_CREDIT_EX], ''),
		[DEALER_CREDIT_EQ]			= ISNULL([AUTO_LOAN_APP].[DEALER_CREDIT_EQ], ''),
		[DEALER_CREDIT_TU]			= ISNULL([AUTO_LOAN_APP].[DEALER_CREDIT_TU], ''),
		[LENDER_CREDIT_EQ]			= ISNULL([Bid].[LENDER_CREDIT_EQ], ISNULL([AUTO_LOAN_APP].[LENDER_CREDIT_EQ], '')),
		[LENDER_CREDIT_TU]			= ISNULL([Bid].[LENDER_CREDIT_TU], ISNULL([AUTO_LOAN_APP].[LENDER_CREDIT_TU], '')),
		[LENDER_CREDIT_EX]			= ISNULL([Bid].[LENDER_CREDIT_EX], ISNULL([AUTO_LOAN_APP].[LENDER_CREDIT_EX], '')),
		[Reasons]					= [Bid].[Reasons],
		[DISCOUNT_FEE]				= [Bid].[DISCOUNT_FEE],
		[AUTOMATED]					= [Bid].[AUTOMATED],
		[OFFER_DATE]				= [Bid].[OFFER_DATE],
		[OFFERED_BY]				= [Bid].[OFFERED_BY],
		[ACCEPT_DATE]				= [Bid].[ACCEPT_DATE],
		[SUBMIT_DATE]				= [Bid].[SUBMIT_DATE],
		[SUBMIT_BY]					= [Bid].[SUBMIT_BY],
		[PRIMARY_SCORE]				= [Bid].[PRIMARY_SCORE],
		[SECONDARY_SCORE]			= [Bid].[SECONDARY_SCORE],
		[ACCEPT_BY]					= [Bid].[ACCEPT_BY],
		[PTI]						= [Bid].[PTI],
		[DTI]						= [Bid].[DTI],
		[REMINDER_DATE]				= [Bid].[REMINDER_DATE],
		[BranchStreet1]				= ISNULL(ISNULL([Branch].[STREET_1], [Lender].[Address]), ''),
		[BranchPhone]				= ISNULL(ISNULL([Branch].[Phone], [Lender].[Phone]), ''),
		[BranchFax]					= ISNULL(ISNULL([Branch].[Fax], [Lender].[Fax]), ''),
		[BranchCity]				= ISNULL(ISNULL([Branch].[City], [Lender].[City]), ''),
		[BranchState]				= ISNULL(ISNULL([Branch].[State], [Lender].[State]), ''),
		[BranchZip]					= ISNULL(ISNULL([Branch].[Zip], [Lender].[Zip]), ''),
		[BranchFaxOnly]				= ISNULL([Branch].[FAX_ONLY], 0),
		[LenderDealerID]			= [AUTO_LOAN_APP].[LenderID],
		[Fax_Status]				= ISNULL([Fax].[Status], ''),
		[Fax_LastUpdate]			= [FAX].[UpdateDateTime],
		[DealerCity]				= ISNULL([Dealer].[City], ''),
		[DealerState]				= ISNULL([Dealer].[State], ''),
		[Counter]					= [Bid].[Counter],
		[RESUBMIT_POLICY]			= [Lender].[RESUBMIT_POLICY],
		[PartnerName]				= CASE WHEN [Partner].[PartnerToolID] IS NOT NULL AND [Partner].[Partner] IS NOT NULL AND [Partner].[Partner] <> '' THEN [Partner].[Partner] WHEN ISNULL([ASSET_TYPE].[IsSolar], 0) = 1 		THEN 'Solar' ELSE '' END,
		[PartnerToolID]				= [Partner].[PartnerToolID],
		[BidFundingStatus]			= [Funding_Status].[BidFundingStatus],
		[StatusUpdateDateTime]		= [Funding_Status].[StatusUpdateDateTime],
		[LenderAgentName]			= ISNULL([LenderLogin].[FullName], ''),
		[BranchAgentName]			= ISNULL([BranchLogin].[FullName], ''),
		[LenderAgentColorCode]		=	 CASE
			WHEN [LenderLogin].[ColorCode] IS NULL					THEN 'BLACK'
			WHEN LEN(ISNULL([LenderLogin].[ColorCode], '')) > 0		THEN [LenderLogin].[ColorCode]
			ELSE 'BLACK'
		End,
		[DealerSalesPerson]			= ISNULL([DealerLogin].[FullName], '')
	FROM
					[tblLoanApp_Bids]				[BID]					WITH (NOLOCK)
		JOIN		[tblLoanApps]					[AUTO_LOAN_APP]			WITH (NOLOCK) ON [AUTO_LOAN_APP].[LoanAppID]		= [Bid].[LoanAppID]
		JOIN		[tblLendersBranches]			[BRANCH]				WITH (NOLOCK) ON [Bid].[LendersBranchID]			= [Branch].[LendersBranchID]
		JOIN		[tblLenders]					[LENDER]				WITH (NOLOCK) ON [Branch].[LenderID]				= [Lender].[LenderID]
		JOIN		[tblDealers]					[DEALER]				WITH (NOLOCK) ON [AUTO_LOAN_APP].[DealerID]			= [Dealer].[DealerID]
		LEFT JOIN	[viewBid_PartnerInformation]	[Partner]				WITH (NOLOCK) ON [Partner].[LoanApp_BidID]			= [Bid].[LoanApp_BidID]
		LEFT JOIN	[tblLoanApp_Bids_Fax]			[FAX]					WITH (NOLOCK) ON [Bid].[LoanApp_BidID]				= [FAX].[LoanApp_BidID]
		LEFT JOIN	tblLoanApp_Worksheet			[Worksheet]				WITH (NOLOCK) ON [Bid].[LoanApp_BidID]				= [Worksheet].[LoanApp_BidID] AND [Worksheet].[ACTIVE]=1
		LEFT JOIN	[tblLoanApp_BidFundingStatus]	[FUNDING_STATUS]		WITH (NOLOCK) ON [Bid].[LoanApp_BidID]				= [FUNDING_STATUS].[LoanApp_BidID]
		LEFT JOIN	[tblLenderDealerRelation]		[LenderDealerRelation]	WITH (NOLOCK) ON [LenderDealerRelation].[DealerID]	= [DEALER].[DealerID] AND [Branch].[LenderID] = [LenderDealerRelation].[LenderID]
		LEFT JOIN	[tblLendersLogins]				[LenderLogin]			WITH (NOLOCK) ON [LenderLogin].[LendersLoginID]		= [LenderDealerRelation].[LenderAgentID]
		LEFT JOIN	[tblLendersBranchLogins]		[BranchLogin]			WITH (NOLOCK) ON [BranchLogin].[LendersBranchLoginID]	= [LenderDealerRelation].[LenderBranchAgentID]
		LEFT JOIN	[tblLoanAppAssignedDealers]		[AssignedDealer]		WITH (NOLOCK) ON [AssignedDealer].[LoanAppID]			= [AUTO_LOAN_APP].[LoanAppID]
		LEFT JOIN	[tblDealersLogins]				[DealerLogin]			WITH (NOLOCK) ON [DealerLogin].[DealersLoginID]			= [AssignedDealer].[DealersLoginID]
		LEFT JOIN	[viewDealersDefaultAssetType]	[ASSET_TYPE]			WITH (NOLOCK) ON [ASSET_TYPE].[DealerID]				= [DEALER].[DealerID] AND [ASSET_TYPE].[IsDefault] = 1
	WHERE
		[Bid].[LoanApp_BidID]				>	2622648							AND
--		[Bid].[LoanAppID]					>	2765878							AND
		[Bid].[UpdateDateTime]				>=	DATEADD(day, -30, GETDATE())	AND
		[AUTO_LOAN_APP].[CreateDateTime]	>=	DATEADD(day, -30, GETDATE())	AND
		[AUTO_LOAN_APP].[Archived]			!=	1								AND
	  ([Bid].[STATUS] IN('ACCEPTED','REFERRED', 'PENDING_DEALER', 'DECLINE_LENDER', 'PENDING_LENDER', 'PENDING_AUTOMATION', 'PROCESSING_AUTOMATION', 'B2B_ERROR', 'PENDING_B2B', 'DUPLICATE') OR [Bid].[MESSAGING_STATUS] IN ('COMMENT_FOR_DEALER') OR [Funding_Status].[BidFundingStatus] IN ('REJECTED'))


