/****** Object:  View dbo.viewInterfaceDealerNewDeals_BACKUP_2014_03_25    Script Date: 7/31/2024 12:57:24 PM ******/

CREATE VIEW viewInterfaceDealerNewDeals_BACKUP_2014_03_25 AS

	SELECT
		BID.LoanAppID,
		BID.LoanApp_BidID,
		DEALER.DealerID,
		AUTO_LOAN_APP.APPLICANT_NAMES,
		BID.YIELD_TYPE,
		COMMENTS = '',

	TERM = CASE
		WHEN TERM IS NULL 				THEN NULL
		WHEN ISNUMERIC(TERM) = 1		THEN TERM
		WHEN TERM = ''					THEN NULL
		WHEN CHARINDEX('M', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('M', TERM) - 1))
		WHEN CHARINDEX('/', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX('/', TERM) - 1))
		WHEN CHARINDEX(' ', TERM) > 0	THEN CONVERT(INT, LEFT(TERM, CHARINDEX(' ', TERM) - 1))
		ELSE -1
	END,
		PAYMENT,
		MESSAGING_STATUS,
		REBATE_PERCT,
		ADVANCE,
		LENDER.LenderID,

