/****** Object:  View dbo.viewInterfaceLenderNewDeals_L    Script Date: 7/31/2024 12:57:24 PM ******/



CREATE  VIEW [dbo].[viewInterfaceLenderNewDeals_L] AS

SELECT --TOP 10
	DEALS.*,
	LOCKS.LockedSince,
	LOCKS.LockExpires,
	LOCKS.LockedBy,
	Locked = CONVERT(BIT, CASE
		WHEN LOCKS.LockedBy 		IS NULL		THEN 0	
		WHEN LOCKS.LockedSince		IS NULL		THEN 0
		WHEN LOCKS.LockedBy			IS NULL		THEN 0
		WHEN LOCKS.LockExpires < GETDATE()	THEN 0
		ELSE 1
	END)

FROM
					viewInterfaceLenderNewDeals		DEALS	
	LEFT OUTER JOIN viewUnderwritingLocks			LOCKS	ON ISNULL(LOCKS.LenderID, DEALS.LenderID) = DEALS.LenderID AND LOCKS.LoanAppID = DEALS.LoanAppID

--WHERE	Deals.LenderID = 366





