/*
SELECT TOP 50 * FROM viewInterfaceSearch
WHERE 
	LenderID = 1224 AND BidCreateDateTime >= '1/1/2021'

RETURN

*/
CREATE    VIEW [dbo].[viewInterfaceSearch] AS
	SELECT --TOP 25

	TERM	= CASE
		WHEN BID.TERM				IS	NULL													THEN NULL
		WHEN BID.TERM				=	''														THEN NULL
		WHEN ISNUMERIC(BID.TERM)		=	1														THEN BID.TERM
		WHEN ISNUMERIC(REPLACE(REPLACE(REPLACE(BID.TERM, ' ', ''), 'M', ''), 'O', ''))	=	1	THEN REPLACE(REPLACE(REPLACE(BID.TERM, ' ', ''), 'M', ''), 'O', '')
		ELSE NULL END,

	APPLICATION.LoanAppID,
	BID.LoanApp_BidID,
	APPLICATION.DealerID,

	APPLICANT_NAMES		= UPPER(APPLICATION.APPLICANT_NAMES),

	BidAge = DATEDIFF(day, BID.UpdateDateTime, GetDate()),
	LENDER_ARCHIVED = ISNULL(BID.LENDER_ARCHIVED, 0),

	Canceled = CASE
		WHEN Canceled_Date IS NULL THEN CONVERT(BIT, 0)
		ELSE CONVERT(BIT, 1)
	End,

	Canceled_Date,


	Funded = CASE
		WHEN BID.FUNDED_DATE IS NOT NULL THEN CONVERT(BIT, 1)
		WHEN BID.Funded IS NULL THEN CONVERT(BIT, 0)
		ELSE CONVERT(BIT, BID.Funded)
	End,


	DEALER_CREDIT_WANTS_EX = CASE
		WHEN LEN(ISNULL(APPLICATION.DEALER_CREDIT_EX, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(APPLICATION.DEALER_CREDIT_WANTS_EX, 0)
	END,

	DEALER_CREDIT_WANTS_EQ = CASE
		WHEN LEN(ISNULL(APPLICATION.DEALER_CREDIT_EQ, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(APPLICATION.DEALER_CREDIT_WANTS_EQ, 0)
	END,

	DEALER_CREDIT_WANTS_TU = CASE
		WHEN LEN(ISNULL(APPLICATION.DEALER_CREDIT_TU, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(APPLICATION.DEALER_CREDIT_WANTS_TU, 0)
	END,

	DEALER_CREDIT_EX		= ISNULL(APPLICATION.DEALER_CREDIT_EX, ''),
	DEALER_CREDIT_EQ		= ISNULL(APPLICATION.DEALER_CREDIT_EQ, ''),
	DEALER_CREDIT_TU		= ISNULL(APPLICATION.DEALER_CREDIT_TU, ''),

	LENDER_CREDIT_WANTS_EX = CASE
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_EX, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(BID.LENDER_CREDIT_WANTS_EX, 0)
	END,

	LENDER_CREDIT_WANTS_EQ = CASE
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_EQ, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(BID.LENDER_CREDIT_WANTS_EQ, 0)
	END,

	LENDER_CREDIT_WANTS_TU = CASE
		WHEN LEN(ISNULL(BID.LENDER_CREDIT_TU, '')) > 0	THEN CONVERT(BIT, 1)
		ELSE ISNULL(BID.LENDER_CREDIT_WANTS_TU, 0)
	END,

	LENDER_CREDIT_EX		= ISNULL(BID.LENDER_CREDIT_EX, ''),
	LENDER_CREDIT_EQ		= ISNULL(BID.LENDER_CREDIT_EQ, ''),
	LENDER_CREDIT_TU		= ISNULL(BID.LENDER_CREDIT_TU, ''),

	LenderID          = LENDER.LenderID,



