			WHEN ISNUMERIC(REPLACE(REPLACE(REPLACE(APPLICATION.LOAN_TERM_REQUESTED, ' ', ''), 'M', ''), 'O', ''))	=	1	THEN REPLACE(REPLACE(REPLACE(APPLICATION.LOAN_TERM_REQUESTED, ' ', ''), 'M', ''), 'O', '')
