    LOAN_LICENSE_TAXABLE            = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_LICENSE_TAXABLE        ELSE    WS.LOAN_LICENSE_TAXABLE         END,
    LOAN_DOCSMOG_TAXABLE            = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_DOCSMOG_TAXABLE        ELSE    WS.LOAN_DOCSMOG_TAXABLE         END,
