/****** Object:  View dbo.viewInterfaceSearch1    Script Date: 7/31/2024 12:57:24 PM ******/



CREATE VIEW viewInterfaceSearch1 AS
SELECT DISTINCT
	TERM = CASE
		WHEN BID.TERM IS NULL 				THEN NULL
		WHEN ISNUMERIC(BID.TERM) = 1		THEN BID.TERM
		WHEN BID.TERM = ''					THEN NULL
