		WHEN REPLACE(BID.Rate, ',', '.') IS NULL 			THEN CONVERT(DECIMAL(6, 2), NULL)
		WHEN LEN(REPLACE(BID.Rate, ',', '.')) = 0			THEN CONVERT(DECIMAL(6, 2), NULL)
		WHEN ISNUMERIC(REPLACE(BID.Rate, ',', '.'))=1		THEN CONVERT(DECIMAL(6, 2), REPLACE(BID.Rate, ',', '.'))
		WHEN RIGHT(REPLACE(BID.Rate, ',', '.'), 1) = '$'	THEN CONVERT(DECIMAL(6, 2), SUBSTRING(REPLACE(BID.Rate, ',', '.'), 1, LEN(REPLACE(BID.Rate, ',', '.')) - 1))
		WHEN RIGHT(REPLACE(BID.Rate, ',', '.'), 1) = '%'	THEN CONVERT(DECIMAL(6, 2), SUBSTRING(REPLACE(BID.Rate, ',', '.'), 1, LEN(REPLACE(BID.Rate, ',', '.')) - 1))
	END,

	BID.Stips,
	BID.Reason,
