	LOAN_DOWN_PAYMENT			= CASE WHEN WS.LoanApp_WorksheetID	IS NULL	THEN	APPLICATION.LOAN_DOWN_PAYMENT			ELSE	WS.LOAN_DOWN_PAYMENT		END,
	LOAN_ESTIMATED_PAYMENT		= CASE WHEN WS.LoanApp_WorksheetID	IS NULL	THEN	APPLICATION.LOAN_ESTIMATED_PAYMENT		ELSE	WS.LOAN_ESTIMATED_PAYMENT	END,
	LOAN_LICENSE				= CASE WHEN WS.LoanApp_WorksheetID	IS NULL	THEN	APPLICATION.LOAN_LICENSE				ELSE	WS.LOAN_LICENSE				END,
