			WHEN APPLICATION.LOAN_TERM_REQUESTED				=	''														THEN NULL
			WHEN ISNUMERIC(APPLICATION.LOAN_TERM_REQUESTED)		=	1														THEN APPLICATION.LOAN_TERM_REQUESTED
			WHEN ISNUMERIC(REPLACE(REPLACE(REPLACE(APPLICATION.LOAN_TERM_REQUESTED, ' ', ''), 'M', ''), 'O', ''))	=	1	THEN REPLACE(REPLACE(REPLACE(APPLICATION.LOAN_TERM_REQUESTED, ' ', ''), 'M', ''), 'O', '')
			ELSE NULL END
		ELSE CASE
