	VEHICLE_VIN						= CASE WHEN WS.LoanApp_WorksheetID	IS NULL	THEN	APPLICATION.VEHICLE_VIN				ELSE	WS.VEHICLE_VIN					END,
	VEHICLE_YEAR					= CASE WHEN WS.LoanApp_WorksheetID	IS NULL	THEN	APPLICATION.VEHICLE_YEAR			ELSE	WS.VEHICLE_YEAR					END,
	VEHICLE_TYPE					= CASE WHEN WS.LoanApp_WorksheetID	IS NULL	THEN	APPLICATION.VEHICLE_TYPE			ELSE	WS.VEHICLE_TYPE					END,

	VEHICLE							= ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), APPLICATION.VEHICLE_YEAR) + ' ' + APPLICATION.VEHICLE_MAKE + ' ' + APPLICATION.VEHICLE_MODEL),

	WorksheetID						= WS.LoanApp_WorksheetID,
	LoanAppComments					= CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.COMMENTS					ELSE    WS.COMMENTS            			END,
    LOAN_TRADE_IN_NET               = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_TRADE_IN_NET           ELSE    WS.LOAN_TRADE_IN_NET            END,
    LOAN_LICENSE_TAXABLE            = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_LICENSE_TAXABLE        ELSE    WS.LOAN_LICENSE_TAXABLE         END,
    LOAN_DOCSMOG_TAXABLE            = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_DOCSMOG_TAXABLE        ELSE    WS.LOAN_DOCSMOG_TAXABLE         END,
    SMOG_CERTIFY_FEE                = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.SMOG_CERTIFY_FEE            ELSE    WS.SMOG_CERTIFY_FEE             END,
    SMOG_CERTIFY_FEE_TAXABLE        = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.SMOG_CERTIFY_FEE_TAXABLE    ELSE    WS.SMOG_CERTIFY_FEE_TAXABLE     END,
    SMOG_SELLER_FEE                 = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.SMOG_SELLER_FEE             ELSE    WS.SMOG_SELLER_FEE              END,
    SMOG_SELLER_FEE_TAXABLE         = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.SMOG_SELLER_FEE_TAXABLE     ELSE    WS.SMOG_SELLER_FEE_TAXABLE      END,
    LOAN_GAP                        = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_GAP                    ELSE    WS.LOAN_GAP                     END,
    LOAN_GAP_TAXABLE                = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_GAP_TAXABLE            ELSE    WS.LOAN_GAP_TAXABLE             END,
    LOAN_WARRANTY_TAXABLE           = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_WARRANTY_TAXABLE       ELSE    WS.LOAN_WARRANTY_TAXABLE        END,
    LOAN_MISC2                      = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_MISC2                  ELSE    WS.LOAN_MISC2                   END,
    LOAN_MISC_TAXABLE               = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.LOAN_MISC_TAXABLE           ELSE    WS.LOAN_MISC_TAXABLE            END,
    NEW_USED                        = CASE WHEN WS.LoanApp_WorksheetID  IS NULL THEN    APPLICATION.NEW_USED                    ELSE    WS.NEW_USED                     END,

	APPLICATION.REMINDER_DATE,
	APPLICATION.LenderID AS LenderDealerID,

	FAX.Fax_Status,
	FAX.Fax_LastUpdate,

	RESUBMIT_POLICY=ISNULL(LENDER.RESUBMIT_POLICY, 'NOT_ALLOWED'),

	PartnerName = DBO.FormatPartnerName(PARTNER.Partner),
	--PartnerName = '',

	BidFundingStatus	= ISNULL(FUNDING.BidFundingStatus, ''),
	FUNDING.StatusUpdateDateTime,

	LenderAgentName = CASE
		WHEN ASSIGNMENT.LendersLoginID IS NULL		THEN ''
		WHEN LEN(ISNULL(ASSIGNMENT.LenderFullName, '')) > 0		THEN DBO.ProperCase(ASSIGNMENT.LenderFullName)
		WHEN LEN(ISNULL(ASSIGNMENT.LenderUserName, '')) > 0		THEN ASSIGNMENT.LenderUserName
		ELSE 'Agent of ' + LENDER.LenderName
	End,

	BranchAgentName = CASE
		WHEN ASSIGNMENT.LendersBranchLoginID IS NULL		THEN ''
		WHEN LEN(ISNULL(ASSIGNMENT.BranchFullName, '')) > 0		THEN DBO.ProperCase(ASSIGNMENT.BranchFullName)
		WHEN LEN(ISNULL(ASSIGNMENT.BranchUserName, '')) > 0		THEN ASSIGNMENT.BranchUserName
		ELSE 'Agent of ' + LENDER_BRANCH.BranchName
	End,

	DealerSalesPerson = CASE
		WHEN ASSIGNMENT.DealersLoginID IS NULL					THEN ''
		WHEN LEN(ISNULL(ASSIGNMENT.DealerFullName, '')) > 0		THEN DBO.ProperCase(ASSIGNMENT.DealerFullName)
		WHEN LEN(ISNULL(ASSIGNMENT.DealerUserName, '')) > 0		THEN ASSIGNMENT.DealerUserName
		ELSE 'Sales Person at ' + DBO.ProperCase(DEALER.DealerName)
	End,

	rowVersion = ISNULL(APPLICATION.rowVersion, 0),

	CreateUser                  = ISNULL(ISNULL(APPLICATION.CreateUser, APPLICATION.UpdateUser), ''),
	UpdateUser                  = ISNULL(ISNULL(APPLICATION.UpdateUser, APPLICATION.CreateUser), ''),
	--CreateDateTime              = ISNULL(APPLICATION.CreateDateTime, APPLICATION.UpdateDateTime),
	--UpdateDateTime              = ISNULL(APPLICATION.UpdateDateTime, APPLICATION.CreateDateTime),

	CreateDateTime              = APPLICATION.CreateDateTime,
	UpdateDateTime              = APPLICATION.UpdateDateTime,


	BidCreateUser               = ISNULL(ISNULL(BID.CreateUser, Bid.UpdateUser), ''),
	BidUpdateUser               = ISNULL(ISNULL(Bid.UpdateUser, BID.CreateUser), ''),


	--BidCreateDateTime           = ISNULL(BID.CreateDateTime, Bid.UpdateDateTime),
	--BidUpdateDateTime           = ISNULL(Bid.UpdateDateTime, BID.CreateDateTime)

	BidCreateDateTime           = Bid_Date.Submit_Date,
--BID.CreateDateTime,
	BidUpdateDateTime           = Bid.UpdateDateTime,
	BidUpdateDate		    = DATEADD(dd, 0, DATEDIFF(dd, 0, Bid.UpdateDateTime))


FROM
  						tblLoanApps					APPLICATION		WITH (NOLOCK)
    LEFT	OUTER JOIN	tblLoanApp_Bids				BID				WITH (NOLOCK) ON APPLICATION.LoanAppID		= BID.LoanAppID
--	LEFT	OUTER JOIN	viewLoanPartner				PARTNER			WITH (NOLOCK) ON APPLICATION.LoanAppID = PARTNER.LoanAppID
	LEFT	OUTER JOIN	viewBid_PartnerInformation	Partner			WITH (NOLOCK) ON Partner.LoanApp_BidID		= Bid.LoanApp_BidID
    --LEFT	OUTER JOIN	viewLenderBranches			LENDER_BRANCH	WITH (NOLOCK) ON BID.LendersBranchID		= LENDER_BRANCH.LendersBranchID
	LEFT	OUTER JOIN	tblLendersBranches			LENDER_BRANCH	WITH (NOLOCK) ON BID.LendersBranchID		= LENDER_BRANCH.LendersBranchID
    LEFT	OUTER JOIN	tblLenders 					LENDER			WITH (NOLOCK) ON LENDER_BRANCH.LenderID		= LENDER.LenderID
	LEFT	OUTER JOIN	viewBidsFaxStatus			FAX 			WITH (NOLOCK) ON FAX.LoanApp_BidID			= BID.LoanApp_BidID

	LEFT	OUTER JOIN	viewBidsLoanAppAssignment	ASSIGNMENT		WITH (NOLOCK) ON ASSIGNMENT.LoanApp_BidID	= BID.LoanApp_BidID

	LEFT	OUTER JOIN	viewBidsFundingStatus		FUNDING 		WITH (NOLOCK) ON FUNDING.LoanApp_BidID		= BID.LoanApp_BidID

	LEFT	OUTER JOIN	tblDealers					DEALER			WITH (NOLOCK) ON APPLICATION.DealerID		= DEALER.DealerID
--    LEFT	OUTER JOIN	tblLoanApp_Worksheet		WS 				WITH (NOLOCK) ON BID.LoanApp_BidID			= WS.LoanApp_BidID AND WS.ACTIVE=1


    LEFT	OUTER JOIN	tblLoanApp_Worksheet		WS 				WITH (NOLOCK) ON WS.LoanApp_WorksheetID		IN (
		SELECT 
			LoanApp_WorksheetID = MAX(UW_Inner.LoanApp_WorksheetID)
		FROM
			tblLoanApp_Worksheet 	UW_Inner	WITH (NOLOCK)
		WHERE
			UW_Inner.LoanApp_BidID		= BID.LoanApp_BidID		AND
			UW_Inner.Active				= 1
	)


    LEFT	OUTER JOIN	tblLoanApp_Underwriting		UW 				WITH (NOLOCK) ON BID.LoanAppID				= UW.LoanAppID AND LENDER.LenderID = UW.LenderID

	LEFT	OUTER JOIN	viewBids_Date_Rollup		Bid_Date		WITH (NOLOCK) ON Bid.LoanAppID				= Bid_Date.LoanAppID	AND Bid_Date.LenderID = Lender.LenderID

--WHERE
--	(Lender.LenderID = 1227) AND Bid.[LoanAPPID] IN ('1709317')



