--	FUNDING_TERM = CONVERT(INT, UW.FUNDING_TERM),
	FUNDING_FINANCED_AMOUNT 			= UW.FUNDING_FINANCED_AMOUNT,
    FUNDING_RATE                        = UW.FUNDING_RATE,
    FUNDING_REBATE                      = UW.FUNDING_REBATE,
    FUNDING_FEES                        = UW.FUNDING_FEES,
    FUNDING_RESERVE                     = UW.FUNDING_RESERVE,
    FUNDING_DISCOUNT_FEE                = UW.FUNDING_DISCOUNT_FEE,
    FUNDING_MONTHLY_PAYMENT             = UW.FUNDING_MONTHLY_PAYMENT,
    FUNDING_TOTAL_PAYMENTS              = UW.FUNDING_TOTAL_PAYMENTS,
    Funding_Comments                    = UW.Comments,
    FUNDING_METHOD                      = UW.FUNDING_METHOD,
    CONTRACT_DATE                       = UW.CONTRACT_DATE,
