		WHEN ASSIGNMENT.LendersBranchLoginID IS NULL		THEN ''
		WHEN LEN(ISNULL(ASSIGNMENT.BranchFullName, '')) > 0		THEN ASSIGNMENT.BranchFullName
		WHEN LEN(ISNULL(ASSIGNMENT.BranchUserName, '')) > 0		THEN ASSIGNMENT.BranchUserName
		ELSE 'Agent of ' + LENDER_BRANCH.BranchName
	End,

	DealerSalesPerson = CASE
		WHEN ASSIGNMENT.DealersLoginID IS NULL					THEN ''
		WHEN LEN(ISNULL(ASSIGNMENT.DealerFullName, '')) > 0		THEN ASSIGNMENT.DealerFullName
		WHEN LEN(ISNULL(ASSIGNMENT.DealerUserName, '')) > 0		THEN ASSIGNMENT.DealerUserName
		ELSE 'Sales Person at ' + DEALER.DealerName
	End,

	rowVersion = ISNULL(APPLICATION.rowVersion, 0),

