	BidUpdateDateTime           = ISNULL(Bid.UpdateDateTime, BID.CreateDateTime)


FROM
  						tblLoanApps					APPLICATION		WITH (NOLOCK)
    LEFT	OUTER JOIN	tblLoanApp_Bids				BID				WITH (NOLOCK) ON APPLICATION.LoanAppID		= BID.LoanAppID
	LEFT	OUTER JOIN	viewLoanPartner				PARTNER			WITH (NOLOCK) ON APPLICATION.LoanAppID = PARTNER.LoanAppID
--	LEFT	OUTER JOIN	viewBidsPartnerTool			PARTNER 		WITH (NOLOCK) ON BID.LoanApp_BidID			= PARTNER.LoanApp_BidID
--			JOIN	viewBidsPartnerTool			PARTNER 		WITH (NOLOCK) ON BID.LoanApp_BidID			= PARTNER.LoanApp_BidID
    LEFT	OUTER JOIN	viewLenderBranches			LENDER_BRANCH	WITH (NOLOCK) ON BID.LendersBranchID		= LENDER_BRANCH.LendersBranchID
    LEFT	OUTER JOIN	tblLenders 					LENDER			WITH (NOLOCK) ON LENDER_BRANCH.LenderID		= LENDER.LenderID
	LEFT	OUTER JOIN	viewBidsFaxStatus			FAX 			WITH (NOLOCK) ON FAX.LoanApp_BidID			= BID.LoanApp_BidID
	LEFT	OUTER JOIN	viewBidsLoanAppAssignment	ASSIGNMENT		WITH (NOLOCK) ON ASSIGNMENT.LoanApp_BidID	= BID.LoanApp_BidID
	LEFT	OUTER JOIN	viewBidsFundingStatus		FUNDING 		WITH (NOLOCK) ON FUNDING.LoanApp_BidID		= BID.LoanApp_BidID
	LEFT	OUTER JOIN	tblDealers					DEALER			WITH (NOLOCK) ON APPLICATION.DealerID		= DEALER.DealerID
    LEFT	OUTER JOIN	tblLoanApp_Worksheet		WS 				WITH (NOLOCK) ON BID.LoanApp_BidID			= WS.LoanApp_BidID AND WS.ACTIVE=1
    LEFT	OUTER JOIN	tblLoanApp_Underwriting		UW 				WITH (NOLOCK) ON BID.LoanAppID				= UW.LoanAppID AND LENDER.LenderID = UW.LenderID


