/****** Object:  View dbo.viewKBB_MakeModelTrim    Script Date: 7/31/2024 12:57:24 PM ******/


CREATE VIEW viewKBB_MakeModelTrim AS

SELECT TOP 100 PERCENT
	MAKE.ManID,
	MAKE.ManName,
	MODEL.ModelID,
	MODEL.ModelName,
	TRIM.TrimID,
	TRIM.TrimName

FROM
	tblKBB_Makes MAKE,
	tblKBB_Models MODEL,
	tblKBB_Trim TRIM

WHERE
			MAKE.ManID = MODEL.ManID
	AND	MODEL.ManID = TRIM.ManID
	AND	MODEL.ModelID = TRIM.ModelID

ORDER BY
		MAKE.ManName,
		MODEL.ModelName,
		TRIM.TrimName





