/****** Object:  View dbo.viewLenderProgramStats    Script Date: 7/31/2024 12:57:24 PM ******/


CREATE VIEW dbo.viewLenderProgramStats
AS
SELECT     TOP 100 PERCENT dbo.tblPrograms.LenderID, dbo.tblPrograms.ProgramID, dbo.tblPrograms.ProgramName, dbo.tblPrograms.CreditTier,
                      dbo.tblPrograms.Active, dbo.tblPrograms.Automated, dbo.tblPrograms.Underwriting, dbo.tblPrograms.AutoSelect,
                      COUNT(dbo.tblProgramFilter.ProgramFilterID) AS ProgramFilterCount, SUM(ISNULL(dbo.viewProgramFilterStatistics.ParameterCount, 0))
                      AS ParameterValueCount
FROM         dbo.viewProgramFilterStatistics INNER JOIN
                      dbo.tblProgramFilter ON dbo.viewProgramFilterStatistics.ProgramFilterID = dbo.tblProgramFilter.ProgramFilterID RIGHT OUTER JOIN
                      dbo.tblPrograms ON dbo.tblProgramFilter.ProgramID = dbo.tblPrograms.ProgramID
GROUP BY dbo.tblPrograms.LenderID, dbo.tblPrograms.ProgramID, dbo.tblPrograms.ProgramName, dbo.tblPrograms.CreditTier, dbo.tblPrograms.Active,
                      dbo.tblPrograms.Automated, dbo.tblPrograms.Underwriting, dbo.tblPrograms.AutoSelect
ORDER BY dbo.tblPrograms.LenderID, dbo.tblPrograms.ProgramID






