/****** Object:  View dbo.viewLendersProgramStatus    Script Date: 7/31/2024 12:57:24 PM ******/

CREATE VIEW viewLendersProgramStatus AS
	SELECT
		[LenderID]					= [Programs].[LenderID],
		[LendersBranchID]			= [Branch].[LendersBranchID],
		[LenderStatus]				= [Programs].[LenderStatus],
		--[Lender]					= [Programs].[Lender],
		[HasPrograms]				= CONVERT(BIT, CASE WHEN [Programs].[Programs] = 0 THEN 0 ELSE 1 END),
		[Programs]					= [Programs].[Programs],
		[HasUnderwritingPrograms]	= CONVERT(BIT, CASE WHEN [Programs].[UnderwritingPrograms] = 0 THEN 0 ELSE 1 END),
		[UnderwritingPrograms]		= [Programs].[UnderwritingPrograms],
		[HasAutomatedPrograms]		= CONVERT(BIT, CASE WHEN [Programs].[AutoOfferPrograms] > 0 THEN 1 WHEN [Programs].[AutoDeclinePrograms] > 0 THEN 1 ELSE 0 END),
		[AutomatedPrograms]			= [Programs].[AutoOfferPrograms] + [Programs].[AutoDeclinePrograms],
		[HasAutoOfferPrograms]		= CONVERT(BIT, CASE WHEN [Programs].[AutoOfferPrograms] = 0 THEN 0 ELSE 1 END),
		[AutoOfferPrograms]			= [Programs].[AutoOfferPrograms],
		[HasAutoDeclinePrograms]	= CONVERT(BIT, CASE WHEN [Programs].[AutoDeclinePrograms] = 0 THEN 0 ELSE 1 END),
		[AutoDeclinePrograms]		= [Programs].[AutoDeclinePrograms]
	FROM
				[tblLenders]						[Lender]	WITH (NOLOCK)
		JOIN	[tblLendersBranches]				[Branch]	WITH (NOLOCK) ON [Branch].[LenderID]	= [Lender].[LenderID]
		JOIN	[viewLendersProgramStatus_Inner]	[Programs]	WITH (NOLOCK) ON [Programs].[LenderID]	= [Lender].[LenderID]


