/****** Object:  View dbo.viewLoanApp_LES    Script Date: 7/31/2024 12:57:24 PM ******/


CREATE VIEW viewLoanApp_LES AS
  SELECT
    LoanAppID                                   = APPLICANT.LoanAppID,
    LoanApp_MilitaryLESID                       = LES.LoanApp_MilitaryLESID,
    LoanApp_MilitaryLES_AlotmentID              = LoanApp_MilitaryLES_AlotmentID,
    LoanApp_MilitaryLES_DeductionID             = NULL,
    LoanApp_MilitaryLES_EarningID               = NULL,
    Type                                        = 'ALLOTMENTS',
    AMOUNT,
    CATEGORY,
    DESCRIPTION,
    ALLOTMENTS.CreateDateTime,
    ALLOTMENTS.UpdateDateTime,
    ALLOTMENTS.CreateUser,
    ALLOTMENTS.UpdateUser,
    ALLOTMENTS.rowVersion
  FROM
    tblLoanApp_Applicant    APPLICANT
      JOIN tblLoanApp_MilitaryLES                 LES             ON (LES.LoanApp_ApplicantID = APPLICANT.LoanApp_ApplicantID)
      JOIN tblLoanApp_MilitaryLES_Allotments      ALLOTMENTS      ON (LES.LoanApp_MilitaryLESID = ALLOTMENTS.LoanApp_MilitaryLESID)

  UNION ALL

  SELECT
    LoanAppID                                   = APPLICANT.LoanAppID,
    LoanApp_MilitaryLESID                       = LES.LoanApp_MilitaryLESID,
    LoanApp_MilitaryLES_AlotmentID              = NULL,
    LoanApp_MilitaryLES_DeductionID             = LoanApp_MilitaryLES_DeductionID,
    LoanApp_MilitaryLES_EarningID               = NULL,
    Type                                        = 'DEDUCTIONS',
    AMOUNT,
    CATEGORY,
    DESCRIPTION,
    DEDUCTIONS.CreateDateTime,
    DEDUCTIONS.UpdateDateTime,
    DEDUCTIONS.CreateUser,
    DEDUCTIONS.UpdateUser,
    DEDUCTIONS.rowVersion
  FROM
    tblLoanApp_Applicant    APPLICANT
      JOIN tblLoanApp_MilitaryLES                 LES             ON (LES.LoanApp_ApplicantID = APPLICANT.LoanApp_ApplicantID)
      JOIN tblLoanApp_MilitaryLES_Deductions      DEDUCTIONS      ON (LES.LoanApp_MilitaryLESID = DEDUCTIONS.LoanApp_MilitaryLESID)

  UNION ALL

  SELECT
    LoanAppID                                   = APPLICANT.LoanAppID,
    LoanApp_MilitaryLESID                       = LES.LoanApp_MilitaryLESID,
    LoanApp_MilitaryLES_AlotmentID              = NULL,
    LoanApp_MilitaryLES_DeductionID             = NULL,
    LoanApp_MilitaryLES_EarningID               = LoanApp_MilitaryLES_EarningID,
    Type                                        = 'EARNINGS',
    AMOUNT,
    CATEGORY,
    DESCRIPTION,
    EARNINGS.CreateDateTime,
    EARNINGS.UpdateDateTime,
    EARNINGS.CreateUser,
    EARNINGS.UpdateUser,
    EARNINGS.rowVersion
  FROM
    tblLoanApp_Applicant    APPLICANT
      JOIN tblLoanApp_MilitaryLES                 LES             ON (LES.LoanApp_ApplicantID = APPLICANT.LoanApp_ApplicantID)
      JOIN tblLoanApp_MilitaryLES_Earnings        EARNINGS        ON (LES.LoanApp_MilitaryLESID = EARNINGS.LoanApp_MilitaryLESID)






