/****** Object:  View dbo.viewLoginNames_HTML    Script Date: 7/31/2024 12:57:24 PM ******/
--DECLARE @UID VARCHAR(60);SET @UID='koconnor@SALI55428';
--SET @UID='CSMarts_Internal\erik';

CREATE VIEW viewLoginNames_HTML AS

SELECT 
	UserID, AltUserID, Type, Company, SubCompany, CompanyCode, UserName, Name, Description,
	HTML_Title= ' TITLE="' + 

	REPLACE(	CHAR(10) + 

														CHAR(9) +	'Name:'			+ REPLICATE(CHAR(9),	13)	+ Name			+ CHAR(9) + CHAR(10) + CHAR(10) +
														CHAR(9) +	'Company:'		+ REPLICATE(CHAR(9),	 6)	+ Company		+ CHAR(9) + CHAR(10) + CHAR(10) +
				CASE WHEN LEN(Description) > 0	THEN	CHAR(9) +	'Description:'	+ REPLICATE(CHAR(9),	 3) + Description	+ CHAR(9) + CHAR(10) + CHAR(10) ELSE '' END +
				CASE WHEN UserName <> Name 		THEN	CHAR(9) +	'User ID:'		+ REPLICATE(CHAR(9),	 8) + UserName		+ CHAR(9) + CHAR(10) + CHAR(10) ELSE '' END,

				'"', '''')
+ '" '

FROM 
	viewLoginNames 
--WHERE @UID IN (UserID, AltUserID)

