/****** Object:  View dbo.viewPartnerDataElementValues_Outer    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW [viewPartnerDataElementValues_Outer] AS
			SELECT
						[PartnerLender].[PartnerToolID], [Bid].[LoanApp_BidID], [Value].[Field], [Value].[PartnerDataElementID],
						MIN(CASE WHEN [Value].[LoanApp_BidID] <> 0 THEN 90 WHEN [Value].[LoanAppID] <> 0 THEN 30 ELSE 0 END + CASE WHEN [Value].[LendersBranchID] <> 0 THEN 50 WHEN [Value].[LenderID] <> 0 THEN 20 ELSE 0 END + CASE WHEN [Value].[DealerID] <> 0 THEN 10 ELSE 0 END + CASE WHEN [Value].[PartnerToolID] <> 0 THEN 5 ELSE 0 END) [Score]
						, MIN([Value].[UpdateDateTime]) [UpdateDateTime], MIN([Value].[DataValue]) [DataValue]
				FROM
											[tblPartnerDataElement]						[Value]								WITH (NOLOCK)
								JOIN	[viewPartnerLenderSetup] 					[PartnerLender]				WITH (NOLOCK)	ON	[Value].[PartnerToolID]				 = [PartnerLender].[PartnerToolID]
								JOIN	[viewPartnerFieldDefinitions]			[Field]								WITH (NOLOCK)	ON 	[Field].[PartnerToolID]				 = [PartnerLender].[PartnerToolID]					AND	[Field].[Field]						 = [Value].[Field]		AND ([Value].[LoanAppID] > 0 OR [Value].[LoanApp_BidID] > 0)
--					LEFT	JOIN	[viewPartnerIdentifierFields]			[Fields]							WITH (NOLOCK)	ON	[Fields].[PartnerToolID]		 = [Value].[PartnerToolID]
					LEFT	JOIN	[tblLoanApp_Bids]									[Bid_App]							WITH (NOLOCK)	ON	[Field].[KeyedFromLoan]				 = 1															AND	[Value].[LoanAppID] 									<> 0														AND	[Bid_App].[LoanAppID]										 = [Value].[LoanAppID]
					LEFT	JOIN	[tblLoanApp_Bids]									[Bid_Bid]							WITH (NOLOCK)	ON	[Field].[KeyedFromLoan]				 = 1															AND	[Value].[LoanApp_BidID]								<> 0														AND	[Bid_Bid].[LoanApp_BidID]								 = [Value].[LoanApp_BidID]
								JOIN	[tblLoanApp_Bids]									[Bid]									WITH (NOLOCK)	ON	[Bid].[LoanApp_BidID]								 = ISNULL([Bid_Bid].[LoanApp_BidID], [Bid_App].[LoanApp_BidID])
								JOIN	[tblLendersBranches]							[Branch]							WITH (NOLOCK)	ON	[Branch].[LendersBranchID]					 = [Bid].[LendersBranchID]
--								JOIN	[tblLoanApps]											[App]									WITH (NOLOCK)	ON	[App].[LoanAppID]										 = [Bid].[LoanAppID]
				WHERE
					([Value].[LoanAppID] > 0 OR [Value].[LoanApp_BidID] > 0)
				GROUP BY
					[PartnerLender].[PartnerToolID], [Bid].[LoanApp_BidID], [Value].[Field], [Value].[PartnerDataElementID]

