/****** Object:  View dbo.viewPartnerDecision_ShouldSend    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW viewPartnerDecision_ShouldSend AS








SELECT
	Bid.LoanAppID, 
	PDR.LoanApp_BidID, 
	Branch.LenderID, 
	PDR.PartnerToolID, 
	PDR.PartnerToolsTriggerID, 
	DATEDIFF(mi, PDR.TS_Success, GETDATE()) AS SentAgo, 
	DATEDIFF(mi, PDR.TS_LastError, GETDATE()) AS ErrorAgo, 
	CONVERT(BIT, CASE WHEN TS_Success IS NOT NULL AND TS_Success < Bid.Offer_Date THEN 1 WHEN SuccessCount >= 1 AND TS_Success IS NOT NULL AND DATEDIFF(mi, TS_Success, GETDATE()) < 180 THEN 0 WHEN ErrorCount >= 1 AND TS_LastError IS NOT NULL AND DATEDIFF(mi, TS_LastError, GETDATE()) < 10 THEN 0 WHEN TS_Success IS NULL THEN 1 ELSE 0 END) AS ShouldSend

FROM         
			tblPartnerDecision_Receipt 		PDR	WITH (NOLOCK)
	INNER JOIN	tblLoanApp_Bids 			Bid	WITH (NOLOCK) 	ON Bid.LoanApp_BidID 		= PDR.LoanApp_BidID 
	INNER JOIN	tblLendersBranches 			Branch	WITH (NOLOCK)	ON Branch.LendersBranchID	= Bid.LendersBranchID


GO

