/****** Object:  View dbo.viewPartnersActivatedForBranch    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE  VIEW viewPartnersActivatedForBranch AS
	SELECT
		*
	FROM
		[viewPartnersActivatedForBranch_Inner] [PAB] WITH (NOLOCK)
	
	WHERE
		[PAB].[ActivatedByLendersBranchID] = 1 
		OR NOT EXISTS (
			SELECT
				*
			FROM
				[tblPartnerDataElement] [PDE_Other] WITH (NOLOCK)
				JOIN [tblLendersBranches] [Branch] WITH (NOLOCK) ON [Branch].[LendersBranchID] = [PDE_Other].[LendersBranchID]
			WHERE
				[PDE_Other].[PartnerToolID] = [PAB].[PartnerToolID] AND
				[PDE_Other].[LendersBranchID] = [Branch].[LendersBranchID] AND 
				[PDE_Other].[LoanAppID] = 0 AND
				[PDE_Other].[LoanApp_BidID] = 0 AND
				[PDE_Other].[DealerID] = 0 AND
				[PDE_Other].[Field] = 'Lender Enabled (CreditSmarts)'

		)



