/****** Object:  View dbo.viewUnderwritingLocks    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW [viewUnderwritingLocks] AS
	SELECT
		[LoanAppID]			= [Underwriting].[LoanAppID],
		[LenderID]			= [Underwriting].[LenderID],	
		[LockedSince]		= [Lock].[LockCreateDateTime],
		[LockExpires]		= [Lock].[LockExpireDateTime],
		[LockedBy]			= CASE	WHEN [Lock].[LockedBy] IN ('CSMARTS_INTERNAL/CSmarts_Automation_Credit', 'CSMarts_Internal/AutoOffer', 'CSMarts_Internal/AutoDecline', 'CSMarts_Internal/AutoCredit', 'CSMarts_Internal/Automation') THEN 'Automation'
														WHEN NULLIF([Names].[Name], '') IS NOT NULL THEN [Names].[Name] WHEN [Names].[AltUserID] IS NOT NULL THEN [Names].[AltUserID] 
														ELSE ISNULL(NULLIF([Lock].[LockedBy], ''), 'Unknown') END
		FROM 
											[SYSTEM_LOGICAL_LOCKS] 			[Lock]					WITH (NOLOCK)
			INNER JOIN			[tblLoanApp_Underwriting]		[Underwriting]	WITH (NOLOCK) ON	[Underwriting].[UnderwritingID] = [Lock].[PrimaryKeyValue]
			LEFT OUTER JOIN	[viewLoginNames]						[Names]					WITH (NOLOCK) ON 	[Lock].[LockedBy] = [Names].[UserID]
		WHERE
					[Lock].[Object]							= 'tblLoanApp_Underwriting'
			AND [Lock].[LockExpireDateTime] > GETDATE()
			AND	[Lock].[LockID]							= (SELECT TOP 1 [Lock_Inner].[LockID] FROM [SYSTEM_LOGICAL_LOCKS] [Lock_Inner] WITH (NOLOCK) WHERE [Lock_Inner].[Object] = [Lock].[Object] AND [Lock_Inner].[PrimaryKeyValue] = [Lock].[PrimaryKeyValue] AND [Lock_Inner].[LockExpireDateTime] > GETDATE() ORDER BY [Lock_Inner].[LockExpireDateTime] DESC)


