/****** Object:  View dbo.viewVehicleSubTypes    Script Date: 7/31/2024 12:57:24 PM ******/

CREATE VIEW viewVehicleSubTypes AS
	SELECT TOP 100 PERCENT
		VehicleTypeID				= VEHICLE_SUB_TYPE.VehicleTypeID,
		VehicleSubTypeID			= VEHICLE_SUB_TYPE.VehicleSubTypeID,

		Caption						= CASE
			WHEN VEHICLE_SUB_TYPE.VehicleSubType = VEHICLE_TYPE.VehicleType THEN CASE WHEN LEN(ISNULL(LTRIM(RTRIM(VEHICLE_SUB_TYPE.Caption)), '')) > LEN(ISNULL(LTRIM(RTRIM(VEHICLE_TYPE.Caption)), '')) THEN VEHICLE_SUB_TYPE.Caption ELSE VEHICLE_TYPE.Caption END
			WHEN VEHICLE_TYPE.VehicleType		IN('ATV', 'WATERCRAFT')		THEN VEHICLE_SUB_TYPE.Caption
			ELSE	VEHICLE_TYPE.Caption + ' (' + VEHICLE_SUB_TYPE.Caption + ')'
		END,

		VehicleType					= VEHICLE_TYPE.VehicleType,
		VehicleTypeCaption			= VEHICLE_TYPE.Caption,
		SubTypesOfVehicleType		= VEHICLE_TYPE.SubTypes,
		ManufacturersOfVehicleType	= VEHICLE_TYPE.Manufacturers,

		VehicleSubType				= VEHICLE_SUB_TYPE.VehicleSubType,
		VehicleSubTypeCaption		= VEHICLE_SUB_TYPE.Caption,
		ManufacturersOfSubType		= CONVERT(INT, (SELECT COUNT(DISTINCT M_S.Manufacturer) FROM tblVehicleManufacturers M_S WITH (NOLOCK) WHERE M_S.Active = 1 AND M_S.VehicleSubTypeID = VEHICLE_SUB_TYPE.VehicleSubTypeID))

	FROM
				viewVehicleTypes		VEHICLE_TYPE		WITH (NOLOCK)
		JOIN	tblVehicleSubTypes		VEHICLE_SUB_TYPE	WITH (NOLOCK) ON (VEHICLE_TYPE.VehicleTypeID = VEHICLE_SUB_TYPE.VehicleTypeID)

	WHERE
		VEHICLE_SUB_TYPE.Active = 1

	ORDER BY
		VEHICLE_TYPE.SortOrder,
		VEHICLE_TYPE.VehicleTypeID,
		VEHICLE_SUB_TYPE.SortOrder,
		VEHICLE_SUB_TYPE.VehicleSubTypeID





GO

