/****** Object:  View dbo.viewVehicleTypes    Script Date: 7/31/2024 12:57:24 PM ******/

CREATE VIEW viewVehicleTypes AS
	SELECT TOP 100 PERCENT
		VehicleTypeID				= TYPE.VehicleTypeID,
		VehicleType					= TYPE.VehicleType,
		Caption						= TYPE.Caption,
		SubTypes					= CONVERT(INT, (
			SELECT 
				COUNT(DISTINCT VehicleSubType)
			FROM
				tblVehicleSubTypes		SUB_TYPE	WITH (NOLOCK)	
			WHERE
				SUB_TYPE.Active	= 1	AND SUB_TYPE.VehicleTypeID = TYPE.VehicleTypeID)),

		Manufacturers				= CONVERT(INT, (
			SELECT
				COUNT(DISTINCT MANUF.Manufacturer)
			FROM
				tblVehicleManufacturers		MANUF			WITH (NOLOCK)
			WHERE
					MANUF.Active		= 1	
				AND	MANUF.VehicleSubTypeID	IN (
					SELECT
						VehicleSubTypeID
					FROM
						tblVehicleSubTypes	MANUF_SUB_TYPE	WITH (NOLOCK) 
					WHERE 
							MANUF_SUB_TYPE.VehicleTypeID = TYPE.VehicleTypeID
						AND MANUF_SUB_TYPE.Active = 1))),

		SortOrder
	FROM
				tblVehicleTypes				TYPE	WITH (NOLOCK)
	WHERE
			TYPE.Active = 1
	ORDER BY
		TYPE.SortOrder, 
		TYPE.VehicleTypeID




