	--EXEC	INTO Er1k.wstest
	--EXEC sp_GetWorksheetsForUnderwritingConsole @pBidID = @pBidID
--	SELECT * FROM		viewWorksheet_List			WHERE		LoanApp_BidID = @pBidID;
--	SELECT * FROM		spWorksheet_GetProperties	WHERE		LoanApp_BidID = @pBidID;
*/

CREATE VIEW viewWorksheet_List AS
	SELECT TOP 100 PERCENT
		LoanApp_WorksheetID				= Worksheet.LoanApp_WorksheetID,
		LoanApp_BidID					= Bid.LoanApp_BidID,
		LoanAppID						= Bid.LoanAppID,
		LenderID						= Branch.LenderID,
		LendersBranchID					= Branch.LendersBranchID,
		Active							= ISNULL(Worksheet.Active, 0),
		CanEditWorksheet				= CONVERT(BIT, CASE	WHEN Worksheet.Active IS NULL THEN 1 WHEN Worksheet.Active = 0 THEN 1 WHEN Worksheet.Active = 1 AND Bid.Status IN('PENDING_LENDER', 'REFERRED') THEN 1 ELSE 0 END),
		BidStatus						= Bid.Status,

		Vehicle							= CONVERT(VARCHAR(60),	DBO.VehicleDescription(Worksheet.Vehicle_Year, Worksheet.Vehicle_Make, Worksheet.Vehicle_Model, Worksheet.Vehicle_Mileage, Worksheet.Vehicle_VIN)),
		Vehicle_Year					= Worksheet.Vehicle_Year,
		Vehicle_Make					= CONVERT(VARCHAR(30),	DBO.ProperCase(IsNull(Worksheet.Vehicle_Make,		''))),
		Vehicle_Model					= CONVERT(VARCHAR(30),	DBO.ProperCase(IsNull(Worksheet.Vehicle_Model,		''))),
		Vehicle_Mileage					= Worksheet.Vehicle_Mileage,
		Vehicle_IsUsed					= CONVERT(BIT, CASE ISNULL(Worksheet.New_Used, '') WHEN 'NEW' THEN 1 ELSE 0 END),
		Vehicle_IsNew					= CONVERT(BIT, CASE ISNULL(Worksheet.New_Used, '') WHEN 'NEW' THEN 0 ELSE 1 END),
		Vehicle_New_Used				= CASE ISNULL(Worksheet.New_Used, '') WHEN 'NEW' THEN 'New' ELSE 'Used' END,
		Vehicle_Type					= CONVERT(VARCHAR(20),	DBO.ProperCase(IsNull(Worksheet.Vehicle_Type,		''))),
		Vehicle_VIN						= CONVERT(VARCHAR(17),	UPPER(REPLACE(ISNULL(Worksheet.Vehicle_Vin, ''), ' ', ''))),
		Vehicle_Description				= ISNULL(Worksheet.Vehicle_Description,				''),
		Book_Source						= ISNULL(Worksheet.Book_Source,						''),
		Vehicle_Retail					= ISNULL(Worksheet.Vehicle_Retail,					0),
		Vehicle_Retail_Adjusted			= ISNULL(Worksheet.Vehicle_Retail_Adjusted,			0),
		Vehicle_Wholesale				= ISNULL(Worksheet.Vehicle_Wholesale,				0),
		Vehicle_Wholesale_Adjusted		= ISNULL(Worksheet.Vehicle_Wholesale_Adjusted,		0),

		Loan_Term_Requested				= ISNULL(Worksheet.Loan_Term_Requested,				0),
		Loan_Up_Front_PaymentS			= ISNULL(Worksheet.Loan_Up_Front_PaymentS,			0),
		Preferred_Payment				= ISNULL(Worksheet.Preferred_Payment,				0),
		Purchase_Type					= ISNULL(Worksheet.Purchase_Type,					0),
		Anticipated_Rate				= ISNULL(Worksheet.Anticipated_Rate,				0),
		Yield_Type						= ISNULL(Worksheet.Yield_Type,						0),

		Loan_Total_Loan_Amount			= ISNULL(Worksheet.Loan_Total_Loan_Amount,			0),
		Loan_Purchase_Price				= ISNULL(Worksheet.Loan_Purchase_Price,				0),
		Loan_Deposit					= ISNULL(Worksheet.Loan_Deposit,					0),
		Loan_Doc_Fee					= ISNULL(Worksheet.Loan_Doc_Fee,					0),
		Loan_Down_Payment				= ISNULL(Worksheet.Loan_Down_Payment,				0),
		Loan_Due_At_Signing				= ISNULL(Worksheet.Loan_Due_At_Signing,				0),
		Loan_Estimated_Payment			= ISNULL(Worksheet.Loan_Estimated_Payment,			0),
		Loan_GAP						= ISNULL(Worksheet.Loan_GAP,						0),
		Loan_License					= ISNULL(Worksheet.Loan_License,					0),
		Loan_Misc						= ISNULL(Worksheet.Loan_Misc,						0),
		Loan_Misc2						= ISNULL(Worksheet.Loan_Misc2,						0),
		Loan_Residual					= ISNULL(Worksheet.Loan_Residual,					0),
		Loan_Sales_Tax_Rate				= ISNULL(Worksheet.Loan_Sales_Tax_Rate,				0),
		Loan_Tax						= ISNULL(Worksheet.Loan_Tax,						0),
		Loan_Trade_In_Net				= ISNULL(Worksheet.Loan_Trade_In_Net,				0),
		Loan_Trade_In_Payment			= ISNULL(Worksheet.Loan_Trade_In_Payment,			0),
		Smog_Certify_Fee				= ISNULL(Worksheet.Smog_Certify_Fee,				0),
		Smog_Seller_Fee					= ISNULL(Worksheet.Smog_Seller_Fee,					0),
		Loan_DocSmog_Taxable			= ISNULL(Worksheet.Loan_DocSmog_Taxable,			0),
		Loan_Doc_Fee_Taxable			= ISNULL(Worksheet.Loan_Doc_Fee_Taxable,			0),
		Loan_GAP_Taxable				= ISNULL(Worksheet.Loan_GAP_Taxable,				0),
		Loan_License_Taxable			= ISNULL(Worksheet.Loan_License_Taxable,			0),
		Loan_Misc_Taxable				= ISNULL(Worksheet.Loan_Misc_Taxable,				0),
		Loan_Warranty_Taxable			= ISNULL(Worksheet.Loan_Warranty_Taxable,			0),
		Smog_Certify_Fee_Taxable		= ISNULL(Worksheet.Smog_Certify_Fee_Taxable,		0),
		Smog_Seller_Fee_Taxable			= ISNULL(Worksheet.Smog_Seller_Fee_Taxable,			0),
		Warranty_Term					= ISNULL(Worksheet.Warranty_Term,					0),
		Loan_Warranty					= ISNULL(Worksheet.Loan_Warranty,					0),

		Comments						= ISNULL(Worksheet.Comments,						''),
		Entered_By						= Worksheet.Entered_By,
		CreateDateTime					= Worksheet.CreateDateTime,
		UpdateDateTime					= Worksheet.UpdateDateTime,
		CreateUser						= Worksheet.CreateUser,
		UpdateUser						= Worksheet.UpdateUser,
		rowVersion						= Worksheet.rowVersion,
		--LoanAppID						= Worksheet.LoanAppID,
		Submit							= Worksheet.Submit
	FROM
					tblLoanApp_Bids				Bid			WITH (NOLOCK)
		INNER JOIN	tblLendersBranches			Branch		WITH (NOLOCK) ON Branch.LendersBranchID		= Bid.LendersBranchID
		INNER JOIN	tblLoanApp_Worksheet		Worksheet	WITH (NOLOCK) ON Worksheet.LoanApp_BidID	= Bid.LoanApp_BidID
		INNER JOIN	spWorksheet_GetProperties	Prop		WITH (NOLOCK) ON Prop.LoanApp_WorksheetID	= Worksheet.LoanApp_WorksheetID

	--WHERE
		--		Bid.LoanAppID		= @_LoanAppID		AND		Branch.LenderID		= @_LenderID		AND		
		--Bid.LoanApp_BidID	= @pBidID
/*
	ORDER BY
		Worksheet.CanEditWorksheet		DESC,
		Worksheet.Active				DESC,
		Worksheet.CreateDateTime		DESC,
		Bid.UpdateDateTime				DESC,
		Worksheet.LoanApp_WorksheetID	DESC,
		Bid.LoanAppID					DESC,
		Bid.LoanApp_BidID				DESC
*/



