				ELSE ''
			END,
ProductionTime = DATEDIFF(MINUTE, AUTO_LOAN_APP.CreateDateTime, BID.OFFER_DATE),
tblLenders.LenderStatus,
PackageRecievedDate = CASE ISNULL(FUNDING.BidFundingStatus, '')
