Retail_Base = ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL),
Retail_Adjusted = ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED),
Wholesale_Base = ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE),
Wholesale_Adjusted = ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED),

LTV_Retail_Base = CASE ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL)
			WHEN NULL THEN 999
			WHEN 0 THEN 999
--			ELSE CAST((ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL))*100 AS numeric(10,2))
			ELSE (ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL))*100
			END,

LTV_Retail_Adjusted = CASE ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED)
			WHEN NULL THEN 999
			WHEN 0 THEN 999
--			ELSE CAST((ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED))*100 AS numeric(10,2))
			ELSE (ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED))*100
			END,

LTV_Wholesale_Base = CASE ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE)
			WHEN NULL THEN 999
			WHEN 0 THEN 999
--			ELSE CAST((ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE))*100 AS numeric(10,2))
			ELSE (ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE, AUTO_LOAN_APP.VEHICLE_WHOLESALE))*100
			END,

LTV_Wholesale_Adjusted = CASE ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED)
			WHEN NULL THEN 999
			WHEN 0 THEN 999
--			ELSE CAST((ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED))*100 AS numeric(10,2))
			ELSE (ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED))*100
			END,

PRIMARY_APPLICANT.CurrentAddress_YEARS as PrimaryCurrentAddress_Years,
PRIMARY_APPLICANT.CurrentAddress_MONTHS as PrimaryCurrentAddress_Months,
ISNULL(PRIMARY_APPLICANT.CurrentAddress_YEARS*12, 0) + ISNULL(PRIMARY_APPLICANT.CurrentAddress_MONTHS, 0) as PrimaryCurrentAddress_TotalMonths,

PRIMARY_APPLICANT.PreviousAddress_YEARS as PrimaryPreviousAddress_Years,
PRIMARY_APPLICANT.PreviousAddress_MONTHS as PrimaryPreviousAddress_Months,
ISNULL(PRIMARY_APPLICANT.PreviousAddress_YEARS*12, 0) + ISNULL(PRIMARY_APPLICANT.PreviousAddress_MONTHS, 0) as PrimaryPreviousAddress_TotalMonths,

PRIMARY_APPLICANT.CurrentEmployer_YEARS as PrimaryCurrentEmployer_Years,
PRIMARY_APPLICANT.CurrentEmployer_MONTHS as PrimaryCurrentEmployer_Months,
ISNULL(PRIMARY_APPLICANT.CurrentEmployer_YEARS, 0)*12 + ISNULL(PRIMARY_APPLICANT.CurrentEmployer_MONTHS, 0) as PrimaryCurrentEmployer_TotalMonths,

PRIMARY_APPLICANT.PreviousEmployer_YEARS as PrimaryPreviousEmployer_Years,
PRIMARY_APPLICANT.PreviousEmployer_MONTHS as PrimaryPreviousEmployer_Months,
ISNULL(PRIMARY_APPLICANT.PreviousEmployer_YEARS*12, 0) + ISNULL(PRIMARY_APPLICANT.PreviousEmployer_MONTHS, 0) as PrimaryPreviousEmployer_TotalMonths,

SECONDARY_APPLICANT.CurrentAddress_YEARS as SecondaryCurrentAddress_Years,
SECONDARY_APPLICANT.CurrentAddress_MONTHS as SecondaryCurrentAddress_Months,
ISNULL(SECONDARY_APPLICANT.CurrentAddress_YEARS, 0)*12 + ISNULL(SECONDARY_APPLICANT.CurrentAddress_MONTHS, 0) as SecondaryCurrentAddress_TotalMonths,

SECONDARY_APPLICANT.PreviousAddress_YEARS as SecondaryPreviousAddress_Years,
SECONDARY_APPLICANT.PreviousAddress_MONTHS as SecondaryPreviousAddress_Months,
ISNULL(SECONDARY_APPLICANT.PreviousAddress_YEARS, 0)*12 + ISNULL(SECONDARY_APPLICANT.PreviousAddress_MONTHS, 0) as SecondaryPreviousAddress_TotalMonths,

SECONDARY_APPLICANT.CurrentEmployer_YEARS as SecondaryCurrentEmployer_Years,
SECONDARY_APPLICANT.CurrentEmployer_MONTHS as SecondaryCurrentEmployer_Months,
ISNULL(SECONDARY_APPLICANT.CurrentEmployer_YEARS, 0)*12 + ISNULL(SECONDARY_APPLICANT.CurrentEmployer_MONTHS, 0) as SecondaryCurrentEmployer_TotalMonths,

SECONDARY_APPLICANT.PreviousEmployer_YEARS as SecondaryPreviousEmployer_Years,
SECONDARY_APPLICANT.PreviousEmployer_MONTHS as SecondaryPreviousEmployer_Months,
ISNULL(SECONDARY_APPLICANT.PreviousEmployer_YEARS, 0)*12 + ISNULL(SECONDARY_APPLICANT.PreviousEmployer_MONTHS, 0) as SecondaryPreviousEmployer_TotalMonths,




ISNULL(PRIMARY_APPLICANT.CurrentAddress_STREET_1, '') + ' ' + ISNULL(PRIMARY_APPLICANT.CurrentAddress_STREET_2, '') as PrimaryCurrentAddressStreet,
--PRIMARY_APPLICANT.CurrentAddress_STREET_1  as PrimaryCurrentAddressStreet,
--PRIMARY_APPLICANT.CurrentAddress_STREET_2,
PRIMARY_APPLICANT.CurrentAddress_CITY as PrimaryCurrentAddressCity,
PRIMARY_APPLICANT.CurrentAddress_STATE as PrimaryCurrentAddressState,
PRIMARY_APPLICANT.CurrentAddress_ZIP as PrimaryCurrentAddressZip,

--'XXX-XX-' + RIGHT('0000'+CONVERT(VARCHAR(4), PRIMARY_APPLICANT.SSN_3), 4) as PrimarySSN,
RIGHT('000'+CONVERT(VARCHAR(3), PRIMARY_APPLICANT.SSN_1), 3)+'-'+RIGHT('00'+CONVERT(VARCHAR(2), PRIMARY_APPLICANT.SSN_2), 2)+'-' + RIGHT('0000'+CONVERT(VARCHAR(4), PRIMARY_APPLICANT.SSN_3), 4) as PrimarySSN,

ISNULL(SECONDARY_APPLICANT.CurrentAddress_STREET_1, '') + ' ' + ISNULL(SECONDARY_APPLICANT.CurrentAddress_STREET_2, '') as SecondaryCurrentAddressStreet,
--PRIMARY_APPLICANT.CurrentAddress_STREET_2,
SECONDARY_APPLICANT.CurrentAddress_CITY as SecondaryCurrentAddressCity,
SECONDARY_APPLICANT.CurrentAddress_STATE as SecondaryCurrentAddressState,
SECONDARY_APPLICANT.CurrentAddress_ZIP as SecondaryCurrentAddressZip,

--'XXX-XX-' + RIGHT('0000'+CONVERT(VARCHAR(4), SECONDARY_APPLICANT.SSN_3), 4) as SecondarySSN,
RIGHT('000'+CONVERT(VARCHAR(3), SECONDARY_APPLICANT.SSN_1), 3)+'-'+RIGHT('00'+CONVERT(VARCHAR(2), SECONDARY_APPLICANT.SSN_2), 2)+'-' + RIGHT('0000'+CONVERT(VARCHAR(4), SECONDARY_APPLICANT.SSN_3), 4) as SecondarySSN,


AUTO_LOAN_APP.TRADE_IN_MAKE as TradeInMake,
AUTO_LOAN_APP.TRADE_IN_MODEL as TradeInModel,
AUTO_LOAN_APP.TRADE_IN_CREDITOR as TradeInCreditor,
AUTO_LOAN_APP.TRADE_IN_ALLOWANCE as TradeInAllowance,
AUTO_LOAN_APP.TRADE_IN_DEBT as TradeInDebt,
AUTO_LOAN_APP.TRADE_IN_YEAR as TradeInYear,
AUTO_LOAN_APP.TRADE_IN_MILEAGE as TradeInMileage,
AUTO_LOAN_APP.TRADE_IN_VIN as TradeInVIN,

WS.LOAN_TRADE_IN_NET AS TradeInNet,
ISNULL(WS.VEHICLE_VIN, AUTO_LOAN_APP.VEHICLE_VIN) as VehicleVin,


CASE 
	WHEN LEN(ISNULL(AUTO_LOAN_APP.TRADE_IN_MAKE, '')) = 0 THEN 'NO'
	WHEN LEN(ISNULL(AUTO_LOAN_APP.TRADE_IN_MODEL, '')) = 0 THEN 'NO'
	WHEN LEN(ISNULL(AUTO_LOAN_APP.TRADE_IN_YEAR, '')) = 0 THEN 'NO'
	ELSE 'YES'
END as HasTradeIn,




--dbo.viewLoanApp_Underwriting.SALARY_OVERRIDE_1,
--dbo.viewLoanApp_Underwriting.SALARY_OVERRIDE_1_AMT,
--dbo.viewLoanApp_Underwriting.SALARY_OVERRIDE_2,
--dbo.viewLoanApp_Underwriting.SALARY_OVERRIDE_2_AMT,
--dbo.viewLoanApp_Underwriting.OTHER_INCOME_OVERRIDE_1,
--dbo.viewLoanApp_Underwriting.OTHER_INCOME_OVERRIDE_1_AMT,
--dbo.viewLoanApp_Underwriting.OTHER_INCOME_OVERRIDE_2,
--dbo.viewLoanApp_Underwriting.OTHER_INCOME_OVERRIDE_2_AMT


PrimaryOverrideIncome = CASE ISNULL(dbo.viewLoanApp_Underwriting.SALARY_OVERRIDE_1, 0)
			WHEN 0 THEN 0
			ELSE dbo.viewLoanApp_Underwriting.SALARY_OVERRIDE_1_AMT
			END,
SecondaryOverrideIncome = CASE ISNULL(dbo.viewLoanApp_Underwriting.SALARY_OVERRIDE_2, 0)
			WHEN 0 THEN 0
			ELSE dbo.viewLoanApp_Underwriting.SALARY_OVERRIDE_2_AMT
			END,
PrimaryOverrideOtherIncome = CASE ISNULL(dbo.viewLoanApp_Underwriting.OTHER_INCOME_OVERRIDE_1, 0)
			WHEN 0 THEN 0
			ELSE dbo.viewLoanApp_Underwriting.OTHER_INCOME_OVERRIDE_1_AMT
			END,
SecondaryOverrideOtherIncome = CASE ISNULL(dbo.viewLoanApp_Underwriting.OTHER_INCOME_OVERRIDE_2, 0)
			WHEN 0 THEN 0
			ELSE dbo.viewLoanApp_Underwriting.OTHER_INCOME_OVERRIDE_2_AMT
			END,

CUSTOM_CREDIT_SCORE.Score as CustomCreditScore,
CUSTOM_CREDIT_SCORE.CreateDateTime as CustomCreditScoreCreateDateTime,
CUSTOM_CREDIT_SCORE.UpdateDateTime as CustomCreditScoreUpadateDateTime,

dbo.viewLoanApp_Underwriting.WIRE_CUSTOMER_ACCT as CustomerAccountNumber

FROM         dbo.viewLoanApp_Underwriting
	RIGHT OUTER JOIN	dbo.viewLenderBranches LENDER_BRANCH
	INNER JOIN			dbo.tblLoanApp_Bids BID WITH (NOLOCK) ON LENDER_BRANCH.LendersBranchID = BID.LendersBranchID
	INNER JOIN			dbo.tblLenders WITH (NOLOCK) ON LENDER_BRANCH.LenderID = dbo.tblLenders.LenderID
	LEFT	JOIN		viewBid_PartnerInformation		PT					WITH (NOLOCK) ON PT.LoanApp_BidID					= Bid.LoanApp_BidID
	--INNER JOIN			viewBidsPartnerTool	PT	WITH (NOLOCK)	ON 	PT.LoanApp_BidID = BID.LoanApp_BidID


	LEFT OUTER JOIN		dbo.tblLoanApp_Bids_B2B WITH (NOLOCK) ON BID.LoanApp_BidID = dbo.tblLoanApp_Bids_B2B.LoanApp_BidID
	LEFT OUTER JOIN		dbo.tblLoanApp_Bids_Fax WITH (NOLOCK) ON BID.LoanApp_BidID = dbo.tblLoanApp_Bids_Fax.LoanApp_BidID ON
						dbo.viewLoanApp_Underwriting.LoanApp_BidID = BID.LoanApp_BidID
    RIGHT OUTER JOIN	dbo.viewLoanAppPhoneNumbers
    INNER JOIN			dbo.tblLoanApps AUTO_LOAN_APP WITH (NOLOCK)
    INNER JOIN			dbo.tblDealers DEALER WITH (NOLOCK) ON AUTO_LOAN_APP.DealerID = DEALER.DealerID ON
						dbo.viewLoanAppPhoneNumbers.LoanAppID = AUTO_LOAN_APP.LoanAppID ON BID.LoanAppID = AUTO_LOAN_APP.LoanAppID
    LEFT OUTER JOIN		tblLenderDealerRelation		r	      WITH (NOLOCK) ON r.DealerID = DEALER.DealerID AND LENDER_BRANCH.LenderID = r.LenderID
	LEFT OUTER JOIN		tblLendersLogins		    ll		  WITH (NOLOCK) ON ll.LendersLoginID = r.LenderAgentID
	LEFT OUTER JOIN		tblLendersBranchLogins		lbl		  WITH (NOLOCK) ON lbl.LendersBranchLoginID = r.LenderBranchAgentID
	
--	LEFT OUTER JOIN     tblPartnerDataElement		de		  WITH (NOLOCK) ON AUTO_LOAN_APP.LoanAppID = de.LoanAppID
--	LEFT OUTER JOIN     tblPartnerTools				pt	      WITH (NOLOCK) ON pt.PartnerToolID = de.PartnerToolID

	LEFT OUTER JOIN tblLoanApp_Worksheet        WS        WITH (NOLOCK) ON (BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)
	LEFT OUTER JOIN tblLoanAppAssignedDealers	ad		  WITH (NOLOCK) ON ad.LoanAppID = AUTO_LOAN_APP.LoanAppID
	LEFT OUTER JOIN tblDealersLogins			dl		  WITH (NOLOCK) ON dl.DealersLoginID = ad.DealersLoginID
	LEFT OUTER JOIN viewLoanAppApplicants_Emails ae		  WITH (NOLOCK) ON ae.LoanAppID = AUTO_LOAN_APP.LoanAppID
	LEFT OUTER JOIN	viewBidsFundingStatus		FUNDING 		WITH (NOLOCK) ON FUNDING.LoanApp_BidID		= BID.LoanApp_BidID
	left outer JOIN viewApplicantsIncome APPLICANTS_INCOME WITH (NOLOCK) ON (AUTO_LOAN_APP.LoanAppID = APPLICANTS_INCOME.LoanAppID and APPLICANTS_INCOME.LoanApp_ApplicantID=(SELECT MIN(LoanApp_ApplicantID) FROM viewApplicantsIncome WHERE LoanAppID=AUTO_LOAN_APP.LoanAppID ))--(a.loanappid=l.loanappid and a.loanapp_applicantid = (select min(loanapp_applicantid) from viewapplicantsincome where loanappid=l.loanappid))
	LEFT JOIN viewLoanAppPrimarySecondaryApplicant APPLICANT_PRIMARY_SECONDARY WITH (NOLOCK) ON (APPLICANT_PRIMARY_SECONDARY.LoanAppID = AUTO_LOAN_APP.LoanAppID) 
	LEFT JOIN view_LoanApp_Applicant PRIMARY_APPLICANT WITH (NOLOCK) ON (PRIMARY_APPLICANT.LoanApp_ApplicantID=APPLICANT_PRIMARY_SECONDARY.PrimaryApplicantID)--(PRIMARY_APPLICANT.LoanAppID=AUTO_LOAN_APP.LoanAppID AND PRIMARY_APPLICANT.[PRIMARY]=1)
	LEFT JOIN view_LoanApp_Applicant SECONDARY_APPLICANT WITH (NOLOCK) ON (SECONDARY_APPLICANT.LoanApp_ApplicantID=APPLICANT_PRIMARY_SECONDARY.SecondaryApplicantID AND NOT APPLICANT_PRIMARY_SECONDARY.SecondaryApplicantID=APPLICANT_PRIMARY_SECONDARY.PrimaryApplicantID)--(SECONDARY_APPLICANT.LoanAppID=AUTO_LOAN_APP.LoanAppID AND SECONDARY_APPLICANT.[PRIMARY]=0)

	LEFT JOIN tblLoanApp_CustomCreditScore CUSTOM_CREDIT_SCORE WITH (NOLOCK) ON (CUSTOM_CREDIT_SCORE.LoanApp_BidID=BID.LoanApp_BidID)	



--WHERE		(Lender_Branch.LenderID = 227) AND (Bid.STATUS IN ('PENDING_DEALER')) AND Bid.[CreateDateTime] >= '12/23/2015'

--	left join tblLoanApp_Applicant PRIMARY_APPLICANT WITH (NOLOCK) ON (PRIMARY_APPLICANT.LoanAppID=AUTO_LOAN_APP.LoanAppID AND PRIMARY_APPLICANT.PRIMARY=1)
	
--ORDER BY BID.LoanApp_BidID DESC, AUTO_LOAN_APP.LoanAppID DESC









