			ELSE (ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, AUTO_LOAN_APP.LOAN_TOTAL_LOAN_AMOUNT)/ISNULL(WS.VEHICLE_WHOLESALE_ADJUSTED, AUTO_LOAN_APP.VEHICLE_WHOLESALE_ADJUSTED))*100
			END,

PRIMARY_APPLICANT.CurrentAddress_YEARS as PrimaryCurrentAddress_Years,
