	WHEN LEN(ISNULL(AUTO_LOAN_APP.TRADE_IN_MODEL, '')) = 0 THEN 'NO'
	WHEN LEN(ISNULL(AUTO_LOAN_APP.TRADE_IN_YEAR, '')) = 0 THEN 'NO'
	ELSE 'YES'
END as HasTradeIn,




