Retail_Base = ISNULL(WS.VEHICLE_RETAIL, AUTO_LOAN_APP.VEHICLE_RETAIL),
Retail_Adjusted = ISNULL(WS.VEHICLE_RETAIL_ADJUSTED, AUTO_LOAN_APP.VEHICLE_RETAIL_ADJUSTED),
