AUTO_LOAN_APP.TRADE_IN_MAKE as TradeInMake,
AUTO_LOAN_APP.TRADE_IN_MODEL as TradeInModel,
AUTO_LOAN_APP.TRADE_IN_CREDITOR as TradeInCreditor,
AUTO_LOAN_APP.TRADE_IN_ALLOWANCE as TradeInAllowance,
AUTO_LOAN_APP.TRADE_IN_DEBT as TradeInDebt,
AUTO_LOAN_APP.TRADE_IN_YEAR as TradeInYear,
AUTO_LOAN_APP.TRADE_IN_MILEAGE as TradeInMileage,
AUTO_LOAN_APP.TRADE_IN_VIN as TradeInVIN,

CASE 
	WHEN LEN(ISNULL(AUTO_LOAN_APP.TRADE_IN_MAKE, '')) = 0 THEN 0
	WHEN LEN(ISNULL(AUTO_LOAN_APP.TRADE_IN_MODEL, '')) = 0 THEN 0
	WHEN LEN(ISNULL(AUTO_LOAN_APP.TRADE_IN_YEAR, '')) = 0 THEN 0
	ELSE 1
END as HasTradeIn,

--U.SALARY_OVERRIDE_1,
--U.SALARY_OVERRIDE_1_AMT,
--U.SALARY_OVERRIDE_2,
--U.SALARY_OVERRIDE_2_AMT,
--U.OTHER_INCOME_OVERRIDE_1,
--U.OTHER_INCOME_OVERRIDE_1_AMT,
--U.OTHER_INCOME_OVERRIDE_2,
--U.OTHER_INCOME_OVERRIDE_2_AMT


PrimaryOverrideIncome = CASE ISNULL(U.SALARY_OVERRIDE_1, 0)
			WHEN 0 THEN 0
			ELSE U.SALARY_OVERRIDE_1_AMT
			END,
SecondaryOverrideIncome = CASE ISNULL(U.SALARY_OVERRIDE_2, 0)
			WHEN 0 THEN 0
			ELSE U.SALARY_OVERRIDE_2_AMT
			END,
PrimaryOverrideOtherIncome = CASE ISNULL(U.OTHER_INCOME_OVERRIDE_1, 0)
			WHEN 0 THEN 0
			ELSE U.OTHER_INCOME_OVERRIDE_1_AMT
			END,
SecondaryOverrideOtherIncome = CASE ISNULL(U.OTHER_INCOME_OVERRIDE_2, 0)
			WHEN 0 THEN 0
			ELSE U.OTHER_INCOME_OVERRIDE_2_AMT
			END

FROM    
				tblLoanApp_Bids BID 		WITH (NOLOCK)
    	INNER JOIN		tblLoanApps 			AUTO_LOAN_APP WITH (NOLOCK) ON BID.LoanAppID = AUTO_LOAN_APP.LoanAppID
	INNER JOIN		tblLendersBranches		LENDER_BRANCH WITH (NOLOCK) ON BID.LendersBranchID = LENDER_BRANCH.LendersBranchID
	INNER JOIN 		tblLoanApp_Underwriting 	U WITH (NOLOCK)ON BID.LoanAppID = U.LoanAppID AND LENDER_BRANCH.LenderID = U.LenderID --AND U.LoanApp_BidID = BID.LoanApp_BidID

--dbo.viewLoanApp_Underwriting WITH (NOLOCK)
--	RIGHT OUTER JOIN	dbo.viewLenderBranches 		LENDER_BRANCH WITH (NOLOCK)
--	INNER JOIN		dbo.tblLoanApp_Bids 		BID WITH (NOLOCK) ON LENDER_BRANCH.LendersBranchID = BID.LendersBranchID
	INNER JOIN		dbo.tblLenders 			WITH (NOLOCK) ON LENDER_BRANCH.LenderID = dbo.tblLenders.LenderID
    	INNER JOIN		dbo.tblDealers DEALER 		WITH (NOLOCK) ON AUTO_LOAN_APP.DealerID = DEALER.DealerID 

	--INNER JOIN		viewBidsPartnerTool	PT	WITH (NOLOCK)	ON 	PT.LoanApp_BidID = BID.LoanApp_BidID

	LEFT OUTER JOIN		dbo.tblLoanApp_Bids_B2B 	WITH (NOLOCK) ON BID.LoanApp_BidID = dbo.tblLoanApp_Bids_B2B.LoanApp_BidID
	LEFT OUTER JOIN		dbo.tblLoanApp_Bids_Fax 	WITH (NOLOCK) ON BID.LoanApp_BidID = dbo.tblLoanApp_Bids_Fax.LoanApp_BidID 

   	LEFT OUTER JOIN		tblLenderDealerRelation		r       WITH (NOLOCK) ON r.DealerID = DEALER.DealerID AND LENDER_BRANCH.LenderID = r.LenderID
	LEFT OUTER JOIN		tblLendersLogins		ll	WITH (NOLOCK) ON ll.LendersLoginID = r.LenderAgentID
	LEFT OUTER JOIN		tblLendersBranchLogins		lbl	 WITH (NOLOCK) ON lbl.LendersBranchLoginID = r.LenderBranchAgentID

	LEFT OUTER JOIN 	tblLoanApp_Worksheet        	WS        WITH (NOLOCK) ON (BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)
	LEFT OUTER JOIN 	tblLoanAppAssignedDealers	ad	  WITH (NOLOCK) ON ad.LoanAppID = AUTO_LOAN_APP.LoanAppID
    	LEFT OUTER JOIN 	tblDealersLogins		dl	  WITH (NOLOCK) ON dl.DealersLoginID = ad.DealersLoginID

/*
