/****** Object:  View dbo.view_FilterStates    Script Date: 7/31/2024 12:57:24 PM ******/


CREATE VIEW [dbo].[view_FilterStates] AS

SELECT TOP 100 PERCENT
	[F].[ProgramID],
	[S].[StateAbbrev],
	[S].[ProgramFilterID]

FROM
	[tblProgramFilterStates] [S],
  [tblProgramFilter] [F]

WHERE
  [S].[ProgramFilterID] = [F].[ProgramFilterID]

UNION ALL

SELECT TOP 100 PERCENT
  [ProgramID],
	'*' [StateAbbrev],
	[ProgramFilterID]

FROM
	[tblProgramFilter]

WHERE
						[ProgramFilterID] NOT IN (Select [ProgramFilterID] FROM [tblProgramFilterStates])
		AND 		[ProgramID] NOT IN (SELECT [ProgramID] FROM [tblPrograms] WHERE [ACTIVE]=0)

ORDER BY
	[StateAbbrev],
	[ProgramID],
	[ProgramFilterID]	



