/****** Object:  View dbo.view_FilterStates_App    Script Date: 7/31/2024 12:57:24 PM ******/


CREATE VIEW view_FilterStates_App AS
	SELECT TOP 100 PERCENT
		ProgramID					=	F.ProgramID,
		StateAbbrev				=	S.StateAbbrev,
		ProgramFilterID		=	S.ProgramFilterID
	FROM
					tblProgramFilterStates_App	S	WITH (NOLOCK)
 		JOIN	tblProgramFilter 						F WITH (NOLOCK)	ON S.ProgramFilterID = F.ProgramFilterID

	UNION ALL

	SELECT TOP 100 PERCENT
		ProgramID					= ProgramID,
		StateAbbrev				=	'*' ,
		ProgramFilterID		=	F2.ProgramFilterID
	FROM
		tblProgramFilter	F2	WITH (NOLOCK)
	WHERE
					F2.ProgramFilterID	NOT IN (Select ProgramFilterID	FROM tblProgramFilterStates_App WITH (NOLOCK))
		AND		ProgramID						NOT IN (SELECT ProgramID 				FROM tblPrograms  WITH (NOLOCK) WHERE ACTIVE=0)

	ORDER BY
		StateAbbrev,
		ProgramID,
		ProgramFilterID	





