/****** Object:  View dbo.view_MasterFilterPrograms    Script Date: 7/31/2024 12:57:24 PM ******/


CREATE VIEW [view_MasterFilterPrograms] AS

SELECT TOP 100 PERCENT
    [Lender].[LenderID],
    [Lender].[LenderName],
    [Lender].[City],
    [Lender].[State],
    [Lender].[ZIP],
    [Program].[ProgramID],
    [Program].[ProgramName],
    [Program].[CreditTier],
    [Program].[Automated],
    [Program].[Underwriting],
		[Program].[AutoSelect],
		IsNull([Program].[RequiresCredit], 1) ProgramRequiresCredit,
    [ProgramFilter].[ProgramFilterID],
    [ProgramFilter].[Description],
    [Filter].[FilterID],
    [Filter].[ShortName],
    [Filter].[LongName],
    [ParameterValue].[ParameterDescription],
    [ParameterValue].[ParameterName],
    [ParameterValue].[DataTypeName],
    [ParameterValue].[Value],
    [ParameterValue].[Operator],
		[ParameterValue].[Units],
		IsNull([Filter].[RequiresCredit], 1) RequiresCredit

FROM
    [tblLenders] [Lender]
      INNER JOIN      [tblPrograms]           [Program]                 ON  [Program].[LenderID]                = [Lender].[LenderID]
      INNER JOIN      [tblProgramFilter]      [ProgramFilter]           ON  [ProgramFilter].[ProgramID]         = [Program].[ProgramID]
      INNER JOIN      [viewParameterValues]   [ParameterValue]          ON  [ProgramFilter].[ProgramFilterID]   = [ParameterValue].[ProgramFilterID]
      INNER JOIN      [tblFilters]            [Filter]                  ON  [ParameterValue].[FilterID]         = [Filter].[FilterID]

WHERE
            ([Program].[Active] = 1)
--      AND   (NOT [Lender].[Submit_Status] = 'CLOSED' )
--			AND		(NOT [ParameterValue].[Value] = '')

ORDER BY
    [Lender].[LenderID],
    [Program].[CreditTier],
    [Program].[ProgramID],
    [ProgramFilter].[ProgramFilterID],
    [Filter].[FilterID],
    [ParameterValue].[ParameterID],
    [ParameterValue].[ValueID]






