-- * 27 of 64    view_MasterFilterPrograms_2   ID: 912058335
CREATE VIEW view_MasterFilterPrograms_2 as

SELECT TOP 100 PERCENT
	LP.LenderID,
	LP.LenderName,
	LP.City,
	LP.State,
	LP.ZIP,
	LP.ProgramID,
	LP.ProgramName,
	LP.CreditTier,
	LP.Automated,
	LP.Underwriting,
	ISNULL(PF.ProgramFilterID,        -1)		        ProgramFilterID,
	ISNULL(PF.Description,            'Filler')	    Description,
	ISNULL(F.FilterID,                -1) 				  FilterID,
	ISNULL(F.ShortName,               'Filler')		  ShortName,
	ISNULL(F.LongName,                'Filler')		  LongName,
	ISNULL(PV.ParameterDescription,   '')           ParameterDescription,
	ISNULL(PV.ParameterName,          '')           ParameterName,
	ISNULL(PV.DataTypeName,           '')           DataTypeName,
	ISNULL(PV.[Value],                '')           [Value],
	ISNULL(PV.Operator,               '')           Operator

FROM         viewParameterValues PV INNER JOIN
                      tblProgramFilter PF ON PV.ProgramFilterID = PF.ProgramFilterID INNER JOIN
                      tblFilters F ON PV.FilterID = F.FilterID RIGHT OUTER JOIN
                      view_Lender_Programs LP ON PF.ProgramID = LP.ProgramID
WHERE     (LP.Active = 1)
ORDER BY LP.LenderID, LP.CreditTier, LP.ProgramID, PF.ProgramFilterID, F.FilterID, PV.ParameterID, PV.ValueID









