					RATE = CONVERT(FLOAT, CASE 
						WHEN BID.RATE IS NULL THEN NULL
						WHEN ISNUMERIC(BID.RATE) = 0 THEN NULL
						WHEN ISNUMERIC(REPLACE(REPLACE(REPLACE(BID.RATE, ',', '.'), '%', ''), ' ', '')) = 1 THEN REPLACE(REPLACE(REPLACE(BID.RATE, ',', '.'), '%', ''), ' ', '')
						ELSE NULL END),

