                      dbo.tblLenders.Address AS LenderAddress, dbo.tblLenders.City AS LenderCity, dbo.tblLenders.State AS LenderState, dbo.tblLenders.ZIP AS LenderZip,
                      BID.LENDER_ARCHIVED, DEALER.DealerName, BID.FUNDED, BID.Stips, ISNULL(WS.ANTICIPATED_RATE,       AUTO_LOAN_APP.ANTICIPATED_RATE) as ANTICIPATED_RATE, BID.Reason,
                      BID.LENDER_CREDIT_GUID, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EX, AUTO_LOAN_APP.DEALER_CREDIT_WANTS_EQ,
                      AUTO_LOAN_APP.DEALER_CREDIT_WANTS_TU, AUTO_LOAN_APP.DEALER_CREDIT_EX, AUTO_LOAN_APP.DEALER_CREDIT_EQ,
                      AUTO_LOAN_APP.DEALER_CREDIT_TU, BID.LENDER_CREDIT_WANTS_EX, BID.LENDER_CREDIT_WANTS_TU, BID.LENDER_CREDIT_EQ,
                      BID.LENDER_CREDIT_TU, BID.LENDER_CREDIT_EX, BID.LENDER_CREDIT_WANTS_EQ, BID.Reasons, BID.DISCOUNT_FEE, BID.REMINDER_DATE,
                      BID.AUTOMATED, BID.OFFERED_BY, BID.OFFER_DATE, BID.CANCELED_DATE, BID.FUNDED_DATE, BID.ACCEPT_DATE, BID.SUBMIT_DATE,
                      BID.SUBMIT_BY, CONVERT(int, BID.PRIMARY_SCORE) AS PRIMARY_SCORE, CONVERT(int, BID.SECONDARY_SCORE) AS SECONDARY_SCORE,
                      BID.ACCEPT_BY, CONVERT(int, BID.DTI) AS DTI, CONVERT(int, BID.PTI) AS PTI, AUTO_LOAN_APP.LenderID AS LenderDealerID,
                      dbo.viewLoanApp_Underwriting.FUNDING_FINANCED_AMOUNT, dbo.viewLoanApp_Underwriting.FUNDING_TERM,
                      dbo.viewLoanApp_Underwriting.FUNDING_RATE, dbo.viewLoanApp_Underwriting.FUNDING_FEES, dbo.viewLoanApp_Underwriting.FUNDING_REBATE,
                      dbo.viewLoanApp_Underwriting.FUNDING_RESERVE, dbo.viewLoanApp_Underwriting.FUNDING_DISCOUNT_FEE,
                      dbo.viewLoanApp_Underwriting.FUNDING_MONTHLY_PAYMENT, dbo.viewLoanApp_Underwriting.FUNDING_TOTAL_PAYMENTS,
                      dbo.tblLoanApp_Bids_Fax.STATUS AS Fax_Status, dbo.tblLoanApp_Bids_Fax.UpdateDateTime AS Fax_LastUpdate,
                      LENDER_BRANCH.FAX_TYPE AS BranchFaxType, LENDER_BRANCH.FAX_ONLY AS BranchFaxOnly,
                      dbo.viewLoanApp_Underwriting.CONTRACT_DATE, dbo.viewLoanApp_Underwriting.FIRST_PAY_DATE,
                      dbo.viewLoanApp_Underwriting.WIRE_DATE_WIRED, dbo.viewLoanApp_Underwriting.ADMIN_FEE,
                      dbo.viewLoanApp_Underwriting.WIRE_WIRED_AMOUNT, dbo.viewLoanApp_Underwriting.WIRE_BANK_NAME,
                      dbo.viewLoanApp_Underwriting.WIRE_ABA_NUM, dbo.viewLoanApp_Underwriting.WIRE_ACCOUNT_NUM,
                      dbo.viewLoanApp_Underwriting.NEW_USED, dbo.viewLoanApp_Underwriting.MEMBER_FEE, dbo.viewLoanApp_Underwriting.MISC_FEE,
                      dbo.viewLoanApp_Underwriting.WIRE_CHECK_NUM, dbo.viewLoanApp_Underwriting.YIELD_TYPE AS FUNDING_YIELD_TYPE,
                      dbo.viewLoanApp_Underwriting.FUNDING_METHOD, DEALER.City AS DealerCity, DEALER.State AS DealerState,
                      dbo.viewLoanAppPhoneNumbers.Primary_Home_Phone, dbo.viewLoanAppPhoneNumbers.Primary_Mobile_Phone,
                      dbo.viewLoanAppPhoneNumbers.Secondary_Home_Phone, dbo.viewLoanAppPhoneNumbers.DealerPhone,



