/****** Object:  View dbo.view_Search_3    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW [dbo].[view_Search_3] AS
SELECT --TOP 100 PERCENT
  APP.LoanAppID,
  BID.LoanApp_BidID,
  BRANCH.LenderID,
  BID.LendersBranchID,
  LENDER.LenderName + N' - ' + BRANCH.BranchName + N' (' + BRANCH.CITY + N', ' + BRANCH.STATE + N')'  AS Lender,
  BRANCH.BranchName,
  BRANCH.notification_email                                                                           AS lenderEmail,
  ANTICIPATED_RATE=          ISNULL(WS.ANTICIPATED_RATE,       APP.ANTICIPATED_RATE),
  LOAN_DOWN_PAYMENT=         ISNULL(WS.LOAN_DOWN_PAYMENT,      APP.LOAN_DOWN_PAYMENT),
  LOAN_ESTIMATED_PAYMENT=    ISNULL(WS.LOAN_ESTIMATED_PAYMENT, APP.LOAN_ESTIMATED_PAYMENT),
  LOAN_LICENSE=              ISNULL(WS.LOAN_LICENSE,           APP.LOAN_LICENSE),
  LOAN_MISC=                 ISNULL(WS.LOAN_MISC,              APP.LOAN_MISC),
  LOAN_PURCHASE_PRICE=       ISNULL(WS.LOAN_PURCHASE_PRICE,    APP.LOAN_PURCHASE_PRICE),
  LOAN_TAX=                  ISNULL(WS.LOAN_TAX,               APP.LOAN_TAX),
  LOAN_TERM_REQUESTED=       ISNULL(WS.LOAN_TERM_REQUESTED,    APP.LOAN_TERM_REQUESTED),
  LOAN_TOTAL_LOAN_AMOUNT=    ISNULL(WS.LOAN_TOTAL_LOAN_AMOUNT, APP.LOAN_TOTAL_LOAN_AMOUNT),
  LOAN_WARRANTY=             ISNULL(WS.LOAN_WARRANTY,          APP.LOAN_WARRANTY),
  VEHICLE_DESCRIPTION=       ISNULL(WS.VEHICLE_DESCRIPTION,    APP.VEHICLE_DESCRIPTION),
  VEHICLE_MAKE=              ISNULL(WS.VEHICLE_MAKE,           APP.VEHICLE_MAKE),
  VEHICLE_MILEAGE=           ISNULL(WS.VEHICLE_MILEAGE,        APP.VEHICLE_MILEAGE),
  VEHICLE_MODEL=             ISNULL(WS.VEHICLE_MODEL,          APP.VEHICLE_MODEL),
  VEHICLE_VIN=               ISNULL(WS.VEHICLE_VIN,            APP.VEHICLE_VIN),
  VEHICLE_YEAR=              ISNULL(WS.VEHICLE_YEAR,           APP.VEHICLE_YEAR),
  VEHICLE=                   ISNULL(CONVERT(CHAR(4), WS.VEHICLE_YEAR) + ' ' + WS.VEHICLE_MAKE + ' ' + WS.VEHICLE_MODEL, CONVERT(CHAR(4), APP.VEHICLE_YEAR) + ' ' + APP.VEHICLE_MAKE + ' ' + APP.VEHICLE_MODEL),
	WorksheetID = WS.LoanApp_WorksheetID,
  BID.YIELD_TYPE,
  BID.COMMENTS,
  CONVERT(int, LEFT(BID.TERM, 2))                                                                                  AS TERM,
  BID.PAYMENT,
  BID.MESSAGING_STATUS,
  BID.REBATE_PERCT,
  BID.ADVANCE,
  BID.FINANCING_AMOUNT,
  APP.DealerID,
  APP.APPLICANT_NAMES,
  BID.STATUS,
  BID.ARCHIVED,
  DEALER.DealerName + ' - ' + DEALER.City + ' ' + DEALER.State                                        AS Dealer,
  APP.COMMENTS                                                                                        AS LoanAppCOMMENTS,
  DEALER.EMail                                                                                        AS DealerEMail,
  APP.rowVersion,
  APP.UpdateUser,
  APP.CreateUser,
  APP.UpdateDateTime,
  APP.CreateDateTime,
  CONVERT(float, REPLACE(BID.RATE, '%', ''))                                                          AS RATE,
  BID.CreateDateTime                                                                                  AS BidCreateDateTime,
  BID.UpdateDateTime                                                                                  AS BidUpdateDateTime,
  LENDER.Address                                                                                      AS LenderAddress,
  LENDER.City                                                                                         AS LenderCity,
  LENDER.State                                                                                        AS LenderState,
  LENDER.ZIP                                                                                          AS LenderZip,
  BID.LENDER_ARCHIVED,
  DEALER.DealerName,
  BID.FUNDED,
  BID.Stips,
  BID.Reason,
  BID.LENDER_CREDIT_GUID,
  APP.DEALER_CREDIT_WANTS_EX,
  APP.DEALER_CREDIT_WANTS_EQ,
  APP.DEALER_CREDIT_WANTS_TU,
  APP.DEALER_CREDIT_EX,
  APP.DEALER_CREDIT_EQ,
  APP.DEALER_CREDIT_TU,
  BID.LENDER_CREDIT_WANTS_EX,
  BID.LENDER_CREDIT_WANTS_TU,
  BID.LENDER_CREDIT_EQ,
  BID.LENDER_CREDIT_TU,
  BID.LENDER_CREDIT_EX,
  BID.LENDER_CREDIT_WANTS_EQ,
  BID.Reasons,
  BID.DISCOUNT_FEE,
  BID.REMINDER_DATE,
  BID.AUTOMATED,
  BID.OFFERED_BY,
  BID.OFFER_DATE,
  BID.CANCELED_DATE,
  BID.FUNDED_DATE,
  BID.ACCEPT_DATE,
  BID.SUBMIT_DATE,
  BID.SUBMIT_BY,
  CONVERT(int, BID.PRIMARY_SCORE)                                                                     AS PRIMARY_SCORE,
  CONVERT(int, BID.SECONDARY_SCORE)                                                                   AS SECONDARY_SCORE,
  BID.ACCEPT_BY,
  CONVERT(int, BID.DTI)                                                                               AS DTI,
  CONVERT(int, BID.PTI)                                                                               AS PTI,
  APP.LenderID                                                                                        AS LenderDealerID,
  UW.FUNDING_FINANCED_AMOUNT,
  UW.FUNDING_TERM,
  UW.FUNDING_RATE,
  UW.FUNDING_FEES,
  UW.FUNDING_REBATE,
  UW.FUNDING_RESERVE,
  UW.FUNDING_DISCOUNT_FEE,
  UW.FUNDING_MONTHLY_PAYMENT,
  UW.FUNDING_TOTAL_PAYMENTS,
  FAX.STATUS                                                                                          AS Fax_Status,
  FAX.UpdateDateTime                                                                                  AS Fax_LastUpdate,
  BRANCH.FAX_TYPE                                                                                     AS BranchFaxType,
  BRANCH.FAX_ONLY                                                                                     AS BranchFaxOnly,
  UW.CONTRACT_DATE,
  UW.FIRST_PAY_DATE,
  UW.WIRE_DATE_WIRED,
  UW.ADMIN_FEE,
  UW.WIRE_WIRED_AMOUNT,
  UW.WIRE_BANK_NAME,
  UW.WIRE_ABA_NUM,
  UW.WIRE_ACCOUNT_NUM,
  UW.NEW_USED,
  UW.MEMBER_FEE,
  UW.MISC_FEE,
  UW.WIRE_CHECK_NUM,
  UW.YIELD_TYPE                                                                                       AS FUNDING_YIELD_TYPE,
  UW.FUNDING_METHOD,
  DEALER.City DealerCity,
  DEALER.State DealerState,
  ISNULL(BID.Counter, 0)                                                                              AS Counter,
  RESUBMIT_POLICY=ISNULL(LENDER.RESUBMIT_POLICY, 'NOT_ALLOWED'),
	CREDIT_GUID=NULL,
  t.ShortName AS PartnerName,
  ISNULL(ll.FullName, ISNULL(lbl.FullName,'')) As LenderAgentName,
  ISNULL(dl.UserName, '') as DealerSalesPerson,
  ISNULL(ae.CustomerEmail, '') as CustomerEmail
FROM
  tblLoanApps APP WITH (NOLOCK)
    LEFT OUTER JOIN tblLoanApp_Bids             BID       WITH (NOLOCK) ON APP.LoanAppID = BID.LoanAppID
    LEFT OUTER JOIN tblLendersBranches          BRANCH    WITH (NOLOCK) ON BID.LendersBranchID = BRANCH.LendersBranchID
    LEFT OUTER JOIN tblLenders                  LENDER    WITH (NOLOCK) ON BRANCH.LenderID = LENDER.LenderID
    LEFT OUTER JOIN tblLoanApp_Bids_Fax         FAX       WITH (NOLOCK) ON BID.LoanApp_BidID = FAX.LoanApp_BidID
    LEFT OUTER JOIN viewLoanApp_Underwriting    UW        WITH (NOLOCK) ON BID.LoanApp_BidID = UW.LoanApp_BidID
    LEFT OUTER JOIN tblDealers                  DEALER    WITH (NOLOCK) ON APP.DealerID = DEALER.DealerID
    LEFT OUTER JOIN tblLoanApp_Worksheet        WS        WITH (NOLOCK) ON (BID.LoanApp_BidID = WS.LoanApp_BidID AND WS.ACTIVE=1)
    LEFT OUTER JOIN tblPartnerDataElement		e		  WITH (NOLOCK) ON APP.LoanAppID = e.LoanAppID
	LEFT OUTER JOIN tblPartnerTools				t	      WITH (NOLOCK) ON t.PartnerToolID = e.PartnerToolID
	LEFT OUTER JOIN tblLenderDealerRelation		r	      WITH (NOLOCK) ON r.DealerID = DEALER.DealerID AND BRANCH.LenderID = r.LenderID
	LEFT OUTER JOIN tblLendersLogins		    ll		  WITH (NOLOCK) ON ll.LendersLoginID = r.LenderAgentID
	LEFT OUTER JOIN tblLendersBranchLogins		lbl		  WITH (NOLOCK) ON lbl.LendersBranchLoginID = r.LenderBranchAgentID
    LEFT OUTER JOIN tblLoanAppAssignedDealers	ad		  WITH (NOLOCK) ON ad.LoanAppID = APP.LoanAppID
    LEFT OUTER JOIN tblDealersLogins			dl		  WITH (NOLOCK) ON dl.DealersLoginID = ad.DealersLoginID
	LEFT OUTER JOIN viewLoanAppApplicants_Emails ae		  WITH (NOLOCK) ON ae.LoanAppID = APP.LoanAppID
/*
ORDER BY
  APP.LoanAppID DESC,
  BID.LoanApp_BidID DESC
*/

