UNION ALL
SELECT MAX(UpdateDateTime) DateTime FROM tblLenders           WHERE (NOT UpdateDateTime IS NULL)
UNION ALL
SELECT MAX(UpdateDateTime) DateTime FROM tblLendersBranches   WHERE (NOT UpdateDateTime IS NULL)
UNION ALL
SELECT MAX(CreateDateTime) DateTime FROM tblProgramFilter     WHERE (NOT CreateDateTime IS NULL)
UNION ALL
SELECT MAX(CreateDateTime) DateTime FROM tblPrograms          WHERE (NOT CreateDateTime IS NULL)
UNION ALL
SELECT MAX(CreateDateTime) DateTime FROM tblLenders           WHERE (NOT CreateDateTime IS NULL)
UNION ALL
SELECT MAX(CreateDateTime) DateTime FROM tblLendersBranches   WHERE (NOT CreateDateTime IS NULL)









