/****** Object:  View dbo.TEMP_PROGRAMS    Script Date: 7/31/2024 12:57:24 PM ******/


CREATE VIEW dbo.TEMP_PROGRAMS
AS
SELECT     COUNT(*) AS Expr1
FROM         dbo.tblParameters INNER JOIN
                      dbo.tblFilters ON dbo.tblParameters.FilterID = dbo.tblFilters.FilterID INNER JOIN
                      dbo.tblPrograms INNER JOIN
                      dbo.tblProgramFilter ON dbo.tblPrograms.ProgramID = dbo.tblProgramFilter.ProgramID INNER JOIN
                      dbo.tblValues ON dbo.tblProgramFilter.ProgramFilterID = dbo.tblValues.ProgramFilterID ON
                      dbo.tblParameters.ParameterID = dbo.tblValues.ParameterID
WHERE     (LEN(dbo.tblValues.Value) > 0)





