/****** Object:  View dbo.TEMP_viewUnderwritingProgramStatistics    Script Date: 7/31/2024 12:57:24 PM ******/



CREATE VIEW TEMP_viewUnderwritingProgramStatistics AS

SELECT TOP 100 PERCENT
  LENDER.LenderID,
  LENDER.LenderName,
  PROGRAM.ProgramID,
  PROGRAM.ProgramName,
  PROGRAM.CreditTier,
  What = CASE
    WHEN F.ShortName = 'CREDIT_SCORE'   AND PARAM.ShortName = 'SCORECARD'            THEN 'CREDIT_SCORECARD'
    WHEN F.ShortName = 'LOAN_TERM'      AND PARAM.ShortName = 'MONTHS'               AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'TERM_MAX'
    WHEN F.ShortName = 'LOAN_TERM'      AND PARAM.ShortName = 'MONTHS'               AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'TERM_MIN'
    WHEN F.ShortName = 'AMOUNT_FINANCE' AND PARAM.ShortName = 'AMOUNT_FINANCED'      AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'AMOUNT_MAX'
    WHEN F.ShortName = 'AMOUNT_FINANCE' AND PARAM.ShortName = 'AMOUNT_FINANCED'      AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'AMOUNT_MIN'
    WHEN F.ShortName = 'DTI'            AND PARAM.ShortName = 'APP'                  AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'PRIMARY_DTI_MIN'
    WHEN F.ShortName = 'DTI'            AND PARAM.ShortName = 'COMB'                 AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'JOINT_DTI_MIN'
    WHEN F.ShortName = 'DTI'            AND PARAM.ShortName = 'APP'                  AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'PRIMARY_DTI_MAX'
    WHEN F.ShortName = 'DTI'            AND PARAM.ShortName = 'COMB'                 AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'JOINT_DTI_MAX'
    WHEN F.ShortName = 'DTI'            AND PARAM.ShortName = 'COMB_OVERRIDE'                                                    THEN 'JOINT_DTI_CAN_OVERRIDE'
    WHEN F.ShortName = 'PTI'            AND PARAM.ShortName = 'APP'                  AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'PRIMARY_PTI_MAX'
    WHEN F.ShortName = 'PTI'            AND PARAM.ShortName = 'COMB'                 AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'JOINT_PTI_MAX'
    WHEN F.ShortName = 'PTI'            AND PARAM.ShortName = 'APP'                  AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'PRIMARY_PTI_MIN'
    WHEN F.ShortName = 'PTI'            AND PARAM.ShortName = 'COMB'                 AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'JOINT_PTI_MIN'
    WHEN F.ShortName = 'PTI'            AND PARAM.ShortName = 'COMB_OVERRIDE'                                                    THEN 'JOINT_PTI_CAN_OVERRIDE'
    WHEN F.ShortName = 'LTV_NET'        AND PARAM.ShortName = 'RETAIL'               AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'LTV_RETAIL_MAX'
    WHEN F.ShortName = 'LTV_NET'        AND PARAM.ShortName = 'RETAIL_ADJUSTED'      AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'LTV_RETAIL_ADJ_MAX'
    WHEN F.ShortName = 'LTV_NET'        AND PARAM.ShortName = 'WHOLESALE'            AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'LTV_WHOLESALE_MAX'
    WHEN F.ShortName = 'LTV_NET'        AND PARAM.ShortName = 'WHOLESALE_ADJUSTED'   AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'LTV_WHOLESALE_ADJ_MAX'
    WHEN F.ShortName = 'LTV'            AND PARAM.ShortName = 'RETAIL'               AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'LTV_RETAIL_MAX'
    WHEN F.ShortName = 'LTV'            AND PARAM.ShortName = 'RETAIL'               AND ISNULL(V.Operator, '') =''              THEN 'LTV_RETAIL_MAX'
    WHEN F.ShortName = 'LTV'            AND PARAM.ShortName = 'RETAIL_ADJUSTED'      AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'LTV_RETAIL_ADJ_MAX'
    WHEN F.ShortName = 'LTV'            AND PARAM.ShortName = 'WHOLESALE_BASE'       AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'LTV_WHOLESALE_MAX'
    WHEN F.ShortName = 'LTV'            AND PARAM.ShortName = 'WHOLESALE_ADJUSTED'   AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'LTV_WHOLESALE_ADJ_MAX'
    WHEN F.ShortName = 'LTV'            AND PARAM.ShortName = 'BOOK_SOURCE'                                                      THEN 'LTV_BOOK'
    WHEN F.ShortName = 'VEHICLE'        AND PARAM.ShortName = 'RETAIL'               AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'VEHICLE_RETAIL_MAX'
    WHEN F.ShortName = 'VEHICLE'        AND PARAM.ShortName = 'RETAIL_ADJUSTED'      AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'VEHICLE_RETAIL_ADJ_MAX'
    WHEN F.ShortName = 'VEHICLE'        AND PARAM.ShortName = 'WHOLESALE'            AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'VEHICLE_WHOLESALE_MAX'
    WHEN F.ShortName = 'VEHICLE'        AND PARAM.ShortName = 'WHOLESALE_ADJUSTED'   AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'VEHICLE_WHOLESALE_ADJ_MAX'
    WHEN F.ShortName = 'VEHICLE'        AND PARAM.ShortName = 'RETAIL'               AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'VEHICLE_RETAIL_MIN'
    WHEN F.ShortName = 'VEHICLE'        AND PARAM.ShortName = 'RETAIL_ADJUSTED'      AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'VEHICLE_RETAIL_ADJ_MIN'
    WHEN F.ShortName = 'VEHICLE'        AND PARAM.ShortName = 'WHOLESALE'            AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'VEHICLE_WHOLESALE_MIN'
    WHEN F.ShortName = 'VEHICLE'        AND PARAM.ShortName = 'WHOLESALE_ADJUSTED'   AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'VEHICLE_WHOLESALE_ADJ_MIN'
    WHEN F.ShortName = 'CREDIT_SCORE'   AND PARAM.ShortName = 'SCORE'                AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'CREDIT_SCORE_APP_MIN'
    WHEN F.ShortName = 'CREDIT_SCORE'   AND PARAM.ShortName = 'COBO'                 AND (V.Operator='GTE' OR V.Operator = 'GT') THEN 'CREDIT_SCORE_COBO_MIN'
    WHEN F.ShortName = 'CREDIT_SCORE'   AND PARAM.ShortName = 'SCORE'                AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'CREDIT_SCORE_APP_MAX'
    WHEN F.ShortName = 'CREDIT_SCORE'   AND PARAM.ShortName = 'COBO'                 AND (V.Operator='LTE' OR V.Operator = 'LT') THEN 'CREDIT_SCORE_COBO_MAX'
    ELSE ' * fillmein * '
  END,

  Filter = F.ShortName,
  Parameter = PARAM.ShortName,

  Value = CASE
    WHEN PARAM.ShortName = 'COMB_OVERRIDE' THEN ISNULL(NULLIF(V.Value, ''), 'False')
    WHEN PARAM.DataTypeID = 2    THEN  REPLACE(REPLACE(V.Value, ',', ''), '$', '')
    ELSE V.Value
  END,

  V.Operator
FROM
  tblLenders              LENDER    WITH(NOLOCK)
  JOIN tblPrograms        PROGRAM   WITH(NOLOCK) ON (LENDER.LenderID = Program.LenderID)
  JOIN tblProgramFilter   PF        WITH(NOLOCK) ON (PF.ProgramID = PROGRAM.ProgramID)
  JOIN tblValues          V         WITH(NOLOCK) ON (V.ProgramFilterID = PF.ProgramFilterID)
  JOIN tblParameters      PARAM     WITH(NOLOCK) ON (V.ParameterID = PARAM.ParameterID)
  JOIN tblFilters         F         WITH(NOLOCK) ON (PARAM.FilterID = F.FilterID)
WHERE
  (NOT LENDER.SUBMIT_STATUS = 'CLOSED')
  AND (PROGRAM.Underwriting = 1 OR PROGRAM.Automated = 1)
  AND PROGRAM.Active = 1
  AND LEN(ISNULL(V.Value, '')) > 0
  AND (
      (F.ShortName ='AMOUNT_FINANCE'    AND PARAM.ShortName IN('AMOUNT_FINANCED', 'PURCHASE_PRICE'))
   OR (F.ShortName ='CREDIT_SCORE'      AND PARAM.ShortName IN('SCORE', 'SCORECARD', 'COBO', 'COMB_OVERRIDE'))
   OR (F.ShortName ='DTI'               AND PARAM.ShortName IN('APP', 'COMB', 'COMB_OVERRIDE'))
   OR (F.ShortName ='LOAN_TERM'         AND PARAM.ShortName IN('MONTHS'))
   OR (F.ShortName ='LTV'               AND PARAM.ShortName IN('BOOK_SOURCE', 'RETAIL', 'RETAIL_ADJUSTED', 'WHOLESALE_ADJUSTED', 'WHOLESALE_BASE'))
   OR (F.ShortName ='LTV_NET'           AND PARAM.ShortName IN('BOOK_SOURCE', 'RETAIL', 'RETAIL_ADJUSTED', 'WHOLESALE_ADJUSTED', 'WHOLESALE_BASE'))
   OR (F.ShortName ='PTI'               AND PARAM.ShortName IN('APP', 'COMB', 'COMB_OVERRIDE'))
   OR (F.ShortName ='VEHICLE'           AND PARAM.ShortName IN('RETAIL', 'WHOLESALE'))
  )
ORDER BY
  LENDER.LenderID,
  PROGRAM.ProgramID






