/****** Object:  View dbo.viewB2B_DecisionsPendingToSend_Inner    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW [viewB2B_DecisionsPendingToSend_Inner] AS
	SELECT
		[DSR].*,
		[Decisioned]								= CONVERT(BIT, CASE WHEN [DSR].[IsDecision] = 1 THEN 1 WHEN [Latest_Decision].[LoanApp_BidID] IS NULL THEN 0 ELSE 1 END),
		[IsLatestDecision]					= CONVERT(BIT, CASE WHEN [Latest_Decision].[LoanApp_BidID] IS NOT NULL AND [Latest_Decision].[LoanApp_BidID] = [DSR].[LoanApp_BidID] THEN 1 WHEN [DSR].[IsDecision] = 1 AND [Latest_Decision].[LoanApp_BidID] IS NULL THEN 1 ELSE 0 END),
		[LatestDecisionBidID]				= CASE WHEN [Latest_Decision].[LoanApp_BidID] IS NOT NULL THEN [Latest_Decision].[LoanApp_BidID] WHEN [DSR].[IsDecision] = 1 THEN [DSR].[LoanApp_BidID] END,
		[IsLatestBid]								= CONVERT(BIT, CASE WHEN [Latest_Bid].[LoanApp_BidID] = [DSR].[LoanApp_BidID] THEN 1 ELSE 0 END),
		[LatestBidID]								= [Latest_Bid].[LoanApp_BidID],
		[SendDecisions]							= CONVERT(BIT, CASE WHEN [DSR].[PartnerToolID] IN (61)		THEN 0 ELSE 1 END),
		[SendNonDecisions]					= CONVERT(BIT, CASE WHEN [DSR].[PartnerToolID] IN (61)		THEN 1 ELSE 0 END),
		[SendNewDecisions]					= CONVERT(BIT, CASE WHEN [DSR].[PartnerToolID] IN (2)			THEN 1 ELSE 0 END),
		[SendNewNonDecisions]				= CONVERT(BIT, 0),
		[ResendOnError]							= CONVERT(BIT, CASE WHEN [DSR].[PartnerToolID] IN (52)		THEN 0 ELSE 1 END),
		[OnlySendUserInitiated]			= CONVERT(BIT, CASE WHEN [DSR].[PartnerToolID] IN (61)		THEN 1 ELSE 0 END),
		[LendersBranchID]						= [Bid].[LendersBranchID],
		[Locked]										= CONVERT(BIT, CASE WHEN [Locks].[SessionID] IS NULL THEN 0 ELSE 1 END),
		[LockedBySessionID]					=	[Locks].[SessionID]
	FROM
								[viewB2B_DecisionSenderReceipts]	[DSR]							WITH (NOLOCK)
					JOIN	[tblLoanApp_Bids]									[Bid]							WITH (NOLOCK) ON [Bid].[LoanApp_BidID]					= [DSR].[LoanApp_BidID]
					JOIN	[tblLoanApp_Bids]									[Latest_Bid]			WITH (NOLOCK) ON [Latest_Bid].[LoanApp_BidID]		= (SELECT MAX([LoanApp_BidID]) FROM [tblLoanApp_Bids] [Bid_Inner] WITH (NOLOCK) JOIN [tblLendersBranches] [Branch_Inner] WITH (NOLOCK) ON [Branch_Inner].[LendersBranchID] = [Bid_Inner].[LendersBranchID] AND [Branch_Inner].[LenderID] = [DSR].[LenderID] WHERE [Bid_Inner].[LoanAppID] = [DSR].[LoanAppID] AND [Bid_Inner].[Canceled_Date] IS NULL)
		LEFT	JOIN	[tblPartnerSender_Lock]						[Locks]						WITH (NOLOCK) ON [Locks].[LoanApp_BidID] 				= [Bid].[LoanApp_BidID] AND [Locks].[PartnerToolID] = [DSR].[PartnerToolID] AND [Locks].[ExpireDateTime] >= GETDATE()
		LEFT	JOIN	[viewBidsLatestDecision] 					[Latest_Decision]	WITH (NOLOCK) ON [Latest_Decision].[LoanAppID]	= [DSR].[LoanAppID]			AND [Latest_Decision].[LenderID] = [DSR].[LenderID]
	WHERE
			[DSR].[CreateDateTime]		>= DATEADD(d, -30, GETDATE())
		-- AND	[DSR].[UpdateDateTime]		>= DATEADD(d, -30, GETDATE())


