/****** Object:  View dbo.viewB2B_PartnerBidHistory    Script Date: 7/31/2024 12:57:24 PM ******/

--SELECT @LoanAppID = LoanAppID, @LoanApp_BidID = LoanApp_BidID FROM tblLoanApp_Bids WITH (NOLOCK) WHERE LoanApp_BidID = 2500653;


-- SELECT TOP 1 * FROM [tblPartnerDecision_Receipt]				[PDR]						WITH (NOLOCK);

CREATE VIEW [dbo].[viewB2B_PartnerBidHistory] AS
SELECT
	[Bid].[LoanAppID],
	[Bid].[LoanApp_BidID],
	[Branch].[LenderID],
	[Partner].[PartnerToolID],
	[TryCount]										= SUM([PDR].[TryCount]),
	[SuccessCount]								= SUM([PDR].[SuccessCount]),
	[ErrorCount]									= SUM([PDR].[ErrorCount]),
	[FirstAttempt]								= MIN([PDR].[TS_FirstAttempt]),
	[LastAttempt]									= MAX([PDR].[TS_LastAttempt]),
	[LastAttemptAgo]							= CASE WHEN SUM([PDR].[TryCount]) > 0 THEN DATEDIFF(s, MAX([PDR].[TS_LastAttempt]), GETDATE()) END
FROM
				[tblLoanApp_Bids]										[Bid]						WITH (NOLOCK)
	JOIN	[tblLendersBranches]								[Branch]				WITH (NOLOCK) ON [Branch].[LendersBranchID]				= [Bid].[LendersBranchID]
	JOIN	[tblLenders]												[Lender]				WITH (NOLOCK) ON [Lender].[LenderID]							= [Branch].[LenderID]
	JOIN	[tblPartnerDecision_Receipt]				[PDR]						WITH (NOLOCK) ON [PDR].[LoanApp_BidID]						= [Bid].[LoanApp_BidID]
	JOIN	[tblPartnerTools]										[Partner]				WITH (NOLOCK) ON [Partner].[PartnerToolID]				= [PDR].[PartnerToolID]
	LEFT JOIN 	[viewPartnersActivatedForBranch]		[Activation]		WITH (NOLOCK) ON [Activation].[LendersBranchID]		= [Bid].[LendersBranchID]			AND [Activation].[PartnerToolID]				= [PDR].[PartnerToolID]
WHERE
			[Bid].[CreateDateTime] >= DATEADD(d, -60, GETDATE())
			--AND [Bid].[LoanAppID] = (SELECT TOP 1 LoanAppID FROM tblLoanApp_Bids WITH (NOLOCK) WHERE LoanApp_BidID = 2500653)
GROUP BY
	[Bid].[LoanAppID],
	[Bid].[LoanApp_BidID],
	[Branch].[LenderID],
	[Partner].[PartnerToolID]















