/****** Object:  View dbo.viewB2B_QueuePriority_Outer    Script Date: 7/31/2024 12:57:24 PM ******/
/*
SELECT 
--TOP 500 * 
[Count] = COUNT(*)
FROM [viewB2B_QueuePriority_Inner]		[Queue]		WITH (NOLOCK);

RETURN
*/

CREATE VIEW [viewB2B_QueuePriority_Outer] AS
	SELECT
	--TOP 500
		[PartnerToolID]				 		= [Queue].[PartnerToolID],
		[Partner]									= [Queue].[Partner],
		[LoanAppID]						 		= [Queue].[LoanAppID],
		[LoanApp_BidID]				 		= [Queue].[LoanApp_BidID],
		[LenderID]						 		= [Queue].[LenderID],
		[LendersBranchID]			 		= [Queue].[LendersBranchID],
		--[Lender]									= [Queue].[Lender],
		--[DealerID]						 		= [Queue].[DealerID],
		--[Dealer]									= [Queue].[Dealer],
		[BidStatus]								= [Queue].[BidStatus],
		[isManuallyTriggered]			= [Queue].[isManuallyTriggered],
		[isDecision]							= [Queue].[isDecision],
		[isPending]								= [Queue].[isPending],
		-- [Bids]								 		= [Queue].[Bids],
		-- [Decisions]						 		= [Queue].[Decisions],
		-- [Pendings]					 			= [Queue].[Pendings],
		[TS_Success]								= [PDR].[TS_Success],

		[isLatestBid]								= CONVERT(BIT, CASE 																			WHEN [Queue].[Bids]	= 1															THEN 1	WHEN [Queue].[LoanApp_BidID] = (SELECT TOP 1 [Bids].[LoanApp_BidID] FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK)	WHERE [Bids].[LoanAppID] = [Queue].[LoanAppID] AND EXISTS(SELECT * FROM [tblLendersBranches] [Branches] WITH (NOLOCK) WHERE [Branches].[LendersBranchID] = [Bids].[LendersBranchID]	AND [Branches].[LenderID] = [Queue].[LenderID])	AND [Bids].[Canceled_Date] IS NULL ORDER BY [Bids].[UpdateDateTime] DESC, [Bids].[Offer_Date] DESC) THEN 1 ELSE 0 END),
		[isLatestDecision]					= CONVERT(BIT, CASE	WHEN [Queue].[isDecision]	= 0 THEN 0	WHEN [Queue].[Bids]	= 1 OR [Queue].[Decisions]	= 1	THEN 1	WHEN [Queue].[LoanApp_BidID] = (SELECT TOP 1 [Bids].[LoanApp_BidID] FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK)	WHERE [Bids].[LoanAppID] = [Queue].[LoanAppID] AND EXISTS(SELECT * FROM [tblLendersBranches] [Branches] WITH (NOLOCK) WHERE [Branches].[LendersBranchID] = [Bids].[LendersBranchID]	AND [Branches].[LenderID] = [Queue].[LenderID]) AND [Bids].[Canceled_Date] IS NULL	AND [Bids].[Status] IN ('PENDING_DEALER', 'DECLINE_DEALER', 'DECLINE_LENDER', 'ACCEPTED') AND [Bids].[Offer_Date] IS NOT NULL ORDER BY [Bids].[Offer_Date] DESC, [Bids].[UpdateDateTime] DESC) THEN 1 ELSE 0 END),
		[isLatestPending]						= CONVERT(BIT, CASE	WHEN [Queue].[isPending]	= 0 THEN 0	WHEN [Queue].[Bids]	= 1 OR [Queue].[Pendings]		= 1	THEN 1	WHEN [Queue].[LoanApp_BidID] = (SELECT TOP 1 [Bids].[LoanApp_BidID] FROM [tblLoanApp_Bids] [Bids] WITH (NOLOCK)	WHERE [Bids].[LoanAppID] = [Queue].[LoanAppID] AND EXISTS(SELECT * FROM [tblLendersBranches] [Branches] WITH (NOLOCK) WHERE [Branches].[LendersBranchID] = [Bids].[LendersBranchID]	AND [Branches].[LenderID] = [Queue].[LenderID]) AND [Bids].[Canceled_Date] IS NULL	AND [Bids].[Status] IN ('REFERRED', 'PENDING_LENDER') ORDER BY [Bids].[UpdateDateTime] DESC) THEN 1 ELSE 0 END),
		[Sent]											= CONVERT(BIT, CASE WHEN [PDR].[SuccessCount]	= 0 OR [PDR].[TS_Success] IS NULL THEN 0 ELSE 1 END)
		
		--[SentLatestDecision]				= CONVERT(BIT, CASE WHEN [PDR].[SuccessCount] > 0 AND [Queue].[isDecision] = 1 AND [PDR].[TS_Success] IS NOT NULL AND [PDR].[TS_Success] >= [Bid].[Offer_Date] THEN 1 ELSE 0 END)
		/*,
		
		[SentAgo]										= DATEDIFF(ss, [PDR].[TS_Success], GETDATE()),
		[LastAttemptAgo]						= DATEDIFF(ss, [PDR].[TS_LastAttempt], GETDATE()),
		[LastErrorAgo]							= DATEDIFF(ss, [PDR].[TS_LastError], GETDATE())*/
	FROM
					[tblLoanApp_Bids]								[Bid]			WITH (NOLOCK)
		JOIN	[tblPartnerDecision_Receipt]		[PDR]			WITH (NOLOCK) ON	[PDR].[LoanApp_BidID]	= [Bid].[LoanApp_BidID]
		JOIN	[viewB2B_QueuePriority_Inner]		[Queue]		WITH (NOLOCK) ON	[Queue].[LoanApp_BidID]	= [Bid].[LoanApp_BidID] AND [Queue].[PartnerToolID] = [PDR].[PartnerToolID]
	WHERE
		--[Bid].[CreateDateTime] >= DATEADD(d, -30, GETDATE()) AND [Bid].[Canceled_Date] IS NULL AND
		--[Queue].[PartnerToolID] = 61	AND
		--[Queue].[isManuallyTriggered] = 1	AND
		--[PDR].[TryCount] > 0
		1 = 1
/*
GROUP BY
	[Bid].[OFFER_DATE],
	[PDR].[SuccessCount],
	[PDR].[TS_LastAttempt],
	[PDR].[TS_LastError],
	[PDR].[TS_Success],


	[Queue].[BidCreated],
	[Queue].[Bids],
	[Queue].[BidStatus],
	[Queue].[BidUpdated],
	[Queue].[Dealer],
	[Queue].[DealerID],
	[Queue].[Decisions],
	[Queue].[isDecision],
	[Queue].[isManuallyTriggered],
	[Queue].[isPending],
	[Queue].[Lender],
	[Queue].[LenderID],
	[Queue].[LendersBranchID],
	[Queue].[LoanApp_BidID],
	[Queue].[LoanAppID],
	[Queue].[Offer_Date],
	[Queue].[Partner],
	[Queue].[PartnerToolID],
	[Queue].[Pendings],
	[Queue].[ReceiptCreated],
	[Queue].[ReceiptUpdated]
*/

