/****** Object:  View dbo.viewB2B_V3_QueuePriority    Script Date: 7/31/2024 12:57:24 PM ******/





--select * from tblpartnertools
--SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE 'view%Partner%Acti%'
--SELECT	* FROM	[viewPartnersActivatedForBranch] [PAB] WITH (NOLOCK) WHERE activatedbylenderid=0 and activatedbylendersbranchid=0;
--RETURN
--SELECT COUNT(*) FROM [viewB2B_V3_QueuePriority] WITH (NOLOCK) WHERE [Priority] > 0
CREATE    VIEW [dbo].[viewB2B_V3_QueuePriority] AS
	SELECT
		[LoanApp_BidID]			= [Bid].[LoanApp_BidID],
		-- LoanAppID			= MIN([Bid].[LoanAppID]),
		 LenderID				= MIN([Branch].[LenderID]),
		 LendersBranchID		= MIN([Branch].[LendersBranchID]),
		-- Original_BidID		= [Bid_Base].[LoanApp_BidID],
		[PartnerToolID]			= [PDR].[PartnerToolID],
		[Priority] = CASE

			WHEN [PDR].[PartnerToolID] IN (61, 65, 67) AND MIN([Bid].[Status]) = 'PENDING_DEALER' AND MIN([PDR].[UpdateUser])	<> 'sp_B2B_Submit'									THEN -202
			WHEN [PDR].[PartnerToolID] IN (61) AND [PDR].[ErrorCount] > 5																											THEN -666
			WHEN [PDR].[PartnerToolID] IN (65, 67) AND [PDR].[ErrorCount] > 0																										THEN -666
			WHEN [PDR].[PartnerToolID] IN (61, 65, 67) AND [PDR].[TS_Success] IS NOT NULL																							THEN -665
			--WHEN [PDR].[PartnerToolID] IN (65) AND [PDR].[TS_Success] IS NULL AND [PDR].[TS_LastAttempt] IS NOT NULL
			--	AND EXISTS (
			--		SELECT * 
			--		FROM [tblPartnerDecision_Attempt] [Attempt] WITH (NOLOCK) 
			--		WHERE 
			--			[Attempt].PartnerToolID=[PDR].[PartnerToolID]
			--			AND [Attempt].[LoanApp_BidID] = [Bid].[LoanApp_BidID]
			--			AND [Try]=(SELECT MAX([Try]) FROM [tblPartnerDecision_Attempt] WHERE [PartnerToolID]=[PDR].[PartnerToolID] AND [LoanApp_BidID]=[Bid].[LoanApp_BidID])
			--			AND [ResponseStatus]=200
			--		)																																							THEN -665
			WHEN [PDR].[PartnerToolID] IN (61, 65, 67) AND EXISTS (SELECT * FROM [tblPartnerDecision_Receipt_ValidationError] [Error] WITH (NOLOCK) WHERE
				[Error].[PartnerToolID] = [PDR].[PartnerToolID] AND [Error].[LoanApp_BidID] = [Bid].[LoanApp_BidID] AND 
				[Error].[UpdateDateTime] > MAX([PDR].[UpdateDateTime]))																											THEN -205
			WHEN [PDR].[PartnerToolID] IN (61, 65, 67) AND NOT EXISTS(SELECT	* FROM	[viewPartnersActivatedForBranch] [PAB] WITH (NOLOCK)
				WHERE [PAB].[PartnerToolID]	= [PDR].[PartnerToolID] AND	[PAB].[LendersBranchID] = MIN([Branch].[LendersBranchID]) AND [PAB].[ActivatedByLendersBranchID] = 1)	THEN -206
			WHEN [PDR].[PartnerToolID] IN (61, 65, 67) AND NOT EXISTS(SELECT	* FROM	[viewLenderPartnersActivatedForBid] [PAB] WITH (NOLOCK)
				WHERE	[PAB].[PartnerToolID]	= [PDR].[PartnerToolID] AND	[PAB].[LoanApp_BidID]	= [Bid].[LoanApp_BidID] AND	[PAB].[Active] = 1)								THEN -203
			WHEN [PDR].[PartnerToolID] IN (61, 65, 67) AND NULLIF(MIN([Bid].[Lender_Credit_TU]), '') IS NULL AND NOT EXISTS(SELECT * FROM [viewLenderPartnerFields] 
				[Field] WITH (NOLOCK) WHERE [Field].[PartnerToolID] = [PDR].[PartnerToolID] AND [Field].[Field] = 'USE_AllowPostingWithoutBureau' AND 
				[Field].[LendersBranchID] = MIN([Bid].[LendersBranchID]) AND [Field].[Value] = 'TRUE')																			THEN -204
			/*
			WHEN [PDR].[PartnerToolID] = 61 AND NOT EXISTS(SELECT * FROM [view_LoanApps_Bids] [Worksheet] WITH (NOLOCK) WHERE 
				[Worksheet].[LoanApp_BidID] = [Bid].[LoanApp_BidID] AND LEN([Worksheet].[VEHICLE_VIN]) = 17 AND [Worksheet].[LOAN_TOTAL_LOAN_AMOUNT] > 0 
				AND [Worksheet].[VEHICLE_MILEAGE] <= 120000 AND YEAR(GETDATE()) - [Worksheet].[Vehicle_Year] <= 10)																THEN -205
			/*WHEN [PDR].[PartnerToolID] = 61 AND NULLIF(MIN([Bid].[Lender_Credit_TU]), '') IS NOT NULL AND NOT EXISTS(SELECT * FROM [tblCreditPulls]
				[Credit] WITH (NOLOCK) WHERE [Credit].[GUID] = MIN([Bid].[Lender_Credit_TU]) AND DATALENGTH([Credit].[Data_Raw]) > 64) AND NOT EXISTS
				(SELECT * FROM [viewLenderPartnerFields] [Field] WITH (NOLOCK) WHERE [Field].[PartnerToolID] = [PDR].[PartnerToolID] AND 
				[Field].[Field] = 'USE_AllowPostingWithoutBureau' AND [Field].[LendersBranchID] = MIN([Bid].[LendersBranchID]) AND [Field].[Value] = 'TRUE')	THEN -205*/
			*/
			WHEN [PDR].[TS_Success] IS NULL AND [PDR].[ErrorCount] > 2 AND [PDR].[TS_LastError] IS NOT NULL 
				AND DATEADD(s, ([PDR].[ErrorCount] - 2) * 30, [PDR].[TS_LastError]) > GETDATE()																					THEN -666
			WHEN [PDR].[PartnerToolID] <> 2 AND [PDR].[TS_Success] IS NOT NULL																									THEN -500
			WHEN [PDR].[TS_Success] IS NOT NULL AND [Bid].[Offer_Date] > [PDR].[TS_Success]																						THEN 100
			WHEN [PDR].[TS_Success] IS NOT NULL AND [PDR].[TS_Success] > (SELECT MAX([Offer_Date]) FROM	[tblLoanApp_Bids] Bid_Other WITH (NOLOCK)
				JOIN	[tblLendersBranches] [Branch_Other] WITH (NOLOCK) ON [Branch_Other].[LendersBranchID] = [Bid_Other].[LendersBranchID]
					AND	[Branch_Other].[LenderID] = [Branch].[LenderID] WHERE	[Bid_Other].[LoanAppID] = [Bid].[LoanAppID] 
					AND	[Bid_Other].[Offer_Date] IS NOT NULL AND [Bid_Other].[Status] IN ('PENDING_DEALER', 'DECLINE_LENDER') )													THEN -100
			-- DON'T SEND IF NO OFFER DATE
			--WHEN [Bid].[Offer_Date]									IS NULL																									THEN -100
			-- DON'T SEND IF 'TOO' NEW
			--WHEN DATEDIFF(ss, [Bid].[Offer_Date], GETDATE())		< 15																										THEN -200
			-- DON'T SEND IF WE SENT IT LESS THAN 30 SECONDS AGO
			WHEN [PDR].[TS_LastAttempt] IS NOT NULL AND DATEDIFF(ss, [PDR].[TS_LastAttempt], GETDATE()) < 30																	THEN -500
			WHEN [PDR].[TS_Success] IS NULL	 and [PDR].[TS_LastError]	IS NOT NULL AND [PDR].[PartnerToolID] = 52																THEN -300
			WHEN [PDR].[TS_Success] IS NULL																																		THEN 1000 - [PDR].[ErrorCount] * 50 - ([PDR].[TryCount] - [PDR].[ErrorCount]) * 10
			--WHEN [PDR].[TS_Success]	IS NOT NULL AND [PDR].[TryCount] >=2																									THEN -600
			WHEN [PDR].[TS_Success]	IS NOT NULL AND DATEDIFF(d, [PDR].[TS_Success], GETDATE()) > 1																				THEN -400
			WHEN [PDR].[TS_Success]	IS NOT NULL AND [PDR].[TryCount] < 2 AND [PDR].[PartnerToolID] <> 52																		THEN 2000 + ( [PDR].[ErrorCount] * 100 ) + ( [PDR].[TryCount] * 10 )
		END,
		[PDR].[ErrorCount]
	FROM
				[tblLoanApp_Bids]					[Bid]				WITH (NOLOCK)
		JOIN	[tblPartnerDecision_Receipt]		[PDR]				WITH (NOLOCK) ON	[PDR].[LoanApp_BidID]				= [Bid].[LoanApp_BidID]
		JOIN	[tblLendersBranches]				[Branch]			WITH (NOLOCK) ON	[Branch].[LendersBranchID]			= [Bid].[LendersBranchID]

		JOIN	[tblLoanApps]						[App]				WITH (NOLOCK) ON [App].[LoanAppID]		= [Bid].[LoanAppID]
		JOIN	[tblDealers]						[Dealer]			WITH (NOLOCK) ON [Dealer].[DealerID]	= [App].[DealerID]

--		JOIN	[tblLenders]						[Lender]			WITH (NOLOCK) ON	[Lender].[LenderID]					= [Branch].[LenderID]
--		JOIN	[tblPartnerTools]					[Partner]			WITH (NOLOCK) ON	[Partner].[PartnerToolID]			= [PDR].[PartnerToolID]
	WHERE
		[PDR].[CreateDateTime] >= DATEADD(d, -30, GETDATE())
		AND [PDR].[ErrorCount] < 20
		--AND [PDR].[PartnerToolID] = 61 --AND [Bid].[LoanApp_BidID] IN (2505070, 2505084, 2488987, 2504280)
		AND ([PDR].[TS_Success] IS NULL OR [PDR].[PartnerToolID] IN (2, 12))
	GROUP BY
		[Bid].[LoanApp_BidID],
		[Bid].[LoanAppID],
		[Branch].[LenderID],
		[PDR].[PartnerToolID],
		[Bid].[Offer_Date],
		[PDR].[TS_LastAttempt],
		[PDR].[TS_Success],
		[PDR].[TS_LastError],
		[PDR].[ErrorCount],
		[PDR].[TryCount],
		[Bid].[UpdateDateTime]









