/****** Object:  View dbo.viewBidsAutomationPending_Outer_Outer    Script Date: 7/31/2024 12:57:24 PM ******/

CREATE VIEW viewBidsAutomationPending_Outer_Outer AS
	SELECT TOP 100 PERCENT
		LoanAppID					= [App].[LoanAppID],
		DealerID					= MIN([Dealer].[DealerID]),
		LenderID					= [Lender].[LenderID],
		LendersBranchID				= MIN([Branch].[LendersBranchID]),
		LoanApp_BidID				= MIN([Bid].[LoanApp_BidID]),
		Lender						= MIN(UPPER([Lender].[LenderName])),
		Branch						= MIN(UPPER([Branch].[BranchName])),
		Dealer						= MIN(UPPER([Dealer].[DealerName])),
		Customer					= MIN(UPPER([App].[Applicant_Names])),
		LenderPrefix				= MIN(UPPER([Lender].[LoginPrefix])),
		BranchPrefix				= MIN(UPPER(CASE WHEN LEN(RTRIM(LTRIM(ISNULL([Branch].[LoginPrefix], '')))) = 0 THEN [Lender].[LoginPrefix] ELSE [Branch].[LoginPrefix] END)),
		Status						= MIN([Bid].[Status]),
		CreditReportAccount			= MIN(UPPER(CASE WHEN LEN(ISNULL([Branch].[Microbilt_Login], '')) > 0 AND LEN(ISNULL([Branch].[Microbilt_Password], '')) > 0 THEN CONVERT(BIT, 1) WHEN LEN(ISNULL([Lender].[Microbilt_Login], '')) > 0 AND LEN(ISNULL([Lender].[Microbilt_Password], '')) > 0 THEN CONVERT(BIT, 1) ELSE CONVERT(BIT, 0) END)),
		CreditReportAccountSource	= MIN(UPPER(CASE WHEN LEN(ISNULL([Branch].[Microbilt_Login], '')) > 0 AND LEN(ISNULL([Branch].[Microbilt_Password], '')) > 0 THEN 'Lender_Branch' WHEN LEN(ISNULL([Lender].[Microbilt_Login], '')) > 0 AND LEN(ISNULL([Lender].[Microbilt_Password], '')) > 0 THEN 'Lender_MASTER' ELSE 'NONE' END)),
		CreditReportUserName		= MIN(UPPER(CASE WHEN LEN(ISNULL([Branch].[Microbilt_Login], '')) > 0 AND LEN(ISNULL([Branch].[Microbilt_Password], '')) > 0 THEN LTRIM(RTRIM([Branch].[MicroBilt_Login])) WHEN LEN(ISNULL([Lender].[Microbilt_Login], '')) > 0 AND LEN(ISNULL([Lender].[Microbilt_Password], '')) > 0 THEN LTRIM(RTRIM([Lender].[MicroBilt_Login])) ELSE '' END)),
		CreditReportPassword		= MIN(UPPER(CASE WHEN LEN(ISNULL([Branch].[Microbilt_Login], '')) > 0 AND LEN(ISNULL([Branch].[Microbilt_Password], '')) > 0 THEN LTRIM(RTRIM([Branch].[MicroBilt_Password])) WHEN LEN(ISNULL([Lender].[Microbilt_Login], '')) > 0 AND LEN(ISNULL([Lender].[Microbilt_Password], '')) > 0 THEN LTRIM(RTRIM([Lender].[MicroBilt_Password])) ELSE '' END)),
		Automation_Bureau			= MIN(UPPER([Lender].[AUTOMATION_CREDIT_PROVIDER])),
		Existing_Bureau				= MIN(CASE WHEN LEN(ISNULL([Bid].[Lender_CREDIT_EX], '')) = 38 THEN [Bid].[Lender_CREDIT_EX] WHEN LEN(ISNULL([Bid].[Lender_CREDIT_TU], '')) = 38 THEN [Bid].[Lender_CREDIT_TU] WHEN LEN(ISNULL([Bid].[Lender_CREDIT_EQ], '')) = 38 THEN [Bid].[Lender_CREDIT_EQ] ELSE '' END),
		Has_Existing_Bureau			= CONVERT(BIT, CASE WHEN NULlif([Lender].[AUTOMATION_CREDIT_PROVIDER], '') IS NULL THEN 0 WHEN LEN(ISNULL([Bid].[Lender_CREDIT_EX], ''))			= 38 THEN 1 WHEN LEN(ISNULL([Bid].[Lender_CREDIT_TU], ''))			= 38 THEN 1 WHEN LEN(ISNULL([Bid].[Lender_CREDIT_EQ], ''))			= 38 THEN 1 ELSE 0 END),
		CreditPullID_EQ				= MAX(ISNULL([Credit_EQ].[CreditPullID], 0)),
		CreditPullID_EX				= MAX(ISNULL([Credit_EX].[CreditPullID], 0)),
		CreditPullID_TU				= MAX(ISNULL([Credit_TU].[CreditPullID], 0)),
		Age							= DATEDIFF(s, [Bid].[UpdateDateTime], GETDATE()),
		BidSubmit					= DATEDIFF(d, [Bid].[Submit_Date], GETDATE()),
		BidOffer					= DATEDIFF(d, [Bid].[Offer_Date], GETDATE()),

		HasAutoDeclinePrograms		= [Program].[HasAutoDeclinePrograms],
		HasAutoOfferPrograms		= [Program].[HasAutoOfferPrograms]
	FROM
					[tblLoanApp_Bids]				[Bid]			WITH (NOLOCK)
		JOIN		[tblLoanApps]					[App]			WITH (NOLOCK) ON [Bid].[LoanAppID]										= [App].[LoanAppID]
		JOIN		[tblDealers]					[Dealer]		WITH (NOLOCK) ON [Dealer].[DealerID]									= [App].[DealerID]
		JOIN		[tblLendersBranches]			[Branch]		WITH (NOLOCK) ON [Branch].[LendersBranchID]								= [Bid].[LendersBranchID]
		JOIN		[tblLenders]					[Lender]		WITH (NOLOCK) ON [Branch].[LenderID]									= [Lender].[LenderID]
		JOIN		[viewLendersProgramStatus]		[Program]		WITH (NOLOCK) ON [Program].[LenderID]									= [Lender].[LenderID]		AND [Program].[HasAutomatedPrograms]	= 1
--		JOIN		[tblPrograms]					[PROGRAM]		WITH (NOLOCK) ON [Program].[LenderID]									= [Lender].[LenderID]		AND [Program].[Active]					= 1										AND [Program].[Automated] = 1
		LEFT JOIN	[tblCreditPulls]				[Credit_EX]		WITH (NOLOCK) ON [DBO].[IsGUID](NULLIF([Bid].[Lender_Credit_EX], ''))	= 1							AND [Credit_EX].[GUID]					= NULLIF([Bid].[Lender_Credit_EX], '')
		LEFT JOIN	[tblCreditPulls]				[Credit_TU]		WITH (NOLOCK) ON [DBO].[IsGUID](NULLIF([Bid].[Lender_Credit_TU], ''))	= 1							AND [Credit_TU].[GUID]					= NULLIF([Bid].[Lender_Credit_TU], '')
		LEFT JOIN	[tblCreditPulls]				[Credit_EQ]		WITH (NOLOCK) ON [DBO].[IsGUID](NULLIF([Bid].[Lender_Credit_EQ], ''))	= 1							AND [Credit_EQ].[GUID]					= NULLIF([Bid].[Lender_Credit_EQ], '')
	WHERE
			[Bid].[CreateDateTime] >= DATEADD(d, -30, GETDATE())
		AND [Bid].[Status] IN ('PENDING_AUTOMATION', 'PROCESSING_AUTOMATION', 'PENDING_AUTOMATION_CREDIT', 'PENDING_LENDER', 'REFERRED', 'PENDING_DEALER', 'DECLINE_LENDER')
		AND (DATEDIFF(d, [Bid].[UpdateDateTime], GETDATE()) <= 2 OR DATEDIFF(d, [Bid].[Submit_Date], GETDATE()) <= 2 OR DATEDIFF(d, [Bid].[Offer_Date], GETDATE()) <= 2)
		AND	NULLIF([Lender].[Automation_Credit_Provider], '')	IS NOT NULL
		AND	NULLIF(NULLIF([App].[LenderID], 0), '')				IS NULL



--OR (LEN() > 0 AND [Lender].[LenderID] IN(1094, 227, 1037) AND [Bid].[Status] IN ('REFERRED', 'PENDING_LENDER', 'PENDING_Dealer', 'DECLINE_Lender') AND [Bid].[CreateDateTime] >= '2014-03-01')

	GROUP BY
		[App].[LoanAppID],
		[Lender].[LenderID],
		[Bid].[UpdateDateTime],
		[Bid].[Submit_Date],
		[Bid].[Offer_Date],
		[Bid].[Offered_By],
		[Lender].[Automation_Credit_Provider],
		[Bid].[Lender_Credit_EX],
		[Bid].[Lender_Credit_EQ],
		[Bid].[Lender_Credit_TU],
		[Credit_EX].[Bureau],
		[Credit_TU].[Bureau],
		[Credit_EQ].[Bureau],
		[Program].[HasAutoDeclinePrograms],
		[Program].[HasAutoOfferPrograms]

	ORDER BY
		LoanApp_BidID,
		[Lender].[LenderID]


