/****** Object:  View dbo.viewFilterAutoDeclineReasons    Script Date: 7/31/2024 12:57:24 PM ******/
/*
DELETE FROM [tblLoanApp_AutoDeclineProgramResult];
DELETE FROM [tblLoanApp_AutoDeclineResult];
*/

/*
	SELECT
		[Param].[FilterID]
	FROM
					[tblPrograms]				[Program] WITH (NOLOCK)
		JOIN	[tblProgramFilter]	[ProgramFilter] WITH (NOLOCK) ON [ProgramFilter].[ProgramID] = [Program].[ProgramID]
		JOIN	[tblValues]					[Values] WITH (NOLOCK) ON [Values].[ProgramFilterID] = [ProgramFilter].[ProgramFilterID]
		JOIN	[tblParameters]			[Param] WITH (NOLOCK) ON [Param].[ParameterID] = [Values].[ParameterID]
	WHERE
		[Program].[AutoDecline] = 1

	RETURN
*/

	CREATE VIEW [viewFilterAutoDeclineReasons] AS
		SELECT
			[Lender].[LenderID], [Decline_Global].[FilterID],
			[Source] = CASE WHEN [Decline_Specific].[FilterDeclineID] IS NOT NULL THEN 'Lender' ELSE 'Global' END,
			[FilterDeclineID] = ISNULL([Decline_Specific].[FilterDeclineID], [Decline_Global].[FilterDeclineID]),
			[AutoDeclineEnabled] = CASE WHEN [Decline_Global].[AutoDeclineEnabled] = 0 THEN 0 WHEN [Decline_Specific].[FilterDeclineID] IS NOT NULL THEN [Decline_Specific].[AutoDeclineEnabled] ELSE [Decline_Global].[AutoDeclineEnabled] END,
			[Reasons] = (SELECT COUNT(*) FROM [tblFilterDeclineReasons] [Reasons_Inner]	WITH (NOLOCK) WHERE [Reasons_Inner].[FilterDeclineID] = [Reasons].[FilterDeclineID]),
			[Reason].[DeclineReasonID]
		FROM
										[tblLenders]							[Lender]						WITH (NOLOCK)
				LEFT 	JOIN	[tblFilterDecline]				[Decline_Global]		WITH (NOLOCK) ON [Decline_Global].[LenderID] IS NULL
				LEFT 	JOIN	[tblFilterDecline]				[Decline_Specific]	WITH (NOLOCK) ON [Decline_Specific].[FilterID] = [Decline_Global].[FilterID] AND [Decline_Specific].[LenderID] = [Lender].[LenderID]
				LEFT 	JOIN	[tblFilterDeclineReasons]	[Reasons]						WITH (NOLOCK) ON [Reasons].[FilterDeclineID] = ISNULL([Decline_Specific].[FilterDeclineID], [Decline_Global].[FilterDeclineID])
				LEFT 	JOIN [tblDeclineReasons]				[Reason]						WITH (NOLOCK) ON [Reason].[DeclineReasonID] = [Reasons].[DeclineReasonID]
		WHERE
			EXISTS(SELECT * FROM [tblPrograms] [Programs] WITH (NOLOCK) WHERE [Programs].[LenderID] = [Lender].[LenderID] AND [Programs].[AutoDecline] = 1)
		/*ORDER BY
			[Lender].[LenderID], [Decline_Global].[FilterID]*/



