/****** Object:  View dbo.viewFilterGen2_TimeStamps_Inner    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW viewFilterGen2_TimeStamps_Inner AS
	SELECT
		Lenderid							= Lender.LenderID,
		BranchID							= Branch.LendersBranchID,
		ProgramID							= Program.ProgramID,
		ProgramFilterID						= ProgramFilter.ProgramID,
		ValueID								= Value.ValueID,
		HighestDateStamp					= [CreditSmarts].[dbo].[HighestDateOf8](ISNULL( Value.UpdateDateTime, Value.CreateDateTime), ISNULL( ProgramFilter.UpdateDateTime, ProgramFilter.CreateDateTime), ISNULL(Program.UpdateDateTime, Program.CreateDateTime), ISNULL(Branch.UpdateDateTime, Branch.CreateDateTime), ISNULL(Lender.UpdateDateTime, Lender.CreateDateTime), NULL, NULL, NULL ),
		LenderUpdated						= ISNULL(Lender.UpdateDateTime,			Lender.CreateDateTime),
		BranchUpdated						= ISNULL(Branch.UpdateDateTime,			Branch.CreateDateTime),
		ProgramUpdated						= ISNULL(Program.UpdateDateTime,		Program.CreateDateTime),
		ProgramFilterUpdated				= ISNULL(ProgramFilter.UpdateDateTime,	ProgramFilter.CreateDateTime),
		ValueUpdated						= ISNULL(Value.UpdateDateTime,			Value.CreateDateTime),
--		StipsUpdated						= ISNULL(Stips.UpdateDateTime,			Stips.CreateDaeTime),
	
		LenderCreated						= ISNULL(Lender.CreateDateTime,			Lender.UpdateDateTime),
		BranchCreated						= ISNULL(Branch.CreateDateTime,			Branch.UpdateDateTime),
		ProgramCreated						= ISNULL(Program.CreateDateTime,		Program.UpdateDateTime),
		ProgramFilterCreated				= ISNULL(ProgramFilter.CreateDateTime,	ProgramFilter.UpdateDateTime),
		ValueCreated						= ISNULL(Value.CreateDateTime,			Value.UpdateDateTime)
--		StipsCreated						= ISNULL(Stips.CreateDateTime,			Stips.UpdateDaeTime)
	FROM
					tblLenders					Lender
		LEFT JOIN tblLendersBranches			Branch			ON Branch.LenderID			= Lender.LenderID
		LEFT JOIN tblPrograms					Program			ON Program.LenderID			= Branch.LenderID
		LEFT JOIN tblProgramFilter				ProgramFilter	ON ProgramFilter.ProgramID	= Program.ProgramID
		LEFT JOIN tblValues						Value			ON Value.ProgramFilterID	= ProgramFilter.ProgramFilterID
		LEFT JOIN tblProgramFilterStipulations	Stips			ON Stips.ProgramFilterID	= ProgramFilter.ProgramFilterID
	WHERE
		NULLIF(Value.Value, '') IS NOT NULL
--	ORDER BY
--		Lender.UpdateDateTime DESC

