	S_R_A	= ISNULL(L.MIN_HOUSING_SINGLE_RENT_AMT, 0),
	S_M_A	= ISNULL(NULLIF(L.MIN_HOUSING_SINGLE_MORTGAGE_AMT, 0), ISNULL(L.MIN_HOUSING_SINGLE_RENT_AMT, 0)),
	J_R_A = ISNULL(NULLIF(L.MIN_HOUSING_JOINT_RENT_AMT, 0),  ISNULL(L.MIN_HOUSING_SINGLE_RENT_AMT, 0)),
	J_M_A = ISNULL(NULLIF(L.MIN_HOUSING_JOINT_MORTGAGE_AMT, 0), ISNULL(L.MIN_HOUSING_SINGLE_MORTGAGE_AMT, ISNULL(L.MIN_HOUSING_SINGLE_RENT_AMT, 0))),
	S_R_P = ISNULL(L.MIN_HOUSING_SINGLE_RENT_PCT, 0),
	S_M_P = ISNULL(NULLIF(L.MIN_HOUSING_SINGLE_MORTGAGE_PCT, 0), ISNULL(L.MIN_HOUSING_SINGLE_RENT_PCT, 0)),
	J_R_P = ISNULL(NULLIF(L.MIN_HOUSING_JOINT_RENT_PCT, 0), ISNULL(L.MIN_HOUSING_SINGLE_RENT_PCT, 0)),
	J_M_P = ISNULL(NULLIF(L.MIN_HOUSING_JOINT_MORTGAGE_PCT, 0), ISNULL(NULLIF(L.MIN_HOUSING_SINGLE_MORTGAGE_PCT, 0), ISNULL(L.MIN_HOUSING_SINGLE_RENT_PCT, 0))),

	P.ProgramID,
	P.ProgramName,
  P.CreditTier,
  P.Automated,
  P.Underwriting,
  P.AutoSelect,
  P.NoCredit,
  Submit = CASE
    WHEN Automated=0 AND Underwriting=0 THEN
      1
    ELSE
      0
  END,
	ISNULL(PF.Description, '') Description,
  ISNULL(PF.ProgramFilterID, 0) ProgramFilterID,
  (SELECT COUNT(*) FROM tblValues V WHERE Len(Value) > 0 AND ProgramFilterID = PF.ProgramFilterID) ParameterValueCount,
  (SELECT COUNT(*) FROM tblProgramFilterBranches WHERE ProgramFilterID = PF.ProgramFilterID) BranchFilterCount,
  (SELECT COUNT(*) FROM tblProgramFilterStates_App WHERE ProgramFilterID = PF.ProgramFilterID) ApplicantStateFilterCount,
  (SELECT COUNT(*) FROM tblProgramFilterCounties_App WHERE ProgramFilterID = PF.ProgramFilterID) ApplicantCountyFilterCount,
  (SELECT COUNT(*) FROM tblProgramFilterStates WHERE ProgramFilterID = PF.ProgramFilterID) DealerStateFilterCount,
  (SELECT COUNT(*) FROM tblProgramFilterCounties WHERE ProgramFilterID = PF.ProgramFilterID) DealerCountyFilterCount,
  (SELECT COUNT(*) FROM tblProgramFilterDealers WHERE ProgramFilterID = PF.ProgramFilterID) DealerFilterCount,
  (SELECT COUNT(*) FROM tblProgramFilterDealersExclude WHERE ProgramFilterID = PF.ProgramFilterID) DealerExcludeFilterCount,
	(SELECT COUNT(*) FROM tblProgramFilterStipulations WHERE ProgramFilterID = PF.ProgramFilterID) StipulationsCount,
	ISNULL(PF.UpdateDateTime, P.UpdateDateTime) LastUpdate

FROM
  tblPrograms P WITH (NOLOCK)
  INNER JOIN tblLenders L WITH (NOLOCK) ON  P.LenderID = L.LenderID
  LEFT JOIN tblProgramFilter PF WITH (NOLOCK) ON P.ProgramID = PF.ProgramID
  

WHERE
	--P.ProgramID *= PF.ProgramID
  --AND 
