/****** Object:  View dbo.viewFilterGen_Programs_Inner    Script Date: 7/31/2024 12:57:24 PM ******/

CREATE VIEW viewFilterGen_Programs_Inner AS
--CREATE VIEW viewFilterGen_Programs_Inner_NEW_2014_04_11 AS
	SELECT TOP 100 PERCENT
		tblPrograms.LenderID,
		tblPrograms.ProgramID,
		tblPrograms.ProgramName,
		tblPrograms.CreditTier,
		tblPrograms.Active,
		tblPrograms.Automated,
		tblPrograms.Underwriting,
		tblPrograms.AutoSelect,
		tblPrograms.NoCredit,
		Submit = CASE
			WHEN Automated=0 AND Underwriting=0 THEN
				1
			ELSE
				0
		END,
		(SELECT COUNT(*)			FROM tblProgramFilter						WITH (NOLOCK) WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID) ProgramFilterCount,
		(SELECT COUNT(*)			FROM tblValues 							V	WITH (NOLOCK) WHERE Len(Value) > 0 AND ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) ParameterValueCount,
		(SELECT COUNT(*)			FROM tblProgramFilterStates_App				WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) ApplicantStateFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterCounties_App 			WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) ApplicantCountyFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterStates 				WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) DealerStateFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterCounties 				WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) DealerCountyFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterDealers 				WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) DealerFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterDealersExclude 		WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) DealerExcludeFilterCount,
		(SELECT MAX(UpdateDateTime) FROM tblProgramFilter 						WITH (NOLOCK) WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID) LastUpdate,
		(SELECT MAX(UpdateDateTime) FROM tblLendersBranches 					WITH (NOLOCK) WHERE tblLendersBranches.LenderID = tblPrograms.LenderID) LastBranchUpdate,
		(SELECT UpdateDateTime		FROM tblLenders 							WITH (NOLOCK) WHERE tblLenders.LenderID=tblPrograms.LenderID) LastLenderUpdate
	
	FROM
		tblPrograms WITH (NOLOCK)
	
	--ORDER BY		tblPrograms.LenderID, tblPrograms.ProgramID

	UNION ALL

	SELECT TOP 100 PERCENT
		tblPrograms.LenderID,
		tblPrograms.ProgramID,
		tblPrograms.ProgramName,
		tblPrograms.CreditTier,
		tblPrograms.Active,
		tblPrograms.Automated,
		tblPrograms.Underwriting,
		tblPrograms.AutoSelect,
		--tblPrograms.NoCredit,
		NoCredit = CONVERT(BIT, 0),
		Submit = CASE
			WHEN Automated=0 AND Underwriting=0 THEN
				1
			ELSE
				0
		END,
		(SELECT COUNT(*)			FROM tblProgramFilter						WITH (NOLOCK) WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID) ProgramFilterCount,
		(SELECT COUNT(*)			FROM tblValues 							V	WITH (NOLOCK) WHERE Len(Value) > 0 AND ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) ParameterValueCount,
		(SELECT COUNT(*)			FROM tblProgramFilterStates_App				WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) ApplicantStateFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterCounties_App 			WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) ApplicantCountyFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterStates 				WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) DealerStateFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterCounties 				WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) DealerCountyFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterDealers 				WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) DealerFilterCount,
		(SELECT COUNT(*)			FROM tblProgramFilterDealersExclude 		WITH (NOLOCK) WHERE ProgramFilterID IN (SELECT ProgramFilterID FROM tblProgramFilter 			WITH (NOLOCK)		WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID)) DealerExcludeFilterCount,
		(SELECT MAX(UpdateDateTime) FROM tblProgramFilter 						WITH (NOLOCK) WHERE tblProgramFilter.ProgramID = tblPrograms.ProgramID) LastUpdate,
		(SELECT MAX(UpdateDateTime) FROM tblLendersBranches 					WITH (NOLOCK) WHERE tblLendersBranches.LenderID = tblPrograms.LenderID) LastBranchUpdate,
		(SELECT UpdateDateTime		FROM tblLenders 							WITH (NOLOCK) WHERE tblLenders.LenderID=tblPrograms.LenderID) LastLenderUpdate
	
	FROM
		tblPrograms WITH (NOLOCK)

	WHERE
			ISNULL(tblPrograms.Underwriting, 0)	= 0
		AND ISNULL(tblPrograms.Automated,	 0) = 0
