/****** Object:  View dbo.viewFilterGen_Values_2013_09_05    Script Date: 7/31/2024 12:57:24 PM ******/

--SELECT TOP 5 * FROM tblParameters WITH (NOLOCK);

CREATE VIEW viewFilterGen_Values_2013_09_05 AS
	SELECT TOP 100 PERCENT
		LenderID				= Lender.LenderID,
		ProgramID				= Program.ProgramID,
		ProgramFilterID			= RuleSet.ProgramFilterID,
		FilterID				= RuleInfo.FilterID,
		ShortName				= RuleInfo.ShortName,
		Category				= Category.CategoryName,
		LongName				= RuleInfo.LongName,
		ParameterDescription	= Parameter.LongName,
		ParameterName			= Parameter.ShortName,
		DataTypeName			= DataType.ShortName,
		Value					= CASE WHEN RuleInfo.FilterID = 52 AND ISNULL(Value.Value, '') = '0' THEN '9999' ELSE Value.Value END,
		Operator				= Value.Operator,
		Units					= Parameter.Units,
		RequiresCredit			= IsNull(RuleInfo.RequiresCredit, 1)
	FROM
				tblLenders				Lender		WITH (NOLOCK) 
		JOIN	tblPrograms				Program		WITH (NOLOCK) ON	Program.LenderID		= Lender.LenderID				AND	Program.Active = 1
		JOIN	tblProgramFilter		RuleSet		WITH (NOLOCK) ON	RuleSet.ProgramID		= Program.ProgramID
		JOIN	tblValues				Value		WITH (NOLOCK) ON	Value.ProgramFilterID	= RuleSet.ProgramFilterID		AND	NULLIF(Value.Value, '') IS NOT NULL
		JOIN	tblParameters			Parameter	WITH (NOLOCK) ON	Parameter.ParameterID	= Value.ParameterID
		JOIN	tblFilters				RuleInfo	WITH (NOLOCK) ON	RuleInfo.FilterID		= Parameter.FilterID		
		JOIN	tblCategories			Category	WITH (NOLOCK) ON	Category.CategoryID		= RuleInfo.CategoryID
		JOIN	tblDataTypes			DataType	WITH (NOLOCK) ON	DataType.DataTypeID		= Parameter.DataTypeID
	ORDER BY
		Lender.LenderName,
		Lender.LenderID,
		Program.ProgramID,
		RuleSet.ProgramFilterID,
		Category.SortValue,
		RuleInfo.SortValue,
		RuleInfo.LongName,
		RuleInfo.FilterID,
		Parameter.SortValue,
		Parameter.LongName,
		Value.ParameterID

--WHERE		Len(ISNULL(Value.Value, '')) > 0




