RETURN;
*/
--SELECT TOP 2 * FROM [tblPrograms] WITH (NOLOCK);
--SELECT COUNT(*) FROM [tblPrograms] WITH (NOLOCK) WHERE [NoCredit] = 1;

CREATE VIEW [viewFilterProgramVersions] AS
	SELECT
		[P].*,
		[Version] = DATEDIFF(ss, '2010-01-01', [P].[Newest]),
		[Key] = 'Filter.XML.Gen/Lender/' + CONVERT(VARCHAR(8), [P].[LenderID]) +
			CASE WHEN [P].[Submit] = 1 THEN '/Submit' ELSE '' END +
			CASE WHEN [P].[Bureau] = 1 THEN '/Bureau' ELSE '/NoBureau' END +
			''
	FROM
		(
	SELECT
		[P].*,
		[Newest] = CASE
			WHEN [P].[ProgramUpdated]			>= [P].[ProgramFiltersUpdated]	AND [P].[ProgramUpdated]		>= [P].[ValuesUpdated]			AND [P].[ProgramUpdated]		>= [P].[LenderStatusUpdated] THEN	[P].[ProgramUpdated]
			WHEN [P].[ProgramFiltersUpdated]	>= [P].[ProgramUpdated]			AND [P].[ProgramFiltersUpdated]	>= [P].[ValuesUpdated]			AND [P].[ProgramFiltersUpdated]	>= [P].[LenderStatusUpdated] THEN	[P].[ProgramFiltersUpdated]
			WHEN [P].[ValuesUpdated]			>= [P].[ProgramUpdated]			AND [P].[ValuesUpdated]			>= [P].[ProgramFiltersUpdated]	AND [P].[ValuesUpdated]			>= [P].[LenderStatusUpdated] THEN	[P].[ValuesUpdated]
			WHEN [P].[LenderStatusUpdated]		>= [P].[ProgramFiltersUpdated]	AND [P].[LenderStatusUpdated]	>= [P].[ValuesUpdated]			AND [P].[LenderStatusUpdated]	>= [P].[LenderStatusUpdated] THEN	[P].[LenderStatusUpdated]
		END
	FROM
		(
		SELECT
			[Lender].[LenderID],
			[Lender]				= UPPER(([Lender].[LenderName])),
			[LenderStatus]			= MIN([Lender].[LenderStatus]),
			[CompanyCode]			= MIN([Lender].[LoginPrefix]),
			/*[ProgramID]			= [Program].[ProgramID],
			[Program]				= UPPER(([Program].[ProgramName])),*/
			[Bureau]				= CONVERT(BIT, CASE WHEN [Program].[NoCredit] = 1 THEN 0 ELSE 1 END),
			[Submit]				= CONVERT(BIT, CASE WHEN [Program].[Underwriting] = 0 AND [Program].[Automated] = 0 AND [Program].[AutoDecline] = 0 THEN 1 ELSE 0 END),
			[Underwriting]			= [Program].[Underwriting],
			[Automated]				= CONVERT(BIT, CASE WHEN [Program].[Automated] = 0 AND [Program].[AutoDecline] = 0 THEN 0 ELSE 1 END),
			[Automation]			= CASE WHEN [Program].[Automated] = 1 AND [Program].[AutoDecline] = 1 THEN 'BOTH' WHEN [Program].[Automated] = 1 THEN 'OFFER' WHEN [Program].[AutoDecline] = 1 THEN 'DECLINE' ELSE '' END,
			[Programs]				= COUNT(DISTINCT [Program].[ProgramID]),
			[ProgramFilters]		= COUNT(DISTINCT [ProgramFilter].[ProgramFilterID]),
			[Values]				= COUNT(DISTINCT [Values].[ValueID]),
			[ProgramUpdated]		= MAX([Program].[UpdateDateTime]),
			[ProgramFiltersUpdated]	= MAX([ProgramFilter].[UpdateDateTime]),
			[ValuesUpdated]			= MAX([Values].[UpdateDateTime]),
			[LenderStatusUpdated]	= MAX([Lender].[LenderStatusUpdateDateTime])
		FROM
					[tblLenders]			[Lender]			WITH (NOLOCK)
			JOIN	[tblPrograms]			[Program]			WITH (NOLOCK) ON [Program].[LenderID]			= [Lender].[LenderID]
			JOIN	[tblProgramFilter]		[ProgramFilter]		WITH (NOLOCK) ON [ProgramFilter].[ProgramID]	= [Program].[ProgramID]
			JOIN	[tblValues]				[Values]			WITH (NOLOCK) ON [Values].[ProgramFilterID]		= [ProgramFilter].[ProgramFilterID]
		WHERE
			[Program].[Active] = 1 AND [Lender].[LenderStatus] NOT IN ('INACTIVE', 'FAX')
		GROUP BY
			[Lender].[LenderID], [Lender].[LenderName], 
			--[Program].[ProgramID], [Program].[ProgramName],
			[Program].[NoCredit],
			[Program].[Underwriting],
			[Program].[Automated],
			[Program].[AutoDecline]
		) [P]
	) [P]
--	ORDER BY [P].[LenderID]


