/****** Object:  View dbo.viewFilter_CreditScoreRule_Inner    Script Date: 7/31/2024 12:57:24 PM ******/

CREATE VIEW viewFilter_CreditScoreRule_Inner AS
SELECT TOP 100 PERCENT
		PROGRAM.ProgramID,
		VALUE.ProgramFilterID,
		Score	=	CONVERT(INT, VALUE.Value),
		Who		=	CONVERT(INT, CASE PARAMETER.ShortName
									WHEN 'SCORE'	THEN 1
									WHEN 'COBO'		THEN 2
						END)		
	FROM 
				tblFilters			FILTER			WITH (NOLOCK)	
		JOIN	tblParameters 		PARAMETER		WITH (NOLOCK) ON		PARAMETER.FilterID				=	FILTER.FilterID		
																		AND	PARAMETER.ShortName					IN ('SCORE', 'COBO')
																		AND	PARAMETER.Units					=	110
		JOIN	tblValues			VALUE			WITH (NOLOCK) ON		VALUE.ParameterID				=	PARAMETER.ParameterID
																		AND	ISNUMERIC(VALUE.Value)			=	1
																		AND CONVERT(INT, VALUE.Value)		>=	0
		JOIN	tblProgramFilter	PROGRAM_FILTER	WITH (NOLOCK) ON		PROGRAM_FILTER.ProgramFilterID	=	VALUE.ProgramFilterID
		JOIN	tblPrograms			PROGRAM			WITH (NOLOCK) ON		PROGRAM.ProgramID				=	PROGRAM_FILTER.ProgramID
	WHERE
		FILTER.ShortName		= 'CREDIT_SCORE'
	ORDER BY
		PROGRAM.ProgramID, 
		PROGRAM_FILTER.ProgramFilterID, 
		Who




