/****** Object:  View dbo.viewPartnerDecisionDisposition    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW viewPartnerDecisionDisposition AS
	SELECT
		[Bid].[LoanAppID],
		[Bid].[LoanApp_BidID],
		[Branch].[LenderID],
		[Partner].[PartnerToolID],
		[PDR].[TryCount],
		[PDR].[ErrorCount],
		[PDR].[SuccessCount],
		[PDR].[TS_LastError],
		[PDR].[TS_Success],
		[PDR].[TS_FirstAttempt],
		[PDR].[TS_LastAttempt],
		[PDA].[ErrorCode],
		[PDA].[ErrorText],
		[PDA].[OperationCode],
		[PDA].[OperationText],
		[Status] = CASE 
			WHEN [PDR].[TS_Success]					IS NOT NULL									THEN 'OK' 
			WHEN LEFT([PDA].[ErrorText], 22)		= 'XML validation failed:'					THEN 'Validation Failure' 
			WHEN [PDA].[ResponseStatus]				NOT IN (200)								THEN 'Non 200 Response' 
			WHEN [PDA].[ResponseStatusText]			NOT IN ('OK')								THEN 'Bad ResponseText: "' + [PDA].[ResponseStatusText] + '"' 
			WHEN [PDA].[ContentLength_Sent]			<> DATALENGTH([PDA].[Content_Sent])			THEN 'ContentLength_Sent does not match actual length' 
			WHEN [PDA].[ContentLength_Response]		<> DATALENGTH([PDA].[Content_Response])		THEN 'ContentLength_Response does not match actual length' 
																								ELSE 'OK' END
	FROM
				[tblLoanApp_Bids]					[Bid]			WITH (NOLOCK)
		JOIN	[tblLendersBranches]				[Branch]		WITH (NOLOCK) ON [Branch].[LendersBranchID]			= [Bid].[LendersBranchID]
		JOIN	[tblPartnerDecision_Receipt]		[PDR]			WITH (NOLOCK) ON [PDR].[LoanApp_BidID]				= [Bid].[LoanApp_BidID]
		JOIN	[tblPartnerTools]					[Partner]		WITH (NOLOCK) ON [Partner].[PartnerToolID]			= [PDR].[PartnerToolID]	
		JOIN	[tblPartnerDecision_Attempt]		[PDA]			WITH (NOLOCK) ON [PDA].[LoanApp_BidID]				= [Bid].[LoanApp_BidID]				AND
																					 [PDA].[PartnerToolID]				= [Partner].[PartnerToolID]			AND
																					 ISNULL(ISNULL([PDR].[PartnerToolsTriggerID], [PDA].[PartnerToolsTriggerid]), 0) = ISNULL(ISNULL([PDA].[PartnerToolsTriggerID], [PDR].[PartnerToolsTriggerid]), 0)
	WHERE
			[PDR].[PartnerToolID]		= 52
		AND	[PDR].[CreateDateTime]		> DATEADD(d, -7, GETDATE())

		--AND	[PDR].[TS_Success]				IS NOT NULL
		--AND [PDR].[TS_LastError]			IS NOT NULL
		AND	[PDR].[TryCount]				>= 1
		--AND	[PDR].[ErrorCount]				<= 5
		--AND [PDR].[SuccessCount]			 = 0
		--AND [PDA].[Success]					 = 0
		--AND [PDA].[ContentLength_Response]	 > 10
		--AND [PDA].[ResponseStatus]		<> 200
		AND [PDA].[Try]						 = (SELECT MAX([Try]) FROM [tblPartnerDecision_Attempt] [PDA2] WITH (NOLOCK) WHERE [PDA2].[LoanApp_BidID] = [PDR].[LoanApp_BidID] AND [PDA2].[PartnerToolID] = [PDR].[PartnerToolID])

		--AND (LEFT([PDA].[ErrorText], 22) <> 'XML validation failed:')

	
/*
	ORDER BY
		[PDA].[LoanApp_BidID],
		[PDA].[Try] DESC
*/

