/****** Object:  View dbo.viewProgramFilterCredit    Script Date: 7/31/2024 12:57:24 PM ******/


CREATE VIEW viewProgramFilterCredit

AS

SELECT
P.LenderID,
PF.ProgramFilterID,
P.ProgramName,
P.CreditTier,
P.CreateDateTime 	Program_CreateDateTime,
P.UpdateDateTime	Program_UpdateDateTime,

(SELECT COUNT(*) FROM tblValues V WHERE V.ProgramFilterID = PF.ProgramFilterID AND Len(V.Value)>0 AND V.ParameterID IN (SELECT ParameterID FROM tblParameters PAR WHERE Par.FilterID IN (SELECT FilterID FROM tblFilters WHERE RequiresCredit=0))) NoCredit,
(SELECT COUNT(*) FROM tblValues V WHERE V.ProgramFilterID = PF.ProgramFilterID AND Len(V.Value)>0 AND V.ParameterID IN (SELECT ParameterID FROM tblParameters PAR WHERE Par.FilterID IN (SELECT FilterID FROM tblFilters WHERE RequiresCredit=1))) YesCredit,
(SELECT MAX(CREATEDATETIME) FROM tblProgramFilter WHERE tblProgramFilter.ProgramID = P.ProgramID) PF_CreateDateTime,
(SELECT MAX(UPDATEDATETIME) FROM tblProgramFilter WHERE tblProgramFilter.ProgramID = P.ProgramID) PF_UpdateDateTime

FROM
	tblPrograms P,
	tblProgramFilter PF

WHERE
	P.ProgramID = PF.ProgramID





