/****** Object:  View dbo.viewB2B_PendingToSend    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW [viewB2B_PendingToSend] AS
SELECT
--TOP 100
	[Priority] = CASE
		WHEN	([Bid].[CreateDateTime]						< DATEADD(d, -90, GETDATE())																														) THEN -33	/* 'Bid Create too Old' */
		WHEN	([DPS].[Decisioned]								=  1	AND [Bid].[Offer_Date]							<  DATEADD(d, -30, GETDATE())									)	THEN -32	/* 'Offer too Old' */
		WHEN	([DPS].[Decisioned]								=  0	AND [Bid].[UpdateDateTime]					<  DATEADD(d, -30, GETDATE())									) THEN -31	/* 'Bid Update too Old' */
		WHEN	([DPS].[SentLatest]								=  1																																										)	THEN -30	/* 'Already Sent Latest' */
		WHEN	([DPS].[LastAttemptAgo]						< 15																																										)	THEN -29	/* 'Last Attempt Too Soon' */
		WHEN	([DPS].[Errors]										> 10																																										)	THEN -28	/* 'Too Many Errors' */
		WHEN	([DPS].[Decisioned]								=  1	AND	[DPS].[SendDecisions]						=  0																					)	THEN -27	/* 'Not Sending Decisions' */
		WHEN	([DPS].[Decisioned]								=  0	AND	[DPS].[SendNonDecisions]				=  0																					)	THEN -26	/* 'Not Sending Non-Decisions' */
		WHEN	([DPS].[Decisioned]								=  1	AND	[DPS].[IsLatestDecision]				=  0																					)	THEN -25	/* 'Not Latest Decision' */
		WHEN	([DPS].[Decisioned]								=  0	AND	[DPS].[IsLatestBid]							=  0																					)	THEN -24	/* 'Not Latest Bid' */
		WHEN	([DPS].[OnlySendUserInitiated]		=  1	AND	[DPS].[CreatedOrUpdatedByUser]	=  0																					)	THEN -23	/* 'Not User Initiated' */
		WHEN	([DPS].[Errors]										>  0	AND	[DPS].[ResendOnError]						=  0																					)	THEN -22	/* 'Not Resending on Error' */
		WHEN	([DPS].[Sent]											=  1	AND	[DPS].[Decisioned]							=  1	AND	[DPS].[SendNewDecisions]			=  0	)	THEN -21	/* 'Not Sending Updated Decisions' */
		WHEN	([DPS].[Sent]											=  1	AND	[DPS].[Decisioned]							=  0	AND	[DPS].[SendNewNonDecisions]		=  0	)	THEN -20	/* 'Not Sending Updated Non-Decisions' */
		ELSE 100 - [DPS].[Errors] * 10 - [DPS].[Tries] + [DPS].[Successes] END,

	[PriorityReason] = CASE
		WHEN	([Bid].[CreateDateTime]						< DATEADD(d, -90, GETDATE())																														) THEN /* -33	*/	'Bid Create too Old'
		WHEN	([DPS].[Decisioned]								=  1	AND [Bid].[Offer_Date]							<  DATEADD(d, -30, GETDATE())									)	THEN /* -32	*/	'Offer too Old'
		WHEN	([DPS].[Decisioned]								=  0	AND [Bid].[UpdateDateTime]					<  DATEADD(d, -30, GETDATE())									) THEN /* -31	*/	'Bid Update too Old'
		WHEN	([DPS].[SentLatest]								=  1																																										)	THEN /* -30	*/	'Already Sent Latest'
		WHEN	([DPS].[LastAttemptAgo]						< 15																																										)	THEN /* -29	*/	'Last Attempt Too Soon'
		WHEN	([DPS].[Errors]										> 10																																										)	THEN /* -28	*/	'Too Many Errors'
		WHEN	([DPS].[Decisioned]								=  1	AND	[DPS].[SendDecisions]						=  0																					)	THEN /* -27	*/	'Not Sending Decisions'
		WHEN	([DPS].[Decisioned]								=  0	AND	[DPS].[SendNonDecisions]				=  0																					)	THEN /* -26	*/	'Not Sending Non-Decisions'
		WHEN	([DPS].[Decisioned]								=  1	AND	[DPS].[IsLatestDecision]				=  0																					)	THEN /* -25	*/	'Not Latest Decision'
		WHEN	([DPS].[Decisioned]								=  0	AND	[DPS].[IsLatestBid]							=  0																					)	THEN /* -24	*/	'Not Latest Bid'
		WHEN	([DPS].[OnlySendUserInitiated]		=  1	AND	[DPS].[CreatedOrUpdatedByUser]	=  0																					)	THEN /* -23	*/	'Not User Initiated'
		WHEN	([DPS].[Errors]										>  0	AND	[DPS].[ResendOnError]						=  0																					)	THEN /* -22	*/	'Not Resending on Error'
		WHEN	([DPS].[Sent]											=  1	AND	[DPS].[Decisioned]							=  1	AND	[DPS].[SendNewDecisions]			=  0	)	THEN /* -21	*/	'Not Sending Updated Decisions'
		WHEN	([DPS].[Sent]											=  1	AND	[DPS].[Decisioned]							=  0	AND	[DPS].[SendNewNonDecisions]		=  0	)	THEN /* -20	*/	'Not Sending Updated Non-Decisions'
		ELSE '' END,
		[DPS].*
FROM
								[viewB2B_DecisionsPendingToSend_Inner]	[DPS]								WITH (NOLOCK)
					JOIN	[tblLoanApp_Bids]												[Bid]								WITH (NOLOCK) ON [Bid].[LoanApp_BidID]	= [DPS].[LoanApp_BidID]
					JOIN	[tblLoanApp_Bids]												[Latest_Bid]				WITH (NOLOCK) ON [Latest_Bid].[LoanApp_BidID]	= (SELECT MAX([LoanApp_BidID]) FROM [tblLoanApp_Bids] [Bid_Inner] WITH (NOLOCK) JOIN [tblLendersBranches] [Branch_Inner] WITH (NOLOCK) ON [Branch_Inner].[LendersBranchID] = [Bid_Inner].[LendersBranchID]	AND [Branch_Inner].[LenderID] = [DPS].[LenderID] WHERE [Bid_Inner].[LoanAppID] = [DPS].[LoanAppID]	AND [Bid_Inner].[Canceled_Date] IS NULL)
		LEFT	JOIN	[viewBidsLatestDecision] 								[Latest_Decision]		WITH (NOLOCK) ON [Latest_Decision].[LoanAppID]	= [DPS].[LoanAppID]			AND [Latest_Decision].[LenderID] = [DPS].[LenderID]
WHERE
		ISNULL([Bid].[Offer_Date], [Bid].[UpdateDateTime])	> DATEADD(d, -30, GETDATE()) AND NOT (0 = 1
			OR	([Bid].[CreateDateTime]						< DATEADD(d, -90, GETDATE())																														)	/* -33	'Bid Create too Old' */
			OR	([DPS].[Decisioned]								=  1	AND [Bid].[Offer_Date]							<  DATEADD(d, -30, GETDATE())									)	/* -32	'Offer too Old' */
			OR	([DPS].[Decisioned]								=  0	AND [Bid].[UpdateDateTime]					<  DATEADD(d, -30, GETDATE())									) /* -31	'Bid Update too Old' */
			OR	([DPS].[SentLatest]								=  1																																										)	/* -30	'Already Sent Latest' */
			OR	([DPS].[LastAttemptAgo]						< 15																																										)	/* -29	'Last Attempt Too Soon' */
			OR	([DPS].[Errors]										> 10																																										)	/* -28	'Too Many Errors' */
			OR	([DPS].[Decisioned]								=  1	AND	[DPS].[SendDecisions]						=  0																					)	/* -27	'Not Sending Decisions' */
			OR	([DPS].[Decisioned]								=  0	AND	[DPS].[SendNonDecisions]				=  0																					)	/* -26	'Not Sending Non-Decisions' */
			OR	([DPS].[Decisioned]								=  1	AND	[DPS].[IsLatestDecision]				=  0																					)	/* -25	'Not Latest Decision' */
			OR	([DPS].[Decisioned]								=  0	AND	[DPS].[IsLatestBid]							=  0																					)	/* -24	'Not Latest Bid' */
			OR	([DPS].[OnlySendUserInitiated]		=  1	AND	[DPS].[CreatedOrUpdatedByUser]	=  0																					)	/* -23	'Not User Initiated' */
			OR	([DPS].[Errors]										>  0	AND	[DPS].[ResendOnError]						=  0																					)	/* -22	'Not Resending on Error' */
			OR	([DPS].[Sent]											=  1	AND	[DPS].[Decisioned]							=  1	AND	[DPS].[SendNewDecisions]			=  0	)	/* -21	'Not Sending Updated Decisions' */
			OR	([DPS].[Sent]											=  1	AND	[DPS].[Decisioned]							=  0	AND	[DPS].[SendNewNonDecisions]		=  0	)	/* -20	'Not Sending Updated Non-Decisions' */
		)
/*
GROUP BY
	[DPS].[PartnerToolID],
	[DPS].[LoanAppID],
	[DPS].[LoanApp_BidID],
	[Bid].[CreateDateTime],
	[Bid].[UpdateDateTime],
	[Bid].[OFFER_DATE],
	[DPS].[Decisioned],
	[DPS].[SentLatest],
	[DPS].[LastAttemptAgo],
	[DPS].[Errors],
	[DPS].[SendDecisions],
	[DPS].[SendNonDecisions],
	[DPS].[IsLatestDecision],
	[DPS].[IsLatestBid],
	[DPS].[OnlySendUserInitiated],
	[DPS].[CreatedOrUpdatedByUser],
	[DPS].[ResendOnError],
	[DPS].[Sent],
	[DPS].[SendNewDecisions],
	[DPS].[SendNewNonDecisions],
	[Bid].[CreateDateTime],
	[DPS].[LenderID],
	[DPS].[BidStatus],
