/****** Object:  View dbo.viewFilterGen_Values_New    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW viewFilterGen_Values_New AS
	SELECT TOP 100 PERCENT
		ProgramFilterID			= ProgramFilter.ProgramFilterID,
		FilterID				= Filter.FilterID,
		ShortName				= Filter.ShortName,
		LongName				= Filter.LongName,
		ParameterDescription	= ParameterValue.ParameterDescription,
		ParameterName			= ParameterValue.ParameterName,
		DataTypeName			= ParameterValue.DataTypeName,
		Value					= CASE	WHEN Filter.FilterID = 52 AND ISNULL(ParameterValue.Value, '') = '0' THEN '9999' ELSE ParameterValue.Value	END,
		Operator				= ParameterValue.Operator,
		Units					= ParameterValue.Units,
		RequiresCredit			= IsNull(Filter.RequiresCredit, 1),
		CategoryID				= Category.CategoryID,
		CategoryName			= Category.CategoryName
	FROM
							tblProgramFilter		ProgramFilter 		WITH (NOLOCK)
			JOIN			viewParameterValues		ParameterValue		WITH (NOLOCK) ON ProgramFilter.ProgramFilterID			= ParameterValue.ProgramFilterID
			JOIN			tblFilters				Filter				WITH (NOLOCK) ON ParameterValue.FilterID				= Filter.FilterID
			JOIN			tblPrograms				Program				WITH (NOLOCK) ON Program.ProgramID						= ProgramFilter.ProgramID
			JOIN			tblLenders				Lender				WITH (NOLOCK) ON Program.LenderID						= Lender.LenderID
			LEFT OUTER JOIN tblCategories			Category			WITH (NOLOCK) ON Filter.CategoryID						= Category.CategoryID
	WHERE
		Len(ISNULL(Value, '')) > 0
	ORDER BY
		Program.LenderID,
		Program.ProgramID,
		ProgramFilter.ProgramFilterID,
		ISNULL(CATEGORY.SortValue, CATEGORY.CategoryName),
		ISNULL(FILTER.SortValue, 'ZZZZZZZZZ'),
		Filter.FilterID,
		ISNULL(PARAMETERVALUE.ParameterName, 'ZZZZZZZZZ')
	
	--ORDER BY	ProgramFilter.ProgramFilterID,	Filter.FilterID,	ParameterValue.ParameterID







