/****** Object:  View dbo.viewFilterGen_Values_New_BACKUP_2017_07_06    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW viewFilterGen_Values_New_BACKUP_2017_07_06 AS
	SELECT TOP 100 PERCENT
	    [ProgramFilter].[ProgramFilterID],
	    [Filter].[FilterID],
	    [Filter].[ShortName],
	    [Filter].[LongName],
	    [ParameterValue].[ParameterDescription],
	    [ParameterValue].[ParameterName],
	    [ParameterValue].[DataTypeName],
	    Value = CASE
	      WHEN Filter.FilterID = 52 AND ISNULL(ParameterValue.Value, '') = '0' THEN '9999'
	      ELSE ParameterValue.Value
	    END,
	    [ParameterValue].[Operator],
			[ParameterValue].[Units],
			IsNull([Filter].[RequiresCredit], 1) RequiresCredit,
	    Category.CategoryID,
	    Category.CategoryName
	
	FROM
	    [tblProgramFilter] [ProgramFilter] WITH (NOLOCK)
	      INNER JOIN      viewParameterValues   [ParameterValue]    WITH (NOLOCK) ON  [ProgramFilter].[ProgramFilterID]   = [ParameterValue].[ProgramFilterID]
	      INNER JOIN      tblFilters            [Filter]            WITH (NOLOCK) ON  [ParameterValue].[FilterID]         = [Filter].[FilterID]
	      INNER JOIN      tblPrograms           [Program]           WITH (NOLOCK) ON  Program.ProgramID = ProgramFilter.ProgramID
	      INNER JOIN      tblLenders            [Lender]            WITH (NOLOCK) ON  Program.LenderID = Lender.LenderID
	      LEFT OUTER JOIN tblCategories         [Category]          WITH (NOLOCK) ON  Filter.CategoryID = Category.CategoryID
	
	WHERE
		Len(ISNULL(Value, '')) > 0
	ORDER BY
		[ProgramFilter].[ProgramFilterID],
		ISNULL(CATEGORY.SortValue, CATEGORY.CategoryName),
		ISNULL(FILTER.SortValue, 'ZZZZZZZZZ'),
		ISNULL(PARAMETERVALUE.ParameterName, 'ZZZZZZZZZ')
	
	--ORDER BY    [ProgramFilter].[ProgramFilterID],    [Filter].[FilterID],    [ParameterValue].[ParameterID]







