/****** Object:  View dbo.viewB2B_PendingToSendBySession    Script Date: 7/31/2024 12:57:24 PM ******/
CREATE VIEW [viewB2B_PendingToSendBySession] AS
SELECT	TOP 100
	-- [Bids].[LendersBranchID],
	-- [Dealer].[DealerID],
	[SessionID]								= [Session].[SessionID],
	[Locked]									= [Bids].[Locked],
	[PartnerToolID]						= [Bids].[PartnerToolID],
	[LoanAppID]								= [Bids].[LoanAppID],
	[LenderID]								= [Bids].[LenderID],
	[LoanApp_BidID]						= [Bids].[LoanApp_BidID],
	[Priority]								= [Bids].[Priority],
	[PriorityReason]					= [Bids].[PriorityReason],
	[BidStatus]								= [Bids].[BidStatus],
	[IsDecision]							= [Bids].[IsDecision],
	[PartnerToolsTriggerID]		= [Bids].[PartnerToolsTriggerID],
	[CreateDateTime]					= [Bids].[CreateDateTime],
	[UpdateDateTime]					= [Bids].[UpdateDateTime],
	[CreateUser]							= [Bids].[CreateUser],
	[UpdateUser]							= [Bids].[UpdateUser],
	[RowVersion]							= [Bids].[RowVersion]
FROM
	-- [tblLoanApp_Bids]						[Bids] 			WITH (NOLOCK)
	-- LEFT	JOIN	[tblDealers]								[Dealer]		WITH (NOLOCK) ON [Dealer].[DealerID]		= [App].[DealerID]
							[viewB2B_PendingToSend]			[Bids]			WITH (NOLOCK)
	LEFT	JOIN	[tblPartnerSender_Session]	[Session] 	WITH (NOLOCK) ON [Session].[Active] = 1 AND [Session].[PartnerToolID] = [Bids].[PartnerToolID] AND ([Session].[LenderID] IS NULL OR [Session].[LenderID] = [Bids].[LenderID])
	--AND ([Session].[LendersBranchID] IS NULL OR [Session].[LendersBranchID] = [Bids].[LendersBranchID]) AND ([Session].[DealerID] IS NULL OR [Dealer].[DealerID] IS NULL OR [Session].[DealerID] = [Dealer].[DealerID])
WHERE
	[Bids].[Priority] >= 0 AND NULLIF([Bids].[LockedBySessionID], [Session].[SessionID]) IS NULL
-- [Bids].[CreateDateTime] > DATEADD(d, -365, GETDATE()) OR [Bids].[Offer_Date] > DATEADD(d, -365, GETDATE()) OR [App].[CreateDateTime] > DATEADD(d, -365, GETDATE()) OR [App].[UpdateDateTime] > DATEADD(d, -365, GETDATE()) OR [Bids].[UpdateDateTime] > DATEADD(d, -365, GETDATE())
ORDER BY
	[Bids].[Priority]					DESC,
	[Bids].[PartnerToolID],
	[Session].[SessionID]			DESC,
	[Bids].[Tries],
	[Bids].[Errors],
	[Bids].[Offer_Date]				DESC


GO

